section("Lockpicks and bypass charges")
local burglar = newPlayer("Burglar", "citizen")
burglar:SetPos(FAR)
local ldoor = ents.Create("func_door")
ldoor.mapid = 601
ldoor:SetPos(FAR + Vector(60, 0, 0))
