function NPCArrestTests()
section("Searching and arresting citizens on the street")
local function forceRandom(v, fn)
    local r = math.random
    math.random = function(a, b) if a == nil then return v end if b == nil then return r(a) end return r(a, b) end
    local okr, err = pcall(fn)
    math.random = r
    if not okr then error(err) end
end
local officer = newPlayer("Officer", "cp")
local cellPt = LC.AddPoint(Vector(-12000, 12000, 0), 90, "cell", 0)
local relPt = LC.AddPoint(Vector(-12500, 12000, 0), 0, "release", 0)
local suspect, sst = LC.Spawners.citizen(Vector(-11000, 11000, 0))
suspect.sim = false
officer:SetPos(suspect:GetPos() + Vector(60, 0, 0))
hook.Run("PlayerUse", officer, suspect)
ok(sst.state == "detained" and has(officer.chat, "R to search them"), "pressing E stops them, and tells a unit what they can do next")
sst.rebel = true
LC.StartSearch(officer, suspect)
forceRandom(0.01, function() _run(3.5) end)
ok(sst.contraband and has(officer.chat, "Found "), "R with the baton searches a citizen, and finds what a sympathizer carries", table.concat(officer.chat, " | "))
local okAgain, whyAgain = LC.StartSearch(officer, suspect)
ok(not okAgain and whyAgain:find("moment ago", 1, true), "not twice in a row")
ok(LC.ArrestNPC(suspect, officer), "right click detains them")
ok(sst.state == "detained", "cuffed for a moment first")
-- (7 November: walked to the cells, not sent there: sv_livingcity_arrest.lua, ArrestOverhaulTests)
ok(LC.NPCCustody[suspect] ~= nil, "cuffed where they stand, to be walked to the cells")
LC.NPCCustodyLead(suspect, officer)
officer:SetPos(cellPt.pos + Vector(150, 0, 0))
suspect:SetPos(cellPt.pos + Vector(100, 0, 0))
_run(2)
local inCell = false
for _, cp in ipairs(LC.PointsOfKind("cell")) do if suspect:GetPos():DistToSqr(cp.pos) < 20 * 20 then inCell = true end end
ok(sst.state == "jailed" and inCell, "walked up to the cells, they're locked in one", sst.state)
LC.ReleaseNPCPrisoner(suspect, sst, CurTime())
local atRelease = false
for _, rp2 in ipairs(LC.PointsOfKind("release")) do if suspect:GetPos():DistToSqr(rp2.pos) < 110 * 110 then atRelease = true end end
ok(sst.state == "idle" and atRelease, "and let out at the release point (beside anyone already standing there)")
local clean, cst2 = LC.Spawners.citizen(Vector(-11000, 11500, 0))
clean.sim = false
cst2.rebel = false
officer:SetPos(clean:GetPos() + Vector(60, 0, 0))
LC.StartSearch(officer, clean)
forceRandom(0.99, function() _run(3.5) end)
ok(has(officer.chat, "Nothing on them"), "most people have nothing on them")
suspect:Remove() clean:Remove()
LC.RemovePoint(cellPt) LC.RemovePoint(relPt)
officer:SetPos(Vector(-30000, 30000, 0))
end
NPCArrestTests()

function PatSearchTests()
section("A unit's search: the pat-down game")
-- (math.random scripted: a number for math.random(), and a queue for math.random(n))
local function scripted(v, ints, fn)
    local r = math.random
    math.random = function(a, b)
        if a == nil then return v end
        if b == nil and #ints > 0 then return math.min(a, table.remove(ints, 1)) end
        if b == nil then return r(a) end
        return r(a, b)
    end
    local okr, err = pcall(fn)
    math.random = r
    if not okr then error(err) end
end
local function lastTo(name, ply)
    for i = #net.sent, 1, -1 do local m = net.sent[i] if m.name == name and m.to == ply then return m end end
end
local function stateOf(ply) local m = lastTo("lc_pat_open", ply) return m and util.JSONToTable(m.data[1] or "") or {} end
local spot = Vector(-21000, 21000, 0)
_setcvar("lc_jobgames", 1)
local unit = newPlayer("PatUnit", "cp")
local guy = newPlayer("PatGuy", "citizen")
guy:StripWeapons()
guy:SetPos(spot)
unit:SetPos(spot + Vector(60, 0, 0))
LC.GiveItem(guy, "lockpick")
LC.GiveItem(guy, "papers_forged")
guy:Give("weapon_crowbar")
local lockName, papersName = LC.PatSearchItemName({ id = "lockpick", n = 1 }), LC.PatSearchItemName({ id = "papers_forged", n = 1 })
ok(LC.StartSearch(unit, guy), "a unit starts a search")
local S = LC.PatSearchOf(guy)
ok(S and not S.live and lastTo("lc_pat_open", unit) and stateOf(unit).role == "unit", "the unit is offered the pat-down window")
ok(not lastTo("lc_pat_open", guy), "the person searched sees nothing until the window is open")
-- the window opens (the client answers "check 0"): lockpick in the jacket, the papers in the legs, the crowbar at the waist
scripted(0.99, { 1, 3, 2 }, function() _netcall("lc_pat_check", unit, 0) end)
ok(S.live and #S.spots[1].items == 1 and #S.spots[2].items == 1 and #S.spots[3].items == 1 and #S.spots[4].items == 0,
    "what a search would find is spread over the four spots")
local uj = lastTo("lc_pat_open", unit).data[1]
ok(not string.find(uj, lockName, 1, true) and not string.find(uj, papersName, 1, true) and not string.find(uj, "crowbar", 1, true),
    "nothing in a spot is sent to the unit before it's checked", uj)
local ts = stateOf(guy)
ok(ts.role == "target" and ts.key == "R" and ts.spots and string.find(ts.spots[1].mine or "", lockName, 1, true) and ts.slip == "wait",
    "the person searched sees their own four spots, and R for later")
ok(LC.HasItem(guy, "lockpick") and guy:HasWeapon("weapon_crowbar"), "nothing is taken before a spot is checked")
_netcall("lc_pat_check", unit, 1)
ok(S.checking == 1 and stateOf(guy).spots[1].state == 1, "checking the jacket: the person searched sees which spot")
ok(not LC.PatSearchCheck(unit, 2), "one spot at a time")
local stranger = newPlayer("PatStranger", "citizen")
ok(not LC.PatSearchCheck(stranger, 2), "only the unit searching can check a spot")
_run(1.4)
ok(not LC.HasItem(guy, "lockpick") and LC.HasItem(guy, "papers_forged") and guy:HasWeapon("weapon_crowbar"),
    "a checked spot gives up only what was in it")
ok(string.find(stateOf(unit).spots[1].text or "", lockName, 1, true), "and the unit's window shows what was there", stateOf(unit).spots[1].text)
-- a slip that works: the papers (legs) into the jacket, already checked
ok(stateOf(guy).slip == "ready", "with a spot checked, the person searched may slip something")
scripted(0.1, { 2, 1 }, function() ok(LC.PatSearchSlip(guy), "R: they try to slip something") end)
ok(S.slipUsed and #S.spots[3].items == 0 and S.spots[1].items[1] and S.spots[1].items[1].id == "papers_forged" and has(guy.chat, "didn't notice"),
    "60% of the time it works: the papers are moved into the checked jacket")
ok(not LC.PatSearchSlip(guy), "once per search")
_netcall("lc_pat_check", unit, 3)
_run(1.4)
ok(LC.HasItem(guy, "papers_forged") and stateOf(unit).spots[3].text == "Nothing.", "the legs are empty now")
local ev0 = LC.EvidenceTotal()
unit.chat = {}
_netcall("lc_pat_close", unit)
ok(LC.PatSearchOf(guy) == nil and guy.lcBeingSearched == nil and lastTo("lc_pat_close", unit) and lastTo("lc_pat_close", guy), "Done ends it, for both")
ok(guy:HasWeapon("weapon_crowbar") and LC.HasItem(guy, "papers_forged"), "a spot never checked keeps what's in it")
ok(has(unit.chat, "was carrying") and has(guy.chat, "Confiscated: " .. lockName) and LC.PlayerIsWanted(guy),
    "what was found is confiscated as a search always has: the messages, wanted")
ok(LC.EvidenceTotal() == ev0 + 1, "and it goes into the evidence stock", LC.EvidenceTotal() .. " vs " .. ev0)
LC.ClearWanted(guy)
LC.CalmCops(guy)
_run(3.5)
ok(LC.HasItem(guy, "papers_forged"), "the old three-second search doesn't run as well")

-- a slip that fails, then walking off
local guy2 = newPlayer("PatGuy2", "citizen")
guy2:StripWeapons()
guy2:SetPos(spot + Vector(0, 300, 0))
unit:SetPos(guy2:GetPos() + Vector(60, 0, 0))
LC.GiveItem(guy2, "lockpick")
ok(LC.StartSearch(unit, guy2), "a second search")
local S2 = LC.PatSearchOf(guy2)
scripted(0.9, { 2 }, function() _netcall("lc_pat_check", unit, 0) end)
_netcall("lc_pat_check", unit, 1)
_run(1.4)
ok(stateOf(unit).spots[1].text == "Nothing.", "an empty spot says so")
unit.chat = {}
scripted(0.9, { 1 }, function() LC.PatSearchSlip(guy2) end)
ok(not LC.HasItem(guy2, "lockpick") and string.find(stateOf(unit).flash or "", "They tried to move something: " .. lockName, 1, true)
    and has(unit.chat, "tried to move something"), "a slip that fails: the unit's window flashes, and the thing is found there and then")
guy2:SetPos(guy2:GetPos() + Vector(2000, 0, 0))
_run(0.5)
ok(S2.ended and LC.PatSearchOf(guy2) == nil and LC.PlayerIsWanted(guy2) and has(unit.chat, "walked away"), "walking off during the pat-down is evading a search")
ok(has(guy2.chat, "Confiscated: " .. lockName), "and what was already found is still confiscated")
LC.ClearWanted(guy2)
LC.CalmCops(guy2)

-- nothing on them; the unit walks off
local guy3 = newPlayer("PatGuy3", "citizen")
guy3:StripWeapons()
guy3:SetPos(spot + Vector(0, 600, 0))
unit:SetPos(guy3:GetPos() + Vector(60, 0, 0))
LC.StartSearch(unit, guy3)
local S3 = LC.PatSearchOf(guy3)
_netcall("lc_pat_check", unit, 0)
for i = 1, 4 do _netcall("lc_pat_check", unit, i) _run(1.3) end
local all = true
for i = 1, 4 do if (stateOf(unit).spots or {})[i] == nil or stateOf(unit).spots[i].text ~= "Nothing." then all = false end end
ok(all, "someone carrying nothing: every spot says Nothing.")
unit:SetPos(unit:GetPos() + Vector(0, 2000, 0))
_run(0.5)
ok(S3 and S3.ended and not LC.PlayerIsWanted(guy3) and has(guy3.chat, "Nothing found"), "the unit walking off ends it, and the person isn't evading")

-- an NPC citizen: the same window, the old odds, put in one spot
local npc, nst = LC.Spawners.citizen(spot + Vector(0, 900, 0))
npc.sim = false
nst.rebel = true
unit:SetPos(npc:GetPos() + Vector(60, 0, 0))
unit.chat = {}
ok(LC.StartSearch(unit, npc), "a unit searches an NPC citizen")
local SN = LC.PatSearchOf(npc)
scripted(0.01, { 1, 2 }, function() _netcall("lc_pat_check", unit, 0) end)
ok(SN and SN.live and #SN.spots[2].items == 1, "what they carry goes in one spot")
_netcall("lc_pat_check", unit, 1) _run(1.3)
ok(not nst.contraband and not has(unit.chat, "Found "), "not in the jacket")
_netcall("lc_pat_check", unit, 2) _run(1.3)
ok(nst.contraband == "a Resistance pamphlet" and has(unit.chat, "Found a Resistance pamphlet"), "found at the waist, as the old search found things")
_netcall("lc_pat_close", unit)
ok(not has(unit.chat, "Nothing on them") and nst.state == "detained", "and they stay put for the unit")
local npc2, nst2 = LC.Spawners.citizen(spot + Vector(0, 1200, 0))
npc2.sim = false
nst2.rebel = false
unit:SetPos(npc2:GetPos() + Vector(60, 0, 0))
unit.chat = {}
LC.StartSearch(unit, npc2)
scripted(0.99, {}, function() _netcall("lc_pat_check", unit, 0) end)
_netcall("lc_pat_close", unit)
ok(has(unit.chat, "Nothing on them") and not nst2.contraband, "an NPC with nothing: papers in order")
npc:Remove() npc2:Remove()

-- the old search: job games off, the window never opening, or opening too late
_setcvar("lc_jobgames", 0)
local guy4 = newPlayer("PatGuy4", "citizen")
guy4:StripWeapons()
guy4:SetPos(spot + Vector(0, 1500, 0))
unit:SetPos(guy4:GetPos() + Vector(60, 0, 0))
LC.GiveItem(guy4, "uniform_cp")
ok(LC.StartSearch(unit, guy4) and LC.PatSearchOf(guy4) == nil, "with lc_jobgames off there's no window")
_run(3.5)
ok(not LC.HasItem(guy4, "uniform_cp"), "and the search is the old one")
LC.ClearWanted(guy4)
_setcvar("lc_jobgames", 1)
local guy5 = newPlayer("PatGuy5", "citizen")
guy5:StripWeapons()
guy5:SetPos(spot + Vector(0, 1800, 0))
unit:SetPos(guy5:GetPos() + Vector(60, 0, 0))
LC.GiveItem(guy5, "uniform_cp")
LC.StartSearch(unit, guy5)
local S5 = LC.PatSearchOf(guy5)
_run(3.5)
ok(S5 and S5.ended and not S5.live and not LC.HasItem(guy5, "uniform_cp"), "the unit's window never answering: the old search")
_netcall("lc_pat_check", unit, 0)
ok(lastTo("lc_pat_close", unit) ~= nil and LC.PatSearchOf(guy5) == nil, "a window opening too late is told to close")
LC.ClearWanted(guy5)
local guy6 = newPlayer("PatGuy6", "citizen")
guy6:StripWeapons()
guy6:SetPos(spot + Vector(0, 2100, 0))
unit:SetPos(guy6:GetPos() + Vector(60, 0, 0))
LC.GiveItem(guy6, "uniform_cp")
LC.StartSearch(unit, guy6)
_netcall("lc_pat_close", unit) -- (the client couldn't build the window)
ok(LC.PatSearchOf(guy6) == nil and guy6.lcBeingSearched == unit, "a window that can't open hands back to the old search")
_run(3.5)
ok(not LC.HasItem(guy6, "uniform_cp"), "which still finds things")
LC.ClearWanted(guy6)
for _, p in ipairs({ unit, guy, guy2, guy3, guy4, guy5, guy6, stranger }) do p:SetPos(Vector(-30000, 30000, 0)) end
end
PatSearchTests()

function RunningTests()
section("Running in front of Civil Protection")
_setcvar("lc_stops", 0)
_setcvar("lc_can_event", 0)
LC.EndEvent(true)
local rcop, rst
for n, st in pairs(LC.NPCs) do
    if IsValid(n) and st.role == "cop" and not st.questLock and not st.test then rcop, rst = n, st break end
end
for n, st in pairs(LC.NPCs) do -- just the one unit around
    if IsValid(n) and (st.role == "cop" or st.role == "soldier") and n ~= rcop then n:SetPos(Vector(0, -40000, 0)) end
end
LC.CalmCops(nil)
LC.SetState(rcop, rst, "idle")
rst.untilT, rst.nextInspect, rst.nextWarn = CurTime() + 1000, CurTime() + 1000, CurTime() + 1000
rcop.sim = false
-- somewhere quiet: no walls, zones or curfew left over from earlier tests in the way
local savedWalls = _walls
_walls = {}
rcop:SetPos(Vector(26000, -26000, 0))
local here = rcop:GetPos()
ok(not LC.InRebelZone(here) and not LC.Event, "a clear street for the running checks", LC.Event)

local walker = newPlayer("Walker", "citizen")
walker:SetPos(here + Vector(300, 0, 0))
walker.vel = Vector(100, 0, 0)
_run(2)
ok(not LC.Runners[walker] and walker:GetNW2Float("lc_shout_until", 0) == 0, "walking past a unit is fine")
walker.walkspeed, walker.runspeed, walker.vel = 160, 260, Vector(160, 0, 0)
_run(2)
ok(not LC.Runners[walker], "even at a brisk walk (Sandbox's walking pace is faster than the gamemode's)")
-- the gamemode's slow pace: the gap between a walk and a sprint is small
walker.walkspeed, walker.runspeed, walker.vel = 110, 190, Vector(110, 0, 0)
ok(not LC.PlayerSprinting(walker), "walking at the slow pace isn't running")
walker.keys = { [IN_SPEED] = true }
walker.vel = Vector(150, 0, 0)
ok(LC.PlayerSprinting(walker), "holding sprint at the slow pace is, even before you're up to full speed")
walker.keys = nil
walker.vel = Vector(185, 0, 0)
ok(LC.PlayerSprinting(walker), "and so is moving at sprinting speed")
ok(string.find(LC.RunningStatus(walker), "sprinting", 1, true) and string.find(LC.RunningStatus(walker), "unit watching", 1, true),
    "the debug report says whether you're running and whether a unit can see you", LC.RunningStatus(walker))
walker.vel = nil
walker:SetPos(Vector(-30000, 30000, 0))

local sprinter = newPlayer("Sprinter", "citizen")
sprinter:SetPos(here + Vector(300, 0, 0))
sprinter.vel, sprinter.keys = Vector(190, 0, 0), { [IN_SPEED] = true }
_run(0.6)
ok(LC.Runners[sprinter] and has(sprinter.chat, "Stop running!"), "running past a unit gets a shout", table.concat(sprinter.chat or {}, " | "))
ok(sprinter:GetNW2Float("lc_shout_until", 0) > CurTime() and sprinter:GetNW2String("lc_shout", "") == "STOP RUNNING!", "and it's on the screen")
ok(not LC.PlayerIsWanted(sprinter), "you get a moment to stop")
sprinter.vel = nil
_run(5)
ok(not LC.PlayerIsWanted(sprinter), "stopping is the end of it")
sprinter.vel, sprinter.keys = Vector(190, 0, 0), { [IN_SPEED] = true }
_run(2)
ok(LC.PlayerIsWanted(sprinter) and sprinter:GetNW2String("lc_wanted_reason", "") == "Fleeing Civil Protection",
    "running again while he remembers you: wanted for fleeing")
ok(rst.state == "hostile" and rst.enemy == sprinter, "and he comes after you", rst.state)
sprinter.vel = nil
LC.ClearWanted(sprinter)
LC.CalmCops(sprinter)
sprinter:SetPos(Vector(-30000, 30000, 0))

local bolter = newPlayer("Bolter", "citizen")
LC.SetState(rcop, rst, "idle")
bolter:SetPos(here + Vector(300, 0, 0))
bolter.vel, bolter.keys = Vector(190, 0, 0), { [IN_SPEED] = true }
_run(4)
ok(LC.PlayerIsWanted(bolter) and has(bolter.chat, "I said stop running"), "keep running after the shout and he chases you")
-- caught: the first time this hour it's cuffs, the stick and "you can go", not the cells (the owner, 7 November)
bolter.vel = nil
local st0 = LC.Standing(bolter)
ok(LC.RunningOffences(bolter) == 1, "the chase counts as a running offence", LC.RunningOffences(bolter))
ok(LC.NPCTakesIn(rcop, bolter) and LC.RoughingUp[bolter] and LC.IsTied(bolter) and not LC.PlayerIsWanted(bolter) and not LC.InCustody(bolter),
    "a unit who catches him cuffs him on the spot: no cell, no street detention")
_run(8)
ok(not LC.RoughingUp[bolter] and not LC.IsTied(bolter) and has(bolter.chat, "you can go") and LC.Standing(bolter) == st0,
    "a few of the stick, the cuffs off, \"you can go\": no standing lost", table.concat(bolter.chat or {}, " | "))
LC.RunOffences[bolter] = { CurTime(), CurTime(), CurTime() }
ok(not LC.RunningBeating(rcop, bolter, "Fleeing Civil Protection"), "the third time in an hour, it's the cells")
LC.RunOffences[bolter] = nil
LC.ClearWanted(bolter)
LC.CalmCops(bolter)
bolter:SetPos(Vector(-30000, 30000, 0))

local unit = newPlayer("RunUnit", "cp")
LC.SetState(rcop, rst, "idle")
unit:SetPos(here + Vector(300, 0, 0))
unit.vel, unit.keys = Vector(190, 0, 0), { [IN_SPEED] = true }
_run(3)
ok(not LC.Runners[unit] and not LC.PlayerIsWanted(unit), "units can run")
unit.vel = nil
unit:SetPos(Vector(-30000, 30000, 0))
_walls = savedWalls
rcop.sim = true
_setcvar("lc_can_event", 1)
end
RunningTests()

function RebelTests()
local savedWalls = _walls
_walls = {}
_setcvar("lc_auto_events", 0)
_setcvar("lc_skirmishes", 0)
LC.EndEvent(true)
local FAR = Vector(-30000, 30000, 0)
for _, p in ipairs(player.GetAll()) do p:SetPos(FAR) end
LC.CalmCops(nil)

----------------------------------------------------------------------
section("Quest items lie on the ground")
local Q = LC.QB
local motion
local realPhys = _EMT.GetPhysicsObject
_EMT.GetPhysicsObject = function(self)
    return { IsValid = function() return true end, EnableMotion = function(_, b) motion = b end, Wake = function() end }
end
local fakeQ = { ents = {} }
local item = Q.SpawnItem(fakeQ, "models/weapons/w_stunbaton.mdl", Vector(100, 100, 60), nil, true)
ok(item:GetPos().z < 5, "a dropped item lands on the floor instead of floating", tostring(item:GetPos()))
ok(motion == true, "and it has physics")
local bin = Q.SpawnItem(fakeQ, "models/props_junk/trashdumpster01a.mdl", Vector(300, 100, 60))
ok(motion == false and bin:GetPos().z < 5, "big fixtures stand still, on the ground too")
_EMT.GetPhysicsObject = realPhys
item:Remove() bin:Remove()

----------------------------------------------------------------------
section("Scanners leave units alone")
local scn, scst = LC.Spawners.scanner(Vector(24000, 24000, 0))
scn.sim = false
local unitS = newPlayer("ScanUnit", "cp")
unitS:SetPos(Vector(24000, 24300, 0))
_run(1)
ok(scn.kv.NeverInspectPlayers == "1", "a scanner doesn't photograph a unit standing nearby")
LC.RefreshRelations()
ok(scn.rel[unitS] == D_LI, "it counts units as its own")
unitS:SetPos(FAR)
_run(1)
ok(scn.kv.NeverInspectPlayers == "0", "and goes back to photographing people once the unit leaves")
scn:Remove()

----------------------------------------------------------------------
section("The Resistance lives in rebel territory")
_setcvar("lc_npc_budget", 500)
_setcvar("lc_rebels", 3)
for _, z in ipairs(LC.ZonesOfKind("rebel")) do LC.RemoveZone(z) end -- just the one territory, for these tests
local rz = LC.AddZone(Vector(1500, 3500, 0), 500, "rebel", 0)
do -- (the owner, 9 November: at least 1.25 fighters for each Combine NPC on the streets, as room allows)
    _setcvar("lc_rebel_per_combine", 1.25)
    local units = LC.CombineStreetCount()
    ok(LC.RebelTarget() == math.min(LC.RebelRoomIn(rz), math.max(3, math.ceil(1.25 * units - 1e-6))),
        "at least 1.25 Resistance fighters for each Combine NPC on the streets (as the zone's room allows)", LC.RebelTarget() .. " for " .. units)
end
_setcvar("lc_rebel_per_combine", 0) -- (the rest of these tests count lc_rebels alone)
ok(LC.RebelTarget() == 3, "rebels are wanted where there's rebel territory")
_run(10)
ok(count("rebel") >= 3, "and they turn up", count("rebel"))
local reb, rbst
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" then reb, rbst = n, st break end end
ok(reb and LC.InRebelZone(reb:GetPos()), "inside rebel territory")
ok(reb and reb.kv.citizentype == "3" and reb.kv.additionalequipment ~= nil, "in the Resistance's clothes, armed")
_run(40)
local inside = true
for n, st in pairs(LC.NPCs) do
    if IsValid(n) and st.role == "rebel" and n:GetPos():Distance(rz.pos) > rz.r * 1.3 then inside = false end
end
ok(inside, "they keep to their territory")

local friend = newPlayer("RebFriend", "resistance", nil, 200)
friend:SetPos(rz.pos + Vector(100, 0, 0))
_run(1.5)
ok(not LC.RebelAlarms[friend] and reb.rel[friend] == D_LI, "Resistance players are among friends")
friend:SetPos(FAR)

local intruder = newPlayer("RebIntruder", "cp")
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" then st.nextLook = 0 end end
intruder:SetPos(rz.pos + Vector(150, 0, 0))
_run(0.6)
ok(LC.RebelAlarms[intruder] ~= nil and has(intruder.chat, "Combine!"), "a unit walking in gets shouted at first", table.concat(intruder.chat or {}, " | "))
ok(rbst.foe ~= intruder, "not shot at straight away")
_run(3)
local shooters = 0
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" and st.foe == intruder and n.rel[intruder] == D_HT then shooters = shooters + 1 end end
ok(shooters >= 2, "then they open fire", shooters)
local hit = _dmg(reb, 20)
hook.Run("EntityTakeDamage", intruder, hit)
ok(hit:GetDamage() == 12, "rebel fire hurts, but less (dying is permanent; 0.6 of it since 13 November, was 0.5)", hit:GetDamage())
intruder:SetPos(FAR)
_run(2)
local still = 0
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" and st.foe == intruder then still = still + 1 end end
ok(still == 0 and reb.rel[intruder] == D_NU, "once the unit is gone they stand down")

local pest = newPlayer("RebPest", "citizen")
pest:SetPos(rz.pos + Vector(-200, 0, 0))
_run(1)
ok(rbst.foe == nil, "ordinary citizens are left alone")
hook.Run("EntityTakeDamage", reb, _dmg(pest, 5))
ok(rbst.foe == pest and not LC.PlayerIsWanted(pest), "shoot at one and they shoot back (the Combine doesn't care)")
pest:SetPos(FAR)
rbst.provokedUntil = 0
_run(2)
ok(rbst.foe == nil, "and they let it go once you've gone")

----------------------------------------------------------------------
section("Rebels raid the Combine, sometimes")
local cp0 = LC.PointsOfKind("checkpoint")[1].pos
local guard, gst = LC.Spawners.cop(cp0 + Vector(250, 0, 4))
gst.untilT, gst.nextInspect = CurTime() + 1000, CurTime() + 1000
guard.sim = false
ok(LC.StartRebelRaid(rz), "a raid can start")
local sk = LC.Skirmish
ok(sk and sk.kind == "raid" and #sk.rebels >= 2, "with a few fighters", sk and #sk.rebels)
local alerted
for _ = 1, 60 do _run(0.5) if sk.alerted and gst.state == "hostile" then alerted = true break end end
ok(alerted, "the units near the target respond", tostring(sk.alerted) .. " " .. tostring(gst.state))
ok(gst.armed and LC.NPCs[gst.enemy] and LC.NPCs[gst.enemy].role == "rebel", "with guns drawn, at a raider")
local fighting = false
for _ = 1, 20 do
    for _, r in ipairs(sk.rebels) do local st = LC.NPCs[r] if st and st.foe then fighting = true end end
    if fighting then break end
    _run(0.5)
end
ok(fighting, "and the raiders fight them")
for _, r in ipairs(sk.rebels) do if IsValid(r) then r:SetHealth(0) end end
_run(4)
ok(LC.Skirmish == nil, "the raid ends when the raiders are down")
ok(gst.state ~= "hostile", "and the units go back to work", gst.state)
guard:Remove()

----------------------------------------------------------------------
section("The Combine sweeps rebel territory, sometimes")
_run(15) -- the zone fills back up
local okSweep, why = LC.StartCombineSweep(rz)
ok(okSweep, "a sweep can start", why)
local sw = LC.Skirmish
ok(sw and #sw.units >= 3, "an armed team gathers out of sight", sw and #sw.units)
local armed = sw ~= nil
for _, u in ipairs(sw and sw.units or {}) do local st = LC.NPCs[u] if st.role == "cop" and not st.armed then armed = false end end
ok(armed, "units on a sweep carry guns")
local engaged
for _ = 1, 80 do
    _run(0.5)
    for _, u in ipairs(sw.units) do local st = LC.NPCs[u] if st and st.state == "hostile" then engaged = true end end
    if engaged then break end
end
ok(engaged, "they move in and find someone to fight")
local defending = false
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" and st.foe and LC.NPCs[st.foe] then defending = true end end
ok(defending, "and the rebels fight back")
sw.ends = CurTime()
_run(3)
ok(LC.Skirmish == nil, "sweeps end")
_run(6)
local left = 0
for _, u in ipairs(sw.units) do if IsValid(u) and LC.NPCs[u] then left = left + 1 end end
ok(left == 0, "and the team withdraws out of sight", left)

_setcvar("lc_skirmishes", 1)
_setcvar("lc_skirmish_interval", 1)
local sawOne = false
for _ = 1, 120 do _run(1) if LC.Skirmish or LC.PlannedRaid or LC.PlannedSweep then sawOne = true break end end
ok(sawOne, "skirmishes start on their own now and then (planned a little ahead, each side's own told first)")
LC.PlannedRaid = nil
LC.PlannedSweep = nil
if LC.Skirmish then LC.EndSkirmish(LC.Skirmish, "test") end
_setcvar("lc_skirmishes", 0)

----------------------------------------------------------------------
section("The Missing Unit: retaliation finds the rebels home")
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" then n:Remove() end end
_setcvar("lc_rebels", 0)
local mu = newPlayer("MUCop", "cp", nil, 1000)
LC.Story(mu).chains.missing = { part = "retaliation", data = { cause = "rebels" }, readyAt = 0 }
mu.lcStoryPostings = nil
mu.lcqNext = 0
local mp = storyPosting(mu, "missing")
LC.AcceptPosting(mu, mp.id)
ok(LC.QuestOf[mu] and LC.RebelsIn(rz) >= 3, "there are rebels waiting in rebel territory", LC.RebelsIn(rz))
LC.AbandonQuest(mu)

----------------------------------------------------------------------
section("Rebels keep out of doorways, and a camp isn't packed past its room (the owner, 7 November)")
local openSpot = Vector(1500, 3500, 0)
ok(LC.RoomAround(openSpot), "open floor has room round it")
_walls = { { a = Vector(1400, 3470, 0), b = Vector(1600, 3470, 0) }, { a = Vector(1400, 3530, 0), b = Vector(1600, 3530, 0) } }
ok(not LC.RoomAround(openSpot), "a hallway 60 wide hasn't (a person gets through two ways, not three)")
_walls = {}
local roomy, isRoomy = LC.RoomySpot(rz)
ok(roomy ~= nil and isRoomy, "a spot with room round it is found in the camp")
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" then n:Remove() end end
local roomFor = LC.RebelRoomIn(rz)
for _ = 1, roomFor + 5 do
    local _, rst = LC.SpawnRebel(rz.pos + Vector(math.random(-50, 50), math.random(-50, 50), 4), rz)
    if rst then rst.unmanaged = true end
end
ok(LC.RebelsIn(rz) == roomFor + 5, "a camp packed past its room", LC.RebelsIn(rz))
local seenWas = LC.IsSeen
LC.IsSeen = function() return false end
LC.RebelTrimCrowds(CurTime())
LC.IsSeen = seenWas
ok(LC.RebelsIn(rz) == roomFor, "is thinned to what it has room for (lc_rebel_room), unseen", LC.RebelsIn(rz))
for _ = 1, 3 do
    local _, rst = LC.SpawnRebel(rz.pos + Vector(math.random(-50, 50), math.random(-50, 50), 4), rz)
    if rst then rst.unmanaged = true end
end
local clearing = LC.QuietRebels(rz.pos, rz.r or 300, 60)
LC.IsSeen = function() return false end
LC.RebelTrimCrowds(CurTime())
LC.IsSeen = seenWas
ok(LC.RebelsIn(rz) == roomFor + 3, "but not while a team is retaking it: the fighters holding it stay to be cleared", LC.RebelsIn(rz))
clearing.untilT = 0
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" then n:Remove() end end

----------------------------------------------------------------------
section("Birds don't block doors")
local dr = ents.Create("prop_door_rotating")
dr:SetPos(Vector(-24000, -24000, 0))
_run(31) -- the door list refreshes
local bird = ents.Create("npc_pigeon")
bird:SetPos(dr:GetPos() + Vector(20, 0, -30))
LC.Wildlife[bird] = "bird"
_run(2.5)
ok(bird:GetPos():Distance(dr:GetPos()) > 80, "a bird in a doorway gets moved along", tostring(bird:GetPos()))
ok(has(bird.fired, "FlyAway"), "it flies off")
bird:SetPos(dr:GetPos() + Vector(20, 0, -30))
hook.Run("PlayerUse", mu, dr)
ok(bird:GetPos():Distance(dr:GetPos()) > 80, "opening the door shoos it right away")
ok(LC.NearDoor(dr:GetPos() + Vector(50, 0, 0), 160) ~= nil, "and birds don't spawn by doors")
bird:Remove() dr:Remove()

LC.RemoveZone(rz)
_walls = savedWalls
end
RebelTests()

function PlacementAndRouteTests()
local savedWalls = _walls
local FAR = Vector(-30000, 30000, 0)
for _, p in ipairs(player.GetAll()) do p:SetPos(FAR) end

----------------------------------------------------------------------
section("Hidden things go somewhere sensible")
local Q = LC.QB
local C = Vector(-26000, 26000, 0)
_walls = { { a = C + Vector(300, -600, 0), b = C + Vector(300, 600, 0) } } -- a wall east of the spot
local spots = Q.HideSpots(C, 3, 500, true)
local byWall = 0
for _, sp in ipairs(spots) do if math.abs(sp.x - (C.x + 300)) < 40 then byWall = byWall + 1 end end
ok(#spots == 3 and byWall == 3, "contraband ends up on the floor against a wall, not out in the open", byWall)
local dr = ents.Create("prop_door_rotating")
dr:SetPos(C + Vector(290, 0, 0))
LC.NearDoor(C, 1) -- refresh the door list
_run(31)
local inDoor = 0
