local function rollAs(n, fn)
    local r = math.random
    math.random = function(a, b)
        if a == 20 and b == nil then return n end
        if a == nil then return r() elseif b == nil then return r(a) end
        return r(a, b)
    end
    local ok2, res, res2 = pcall(fn)
    math.random = r
    if not ok2 then error(res) end
    return res, res2
end

