n0 = #net.sent
LC.Announce("curfew")
got = netPaths("lc_announce", n0)
ok(#got == 1 and not string.find(got[1], "livingcity/announce", 1, true), "at 0 percent the built-in line is used", got[1])
_setcvar("lc_announce_custom_pct", 100)
