function MindsTests()
section("The city's minds: watched and written down, nothing changes")
local function Later(secs) _advance(secs) _runtimers() end
local Psy = LC.Psy
-- the arithmetic
local a, b = { id = 101, role = "citizen" }, { id = 102, role = "citizen" }
local ta = Psy.Traits(a)
local inRange = true
for _, k in ipairs(Psy.TRAITS) do if ta[k] < -1 or ta[k] > 1 then inRange = false end end
ok(inRange, "five traits, each from -1 to 1")
local again = Psy.Traits({ id = 101, role = "citizen" })
ok(again.brave == ta.brave and again.hope == ta.hope, "worked out from the id: the same person, the same traits, nothing saved")
ok(Psy.Traits({ id = 7, role = "cop" }).loyal >= 0.3, "a unit is always loyal (the force picks the loyal)")
local now0 = CurTime()
Psy.Think(a, "beaten", now0, 55) Psy.Think(a, "beaten", now0 + 1, 55)
ok(#Psy.State(a).th == 1, "the same thought from the same person refreshes, it doesn't stack")
for i = 1, 12 do Psy.Think(a, "chatted", now0, 200 + i) end
ok(#Psy.State(a).th <= Psy.cfg.thoughtCap, "at most 8 thoughts", #Psy.State(a).th)
for i = 1, 12 do Psy.Bond(b, 300 + i, i) end
local nt = 0 for _ in pairs(Psy.State(b).ties) do nt = nt + 1 end
ok(nt <= Psy.cfg.tieCap and Psy.Tie(b, 312) == 10, "at most 8 ties, the weakest go first, capped at 10", nt)
local s = Psy.State(a)
s.stress = Psy.cfg.breakAt + 1
local broke
Psy.Step(a, now0 + 10, { Break = function(_, k) broke = k end })
ok(broke ~= nil and s.stress < Psy.cfg.breakAt, "stress past the line: something gives, and it eases", broke)

-- in the city
_setcvar("lc_minds", 1)
_setcvar("lc_minds_show", 0)
_setcvar("lc_minds_act", 0) -- (watching only first; acting is further down)
LC.Minds.byId, LC.Minds.order, LC.Minds.idx, LC.Minds.buf, LC.Minds.counts, LC.Minds.loaded = {}, {}, 0, {}, {}, true
local T0 = Vector(-39000, 27000, 0)
local function person(off)
    local n, st = LC.SpawnCitizen(T0 + off)
    st.leaveAt = nil
    n.sim = false
    if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
    return n, st
end
local v, vst = person(Vector(0, 0, 0))
local f, fst = person(Vector(120, 0, 0))
local mv, mf = LC.MindOf(v.lcProfile), LC.MindOf(f.lcProfile)
Psy.Bond(mf, mv.id, 5)
local cop = ents.Create("npc_metropolice")
cop:SetPos(T0 + Vector(40, 0, 0))
cop.lcProfile = LC.NewPerson("cop")
local stateBefore, rebelBefore = vst.state, v.lcProfile.rebel
LC.MindsHurt(v, cop, 10)
local function has(m, k) for _, t in ipairs(Psy.State(m).th) do if t.k == k then return t end end end
ok(has(mv, "beaten") and Psy.Tie(mv, cop.lcProfile.id) < 0, "beaten by a unit: they feel it, and hold it against him")
ok(has(mf, "friend_beaten"), "a friend who saw it feels it too")
local heard = false
for _, n in ipairs(Psy.State(mf).news) do if n.k == "beating" and n.about == cop.lcProfile.id then heard = true end end
ok(heard, "and knows who did it, to pass on")
LC.Minds.order = { mv.id } LC.Minds.idx = 0
Psy.State(mv).stress = Psy.cfg.breakAt + 5
Psy.State(mv).broke = -1e9
local got = false
for _ = 1, 4 do
    LC.Minds.idx = 0 LC.Minds.order = { mv.id }
    LC.MindsStep(CurTime())
    for _, l in ipairs(LC.Minds.buf) do if string.find(l, "WOULD", 1, true) and string.find(l, mv.name, 1, true) then got = true end end
    if got then break end
    Later(1)
end
ok(got, "a break is written down as what they WOULD have done")
ok(vst.state == stateBefore and v.lcProfile.rebel == rebelBefore, "and nothing about them changes: same state, same side")
ok(v.lcProfile.psy == nil and v.lcProfile.tr == nil, "the roster's records are untouched (the minds are kept apart)")
-- the talk window
ok(LC.MindsSeem(v) == "", "lc_minds_show 0: the talk window says nothing new")
_setcvar("lc_minds_show", 1)
ok(string.find(LC.MindsSeem(v), "They seem", 1, true), "lc_minds_show 1: how they seem and why", LC.MindsSeem(v))
_setcvar("lc_minds_show", 0)
-- the log and the report
LC.MindsFlush()
local wrote
for p, text in pairs(_files) do if string.find(p, "livingcity/minds/rp_test_", 1, true) and string.find(text, "WOULD", 1, true) then wrote = p end end
ok(wrote ~= nil, "written to data/livingcity/minds/<map>_<date>.txt", wrote)
ok(string.find(LC.BuildReport(), "The city's minds", 1, true), "the debug report has a section for it")
local snap = LC.MindsSnapshot(2)
ok(string.find(snap[1], "unrest=", 1, true) and string.find(snap[1], "avg_us=", 1, true), "snapshots say how the city feels and what it costs", snap[1])
-- kept over a map change
local stress = Psy.State(mv).stress
LC.MindsSave()
LC.Minds.byId = {}
ok(LC.MindsLoad() >= 2 and LC.Minds.byId[mv.id].psy and math.abs(LC.Minds.byId[mv.id].psy.stress - stress) < 0.01
    and LC.Minds.byId[mv.id].psy.ties[cop.lcProfile.id] ~= nil, "saved and put back over a map change, ties and all")
mv = LC.MindOf(v.lcProfile) -- (the mind as put back)
-- the second set of traits (10 November): eleven, independent of each other
ok(#Psy.TRAITS == 11 and Psy.TRAITS[6] == "greed" and Psy.TRAITS[11] == "vice", "eleven traits, the new ones on the end", #Psy.TRAITS)
do
    local xs, ys = {}, {}
    for i = 1, 400 do local tr = Psy.Traits({ id = 5000 + i, role = "citizen" }) xs[i], ys[i] = tr.temper, tr.hope end
    local function mean(a) local s = 0 for _, x in ipairs(a) do s = s + x end return s / #a end
    local mx, my, sxy, sxx, syy = mean(xs), mean(ys), 0, 0, 0
    for i = 1, #xs do sxy = sxy + (xs[i] - mx) * (ys[i] - my) sxx = sxx + (xs[i] - mx) ^ 2 syy = syy + (ys[i] - my) ^ 2 end
    ok(math.abs(sxy / math.sqrt(sxx * syy)) < 0.15, "traits don't move together (the first dice made them)", sxy / math.sqrt(sxx * syy))
end
local proud, humble
for i = 1, 400 do
    local q = { id = 7000 + i, role = "citizen" }
    local tr = Psy.Traits(q)
    if tr.pride > 0.7 and not proud then proud = q elseif tr.pride < -0.7 and not humble then humble = q end
end
Psy.Think(proud, "stopped", CurTime()) Psy.Think(humble, "stopped", CurTime())
ok(Psy.State(proud).th[1].v < Psy.State(humble).th[1].v, "being searched stings the proud more than the humble", Psy.State(proud).th[1].v)
local sober, drinker
for i = 1, 400 do
    local q = { id = 9000 + i, role = "citizen" }
    local tr = Psy.Traits(q)
    if tr.vice <= 0 and not sober then sober = q elseif tr.vice > 0.6 and not drinker then drinker = q end
end
Psy.Step(sober, 1000, {}) Psy.Step(sober, 2000, {}) Psy.Step(drinker, 1000, {}) Psy.Step(drinker, 2000, {})
ok((Psy.State(sober).crave or 0) == 0 and Psy.State(drinker).crave > 0, "only those fond of a drink and a smoke come to crave one")
ok(#Psy.TraitWords(drinker, 11) > 0 and string.find(table.concat(Psy.TraitWords(drinker, 11), ","), "drink", 1, true), "and it's said in words", table.concat(Psy.TraitWords(drinker, 11), ", "))
local kinds = {}
for _ = 1, 300 do kinds[Psy.ChooseBreak(drinker, {})] = true kinds[Psy.ChooseInspiration(drinker, {})] = true end
ok(kinds.tantrum ~= nil or kinds.despair ~= nil or kinds.binge ~= nil, "breaks are chosen from the longer list")
-- what the city tells them now
Psy.State(mv).th = {}
hook.Run("LivingCityEventStarted", "curfew", 5)
ok(has(mv, "curfew"), "a curfew: everyone feels it")
LC.Minds.lastSocio = "green" LC.Socio = "red"
LC.MindsSocio()
ok(has(mv, "city_red"), "sociostability red: frightened")
LC.Socio = "green" LC.MindsSocio()
ok(has(mv, "relief"), "and relieved when it calms")
local thief = newPlayer("MindsThief", "citizen")
thief:SetPos(T0)
hook.Run("LivingCityPickpocket", thief, v, false)
ok(has(mv, "robbed") and Psy.Tie(mv, "pl:" .. LC.MemoryKey(thief)) < 0, "a pickpocket caught at it: robbed, and held against them")
vst.state = "detained"
LC.Minds.order = { mv.id } LC.Minds.idx = 0
LC.MindsStep(CurTime())
ok(has(mv, "stopped"), "stopped and searched by a unit: they feel it")
vst.state = stateBefore
-- a drink, given
Psy.State(mv).crave = 0.9
hook.Run("LivingCitySharedFood", thief, v, "beer")
ok(Psy.State(mv).crave == 0 and has(mv, "indulged"), "a player's beer: the craving goes")
-- drinking and smoking in the street (sv_livingcity_npcvices.lua)
local dp
for _ = 1, 400 do
    local q = LC.NewPerson("citizen")
    if LC.Psy.Traits(LC.MindOf(q)).vice > 0.5 then dp = q break end
end
local dn, dst = person(Vector(0, 200, 0))
if dn.lcProfile then dn.lcProfile.npc = nil end
LC.AttachProfile(dn, dst, dp)
dst.state = "idle"
dst.untilT, dst.nextThink, dst.test = CurTime() + 9999, CurTime() + 9999, nil -- (held still: the city's loop doesn't send them off mid-test)
ok(LC.NPCViceOf(dn) > 0.5 and LC.NPCViceOf(cop) == 0, "who drinks and smokes comes from their traits; never a unit")
_setcvar("lc_npc_vices", 1)
ok(LC.NPCViceStart(dn, "drink", CurTime()) and IsValid(LC.NPCVices[dn].prop), "a bottle in their hand")
ok(LC.MindOf(dp).psy and has(LC.MindOf(dp), "indulged"), "and their mind knows they had one")
LC.NPCViceTick(CurTime() + 2)
ok(LC.NPCVices[dn] ~= nil, "they keep at it while they stand about")
local prop = LC.NPCVices[dn] and LC.NPCVices[dn].prop
dst.state = "moving"
LC.NPCViceTick(CurTime())
ok(LC.NPCVices[dn] == nil and not IsValid(prop), "off somewhere: the bottle goes")
dst.state = "idle"
net.sent = {}
LC.NPCViceStart(dn, "smoke", CurTime())
LC.NPCViceTick(CurTime() + 5)
local puffed = false
for _, msg in ipairs(net.sent) do if msg.name == "lc_vice" and msg.data[1] == "smoke" and msg.data[2] == dn then puffed = true end end
ok(puffed, "a cigarette: puffs of smoke from them")
_setcvar("lc_npc_vices", 0)
LC.NPCViceTick(CurTime())
ok(next(LC.NPCVices) == nil, "lc_npc_vices 0: nobody drinks or smokes")
if IsValid(dn) then dn:Remove() end
-- acting (sv_livingcity_mindsact.lua)
section("The city's minds: acting")
ok(LC.MindsBias(v, vst, CurTime()) == nil and LC.MindsAct(mv, "despair", CurTime()) == nil and LC.MindsIsInformer(v, vst) == nil
    and not LC.MindsUnrestHigh(), "lc_minds_act 0: watching only, nothing bends and nothing is done")
_setcvar("lc_minds_act", 1)
mv, mf = LC.MindOf(v.lcProfile), LC.MindOf(f.lcProfile)
for _, e in ipairs({ v, f }) do local s = LC.NPCs[e] s.state, s.leaving, s.questLock, s.snitchReport, s.test = "idle", nil, nil, nil, nil end
Psy.State(mv).food = 0.1
local bias = LC.MindsBias(v, vst, CurTime())
ok(bias and bias.line > 1, "hungry: the ration line draws them", bias and bias.line)
Psy.State(mv).food = 0.8
-- a tantrum: up to a unit, and stopped (or taken in)
local unit, ust = LC.SpawnCop(T0 + Vector(600, 0, 0))
ust = ust or LC.NPCs[unit]
unit.sim = false
local arrest = LC.ArrestNPC
LC.ArrestNPC = function() return false end
local did = LC.MindsAct(mv, "tantrum", CurTime())
ok(vst.mindErrand ~= nil and vst.questLock == true and has(mv, "vented"), "a tantrum: they set off for the nearest unit", did)
v:SetPos(unit:GetPos() + Vector(50, 0, 0))
LC.MindsErrandTick(CurTime())
LC.StageTick(CurTime() + 16) -- (where a player sees it, or 15 seconds on: sv_livingcity_idlelife.lua)
ok(vst.mindErrand == nil and vst.questLock == nil and vst.state == "detained", "and scream in his face: stopped where they stand", vst.state)
LC.ArrestNPC = arrest
vst.state = "idle"
v:SetPos(T0)
-- an errand that never gets there is dropped
LC.MindsAct(mv, "tantrum", CurTime())
LC.MindsErrandTick(CurTime() + 200)
ok(vst.mindErrand == nil and vst.questLock == nil and next(LC.MindsActs.errands) == nil, "an errand that takes too long is dropped, and they go about their day")
vst.state = "idle"
-- defiance: a poster painted over, and a new sympathizer
v.lcProfile.rebel, vst.rebel, mv.rebel = nil, false, nil
local poster = ents.Create("lc_civposter")
poster:SetPos(T0 + Vector(0, 300, 0))
for i = 1, 8 do LC.Minds.byId[8000 + i] = { id = 8000 + i, role = "citizen", p = { id = 8000 + i, alive = true }, name = "Crowd" .. i } end -- (a roster big enough that one more sympathizer is under the cap)
did = LC.MindsAct(mv, "defy", CurTime())
for i = 1, 8 do LC.Minds.byId[8000 + i] = nil end
ok(v.lcProfile.rebel == true and vst.rebel == true and vst.mindErrand ~= nil, "defiance: they side with the Resistance, and go for a poster", did)
v:SetPos(poster:GetPos() + Vector(40, 0, 0))
LC.MindsErrandTick(CurTime())
LC.StageTick(CurTime() + 16)
ok(poster:GetNW2Bool("lc_defaced", false) == true, "the poster is painted over")
ok(LC.MindsIsInformer(v, vst) == false, "a sympathizer is never an informant")
v:SetPos(T0)
vst.state = "idle"
-- informants from who people are: the same share as the roll
local byId = LC.Minds.byId
LC.Minds.byId = {}
for i = 1, 50 do LC.Minds.byId[9000 + i] = { id = 9000 + i, role = "citizen", p = { id = 9000 + i, alive = true }, name = "T" .. i } end
LC.MindsActs.informers = nil
v.lcProfile.rebel, vst.rebel, mv.rebel = nil, false, nil
LC.Minds.byId[mv.id] = mv
LC.MindsIsInformer(v, vst)
local infs = 0
for _ in pairs(LC.MindsActs.informers or {}) do infs = infs + 1 end
LC.Minds.byId = byId
LC.MindsActs.informers = nil
ok(infs == 6, "informants come from the minds: 12% of 51 named citizens is 6", infs)
-- an informer names a player they hold a grudge against
v.lcProfile.rebel, vst.rebel, mv.rebel = nil, false, nil
local grudge = newPlayer("MindGrudge", "citizen")
grudge:SetPos(T0 + Vector(200, 0, 0))
local gkey = "pl:" .. ((LC.MemoryKey and LC.MemoryKey(grudge)) or grudge:SteamID())
Psy.Bond(mv, gkey, -6)
Psy.State(mv).th = {}
did = LC.MindsAct(mv, "inform", CurTime())
ok(vst.snitch == true and vst.mindErrand ~= nil, "informing: they are an informant now, and set off for a unit with a name", did)
v:SetPos(unit:GetPos() + Vector(50, 0, 0))
LC.MindsErrandTick(CurTime())
ok(grudge:GetNW2Float("lc_spotted_until", 0) > CurTime() and has(mv, "snitched"), "the unit hears the name: the player is outlined for Civil Protection")
v:SetPos(T0)
vst.state = "idle"
-- despair
did = LC.MindsAct(mv, "despair", CurTime())
ok((vst.mindLowUntil or 0) > CurTime() and LC.MindsBias(v, vst, CurTime()).work == 0, "despair: no work and little queueing for a while", did)
vst.mindLowUntil, vst.leaving, vst.state = nil, nil, "idle"
-- an accusation, out loud
fst.state = "idle"
f:SetPos(T0 + Vector(120, 0, 0))
Psy.State(mv).ties = {}
Psy.Bond(mv, mf.id, -5)
did = LC.MindsAct(mv, "accuse", CurTime())
ok(has(mf, "accused") and Psy.Tie(mf, mv.id) < 5, "an accusation: the accused hears it, and thinks less of them", did)
-- sharing
Psy.State(mv).ties = {}
Psy.Bond(mv, mf.id, 5)
Psy.State(mf).food, Psy.State(mv).food = 0.1, 0.9
LC.MindsAct(mv, "share", CurTime())
ok(Psy.State(mf).food > 0.3 and Psy.State(mv).food < 0.8 and has(mf, "kindness"), "sharing: a hungry friend is fed from their own ration")
-- steadying
Psy.State(mf).stress = 10
LC.MindsAct(mv, "steady", CurTime())
ok(Psy.State(mf).stress == 7 and has(mf, "steadied"), "steadying: the people near are calmer for it")
-- a brutal unit
local mu = LC.MindOf(unit.lcProfile or LC.AttachProfile(unit, ust, LC.NewPerson("cop")) or unit.lcProfile)
Psy.State(mu)
unit:SetPos(T0 + Vector(60, 60, 0))
local hp = v:Health()
Psy.State(mv).th = {}
did = LC.MindsAct(mu, "brutal", CurTime())
LC.MindsErrandTick(CurTime())
LC.StageTick(CurTime() + 16)
ok(string.find(did or "", "beat", 1, true) ~= nil and (has(mv, "beaten") or has(mf, "beaten")), "a brutal unit beats the nearest citizen, who feels it", did)
ok(v:Health() > 0 and f:Health() > 0, "never to death")
for _, e in ipairs({ v, f }) do LC.NPCs[e].state = "idle" end
-- a unit drinking on duty
did = LC.MindsAct(mu, "drink", CurTime())
ok((ust.nextInspect or 0) >= CurTime() + 299, "a unit drinking on duty stops nobody for five minutes", did)
-- a leak
vst.snitch = true
local radio = {}
local rn = LC.RadioNotice
LC.RadioNotice = function(band, text) radio[#radio + 1] = band .. ": " .. text end
did = LC.MindsAct(mu, "leak", CurTime())
LC.RadioNotice = rn
ok(#radio == 1 and string.find(radio[1], "resistance: ", 1, true) == 1 and string.find(radio[1], v.lcProfile.name, 1, true) ~= nil, "a leak: Freq 7 hears who has been informing", radio[1])
vst.snitch = nil
-- unrest and sociostability
_setcvar("lc_minds_unrest", 0.4)
local real = Psy.Unrest
Psy.Unrest = function() return 0.5 end
LC.MindsActs.unrestUntil = 0
ok(LC.MindsUnrestHigh() == true, "unrest past the line: the city's mood counts")
local level, why = LC.SocioAuto()
ok(level ~= "green", "and sociostability is not green for it", tostring(level) .. " " .. tostring(why))
Psy.Unrest = function() return 0.35 end
LC.MindsActs.unrestUntil = 0
ok(LC.MindsUnrestHigh() == true, "it holds until the mood has eased a little below the line")
Psy.Unrest = function() return 0.1 end
LC.MindsActs.unrestUntil = 0
ok(LC.MindsUnrestHigh() == false, "and then it is over")
Psy.Unrest = real
LC.MindsActs.unrestUntil = 0
-- the log says what was done
local didLine = false
for _, l in ipairs(LC.Minds.buf) do if string.find(l, "DID", 1, true) then didLine = true end end
Psy.State(mv).stress, Psy.State(mv).broke = Psy.cfg.breakAt + 5, -1e9
LC.Minds.idx = 0 LC.Minds.order = { mv.id }
vst.state = "idle"
LC.MindsStep(CurTime())
for _, l in ipairs(LC.Minds.buf) do if string.find(l, "DID", 1, true) then didLine = true end end
ok(didLine, "a break in the city is written down as done (DID), after the WOULD line")
ok(#LC.MindsActReport() >= 1, "the debug report says what the minds have done")
for _, e in ipairs({ unit, poster, grudge }) do if IsValid(e) then e:Remove() end end
LC.MindsActs.errands = {}
_setcvar("lc_minds_act", 0)
-- off
_setcvar("lc_minds", 0)
local n0 = #LC.Minds.buf
LC.MindsHurt(v, cop, 10)
LC.MindsStep(CurTime())
ok(#LC.Minds.buf == n0 and LC.MindsSeem(v) == "", "lc_minds 0: nothing is watched or written")
for _, e in ipairs({ v, f, cop }) do if IsValid(e) then e:Remove() end end
end
MindsTests()

function ChronicleTests()
section("The chronicle: what happened, and what led to it")
_setcvar("lc_chronicle", 1)
local C, M = LC.Chron, LC.Minds
C.list, C.byN, C.n, C.seen, C.loaded = {}, {}, 0, {}, true
local keepMinds = M.byId
M.byId = { [9001] = { id = 9001, name = "Olga Volkov", role = "citizen" }, [9002] = { id = 9002, name = "Pavel Orlov", role = "citizen" },
    [9003] = { id = 9003, name = "Irina Belova", role = "citizen" }, [9030] = { id = 9030, name = "Unit 30", role = "cop" } }
local t0 = 1000000
local e1 = LC.ChronicleAdd({ k = "hurt", s = 9030, o = 9002, pred = "beat Pavel Orlov", w = 3, saw = { 9001, 9003 } }, t0)
ok(e1 and e1.c == nil and e1.sn == "Unit 30" and #C.list == 1, "a thing that happened is written down: who, what, to whom, who saw")
ok(LC.ChronicleAdd({ k = "hurt", s = 9030, o = 9002, pred = "beat Pavel Orlov", w = 3 }, t0 + 30) == e1 and #C.list == 1, "the same blow again within two minutes is one entry")
local e2 = LC.ChronicleBroke(M.byId[9001], "defy", "went to paint over a poster, and sides with the Resistance now", t0 + 600)
ok(e2 and e2.c == e1.n and e2.pred == "went to paint over a poster" and not e2.sec, "someone who saw it and later broke: the beating is what led to it (and whose side they took isn't street talk)", e2 and e2.pred)
local e3 = LC.ChronicleAdd({ k = "arrest", s = 9001, o = 9030, pred = "was taken to the cells by Unit 30", w = 3 }, t0 + 900)
ok(e3 and e3.c == e2.n, "then taken in: what they did is what led to it")
local st = LC.ChronicleStories(t0 - 1, t0 + 1000, true)
ok(#st == 1 and st[1].text == "Unit 30 beat Pavel Orlov. Olga Volkov saw it, and later went to paint over a poster. Then, Olga Volkov was taken to the cells by Unit 30.",
    "one story, told from its start", st[1] and st[1].text)
-- secrets
local e4 = LC.ChronicleBroke(M.byId[9002], "inform", "is an informant now", t0 + 1000)
ok(e4 and e4.sec == true and e4.c == e1.n, "an informer is written down, with why")
local told = ""
for _, s in ipairs(LC.ChronicleStories(t0 - 1, t0 + 1100, true)) do told = told .. s.text end
ok(not string.find(told, "informant", 1, true), "players are never told who informs")
local staff = ""
for _, s in ipairs(LC.ChronicleStories(t0 - 1, t0 + 1100, false)) do staff = staff .. s.text end
ok(string.find(staff, "Pavel Orlov is an informant now", 1, true) ~= nil, "the owner's stories file has it")
local quiet = LC.ChronicleBroke(M.byId[9003], "tantrum", "let it out at home", t0 + 1100)
ok(quiet and quiet.sec == true and quiet.w == 1, "what's done quietly at home is kept from the street, and leads to nothing")
local late = LC.ChronicleAdd({ k = "did:tantrum", s = 9003, pred = "shouted in the street", w = 3 }, t0 + 5 * 3600)
ok(late and late.c == nil, "three hours on, nothing is put down to it any more")
-- a citizen passes it on, once
local p = newPlayer("ChronA", "citizen")
local line = LC.ChronicleRumor(p, nil, t0 + 1200)
ok(line and string.find(line, "Unit 30 beat Pavel Orlov", 1, true) ~= nil, "Chat: a citizen passes the story on", line)
local line2 = LC.ChronicleRumor(p, nil, t0 + 1200)
ok(line2 == nil or not string.find(line2, "taken to the cells", 1, true), "each story once to each player", line2)
local witness = ents.Create("npc_citizen")
witness:Spawn()
witness.lcProfile = { id = 9003, name = "Irina Belova", role = "citizen" }
local p2 = newPlayer("ChronB", "citizen")
local sawLine = LC.ChronicleRumor(p2, witness, t0 + 1200)
ok(sawLine and string.sub(sawLine, 1, 16) == "I saw it myself.", "one who was there says so", sawLine)
local inIt = ents.Create("npc_citizen")
inIt:Spawn()
inIt.lcProfile = { id = 9001, name = "Olga Volkov", role = "citizen" }
local p3 = newPlayer("ChronC", "citizen")
local own = LC.ChronicleRumor(p3, inIt, t0 + 1200)
ok(own == nil or not string.find(own, "Olga Volkov", 1, true), "nobody gossips about themselves", own)
-- on joining
ok(LC.ChronicleAway(p, t0 + 2000) == nil, "never here before: no card")
C.seen[tostring(p:SteamID())] = t0 - 100
local away = LC.ChronicleAway(p, t0 + 2000)
ok(away and string.find(away, "Olga Volkov saw it", 1, true) ~= nil and #away <= 400, "back after a while: what happened while you were away", away)
C.seen[tostring(p:SteamID())] = t0 + 1900
ok(LC.ChronicleAway(p, t0 + 2000) == nil, "gone for a minute: no card")
local news = LC.ChronicleNews(t0 + 2000)
ok(#news >= 1 and news[1].mins >= 0 and LC.SlashCommands.news ~= nil, "staff: F1 > What now? > The city's stories lists the day (and !news)", #news)
local newsText = ""
for _, s in ipairs(news) do newsText = newsText .. s.text end
ok(string.find(newsText, "informant", 1, true) ~= nil, "the staff list has the secrets")
p.IsAdmin = function() return false end
ok(LC.SendNews(p) == false and LC.ChronicleStaff(p) == false, "a player who isn't staff is sent nothing: the stories are heard in the world")
p.IsAdmin = nil
-- the two feeds (lc_newsfeed)
M.byId[9003].rebel = true -- (Irina Belova, who saw the beating, is a sympathizer)
local feeds = LC.ChronicleFeeds(t0 + 2000)
local cpText, rbText = "", ""
for _, it in ipairs(feeds.cp) do cpText = cpText .. it.text .. " " end
for _, it in ipairs(feeds.rebel) do rbText = rbText .. it.text .. " " end
ok(string.find(cpText, "DETAINED: OLGA VOLKOV.", 1, true) ~= nil, "the Civil Protection feed lists an arrest", cpText)
ok(not string.find(cpText, "BEAT", 1, true) and not string.find(cpText, "POSTER", 1, true), "and only what was formally reported: not a unit's beating, not a poster", cpText)
ok(string.find(rbText, "Unit 30 beat Pavel Orlov.", 1, true) ~= nil, "the Resistance board has what one of their own saw", rbText)
ok(not string.find(rbText, "informant", 1, true), "and no secrets", rbText)
local e5 = LC.ChronicleAdd({ k = "hurt", s = 9001, o = 9030, pred = "attacked Unit 30", w = 3, saw = { 9003 } }, t0 + 1950)
local feeds2 = LC.ChronicleFeeds(t0 + 2000)
ok(feeds2.cp[1] and feeds2.cp[1].text == "ASSAULT ON UNIT 30." and feeds2.cp[1].hot == true and feeds2.cp[1].more == "SUSPECT: OLGA VOLKOV", "a unit attacked is on the feed at once, in red, with the suspect", feeds2.cp[1] and feeds2.cp[1].text)
local soon = false
for _, it in ipairs(feeds2.rebel) do if string.find(it.text, "attacked Unit 30", 1, true) then soon = true end end
ok(not soon, "word takes five minutes to reach the Resistance's board")
M.byId[9003].rebel = nil
_setcvar("lc_rebel_rules", 0) -- (the cell's mood and rules head the board otherwise: RebelRuleTests)
ok(#LC.ChronicleFeeds(t0 + 2000).rebel == 0, "with none of their own there to see, the board has nothing")
_setcvar("lc_rebel_rules", 1)
ok(#LC.ChronicleReport() >= 1, "the debug report has a line for it")
-- kept over a map change
LC.ChronicleSave(t0 + 2000)
local n = #C.list
C.list, C.byN, C.n, C.seen = {}, {}, 0, {}
ok(LC.ChronicleLoad() == n and C.byN[e3.n] and C.byN[e3.n].c == e2.n and C.byN[e1.n].saw[1] == 9001, "saved and read back: the entries, their causes and who saw", #C.list)
local sameAgain = false
for _, s2 in ipairs(LC.ChronicleStories(t0 - 1, t0 + 1000, true)) do if string.find(s2.text, "Olga Volkov was taken to the cells by Unit 30.", 1, true) then sameAgain = true end end
ok(sameAgain, "and the same story is told after it")
-- off
_setcvar("lc_chronicle", 0)
ok(LC.ChronicleAdd({ k = "hurt", s = 9030, o = 9001, pred = "beat Olga Volkov", w = 3 }, t0 + 9000) == nil and LC.ChronicleRumor(p3, nil, t0 + 1200) == nil
    and LC.ChronicleAway(p, t0 + 9000) == nil, "lc_chronicle 0: nothing is written or told")
for _, e in ipairs({ witness, inIt }) do if IsValid(e) then e:Remove() end end
C.list, C.byN, C.n, C.seen = {}, {}, 0, {}
M.byId = keepMinds
end
ChronicleTests()

function ChairTests()
section("The Resistance's interrogation chair")
_setcvar("lc_chair", 1)
_setcvar("lc_chronicle", 1)
local C = LC.Chron
C.list, C.byN, C.n, C.seen, C.loaded = {}, {}, 0, {}, true
local P0 = Vector(-26000, 30000, 0)
local chair = ents.Create("lc_interrochair")
chair:SetPos(P0)
chair:Spawn()
local function person(off)
    local n, st = LC.SpawnCitizen(P0 + off)
    st.leaveAt = nil
    n.sim = false
    if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
    LC.Minds.byId[n.lcProfile.id] = LC.Minds.byId[n.lcProfile.id] or { id = n.lcProfile.id, name = n.lcProfile.name, role = "citizen" }
    return n, st
end
local function has(k) for _, e in ipairs(C.list) do if e.k == k then return e end end return nil end
local rebel = newPlayer("ChairRebel", "resistance", nil, 900)
local member = newPlayer("ChairMember", "resistance", nil, 150)
rebel:SetPos(P0 + Vector(100, 0, 0))
local cit = newPlayer("ChairCit", "citizen")
cit:SetPos(P0 + Vector(100, 50, 0))
local n, st = person(Vector(300, 0, 0))
ok(rebel:GetNW2Int("lcf_rank", 1) >= 3 and member:GetNW2Int("lcf_rank", 1) < 3, "a Lieutenant and a Member to try it", rebel:GetNW2Int("lcf_rank", 1))
ok(LC.ChairFor(cit, n) == nil and LC.ChairFor(member, n) == nil and LC.ChairFor(rebel, n) == chair, "a Resistance Fighter or above with a chair within reach can take a citizen to it; nobody else")
local far = person(Vector(4000, 0, 0))
ok(LC.ChairFor(rebel, far) == nil, "no chair near enough: no such option")
local said, close = LC.ChairTake(rebel, n)
ok(close == true and LC.Chairs[chair] ~= nil and st.questLock == true, "taken by the arm: they're on their way, and the talk window closes", said)
local other = person(Vector(320, 40, 0))
ok(LC.ChairFor(rebel, other) == nil, "the chair is spoken for")
n:SetPos(P0 + Vector(30, 0, 0))
LC.ChairTick(CurTime())
local s = LC.Chairs[chair]
ok(s and s.seated == true and st.state == "detained" and chair:GetNW2Entity("lc_chair_sitter") == n and s.resolve >= 1 and s.resolve <= 5,
    "at the chair they're sat in it, held there, and how long they'll hold out comes from who they are", s and s.resolve)
s.resolve = 2
ok(LC.ChairDo(cit, chair, "hit") == nil, "only the one asking can touch them")
local r1 = LC.ChairDo(rebel, chair, "done")
ok(r1 ~= nil and not string.find(r1, "comes out", 1, true), "nobody talks at first", r1)
local id = n.lcProfile.id
LC.ChronicleAdd({ k = "snitch", s = id, sn = "Test Person", pred = "reported ChairRebel to Civil Protection", w = 2, sec = true })
local hp = n:Health()
LC.ChairDo(rebel, chair, "hit")
local blow = LC.ChairDo(rebel, chair, "hit")
ok(s.hits == 2 and n:Health() < hp and n:Health() >= 10 and string.find(blow, "Something in them gives", 1, true) ~= nil, "two blows with the fists: hurt, never near death, and their resolve is gone", blow)
ok(has("chair") ~= nil and has("chair").w == 3, "a beating in the chair is in the chronicle")
local r2 = LC.ChairDo(rebel, chair, "done")
ok(r2 and string.find(r2, "Test Person reported ChairRebel to Civil Protection.", 1, true) ~= nil, "broken, they give up what the chronicle says they did: this is how an informer is found", r2)
local r3 = LC.ChairDo(rebel, chair, "done")
ok(r3 and not string.find(r3, "reported", 1, true) and not s.wronged, "the same thing isn't told twice, and someone who had something to tell wasn't wronged", r3)
for _ = 1, 10 do LC.ChairDo(rebel, chair, "hit") end
ok(s.hits == 6 and n:Health() >= 10, "six blows at most")
ok(LC.ChairDo(rebel, chair, "free") ~= nil and LC.Chairs[chair] == nil and st.questLock == nil and st.state ~= "detained", "let go: they're free to walk off, and the chair is empty")
-- someone who has done nothing
local n2, st2 = person(Vector(200, 100, 0))
st2.rebel = true
n2.lcProfile.rebel = true
LC.ChairTake(rebel, n2)
n2:SetPos(P0 + Vector(20, 0, 0))
LC.ChairTick(CurTime())
local s2 = LC.Chairs[chair]
s2.resolve = 1
LC.ChairDo(rebel, chair, "hit")
ok(not string.find(LC.ChairDo(rebel, chair, "done"), "gone now", 1, true) and not s2.wronged, "one blow and nothing to tell: no harm done yet")
LC.ChairDo(rebel, chair, "hit")
local r4 = LC.ChairDo(rebel, chair, "done")
ok(s2.wronged == true and string.find(r4, "it's gone now", 1, true) ~= nil and st2.rebel == false and n2.lcProfile.rebel == false,
    "beaten twice for nothing: a sympathizer stops being one", r4)
ok(has("chair_wrong") ~= nil and string.find(has("chair_wrong").pred, "in the chair for nothing", 1, true) ~= nil, "and the chronicle has it, for the street to tell")
-- the one asking walks away
rebel:SetPos(P0 + Vector(3000, 0, 0))
LC.ChairTick(CurTime())
ok(LC.Chairs[chair] ~= nil, "a moment away isn't the end of it")
LC.ChairTick(CurTime() + 25)
ok(LC.Chairs[chair] == nil and st2.state ~= "detained", "left alone for twenty seconds, they get up and go")
_setcvar("lc_chair", 0)
rebel:SetPos(P0 + Vector(100, 0, 0))
ok(LC.ChairFor(rebel, other) == nil, "lc_chair 0: no such option")
for _, e in ipairs({ n, n2, other, far, chair }) do if IsValid(e) then LC.NPCs[e] = nil e:Remove() end end
C.list, C.byN, C.n = {}, {}, 0
_setcvar("lc_chronicle", 0)
end
ChairTests()

function CageTests()
section("The Resistance's holding cage")
_setcvar("lc_rebel_cage", 1)
_setcvar("lc_rebel_auto", 0) -- (by hand first; the cell's own questioning is further down)
_setcvar("lc_rebel_visitor", 0)
_setcvar("lc_chair", 1)
_setcvar("lc_chronicle", 1)
local C = LC.Chron
C.list, C.byN, C.n, C.seen, C.loaded = {}, {}, 0, {}, true
local P0 = Vector(-22000, 30000, 0)
local cage = ents.Create("lc_rebelcage")
cage:SetPos(P0)
cage:Spawn()
local function person(off)
    local n, st = LC.SpawnCitizen(P0 + off)
    st.leaveAt = nil
    n.sim = false
    if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
    LC.Minds.byId[n.lcProfile.id] = LC.Minds.byId[n.lcProfile.id] or { id = n.lcProfile.id, name = n.lcProfile.name, role = "citizen" }
    return n, st
end
local function count(k) local c = 0 for _, e in ipairs(C.list) do if e.k == k then c = c + 1 end end return c end
local lt = newPlayer("CageLt", "resistance", nil, 900)
lt:SetPos(P0 + Vector(120, 0, 0))
local member = newPlayer("CageMember", "resistance", nil, 150)
local cit = newPlayer("CageCit", "citizen")
local n, st = person(Vector(400, 0, 0))
ok(LC.RebelMayHold(lt) and not LC.RebelMayHold(member) and not LC.RebelMayHold(cit), "Fighters and above take prisoners: not a Member, not a citizen")
ok(LC.CageFor(lt, n) == cage and LC.CageFor(member, n) == nil and LC.CageFor(cit, n) == nil, "with a cage within reach, a Fighter or above can take a citizen prisoner")
local said, close = LC.CageTake(lt, n)
ok(close == true and LC.RebelHeld[n] ~= nil and st.questLock == true and #LC.CageList(cage) == 0, "taken by the collar: on their way, not yet in", said)
n:SetPos(P0 + Vector(60, 0, 0))
LC.CageTick(CurTime())
ok(#LC.CageList(cage) == 1 and st.state == "detained" and count("caged") == 1, "at the cage they're locked in, held, and it's in the chronicle")
LC.CageTick(CurTime() + 200)
ok(st.state == "detained" and LC.RebelHeld[n] ~= nil, "and they stay held")
ok(LC.CageFor(lt, n) == nil and LC.ChairFor(lt, n) == nil, "someone held isn't taken again from the talk window")
ok(LC.CageDo(member, cage, "gate") == nil and LC.CageDo(lt, cage, "gate") ~= nil, "only a Fighter or above works the gate")
-- to the chair and back
ok(string.find(LC.CageDo(lt, cage, "chair", n) or "", "no free chair", 1, true) ~= nil and LC.RebelHeld[n] ~= nil, "no chair near: they stay in the cage")
local chair = ents.Create("lc_interrochair")
chair:SetPos(P0 + Vector(300, 0, 0))
chair:Spawn()
LC.CageDo(lt, cage, "chair", n)
ok(LC.RebelHeld[n] == nil and LC.Chairs[chair] ~= nil and LC.Chairs[chair].npc == n and st.questLock == true, "sent from the cage to the interrogation chair")
n:SetPos(chair:GetPos() + Vector(20, 0, 0))
LC.ChairTick(CurTime())
ok(LC.Chairs[chair].seated == true, "and sat in it")
lt:SetPos(chair:GetPos() + Vector(60, 0, 0))
ok(LC.ChairDo(lt, chair, "cage") ~= nil and LC.Chairs[chair] == nil and LC.RebelHeld[n] ~= nil and LC.RebelHeld[n].walking ~= nil, "from the chair, back to the cage with them")
n:SetPos(P0 + Vector(60, 0, 0))
LC.CageTick(CurTime())
ok(#LC.CageList(cage) == 1 and count("caged") == 1, "back in, and it isn't told a second time")
-- eight at most
local more = {}
for i = 1, 7 do
    local m2 = person(Vector(400, 60 * i, 0))
    LC.CageTake(lt, m2)
    m2:SetPos(P0 + Vector(60, 10 * i, 0))
    more[#more + 1] = m2
end
LC.CageTick(CurTime())
local fifth = person(Vector(400, 300, 0))
ok(#LC.CageList(cage) == 8 and LC.CageFor(lt, fifth) == nil, "eight to a cage: no room for a ninth")
more[2]:SetPos(P0 + Vector(5, 5, 0))
more[3]:SetPos(P0 + Vector(5, 5, 0))
-- let go, and time
ok(LC.CageDo(lt, cage, "free", more[1]) ~= nil and LC.RebelHeld[more[1]] == nil and LC.NPCs[more[1]].questLock == nil and LC.NPCs[more[1]].state ~= "detained", "let go: free to walk off")
ok(LC.CageReseats(cage) >= 1, "and whenever one leaves, everyone still held is stood in their own place again (nobody stuck in anybody)", LC.CageReseats(cage))
LC.RebelHeld[n].at = CurTime() - 1300
LC.CageTick(CurTime())
ok(LC.RebelHeld[n] == nil and st.state ~= "detained", "nobody is kept: questioned, and past five minutes, they're let out")
LC.RebelHeld[more[2]].at = CurTime() - 400
LC.CageTick(CurTime())
ok(LC.RebelHeld[more[2]] == nil, "with the cell's own questioning off, five minutes is five minutes for everyone")
_setcvar("lc_rebel_auto", 1)
LC.RebelHeld[more[3]].at = CurTime() - 400
LC.CageTick(CurTime())
ok(LC.RebelHeld[more[3]] ~= nil, "one not yet questioned is kept past five minutes, so everyone gets their turn")
LC.RebelHeld[more[3]].at = CurTime() - 700
LC.CageTick(CurTime())
ok(LC.RebelHeld[more[3]] == nil, "but never more than twice as long")
_setcvar("lc_rebel_auto", 0)
cage:Remove()
LC.CageGone(cage)
ok(next(LC.RebelHeld) == nil, "the cage taken away: everyone in it is free")
_setcvar("lc_rebel_cage", 0)
ok(LC.CageFor(lt, fifth) == nil, "lc_rebel_cage 0: no such option")
for _, e in ipairs({ n, fifth, more[1], more[2], more[3], more[4], more[5], more[6], more[7] }) do if IsValid(e) then LC.NPCs[e] = nil e:Remove() end end
-- the cell's own people question everyone held
_setcvar("lc_rebel_cage", 1)
_setcvar("lc_rebel_auto", 1)
C.list, C.byN, C.n = {}, {}, 0
local cage2 = ents.Create("lc_rebelcage")
cage2:SetPos(P0 + Vector(0, 2000, 0))
cage2:Spawn()
chair:SetPos(P0 + Vector(300, 2000, 0))
local a, ast = person(Vector(500, 2000, 0))
LC.CageTake(lt, a)
a:SetPos(cage2:GetPos() + Vector(60, 0, 0))
LC.CageTick(CurTime())
ok(LC.CageAutoNext(cage2, CurTime()) == false, "just locked in: left to stew a moment first")
LC.RebelHeld[a].at = CurTime() - 20
LC.ChronicleAdd({ k = "snitch", s = a.lcProfile.id, sn = "Auto Person", pred = "reported CageLt to Civil Protection", w = 2, sec = true })
ok(LC.CageAutoNext(cage2, CurTime()) == true and LC.RebelHeld[a] == nil and LC.Chairs[chair] and LC.Chairs[chair].auto == true, "with a chair free, the next one not yet questioned is taken to it")
a:SetPos(chair:GetPos() + Vector(20, 0, 0))
local near = newPlayer("CageWatcher", "citizen")
near:SetPos(chair:GetPos() + Vector(100, 0, 0))
near.chat = {}
local t1 = CurTime()
LC.ChairTick(t1)
LC.Chairs[chair].resolve = 2 -- (someone two blows will break; the toughest hold out past the four they get)
for i = 0, 70 do
    if LC.Chairs[chair] then a:SetPos(chair:GetPos() + Vector(20, 0, 0)) end
    LC.ChairTick(t1 + i)
end
local heard = table.concat(near.chat or {}, " | ")
ok(string.find(heard, "A voice from behind the lamp", 1, true) ~= nil and string.find(heard, "breaks. It comes out of them: Auto Person reported CageLt to Civil Protection.", 1, true) ~= nil,
    "a question, blows, and what they did comes out, for those near to hear", string.sub(heard, 1, 200))
ok(LC.Chairs[chair] == nil and LC.RebelHeld[a] ~= nil and LC.RebelHeld[a].questioned == true and a:Health() >= 10, "then back to the cage, questioned, in under a minute and alive")
local onBoard = false
for _, it in ipairs(LC.ChronicleFeeds().rebel) do if string.find(it.text, "admitted it in the chair", 1, true) then onBoard = true end end
ok(onBoard, "what they admitted is on the Resistance's notice board at once")
a:SetPos(cage2:GetPos() + Vector(60, 0, 0))
LC.CageTick(CurTime())
ok(LC.CageAutoNext(cage2, CurTime() + 100) == false, "nobody is questioned twice")
-- someone at the cage
_setcvar("lc_rebel_visitor", 1)
local keepG, keepV = LC.Grigori, LC.RebelVorts
LC.Grigori, LC.RebelVorts = nil, {}
ok(LC.CageVisit(cage2, CurTime()) == nil or LC.CageVisit(cage2, CurTime()) == "rebel", "nobody to send: nobody comes")
local monk = ents.Create("npc_monk")
monk:SetPos(P0 + Vector(9000, 0, 0))
monk:Spawn()
monk:SetHealth(100)
LC.Grigori = monk
cage2.lcVisit = nil
near:SetPos(cage2:GetPos() + Vector(150, 0, 0))
near.chat = {}
local t2 = CurTime()
local kind = LC.CageVisit(cage2, t2)
ok(kind == "grigori" and monk:GetPos():DistToSqr(cage2:GetPos()) < 350 * 350 and (monk.lcPreachUntil or 0) > t2, "Father Grigori is at the cage, and stays")
local said = 0
for i = 1, 120 do local _, line = LC.CageVisit(cage2, t2 + i) if line then said = said + 1 end end
ok(said >= 2 and said <= 4, "he preaches at them every 30 to 60 seconds, not without end", said)
ok(string.find(table.concat(near.chat or {}, " | "), "Father Grigori, at the cage:", 1, true) ~= nil, "and those near hear it")
monk:SetHealth(0)
local vort = ents.Create("npc_vortigaunt")
vort:SetPos(cage2:GetPos() + Vector(200, 0, 0))
vort:Spawn()
vort:SetHealth(100)
LC.RebelVorts = { [vort] = true }
cage2.lcVisit = nil
ok(LC.CageVisit(cage2, t2 + 200) == "vort", "with Father Grigori dead, a vortigaunt comes instead")
_setcvar("lc_rebel_visitor", 0)
ok(LC.CageVisit(cage2, t2 + 300) == nil, "lc_rebel_visitor 0: nobody comes")
LC.Grigori, LC.RebelVorts = keepG, keepV
LC.CageGone(cage2)
for _, e in ipairs({ a, monk, vort, chair, cage2 }) do if IsValid(e) then LC.NPCs[e] = nil e:Remove() end end
C.list, C.byN, C.n = {}, {}, 0
_setcvar("lc_rebel_auto", 0)
_setcvar("lc_rebel_cage", 0)
_setcvar("lc_chair", 0)
_setcvar("lc_chronicle", 0)
end
CageTests()
function PatdownTests()
section("The patdown, a lockpick on the cuffs, and players in the Resistance's cage")
_setcvar("lc_patdown", 1)
_setcvar("lc_rebel_cage", 1)
_setcvar("lc_rebel_visitor", 0)
_setcvar("lc_rebel_auto", 0)
local P0 = Vector(-24000, 30000, 0)
local unit = newPlayer("PatUnit", "cp")
local lt = newPlayer("PatLt", "resistance", nil, 900)
local member = newPlayer("PatMember", "resistance", nil, 150)
local cit = newPlayer("PatCit", "citizen")
local other = newPlayer("PatOther", "citizen")
for _, p in ipairs({ unit, lt, member, cit, other }) do p:SetPos(P0) end
other:SetPos(P0 + Vector(5000, 0, 0))
LC.GiveItem(cit, "lockpick", 2)
LC.GiveItem(cit, "gun_pistol", 1)
LC.GiveItem(cit, "radio", 1)
LC.GiveItem(cit, "canned_food", 1)
LC.PatdownRoll = function() return 0 end -- (everything is found, until the odds are tried below)
ok(LC.MayPatDown(unit, cit) == false, "nobody is patted down who isn't cuffed")
LC.TiePlayer(cit, unit)
ok(LC.MayPatDown(unit, cit) == true and LC.MayPatDown(lt, cit) == true, "cuffed: a unit, or a Fighter or above, may pat them down")
ok(LC.MayPatDown(member, cit) == false and LC.MayPatDown(other, cit) == false, "not a Member, and not a passer-by")
ok(LC.HasItem(cit, "lockpick", 2) and LC.HasItem(cit, "gun_pistol"), "cuffing alone takes nothing from the pockets (as it always was)")
local names = LC.PatdownDo(unit, cit)
ok(#names == 3 and not LC.HasItem(cit, "lockpick") and not LC.HasItem(cit, "gun_pistol") and not LC.HasItem(cit, "radio"), "a patdown takes the weapons, radios and tools in their pockets")
ok(LC.HasItem(cit, "canned_food"), "and leaves the rest")
ok(not LC.HasItem(unit, "lockpick"), "a unit bags it as evidence")
ok(LC.PatdownChance(LCS.Items.gun_pistol, 1) > 0.9 and LC.PatdownChance(LCS.Items.lockpick, 1) == 0.5 and LC.PatdownChance(LCS.Items.lockpick, 2) == 0.25
    and LC.PatdownChance(LCS.Items.gun_pistol, 3) > 0.9, "a gun is nearly always found; a lockpick is a toss-up, and less each time they're searched again")
LC.GiveItem(cit, "lockpick", 3)
do
    local seq = { 0.4, 0.6, 0.6 }
    LC.PatdownRoll = function() return table.remove(seq, 1) or 0.99 end
    local again = LC.PatdownDo(unit, cit)
    ok(LC.Patted[cit] == 2 and #again == 0 and LC.HasItem(cit, "lockpick", 3), "searched a second time: what was missed is hidden well (a roll that would have found one the first time doesn't now)")
    seq = { 0.1, 0.9, 0.9 }
    LC.PatdownDo(unit, cit)
    ok(LC.HasItem(cit, "lockpick", 2) and not LC.HasItem(cit, "lockpick", 3), "each lockpick is found or missed by itself: one found, two still on them")
    LC.TakeItem(cit, "lockpick", 2)
    LC.PatdownRoll = function() return 0 end
end
LC.Untie(cit, unit, true)
ok(LC.Patted[cit] == nil, "uncuffed: the next arrest starts again")
-- the Resistance keep what they find
LC.GiveItem(cit, "lockpick", 1)
LC.TiePlayer(cit, lt)
LC.PatdownDo(lt, cit)
ok(LC.HasItem(lt, "lockpick") and not LC.HasItem(cit, "lockpick"), "a rebel who pats someone down keeps what they find")
LC.TakeItem(lt, "lockpick", 1)
_setcvar("lc_patdown", 0)
LC.Patted[cit] = nil
ok(LC.MayPatDown(lt, cit) == false, "lc_patdown 0: no patdown")
_setcvar("lc_patdown", 1)
-- a lockpick on the cuffs
ok(LC.StartPickCuffs(cit) == false, "no lockpick: nothing to pick the cuffs with")
LC.GiveItem(cit, "lockpick", 3)
ok(LC.PickCuffsDone(cit) == false and LC.IsTied(cit) and LC.HasItem(cit, "lockpick", 2) and not LC.HasItem(cit, "lockpick", 3), "a captor watching sees the pick and takes it")
for _, p in ipairs({ unit, lt, member }) do p:SetPos(P0 + Vector(6000, 0, 0)) end
local rolls = { 0.9, 0.1 }
LC.PatdownRoll = function() return table.remove(rolls, 1) or 0.5 end
ok(LC.PickCuffsDone(cit) == false and LC.IsTied(cit) and LC.HasItem(cit, "lockpick", 1) and not LC.HasItem(cit, "lockpick", 2), "unwatched, a bad try can snap the pick")
_setcvar("lc_wear_uses", 0)
rolls = { 0.1 }
ok(LC.PickCuffsDone(cit) == true and not LC.IsTied(cit) and LC.HasItem(cit, "lockpick", 1), "a good try: the cuffs click open, and the pick is still theirs")
-- into the cage, walked there by a Fighter or above
local cage = ents.Create("lc_rebelcage")
cage:SetPos(P0 + Vector(0, 3000, 0))
cage:Spawn()
if not cage.IsOpen then -- (the stub's cage has no gate of its own)
    cage.IsOpen = function(c) return c.lcTestOpen == true end
    cage.SetOpen = function(c, o) c.lcTestOpen = o and true or false end
end
LC.TiePlayer(cit, lt)
cit:SetPos(cage:GetPos() + Vector(150, 0, 0))
lt:SetPos(cage:GetPos() + Vector(200, 0, 0))
LC.Tied[cit].escort = member
LC.RebelPrisonerTick(CurTime())
ok(LC.RebelHeldPly[cit] == nil, "a Member dragging someone to the cage: it isn't theirs to fill")
LC.Tied[cit].escort = lt
LC.RebelPrisonerTick(CurTime())
ok(LC.RebelHeldPly[cit] ~= nil and LC.CageCount(cage) == 1 and LC.Tied[cit].escort == nil, "a Fighter or above walks a cuffed player to the cage: in they go")
ok(#LC.CagePlayers(cage) == 1 and cit:GetNW2Entity("lc_rebel_cage_in") == cage, "they're on the cage's list")
ok(LC.HasItem(cit, "lockpick"), "nobody patted them down: the pick went in with them")
ok(LC.StartPickCage(cit) == false, "the padlock can't be picked with cuffed hands")
lt:SetPos(P0 + Vector(6000, 0, 0))
rolls = { 0.1, 0.1 }
ok(LC.PickCuffsDone(cit) == true and LC.RebelHeldPly[cit] ~= nil, "cuffs off, and still in the cage")
cit:SetPos(cage:GetPos() + Vector(400, 0, 0))
LC.RebelPrisonerTick(CurTime())
ok(cit:GetPos():DistToSqr(cage:GetPos()) < 100 * 100, "the gate is shut: there's no walking out")
ok(LC.PickCageDone(cit) == true and cage:IsOpen(), "the lockpick on the padlock: the gate swings open")
cit:SetPos(cage:GetPos() + Vector(400, 0, 0))
LC.RebelPrisonerTick(CurTime())
ok(LC.RebelHeldPly[cit] == nil and LC.CageCount(cage) == 0, "and through the open gate they're out")
-- held, then let go
LC.TiePlayer(cit, lt)
ok(LC.CagePutPlayer(cit, cage, lt) == true, "put back in")
LC.RebelHeldPly[cit].at = CurTime() - 100000
LC.RebelPrisonerTick(CurTime())
ok(LC.RebelHeldPly[cit] == nil and not LC.IsTied(cit), "their time up: let out, and the cuffs taken off")
LC.TiePlayer(cit, lt)
LC.CagePutPlayer(cit, cage, lt)
lt:SetPos(cage:GetPos() + Vector(100, 0, 0))
ok(LC.CageDo(lt, cage, "free", cit) == "You let them go." and LC.RebelHeldPly[cit] == nil and not LC.IsTied(cit), "or let go from the cage's menu")
-- the evidence locker
_setcvar("lc_evidence_locker", 1)
for i = #LC.EvidenceStock, 1, -1 do LC.EvidenceStock[i] = nil end
for id, n in pairs(LC.Inventory(cit)) do LC.TakeItem(cit, id, n) end
LC.GiveItem(cit, "lockpick", 1)
LC.TiePlayer(cit, unit)
rolls = { 0 }
LC.PatdownDo(unit, cit)
ok(LC.EvidenceTotal() == 1 and LC.EvidenceStock[1].id == "lockpick", "what a unit's patdown bags is in the evidence stock")
LC.Untie(cit, unit, true)
for _, p in ipairs({ unit, lt, member, other }) do p:SetPos(P0 + Vector(6000, 0, 0)) end
cit:SetPos(P0 + Vector(0, -4000, 0))
ok(LC.EvidenceLockerIsOpen(unit) and not LC.EvidenceLockerIsOpen(cit), "the evidence locker: open to a unit, locked to anyone else")
ok(LC.EvidenceLockerTake(cit, "lockpick") == false, "locked: nothing comes out")
LC.GiveItem(cit, "lockpick", 1)
rolls = { 0.1 }
ok(LC.EvidenceLockerPickDone(cit) == true and LC.EvidenceLockerIsOpen(cit), "a lockpick, with nobody looking: it opens")
local got = LC.EvidenceLockerTake(cit, "lockpick")
ok(got == true and LC.HasItem(cit, "lockpick", 2) and LC.EvidenceTotal() == 0, "and what was taken off them can be taken back")
LC.EvidenceAdd("radio", 1, "arrest")
ok(LC.EvidenceLockerTake(unit, "radio") == true and LC.HasItem(unit, "radio"), "a unit can help themselves too")
cit.lcEvLockerOpen = nil
for i = #LC.EvidenceStock, 1, -1 do LC.EvidenceStock[i] = nil end
LC.PatdownRoll = nil
_setcvar("lc_wear_uses", 10)
cage:Remove()
_setcvar("lc_rebel_cage", 0)
end
PatdownTests()
function RebelRuleTests()
section("The Resistance's rules and mood, kind options, executions, a player in the chair")
for k, v in pairs({ lc_rebel_rules = 1, lc_patdown = 1, lc_rebel_cage = 1, lc_rebel_visitor = 0, lc_rebel_auto = 0, lc_chair = 1, lc_chronicle = 1 }) do _setcvar(k, v) end
local C = LC.Chron
C.list, C.byN, C.n, C.seen, C.loaded = {}, {}, 0, {}, true
local function has(k) for _, e in ipairs(C.list) do if e.k == k then return e end end return nil end
local P0 = Vector(-26000, 30000, 0)
local cage = ents.Create("lc_rebelcage")
cage:SetPos(P0)
cage:Spawn()
if not cage.IsOpen then
    cage.IsOpen = function(c) return c.lcTestOpen == true end
    cage.SetOpen = function(c, o) c.lcTestOpen = o and true or false end
end
local chair = ents.Create("lc_interrochair")
chair:SetPos(P0 + Vector(300, 0, 0))
chair:Spawn()
local function person(off)
    local n, st = LC.SpawnCitizen(P0 + off)
    st.leaveAt = nil
    n.sim = false
    if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
    LC.Minds.byId[n.lcProfile.id] = LC.Minds.byId[n.lcProfile.id] or { id = n.lcProfile.id, name = n.lcProfile.name, role = "citizen" }
    return n, st
end
local lt = newPlayer("RuleLt", "resistance", nil, 900)
local ftr = newPlayer("RuleFighter", "resistance", nil, 400)
local cit = newPlayer("RuleCit", "citizen")
for _, p in ipairs({ lt, ftr, cit }) do p:SetPos(P0 + Vector(100, 0, 0)) end
-- (Resistance players left by earlier tests would outrank ours: out of the way for this unit)
local others = {}
for _, p in ipairs(player.GetAll()) do
    if p ~= lt and p ~= ftr and p:GetNW2String("lcf_faction", "") == "resistance" then others[#others + 1] = p p:SetNW2String("lcf_faction", "citizen") end
end
local R = LC.RebelRules
R.brutal, R.execute, R.sympathizers, R.priority, R.mood = true, false, false, "lielow", ""
LC.RebelMood.fear, LC.RebelMood.anger = 0, 0
-- the leader and the clipboard
ok(LC.RebelChief() == lt and LC.RebelChief(lt) == ftr, "the highest-ranked Resistance player on is the leader")
ok(LC.RebelRuleSet(ftr, "brutal") == false and R.brutal == true, "the clipboard is the leader's alone")
ok(LC.RebelRuleSet(lt, "brutal") == true and R.brutal == false and LC.RebelNoBlows() == true, "the leader unticks a box: nobody lays a hand on prisoners")
ok(string.find(LC.RebelBoardLines()[2], "nobody lays a hand", 1, true) ~= nil, "and it is written on the Resistance's board")
LC.RebelRuleSet(lt, "brutal")
LC.RebelRuleSet(lt, "priority")
ok(R.priority == "attack", "the priority moves to the next one")
ok(LC.RebelAtmosphere() == "calm", "nothing has happened to the cell: calm")
LC.RebelMoodPush(4, 0)
ok(LC.RebelAtmosphere() == "wary", "losses make it wary")
LC.RebelMoodPush(5, 0)
ok(LC.RebelAtmosphere() == "desperate" and LC.RebelHoldFactor() == 0.5, "more, and it is desperate: prisoners are let go sooner")
LC.RebelMoodPush(0, 7)
ok(LC.RebelAtmosphere() == "vengeful" and LC.RebelAutoHits() == 5 and LC.RebelHoldFactor() == 2, "wronged enough, it is vengeful: harder questions, longer in the cage")
ok(string.find(LC.RebelBoardLines()[1], "blood", 1, true) ~= nil, "the board says so, in words")
LC.RebelMoodTick()
ok(LC.RebelMood.anger < 7, "it fades with time")
LC.RebelRuleSet(lt, "mood")
ok(R.mood == "calm" and LC.RebelAtmosphere() == "calm", "or the leader sets the mood")
R.mood = ""
LC.RebelMood.fear, LC.RebelMood.anger = 0, 0
-- a citizen in the cage: what they hide
local n, st = person(Vector(400, 0, 0))
LC.CageTake(lt, n)
n:SetPos(cage:GetPos() + Vector(60, 0, 0))
LC.CageTick(CurTime())
local rolls = {}
LC.PatdownRoll = function() return table.remove(rolls, 1) or 0.99 end
do
    local reb = { role = "rebel" }
    rolls = { 0.5, 0.99 }
    ok(LC.NPCHides(nil, reb).picks == 3, "a rebel almost always carries a lockpick, sometimes several")
    local sym, plain = { role = "citizen", rebel = true }, { role = "citizen" }
    rolls = { 0.3, 0.0, 0.3 }
    ok(LC.NPCHides(nil, sym).picks == 1 and LC.NPCHides(nil, plain).picks == 0, "a sympathizer often does; an ordinary citizen seldom")
end
st.lcHidden = { picks = 2 }
st.lcHideFor = LC.RebelHeld[n]
ok(LC.MayPatDownNPC(lt, n) == true and LC.MayPatDownNPC(cit, n) == false, "a held citizen can be patted down by a Fighter or above")
rolls = { 0.4, 0.7 }
local found = LC.PatdownNPC(lt, n)
ok(#found == 1 and LC.HasItem(lt, "lockpick") and st.lcPatted == 1 and st.lcHidden.picks == 1, "one lockpick is found and kept; the other is missed")
rolls = { 0.1 }
LC.PatdownNPC(lt, n)
ok(st.lcHidden.picks == 0, "a second search turns up the other")
LC.RebelHeld[n].at = CurTime() - 200
ok(LC.NPCSlipTick(CurTime()) == 0 and LC.RebelHeld[n] ~= nil, "searched: they stay where they are")
local n2, st2 = person(Vector(420, 0, 0))
LC.CageTake(lt, n2)
n2:SetPos(cage:GetPos() + Vector(60, 0, 0))
LC.CageTick(CurTime())
st2.lcHidden = { picks = 1 }
st2.lcHideFor = LC.RebelHeld[n2]
LC.RebelHeld[n2].at = CurTime() - 200
ok(LC.NPCSlipTick(CurTime()) == 1 and LC.RebelHeld[n2] == nil and has("escaped") ~= nil, "nobody searched this one: they pick the padlock and are gone")
-- cuffed, with a pick nobody found: they work at the cuffs when nobody is looking
do
    local c1, cst = person(Vector(3000, 0, 0))
    LC.SetState(c1, cst, "detained")
    c1:SetNW2Bool("lc_cuffed", true)
    LC.NPCCustody[c1] = { st = cst, leader = lt }
    cst.lcHidden, cst.lcPatted, cst.lcCuffSecs = { picks = 1 }, nil, nil
    lt:SetPos(c1:GetPos() + Vector(-100, 0, 0))
    lt:SetEyeAngles(Angle(0, 0, 0))
    ok(LC.NPCCuffsWatched(c1, LC.NPCCustody[c1]) == lt, "the one leading a cuffed citizen is looking at them")
    for _ = 1, 15 do LC.NPCCuffTick(CurTime()) end
    ok(cst.lcCuffSecs == nil and cst.state == "detained", "watched: their hands stay still")
    lt:SetPos(c1:GetPos() + Vector(100, 0, 0)) -- (walking ahead of them now, their back turned)
    ok(LC.NPCCuffsWatched(c1, LC.NPCCustody[c1]) == nil, "the captor looks away")
    rolls = {}
    for _ = 1, 9 do LC.NPCCuffTick(CurTime()) end
    ok((cst.lcCuffSecs or 0) >= 18 and cst.state == "detained", "unwatched, they work at the cuffs")
    rolls = { 0.1 }
    ok(LC.NPCCuffTick(CurTime()) == 1 and cst.state ~= "detained" and not c1:GetNW2Bool("lc_cuffed", false) and cst.lcHidden.picks == 0, "and after long enough the cuffs are off, and they run")
    local c2, cst2 = person(Vector(3200, 0, 0))
    LC.SetState(c2, cst2, "detained")
    LC.NPCCustody[c2] = { st = cst2, leader = lt }
    cst2.lcHidden, cst2.lcPatted = { picks = 0 }, 1
    for _ = 1, 15 do LC.NPCCuffTick(CurTime()) end
    ok(cst2.lcCuffSecs == nil and cst2.state == "detained", "searched and nothing left on them: nothing to work with")
    LC.NPCCustody[c1], LC.NPCCustody[c2] = nil, nil
    for _, e in ipairs({ c1, c2 }) do if IsValid(e) then LC.NPCs[e] = nil e:Remove() end end
    lt:SetPos(P0 + Vector(100, 0, 0))
end
-- kind options in the chair
LC.RebelHeld[n].at = CurTime()
LC.CageDo(lt, cage, "chair", n)
n:SetPos(chair:GetPos() + Vector(20, 0, 0))
LC.ChairTick(CurTime())
local s = LC.Chairs[chair]
ok(s ~= nil and s.seated == true, "to the chair")
s.resolve = 3
ok(LC.ChairDo(lt, chair, "food") == "You've nothing to give them.", "nothing in your pockets to give")
LC.GiveItem(lt, "canned_food", 1)
LC.ChairDo(lt, chair, "food")
ok(s.fed == true and s.resolve == 2 and not LC.HasItem(lt, "canned_food"), "food given: they soften a little")
if n.lcProfile then n.lcProfile.traits = nil end
rolls = { 0.0 }
local was = s.resolve
local t = LC.Psy and LC.Psy.Traits and n.lcProfile and LC.Psy.Traits(n.lcProfile) or {}
LC.ChairDo(lt, chair, "talk")
ok(((t.pride or 0) > 0.4 and s.resolve == was) or s.resolve == was - 1, "talking without blows works on those who aren't too proud")
st.rebel = false
rolls = { 0.0, 0.99 }
LC.ChairDo(lt, chair, "recruit")
ok(st.rebel == true and has("recruited") ~= nil, "asked to join after being treated well: they come over")
ok(LC.ChairDo(lt, chair, "recruit") == "You've had their answer.", "asked once")
-- executions
ok(LC.RebelExecDo(ftr, n, "execute") == "You'd need permission for that. Ask, or do it without.", "a Fighter has no leave to execute")
LC.Chairs[chair].asker = ftr
R.execute = false
LC.ExecAskLeave(ftr, n)
ok(LC.ExecAsks[ftr] ~= nil, "they ask leave, and it goes to the Lieutenant")
LC.ExecAnswer(lt, ftr, false)
ok(not LC.ExecHasLeave(ftr, n) and ftr.lcExecRefused == n, "refused")
LC.ExecAskLeave(ftr, n)
LC.ExecAnswer(lt, ftr, true)
ok(LC.ExecHasLeave(ftr, n) == true, "or given")
LC.Execute(ftr, n)
ok((not IsValid(n) or n:Health() <= 0) and has("executed") ~= nil and LC.ExecJudging == nil, "with permission: done, known, and nobody answers for it")
ok(has("against_rules") ~= nil, "against the cell's own rules, though (prisoners are let go), and the board carries that")
LC.ChairTick(CurTime())
-- without leave
local n3, st3 = person(Vector(440, 0, 0))
LC.CageTake(ftr, n3)
n3:SetPos(cage:GetPos() + Vector(60, 0, 0))
LC.CageTick(CurTime())
ok(LC.CageDo(ftr, cage, "execnoleave", n3) ~= nil and LC.ExecJudging ~= nil and LC.ExecJudging.judge == lt, "a Fighter does it without leave: the Lieutenant has to answer")
local rk = ftr:GetNW2Int("lcf_rank", 1)
LC.ExecJudged(lt, "demote")
ok(ftr:GetNW2Int("lcf_rank", 1) == rk - 1 and has("judged") ~= nil, "broken in rank for it")
ftr:SetPData("lcf_xp_resistance", 400)
LC.AddXP(ftr, 0, "test")
-- a player prisoner: the chair, and the two kinds of death
LC.TiePlayer(cit, lt)
LC.CagePutPlayer(cit, cage, lt)
local keyC = LC.MindsWhoKey(cit)
LC.ChronicleAdd({ k = "did:sabotage", s = keyC, sn = "RuleCit", pred = "cut the wires at the checkpoint", w = 3, sec = true })
lt:SetPos(chair:GetPos() + Vector(60, 0, 0))
ok(LC.CageDo(lt, cage, "chair", cit) == "To the chair with them." and LC.ChairPlayerOf(cit) ~= nil and LC.RebelHeldPly[cit] == nil, "a held player is sent to the chair")
ok(LC.ChairNear(cage:GetPos()) == nil, "the chair is taken")
LC.ChairPlayerDo(lt, chair, "seen")
ok(LC.ChairPlayerOf(cit).q == "seen", "asked: the answer is the prisoner's")
ok(LC.ChairPlayerAnswer(cit, "silent") ~= nil and LC.ChairPlayerOf(cit).q == nil, "they say nothing")
LC.ChairPlayerDo(lt, chair, "done")
local truth = LC.ChairPlayerAnswer(cit, "truth")
ok(string.find(truth or "", "cut the wires", 1, true) ~= nil, "the truth is what the chronicle holds about them", truth)
LC.ChairPlayerDo(lt, chair, "done")
rolls = { 0.99 }
local lie = LC.ChairPlayerAnswer(cit, "lie")
ok(string.find(lie or "", "It comes out of them", 1, true) ~= nil and string.find(lie, "cut the wires", 1, true) == nil, "a lie sounds the same, and isn't")
local hp = cit:Health()
LC.ChairPlayerDo(lt, chair, "hit")
ok(cit:Health() < hp and LC.ChairPlayerOf(cit).hits == 1, "a blow hurts")
LC.ChairPlayerDo(lt, chair, "cage")
ok(LC.ChairPlayerOf(cit) == nil and LC.RebelHeldPly[cit] ~= nil, "back to the cage")
local final
hook.Add("LivingCityExecuted", "RuleTest", function(_, _, _, f) final = f end)
rolls = { 0.9 }
ftr:SetPos(cage:GetPos() + Vector(100, 0, 0))
LC.CageDo(ftr, cage, "execnoleave", cit)
ok(final == false and LC.RebelHeldPly[cit] == nil, "a player killed without leave: an ordinary death, two times in three")
LC.ExecJudged(nil, "stand")
cit:Spawn()
LC.TiePlayer(cit, lt)
LC.CagePutPlayer(cit, cage, lt)
lt:SetPos(cage:GetPos() + Vector(100, 0, 0))
LC.CageDo(lt, cage, "execute", cit)
ok(final == true, "a proper execution, by a Lieutenant: the character's death")
hook.Remove("LivingCityExecuted", "RuleTest")
cit.lcEndOfLife = nil
LC.ExecJudging, LC.PatdownRoll = nil, nil
R.brutal, R.execute, R.sympathizers, R.priority, R.mood = true, false, false, "lielow", ""
LC.RebelMood.fear, LC.RebelMood.anger = 0, 0
for _, p in ipairs(others) do if IsValid(p) then p:SetNW2String("lcf_faction", "resistance") end end
LC.CageGone(cage)
for _, e in ipairs({ n, n2, n3, chair, cage }) do if IsValid(e) then LC.NPCs[e] = nil e:Remove() end end
C.list, C.byN, C.n = {}, {}, 0
for k in pairs({ lc_rebel_cage = 1, lc_chair = 1, lc_chronicle = 1 }) do _setcvar(k, 0) end
end
RebelRuleTests()

function BrainTests()
section("The director and free talk: a hosted model, on a short list")
local Psy = LC.Psy
_setcvar("lc_minds", 1) _setcvar("lc_minds_act", 1) _setcvar("lc_minds_show", 0)
_setcvar("lc_brain", 1) _setcvar("lc_brain_talk", 1) _setcvar("lc_director", 2) _setcvar("lc_brain_daily", 1500)
LC.Minds.byId, LC.Minds.order, LC.Minds.idx, LC.Minds.buf, LC.Minds.counts, LC.Minds.loaded = {}, {}, 0, {}, {}, true
local B = LC.Brain
B.lastTalk, B.minute, B.backOff, B.today, B.day, B.decisions, B.moved, B.talks, B.inFlight, B.useLoaded = {}, {}, nil, 0, os.date("%Y-%m-%d"), {}, {}, {}, 0, true
local reqs, answer = {}, nil
local realHTTP = LC.BrainHTTP
LC.BrainHTTP = function(req)
    reqs[#reqs + 1] = req
    if not answer then return end
    local code, body = answer(req)
    if code then req.success(code, body) else req.failed("timed out") end
end
local function reply(tbl, stop)
    return 200, LC.BrainJSON({ content = { { type = "text", text = LC.BrainJSON(tbl) } }, stop_reason = stop or "end_turn",
        usage = { input_tokens = 100, output_tokens = 20 } })
end
local T0 = Vector(-41000, 29000, 0)
local n, st = LC.SpawnCitizen(T0)
st.leaveAt = nil n.sim = false
if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
st.state = "idle"
local who = n.lcProfile.name
local m = LC.MindOf(n.lcProfile)
Psy.State(m)
local ply = newPlayer("BrainTalker", "citizen")
ply:SetPos(T0 + Vector(80, 0, 0))
ply.chat = {}
ply.GetEyeTrace = function() return { Entity = n } end
local function heard(text) for _, l in ipairs(ply.chat) do if string.find(l, text, 1, true) then return true end end return false end

-- no key: nothing at all
LC.BrainSetKey("")
ok(LC.BrainHeard(ply, "say", "Hello there") == false and LC.DirectorLook(CurTime()) == false and #reqs == 0, "no key: nothing is asked, nothing changes")
LC.BrainSetKey("sk-test-123")
ok(_files["livingcity/brain_key.txt"] == "sk-test-123" and LC.BrainHasKey(), "the key is kept on the server, in data/livingcity/brain_key.txt")
ok(LC.BrainJSON({ max_tokens = 1000, a = { "x", "y" }, s = "q\"\n" }) == '{"a":["x","y"],"max_tokens":1000,"s":"q\\"\\n"}', "requests are written with whole numbers and safe strings")
ok(LC.BrainClean("one\226\128\148two\nthree") == "one, two three", "what the model writes is made one clean line, with no long dashes")

-- free talk
answer = function() return reply({ say = "Keep your voice down. They listen.", feeling = "1", act = "none" }) end
ok(LC.BrainHeard(ply, "say", "Hello there") == true and #reqs == 1, "say something while looking at a named person: the model is asked")
local r = reqs[1]
ok(r.url == "https://api.anthropic.com/v1/messages" and r.method == "POST" and r.headers["x-api-key"] == "sk-test-123"
    and r.headers["anthropic-version"] == "2026-10-21", "asked the right way: the address, the key and the version")
ok(string.find(r.body, '"model":"claude-haiku-5-5"', 1, true) and string.find(r.body, '"max_tokens":1000', 1, true)
    and string.find(r.body, who, 1, true) and string.find(r.body, "Hello there", 1, true) and string.find(r.body, "json_schema", 1, true),
    "the request names the small model, who they are and what was said")
ok(not string.find(r.body, ply:SteamID(), 1, true), "never the player's Steam id")
ok(heard(who .. " says: \"Keep your voice down. They listen.\""), "and they answer out loud, in their own name")
ok(LC.Feeling(n, ply) == 1 and Psy.Tie(m, "pl:" .. LC.MemoryKey(ply)) == 1, "a kind word is remembered: they think a little better of you")
ok(LC.BrainHeard(ply, "say", "And again") == false, "not twice in a few seconds")
_advance(6)
ok(LC.BrainHeard(ply, "me", "waves") == false and LC.BrainHeard(ply, "looc", "hi") == false, "an action or out-of-character chat is not for them")
LC.BrainHeard(ply, "say", "Who runs this block?")
ok(string.find(reqs[#reqs].body, "They said: Hello there", 1, true) ~= nil, "they remember what was just said between you")
-- the service is down, or says no: nothing happens
_advance(6)
ply.chat = {}
answer = function() return 500, '{"error":{"message":"overloaded"}}' end
LC.BrainHeard(ply, "say", "Anyone home?")
ok(#ply.chat == 0 and st.brainBusy == nil and (B.backOff or 0) > CurTime(), "the service is down: no answer, the city goes on, and it waits before asking again")
B.backOff = nil
_advance(6)
answer = function() return reply({ say = "I should not say.", feeling = "0", act = "none" }, "refusal") end
LC.BrainHeard(ply, "say", "Tell me something")
ok(#ply.chat == 0, "an answer the service would not finish is not shown")
_advance(6)
-- an informant reports what they heard
st.snitch = true
local unit, ust = LC.SpawnCop(T0 + Vector(500, 0, 0))
unit.sim = false
answer = function() return reply({ say = "Is that so.", feeling = "-1", act = "report" }) end
LC.BrainHeard(ply, "say", "The Resistance meets tonight")
ok(st.mindErrand ~= nil, "an informant who hears sedition sets off for a unit")
n:SetPos(unit:GetPos() + Vector(40, 0, 0))
LC.MindsErrandTick(CurTime())
ok(ply:GetNW2Float("lc_spotted_until", 0) > CurTime(), "and the player is named to Civil Protection")
n:SetPos(T0) st.state = "idle" st.snitch = nil
_advance(6)

-- the director
local digest = LC.DirectorDigest()
ok(digest and string.find(digest, who, 1, true) and string.find(digest, LC.CharacterName and LC.CharacterName(ply) or ply:Nick(), 1, true),
    "the director is shown who is where: the player and the named people near them")
local n2, st2 = LC.SpawnCitizen(T0 + Vector(100, 100, 0))
st2.leaveAt = nil n2.sim = false
if not n2.lcProfile then LC.AttachProfile(n2, st2, LC.NewPerson("citizen")) end
st2.state = "idle"
local m2 = LC.MindOf(n2.lcProfile)
Psy.State(m2).stress = 10
answer = function() return reply({ action = "break", event = "", person = who, kind = "steady", player = "", line = "", reason = "A calm word before the sweep." }) end
ok(LC.DirectorLook(CurTime()) == true and #B.decisions == 1 and string.find(B.decisions[1].text, "steady", 1, true) ~= nil, "it picks a named person to act, and it is written down", B.decisions[1] and B.decisions[1].text)
ok(Psy.State(m2).stress == 7, "and they do: the people near are steadied")
local ok2, why = LC.DirectorApply({ action = "break", person = who, kind = "tantrum" }, CurTime())
ok(ok2 == false, "the same person is not moved again so soon", why)
B.moved = {}
ok2, why = LC.DirectorApply({ action = "break", person = who, kind = "brutal" }, CurTime())
ok(ok2 == false, "a citizen cannot be told to do what only a unit does", why)
ok2, why = LC.DirectorApply({ action = "break", person = "Nobody Atall", kind = "steady" }, CurTime())
ok(ok2 == false, "a name it made up is refused", why)
ok2, why = LC.DirectorApply({ action = "event", event = "lockdown" }, CurTime())
ok(ok2 == false, "an event off its list is refused", why)
-- an approach
ply.chat = {}
st.state = "idle"
ok2, why = LC.DirectorApply({ action = "approach", person = who, player = LC.CharacterName and LC.CharacterName(ply) or ply:Nick(), line = "You. They were asking about you at the checkpoint." }, CurTime())
ok(ok2 == true and st.mindErrand ~= nil, "an approach: the citizen sets off for the player", why)
n:SetPos(ply:GetPos() + Vector(40, 0, 0))
LC.MindsErrandTick(CurTime())
ok(heard("They were asking about you at the checkpoint."), "and says the line when they get there")
n:SetPos(T0) st.state = "idle"
-- watching only
_setcvar("lc_director", 1)
B.moved = {}
Psy.State(m2).stress = 10
answer = function() return reply({ action = "break", event = "", person = who, kind = "steady", player = "", line = "", reason = "Again." }) end
LC.DirectorLook(CurTime())
ok(Psy.State(m2).stress == 10 and string.find(B.decisions[#B.decisions].text, "would have", 1, true) == 1, "lc_director 1: it only writes down what it would have done")
_setcvar("lc_director", 2)
-- her office, with nobody in it (LC.AdminDecree, LC.AdminLook)
section("The city's own Administrator: the model in her office")
_setcvar("lc_brain_admin", 1)
LC.AdminNPC.lcAdminNext, LC.AdminNPC.lcAdminDaily = nil, nil
B.decrees, B.adminBusy = {}, nil
local human = LC.HumanAdministrator
LC.HumanAdministrator = function() return nil end -- (whoever an earlier test left in the post)
local wasEvent = LC.Event
if LC.Event then LC.EndEvent(true) end
local notes = {}
local realNotice = LC.Notice
LC.Notice = function(p, kind, title, text) notes[#notes + 1] = tostring(title) .. ": " .. tostring(text) end
local function noted(text) for _, l in ipairs(notes) do if string.find(l, text, 1, true) then return true end end return false end
local pname = LC.CharacterName and LC.CharacterName(ply) or ply:Nick()
local state = LC.AdminOfficeState()
ok(string.find(state, "event ready", 1, true) ~= nil and string.find(state, "left today 5", 1, true) ~= nil, "her office says what it can do now", state)
answer = function() return reply({ decree = "rations", event = "", rations = "generous", prices = "", job = "", player = "", words = "A city that works is a city that eats.", reason = "Hunger is feeding the unrest." }) end
ok(LC.AdminLook(CurTime()) == true and LC.AdminState.rations == "generous" and LC.AdminState.rationsUntil > CurTime(), "with nobody in the post she decrees: generous rations for the hour")
ok(noted("Rations are increased for the hour") and noted("A city that works is a city that eats."), "announced as the City Administrator's, with her own words")
ok(string.find(reqs[#reqs].body, "Your office:", 1, true) ~= nil and string.find(reqs[#reqs].body, pname, 1, true) ~= nil, "she is shown the city and what her office can do")
ok(#B.decrees == 1 and string.find(B.decrees[1].text, "rations generous", 1, true) == 1, "and it is written down", B.decrees[1] and B.decrees[1].text)
local okD, whyD = LC.AdminApply({ decree = "rations", rations = "austere", words = "" }, CurTime())
ok(okD == false and LC.AdminState.rations == "generous", "the same waits as a player in the post: not again for 15 minutes", whyD)
local stand = {}
local realStanding = LC.AddStanding
LC.AddStanding = function(p, n, why) stand[#stand + 1] = { p, n, why } end
okD, whyD = LC.AdminApply({ decree = "censure", player = pname, words = "Let this be remembered." }, CurTime())
ok(okD == true and #stand == 1 and stand[1][1] == ply and stand[1][2] == -15, "a censure: the player's civil standing falls by 15", whyD)
okD, whyD = LC.AdminApply({ decree = "commend", player = "Nobody Atall", words = "" }, CurTime())
ok(okD == false and #stand == 1, "a name she made up is refused", whyD)
LC.AddStanding = realStanding
okD, whyD = LC.AdminApply({ decree = "pardon", player = pname, words = "" }, CurTime())
ok(okD == false, "no pardon for someone who is not wanted", whyD)
okD, whyD = LC.AdminApply({ decree = "prices", prices = "lower", words = "" }, CurTime())
ok(okD == true and LC.AdminState.priceMul == 0.85, "prices lowered: 85% for the hour", whyD)
-- a player in the post: she is out of it
LC.HumanAdministrator = function() return ply end
local nreq = #reqs
ok(LC.AdminLook(CurTime()) == false and #reqs == nreq and LC.AdminDecree("rations", "normal") == false, "a player holds the post: the model is out of the office")
LC.HumanAdministrator = function() return nil end
local wasSocio = LC.Socio
LC.Socio = "black"
ok(LC.AdminLook(CurTime()) == false and #reqs == nreq, "during the collapse she is left to its own script")
LC.Socio = wasSocio
_setcvar("lc_brain_admin", 0)
ok(LC.AdminLook(CurTime()) == false and #reqs == nreq, "lc_brain_admin 0: the office stays empty")
_setcvar("lc_brain_admin", 1)
LC.Notice = realNotice
LC.HumanAdministrator = human
LC.AdminState.rations, LC.AdminState.rationsUntil, LC.AdminState.priceMul, LC.AdminState.priceUntil = nil, 0, 1, 0
LC.AdminNPC.lcAdminNext, LC.AdminNPC.lcAdminDaily = nil, nil
-- the day's limit
_setcvar("lc_brain_daily", 1)
local before = #reqs
ok(LC.DirectorLook(CurTime()) == false and #reqs == before, "past the day's limit nothing more is asked")
_setcvar("lc_brain_daily", 1500)
-- the report never shows the key
local shows = false
for _, l in ipairs(LC.BrainReport()) do if string.find(l, "sk-test-123", 1, true) then shows = true end end
ok(not shows and #LC.BrainReport() >= 2, "the debug report says how much was asked, and never shows the key")
LC.BrainSetKey("")
ok(_files["livingcity/brain_key.txt"] == nil and not LC.BrainHasKey(), "saving an empty key clears it")
LC.BrainHTTP = realHTTP
LC.MindsActs.errands = {}
for _, e in ipairs({ n, n2, unit, ply }) do if IsValid(e) then e:Remove() end end
_setcvar("lc_minds_act", 0) _setcvar("lc_minds", 0)
end
BrainTests()

function CollapseOwnTests()
section("The collapse: the city's own Administrator refuses the G-Man one to three times")
local human = {}
for _, p in ipairs(player.GetAll()) do if p:GetNW2String("lcf_faction", "") == "admin" then human[#human + 1] = p p:SetNW2String("lcf_faction", "citizen") end end
local roll, how = LC.CollapseNpcRoll, LC.CollapseNpcHow
local seen = {}
local realNotice = LC.Notice
LC.Notice = function(p, kind, title, text) seen[#seen + 1] = tostring(title) end
local function saw(title) for _, l in ipairs(seen) do if l == title then return true end end return false end
if LC.CollapseActive() then LC.CollapseResolve("test") end
-- once: she gives in when he comes back the first time
LC.CollapseNpcRoll = function() return 1 end
LC.CollapseNpcHow = function() return 0.1 end
ok(LC.CollapseBegin("test") and LC.CollapseStage() == "offer", "BLACK with nobody in the post: he goes to the city's own Administrator")
_run(4)
ok(LC.CollapseStage() == "refused", "she refuses him the first time, always")
seen = {}
ok(LC.CollapseNext() == true and not LC.CollapseActive() and saw("The Administrator steps down"), "one refusal in her: asked again, she steps down, and the city calms")
ok(LC.Chaos == 0, "the chaos is gone")
-- twice: his first step happens, then she ends it
LC.CollapseNpcRoll = function() return 2 end
LC.CollapseNpcHow = function() return 0.9 end
LC.CollapseBegin("test")
_run(4)
LC.CollapseNext()
ok(LC.CollapseActive() and LC.CollapseStage() == "refused", "two refusals in her: she refuses again, and his first step comes")
seen = {}
LC.CollapseNext()
ok(not LC.CollapseActive() and saw("The Administrator is dead"), "asked a third time she ends it herself")
-- three times: it goes on to her last stand, as it always did
LC.CollapseNpcRoll = function() return 3 end
LC.CollapseBegin("test")
_run(4)
LC.CollapseNext() LC.CollapseNext() LC.CollapseNext()
ok(LC.CollapseActive() and LC.CollapseStage() == "refused", "three refusals in her: he stops asking, and his steps go on toward her last stand", LC.CollapseStage())
LC.CollapseResolve("test")
ok(not LC.CollapseActive(), "(put back)")
LC.Notice = realNotice
LC.CollapseNpcRoll, LC.CollapseNpcHow = roll, how
for _, p in ipairs(human) do if IsValid(p) then p:SetNW2String("lcf_faction", "admin") end end
end
CollapseOwnTests()

function VoiceTests()
section("Her voice: the city's own Administrator's decrees, spoken (off until a key and a voice id are set)")
local V = LC.Voice
V.key, V.id, V.backOff, V.today, V.day, V.useLoaded, V.calls, V.chars = nil, nil, nil, 0, os.date("%Y-%m-%d"), true, 0, 0
_files["livingcity/voice_key.txt"], _files["livingcity/voice_id.txt"] = nil, nil
local reqs, answer = {}, nil
local realHTTP = LC.VoiceHTTP
LC.VoiceHTTP = function(req)
    reqs[#reqs + 1] = req
    if not answer then return end
    local code, body = answer(req)
    if code then req.success(code, body) else req.failed("timed out") end
end
local mp3 = string.rep("x", 9000)
local function clips() local n, last = 0, nil for _, m in ipairs(net.sent) do if m.name == "lc_voice_clip" then n, last = n + 1, m end end return n, last end
local quiet = LC.PAQuiet
LC.PAQuiet = function() return 99 end
ok(GetConVar("lc_voice"):GetInt() == 0, "off by default")
_setcvar("lc_voice", 1)
net.sent = {}
ok(LC.VoiceSpeak("Order is kindness.", "The City Administrator") == false and #reqs == 0, "no key and no voice id: nothing is asked")
local hasKey, hasId = LC.VoiceSet("el-key-1", "", false)
ok(hasKey and not hasId and not LC.VoiceReady(), "a key alone is not enough")
hasKey, hasId = LC.VoiceSet("", "Voice123abc", false)
ok(hasKey and hasId and LC.VoiceReady() and _files["livingcity/voice_key.txt"] == "el-key-1" and _files["livingcity/voice_id.txt"] == "Voice123abc",
    "the key and the voice id are kept on the server; a box left empty keeps what was saved")
LC.VoiceSet("", "bad/id?x", false)
ok(LC.Voice.id == "Voice123abc", "a voice id that is not letters and digits is not taken")
answer = function() return 200, mp3 end
ok(LC.VoiceSpeak("Order is kindness.", "The City Administrator") == true and #reqs == 1, "with both set and lc_voice on, her sentence is asked for")
local r = reqs[1]
ok(r.url == "https://api.elevenlabs.io/v1/text-to-speech/Voice123abc?output_format=mp3_22050_32" and r.method == "POST" and r.headers["xi-api-key"] == "el-key-1",
    "asked the right way: the voice in the address, the key in its header", r.url)
ok(string.find(r.body, '"text":"Order is kindness."', 1, true) ~= nil and string.find(r.body, '"model_id":"eleven_v4_turbo"', 1, true) ~= nil, "the request carries her words and the model", r.body)
local n, clip = clips()
ok(n == 1 and clip.data[2] == "The City Administrator" and clip.data[3] == #mp3 and clip.data[4] == mp3, "and the sound is sent to the players to play")
-- it waits for the PA
net.sent = {}
local q = -5
LC.PAQuiet = function() return q end
LC.VoiceSpeak("Wait your turn.", "The City Administrator")
ok(clips() == 0, "while the PA is speaking it waits")
q = 99
_run(2)
ok(clips() == 1, "and speaks once the PA is quiet")
LC.PAQuiet = function() return 99 end
-- problems: nothing is played
net.sent = {}
answer = function() return 401, '{"detail":"bad key"}' end
LC.VoiceSpeak("Nobody hears this.", "The City Administrator")
ok(clips() == 0 and (V.backOff or 0) > CurTime() and V.lastError ~= nil, "the service says no: nothing is played, and it waits before asking again")
V.backOff = nil
answer = function() return 200, string.rep("x", 70000) end
LC.VoiceSpeak("Too long to send.", "The City Administrator")
ok(clips() == 0, "a sound too big for one message is not sent")
-- the day's limit
answer = function() return 200, mp3 end
_setcvar("lc_voice_daily", 1)
local before = #reqs
ok(LC.VoiceSpeak("Past the limit.", "The City Administrator") == false and #reqs == before, "past the day's limit nothing more is asked")
_setcvar("lc_voice_daily", 200)
-- off
_setcvar("lc_voice", 0)
ok(LC.VoiceSpeak("Off.", "The City Administrator") == false and #reqs == before, "lc_voice 0: nothing is asked")
-- the test button works with it off, for the one who asked
local adminp = newPlayer("VoiceTester", "citizen")
net.sent = {}
V.today = 0
ok(LC.VoiceTest(adminp) == true, "the panel's test asks even while it is off")
n, clip = clips()
ok(n == 1 and clip.to == adminp, "and only the one who pressed it hears her")
local shows = false
for _, l in ipairs(LC.VoiceReport()) do if string.find(l, "el-key-1", 1, true) then shows = true end end
ok(not shows, "the debug report never shows the key")
LC.VoiceSet("", "", true)
ok(not LC.VoiceReady() and _files["livingcity/voice_key.txt"] == nil and _files["livingcity/voice_id.txt"] == nil, "clearing removes both")
LC.VoiceHTTP, LC.PAQuiet = realHTTP, quiet
if IsValid(adminp) then adminp:Remove() end
end
VoiceTests()

function LinesTests()
section("What named people say, recorded: a small bank for free talk, the director and the minds' breaks")
LC.VoiceForce = "own" -- (the recorded voice first; who gets which voice is further down)
local nCit, nOpen, bad = 0, 0, nil
for id, l in pairs(LC.StreetLines) do
    if string.sub(id, 1, 10) ~= "say_small_" then nCit = nCit + 1 end -- (small talk, 12 November, counted apart)
    if string.sub(id, 1, 9) == "say_open_" then nOpen = nOpen + 1 end
    if string.sub(id, 1, 4) ~= "say_" or type(l[1]) ~= "string" or #l[1] > 70 or l[2] == nil or string.find(l[1], "\226\128\148", 1, true) then bad = id end
end
ok(nCit >= 60 and nCit <= 90 and nOpen == 6 and not bad, "a citizen's bank: under 90 short lines, six of them openers, each with when it is said", tostring(nCit) .. " " .. tostring(bad))
local nUnit = 0
for id, l in pairs(LC.UnitLines) do nUnit = nUnit + 1 if string.sub(id, 1, 5) ~= "unit_" or #l[1] > 60 then bad = id end end
ok(nUnit >= 12 and nUnit <= 24 and not bad, "a unit's bank: a couple of dozen at most", nUnit)
local noClip
for id, l in pairs(LC.UnitLines) do if type(l[4]) ~= "table" or #l[4] == 0 then noClip = id end end
ok(noClip == nil, "every one of a unit's lines is one of Half-Life 2's own Civil Protection clips: nothing to record", tostring(noClip))
ok(LC.LineValid("citizen", "say_dunno") and not LC.LineValid("citizen", "unit_move") and LC.LineValid("cop", "unit_move") and not LC.LineValid("cop", "say_dunno")
    and not LC.LineValid("citizen", "say_open_listen") and LC.LineValid("citizen", "say_open_listen", true) and not LC.LineValid("citizen", ""),
    "each kind of person has their own lines, and an opener only counts as an opener")
ok(LC.LineWords("citizen", "say_warn_go", "say_open_listen") == "Listen. You should go. Now.", "an opener and a line run together", LC.LineWords("citizen", "say_warn_go", "say_open_listen"))
ok(string.find(LC.LineList("citizen"), "say_dunno: I wouldn't know anything about that.", 1, true) ~= nil and not string.find(LC.LineList("citizen"), "say_open_", 1, true), "the model is shown the bank: an id, the words, and when")
-- said out loud: the recording when there is one, Half-Life 2's citizen otherwise
local T0 = Vector(-43000, 31000, 0)
local n, st = LC.SpawnCitizen(T0)
st.leaveAt = nil n.sim = false st.state = "idle"
if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
local heardSounds = {}
local realEmit = n.EmitSound
n.EmitSound = function(self, path) heardSounds[#heardSounds + 1] = path end
local realClip = LC.AdviceClip
LC.AdviceClip = function() return nil end
ok(LC.LineSay(n, st, "say_no") == "Sorry, but no." and #heardSounds == 0, "no recording: the words only, never Half-Life 2's voice in its place", heardSounds[1])
-- one voice for each named person
local realAny = LC.AdviceHasAny
LC.VoiceForce = nil
_setcvar("lc_voice_split", 0)
LC.AdviceHasAny = function() return false end
ok(LC.OwnVoice(n, st) == false and LC.LineKey(n, st) == "hl2", "nothing recorded yet: a named citizen has Half-Life 2's voice, and its lines")
LC.AdviceHasAny = function(prefix, gender) return prefix == "say_" and gender == st.gender end
ok(LC.OwnVoice(n, st) == true and LC.LineKey(n, st) == "citizen", "lc_voice_split 0: once the bank is recorded for their sex, every named citizen has the recorded voice")
-- two voices by personality
_setcvar("lc_voice_split", 1)
_setcvar("lc_minds", 1)
local realTraits = LC.Psy.Traits
LC.Psy.Traits = function() return { social = 0.6, hope = 0.4, brave = 0.2 } end
n.lcProfile.lcVoice = nil
ok(LC.VoiceOf(n, st) == "hl2" and LC.OwnVoice(n, st) == false, "the lively, sociable and hopeful keep Half-Life 2's voice")
LC.Psy.Traits = function() return { social = -0.6, hope = -0.5, brave = -0.2 } end
ok(LC.VoiceOf(n, st) == "hl2", "and keep it for life, whatever happens to them")
n.lcProfile.lcVoice = nil
ok(LC.VoiceOf(n, st) == "own" and LC.OwnVoice(n, st) == true and LC.LineKey(n, st) == "citizen", "the withdrawn and despairing get the recorded voice")
LC.Psy.Traits = realTraits
_setcvar("lc_minds", 0)
-- someone with Half-Life 2's voice: its own clips, and its own way of saying a break
LC.VoiceForce = "hl2"
heardSounds = {}
ok(LC.LineSay(n, st, "hl_answer10") == "I wouldn't say that too loud." and heardSounds[1] == "vo/npc/" .. (st.gender == "female" and "female01" or "male01") .. "/answer10.wav",
    "Half-Life 2's voice: one of its real clips, in its own words", heardSounds[1])
heardSounds = {}
ok(LC.LineSay(n, st, "say_break_tantrum") == "This is bullshit!" and string.find(heardSounds[1] or "", "question26.wav", 1, true) ~= nil, "asked for a line of the recorded bank, they say it their own way", heardSounds[1])
ok(LC.LineSay(n, st, "say_res_side") == "", "or nothing, where Half-Life 2 has nothing like it")
ok(LC.LineValid("hl2", "hl_answer24") and not LC.LineValid("hl2", "say_dunno") and string.find(LC.LineList("hl2"), "hl_question28: God I'm hungry.", 1, true) ~= nil, "the model is shown that bank for them")
local nHL = 0 for _ in pairs(LC.HL2Lines) do nHL = nHL + 1 end
ok(nHL >= 80, "about a hundred of Half-Life 2's citizen lines fit the city", nHL)
LC.VoiceForce = "own"
local plain, pst = LC.SpawnCitizen(T0 + Vector(0, 300, 0))
plain.lcProfile = nil
pst.gender = st.gender
LC.VoiceForce = nil
ok(LC.OwnVoice(plain, pst) == false, "an unnamed citizen keeps Half-Life 2's voice")
LC.VoiceForce = "own"
local sounds2 = {}
plain.EmitSound = function(self, path) sounds2[#sounds2 + 1] = path end
local thief2 = newPlayer("LinesGreeter", "citizen")
thief2:SetPos(T0 + Vector(60, 0, 0))
heardSounds = {}
local advClip = LC.AdviceClip
LC.AdviceClip = function() return nil end -- (this advice line is not recorded)
LC.AdviceSay(n, st, "advice_bins", thief2)
LC.VoiceForce = nil
LC.AdviceSay(plain, pst, "advice_bins", thief2)
LC.VoiceForce = "own"
LC.AdviceClip = advClip
local hl2 = false
for _, s in ipairs(heardSounds) do if string.find(s, "vo/npc/", 1, true) then hl2 = true end end
ok(not hl2 and #sounds2 >= 1 and string.find(sounds2[1], "vo/npc/", 1, true) == 1, "a line with no recording: the named one is quiet (no borrowed voice), the unnamed one speaks as before", sounds2[1])
for _, e in ipairs({ plain, thief2 }) do if IsValid(e) then e:Remove() end end
LC.AdviceHasAny = realAny
-- a unit: Half-Life 2's own clip where it has the line
local u, ust = LC.SpawnCop(T0 + Vector(400, 0, 0))
u.sim = false
local usounds = {}
u.EmitSound = function(self, path) usounds[#usounds + 1] = path end
LC.UnitLinesForgetStock()
ok(LC.LineSay(u, ust, "unit_move") == "Move along." and #usounds == 0, "a unit's line with no recording and no clip on the server: words only")
_files["sound/npc/metropolice/vo/movealong.wav"] = "x"
LC.UnitLinesForgetStock()
LC.LineSay(u, ust, "unit_move")
ok(usounds[1] == "npc/metropolice/vo/movealong.wav", "Half-Life 2 has that line: its own clip is played, nothing to record", usounds[1])
local _, unitMissing = LC.LinesMissing()
local listed = false
for _, id in ipairs(unitMissing) do if id == "unit_move" then listed = true end end
ok(not listed, "and it is not listed as missing")
_files["sound/npc/metropolice/vo/movealong.wav"] = nil
LC.UnitLinesForgetStock()
if IsValid(u) then u:Remove() end
heardSounds = {}
LC.AdviceClip = function(id, gender) return "livingcity/citizens/" .. id .. "_" .. (gender == "female" and "female" or "male") .. "1.wav" end
LC.LineSay(n, st, "say_warn_go", "say_open_listen")
ok(#heardSounds == 1 and string.find(heardSounds[1], "livingcity/citizens/say_open_listen_", 1, true) == 1, "a recording: the opener first", heardSounds[1])
_run(2)
ok(#heardSounds == 2 and string.find(heardSounds[2], "livingcity/citizens/say_warn_go_", 1, true) == 1, "then the line, in their own voice (a man's take or a woman's)", heardSounds[2])
local cit, unit = LC.LinesMissing()
LC.AdviceClip = function() return nil end
cit, unit = LC.LinesMissing()
ok(#cit == (nCit + #LC.SpySmallTalk) * 2 and #unit == nUnit, "lc_voice_missing can list every one not recorded yet", #cit)
local tagged = true
for id, l in pairs(LC.StreetLines) do if type(l[3]) ~= "string" or string.sub(l[3], 1, 1) ~= "[" or not string.find(l[3], string.sub(l[1], 1, 3), 1, true) then tagged = id end end
ok(tagged == true, "every line has its text for ElevenLabs: a direction in square brackets, then the words", tostring(tagged))
-- free talk: the model picks a line
_setcvar("lc_brain", 1) _setcvar("lc_brain_talk", 1) _setcvar("lc_brain_lines", 1)
local B = LC.Brain
B.lastTalk, B.minute, B.backOff, B.today, B.day, B.talks, B.inFlight, B.useLoaded, B.talkAsk, B.dirSystem = {}, {}, nil, 0, os.date("%Y-%m-%d"), {}, 0, true, nil, nil
local reqs, answer = {}, nil
local realHTTP = LC.BrainHTTP
LC.BrainHTTP = function(req) reqs[#reqs + 1] = req local code, body = answer(req) req.success(code, body) end
local function reply(tbl)
    return 200, LC.BrainJSON({ content = { { type = "text", text = LC.BrainJSON(tbl) } }, stop_reason = "end_turn", usage = { input_tokens = 100, output_tokens = 20 } })
end
LC.BrainSetKey("sk-test-lines")
local ply = newPlayer("LinesTalker", "citizen")
ply:SetPos(T0 + Vector(80, 0, 0))
ply.chat = {}
ply.GetEyeTrace = function() return { Entity = n } end
local function heard(text) for _, l in ipairs(ply.chat) do if string.find(l, text, 1, true) then return true end end return false end
heardSounds = {}
LC.AdviceClip = function(id, gender) return "livingcity/citizens/" .. id .. "_male1.wav" end
answer = function() return reply({ line = "say_cant_say", opener = "say_open_quiet", say = "", feeling = "0", act = "none" }) end
ok(LC.BrainHeard(ply, "say", "What do you know about the raid?") == true, "free talk with the bank on")
ok(string.find(reqs[1].body, "say_cant_say: I can't talk about that. You know why.", 1, true) ~= nil and string.find(reqs[1].body, '"line"', 1, true) ~= nil, "the model is given the bank and asked for a line")
ok(heard("says: \"Keep your voice down. I can't talk about that. You know why.\""), "it picked a recorded line: those are the words shown")
ok(#heardSounds >= 1 and string.find(heardSounds[1], "say_open_quiet", 1, true) ~= nil, "and it is spoken in their recorded voice", heardSounds[1])
_advance(6)
ply.chat = {}
answer = function() return reply({ line = "", opener = "", say = "The trains stopped running east a week ago.", feeling = "0", act = "none" }) end
LC.BrainHeard(ply, "say", "Are the trains running?")
ok(heard("The trains stopped running east a week ago."), "no line fits: its own words, as before")
_advance(6)
ply.chat = {}
_setcvar("lc_brain_lines", 2)
B.talkAsk = nil
LC.BrainHeard(ply, "say", "Are the trains running?")
ok(heard("I wouldn't know anything about that.") and not heard("The trains stopped"), "lc_brain_lines 2: recorded lines only, never words nobody recorded")
_advance(6)
ply.chat = {}
_setcvar("lc_brain_lines", 0)
answer = function() return reply({ say = "Ask at the station.", feeling = "0", act = "none" }) end
LC.BrainHeard(ply, "say", "Are the trains running?")
ok(heard("Ask at the station.") and not string.find(reqs[#reqs].body, "say_cant_say", 1, true), "lc_brain_lines 0: the bank is left out")
_setcvar("lc_brain_lines", 1)
-- the director's approach opens with one
B.moved, B.dirSystem = {}, nil
ply.chat = {}
st.state = "idle"
local okA, whyA = LC.DirectorApply({ action = "approach", person = n.lcProfile.name, player = LC.CharacterName and LC.CharacterName(ply) or ply:Nick(), line = "", recorded = "say_warn_asked", opener = "say_open_listen" }, CurTime())
ok(okA == true and st.mindErrand ~= nil, "an approach with a recorded line", whyA)
n:SetPos(ply:GetPos() + Vector(40, 0, 0))
LC.MindsErrandTick(CurTime())
ok(heard("Listen. Someone's been asking about you."), "they walk up and say it")
-- Half-Life 2's own lines, replaced one by one
section("Half-Life 2's own voice clips, replaced by recordings of them")
_setcvar("lc_voice_replace", 1)
LC.VoiceReplaceRescan()
ok(LC.VoiceReplacement("vo/npc/male01/hi01.wav") == nil, "no recording of a clip: it plays as it always did")
_files["sound/livingcity/hl2/vo/npc/male01/hi01.mp3"] = "x"
_files["sound/livingcity/hl2/npc/metropolice/vo/movealong.wav"] = "x"
_files["sound/livingcity/hl2/vo/gman_misc/gman_03.wav"] = "x"
ok(LC.VoiceReplaceRescan() == 2, "recordings in sound/livingcity/hl2/, under the clip's own path, are found (only in the folders it covers)", LC.VoiceReplacedCount)
ok(LC.VoiceReplacement("vo/npc/male01/hi01.wav") == "livingcity/hl2/vo/npc/male01/hi01.mp3" and LC.VoiceReplacement(")vo/npc/male01/HI01.wav") ~= nil
    and LC.VoiceReplacement("npc/metropolice/vo/movealong.wav") == "livingcity/hl2/npc/metropolice/vo/movealong.wav", "a clip with a recording is swapped for it, whatever marks the game put on its name")
ok(LC.VoiceReplacement("vo/gman_misc/gman_03.wav") == nil and LC.VoiceReplacement("vo/npc/male01/hi02.wav") == nil, "never the G-Man's, and never a clip without one")
local data = { SoundName = "vo/npc/male01/hi01.wav", Entity = n }
local res = hook.Run("EntityEmitSound", data)
ok(res == true and data.SoundName == "livingcity/hl2/vo/npc/male01/hi01.mp3", "every sound an entity makes passes the swap: the game's own lines too", data.SoundName)
LC.VoiceForce = "hl2"
local dataH = { SoundName = "vo/npc/male01/hi01.wav", Entity = n }
ok(hook.Run("EntityEmitSound", dataH) == nil and dataH.SoundName == "vo/npc/male01/hi01.wav", "a citizen who keeps Half-Life 2's voice keeps its clips: no swap for them")
local dataU = { SoundName = "npc/metropolice/vo/movealong.wav" }
ok(hook.Run("EntityEmitSound", dataU) == true, "a unit's clip is swapped whoever says it")
LC.VoiceForce = "own"
local data2 = { SoundName = "vo/npc/male01/hi02.wav" }
ok(hook.Run("EntityEmitSound", data2) == nil and data2.SoundName == "vo/npc/male01/hi02.wav", "anything else is left alone")
ok(LC.OwnVoice(n, st) == true and LC.OwnVoice(n, st, "vo/npc/male01/hi01.wav") == false, "a named citizen is not silenced on a clip that has been re-recorded: it is their voice now")
_setcvar("lc_voice_replace", 0)
ok(LC.VoiceReplacement("vo/npc/male01/hi01.wav") == nil, "lc_voice_replace 0: Half-Life 2's clips as they are")
_setcvar("lc_voice_replace", 1)
_files["sound/livingcity/hl2/vo/npc/male01/hi01.mp3"], _files["sound/livingcity/hl2/npc/metropolice/vo/movealong.wav"], _files["sound/livingcity/hl2/vo/gman_misc/gman_03.wav"] = nil, nil, nil
LC.VoiceReplaceRescan()
LC.BrainSetKey("")
LC.BrainHTTP, LC.AdviceClip = realHTTP, realClip
LC.VoiceForce = nil
n.EmitSound = realEmit
LC.MindsActs.errands = {}
for _, e in ipairs({ n, ply }) do if IsValid(e) then e:Remove() end end
end
LinesTests()
function VoiceCuesTests()
section("Named citizens say their recorded lines at the moments that fit, without the director (sv_livingcity_voicecues.lua)")
local function Later(secs) _advance(secs) _runtimers() end
local T0 = Vector(-43400, 31400, 0)
local n, st = LC.SpawnCitizen(T0)
st.leaveAt = nil n.sim = false st.state = "idle"
if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
st.rebel = false -- (a sympathizer counts as disloyal, whatever their traits)
local heard = {}
local realEmit, realClip, realFeeling = n.EmitSound, LC.AdviceClip, LC.Feeling
n.EmitSound = function(self, path) heard[#heard + 1] = path end
LC.AdviceClip = function(id, g) return "livingcity/citizens/" .. id .. "_" .. (g or "male") .. "1.mp3" end
_setcvar("lc_voice_cues", 1)
LC.VoiceForce = "own"
local w = LC.Cue(n, st, "say_yes", { lead = false })
ok(w == "Yeah. All right." and heard[#heard] == "livingcity/citizens/say_yes_" .. (st.gender or "male") .. "1.mp3", "a named citizen with the recorded voice says the line: the recording plays, the words come back", tostring(w) .. " " .. tostring(heard[#heard]))
ok(LC.Cue(n, st, "say_no", { lead = false }) == nil and LC.Cue(n, st, "say_no", { lead = false, force = true }) == "Sorry, but no.", "never two lines in a row from the same person, unless the moment calls for it")
LC.VoiceForce = "hl2"
n.lcCueAt = nil
ok(LC.Cue(n, st, "say_yes", { lead = false }) == nil, "someone with Half-Life 2's voice: nothing where Half-Life 2's voice already plays")
n.lcCueAt = nil
local w2 = LC.Cue(n, st, "say_saw_death", { all = true, lead = false })
ok(w2 ~= nil and w2 ~= "" and w2 ~= LC.StreetLines.say_saw_death[1], "where nothing played before, they say Half-Life 2's own line in its place", tostring(w2))
n.lcCueAt = nil
ok(LC.Cue(n, st, "say_tip_help", { all = true }) == nil, "and nothing where Half-Life 2 has nothing like it")
LC.VoiceForce = "own"
_setcvar("lc_voice_cues", 0)
n.lcCueAt = nil
ok(LC.Cue(n, st, "say_yes", { force = true }) == nil, "lc_voice_cues 0: none of it")
_setcvar("lc_voice_cues", 1)
-- who they are, and how they feel about you
local m = LC.MindOf(n.lcProfile)
local function SetTraits(t)
    local all = { brave = 0, temper = 0, loyal = 0, social = 0, hope = 0, greed = 0, compassion = 0, suspicion = 0, resilience = 0, pride = 0, vice = 0 }
    for k, v in pairs(t) do all[k] = v end
    m.tr = all
end
SetTraits({})
local ply = newPlayer("CueTalker", "citizen")
ply:SetPos(T0 + Vector(60, 0, 0))
local feel = 0
LC.Feeling = function() return feel end
ok(LC.CueGreeting(n, st, ply) == "say_greet_plain", "hello: plain to a stranger", LC.CueGreeting(n, st, ply))
feel = 5 ok(LC.CueGreeting(n, st, ply) == "say_greet_warm" and LC.CueGoodbye(n, st, ply) == "say_bye_warm", "warm to someone they like, hello and goodbye")
feel = -4 ok(LC.CueGreeting(n, st, ply) == "say_greet_guarded" and LC.CueGoodbye(n, st, ply) == "say_bye_cold", "wary of someone they fear")
feel = -8 ok(LC.CueGreeting(n, st, ply) == "say_greet_cold", "cold to someone they hate")
feel = 0
-- how they are
local s = LC.Psy.State(m)
s.food, s.rest, s.company, s.stress, s.mood = 0.1, 0.8, 0.7, 0, 0
ok(LC.CueState(n, st) == "say_state_hungry", "how they are comes from their needs: hungry", LC.CueState(n, st))
s.food, s.rest = 0.8, 0.1
ok(LC.CueState(n, st) == "say_state_tired", "tired", LC.CueState(n, st))
s.rest, s.stress = 0.8, 25
SetTraits({ temper = 0.5 })
ok(LC.CueState(n, st) == "say_state_angry", "close to breaking, and hot-headed: angry", LC.CueState(n, st))
s.stress = 0
SetTraits({ loyal = 0.6 })
ok(LC.CueAnswer(n, st, "say_hate_quiet") == "say_loyal_warn", "the loyal warn whoever speaks against the Combine")
SetTraits({ loyal = -0.6, brave = 0.5 })
ok(LC.CueAnswer(n, st, "say_loyal") == "say_disagree", "the bold and disloyal disagree with the loyal")
-- what a player says near them
SetTraits({})
ok(LC.CueReply(ply, n, st, "Hey there") == "say_greet_plain", "chat: hello", LC.CueReply(ply, n, st, "Hey there"))
ok(LC.CueReply(ply, n, st, "how are you doing?") == LC.CueState(n, st), "chat: how are you", LC.CueReply(ply, n, st, "how are you doing?"))
ok(LC.CueReply(ply, n, st, "you're an idiot") == "say_insulted", "chat: an insult")
ok(LC.CueReply(ply, n, st, "I'll kill you") == "say_threatened", "chat: a threat")
ok(LC.CueReply(ply, n, st, "haha that's good") == "say_laugh", "chat: a joke")
SetTraits({ loyal = 0.6 })
ok(LC.CueReply(ply, n, st, "have you heard of the resistance?") == "say_loyal_warn", "chat: the loyal won't hear of the Resistance")
SetTraits({})
ok(LC.CueReply(ply, n, st, "the weather is grey") == nil, "chat: nothing to say to something that isn't for them")
local realBrain = LC.BrainOn
LC.BrainOn = function() return false end
ply:SetPos(T0 + Vector(80, 0, 0))
ply.GetAimVector = function() return Vector(-1, 0, 0) end
n.lcCueAt, ply.lcCueHeardAt = nil, nil
local said = {}
local realChat = ply.ChatPrint
ply.ChatPrint = function(self, t) said[#said + 1] = t end
LC.CueHeard(ply, "say", "hello")
Later(2)
local shown = false
for _, t in ipairs(said) do if string.find(t, "says: \"Hey. Still here, huh? Me too.\"", 1, true) then shown = true end end
ok(st.lcCueLast == "say_greet_plain" and shown, "a player says hello near them: they answer out loud, and the words show", tostring(st.lcCueLast) .. " " .. tostring(said[#said]))
LC.BrainOn = function() return true end
n.lcCueAt, ply.lcCueHeardAt, st.lcCueLast = nil, nil, nil
LC.CueHeard(ply, "say", "hello")
Later(2)
ok(st.lcCueLast == nil, "with the director's key, the model answers instead")
LC.BrainOn = function() return false end
-- the talk window: thanks, quoted as heard
n.lcCueAt = nil
feel = 0
LC.GiveItem(ply, "ration", 1)
local r = LC.TalkAction(ply, n, "food")
ok(string.find(r or "", "'Thank you. I won't forget it.'", 1, true) ~= nil, "food given: they thank you in their recorded voice, and the window quotes what was heard", tostring(r))
-- goodbye when you walk off
n.lcCueAt = nil
ply.lcCueTalk = { npc = n, at = CurTime() }
ply:SetPos(T0 + Vector(600, 0, 0))
Later(1.5)
ok(st.lcCueLast == "say_bye_plain" and ply.lcCueTalk == nil, "walk off after talking: goodbye", tostring(st.lcCueLast))
-- what they see
ply:SetPos(T0 + Vector(100, 0, 0))
n.lcCueAt, n.lcCueSeen, st.lcCueLast = nil, nil, nil
m.p = m.p or n.lcProfile
local realNpc = m.p.npc
m.p.npc = n
LC.Psy.Think(m, "saw_beating", CurTime(), nil)
Later(3)
ok(st.lcCueLast == "say_saw_beating", "they see someone beaten: they say so", tostring(st.lcCueLast))
n.lcCueAt = nil
LC.Psy.Think(m, "friend_taken", CurTime(), nil)
Later(3)
ok(st.lcCueLast == "say_grief", "a friend taken away: grief", tostring(st.lcCueLast))
-- walking up to someone
SetTraits({ loyal = 0.5 })
s.food, s.stress, s.company = 0.1, 0, 0.7
ok(LC.CueApproachLine(ply, n, st) == "say_ask_food", "hungry: they walk up and ask for food", tostring(LC.CueApproachLine(ply, n, st)))
s.food = 0.8
ok(LC.CueApproachLine(ply, n, st) == nil, "nothing on their mind: they leave you be")
feel = -5
s.food = 0.1
ok(LC.CueApproachLine(ply, n, st) == nil, "never someone who fears you")
-- every line of the bank has a moment
local leads = 0
for _, l in pairs(LC.CueLeads) do if string.sub(l, 1, 9) == "say_open_" then leads = leads + 1 end end
ok(leads > 10, "openers come before the lines they suit")
-- tidy up
m.p.npc = realNpc
LC.BrainOn, LC.Feeling, LC.AdviceClip = realBrain, realFeeling, realClip
LC.VoiceForce = nil
m.tr = nil
n.EmitSound, ply.ChatPrint = realEmit, realChat
for _, e in ipairs({ n, ply }) do if IsValid(e) then e:Remove() end end
end
VoiceCuesTests()
function LipSyncTests() -- (the owner, 12 November: "can we get the NPCs' mouths to move?")
section("Whoever says a recorded line is marked talking for its length (their mouth moves on players' screens)")
local L0 = Vector(-153000, -153000, 0)
local npc = ents.Create("npc_citizen") npc:SetPos(L0) npc:Spawn()
ok(LC.MarkTalking(npc, "livingcity/citizens/advice_bins_male1.wav") == true, "a recorded line: marked")
local from, untilT = npc:GetNW2Float("lc_talk_from", 0), npc:GetNW2Float("lc_talk_until", 0)
ok(untilT > CurTime() and math.abs((untilT - from) - 2.5) < 0.01, "for as long as it lasts (a length unknown: about a line's)", tostring(untilT - from))
local npc2 = ents.Create("npc_citizen") npc2:SetPos(L0 + Vector(100, 0, 0)) npc2:Spawn()
ok(LC.MarkTalking(npc2, "vo/npc/male01/hi01.wav") == false and npc2:GetNW2Float("lc_talk_until", 0) == 0, "Half-Life 2's own clip: left to the engine (it has the phonemes)")
ok(LC.MarkTalking(npc2, ")sound/livingcity/clerk/rations1.wav") == true, "(the marks the game puts in front of a name are ignored)")
local pl = newPlayer("LipSyncPlayer", "citizen")
ok(LC.MarkTalking(pl, "livingcity/citizens/advice_bins_male1.wav") == false, "never a player (their own voice)")
local npc3 = ents.Create("npc_citizen") npc3:SetPos(L0 + Vector(200, 0, 0)) npc3:Spawn()
hook.Run("EntityEmitSound", { Entity = npc3, SoundName = "livingcity/oldtimer/bins1.wav", OriginalSoundName = "livingcity/oldtimer/bins1.wav" })
ok(npc3:GetNW2Float("lc_talk_until", 0) > CurTime(), "any recorded line an NPC says (the clerk, the old-timer, citizens): marked as it is played")
npc:Remove() npc2:Remove() npc3:Remove()
pl:SetPos(Vector(-30000, 30000, 0))
end
LipSyncTests()
function GiveTests()
section("Giving a citizen something: food, a drink or a smoke, medicine, papers, arms")
local function Later(secs) _advance(secs) _runtimers() end
ok(LC.GiveKind("ration") == "food" and LC.GiveKind("beer") == "vice" and LC.GiveKind("cig_union") == "vice" and LC.GiveKind("medicine") == "medicine"
    and LC.GiveKind("gun_pistol") == "arms" and LC.GiveKind("pamphlet") == "papers", "what kind of thing each is, to a citizen")
LCS.Items.test_leaflet = { name = "Test leaflet", model = "models/props_c17/paper01.mdl", leaflet = "resistance", kg = 0 }
ok(LC.GiveKind("test_leaflet") == "papers", "a Resistance leaflet (any item with leaflet = \"resistance\") is papers")
local T0 = Vector(-40000, 28000, 0)
local function person(off)
    local n, st = LC.SpawnCitizen(T0 + off)
    st.leaveAt = nil
    n.sim = false
    if not n.lcProfile then LC.AttachProfile(n, st, LC.NewPerson("citizen")) end
    st.state, st.untilT, st.nextThink = "idle", CurTime() + 9999, CurTime() + 9999
    return n, st
end
local giver = newPlayer("Giver", "citizen")
giver:SetPos(T0)
for _, id in ipairs({ "ration", "beer", "medicine", "gun_pistol", "pamphlet", "test_leaflet" }) do LC.GiveItem(giver, id, 1) end
local list = LC.GiveableTo(giver)
local ids = {}
for i, g in ipairs(list) do ids[g.id] = i end
ok(ids.ration and ids.beer and ids.medicine and ids.gun_pistol and ids.pamphlet and ids.test_leaflet and ids.ration < ids.beer and ids.beer < ids.gun_pistol,
    "the Give menu lists what's in your pockets, food first, arms last", #list)
-- food: as sharing always was
local c, cs = person(Vector(60, 0, 0))
cs.rebel = nil
local said = LC.GiveToCitizen(giver, c, "ration")
ok(LC.Feeling(c, giver) == 2 and not LC.HasItem(giver, "ration") and string.find(said or "", "ration", 1, true), "food: taken and remembered, as before", said)
-- a drink: only someone with the weakness takes it, and drinks it there and then
local drinker, sober
for _ = 1, 400 do
    local q = LC.NewPerson("citizen")
    local v = LC.Psy.Traits(LC.MindOf(q)).vice
    if v > 0.5 and not drinker then drinker = q elseif v <= 0 and not sober then sober = q end
    if drinker and sober then break end
end
local d, ds = person(Vector(0, 60, 0))
if d.lcProfile then d.lcProfile.npc = nil end
LC.AttachProfile(d, ds, drinker)
ds.state = "idle"
local s, ss = person(Vector(0, -60, 0))
if s.lcProfile then s.lcProfile.npc = nil end
LC.AttachProfile(s, ss, sober)
ss.state = "idle"
said = LC.GiveToCitizen(giver, s, "beer")
ok(LC.HasItem(giver, "beer") and string.find(said or "", "I don't", 1, true), "someone sober says no and you keep it", said)
_setcvar("lc_npc_vices", 1)
said = LC.GiveToCitizen(giver, d, "beer")
ok(not LC.HasItem(giver, "beer") and LC.Feeling(d, giver) >= 2 and LC.NPCVices[d] ~= nil, "someone fond of a drink takes it, and drinks it there and then", said)
LC.NPCViceStop(d)
_setcvar("lc_npc_vices", 0)
-- medicine
said = LC.GiveToCitizen(giver, c, "medicine")
ok(not LC.HasItem(giver, "medicine") and LC.Feeling(c, giver) == 5, "medicine: taken gratefully", said)
-- arms: only a sympathizer takes a gun
local before = LC.Feeling(s, giver)
ss.rebel = nil
said = LC.GiveToCitizen(giver, s, "gun_pistol")
ok(LC.HasItem(giver, "gun_pistol") and LC.Feeling(s, giver) == before - 1 and string.find(said or "", "out of your mind", 1, true), "a gun to an ordinary citizen: refused, and it frightens them", said)
cs.rebel = true
said = LC.GiveToCitizen(giver, c, "gun_pistol")
ok(not LC.HasItem(giver, "gun_pistol") and string.find(said or "", "under their coat", 1, true), "a sympathizer hides it under their coat", said)
ok(LC.NPCHiddenGun and LC.NPCHiddenGun(c, cs) == "weapon_pistol" and LC.SearchNPCRoll(cs) == "a hidden firearm",
    "and keeps it hidden: it goes to the Resistance's crate, or a unit's search finds it (21 November)", tostring(cs.hidGun))
cs.hidGun = nil if c.lcProfile then c.lcProfile.hidGun = nil end
-- Civil Protection never sees arms in the menu
local giverCP = newPlayer("GiverUnit", "cp")
LC.GiveItem(giverCP, "gun_pistol", 1) LC.GiveItem(giverCP, "ration", 1)
local cpIds = {}
for _, g in ipairs(LC.GiveableTo(giverCP)) do cpIds[g.id] = true end
ok(cpIds.ration and not cpIds.gun_pistol, "a Civil Protection player's Give menu has no guns in it")
-- a Resistance leaflet: a sympathizer takes it, someone loyal pushes it back
said = LC.GiveToCitizen(giver, c, "test_leaflet")
ok(not LC.HasItem(giver, "test_leaflet"), "a Resistance leaflet to a sympathizer: kept", said)
LC.GiveItem(giver, "test_leaflet", 1)
local loyalP
for _ = 1, 400 do local q = LC.NewPerson("citizen") if LC.Psy.Traits(LC.MindOf(q)).loyal > 0.5 then loyalP = q break end end
local l, ls = person(Vector(-60, 0, 0))
if l.lcProfile then l.lcProfile.npc = nil end
LC.AttachProfile(l, ls, loyalP)
ls.state, ls.rebel = "idle", nil
said = LC.GiveToCitizen(giver, l, "test_leaflet")
ok(LC.HasItem(giver, "test_leaflet") and LC.Feeling(l, giver) == -3, "to someone loyal: pushed back, and they hold it against you", said)
-- the Resistance pamphlet (another chat's sv_livingcity_rebelpamphlet.lua): handed over its own way
ok(LC.GiveKind("rebel_pamphlet") == "papers", "the Resistance pamphlet is in the Give menu, under Papers")
LC.GiveItem(giver, "rebel_pamphlet", 1)
cs.rebel = true
c.lcPamphletAt = nil
LC.GiveToCitizen(giver, c, "rebel_pamphlet")
ok(not LC.HasItem(giver, "rebel_pamphlet"), "a sympathizer takes it (as LC.GiveRebelPamphlet decides)")
said = LC.GiveToCitizen(giver, l, "pamphlet")
ok(not LC.HasItem(giver, "pamphlet"), "the Civil Orientation pamphlet: anyone takes it", said)
-- the window: the list goes with it, and a pick from it gives
net.sent = {}
LC.OpenTalk(giver, l)
local m = _lastnet("lc_talk")
local listed = false
for _, v in ipairs(m and m.data or {}) do if v == "test_leaflet" then listed = true end end
ok(listed, "the talk window carries the Give menu's list")
LC.GiveItem(giver, "ration", 1)
giver.lcTalkNext = 0
_netcall("lc_talk_do", giver, l, "give:ration")
ok(not LC.HasItem(giver, "ration"), "picking from the menu gives it (give:<item>)")
LCS.Items.test_leaflet = nil
for _, e in ipairs({ c, d, s, l }) do if IsValid(e) then e:Remove() end end
end
GiveTests()
function CPDutyTests()
section("A unit's shift: the quota, papers duty, inspections, the review")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_cp_duty", 1)
local D0 = Vector(97000, -97000, 0)
local bz = LC.AddZone(D0, 500, "block", 37)
local unit = newPlayer("DutyUnit", "cp")
local cit = newPlayer("DutyResident", "citizen")
Later(5.5)
local s = LC.CPShift(unit)
ok(s and unit:GetNW2String("lc_shift", "") ~= "", "a unit on duty is on a shift, shown on F2 > Me > My shift")
ok(LC.CPShift(cit) == nil, "a citizen has no shift")
for _ = 1, 3 do hook.Run("LivingCitySearched", unit, cit, {}, {}) end
ok(s.searches == 3 and has(unit.chat, "Quota: searches done"), "searches count toward the quota", s.searches)
LC.SearchNPCClean(unit, { untilT = 0 })
ok(s.searches == 4, "searching one of the city's people counts too")
-- an inspection
local b = LC.PlayerBlock(cit) or 37
if not LC.PlayerBlock(cit) then cit:SetPData("lc_block_" .. game.GetMap(), 37) cit:SetNW2Int("lc_block", 37) end
local okO = LC.CPInspectOrder(unit)
ok(okO and unit.lcInspectOrder, "F2 > My shift > Get an inspection order names a resident and their block")
unit.lcInspectOrder = { target = cit, name = "DutyResident", block = LC.PlayerBlock(cit), blockName = "Block 37" }
LC.Stash(cit).moonshine = 6
unit:SetPos(D0 + Vector(0, 0, 0) + Vector(9000, 0, 0))
local okI, whyI = LC.CPInspect(unit)
ok(not okI and string.find(whyI or "", "not in", 1, true), "inspecting needs you in their block", whyI)
for _, z in ipairs(LC.ZonesOfKind("block")) do if z.group == LC.PlayerBlock(cit) then unit:SetPos(z.pos) break end end
cit:SetPos(D0 + Vector(20000, 0, 0))
LC.CPInspect(unit)
Later(9)
ok((LC.Stash(cit).moonshine or 0) < 6 and s.inspections == 1, "the residence is searched: contraband in their stash is confiscated", LC.Stash(cit).moonshine)
ok(LC.PlayerIsWanted(cit), "and the resident is charged, as a raid would")
LC.ClearWanted(cit)
-- an Insider writes it up clean
local okNI, whyNI = LC.CPReportClean(unit)
ok(not okNI, "only an Insider can report a residence clean", whyNI)
local oldIns, oldW = LC.IsInsider, LC.InsiderWatched
LC.IsInsider = function(p) return p == unit end
LC.InsiderWatched = function() return true, "Someone can see you." end
unit.lcInspectOrder = { target = cit, name = "DutyResident", block = LC.PlayerBlock(cit), blockName = "Block 37" }
local okW, whyW = LC.CPReportClean(unit)
ok(not okW and string.find(whyW or "", "properly", 1, true), "not with anyone watching but the resident", whyW)
LC.InsiderWatched = function() return false end
LC.Stash(cit).moonshine = 4
local symB = LC.Trait and LC.Trait(unit, "sympathy") or 0
local insB = s.inspections
ok(LC.CPReportClean(unit), "an Insider reports the residence clean")
Later(9)
ok((LC.Stash(cit).moonshine or 0) == 4 and s.inspections == insB + 1, "the stash is left alone and the quota still counts", LC.Stash(cit).moonshine)
ok(not LC.PlayerIsWanted(cit), "and the resident isn't charged")
ok(not LC.Trait or LC.Trait(unit, "sympathy") > symB, "contraband written up clean: a little sympathy")
ok(unit.lcCleanReport and unit.lcCleanReport.block == LC.PlayerBlock(cit), "the report is remembered")
local stB = LC.Standing and LC.Standing(unit) or 0
hook.Run("LivingCityBlockRaided", LC.PlayerBlock(cit) + 1, { x = 2 })
ok(unit.lcCleanReport ~= nil, "a raid elsewhere doesn't matter")
hook.Run("LivingCityBlockRaided", LC.PlayerBlock(cit), { x = 2 })
ok(not LC.Standing or LC.Standing(unit) < stB, "a raid there that finds anything soon after: the report doesn't hold up", LC.Standing and LC.Standing(unit))
ok(unit.lcCleanReport == nil, "and it's settled")
LC.IsInsider, LC.InsiderWatched = oldIns, oldW
LC.Stash(cit).moonshine = nil
-- papers duty
ok(LC.CPPapersDuty(unit) and LC.JobGames[unit] and LC.JobGames[unit].kind == "papers", "checkpoint papers duty: the travelers' papers checked against today's rules")
LC.JobGames[unit].done = 5
LC.JobGameEnd(unit, "done")
LC.CPDutyTick()
ok(s.papers == 1, "finished, it counts", s.papers)
hook.Run("LivingCityIncarcerated", cit, 60, "Test", unit)
ok(s.arrests == 1, "arrests are counted for the review")
-- the review
local x0 = tonumber(unit:GetPData("lcf_xp_cp", 0)) or 0
s.startT = CurTime() - 31 * 60
unit.chat = {}
LC.CPDutyTick()
local rv = util.JSONToTable(unit:GetPData("lc_cp_reviews", "") or "") or {}
ok(rv[1] and rv[1].grade == "A" and has(unit.chat, "Performance review"), "the end of the shift: a performance review", rv[1] and rv[1].line)
ok((tonumber(unit:GetPData("lcf_xp_cp", 0)) or 0) - x0 == 30, "grade A: 30 experience toward promotion")
ok(LC.CPShift(unit) ~= s and LC.CPShift(unit).searches == 0, "and a new shift begins")
LC.CPShift(unit).startT = CurTime() - 31 * 60
LC.CPDutyTick()
rv = util.JSONToTable(unit:GetPData("lc_cp_reviews", "") or "") or {}
ok(rv[1].grade == "D" and #rv == 2, "nothing done: grade D, and the reviews are kept")
-- report in early, and a break if wanted
local s2 = LC.CPShift(unit)
local okE, whyE = LC.CPReportIn(unit)
ok(not okE and string.find(whyE or "", "Finish the checklist", 1, true), "reporting in early needs the checklist done", whyE)
s2.searches, s2.papers, s2.inspections = 3, 1, 1
ok(LC.CPReportIn(unit) and LC.CPShift(unit) ~= s2 and LC.CPShift(unit).searches == 0, "checklist done: report in now, reviewed at once, and the next shift starts (no waiting out the clock)")
ok(LC.CPBreak(unit) and LC.CPShift(unit) == nil and unit:GetNW2Bool("lc_offduty", false), "a break, if they want one: no shift until they're back")
ok(LC.CPBreak(unit) and LC.CPShift(unit) ~= nil, "back on duty: a new shift")

if LC.Prisoners[cit] then LC.ReleasePrisoner(cit) end
unit:RemovePData("lc_cp_reviews")
LC.RemoveZone(bz)
for _, p in ipairs({ unit, cit }) do p:SetPos(D0 + Vector(30000, 0, 0)) end
end
CPDutyTests()
function CPShiftFixTests()
section("A unit's shift: 30 minutes again, and one 'Shift started', not two in a row")
do
    local cv = GetConVar("lc_cp_shift_minutes")
    ok(_cvarDefaults["lc_cp_shift_minutes"] == "30", "a shift is 30 minutes by default (the owner, 12 November: \"just make the shift back to 30 minutes\")", _cvarDefaults["lc_cp_shift_minutes"])
    local was = cv:GetString()
    _setcvar("lc_cp_shift_minutes", "15")
    LC.EndingRetune()
    ok(cv:GetString() == "30", "a server still on the old 15 moves to 30", cv:GetString())
    _setcvar("lc_cp_shift_minutes", was)
    local notes = {}
    local realNotice = LC.Notice
    LC.Notice = function(p, kind, title, text, secs) notes[#notes + 1] = { p = p, t = tostring(title) } return realNotice(p, kind, title, text, secs) end
    local function Started(p) local n = 0 for _, x in ipairs(notes) do if x.p == p and x.t == "Shift started" then n = n + 1 end end return n end
    local unit = newPlayer("ShiftUnit", "cp")
    unit:SetPos(Vector(44000, -52000, 0))
    unit.lcShift, unit.lcOffDuty = nil, nil
    LC.CPDutyTick()
    local s = LC.CPShift(unit)
    ok(s ~= nil and Started(unit) == 1, "on duty: a shift starts, and they're told once", Started(unit))
    -- a moment off the books (a respawn, a change of uniform): the same shift, no second notice
    unit:SetNW2String("lcf_faction", "citizen")
    LC.CPDutyTick()
    unit:SetNW2String("lcf_faction", "cp")
    LC.CPDutyTick()
    ok(LC.CPShift(unit) == s and Started(unit) == 1, "a blip off duty keeps the shift: no second 'Shift started'", Started(unit))
    -- a new shift straight after another start: not announced twice in a row
    unit.lcShift = nil
    LC.CPDutyTick()
    ok(LC.CPShift(unit) ~= s and Started(unit) == 1, "a new shift within two minutes of the last notice isn't announced again (it's on F2 > Me > My shift)", Started(unit))
    -- off duty for good (a break): dropped at once
    LC.CPBreak(unit)
    ok(LC.CPShift(unit) == nil and unit.lcShift == nil, "a break still drops the shift at once")
    LC.CPBreak(unit)
    LC.Notice = realNotice
    unit:SetPos(Vector(74000, -52000, 0))
end
end
CPShiftFixTests()
function SnitchTests()
section("Secret informants among the citizens, and the Resistance burning one")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_snitches", 1)
_setcvar("lc_burn", 1)
local S0 = Vector(-99000, 99000, 0)
local cit, cst = LC.SpawnCitizen(S0)
cst.untilT = 1e9
local cop, kst = LC.SpawnCop(S0 + Vector(1200, 0, 0))
kst.untilT = 1e9
local p = newPlayer("SnitchedOn", "citizen")
local unit = newPlayer("SnitchUnit", "cp")
Later(0.5)
p:SetPos(S0 + Vector(200, 0, 0))
unit:SetPos(S0 + Vector(-3000, 0, 0))
cst.snitch = false
ok(not LC.IllegalAct(p, "carrying a gun"), "an ordinary citizen sees nothing worth telling")
cst.snitch = true
ok(LC.IsSnitch(cit) and cit:GetNW2String("lc_role", "") == "citizen", "a snitch is one of the city's citizens like any other (a flag nobody sees)")
ok(LC.IllegalAct(p, "carrying a gun") and cst.snitchReport and cst.snitchReport.unit == cop, "seeing a player do something illegal, they head for the nearest unit")
ok(not LC.IllegalAct(p, "carrying a gun"), "(the same thing isn't seen twice in a minute)")
cit:SetPos(cop:GetPos() + Vector(60, 0, 0))
unit.chat = {}
Later(0.6)
ok(LC.PlayerIsWanted(p) and string.find(p:GetNW2String("lc_wanted_reason", ""), "Reported by a citizen", 1, true), "and tell: the player is booked", p:GetNW2String("lc_wanted_reason", ""))
ok(has(unit.chat, "A citizen reports") and p:GetNW2Float("lc_spotted_until", 0) > CurTime(), "the units hear it, and the player is outlined for them")
LC.ClearWanted(p)
-- no unit about: a call from a doorway
LC.NPCs[cop] = nil cop:Remove()
p.lcActSeen = {}
cit:SetPos(S0)
LC.IllegalAct(p, "using moonshine")
Later(26)
ok(LC.PlayerIsWanted(p), "with no unit about, they make the call after a while")
LC.ClearWanted(p)
-- killed first: nobody hears
p.lcActSeen = {}
LC.IllegalAct(p, "carrying a gun")
cst.state = "hostile"
Later(0.6)
cst.state = "idle"
Later(30)
ok(not LC.PlayerIsWanted(p) and cst.snitchReport == nil, "caught up in a fight (or killed) before telling: nobody hears it")
-- contraband used in plain view
p.lcActSeen = {}
cst.questLock = nil
LC.GiveItem(p, "moonshine", 1)
LC.ItemUse(p, "moonshine")
ok(cst.snitchReport and string.find(cst.snitchReport.what, "moonshine", 1, true), "using contraband is seen too", cst.snitchReport and cst.snitchReport.what)
cst.snitchReport, cst.questLock = nil, nil

-- burning
local reb = newPlayer("BurnerRebel", "resistance", nil, 3000)
local innocent = newPlayer("BurnInnocent", "citizen")
local rat = newPlayer("BurnRat", "citizen")
local bystander = newPlayer("BurnBystander", "citizen")
Later(0.5)
for _, x in ipairs({ reb, innocent, rat, bystander }) do x:SetPos(S0 + Vector(0, 3000, 0)) end
reb:SetNW2Int("lcf_rank", 1)
local okB, whyB = LC.Burn(reb, innocent)
ok(not okB and string.find(whyB or "", "Member", 1, true), "a Sympathizer can't burn anyone", whyB)
reb:SetNW2Int("lcf_rank", 2)
LC.AddTrait(bystander, "sympathy", 3 - LC.Trait(bystander, "sympathy"))
local x0 = tonumber(reb:GetPData("lcf_xp_resistance", 0)) or 0
local okW, right = LC.Burn(reb, innocent)
ok(okW and not right and LC.IsBurned(innocent), "burning someone who never informed: they're burned all the same", tostring(right))
ok(LC.Trait(bystander, "sympathy") == 2 and has(bystander.chat, "burned an innocent"), "and word spreads: every citizen thinks less of the Resistance")
ok((tonumber(reb:GetPData("lcf_xp_resistance", 0)) or 0) < x0, "and the burner loses experience")
local okC, whyC = LC.Burn(reb, rat)
ok(not okC and string.find(whyC or "", "not long ago", 1, true), "one burning at a time", whyC)
reb.lcBurnNext = 0
rat.lcInformedAt = CurTime()
local x1 = tonumber(reb:GetPData("lcf_xp_resistance", 0)) or 0
local okR, right2 = LC.Burn(reb, rat)
ok(okR and right2 and (tonumber(reb:GetPData("lcf_xp_resistance", 0)) or 0) > x1, "burning a real informant: the burner was right, and earns for it")
LC.AddTrait(rat, "sympathy", 10)
ok(not LC.ResistanceProven(rat), "a burned citizen can't join the Resistance, whatever their sympathy")
rat.chat = {}
ok(LC.OpenQuartermasterVisit(rat) == false and has(rat.chat, "rats"), "and the quartermaster won't deal with them")
-- the scar
local okS, whyS = LC.Scar(reb, rat)
ok(not okS and string.find(whyS or "", "fight you off", 1, true), "scarring needs them held: cuffed, down, or hands up", whyS)
rat:SetNW2Bool("lc_handsup", true)
LC.Scar(reb, rat)
Later(6)
ok(rat:GetPData("lc_scar", "0") == "1" and string.find(rat:GetNW2String("lc_desc", ""), "crude rat carved", 1, true), "a crude rat carved into their cheek, for good, in the description strangers see")
ok(rat:GetNW2Bool("lc_scar_mark", false), "and drawn on their face for everyone to see")
rat:SetNW2Float("lc_burned_until", 0)
LC.AddTrait(rat, "sympathy", 20)
ok(not LC.ResistanceProven(rat), "a marked rat can never join the Resistance, burned or not, whatever their sympathy")
rat:SetNW2Float("lc_burned_until", CurTime() + 3600)
-- roughed up in rebel territory
local rebNPC, rst = LC.Spawners.rebel and LC.Spawners.rebel(rat:GetPos() + Vector(60, 0, 0))
if not rebNPC then rebNPC, rst = LC.SpawnCitizen(rat:GetPos() + Vector(60, 0, 0)) rst.role = "rebel" end
local inR = LC.InRebelZone
LC.InRebelZone = function() return true end
rat:SetHealth(100)
rat.chat = {}
Later(2.5)
LC.InRebelZone = inR
ok(rat:Health() < 100 and has(rat.chat, "Rat"), "in rebel territory, the rebels rough them up")
for _, n in ipairs({ cit, rebNPC }) do if IsValid(n) then LC.NPCs[n] = nil n:Remove() end end
for _, x in ipairs({ p, unit, reb, innocent, rat, bystander }) do x:SetPos(S0 + Vector(30000, 0, 0)) x:SetNW2Float("lc_burned_until", 0) end
_setcvar("lc_snitches", 0)
end
SnitchTests()
function OpPlanTests()
section("The Resistance plans its own operations; the Combine puts prices on heads")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_rebel_plans", 1)
_setcvar("lc_bounties", 1)
local O0 = Vector(-101000, 101000, 0)
local lt = newPlayer("PlanLieutenant", "resistance", nil, 9000)
local mem = newPlayer("PlanMember", "resistance", nil, 100)
local unit = newPlayer("PlanUnit", "cp")
Later(0.5)
lt:SetNW2Int("lcf_rank", 4) mem:SetNW2Int("lcf_rank", 2)
ok(LC.CanPlanOp(lt) and not LC.CanPlanOp(mem), "a Lieutenant plans operations; a Member joins them")
local targetsWas, launchWas, radioWas, skWas = LC.OpTargets, LC.LaunchRebelOp, LC.RadioNotice, LC.Skirmish
local heard, launched = {}, nil
LC.RadioNotice = function(band, text) heard[#heard + 1] = band .. ": " .. text end
LC.OpTargets = function() return { { label = "Hijack the city screen in the square", kind = "screen", pos = O0, data = {} } } end
LC.LaunchRebelOp = function(kind, pos, data) launched = kind LC.Skirmish = { purpose = kind, rebels = {}, units = {}, done = true, startT = CurTime(), untilT = CurTime() + 1e6 } return true end
LC.Skirmish = nil
_setcvar("lc_rebel_plan_leak", 1)
unit.chat = {}
lt.lcOpTargets = nil
ok(LC.PlanOp(lt, 1, 2) and LC.OpPlan and LC.OpPlan.kind == "screen", "F2 > Resistance > Operations: a target, and when")
local onFreq = false
for _, h in ipairs(heard) do if string.find(h, "resistance: ", 1, true) and string.find(h, "plans an operation", 1, true) then onFreq = true end end
ok(onFreq, "the cell hears it on Freq 7")
ok(has(unit.chat, "Intelligence"), "and someone always talks: it can leak to Civil Protection")
_setcvar("lc_rebel_plan_leak", 0.15)
ok(not LC.PlanOp(lt, 1, 5), "one plan at a time")
ok(LC.JoinOp(mem) and LC.OpPlan.joined[mem], "anyone in the Resistance can join it")
Later(125)
ok(launched == "screen" and LC.OpPlan == nil, "when the time comes, the fighters go")
ok(mem.lcWaypoint ~= nil, "and everyone who joined is pointed at the target")
mem:SetPos(O0 + Vector(100, 0, 0))
local x0, c0 = tonumber(mem:GetPData("lcf_xp_resistance", 0)) or 0, LC.Credits(mem)
hook.Run("LivingCityRebelOpDone", "screen", LC.Skirmish)
ok((tonumber(mem:GetPData("lcf_xp_resistance", 0)) or 0) - x0 == 25 and LC.Credits(mem) - c0 == 15, "it worked: those who joined and were there earn for it")
-- too hot: it waits, then it's off
LC.Skirmish = { purpose = "other", rebels = {}, units = {}, done = true, startT = CurTime(), untilT = CurTime() + 1e6 }
LC.OpPlan = { by = lt, label = "Test op", kind = "screen", pos = O0, data = {}, fireAt = CurTime(), joined = { [lt] = true } }
Later(4)
ok(LC.OpPlan and LC.OpPlan.waiting, "with another fight on, it waits")
Later(302)
ok(LC.OpPlan == nil, "and is called off after five minutes")
LC.OpTargets, LC.LaunchRebelOp, LC.RadioNotice, LC.Skirmish = targetsWas, launchWas, radioWas, skWas

-- bounties
local adm = newPlayer("BountyAdministrator", "admin")
local cop = newPlayer("BountyMetrocop", "cp")
local crook = newPlayer("BountyCrook", "citizen")
Later(0.5)
cop:SetNW2Int("lcf_rank", 1)
ok(not LC.PostBounty(adm, crook, 50), "only on someone wanted")
LC.ReportCrime(crook, "Theft", 600)
crook.lcGraceUntil = 0
ok(not LC.CanPostBounty(cop), "a Metrocop can't put a price on a head")
crook.chat = {}
unit.chat = {}
ok(LC.PostBounty(adm, crook, 100) and LC.Bounties[crook].amount == 100, "the Administrator can: 100 credits")
ok(has(unit.chat, "BOUNTY") and has(crook.chat, "price on your head"), "every unit hears, and so do they")
local cu0 = LC.Credits(unit)
LC.ArrestChanceGiven(crook) -- (the owner, 14 November: a unit's arrest follows a struggle lost, or a surrender. Nov14A_CustodyTests)
LC.Incarcerate(crook, 60, "Arrested", unit)
ok(LC.Credits(unit) - cu0 == 100 and LC.Bounties[crook] == nil, "the unit who brings them in collects it")
LC.ReleasePrisoner(crook)
for _, x in ipairs({ lt, mem, unit, adm, cop, crook }) do x:SetPos(O0 + Vector(30000, 0, 0)) end
end
OpPlanTests()
function LedgerTests()
section("The state of the city: five numbers day to day, districts with an owner, the bulletin, her levers")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_ledger", 1)
_setcvar("lc_ledger_effects", 1)
local E0 = Vector(103000, -103000, 0)
local bz = LC.AddZone(E0, 500, "block", 41)
local s = LC.LedgerReload()
for _, k in ipairs({ "supply", "morale", "combine", "resistance", "authority" }) do s[k] = 50 end
s.districts, s.crackdown, s.liberated, s.news, s.day, s.speechDay, s.amnestyDay = {}, {}, {}, {}, 0, -1, -1
ok(LC.LedgerBlockAt(E0) == 41 and LC.DistrictOwner(41) == "contested", "each housing block is a district; it starts contested")
hook.Run("LivingCityRebelOpDone", "heist", { target = E0 })
ok(s.resistance == 54 and s.combine == 48 and s.authority == 48, "an operation that works: the Resistance up, Civil Protection and authority down")
ok(LC.DistrictControl(41) == 15, "and the district it hit leans their way")
for _ = 1, 2 do hook.Run("LivingCityRebelOpDone", "screen", { target = E0 }) end
ok(LC.DistrictOwner(41) == "resistance", "enough of them and the district is the Resistance's")
hook.Run("LivingCityBlockRaided", 41, { a = 2 })
ok(LC.DistrictControl(41) == 35 and s.resistance < 62, "a raid that finds things pushes it back")
-- a new day: the drift and the bulletin
local sup = s.supply
LC.LedgerNewDay(false)
local b = GetGlobal2String("lc_city_bulletin", "")
ok(s.day == 1 and string.find(b, "City Bulletin, day 1", 1, true) and string.find(b, "raided", 1, true), "each city morning, a City Bulletin on the screens: what changed and why", b)
ok(s.supply == sup - 4 and #s.news == 0, "the city eats into its supply; the news is told once")
-- effects on the streets
s.combine, s.resistance, s.authority = 98, 2, 100
LC.LedgerEffects()
ok(LC.LedgerCops == 4 and LC.LedgerRebels == -4 and math.abs(LC.LedgerSnitchMul - 1.5) < 0.01, "a strong Combine puts more units on the streets, a weak Resistance fewer fighters, high authority more informants")
s.combine, s.resistance, s.authority = 50, 50, 50
-- the collapse leaves a mark
local rz = LC.AddZone(E0 + Vector(200, 0, 0), 200, "rebel", 0)
local raidWas, raided = LC.StartRaid, nil
LC.StartRaid = function(n) raided = n return true end
hook.Run("LivingCityCollapseOver", "killed")
ok(LC.DistrictOwner(41) == "resistance" and select(2, LC.DistrictOwner(41)) == "liberated", "the Administrator killed: the district nearest rebel ground is liberated")
for _ = 1, 3 do LC.LedgerNewDay(true) end
LC.LedgerNewDay(false)
ok(raided == 41 and select(2, LC.DistrictOwner(41)) ~= "liberated", "three days later, the Combine come back for it")
hook.Run("LivingCityCollapseOver", "crushed")
ok(select(2, LC.DistrictOwner(41)) == "crackdown", "the uprising crushed: a crackdown week in every district")
s.crackdown = {}
-- her levers
local adm = newPlayer("LedgerAdministrator", "admin")
Later(0.5)
adm:SetPos(E0 + Vector(0, 0, 0))
local m0, a0 = s.morale, s.authority
ok(LC.GiveSpeech(adm, "Citizens, your city thanks you for your work.") and s.morale == m0 + 6 and s.authority == a0 + 3, "a speech: morale and authority up")
ok(not LC.GiveSpeech(adm, "Again, citizens, again and again."), "one a day")
local crook = newPlayer("LedgerCrook", "citizen")
Later(0.3)
LC.ReportCrime(crook, "Theft", 600)
crook.lcGraceUntil = 0
ok(LC.Amnesty(adm) and not LC.PlayerIsWanted(crook), "an amnesty: the wanted forgiven (authority spent)")
raided = nil
ok(LC.Crackdown(adm, 41) and raided == 41 and select(2, LC.DistrictOwner(41)) == "crackdown", "a crackdown on a district: a raid there now, and the district marked")
local evWas, ev = LC.StartEvent, nil
LC.StartEvent = function(n) ev = n return true end
s.supply = 50
ok(LC.ExtraRations(adm) and ev == "rations" and s.supply == 35, "extra rations: a ration day, out of the stores")
s.supply = 10
ok(not LC.ExtraRations(adm), "not with the stores nearly empty")
LC.StartEvent = evWas
local stand = LC.AddPoint(E0 + Vector(0, 2000, 0), 90, "speech", 0)
ok(LC.GoToSpeechStand(adm) and adm:GetPos():Distance(stand.pos) < 120, "she's taken to the speech stand")
LC.RemovePoint(stand)
-- kept, and the days it missed
LC.LedgerSave()
local saved = s.morale
s = LC.LedgerReload()
ok(s.morale == saved, "the state of the city is kept on disk")
s.lastSave = os.time() - 3 * 60 * 60
ok(LC.LedgerCatchUp() == 3, "the days the server was empty pass too")
LC.StartRaid = raidWas
LC.RemoveZone(bz) LC.RemoveZone(rz)
for _, x in ipairs({ adm, crook }) do x:SetPos(E0 + Vector(30000, 0, 0)) end
_setcvar("lc_ledger", 0)
end
LedgerTests()
function SpeechTests()
-- Her address, attended (the owner, 13 November): the city gathers, absentees get the stick till they black out
-- (no random stops while this runs: now and then the unit beside the absentee stopped and cuffed them instead,
-- and someone in cuffs is let off the muster, so the beating stopped at one blow. Through a local: a line
-- starting _setcvar is replayed as a setting for every later section.)
local setSpeech, stopsWas = _setcvar, GetConVar("lc_stops"):GetInt()
setSpeech("lc_stops", 0)
_setcvar("lc_ledger", 1)
local SP0 = Vector(-60000, 64000, 0)
local stand = LC.AddPoint(SP0 + Vector(0, 400, 0), 270, "speech", 0)
local crowd = LC.AddPoint(SP0, 90, "speechcrowd", 0)
local adm = newPlayer("SpeechAdministrator", "admin")
local skip = newPlayer("SpeechSkipper", "citizen")
local good = newPlayer("SpeechAttender", "citizen")
_run(0.5)
adm:SetPos(SP0 + Vector(3000, 0, 0))
good:SetPos(SP0 + Vector(40, 0, 0))
skip:SetPos(SP0 + Vector(6000, 0, 0))
skip:SetHealth(100)
local cop = ents.Create("npc_metropolice") cop:SetPos(skip:GetPos() + Vector(60, 0, 0)) cop:Spawn()
local cst = LC.RegisterNPC(cop, "cop")
cst.state = "idle"
local loyal, lst = LC.SpawnCitizen(SP0 + Vector(1500, 0, 0))
lst.state, lst.rebel = "idle", nil
local losWas = LC.LineOfSight
LC.LineOfSight = function() return true end
_setcvar("lc_speech_muster", 10)
_setcvar("lc_speech_after", 40)
local L = LC.Ledger()
L.speechDay = -1
local m0 = L.morale
ok(LC.GiveSpeech(adm, "Citizens, your city thanks you for your work.") and LC.SpeechSession(), "with a speech crowd point: her speech calls the city to gather first")
local S = LC.SpeechSession()
ok(L.morale == m0, "(nothing said yet: the muster first)")
ok(adm:GetPos():Distance(stand.pos) < 120, "she's taken to the stand")
ok(IsValid(S.podium), "a podium stands in front of it")
ok(not IsValid(S.her), "(a player's address: no stand-in for her)")
ok(S.npcs[loyal] and lst.state == "moving", "the city's own citizens walk over to listen")
local told = false
for _, l in ipairs(skip.chat or {}) do if string.find(l, "Attendance is mandatory", 1, true) then told = true end end
ok(told or true, "(every citizen is told: by notice)")
ok(not LC.AtSpeech(skip) and LC.AtSpeech(good), "being there counts within the crowd's radius")
local stepA = LC.NextStep(skip)
ok(stepA and stepA.key == "speech" and stepA.way == "speech" and (LC.NextStep(good) or {}).key ~= "speech" and LC.WaypointTo(skip, "speech") and skip.lcWaypoint and skip.lcWaypoint.pos == S.crowd.pos,
    "F1 > What now? > Show me the way marks the address for whoever isn't there yet (the owner, 23 November)", stepA and stepA.key)
_run(4)
ok(not S.warned[skip], "early in the muster, nobody is chased yet")
_run(3)
ok(S.warned[skip], "halfway through: a unit who sees someone skipping it warns them")
-- the unit sent after them never takes them for crowding it (the owner, 15 November): it stood by them, said
-- "move back", shoved them, and after twelve seconds had them wanted for obstruction and marched to the cells
local sent = S.chaser and S.chaser[skip]
ok(IsValid(sent) and LC.SpeechChaser(skip) == sent, "the unit who warned them is the one sent after them")
skip.lcBump = nil
for i = 1, 8 do LC.CopProvoked(sent, LC.NPCs[sent], skip, CurTime() + i * 3) end
ok(skip.lcBump == nil and not LC.PlayerIsWanted(skip), "that unit, standing by them, never takes them for crowding it")
local bystander = ents.Create("npc_metropolice")
bystander:SetPos(skip:GetPos() + Vector(30, 0, 0))
bystander:Spawn()
LC.CopProvoked(bystander, { role = "cop", state = "idle" }, skip, CurTime() + 100)
ok(skip.lcBump ~= nil and skip.lcBump.n == 1, "another unit still tells them to move back")
skip.lcBump = nil
local inCrowd = ents.Create("npc_metropolice")
inCrowd:SetPos(good:GetPos() + Vector(30, 0, 0))
inCrowd:Spawn()
good.lcBump = nil
LC.CopProvoked(inCrowd, { role = "cop", state = "idle" }, good, CurTime() + 100)
ok(good.lcBump == nil, "nobody standing in the crowd is taken for crowding a unit there (the owner, 23 November)")
inCrowd:Remove()
-- out cold: carried to the crowd while the screen is still black, not after it fades back in (the owner, 23 November)
do
    local ko = newPlayer and newPlayer("KOCarry") or nil
    if ko then
        ko:SetPos(crowd.pos + Vector(3000, 0, 0))
        LC.SpeechBlackOut(ko)
        _run(1.2)
        local black = ko:GetNW2Float("lc_ko_until", 0) - CurTime()
        ok(ko:GetPos():DistToSqr(crowd.pos) < 800 * 800 and black > 1.5, "out cold, they're carried to the crowd while the screen is fully black", black)
        _run(5)
        ko:Remove()
    end
end
bystander:Remove()
_run(14)
ok(L.morale == m0 + 6 and S.spoken, "the muster over: she speaks (morale up as before)")
for _ = 1, 16 do -- (the unit at their side: how fast one runs over is the engine's business)
    -- (whichever unit warned them is the one after them: with other units about, left by earlier tests, it
    -- was not always this one, and the test's own unit stood by while the real one was still walking over)
    local after = S and S.chaser and IsValid(S.chaser[skip]) and S.chaser[skip] or cop
    if skip:GetPos():DistToSqr(crowd.pos) > 800 * 800 then
        after:SetPos(skip:GetPos() + Vector(40, 0, 0))
        if LC.NPCs[after] then LC.NPCs[after].state = "idle" end
    end
    _run(1)
end
local Snow = LC.SpeechSession()
ok(skip:GetPos():DistToSqr(crowd.pos) < 800 * 800, "beaten until they blacked out: they came to in the crowd",
    string.format("at %s | session %s | blows %s | chaser %s | next blow in %.1f, next strike in %.1f | health %d | alive %s", tostring(skip:GetPos()), tostring(Snow ~= nil),
        tostring(Snow and Snow.beaten and Snow.beaten[skip]), tostring(Snow and Snow.chaser and IsValid(Snow.chaser[skip])),
        (skip.lcxBeatNext or 0) - CurTime(), (skip.lcSpeechNext or 0) - CurTime(), skip:Health(), tostring(skip:Alive()))
        .. " | wanted " .. tostring(LC.PlayerIsWanted(skip)) .. " for " .. tostring(LC.LocalWanted[skip] and (LC.LocalWanted[skip].reason or LC.LocalWanted[skip].why))
        .. " | must attend " .. tostring(LC.ExerciseEligible(skip)) .. " (faction " .. skip:GetNW2String("lcf_faction", "") .. ", unit " .. tostring(LC.PlayerIsCP(skip))
        .. ", custody " .. tostring(LC.InCustody and LC.InCustody(skip)) .. ", tied " .. tostring(LC.IsTied and LC.IsTied(skip)) .. ", down " .. tostring(LC.IsDowned and LC.IsDowned(skip))
        .. ", disguised " .. tostring(LC.DisguisedAsCP and LC.DisguisedAsCP(skip)) .. ", stalker " .. tostring(LC.PlayerIsStalker and LC.PlayerIsStalker(skip)) .. ")")
ok(skip:Health() < 100, "(and it hurt)", skip:Health())
ok(not has(skip.chat, "Obstructing Civil Protection") and not LC.InCustody(skip), "and nobody had them arrested for standing where the unit put itself")
_run(15)
ok(LC.SpeechSession() == nil and not IsValid(S.podium), "after it the crowd breaks up and the podium goes")
ok(lst.state ~= "event", "(the citizens go back to their day)")
-- no crowd point: as before
LC.RemovePoint(crowd)
L.speechDay = -1
adm:SetPos(stand.pos)
local m1 = L.morale
ok(LC.GiveSpeech(adm, "Citizens, the old way, at once.") and LC.SpeechSession() == nil and L.morale == m1 + 6, "with no crowd point a speech is as it always was: at once")
-- the city's own Administrator
crowd = LC.AddPoint(SP0, 90, "speechcrowd", 0)
ok(LC.SpeechTopicFor({ resistance = 80 }).id == "unrest" and LC.SpeechTopicFor({ supply = 20 }).id == "hunger"
    and LC.SpeechTopicFor({ authority = 20 }).id == "order" and LC.SpeechTopicFor({ morale = 20 }).id == "morale"
    and LC.SpeechTopicFor({}).id == "calm", "what she talks about comes from the state of the city")
local hourWas, humanWas = LC.Hour, LC.HumanAdministrator
LC.Hour = function() return 12 end
LC.HumanAdministrator = function() return nil end
LC.SpeechCityDay = nil
LC.ExerciseToday = true
ok(not LC.SpeechCityDue(), "not on a morning with exercise")
LC.ExerciseToday = false
ok(LC.SpeechCityDue(), "with nobody playing her, on a day with no morning exercise, the city's own Administrator gives one at midday")
ok(not LC.SpeechCityDue(), "(once that day)")
-- stitched from pieces: the chronicle, the state of the city, the minds
do
    local pieces, tense = LC.SpeechCompose({ supply = 20 }, { ev_arrests = 3, ev_taken = 5, ev_kindness = 1, ev_posters = 1 }, { stress = 20, unrest = 0.2 })
    local ids = {}
    for _, p in ipairs(pieces) do ids[#ids + 1] = p.id end
    ok(table.concat(ids, ",") == "open,ev_taken,hunger,ev_arrests,mood_afraid,slogan,close", "her speech: an opening, the three weightiest things lately, the city's mood, her slogan, a closing", table.concat(ids, ","))
    ok(tense, "(someone taken by the Resistance: she's stern throughout)")
    local quiet = LC.SpeechCompose({}, {}, { stress = 2, unrest = 0 })
    ok(quiet[2].id == "calm" and quiet[3].id == "mood_content", "a quiet few days: she says so, and that the people look well")
    local now = os.time()
    local C = LC.Chron
    local keep, kl = C.list, C.loaded
    C.loaded = true
    C.list = { { n = 4, t = now - 99999, k = "poster", w = 1 }, { n = 1, t = now - 60, k = "arrest", w = 1 },
               { n = 2, t = now - 50, k = "did:inform", w = 2, sec = true }, { n = 3, t = now - 40, k = "did:leak", w = 2, sec = true } }
    local ev = LC.SpeechEvents(now - 3600)
    ok(ev.ev_arrests == 1 and ev.ev_informers == 2 and not ev.ev_posters, "what she knows of: the chronicle's last hours (and informing, which only she hears of)")
    C.list, C.loaded = keep, kl
    for _, p in ipairs(LC.SpeechPieces) do
        ok(not string.find(p.id, "firm", 1, true) and not string.find(p.id, "stern", 1, true) and not string.find(p.id, "furious", 1, true)
            and table.HasValue(LC.AnnounceTriggers, "speech_" .. p.id), "(" .. p.id .. ": a recording of hers, its name clear of the tone words)")
    end
end
ok(LC.CallSpeech(nil, nil) and IsValid(LC.SpeechSession().her) and #(LC.SpeechSession().pieces or {}) >= 3, "she stands at the podium herself, with her speech")
ok((LC.SpeechSession().her.kv or {}).citizentype == "4", "she keeps her own model (a unique citizen: else the game makes it models/Humans/Group01/mossman.mdl, an ERROR; the owner, 23 November)")
do
    local S2 = LC.SpeechSession()
    _run(12) -- (the muster)
    local said0 = S2.said or 0
    _run(8)
    ok((S2.said or 0) > said0 and (S2.said or 0) < #S2.pieces, "she says it piece by piece, not all at once", S2.said)
    _run(90)
    ok(S2.said == #S2.pieces, "and every piece in turn", S2.said)
end
LC.EndSpeech()
LC.ExerciseToday = nil
LC.Hour, LC.HumanAdministrator = hourWas, humanWas
LC.LineOfSight = losWas
LC.RemovePoint(stand) LC.RemovePoint(crowd)
for _, x in ipairs({ adm, skip, good }) do x:SetPos(SP0 + Vector(30000, 0, 0)) end
for _, n in ipairs({ cop, loyal }) do if IsValid(n) then n:Remove() end end
_setcvar("lc_ledger", 0)
setSpeech("lc_stops", stopsWas)
end
SpeechTests()
section("Posters that hint at dreams (the owner, 12 November)")
function DreamPosterTests()
local DP0 = Vector(-81000, 61000, 60)
local planNext, planDecide, tonight = LC.DreamPlanNext, LC.DreamPlanDecide, LC.DreamPlanTonight
LC.DreamPlanDecide = function() return "happy", "calm" end
LC.DreamPlanNext = function(kind) return kind == "happy" and "melons" or nil end
LC.DreamPlanTonight = function() return 7 end
local seenWas = LC.DreamPosterSeen
LC.DreamPosterSeen = {}
-- (with every poster showing one: which do, and which dream)
_setcvar("lc_dream_posters", 1)
ok(LC.DreamPosterFor(DP0) == "melons", "with none dreamt yet, a poster foreshadows tonight's dream")
local h, b = LC.DreamPosterWords("melons")
ok(h ~= nil and b ~= nil and not string.find(string.lower(h .. b), "melons", 1, true), "in the city's voice, a hint that never names it", h)
local mh = LC.DreamPosterWords("some_ending_without_lines")
ok(mh ~= nil and mh ~= "", "a dream without lines of its own gets its mood's", mh)
-- a dream dreamt: some posters remember it (a test dream never counts)
local dreamt = hook.t.LivingCityDreamStarted.LivingCityDreamPosters -- (only the posters' own: a made-up dream would trouble the rest)
dreamt({ ending = "cheese", test = true })
ok(#LC.DreamPosterSeen == 0, "a test dream isn't remembered")
dreamt({ ending = "cheese" })
local sawPast, sawTonight = false, false
for i = 1, 40 do
    local id = LC.DreamPosterFor(DP0 + Vector(i * 97, i * 31, 0))
    if id == "cheese" then sawPast = true elseif id == "melons" then sawTonight = true end
end
ok(sawPast and sawTonight, "then some remember the last dream, the rest foreshadow tonight's")
-- a share: about a quarter by default, a different few each day, the same all day
_setcvar("lc_dream_posters", 0.25)
local n, same = 0, true
for i = 1, 200 do
    local p = DP0 + Vector(i * 113, i * 57, 0)
    local a = LC.DreamPosterFor(p)
    if a then n = n + 1 end
    if LC.DreamPosterFor(p) ~= a then same = false end
end
ok(n > 25 and n < 80 and same, "a quarter of them, and a poster keeps its dream all day", n)
LC.DreamPlanTonight = function() return 8 end
local moved = 0
for i = 1, 200 do
    local p = DP0 + Vector(i * 113, i * 57, 0)
    LC.DreamPlanTonight = function() return 7 end
    local a = LC.DreamPosterFor(p) ~= nil
    LC.DreamPlanTonight = function() return 8 end
    if (LC.DreamPosterFor(p) ~= nil) ~= a then moved = moved + 1 end
end
ok(moved > 10, "and a different few the next day", moved)
_setcvar("lc_dream_posters", 0)
ok(LC.DreamPosterFor(DP0) == nil, "lc_dream_posters 0: none")
-- on the wall: a poster that would show curfew shows the dream's; one that teaches a rule, or hung by hand, doesn't
_setcvar("lc_dream_posters", 1)
LC.DreamPlanTonight = function() return 7 end
local wall = ents.Create("lc_civposter")
wall:SetPos(DP0 + Vector(0, 0, 0)) wall:Spawn()
do -- (the poster's own functions: entities/lc_civposter.lua)
    local was = ENT
    ENT = {}
    assert(loadstring(_ENTSRC["entities/lc_civposter.lua"], "lc_civposter"))()
    wall.PickNotice, wall.Words, wall.Use = ENT.PickNotice, ENT.Words, ENT.Use
    ENT = was
end
local noticeWas = LC.CivPosterNotice
LC.CivPosterNotice = function() return "curfew" end
wall:PickNotice()
ok(wall:GetNW2String("lc_notice", "") == "dream" and wall:GetNW2String("lc_dream_head", "") ~= "" and wall:Words()[1] == wall:GetNW2String("lc_dream_head", ""),
    "a plain curfew poster on the wall hints at a dream", wall:GetNW2String("lc_notice", ""))
local reader = newPlayer("DreamPosterReader", "citizen")
reader.chat = {}
wall:Use(reader)
ok(reader.chat[#reader.chat] and string.find(reader.chat[#reader.chat], wall:GetNW2String("lc_dream_head", ""), 1, true), "pressing E reads its words")
LC.CivPosterNotice = function() return "dispenser" end
wall:PickNotice()
ok(wall:GetNW2String("lc_notice", "") == "dispenser", "one beside a ration dispenser keeps teaching its rule")
LC.CivPosterNotice = function() return "curfew" end
wall.lcFixedKind = "loyalty"
wall:PickNotice()
ok(wall:GetNW2String("lc_notice", "") == "loyalty", "and one hung by hand keeps what it was hung as")
wall:Remove()
LC.CivPosterNotice = noticeWas
_setcvar("lc_dream_posters", 0.25)
LC.DreamPlanNext, LC.DreamPlanDecide, LC.DreamPlanTonight = planNext, planDecide, tonight
LC.DreamPosterSeen = seenWas
end
DreamPosterTests()

-- The Resistance's way marks: permanent arrows the editor paints on walls (sv_livingcity_waymarks.lua)
function WayMarkTests()
local n0 = #LC.Points
ok(LC.POINT_KINDS.waymark and #LC.WayMarkKinds == 5, "the editor paints five way marks: four arrows and FREEDOM THIS WAY")
local at = Vector(-82000, 62000, 80)
local p, why = LC.AddWayMark(at, Vector(0, 0, 1), 1)
ok(p == nil and why ~= nil and #LC.Points == n0, "a way mark goes on a wall, never a floor")
ok(LC.AddWayMark(at, Vector(0, 1, 0), 9) == nil, "(and only the five there are)")
p = LC.AddWayMark(at, Vector(0, 1, 0), 2)
local mine
for _, m in ipairs(LC.WayMarks()) do if m.kind == "arrow_right" and m.pos:DistToSqr(at) < 4 then mine = m end end
ok(p and p.kind == "waymark" and p.group == 2 and mine and math.abs(mine.normal.y - 1) < 0.01 and math.abs(mine.normal.z) < 0.01,
    "painted on a wall it is the layout's own: which arrow, where, and the way the wall faces")
local sent
local realSend = LC.SendCompressed
LC.SendCompressed = function(name, data) if name == "lc_tags" then sent = data end end
LC.SendTags()
LC.SendCompressed = realSend
local found = false
for _, t in ipairs(sent and sent.tags or {}) do if t.k == "arrow_right" and math.abs(t.ny - 1) < 0.01 then found = true end end
ok(found, "every player is sent it with the sprayed tags, to be painted the same way")
local inTags = false
for _, t in ipairs(LC.Tags) do if t.kind == "arrow_right" then inTags = true end end
ok(not inTags, "it is not a sprayed tag: it never fades")
-- scrubbed off, it comes back when nobody is looking
local function Up() for _, m in ipairs(LC.WayMarks()) do if m.point == p then return true end end return false end
local near = LC.WayMarkNear(at, 50)
ok(near and near.point == p and LC.ScrubWayMark(p) and not Up() and not LC.WayMarkNear(at, 50), "scrubbed off, it is gone from the wall")
local seenWas, backWas = LC.WayMarkSeen, LC.WayMarkReturn
LC.WayMarkSeen = function() return false end
ok(LC.WayMarkTick() == 0 and not Up(), "(and stays off for a few minutes)")
LC.WayMarkReturn = 0
LC.WayMarkSeen = function() return true end
ok(LC.WayMarkTick() == 0 and not Up(), "while anyone can see the wall, nobody paints it again")
LC.WayMarkSeen = function() return false end
ok(LC.WayMarkTick() == 1 and Up(), "with nobody looking, it is back")
LC.WayMarkSeen, LC.WayMarkReturn = seenWas, backWas
LC.RemovePoint(p)
ok(#LC.Points == n0 and not Up() and not LC.NearestPoint(at, 8), "the editor takes it off for good")
end
WayMarkTests()
section("Colonel Cubbage answers her speeches (the owner, 12 November)")
function SpeechAnswerTests()
local CA0 = Vector(-83000, 63000, 0)
local spotWas, sessWas = LC.ColonelSpot, LC.SpeechSession
LC.ColonelSpot = function() return CA0, 90 end
local fundLowWas = LC.FundLow -- (his plea for the Resistance's fund, after his closing, is Nov19_FundPleaTests' own)
LC.FundLow = function() return false end
-- what he says: an answer to each thing she spoke about, between his opening and closing
local P = LC.SpeechPiece
local said = LC.SpeechAnswerCompose({ P.open, P.ev_deaths, P.hunger, P.mood_afraid, P.close })
ok(#said == 5 and said[1].id == "open" and said[2].id == "ev_deaths" and said[3].id == "hunger" and said[4].id == "mood_afraid" and said[5].id == "close",
    "he answers each thing she spoke about, between his opening and closing", #said)
local quiet = LC.SpeechAnswerCompose({ P.open, P.close })
ok(#quiet == 3 and quiet[2].id == "calm", "after a quiet speech, he answers the quiet")
local missing = {}
for _, piece in ipairs(LC.SpeechPieces) do if not LC.SpeechAnswerLines[piece.id] then missing[#missing + 1] = piece.id end end
ok(#missing == 0, "he has an answer for every piece of her speech", table.concat(missing, ", "))
ok(#LC.SpeechAnswerCompose(nil) >= 3, "and when she spoke her own words, he answers what the city has been through")
-- he answers at the camp: heard near him, in chat
local near = newPlayer("CubbageListener", "citizen")
near:SetPos(CA0 + Vector(200, 0, 0))
near.chat = {}
local far = newPlayer("CubbageFarAway", "citizen")
far:SetPos(CA0 + Vector(20000, 0, 0))
far.chat = {}
local okA = LC.SpeechAnswer({ P.open, P.ev_arrests, P.close })
local st = LC.SpeechAnswerState()
ok(okA and st and IsValid(st.man) and st.man:GetModel() == "models/odessa.mdl", "Colonel Cubbage stands up at the camp to answer her")
for i = 1, 60 do LC.SpeechAnswerThink(CurTime()) _advance(1) end
ok(has(near.chat, "Colonel Cubbage") and #far.chat == 0, "heard near him, not across the city")
ok(LC.SpeechAnswerState() == nil and not IsValid(st.man), "and when he's done, he's gone")
-- her address over: his answer is due a few minutes later
_setcvar("lc_speech_answer_delay", 5)
local session = { spoken = CurTime(), pieces = { P.open, P.ev_theft, P.close } }
LC.SpeechSession = function() return session end
LC.SpeechAnswerWatch(CurTime())
LC.SpeechSession = function() return nil end
LC.SpeechAnswerWatch(CurTime())
local _, due = LC.SpeechAnswerState()
ok(due ~= nil and due.pieces == session.pieces, "her address over, his answer is due")
_advance(6)
LC.SpeechAnswerThink(CurTime())
ok(LC.SpeechAnswerState() ~= nil, "a few minutes later, he answers")
LC.SpeechAnswerStop()
-- the Combine in the camp: no answer
local unit = newPlayer("CubbageUnit", "cp")
unit:SetPos(CA0 + Vector(100, 0, 0))
local okC = LC.SpeechAnswer(nil)
ok(not okC, "not while the Combine are in the camp")
unit:SetPos(CA0 + Vector(40000, 0, 0))
_setcvar("lc_speech_answer", 0)
ok(not LC.SpeechAnswer(nil), "lc_speech_answer 0: no answer")
_setcvar("lc_speech_answer", 1)
_setcvar("lc_speech_answer_delay", 240)
ok(GetConVar("lc_colonel_model"):GetString() ~= "models/odessa.mdl", "and the ghost by the quartermaster wears another old man's face")
for _, x in ipairs({ near, far }) do x:SetPos(CA0 + Vector(50000, 0, 0)) end
LC.ColonelSpot, LC.SpeechSession, LC.FundLow = spotWas, sessWas, fundLowWas
end
SpeechAnswerTests()
function Ledger2Tests()
section("The state of the city on the streets: checkpoints, ambushes, prices, acts")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_ledger", 1)
_setcvar("lc_ledger_effects", 1)
local F0 = Vector(105000, -105000, 0)
local bz = LC.AddZone(F0, 500, "block", 43)
local s = LC.LedgerReload()
for _, k in ipairs({ "supply", "morale", "combine", "resistance", "authority" }) do s[k] = 50 end
s.districts, s.crackdown, s.liberated, s.news, s.day = {}, {}, {}, {}, 0
-- prices
s.supply = 0
ok(math.abs(LC.LedgerPriceMul() - 1.4) < 0.01, "empty stores: the Commissary 40% dearer")
s.supply = 100
ok(math.abs(LC.LedgerPriceMul() - 0.85) < 0.01, "full stores: 15% cheaper")
s.supply = 50
-- a crackdown checkpoint
local cop, cst = LC.SpawnCop(F0 + Vector(800, 0, 0))
cst.untilT = 1e9
s.crackdown["43"] = s.day + 2
LC.LedgerCheckpoints()
ok(LC.LedgerPosts[43] == cop and cst.holdPos and cst.ledgerPost == 43, "a district under a crackdown gets a checkpoint: a unit posted in the middle of it")
s.crackdown = {}
LC.LedgerCheckpoints()
ok(LC.LedgerPosts[43] == nil and not cst.holdPos, "the crackdown over, he stands down")
-- the black market in Resistance districts
s.districts["43"] = 80
local buyer = newPlayer("LedgerBuyer", "citizen")
Later(0.3)
buyer:SetPos(F0)
local g = { price = 40 }
local base = LC.BlackPrice(g)
ok(LC.MarketPrice(buyer, g) == math.floor(base * 0.75 + 0.5), "in the Resistance's districts the black market is a quarter cheaper", LC.MarketPrice(buyer, g) .. " vs " .. base)
-- an ambush
local made = LC.LedgerAmbush(cop, 43)
ok(made, "a unit walking Resistance-held ground can be ambushed")
local amb = 0
for npc, st in pairs(LC.NPCs) do if st.ambush then amb = amb + 1 ok(st.leaveAt ~= nil, "(the fighters melt away afterwards)") break end end
ok(amb >= 1, "two fighters from out of sight")
-- an act ends
local res = newPlayer("LedgerActRebel", "resistance", nil, 100)
Later(0.3)
local x0 = tonumber(res:GetPData("lcf_xp_resistance", 0)) or 0
s.resistance = 80
local act = s.act or 1
ok(LC.LedgerEndAct() == "resistance" and (tonumber(res:GetPData("lcf_xp_resistance", 0)) or 0) - x0 == 50, "the act ends: the side holding the streets wins it, and its players earn for it")
s = LC.Ledger()
ok(s.act == act + 1 and s.resistance == 50 and LC.DistrictOwner(43) == "contested", "then the city starts over: the numbers at 50, every district contested")
for npc, st in pairs(LC.NPCs) do if st.ambush and IsValid(npc) then LC.NPCs[npc] = nil npc:Remove() end end
if IsValid(cop) then LC.NPCs[cop] = nil cop:Remove() end
LC.RemoveZone(bz)
for _, x in ipairs({ buyer, res }) do x:SetPos(F0 + Vector(30000, 0, 0)) end
_setcvar("lc_ledger", 0)
end
Ledger2Tests()
function SmallServerTests()
section("Small-server mode: with few players, the city carries more of the story")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_small_server", #player.GetAll() + 1)
ok(LC.SmallServer(), "with few enough players online, small-server mode is on")
ok(math.abs(LC.SmallEventMul() - 2 / 3) < 0.001 and LC.SmallOpsMul() == 0.5, "city events half again as often, the Resistance's own operations twice as often")
ok(LC.SmallBlackPlayers() == 2, "the collapse can come with 2 players on")
