Later(0.3)
m:SetNW2Int("lcf_rank", 2)
for _, p in ipairs(player.GetAll()) do if p ~= m and p:GetNW2String("lcf_faction", "") == "resistance" then p:SetNW2Int("lcf_rank", 1) end end
