function StatusTests()
section("Things other people can see: fine clothes, home decor, a radio set, a pet bird")
local function Later(secs) _advance(secs) _runtimers() end
local G0 = Vector(107000, -107000, 0)
local p = newPlayer("StatusCitizen", "citizen")
local q = newPlayer("StatusNeighbour", "citizen")
local unit = newPlayer("StatusUnit", "cp")
Later(0.5)
p:SetModel("models/player/group01/male_04.mdl")
LC.GiveItem(p, "fine_clothes", 1)
ok(LC.ItemUse(p, "fine_clothes") and string.find(p:GetModel(), "group02", 1, true) and p:GetNW2Bool("lc_well_dressed", false), "fine clothes: the better-dressed look", p:GetModel())
ok(string.find(LC.LegacyTitle(p) or "", "Well dressed", 1, true), "and \"Well dressed\" with their title")
LC.ItemUse(p, "fine_clothes")
ok(p:GetModel() == "models/player/group01/male_04.mdl" and not p:GetNW2Bool("lc_well_dressed", true), "taken off, the old clothes back")
LC.GiveItem(unit, "fine_clothes", 1)
ok(not LC.ItemUse(unit, "fine_clothes"), "not over a uniform")
-- the bird
LC.GiveItem(p, "pet_bird", 1)
LC.ItemUse(p, "pet_bird")
ok(p:GetNW2Bool("lc_pet_bird", false), "a pet bird on the shoulder, for everyone to see")
LC.TakeItem(p, "pet_bird", 1)
hook.Run("LivingCityInventoryChanged", p)
ok(not p:GetNW2Bool("lc_pet_bird", true), "sold or lost, it's gone from the shoulder")
-- decor
local inOwn = LC.PlayerInOwnBlock
LC.PlayerInOwnBlock = function(ply) return ply == p end
p:SetPos(G0)
p.GetEyeTrace = function() return { Hit = true, HitPos = G0 + Vector(60, 0, 0), HitNormal = Vector(0, 0, 1) } end
q.GetEyeTrace = p.GetEyeTrace
LC.GiveItem(q, "decor_lamp", 1)
ok(not LC.ItemUse(q, "decor_lamp"), "decor goes down only at home, in your own block")
LC.Decor = {}
LC.GiveItem(p, "decor_lamp", 1)
ok(LC.ItemUse(p, "decor_lamp") and #LC.Decor == 1 and IsValid(LC.Decor[1].ent) and not LC.HasItem(p, "decor_lamp"), "a desk lamp set down at home")
local lamp = LC.Decor[1].ent
q.chat = {}
LC.UseDecor(q, lamp)
ok(IsValid(lamp) and has(q.chat, "Not yours"), "nobody else can take it")
LC.GiveItem(p, "radio_set", 1)
LC.ItemUse(p, "radio_set")
local radio = LC.Decor[2].ent
LC.UseDecor(q, radio)
ok(radio.lcSong ~= nil, "a radio set: E plays music, for anyone")
LC.UseDecor(q, radio)
ok(radio.lcSong == nil, "and again stops it")
LC.SaveDecor()
LC.LoadDecor()
ok(#LC.Decor == 2 and IsValid(LC.Decor[1].ent), "decor stays where it was, across a restart")
lamp = LC.Decor[1].ent
LC.UseDecor(p, lamp)
ok(not IsValid(lamp) and #LC.Decor == 1 and LC.HasItem(p, "decor_lamp"), "E on your own piece takes it back")
_setcvar("lc_decor_max", 1)
ok(not LC.ItemUse(p, "decor_lamp"), "at most lc_decor_max pieces each")
_setcvar("lc_decor_max", 6)
for _, d in ipairs(LC.Decor) do if IsValid(d.ent) then d.ent:Remove() end end
LC.Decor = {}
LC.SaveDecor()
LC.PlayerInOwnBlock = inOwn
p.GetEyeTrace, q.GetEyeTrace = nil, nil
for _, x in ipairs({ p, q, unit }) do x:SetPos(G0 + Vector(30000, 0, 0)) end
end
StatusTests()
function HouseholdTests()
section("Households: the same block, shared crates and lockers, keys, known to each other")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_households", 1)
local H0 = Vector(109000, -109000, 0)
local a = newPlayer("HouseHead", "citizen")
local b = newPlayer("HouseMate", "citizen")
local c = newPlayer("HouseThird", "citizen")
local u = newPlayer("HouseUnit", "cp")
Later(0.5)
for i, p in ipairs({ a, b, c, u }) do p:SetNW2String("lc_cid", "HH-" .. i) p:SetPos(H0 + Vector(i * 40, 0, 0)) end
LC.HouseholdsReload()
for id in pairs(LC.HouseholdsReload()) do LC.HouseholdsReload()[id] = nil end
a:SetPData("lc_block_" .. game.GetMap(), 7) a:SetNW2Int("lc_block", 7)
ok(not LC.HouseholdInvite(a, u), "households are for citizens")
ok(LC.HouseholdInvite(a, b) and b:GetNW2String("lc_house_invite", "") ~= "", "F1 > Invite them into my household: they're asked")
ok(LC.HouseholdAccept(b, true), "and accept on F2 > Me > My household")
local id, h = LC.HouseholdOf(b)
ok(h and h.members["HH-1"] and h.members["HH-2"] and h.head == "HH-1", "a household: its head and the one who joined")
ok(string.find(h.name, "household", 1, true) ~= nil and b:GetNW2String("lc_household", "") ~= "", "with a name, shown to them", h.name)
ok(tonumber(b:GetPData("lc_block_" .. game.GetMap(), 0)) == 7, "they move into the head's block")
ok(LC.HouseholdShares(b, "HH-1") and LC.HouseholdShares(a, "HH-2") and not LC.HouseholdShares(c, "HH-1"), "and share crates and lockers (nobody else does)")
ok(not LC.HouseholdInvite(b, c), "only the head takes people in")
ok(LC.HouseholdRename(a, "The Kitchen Table") and select(2, LC.HouseholdOf(a)).name == "The Kitchen Table", "the head can name the household")
LC.HouseholdInvite(a, c) LC.HouseholdAccept(c, true)
ok(LC.HouseholdSendAway(a, LC.CharacterName and LC.CharacterName(c) or c:Nick()) and not LC.HouseholdOf(c), "the head can send someone away")
c:SetPos(H0 + Vector(5000, 0, 0))
ok(not LC.HouseholdInvite(a, c), "invitations are face to face")
LC.HouseholdLeave(b)
ok(not LC.HouseholdOf(b) and not LC.HouseholdOf(a), "a household of one is no household")
LC.HouseholdsReload()
for _, p in ipairs({ a, b, c, u }) do p:SetPos(H0 + Vector(30000, 0, 0)) end
end
HouseholdTests()
function EmploymentTests()
section("A business of your own: hand-made goods, the city's people buying, hiring a worker")
local function Later(secs) _advance(secs) _runtimers() end
local B0 = Vector(111000, -111000, 0)
local owner = newPlayer("StallOwner", "citizen")
local worker = newPlayer("StallWorker", "citizen")
Later(0.5)
owner:SetNW2String("lc_cid", "BZ-1") worker:SetNW2String("lc_cid", "BZ-2")
owner:SetPos(B0) worker:SetPos(B0 + Vector(60, 0, 0))
ok(LCS.RecipesById.rag_doll and LCS.RecipesById.tin_toy and LCS.RecipesById.patched_coat and LCS.Items.rag_doll.handmade, "hand-made goods anyone can make from rags and scrap")
local cs = LC.Containers()
local stall = { kind = "stall", items = { rag_doll = 2, tin_toy = 1 }, prices = { rag_doll = 20, tin_toy = 99 }, owner = "BZ-1", ownerName = "StallOwner", pos = B0, till = 0 }
cs["test_stall"] = stall
local cit, cst = LC.SpawnCitizen(B0 + Vector(300, 0, 0))
ok(LC.StallCustomer() and stall.items.rag_doll == 1 and stall.till == 20, "a passer-by buys a hand-made thing priced fairly; the money goes in the till")
stall.items.rag_doll = nil stall.prices.rag_doll = nil
ok(not LC.StallCustomer(), "but not when it's dear (half again its worth)")
-- hiring
ok(LC.OfferJob(owner, worker) and worker.lcJobOffer, "F1 > Offer them a job at my stall")
ok(LC.AcceptJob(worker, true) and LC.EmployerOf(worker) == "BZ-1", "accepted on F2 > Me: they work it now")
-- wages from the till
stall.till = 25
worker:SetPos(B0 + Vector(50, 0, 0))
worker.lcWorkedAt = 1
local w0 = LC.Credits(worker)
LC.PayStallWages()
ok(LC.Credits(worker) - w0 == 10 and stall.till == 15, "wages: paid from the till, for time spent at the stall")
worker.lcWorkedAt = 0
local w1 = LC.Credits(worker)
LC.PayStallWages()
ok(LC.Credits(worker) == w1, "no time at the stall, no pay")
ok(LC.LetGo(owner, LC.CharacterName and LC.CharacterName(worker) or worker:Nick()) and not LC.EmployerOf(worker), "the owner can let a worker go")
cs["test_stall"] = nil
if IsValid(cit) then LC.NPCs[cit] = nil cit:Remove() end
for _, x in ipairs({ owner, worker }) do x:RemovePData("lc_employer") x:SetPos(B0 + Vector(30000, 0, 0)) end
end
EmploymentTests()
function StreetCrimeTests()
section("Crime between citizens: pickpocketing, debts, deals that go bad")
local function Later(secs) _advance(secs) _runtimers() end
_setcvar("lc_pickpocket", 1)
local C0 = Vector(113000, -113000, 0)
local thief = newPlayer("Pickpocket", "citizen")
local mark = newPlayer("PickMark", "citizen")
local unit = newPlayer("PickUnit", "cp")
Later(0.5)
for i, p in ipairs({ thief, mark, unit }) do p:SetNW2String("lc_cid", "SC-" .. i) end
mark:SetPos(C0)
local fw = mark:GetForward()
thief:SetPos(C0 + fw * 60)
ok(not LC.Pickpocket(thief, mark), "not from in front, where they can see you")
thief:SetPos(C0 - fw * 50)
ok(not LC.Pickpocket(unit, mark), "a unit doesn't pick pockets")
LC.AddCredits(mark, 100 - LC.Credits(mark))
local c0, t0 = LC.Credits(mark), LC.Credits(thief)
local rnd = math.random
math.random = function(a, b) if a == nil then return 0.99 elseif b == nil then return rnd(a) end return rnd(a, b) end
ok(LC.Pickpocket(thief, mark), "from behind, close: F1 > Pick their pocket")
Later(3.5)
math.random = rnd
ok(LC.Credits(mark) < c0 or (LC.Credits(thief) > t0), "unnoticed: some of their credits (or a thing from their pockets)", LC.Credits(mark) .. " " .. LC.Credits(thief))
ok(not LC.Pickpocket(thief, mark), "not again so soon")
-- debts
local a, b = thief, mark
LC.AddCredits(a, 100 - LC.Credits(a)) LC.AddCredits(b, 0 - LC.Credits(b))
b:SetPos(C0 + Vector(40, 0, 0)) a:SetPos(C0)
ok(LC.OfferLoan(a, b, 25) and b.lcLoanOffer, "F1 > Lend them money: they're offered it")
ok(LC.AcceptLoan(b, true) and LC.Credits(a) == 75 and LC.Credits(b) == 25, "accepted: the money changes hands")
local nd = util.JSONToTable(b:GetPData("lc_debts", ""))
ok(nd and nd[1] and nd[1].owed == 30, "and they owe a fifth more back", nd and nd[1] and nd[1].owed)
LC.AddCredits(b, 10)
ok(LC.RepayDebt(b, 1) and LC.Credits(a) == 105 and b:GetPData("lc_debts", "") == "", "repaid: the lender gets it")
LC.OfferLoan(a, b, 10) LC.AcceptLoan(b, true)
local owes, lent = util.JSONToTable(b:GetPData("lc_debts", "")), util.JSONToTable(a:GetPData("lc_lent", ""))
owes[1].due, lent[1].due = os.time() - 10, os.time() - 10
b:SetPData("lc_debts", util.TableToJSON(owes)) a:SetPData("lc_lent", util.TableToJSON(lent))
b.lcGraceUntil = 0
ok(LC.ReportDebt(a, 1) and LC.PlayerIsWanted(b) and string.find(b:GetNW2String("lc_wanted_reason", ""), "Debt default", 1, true), "overdue: the lender can report it to Civil Protection")
LC.ClearWanted(b)
-- a deal gone bad
local access, atqm = LC.MarketAccess, LC.AtQuartermaster
LC.MarketAccess = function() return true end
LC.AtQuartermaster = function() return false end
local gid, gitem
for _, g in ipairs(LCS.Black or {}) do if g.item and not g.qm and not g.stock then gid, gitem = g.id, g.item break end end
_setcvar("lc_bad_deal_chance", 1)
LC.AddCredits(a, 1000)
local n0 = (LC.Inventory(a) or {})[gitem] or 0
math.random = function(x, y) if x == nil then return 0.1 elseif y == nil then return rnd(x) end return rnd(x, y) end
LC.BlackBuy(a, gid)
math.random = rnd
ok(((LC.Inventory(a) or {})[gitem] or 0) == n0, "a deal gone bad: the goods are a brick in a bag", gid)
math.random = function(x, y) if x == nil then return 0.9 elseif y == nil then return rnd(x) end return rnd(x, y) end
a.lcGraceUntil = 0
_setcvar("lc_bad_deal_chance", 1)
LC.BlackBuy(a, gid)
math.random = rnd
ok(LC.PlayerIsWanted(a), "or a sting: Civil Protection have you for it")
LC.ClearWanted(a)
_setcvar("lc_bad_deal_chance", 0)
LC.MarketAccess, LC.AtQuartermaster = access, atqm
for _, p in ipairs({ thief, mark, unit }) do p:RemovePData("lc_debts") p:RemovePData("lc_lent") p:SetPos(C0 + Vector(30000, 0, 0)) end
end
StreetCrimeTests()

function PapersHousingTests()
section("Papers you carry, the housing register, transfers")
local savedGM = GAMEMODE
GAMEMODE = { IsLivingCity = true }
local function Later(secs) _advance(secs) _runtimers() end
local function Payload(name)
    local m = _lastnet(name)
    return m and util.JSONToTable(m.data[2]) or nil
end
local B1 = Vector(-61000, 61000, 0)
local FAR4 = Vector(-140000, -140000, 0)
_setcvar("lc_intake", 1)
_setcvar("lc_intake_secs", 8)
local zA = LC.AddZone(B1 + Vector(0, 3000, 0), 300, "block", 41)
local zB = LC.AddZone(B1 + Vector(3000, 0, 0), 300, "block", 42)
local regPt = LC.AddPoint(B1, 0, "intake", 0)
local housePt = LC.AddPoint(B1 + Vector(0, 900, 0), 0, "housingterm", 0)
LC.SyncFixtures()
local reg, house
for _, e in ipairs(LC.EntsOf("lc_intake")) do
    if e:GetPos():Distance(B1) < 2000 then if LC.IntakeKind(e) == "register" then reg = e else house = e end end
end
ok(IsValid(reg) and IsValid(house), "(the desks)")

-- someone on the register from before papers were things you carry
local old = newPlayer("PapersOld", "citizen")
old:RemovePData("lc_intake")
LC.IntakeForget(old)
old:Spawn()
Later(1.5)
ok(LC.HasItem(old, "id_papers") and not LC.HasItem(old, "ration_card"), "everyone on the register is handed identity papers (no ration card: that's earned)")
LC.GiveItem(old, "ration_card")
ok(has(old.chat, "in your pockets (F3)"), "and told so")
ok(LCS.Weight("id_papers") == 0 and LCS.Items.id_papers.doc and LCS.Items.ration_card.doc, "they weigh nothing")
local count = LC.InvCount(old)
LC.TakeItem(old, "ration_card")
ok(LC.InvCount(old) == count, "and take no room in your pockets")
LC.GiveItem(old, "ration_card")
old.chat = {}
LC.InvAction(old, "drop", "id_papers")
ok(LC.HasItem(old, "id_papers") and has(old.chat, "keep your papers"), "you can't drop your papers")
local friend = newPlayer("PapersFriend", "citizen")
Later(0.3)
old:SetPos(FAR4) friend:SetPos(FAR4 + Vector(40, 0, 0))
old.lookingAt = friend
local okG, whyG = LC.GiveTo(old, "id_papers")
ok(not okG and LC.HasItem(old, "id_papers") and whyG and string.find(whyG, "stay with you", 1, true), "or hand them over", whyG)
net.sent = {}
friend.chat = {}
ok(LC.ShowPapers(old), "show them to whoever you're looking at")
local card = Payload("lc_papers_card")
ok(card and card.from and card.name == LC.CharacterName(old) and card.cid == old:GetNW2String("lc_cid", ""), "they see your papers", card and card.name)
ok(has(friend.chat, "show you their papers") and LC.Recognizes(friend, old), "and now know your name")
old.lookingAt = nil
net.sent = {}
LC.ShowPapers(old)
card = Payload("lc_papers_card")
ok(card and not card.from, "looking at nobody, you read your own")
-- stopped without them, rationed without a card
LC.TakeItem(old, "id_papers")
old.chat = {}
local st0 = LC.Standing(old)
ok(LC.IntakeStopped(old, nil) == false and has(old.chat, "Papers. None?") and LC.Standing(old) == st0 - 2, "a unit who stops you with no papers on you: a little standing", LC.Standing(old) - st0)
local okS, whyS = LC.ShowPapers(old)
ok(not okS and whyS and string.find(whyS, "no papers on you", 1, true), "and nothing to show", whyS)
LC.TakeItem(old, "ration_card")
old.lcnRationAt = 0
old.chat = {}
LC.UseDispenser(old, nil)
ok(has(old.chat, "No ration card"), "the dispensers want a ration card", old.chat[1])
-- a ration card from a finished shift; each ration takes one, and pays no credits
local wk = newPlayer("ShiftCardWorker", "citizen")
Later(0.3)
LC.RegisterPerson(wk, "staff") -- (on the register: only then can they have a ration)
wk.chat = {}
hook.Run("LivingCityQuestComplete", wk, { chain = "shift", title = "Test shift" })
ok(LC.Inventory(wk).ration_card == 1 and has(wk.chat, "earned a ration card"), "a finished Union shift earns a ration card", wk.chat[1])
hook.Run("LivingCityQuestComplete", wk, { chain = "rehab", title = "Not a shift" })
ok(LC.Inventory(wk).ration_card == 1, "other jobs don't")
wk.lcnRationAt = 0
local wcr = LC.Credits(wk)
_setcvar("lc_stockpile", 0) -- (whatever the city's stores are at by now)
ok(LC.UseDispenser(wk, nil) == true and not LC.HasItem(wk, "ration_card") and LC.Credits(wk) == wcr, "a ration takes the card, and pays no credits", LC.Credits(wk) - wcr)
_setcvar("lc_stockpile", 1)
-- Civil Intake replaces them
old:SetPos(B1 + Vector(40, 0, 0))
LC.AddCredits(old, 100)
local cr0 = LC.Credits(old)
net.sent = {}
LC.UseIntake(old, reg)
local rec = Payload("lc_intake_ui")
ok(rec and rec.kind == "register" and rec.papers == false and rec.cards == 0, "E at Civil Intake, registered: your record, with what's missing", rec and tostring(rec.papers))
_netcall("lc_intake_act", old, "papers", 0)
Later(5)
ok(LC.HasItem(old, "id_papers") and LC.Credits(old) == cr0 - 10, "new papers, for ten credits", LC.Credits(old) - cr0)
Later(1)
old.chat = {}
_netcall("lc_intake_act", old, "card", 0)
Later(5)
ok(not LC.HasItem(old, "ration_card") and LC.Credits(old) == cr0 - 10 and has(old.chat, "aren't issued here"), "Civil Intake doesn't hand out ration cards", old.chat[1])
old.chat = {}
Later(1)
_netcall("lc_intake_act", old, "papers", 0)
ok(has(old.chat, "already have"), "not twice")

-- the housing register: a request, a crowded block, a transfer
local crowd = {}
for i = 1, 3 do crowd[i] = newPlayer("Crowd" .. i, "citizen") end
Later(2.5) -- (after the housing module has looked at them)
for _, c in ipairs(crowd) do c:SetNW2Int("lc_block", 42) c:SetPos(FAR4) end
local nw = newPlayer("PapersNew", "citizen")
Later(0.3)
ok(LC.IntakePending(nw), "(a new arrival)")
nw.chat = {}
concommand.list.lc_register(nil, "lc_register", { "PapersNew" })
ok(LC.HasItem(nw, "id_papers") and LC.AwaitingHousing(nw), "registered: papers, and no room yet")
nw:SetPos(B1 + Vector(0, 960, 0))
LC.TakeItem(nw, "id_papers")
Later(1)
nw.chat = {}
net.sent = {}
LC.UseIntake(nw, house)
local hs = Payload("lc_intake_ui")
ok(hs and hs.awaiting and hs.papers == false, "the register sees you haven't your papers on you")
_netcall("lc_intake_act", nw, "apply", 42)
ok(has(nw.chat, "Present your identity papers") and LC.PlayerBlock(nw) == nil, "and won't take an application without them")
LC.GiveItem(nw, "id_papers")
nw:SetPData("lce_standing", 0)
Later(1)
nw.chat = {}
_netcall("lc_intake_act", nw, "apply", 42)
Later(9)
ok(LC.PlayerBlock(nw) ~= nil and LC.PlayerBlock(nw) ~= 42 and has(nw.chat, "declined"), "a crowded block is turned down: you get the least crowded", LC.PlayerBlock(nw))
ok(nw:GetPData("lc_housed_how", "") == "allocation", "and the register remembers how you got it")
ok(_lastnet("lc_waypoint") ~= nil and has(nw.chat, "marked on your screen"), "the way there is marked on your screen")
nw.chat = {}
Later(1)
_netcall("lc_intake_act", nw, "transfer", 42)
ok(has(nw.chat, "good standing") and LC.PlayerBlock(nw) ~= 42, "a transfer needs some standing")
nw:SetPData("lce_standing", 60)
Later(1)
nw.chat = {}
_netcall("lc_intake_act", nw, "transfer", 42)
Later(9)
ok(LC.PlayerBlock(nw) == 42 and has(nw.chat, "Transfer approved") and nw:GetPData("lc_housed_how", "") == "transfer", "good standing gets you into a crowded block", LC.PlayerBlock(nw))
Later(1)
net.sent = {}
LC.UseIntake(nw, house)
hs = Payload("lc_intake_ui")
ok(hs and hs.block == 42 and hs.how == "transfer" and hs.transfer == false and hs.transferWhy and string.find(hs.transferWhy, "too recent", 1, true),
    "housed: where you live, how you got it, and when you can move again", hs and hs.transferWhy)
nw.chat = {}
_netcall("lc_intake_act", nw, "way", 3)
ok(_lastnet("lc_waypoint") ~= nil, "it marks the way home")
ok(has(LC.CharKeys(), "lc_docs") and has(LC.CharKeys(), "lc_housed_how"), "each character slot keeps its own papers and housing record")
-- staff send someone back through all of it
concommand.list.lc_unregister(nil, "lc_unregister", { "PapersNew" })
ok(LC.IntakePending(nw) and LC.PlayerBlock(nw) == nil and not LC.HasItem(nw, "id_papers"), "lc_unregister: back to nothing, room and papers included")

-- on the screen, not just in chat
local kind, title, text = LC.NoticeForChat("[Rebel] Hey! Those are our supplies. Quit it.")
ok(kind == "speech" and title == "Rebel" and text == "Hey! Those are our supplies. Quit it.", "a rebel's warning shows as a subtitle")
ok(LC.NoticeForChat("[Civil Protection] Halt.") == "warn" and LC.NoticeForChat("[Housing Allocation] Approved.") == "info", "units' warnings and the desks' notices as cards")
ok(LC.NoticeForChat("[Miscount] Something routine.") == nil, "routine lines stay in chat")
LC.FlushNotices()
net.sent = {}
LC.Notice(old, "warn", "Civil Protection", "Halt.")
LC.Notice(old, "warn", "Civil Protection", "Halt.")
Later(0.2)
local n = 0
for _, m in ipairs(net.sent or {}) do if m.name == "lc_notice" then n = n + 1 end end
ok(n == 1 and _lastnet("lc_notice").data[1] == "warn", "a notice goes to the screen, once", n)
LC.FlushNotices()
net.sent = {}
LC.Announce("sweep")
Later(0.2)
local ev = false
for _, m in ipairs(net.sent or {}) do if m.name == "lc_notice" and m.data[1] == "event" then ev = true end end
ok(ev, "and the city's announcements, with what they mean for you")

for _, p in ipairs({ old, friend, nw, crowd[1], crowd[2], crowd[3] }) do p:SetPos(FAR4) end
LC.RemovePoint(regPt) LC.RemovePoint(housePt)
LC.SyncFixtures()
LC.RemoveZone(zA) LC.RemoveZone(zB)
GAMEMODE = savedGM
end
PapersHousingTests()

function SuppliesAndLabTests()
section("Units are issued supplies; the Resistance has a lab")
local savedGM = GAMEMODE
GAMEMODE = { IsLivingCity = true }
local function Later(secs) _advance(secs) _runtimers() end
local function Payload(name)
    local m = _lastnet(name)
    return m and util.JSONToTable(m.data[2]) or nil
end
local L0 = Vector(-120000, 60000, 0)
-- the Civil Protection Commissary
local unit = newPlayer("SupplyUnit", "cp")
Later(2)
unit:SetPos(L0)
local sup = ents.Create("lc_cpsupply") sup:SetPos(L0 + Vector(50, 0, 0))
ok(LC.POINT_KINDS.cpsupply and LC.HasCPSupply(), "the editor places a Civil Protection Commissary")
local okC, whyC = LC.Craft(unit, "bandage")
ok(not okC and whyC and string.find(whyC, "Visit a Civil Protection Commissary", 1, true), "units don't make things: they're sent to be issued them", whyC)
ok(LC.WaypointTo(unit, "cpsupply") and _lastnet("lc_waypoint") ~= nil, "and it's marked on their screen")
unit:SetArmor(0)
for id in pairs(LC.Inventory(unit)) do if id == "bandage" or id == "ration" then LC.TakeItem(unit, id, 99) end end
unit.chat = {}
LC.UseCPSupply(unit, sup)
ok(has(unit.chat, "Issued:") and unit:Armor() >= 50 and LC.HasItem(unit, "bandage", 2) and LC.HasItem(unit, "ration"), "E there: armour, bandages, a ration", unit.chat[1])
ok(_lastnet("lce_shop") ~= nil, "and the unit counter opens")
Later(1)
unit.chat = {}
LC.UseCPSupply(unit, sup)
ok(has(unit.chat, "next issue"), "not again straight away")
local cit = newPlayer("SupplyCitizen", "citizen")
Later(0.3)
cit:SetPos(L0)
cit.chat = {}
LC.UseCPSupply(cit, sup)
ok(has(cit.chat, "Civil Protection only"), "citizens are turned away")

-- the lab
local bench = ents.Create("lc_workbench") bench:SetPos(L0 + Vector(0, 2000, 0))
bench:SetAngles(Angle(0, 90, 0))
local sci = LC.SetupLab(bench)
ok(IsValid(sci) and sci:GetClass() == "lc_scientist" and sci:GetPos():Distance(bench:GetPos()) < 150, "a lab has a scientist beside its bench")
ok(LC.SetupLab(bench) == sci, "(once)")
ok(LC.WaypointTo(unit, "lab") == false, "units aren't shown the way to it")
local rebel = newPlayer("LabRebel", "resistance", nil, 900)
Later(3)
rebel:SetPos(sci:GetPos() + Vector(40, 0, 0))
cit:SetPos(sci:GetPos() + Vector(-40, 0, 0))
cit.chat = {}
net.sent = {}
LC.UseScientist(cit, sci)
ok(has(cit.chat, "private") and _lastnet("lc_lab") == nil, "he only works for the Resistance")
local okN, whyN = LC.LabMake(cit, "vest_cell", "pay")
ok(not okN and whyN and string.find(whyN, "Resistance", 1, true), "(and won't make a citizen anything)")
net.sent = {}
LC.UseScientist(rebel, sci)
local lab = Payload("lc_lab")
local pistol
for _, it in ipairs(lab and lab.items or {}) do if it.id == "gun_pistol" then pistol = it end end
ok(pistol == nil, "guns aren't the lab's: anything the quartermaster sells isn't listed there (the owner, 14 November)")
local cell
for _, it in ipairs(lab and lab.items or {}) do if it.id == "vest_cell" then cell = it end end
ok(cell and cell.price and cell.price < 60, "what only he makes (a charge cell) has his price", cell and cell.price)
for id in pairs(LC.Inventory(rebel)) do if id == "gun_pistol" or id == "ammo_pistol" then LC.TakeItem(rebel, id, 99) end end
LC.GiveItem(rebel, "scrap", 2) LC.GiveItem(rebel, "chemicals", 2)
rebel.chat = {}
ok(not LC.LabMake(rebel, "gun_pistol", "mats"), "(no guns from him, even from materials)")
ok(LC.LabMake(rebel, "vest_cell", "mats"), "bring him the materials")
ok(not LC.HasItem(rebel, "chemicals"), "(he takes them)")
local okB, whyB = LC.LabMake(rebel, "firebomb", "pay")
ok(not okB, "one thing at a time", whyB)
Later(7)
ok(LC.HasItem(rebel, "vest_cell") and has(rebel.chat, "He hands you"), "and he makes it, for nothing")
LC.AddCredits(rebel, 500)
local c0 = LC.Credits(rebel)
local ammoPrice = LC.LabPrice(LCS.LabById.vest_cell)
ok(LC.LabMake(rebel, "vest_cell", "pay") and LC.Credits(rebel) == c0 - ammoPrice, "or pay him (for what only he makes)", LC.Credits(rebel) - c0)
Later(7)
ok(LC.HasItem(rebel, "vest_cell", 2), "and it's yours")
ok(not LC.LabMake(rebel, "ammo_pistol", "pay"), "(not for ammunition: that's the quartermaster's)")
c0 = LC.Credits(rebel)
LC.LabMake(rebel, "firebomb", "pay")
rebel:SetPos(sci:GetPos() + Vector(900, 0, 0))
rebel.chat = {}
Later(1)
-- (13 November: walking off no longer undoes it: he works on, keeps it for them alone, hands it over when asked)
ok(LC.Credits(rebel) < c0 and has(rebel.chat, "keep at it") and sci.lcLabJob and sci.lcLabJob.away == true, "walk off and he keeps at it (nothing handed back)")
do
    local thief = newPlayer("LabThief", "resistance", nil, 900)
    Later(12)
    ok(sci.lcLabJob == nil and LC.LabHeldFor(sci, rebel) ~= nil and not LC.HasItem(rebel, "firebomb"), "finished while they were away: he keeps it for them")
    thief:SetPos(sci:GetPos() + Vector(40, 0, 0))
    thief.lcLabUse = 0
    LC.UseScientist(thief, sci)
    ok(not LC.HasItem(thief, "firebomb") and LC.LabHeldFor(sci, rebel) ~= nil, "nobody else is handed it")
    rebel:SetPos(sci:GetPos() + Vector(40, 0, 0))
    rebel.lcLabUse, rebel.chat = 0, {}
    LC.UseScientist(rebel, sci)
    ok(LC.HasItem(rebel, "firebomb") and has(rebel.chat, "kept it safe") and LC.LabHeldFor(sci, rebel) == nil, "back and talking to him: it's handed over")
    -- taken by a unit: what he was keeping is lost with him
    LC.LabHold(sci, LC.LabKey(rebel), "firebomb", 1)
    local heldWas = sci.lcLabHeld
    ok(heldWas ~= nil, "(something kept)")
    local saveShut = LC.LabShut
    sci.lcLabHeld = nil -- (put back as it was: the rest of this section goes on with an open lab)
    ok(LC.LabClean(sci) == true, "and the blood can be cleaned off him and his bench")
    thief:SetPos(Vector(-150000, 150000, 0))
end
ok(LC.Craft(rebel, "gun_pistol") == false and LCS.RecipesById.gun_pistol == nil and LCS.RecipesById.bandage ~= nil, "guns aren't made by hand any more; bandages still are")
-- a unit finds the lab
unit:SetPos(sci:GetPos() + Vector(0, 40, 0))
unit.chat = {}
Later(1)
LC.UseScientist(unit, sci)
ok(LC.LabShut(sci) and has(unit.chat, "Resistance lab"), "a unit who finds him shuts the lab down")
rebel:SetPos(sci:GetPos() + Vector(40, 0, 0))
local okS, whyS = LC.LabMake(rebel, "vest_cell", "pay")
ok(not okS and whyS and string.find(whyS, "Find the scientist", 1, true), "nothing is made there for a while", whyS)
Later(GetConVar("lc_lab_shutdown"):GetFloat() + 1)
ok(not LC.LabShut(sci), "then he's back")

for _, p in ipairs({ unit, cit, rebel }) do p:SetPos(Vector(-150000, 150000, 0)) end
bench:Remove() sci:Remove() sup:Remove()
GAMEMODE = savedGM
end
SuppliesAndLabTests()

