for _, c in ipairs(E.crowd) do
    if IsValid(c) and c:GetNW2Bool("lc_crowd", false) then crowdN = crowdN + 1 end
    if IsValid(c) and c:GetNW2Bool("lc_rocking", false) then rockingN = rockingN + 1 end
end
