-- The owner's playtest, 7 November: the baton's arrests (sv_livingcity_arrest.lua)
function ArrestOverhaulTests()
section("Arrests in the open: struggles, cuffs, walked to the cells, rebels, a shove and a run")
local A0 = Vector(-230000, 60000, 0)
local cellA = LC.AddPoint(A0 + Vector(1200, 0, 0), 0, "cell", 0)
LC.AddPoint(A0 + Vector(1200, 400, 0), 0, "release", 0)
local off = newPlayer("ArrestOfficer", "cp")
_run(0.3)
off:SetPos(A0)
_setcvar("lc_arrest_struggle_chance", 0)
-- the baton on a citizen: cuffed where they stand, and a unit walks them in
local cit, cst = LC.Spawners.citizen(A0 + Vector(50, 0, 0))
local unit, ust = LC.Spawners.cop(A0 + Vector(-500, 0, 0))
ust.untilT = 1e9
local okA, msgA = LC.BatonArrest(off, cit)
ok(okA and cst.state == "detained" and LC.NPCCustody[cit] ~= nil and cit:GetNW2Bool("lc_cuffed", false), "the baton cuffs a citizen where they stand", msgA)
_run(2)
ok(cst.state == "detained" and cit:GetPos():DistToSqr(cellA.pos) > 600 * 600, "not sent to a cell: still out on the street, waiting to be walked in", tostring(cit:GetPos()))
ok(LC.NPCCustody[cit] and LC.NPCCustody[cit].leader == unit and ust.questLock, "the nearest free unit comes over to take them")
local jailed, nearUnit = false, true
for _ = 1, 60 do
    _run(1)
    if cst.state == "jailed" then jailed = true break end
    if LC.NPCCustody[cit] and LC.NPCCustody[cit].walking and cit:GetPos():DistToSqr(unit:GetPos()) > 460 * 460 then nearUnit = false end
end
ok(jailed and cit:GetPos():DistToSqr(cellA.pos) < 30 * 30, "walked all the way there beside the unit, and locked in a cell", cst.state)
ok(nearUnit, "(and they kept at his side on the way)")
ok(not ust.questLock and not ust.marching and not ust.arrestDuty, "the unit goes back to his day")
LC.ReleaseNPCPrisoner(cit, cst, CurTime(), true)
-- with no unit free, the officer walks them in himself
unit:SetPos(Vector(-400000, 0, 0))
local cit2, cst2 = LC.Spawners.citizen(A0 + Vector(40, 0, 0))
off:SetPos(A0)
LC.BatonArrest(off, cit2)
_run(1)
ok(LC.NPCCustody[cit2] and LC.NPCCustody[cit2].leader == off, "nobody free: the prisoner follows the officer")
off.lookingAt = nil
ok(LC.ToggleDrag(off) and LC.NPCCustody[cit2].leader == nil, "F2 > Walk them to the cells / let go: let go of them")
off.lookingAt = cit2
cit2:SetPos(off:GetPos() + Vector(50, 0, 0))
ok(LC.ToggleDrag(off) and LC.NPCCustody[cit2].leader == off, "and take them by the arm again")
for i = 1, 12 do off:SetPos(A0 + Vector(100 * i, 0, 0)) _run(0.5) end
_run(1)
ok(cst2.state == "jailed", "walked up to the cell, they're locked in it", cst2.state)
LC.ReleaseNPCPrisoner(cit2, cst2, CurTime(), true)
unit:SetPos(A0 + Vector(-500, 0, 0))
-- a struggle the officer wins
_setcvar("lc_arrest_struggle_chance", 100)
local cit3, cst3 = LC.Spawners.citizen(A0 + Vector(50, 60, 0))
cit3.sim = false
off:SetPos(A0 + Vector(0, 60, 0))
LC.BatonArrest(off, cit3)
ok(LC.Struggles[cit3] ~= nil and cst3.state == "event", "a citizen can struggle: held there while it's decided")
local sm = _lastnet("lc_struggle")
ok(sm and sm.to == off and sm.data[1] == true and sm.data[2] == "restrain", "the officer sees the struggle bar")
for _ = 1, 45 do _netcall("lc_struggle_press", off) _run(0.08) end
_run(1)
ok(LC.Struggles[cit3] == nil and cst3.state == "detained" and LC.NPCCustody[cit3] ~= nil, "pressing hard enough holds them: cuffed", cst3.state)
LC.JailNPCPrisoner(cit3, LC.NPCCustody[cit3]) LC.ReleaseNPCPrisoner(cit3, cst3, CurTime(), true)
-- a rebel: always struggles, and an officer doing nothing loses: shoved back, and they run
_setcvar("lc_arrest_struggle_chance", 0)
local reb, rst = LC.Spawners.rebel(A0 + Vector(50, -60, 0))
reb.sim = false
off:SetPos(A0 + Vector(0, -60, 0))
off.pushed = nil
local okR, msgR = LC.BatonArrest(off, reb)
ok(okR and LC.Struggles[reb] ~= nil, "rebels can be arrested, and always struggle", msgR)
_run(5)
ok(LC.Struggles[reb] == nil and off.pushed ~= nil and off:GetNW2Float("lc_dazed_until", 0) > 0, "won free: the rebel shoves the officer back")
ok(rst.state == "moving" and rst.run and LC.Fleeing[reb] ~= nil, "and runs, flat out", rst.state)
local away = reb:GetPos() - off:GetPos()
ok(rst.dest and (rst.dest - reb:GetPos()):Dot(away) > 0, "away from the officer, not back past him")
ok(select(2, LC.BatonArrest(off, reb)):find("broke free", 1, true), "(not grabbed again the same instant)")
reb.lcBrokeFree = 0
LC.Struggles[reb] = nil
-- a rebel held: cuffed, disarmed
reb:SetPos(A0 + Vector(50, -60, 0))
reb:Give("weapon_smg1")
LC.BatonArrest(off, reb)
for _ = 1, 50 do _netcall("lc_struggle_press", off) _run(0.08) end
_run(1)
ok(rst.state == "detained" and LC.NPCCustody[reb] ~= nil and rst.cuffWeapon == "weapon_smg1", "a rebel held down is cuffed and disarmed", rst.state)
LC.JailNPCPrisoner(reb, LC.NPCCustody[reb])
ok(rst.state == "jailed", "and goes to a cell like anyone")
rst.untilT = 0
_run(2)
ok(rst.state ~= "jailed" and rst.cuffWeapon == nil, "let out at the end, with their gun back", rst.state)
-- players: a struggle, won and lost
local res = newPlayer("ArrestResister", "citizen")
_run(0.3)
res:SetPos(A0 + Vector(50, 200, 0))
res.lcGraceUntil = 0
off:SetPos(A0 + Vector(0, 200, 0))
LC.GiveItem(off, "zipties", 6) -- (a unit's cuffs are issue now, three, and each arrest uses a pair: enough here for every arrest below)
off.pushed = nil
LC.BatonArrest(off, res)
ok(LC.Struggles[res] ~= nil and res:GetNW2Float("lc_struggle_until", 0) > CurTime(), "a player arrested with the baton gets the chance to resist, held where they stand")
local rm
for i = #net.sent, 1, -1 do if net.sent[i].name == "lc_struggle" and net.sent[i].to == res then rm = net.sent[i] break end end
ok(rm and rm.data[1] == true and rm.data[2] == "resist", "and sees the struggle bar")
for i = 1, 40 do
    _netcall("lc_struggle_press", res)
    if i % 4 == 0 then _netcall("lc_struggle_press", off) end
    _run(0.08)
end
_run(1)
ok(not LC.IsTied(res) and off.pushed ~= nil and LC.PlayerIsWanted(res), "clearly more presses than the officer: free, the officer shoved back, and wanted for resisting arrest")
LC.ClearWanted(res)
res.lcBrokeFree = 0
off.pushed = nil
LC.BatonArrest(off, res)
for i = 1, 40 do
    _netcall("lc_struggle_press", off)
    if i % 2 == 0 then _netcall("lc_struggle_press", res) end
    _run(0.08)
end
_run(0.5)
ok(LC.IsTied(res) and LC.ArrestHolds[res] ~= nil and off.pushed == nil and LC.InCustody(res), "not enough: cuffed where they stand")
local marched = false
for _ = 1, 20 do _run(0.5) if LC.Marching[res] then marched = true break end end
ok(marched and LC.Marching[res].arrester == off, "a unit walks over and walks them to the cells (and it's still the officer's arrest)")
if LC.Marching[res] then LC.Marching[res] = nil end
if LC.IsTied(res) then LC.Untie(res, nil, true) end
-- the officer walks off mid-struggle: it just ends, not a win (the owner, 7 November)
do
    LC.ArrestHolds[res] = nil
    res.lcBrokeFree = 0
    res:SetPos(A0 + Vector(50, 200, 0))
    off:SetPos(A0 + Vector(0, 200, 0))
    off.pushed = nil
    LC.ClearWanted(res)
    local seen = {}
    local realNotice = LC.Notice
    LC.Notice = function(p, kind, title, text, secs) if p == res then seen[#seen + 1] = tostring(title) .. "|" .. tostring(text) end return realNotice(p, kind, title, text, secs) end
    LC.BatonArrest(off, res)
    local began = LC.Struggles[res] ~= nil
    for _ = 1, 10 do _netcall("lc_struggle_press", res) _run(0.05) end
    off:SetPos(A0 + Vector(0, 900, 0))
    _run(0.5)
    LC.Notice = realNotice
    local said = table.concat(seen, " / ")
    ok(began and LC.Struggles[res] == nil and not LC.IsTied(res) and res:GetNW2Float("lc_struggle_until", 0) == 0, "the officer walks off mid-struggle: it ends, and they're let go")
    ok(not LC.PlayerIsWanted(res) and off.pushed == nil and (res.lcBrokeFree or 0) <= CurTime(), "not a win: not wanted for resisting, no shove, no 'broke free'", said)
    ok(said:find("The officer is gone: the struggle is over.", 1, true) and not said:find("broke free", 1, true), "a plain word that it's over, not 'You broke free'", said)
    LC.ClearWanted(res)
end
-- hands up: going quietly
res:SetNW2Bool("lc_handsup", true)
LC.BatonArrest(off, res)
ok(LC.Struggles[res] == nil and LC.IsTied(res), "hands up: no struggle, just cuffed")
LC.ArrestHolds[res] = nil
LC.Untie(res, nil, true)
-- the Apprehend job: a failed Authority check, a shove, and a real run
local q = inject(off, "cp_apprehend")
local t = q and q.data.target
if t then
    reach(off, t)
    off.pushed = nil
    withRoll(1, function() LC.ResolveChoice(off, q.id, 2) end)
    local tst = LC.NPCs[t]
    ok(off.pushed ~= nil, "a failed check: the suspect shoves the officer back")
    ok(tst.state == "moving" and tst.run and LC.Fleeing[t] and LC.Fleeing[t].noChase, "and takes off at a run, left for the officer to catch", tst.state)
    local aw = t:GetPos() - off:GetPos()
    ok(tst.dest and (tst.dest - t:GetPos()):Dot(aw) > 0, "away from the officer")
    LC.AbandonQuest(off)
else
    ok(false, "(an Apprehend job to test)")
end
_setcvar("lc_arrest_struggle_chance", 25)
for _, n in ipairs({ unit, cit, cit2, cit3, reb }) do if IsValid(n) then n:Remove() end end
for _, p in ipairs({ off, res }) do p:SetPos(Vector(-150000, 150000, 0)) end
end
ArrestOverhaulTests()
-- saved player data (sv_livingcity_perf.lua): the first read of each key is kept, writes update it
do
    local store, reads, refuse = {}, 0, false
    local meta = {}
    function meta.GetPData(p, k, d) reads = reads + 1 local v = store[k] if v == nil then return d end return v end
    function meta.SetPData(p, k, v) if refuse then return false end store[k] = tostring(v) return true end
    function meta.RemovePData(p, k) store[k] = nil return true end
    ok(LC.CachePData(meta), "saved data reads are kept in memory")
    ok(not LC.CachePData(meta), "(wrapped only once)")
    local p = {}
    ok(meta.GetPData(p, "lce_credits", 20) == 20 and reads == 1, "not saved: the default")
    ok(meta.GetPData(p, "lce_credits", 7) == 7 and reads == 1, "asked again: the default given, without asking the database")
    meta.SetPData(p, "lce_credits", 35)
    ok(store.lce_credits == "35", "a write still goes to the database")
    ok(meta.GetPData(p, "lce_credits", 20) == "35" and reads == 1, "and is read back as text, as the database gives it, from memory")
    meta.RemovePData(p, "lce_credits")
    ok(store.lce_credits == nil and meta.GetPData(p, "lce_credits", 5) == 5 and reads == 1, "removed: gone, and the default again")
    store.lc_desc = "tall"
    local q = {}
    ok(meta.GetPData(q, "lc_desc", "") == "tall" and meta.GetPData(q, "lc_desc", "") == "tall" and reads == 2, "each player has their own copy, read once")
    refuse = true
    meta.SetPData(q, "lc_desc", "short")
    ok(meta.GetPData(q, "lc_desc", "") == "tall" and reads == 3, "a write the database refused isn't remembered: it's read from the database again")
end
-- LC.IsSeen and LC.ViewerPositions (sv_livingcity.lua): the players' views are worked out once per tick
do
    local tickWas, testWas = engine.TickCount, LC.TestMode
    local tick = 1
    engine.TickCount = function() return tick end
    LC.TestMode = false
    local far = Vector(300000, 300000, 0)
    local looker = newPlayer("PerfLooker", "citizen")
    looker:SetPos(far)
    ok(LC.IsSeen(far + Vector(30, 0, 0)), "a spot right beside a player is seen")
    local list = LC.ViewerPositions()
    ok(list == LC.ViewerPositions(), "the same list for the rest of the tick")
    local found = false
    for _, at in ipairs(list) do if at:DistToSqr(far) < 1 then found = true end end
    ok(found, "with each player in it")
    looker:SetPos(far + Vector(0, 50000, 0))
    ok(LC.IsSeen(far + Vector(30, 0, 0)), "within the same tick, where they stood is still where they are")
    tick = 2
    ok(not LC.IsSeen(far + Vector(30, 0, 0)), "the next tick, they've moved on")
    ok(LC.ViewerPositions() ~= list, "and the list is made again")
    engine.TickCount, LC.TestMode = tickWas, testWas
    looker:SetPos(Vector(-120000, -120000, 0))
    ok(not LC.TestMode or LC.ViewerPositions() ~= LC.ViewerPositions(), "(in tests, asked fresh every time)")
end
end
PerfCacheTests()

function RebelFoodTests()
-- the Resistance's supply crates, restocked for how many are online (sv_livingcity_scavenge.lua; the owner,
-- 7 November: solo it was an endless feast, with 32 or 64 on the server it would be a famine)
section("Rebel food: supplies sized to the Resistance online")
do
    local realR = math.random
    math.randomseed(1107)
    local need = LC.FoodNeedPerHead(20)
    ok(need > 0.8 and need < 1.1, "a fighter eats about a tin every twenty minutes (lc_hunger_minutes 60)", need)
    ok(LC.FoodRestockSize(0, 20) == 0, "nobody in the Resistance online: nothing comes in")
    local function avg(heads)
        local t = 0
        for _ = 1, 4000 do t = t + LC.FoodRestockSize(heads, 20) end
        return t / 4000
    end
    local a2, a40 = avg(2), avg(40)
    ok(a40 > a2 * 15 and a40 < a2 * 25, "forty fighters get about twenty times what two get", string.format("%.2f / %.2f", a2, a40))
    ok(math.abs(a2 / (need * 2) - 0.5) < 0.1 and math.abs(a40 / (need * 40) - 0.5) < 0.06,
        "either way about half of what they eat (lc_food_availability 0.5)", string.format("%.2f %.2f", a2 / (need * 2), a40 / (need * 40)))
    ok(LC.FoodRestockCap(1) >= 2 and LC.FoodRestockCap(40) > LC.FoodRestockCap(1) * 10, "a busy camp's crate is restocked to more",
        LC.FoodRestockCap(1) .. " / " .. LC.FoodRestockCap(40))
    -- a camp that eats what it needs from the crate, period after period: how often is there food?
    local function sim(heads)
        local stock, avail, short, some, cap = 0, 0, 0, 0, LC.FoodRestockCap(heads)
        for _ = 1, 400 do
            stock = math.min(stock + LC.FoodRestockSize(heads, 20), math.max(stock, cap))
            local want = math.max(1, math.floor(need * heads + math.random()))
            local eat = math.min(stock, want)
            stock = stock - eat
            avail = avail + eat / want -- (eaten steadily: the share of the period there was food)
            if eat < want then short = short + 1 end
            if eat > 0 then some = some + 1 end
        end
        return avail / 400, short / 400, some / 400
    end
    for _, heads in ipairs({ 1, 2, 40, 64 }) do
        local avail, short, some = sim(heads)
        ok(avail > 0.35 and avail < 0.65 and short > 0.25 and some > 0.25,
            string.format("%d fighter%s: food about half the time, and the crate runs out regularly", heads, heads == 1 and "" or "s"),
            string.format("food %.2f of the time, ran short %.2f, had some %.2f", avail, short, some))
    end
    math.random = realR

    -- a crate of our own, in a camp of our own
    local c = ents.Create("prop_physics")
    c:SetModel("models/items/item_item_crate.mdl")
    c:SetPos(Vector(-91000, 91000, 0))
    c:Spawn()
    c.lcRebelProp = "cache"
    c:SetNW2String("lc_label_kind", "cache")
    local key = {}
    LC.RebelProps[key] = { cache = c, pots = {} }
    LC.SweepCache(c)
    ok((c.lcStock or 0) == 0, "(an empty crate)")
    math.random = function(a, b) if a == nil then return 0.99 end if b == nil then return realR(a) end return realR(a, b) end
    local got4 = LC.FoodRestock(4, { c }, 1)
    ok(got4 == 3 and c.lcStock == 3, "a delivery for four fighters: three tins at most", got4)
    local got40 = LC.FoodRestock(40, { c }, 1)
    ok(got40 > 20 and c.lcFoodCap == LC.FoodRestockCap(40) and c:GetNW2Int("lc_cache_cap", 0) == c.lcFoodCap,
        "for forty fighters, far more", got40)
    ok(c:GetNW2Float("lc_cache_next", 0) > CurTime(), "the crate knows when the next supplies are due (shown on it to the Resistance)")
    local had = c.lcStock
    ok(LC.FoodRestock(1, { c }, 1) == 0 and c.lcStock == had, "a delivery doesn't pile food up past what's needed (nor take any away)", c.lcStock)
    LC.AddToCache(c, 2)
    ok(c.lcStock == had, "a crate over its cap from busier times keeps what it has", c.lcStock)
    LC.FoodRestock(8, { c }, 2)
    ok(c.lcFoodCap == LC.FoodRestockCap(4), "two camps share the fighters online", c.lcFoodCap)
    math.random = realR

    -- what players bring in goes past what a delivery fills it to
    LC.SweepCache(c)
    LC.FoodRestock(1, { c }, 1)
    LC.AddToCache(c, c.lcFoodCap - (c.lcStock or 0))
    local full = c.lcStock
    ok(full == c.lcFoodCap, "(restocked as far as deliveries go)", full)
    local cit = newPlayer("FoodGiver", "citizen")
    cit:SetPos(c:GetPos() + Vector(-40, 0, 0))
    LC.GiveItem(cit, "cooked_fish")
    LC.GiveItem(cit, "cooked_headcrab")
    LC.GiveItem(cit, "cooked_bird")
    ok(LC.Donate(cit) and c.lcStock == full + 3, "a citizen's fish, headcrab and bird go into the stores, past the delivery cap", c.lcStock)
    ok(LC.AddToCache(c, 2) == 2, "and so does a rebel's scavenging haul or a supply run")
    cit:SetPos(Vector(-120000, -120000, 0))

    -- empty: say so, and where else to find food
    local n0 = LC.ResistanceHeadcount()
    local reb = newPlayer("HungryRebel", "resistance", nil, 200)
    ok(LC.ResistanceHeadcount() == n0 + 1, "the headcount is the Resistance players online")
    reb:SetPos(c:GetPos() + Vector(-40, 0, 0))
    LC.SweepCache(c)
    local notices, realNotice = {}, LC.Notice
    LC.Notice = function(p, kind, title, text, secs) if p == reb then notices[#notices + 1] = text end return realNotice(p, kind, title, text, secs) end
    reb.chat, reb.lcCacheNext, reb.lcPropUseNext = {}, 0, 0
    hook.Run("PlayerUse", reb, c)
    LC.Notice = realNotice
    ok(has(reb.chat, "crate's empty") and has(reb.chat, "Fish the canal") and has(reb.chat, "headcrabs or birds")
        and has(reb.chat, "citizens") and has(reb.chat, "quartermaster"), "an empty crate says so, and points to fishing, hunting, citizens and the quartermaster", reb.chat[#reb.chat])
    ok(has(reb.chat, "More supplies due in about"), "and when the next supplies are due")
    ok(has(notices, "crate's empty"), "on the screen too (LC.Notice)")
    ok(not LC.HasItem(reb, "canned_food"), "and nothing comes out of it")
    reb:SetPos(Vector(-120000, -120000, 0))

    LC.RebelProps[key] = nil
    c:Remove()
end
end
RebelFoodTests()
function LaborTests()
section("Labor Assignment: Union work given out in person")
local savedGM = GAMEMODE
GAMEMODE = { IsLivingCity = true }
local function Later(secs) _advance(secs) _runtimers() end
local function Payload(name)
    local m = _lastnet(name)
    return m and util.JSONToTable(m.data[2]) or nil
end
local function Noticed(txt)
    for _, m in ipairs(net.sent or {}) do
        if m.name == "lc_notice" then
            for _, v in ipairs(m.data or {}) do if isstring(v) and string.find(v, txt, 1, true) then return true end end
        end
    end
    return false
end
local function Listed(info, id)
    for _, j in ipairs(info and info.jobs or {}) do if j.id == id then return j end end
    return nil
end
local FAR5 = Vector(-150000, 150000, 0)
local B0 = Vector(71000, -71000, 0)
_setcvar("lc_intake", 1)
_setcvar("lc_intake_secs", 8)
_setcvar("lc_assign_work", 1)
_setcvar("lc_labor_min_minutes", 30)
_setcvar("lc_labor_min_shifts", 4)
_setcvar("lc_job_cooldown", 900)
local blockZone = LC.AddZone(B0 + Vector(0, 3000, 0), 400, "block", 41)
local regPt = LC.AddPoint(B0, 0, "intake", 0)
local housePt = LC.AddPoint(B0 + Vector(0, 900, 0), 0, "housingterm", 0)
local arrPt = LC.AddPoint(B0 + Vector(-1500, 0, 0), 90, "arrival", 0)
LC.SyncFixtures()
local house
for _, e in ipairs(LC.EntsOf("lc_intake")) do
    if LC.IntakeKind(e) == "housing" and e:GetPos():Distance(housePt.pos) < 50 then house = e end
end

-- no Labor Assignment terminal: as before
ok(LC.POINT_KINDS.laborterm, "the editor places Labor Assignment terminals")
ok(not LC.LaborDesk(), "(none placed yet)")
local before = newPlayer("LaborBefore", "citizen")
Later(0.3)
before:SetPData("lc_chosen", "1")
LC.RegisterPerson(before, "staff")
Later(3)
ok(LC.Job(before) ~= nil, "with no terminal, the Union gives a newly registered citizen work by itself, as before", LC.Job(before) and LC.Job(before).id)
before.lcjNext = 0
ok(LC.SetJob(before, "courier") == true, "and the board still changes jobs")
local boss = newPlayer("LaborBoss", "citizen")
boss.superadmin = true
LC.FlushNotices()
net.sent = {}
LC.LaborTellStaff(boss)
LC.LaborTellStaff(boss)
Later(0.2)
local told = 0
for _, m in ipairs(net.sent or {}) do if m.name == "lc_notice" then told = told + 1 end end
ok(Noticed("no Labor Assignment terminal") and told == 1, "a superadmin is told, once, that the map has none", told)

-- the terminal
local laborPt = LC.AddPoint(B0 + Vector(0, 450, 0), 0, "laborterm", 0)
LC.SyncFixtures()
local labor
for _, e in ipairs(LC.EntsOf("lc_intake")) do if LC.IntakeKind(e) == "labor" then labor = e end end
ok(IsValid(labor) and labor:GetClass() == "lc_intake" and LC.LaborDesk(), "Labor Assignment is a terminal in the world, the same kind as Civil Intake's")
ok(LC.NoticeForChat("[Labor Assignment] Approved.") == "info", "its messages go on screen")

-- no more changing jobs by magic
before.lcjNext = 0
local okM, whyM = LC.SetJob(before, "factory")
ok(not okM and whyM == LC.LABOR_GO and LC.Job(before).id == "courier", "the board can't change your job any more", whyM)
before.chat = {}
net.sent = {}
_netcall("lcj_set", before, "factory")
ok(has(before.chat, "Go to a Labor Assignment terminal to change your assignment"), "it says where to go")
ok(_lastnet("lc_waypoint") ~= nil and _lastnet("lc_waypoint").data[3] == "Labor Assignment", "and marks the nearest terminal")
net.sent = {}
LC.SendBoard(before)
local bd = Payload("lcq_board")
ok(bd and bd.jobs and bd.jobs.desk == true and string.find(bd.jobs.lockLine or "", "Labor Assignment", 1, true), "the board (F3) sends you to the terminal instead of a job list")
ok(LC.SetJob(before, "factory", true) == true, "staff can still set a job")
LC.SetJob(before, "courier", true)

-- a new arrival: Civil Intake, then Labor Assignment, then a room
local n = newPlayer("LaborArrival", "citizen")
Later(0.3)
ok(LC.IntakePending(n), "(a new arrival)")
n:SetPData("lc_chosen", "1")
n.chat = {}
net.sent = {}
LC.RegisterPerson(n, "terminal")
ok(has(n.chat, "Labor Assignment"), "registered, you're told to go to Labor Assignment next")
ok(_lastnet("lc_waypoint") ~= nil and _lastnet("lc_waypoint").data[3] == "Labor Assignment", "and it's marked on your screen")
Later(3)
ok(LC.Job(n) == nil and LC.AwaitingLabor(n), "the Union doesn't hand you work from afar: you walk to it")
LC.IntakeFlags(n)
ok(n:GetNW2Bool("lc_unassigned", false), "your screen says so")
local step = LC.NextStep(n)
ok(step and step.key == "labor" and step.way == "labor", "and so does your next step", step and step.key)
n:SetPos(house:GetPos() + Vector(60, 0, 0))
Later(1)
net.sent = {}
LC.UseIntake(n, house)
local hp = Payload("lc_intake_ui")
ok(hp and hp.kind == "housing" and hp.needWork == true, "Housing Allocation's screen says you need work first")
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "apply", 0)
ok(has(n.chat, "Labor Assignment first") and LC.AwaitingHousing(n) and n:GetNW2Float("lc_intake_until", 0) == 0, "and won't give you a room until you have it", n.chat[1])

-- the first assignment
n:SetPos(labor:GetPos() + Vector(60, 0, 0))
Later(1)
net.sent = {}
LC.UseIntake(n, labor)
local lp = Payload("lc_intake_ui")
ok(lp and lp.kind == "labor" and lp.labor and lp.labor.first == true, "E at Labor Assignment: your first assignment, given by the Union")
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "choose", LCJ.ById.factory.num)
ok(has(n.chat, "first assignment comes from the Union") and LC.Job(n) == nil, "you don't pick the first one yourself")
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "assign", 0)
ok(has(n.chat, "Stand still"), "ask for it and the terminal works on you")
Later(9)
local job = LC.Job(n)
ok(job ~= nil and has(n.chat, "Assignment approved"), "and after a while you have Union work", n.chat[#n.chat])
ok(job and job.id ~= "cleanup" and job.id ~= "porter" and not job.minStanding, "never Infestation Cleanup, Intake Processor or the Block Warden", job and job.id)
local counts = {}
for _, p in ipairs(player.GetAll()) do
    local j = p:GetNW2String("lcj_job", "")
    if j ~= "" and p ~= n then counts[j] = (counts[j] or 0) + 1 end
end
local fewest = true
for _, o in ipairs(LCJ.Occupations) do
    if not LCJ.Closed(o) and not o.minStanding and o.id ~= "cleanup" and o.id ~= "porter" and (counts[o.id] or 0) < (counts[job.id] or 0) then fewest = false end
end
ok(fewest, "the post with the most openings (the fewest people on it)", job and job.id)
ok(has(n.chat, "Housing Allocation") and not LC.AwaitingLabor(n), "then you're sent on to Housing Allocation")
ok(LC.LaborLocked(n), "and you're tied to the job")

-- tied to it
n.lcjNext = 0
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "choose", LCJ.ById.factory.num == (job and job.num) and LCJ.ById.courier.num or LCJ.ById.factory.num)
ok(has(n.chat, "Tied to this job for 30 minutes more or 4 shifts more"), "the terminal won't change it before 30 minutes or 4 shifts", n.chat[1])
net.sent = {}
LC.SendBoard(n)
bd = Payload("lcq_board")
ok(bd and string.find(bd.jobs.lockLine or "", "Tied to this job", 1, true), "the board says how long")
Later(1)
net.sent = {}
LC.UseIntake(n, labor)
lp = Payload("lc_intake_ui")
ok(lp and lp.labor and lp.labor.locked == true and #(lp.labor.jobs or {}) == 0, "nor does the terminal's screen offer other jobs yet")

-- a room now
n:SetPos(house:GetPos() + Vector(60, 0, 0))
Later(1)
LC.UseIntake(n, house)
Later(1)
_netcall("lc_intake_act", n, "apply", 0)
Later(9)
ok(LC.PlayerBlock(n) ~= nil, "with work, Housing Allocation gives you a room")

-- time on the job counts, and is kept over a rejoin
local s0 = LC.LaborStint(n).secs
Later(6)
ok(LC.LaborStint(n).secs > s0, "time on the job counts", LC.LaborStint(n).secs)
hook.Run("LivingCityQuestComplete", n, { chain = "shift" })
hook.Run("PlayerDisconnected", n)
n.lcLabor = nil
ok(LC.LaborLocked(n) and LC.LaborStint(n).shifts == 1 and LC.LaborStint(n).job == job.id, "kept over a rejoin (saved data)")
ok(has(LC.CharKeys(), "lc_labor_job") and has(LC.CharKeys(), "lc_labor_done"), "each character keeps their own")

-- four shifts (or 30 minutes) and they're free to ask for another
LC.FlushNotices()
net.sent = {}
for _ = 1, 3 do hook.Run("LivingCityQuestComplete", n, { chain = "shift" }) end
Later(0.2)
ok(not LC.LaborLocked(n) and n:GetPData("lc_labor_done", "0") == "1", "after 4 shifts they're free")
ok(Noticed("done your stint"), "and told so")
local t2 = newPlayer("LaborTimer", "citizen")
Later(0.3)
t2:SetPData("lc_chosen", "1")
LC.RegisterPerson(t2, "staff")
t2.lcIdentity = nil
if not LC.HasItem(t2, "id_papers") then LC.GiveItem(t2, "id_papers") end
LC.LaborFinish(t2, {})
ok(LC.LaborLocked(t2), "(another, just assigned)")
Later(6)
LC.LaborStint(t2).secs = 30 * 60 - 3
Later(6)
ok(not LC.LaborLocked(t2), "or after 30 minutes on the job", LC.LaborStint(t2).secs)
-- a 0 means that condition doesn't apply; both 0: no stint at all (the owner, 7 November)
do
    local function Assigned(name)
        local z = newPlayer(name, "citizen")
        Later(0.3)
        z:SetPData("lc_chosen", "1")
        LC.RegisterPerson(z, "staff")
        z.lcIdentity = nil
        if not LC.HasItem(z, "id_papers") then LC.GiveItem(z, "id_papers") end
        LC.FlushNotices()
        net.sent = {}
        LC.LaborFinish(z, {})
        Later(12)
        LC.FlushNotices()
        return z
    end
    _setcvar("lc_labor_min_shifts", 0)
    local z1 = Assigned("LaborZeroShifts")
    local line1 = LC.LaborLockLine(z1) or ""
    ok(LC.Job(z1) and LC.LaborLocked(z1) and not Noticed("done your stint"), "lc_labor_min_shifts 0: no 'done your stint' seconds after the job is given")
    ok(line1:find("minutes more;", 1, true) and not line1:find("shift", 1, true), "only the minutes count", line1)
    LC.LaborStint(z1).secs = 30 * 60 - 3
    Later(6)
    LC.FlushNotices()
    ok(not LC.LaborLocked(z1) and Noticed("done your stint"), "and after 30 minutes, the stint's done")
    _setcvar("lc_labor_min_shifts", 4)
    _setcvar("lc_labor_min_minutes", 0)
    local z2 = Assigned("LaborZeroMinutes")
    local line2 = LC.LaborLockLine(z2) or ""
    ok(LC.Job(z2) and LC.LaborLocked(z2) and not Noticed("done your stint"), "lc_labor_min_minutes 0: no 'done your stint' seconds after the job is given")
    ok(line2:find("4 shifts more;", 1, true) and not line2:find("minute", 1, true), "only the shifts count", line2)
    for _ = 1, 4 do hook.Run("LivingCityQuestComplete", z2, { chain = "shift" }) end
    Later(0.2)
    LC.FlushNotices()
    ok(not LC.LaborLocked(z2) and Noticed("done your stint"), "and after 4 shifts, the stint's done")
    _setcvar("lc_labor_min_shifts", 0)
    local z3 = Assigned("LaborNoStint")
    ok(LC.Job(z3) and not LC.LaborLocked(z3) and not Noticed("done your stint") and not Noticed("tied to it"), "both 0: no stint at all, and nothing said about one")
    _setcvar("lc_labor_min_minutes", 30)
    _setcvar("lc_labor_min_shifts", 4)
    for _, z in ipairs({ z1, z2, z3 }) do LC.SetJob(z, "", true) z:SetPos(FAR5) end
end

-- what they're offered, by Civil Standing
LC.AddStanding(n, 10 - LC.Standing(n), "test")
n:SetPos(labor:GetPos() + Vector(60, 0, 0))
Later(1)
net.sent = {}
LC.UseIntake(n, labor)
lp = Payload("lc_intake_ui")
local cl, po = Listed(lp and lp.labor, "cleanup"), Listed(lp and lp.labor, "porter")
ok(cl and cl.locked and string.find(cl.locked, "25", 1, true) and po and po.locked and string.find(po.locked, "50", 1, true),
    "Infestation Cleanup (25) and Intake Processor (50) are listed, locked, with the reason", cl and cl.locked)
ok(not Listed(lp and lp.labor, "warden") and Listed(lp and lp.labor, job.id) and Listed(lp and lp.labor, job.id).current, "the Block Warden isn't listed below 100; your own job is marked")
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "choose", LCJ.ById.cleanup.num)
ok(has(n.chat, "needs Civil Standing 25") and LC.Job(n).id == job.id, "and can't be had yet")
-- the Union's own wait between job changes still counts
LC.AddStanding(n, 30 - LC.Standing(n), "test")
n.lcjNext = CurTime() + 300
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "choose", LCJ.ById.cleanup.num)
ok(has(n.chat, "changed jobs recently"), "the 15 minutes between job changes still holds", n.chat[1])
n.lcjNext = 0
Later(1)
net.sent = {}
LC.UseIntake(n, labor)
lp = Payload("lc_intake_ui")
cl, po = Listed(lp and lp.labor, "cleanup"), Listed(lp and lp.labor, "porter")
ok(cl and not cl.locked and po and po.locked, "at 25 Infestation Cleanup opens; Intake Processor waits for 50")
n.chat = {}
Later(1)
_netcall("lc_intake_act", n, "choose", LCJ.ById.cleanup.num)
Later(9)
ok(LC.Job(n) and LC.Job(n).id == "cleanup" and n:HasWeapon("weapon_lc_hoover") and n:HasWeapon("weapon_lc_sprayer"), "picked at the terminal: Infestation Cleanup, kit and all")
ok(LC.LaborLocked(n), "a job picked here holds for a stint too")

-- losing the job works as before, and ends the stint
LC.SetFaction(n, "cp", nil, true)
LC.CheckUnionJob(n)
ok(LC.Job(n) == nil and not n:HasWeapon("weapon_lc_hoover") and LC.LaborStint(n).job == "", "a Civil Protection unit loses the job and its kit, and the stint")
LC.SetFaction(n, "citizen", nil, true)
Later(1)
ok(LC.AwaitingLabor(n), "back as a citizen, Labor Assignment again")
net.sent = {}
LC.UseIntake(n, labor)
lp = Payload("lc_intake_ui")
ok(lp and lp.labor and lp.labor.first == false and #(lp.labor.jobs or {}) > 0, "having done a stint, you pick for yourself")
ok(LC.SetJob(n, "medic", true) and not LC.LaborLocked(n), "staff setting a job isn't a stint")

-- the terminal taken away: nobody is stuck
LC.RemovePoint(laborPt)
LC.SyncFixtures()
before.lcjNext = 0
ok(not LC.LaborDesk() and LC.SetJob(before, "factory") == true, "take the terminal away and the board changes jobs again")

LC.RemovePoint(regPt) LC.RemovePoint(housePt) LC.RemovePoint(arrPt)
LC.SyncFixtures()
if blockZone then LC.RemoveZone(blockZone) end
for _, p in ipairs({ before, boss, n, t2 }) do LC.SetJob(p, "", true) p:SetPos(FAR5) end
GAMEMODE = savedGM
end
LaborTests()

----------------------------------------------------------------------
section("The Administrator's voice and microphone (7 November)")
function AdminVoiceTests()
    local was = LC.AnnounceForceVoice
    LC.AnnounceForceVoice = nil
    _files["sound/livingcity/administrator/lockdown1.wav"] = "RIFF" .. string.rep("\0", 3000)
    _files["sound/livingcity/overwatch/lockdown1.wav"] = "RIFF" .. string.rep("\0", 3000)
    LC.AnnounceRescan()
    -- (the suite's own Administrators, QAdmin and the like, step out for this: nobody plays her)
    local asideA = {}
    for _, p in ipairs(player.GetAll()) do if LC.IsAdministrator(p) then asideA[#asideA + 1] = p p.valid = false end end
    ok(LC.HumanAdministrator() == nil and LC.AnnounceVoiceFor("lockdown") == "administrator", "nobody plays the Administrator: her recorded voice says it", tostring(LC.HumanAdministrator() and LC.HumanAdministrator():Nick()) .. " " .. tostring(LC.AnnounceVoiceFor("lockdown")))
    local adm = newPlayer("Mayor", "admin")
    ok(LC.HumanAdministrator() == adm and LC.AnnounceVoiceFor("lockdown") == "overwatch", "a player is the Administrator: Overwatch's voice (the owner's recordings) says it")
    ok(LC.AnnounceVoiceFor("curfew_firm_only_hers") == nil or LC.AnnounceVoiceFor("curfew_firm_only_hers") == "overwatch", "(and never her recordings while she's played)")
    local loadout = false
    for _, f in ipairs(LCF.Factions or {}) do
        if f.id == "admin" then for _, w in ipairs(f.ranks[1].loadout or {}) do if w == "weapon_lc_microphone" then loadout = true end end end
    end
    ok(loadout, "the Administrator carries the microphone")
    -- on air, whatever the transmitter's cooldown
    local ear = newPlayer("Listener", "citizen")
    SetGlobal2Float("lc_live_next", CurTime() + 600)
    if LC.LiveSpeaker then LC.StopBroadcast("test") end
    if LC.LiveNPC and LC.StopNPCBroadcast then LC.StopNPCBroadcast("test") end
    SetGlobal2Float("lc_live_next", CurTime() + 600)
    local okB = LC.StartBroadcast(adm)
    ok(okB and LC.LiveSpeaker == adm, "the Administrator goes on air without waiting for the transmitter")
    LC.StopBroadcast("test")
    local cit = newPlayer("Shouter", "citizen")
    SetGlobal2Float("lc_live_next", CurTime() + 600)
    ok(not LC.StartBroadcast(cit), "anyone else still waits for the transmitter")
    adm.valid, ear.valid, cit.valid = false, false, false
    _files["sound/livingcity/administrator/lockdown1.wav"] = nil
    _files["sound/livingcity/overwatch/lockdown1.wav"] = nil
    LC.AnnounceRescan()
    SetGlobal2Float("lc_live_next", 0)
    for _, p in ipairs(asideA) do p.valid = true end
    LC.AnnounceForceVoice = was
end
AdminVoiceTests()
function GuidanceTests()
section("Guidance: the quest trail's way, refreshed when you stray, and where you are")
local G0 = Vector(170000, -170000, 0)
_setcvar("lc_trail_straight", 0) -- (first, every path point; the straight walk is tried at the end)
local function payload()
    local m = _lastnet("lc_trail")
    return m and util.JSONToTable(m.data[2]) or nil
end
local function sends() local n = 0 for _, m in ipairs(net.sent) do if m.name == "lc_trail" then n = n + 1 end end return n end
-- the map's nodegraph: an L, round a corner
local graphWas, statsWas, badWas = LC.NavGraph, LC.NavStats, LC.BadLinks
local function N(x, y) return { pos = G0 + Vector(x, y, 0), adj = {}, comp = 1 } end
local A, B, C, D = N(0, 0), N(600, 0), N(1200, 0), N(1200, 600)
local island = { pos = G0 + Vector(-900, 900, 0), adj = {}, comp = 2 }
local function Link(a, b) local d = a.pos:Distance(b.pos) a.adj[#a.adj + 1] = { b, d } b.adj[#b.adj + 1] = { a, d } end
Link(A, B) Link(B, C) Link(C, D)
LC.NavGraph = { nodes = { A, B, C, D, island }, main = 1, links = 3 }
LC.NavGraphReady()
local from, to = G0 + Vector(-40, 10, 0), G0 + Vector(1210, 640, 0)
local pts = LC.NavPathPoints(from, to, "citizen")
ok(type(pts) == "table" and #pts == 5 and pts[3] == C.pos and pts[#pts] == to, "the way follows the nodegraph round the corner, node by node, ending at the objective", pts and #pts)
local again = LC.NavPathPoints(from, to, "citizen")
local same = #again == #pts
for i = 1, #pts do if again[i] ~= pts[i] then same = false end end
ok(same, "the same way every time it's asked (no side steps: the trail doesn't jump about)")
ok(LC.NavPathPoints(from, island.pos, "citizen") == false, "(somewhere it can't be walked to: false)")
local route = LC.TrailRoute(from, to, "citizen")
ok(#route == 5 and route[#route] == to, "the trail's way uses it", #route)
do -- (14 November: no way there and walls between: no trail at all, never a line through the walls)
    local walls = _walls
    local nw = LC.TrailNoWay
    _walls = { { a = G0 + Vector(-3000, 450, 0), b = G0 + Vector(700, 450, 0) } } -- (between the island and every node)
    local r = LC.TrailRoute(from, island.pos, "citizen")
    _walls = walls
    ok(#r == 0 and LC.TrailNoWay == nw + 1, "no way there: no line drawn through the walls (the marker still shows where)", #r)
end
-- points closer than a step are one, and a very long way is cut short
local many = {}
for i = 1, 300 do many[#many + 1] = G0 + Vector(i * 50, 0, 0) end
many[#many + 1] = many[#many] + Vector(10, 0, 0)
local nodesWas = LC.NavPathPoints
LC.NavPathPoints = function() return many end
local long = LC.TrailRoute(G0, many[#many], "citizen")
ok(#long == LC.TrailConfig.MAX_POINTS, "a long way is sent a stretch at a time", #long)
LC.NavPathPoints = function() return { G0 + Vector(20, 0, 0), G0 + Vector(30, 0, 0), G0 + Vector(400, 0, 0) } end
ok(#LC.TrailRoute(G0, G0 + Vector(400, 0, 0), "citizen") == 1, "points right on top of each other (and of you) are one")
LC.NavPathPoints = nodesWas
-- a player on a quest: sent when it starts, and only again when it needs to be
local objWas = LC.QuestObjectivePos
local goal = to
LC.QuestObjectivePos = function(p) return p.lcTestGoal end
local walker = newPlayer("TrailWalker", "citizen")
walker:SetPos(from)
walker.lcTestGoal = goal
-- (players earlier tests left on a quest have a trail; with the stub above they have no objective and would be
-- sent "no trail" in the middle of these counts)
for _, p in ipairs(player.GetAll()) do if p ~= walker then p.lcTrail = nil end end
local now = 5000
local n0 = sends()
LC.TrailTick(now)
local got = payload()
ok(sends() == n0 + 1 and got and got.p and #got.p == 15 and got.g[1] == math.floor(goal.x), "on a quest, the way is sent: every point, and the objective", got and got.p and #got.p)
ok(walker.lcTrail and walker.lcTrail.from == from, "(and kept, to tell when you've wandered off it)")
LC.TrailTick(now + 1)
ok(sends() == n0 + 1, "standing still, it isn't sent again")
walker:SetPos(G0 + Vector(600, 0, 0))
LC.TrailTick(now + 2)
ok(sends() == n0 + 1, "walking along it, it isn't sent again either")
walker:SetPos(G0 + Vector(600, -500, 0))
LC.TrailTick(now + 3)
ok(sends() == n0 + 2 and walker.lcTrail.from == walker:GetPos(), "wandering off it, it's worked out again from where you are")
walker.lcTestGoal = goal + Vector(0, 400, 0)
LC.TrailTick(now + 4)
ok(sends() == n0 + 3, "the objective moves (someone you're following walks off): worked out again")
walker:SetPos(walker:GetPos() + Vector(0, 200, 0))
LC.TrailTick(now + 5)
ok(sends() == n0 + 3, "a little further on, not yet")
LC.TrailTick(now + 20)
ok(sends() == n0 + 4, "but every few seconds while you're on the move, it is")
walker:SetPos(walker.lcTestGoal + Vector(30, 0, 0))
LC.TrailTick(now + 21)
got = payload()
ok(sends() == n0 + 5 and got and got.p == nil and walker.lcTrail == nil, "at the objective, the trail is taken away")
LC.TrailTick(now + 22)
ok(sends() == n0 + 5, "(once)")
-- hidden in C > Settings: none worked out, and the one showing goes
walker:SetPos(from)
LC.TrailTick(now + 23)
ok(walker.lcTrail ~= nil, "(away again: a trail)")
walker.GetInfoNum = function(_, name, d) if name == "lc_trail_show" then return 0 end return d end
LC.TrailTick(now + 24)
ok(walker.lcTrail == nil and payload() and payload().p == nil, "a player who's hidden the trail gets none")
walker.GetInfoNum = nil
_setcvar("lc_trail", "0")
LC.TrailTick(now + 25)
ok(walker.lcTrail == nil, "lc_trail 0: nobody does")
_setcvar("lc_trail", "1")
LC.TrailTick(now + 25.5)
ok(walker.lcTrail ~= nil, "(on again: a trail)")
walker.lcForgetUntil = CurTime() + 60
LC.TrailTick(now + 25.6)
ok(walker.lcTrail == nil and payload() and payload().p == nil, "Breen's water clouds their memory: the trail goes too, as the quest tracker does")
walker.lcForgetUntil = nil
walker.lcTestGoal = nil
LC.TrailTick(now + 26)
ok(walker.lcTrail == nil, "no quest, no trail")
-- a full server: only a few worked out each second, the rest wait their turn
local crowd = {}
for i = 1, LC.TrailConfig.BUDGET + 3 do
    local p = newPlayer("TrailCrowd" .. i, "citizen")
    p:SetPos(from + Vector(0, i * 5, 0))
    p.lcTestGoal = goal
    crowd[#crowd + 1] = p
end
local n1 = sends()
LC.TrailTick(now + 30)
ok(sends() - n1 == LC.TrailConfig.BUDGET, "a crowd: no more than a few ways a second", sends() - n1)
LC.TrailTick(now + 31)
ok(sends() - n1 == LC.TrailConfig.BUDGET + 3, "the rest get theirs the next second")
LC.QuestObjectivePos = objWas
ok(LC.QuestObjectivePos(walker) == nil, "(the real thing: no quest, nowhere to point)")
for _, p in ipairs(crowd) do p.lcTestGoal = nil p.lcTrail = nil p:SetPos(Vector(-150000, 150000, 0)) end
LC.NavGraph = graphWas
LC.NavGraphReady()
if statsWas then LC.NavStats = statsWas end
if badWas then LC.BadLinks = badWas end
-- where you are, for the panel of what you can do
local rz = LC.AddZone(G0 + Vector(5000, 0, 0), 300, "rebel", 0)
walker:SetPos(G0 + Vector(5000, 50, 0))
ok(LC.WhereKind(walker) == "rebel", "standing on rebel ground: the panel knows", LC.WhereKind(walker))
walker:SetPos(G0 + Vector(9000, 0, 0))
ok(LC.WhereKind(walker) == "", "nowhere in particular: nothing")
LC.RemoveZone(rz)
walker:SetPos(Vector(-150000, 150000, 0))
do -- the straight walk (the owner, 11 November): points you could walk straight past are left out
    _setcvar("lc_trail_straight", 1)
    local from = G0 + Vector(20000, 0, 0)
    local pts = { from + Vector(-200, 300, 0), from + Vector(300, 300, 0), from + Vector(900, 0, 0), from + Vector(900, 0, 400), from + Vector(1500, 0, 400) }
    local out = LC.TrailShortcut(from, pts)
    ok(#out == 3 and out[1] == pts[3] and out[#out] == pts[5], "the trail starts toward the furthest point in plain reach on your own level, not the nearest path node", #out)
    ok(#LC.TrailShortcut(from, { from + Vector(0, 0, 500), from + Vector(600, 0, 500) }) == 2, "never straight to another floor")
    _setcvar("lc_trail_straight", 0)
    ok(#LC.TrailShortcut(from, pts) == 5, "lc_trail_straight 0: every point, as before")
    _setcvar("lc_trail_straight", 1)
end
end
GuidanceTests()

----------------------------------------------------------------------
section("Playtest fixes (7 November, CP): the old job's looks and kit go, ration vouchers, the CP Commissary's daily kit and vest charging, the radio's R, the editor and sleep, rebels' bodies")
function UnitLifeTests()
-- 1. a new faction: the Union job, its tools and its suit go, the saved job too
do
    local p = newPlayer("RecCleaner", "citizen")
    p:SetPos(Vector(-161000, 161000, 0))
    local fired = {}
    hook.Add("LivingCityFactionChanged", "RecTest", function(pl, fid) if pl == p then fired[#fired + 1] = fid end end)
    LC.SetFaction(p, "cp", nil, true)
    hook.Remove("LivingCityFactionChanged", "RecTest")
    ok(fired[1] == "cp", "changing faction says so (LivingCityFactionChanged), for the pass that tidies up after it")
    -- (as a rejoin after a restart left them: the job read back from the save, its kit, the suit's skin)
    p:SetNW2String("lcj_job", "cleanup")
    p:SetPData("lcj_job", "cleanup")
    p:Give("weapon_lc_hoover") p:Give("weapon_lc_sprayer")
    p:SetSkin(3) p:SetBodygroup(0, 2)
    p.chat = {}
    LC.ReconcileAppearance(p)
    ok(LC.Job(p) == nil and p:GetNW2String("lcj_job", "") == "" and p:GetPData("lcj_job", "") == "", "a unit holds no Union job: taken, and the saved one too, so a restart doesn't bring it back")
    ok(not p:HasWeapon("weapon_lc_hoover") and not p:HasWeapon("weapon_lc_sprayer"), "and the job's tools go")
    ok(p:GetSkin() == 0 and p:GetBodygroup(0) == 0, "and the suit's skin and bodygroups: the uniform's own look")
    ok(has(p.chat, "taken your job"), "and they're told")
    p:SetPData("lcj_job", "groundskeeper")
    LC.ReconcileAppearance(p)
    ok(p:GetPData("lcj_job", "") == "", "a job only in the save is cleared as well")
    -- connecting again with a job saved: gone a few seconds in
    p:SetPData("lcj_job", "cleanup")
    p.admin = true -- (still allowed in Civil Protection when they come back: no standing in this test)
    hook.Run("PlayerInitialSpawn", p)
    _run(4)
    p.admin = nil
    ok(p:GetNW2String("lcf_faction", "") == "cp" and p:GetNW2String("lcj_job", "") == "" and p:GetPData("lcj_job", "") == "",
        "connecting as a unit with a job saved: it's taken", p:GetNW2String("lcf_faction", "") .. " " .. p:GetNW2String("lcj_job", ""))
    -- a rank change says so too
    local ranked = false
    hook.Add("LivingCityRankChanged", "RecTest", function(pl) if pl == p then ranked = true end end)
    p:SetPData("lcf_xp_cp", 5000) LC.AddXP(p, 0)
    hook.Remove("LivingCityRankChanged", "RecTest")
    ok(ranked, "a new rank says so (LivingCityRankChanged)")
    -- any faction that can't work, not only units
    local a = newPlayer("RecAdmin", "admin")
    a:SetNW2String("lcj_job", "porter")
    a.chat = {}
    LC.ReconcileAppearance(a)
    ok(a:GetNW2String("lcj_job", "") == "" and has(a.chat, "City Administrator now"), "the City Administrator holds no Union job either")
    -- citizens and the Resistance keep theirs, looks and all
    local c = newPlayer("RecCitizen", "citizen")
    c:SetNW2String("lcj_job", "groundskeeper") c:SetPData("lcj_job", "groundskeeper")
    c:SetSkin(4)
    LC.ReconcileAppearance(c)
    ok(c:GetNW2String("lcj_job", "") == "groundskeeper" and c:GetSkin() == 4, "a citizen keeps their job and their own look")
    for _, q in ipairs({ p, a, c }) do q:SetPos(Vector(-120000, -120000, 0)) end
end
-- 2 and 3. ration vouchers; the CP Commissary's daily kit, and its charge for the vest
do
    local S0 = Vector(-163000, 163000, 0)
    local u = newPlayer("RecVoucher", "cp")
    u:SetPos(S0)
    u.lcnRationAt = 0
    for id in pairs(LC.Inventory(u)) do if id == "ration" or id == "ration_voucher" or id == "bandage" then LC.TakeItem(u, id, 99) end end
    ok(LC.IssueDutyAllocation(u) and LC.HasItem(u, "ration_voucher") and not LC.HasItem(u, "ration"), "a unit's duty allocation is a ration voucher, not a packet")
    local ota = newPlayer("RecOTA", "ota")
    ota:SetPos(S0 + Vector(0, 3000, 0))
    ota.lcnRationAt = 0
    LC.IssueDutyAllocation(ota)
    ok(not LC.HasItem(ota, "ration_voucher"), "the Overwatch don't eat: no voucher")
    local sup = ents.Create("lc_cpsupply") sup:SetPos(S0 + Vector(50, 0, 0))
    u:RemovePData("lc_cp_daily_at")
    local vials = #ents.FindByClass("item_healthvial")
    u.chat = {}
    LC.UseCPSupply(u, sup)
    ok(LC.HasItem(u, "ration") and not LC.HasItem(u, "ration_voucher") and has(u.chat, "for your voucher"), "the CP Commissary takes the voucher and hands over a ration packet")
    ok(#ents.FindByClass("item_healthvial") == vials and LC.HasItem(u, "health_vial", 1) and LC.HasItem(u, "bandage", 3), "and once a city day, a health vial (in the pockets, not on the floor: the owner, 11 November) and a bandage (on top of the bandages it tops up)")
    do -- turning in what you carry (the owner, 11 November)
        LC.GiveItem(u, "scrap", 2)
        local before = LC.Credits(u)
        local scrapPrice = LC.CPTurnInPrice(u, "scrap")
        ok(scrapPrice and scrapPrice >= 1 and LC.CPTurnInPrice(u, "bandage") == nil and LC.CPTurnInPrice(u, "health_vial") == nil,
            "the CP Commissary takes what a unit carries that isn't their own issue")
        local listed = false
        for _, s in ipairs(LC.CPTurnInList(u)) do if s.id == "scrap" and s.n == 2 then listed = true end end
        ok(listed and LC.CPTurnIn(u, "scrap", true) and not LC.HasItem(u, "scrap") and LC.Credits(u) == before + scrapPrice * 2, "turned in, all of it: paid for each")
        local far = newPlayer("TurnInFar", "cp") far:SetPos(S0 + Vector(0, 9000, 0)) LC.GiveItem(far, "scrap", 1)
        ok(not LC.CPTurnIn(far, "scrap") and LC.HasItem(far, "scrap"), "only standing at one")
        far:SetPos(Vector(-150000, 150000, 0))
    end
    ok(not LC.CPDailyKitDue(u), "not again the same day")
    u.lcSupplyNext = 0
    LC.UseCPSupply(u, sup)
    ok(#ents.FindByClass("item_healthvial") == vials and not LC.HasItem(u, "health_vial", 2), "(no second vial)")
    u:SetPData("lc_cp_daily_at", tostring(os.time() - 999999))
    ok(LC.CPDailyKitDue(u), "the next city day it's due again")
    -- a voucher at a dispenser
    LC.GiveItem(u, "ration_voucher", 1)
    u.chat = {}
    ok(LC.UseDispenser(u, nil) and not LC.HasItem(u, "ration_voucher") and has(u.chat, "Voucher accepted"), "a ration dispenser takes a voucher too")
    -- standing at the Commissary charges the vest
    u:SetArmor(0)
    u.chat = {}
    LC.CPSupplyRechargeTick()
    ok(u:Armor() == 5 and has(u.chat, "vest is charging"), "standing at the CP Commissary charges a unit's vest, 5 a second", u:Armor())
    for _ = 1, 20 do LC.CPSupplyRechargeTick() end
    ok(u:Armor() == 50 and has(u.chat, "Vest charged"), "up to their issue (50 for a street rank), and no further", u:Armor())
    u:SetArmor(0)
    u:SetPos(S0 + Vector(800, 0, 0))
    LC.CPSupplyRechargeTick()
    ok(u:Armor() == 0, "not from across the room")
    u:SetPos(S0)
    sup:SetNW2Bool("lc_nopower", true)
    LC.CPSupplyRechargeTick()
    ok(u:Armor() == 0, "not with the power out")
    sup:SetNW2Bool("lc_nopower", false)
    local cit = newPlayer("RecVestCitizen", "citizen")
    cit:SetPos(S0)
    cit:SetArmor(0)
    LC.CPSupplyRechargeTick()
    ok(cit:Armor() == 0, "nor a citizen's")
    sup:Remove()
    for _, q in ipairs({ u, ota, cit }) do q:SetPos(Vector(-120000, -120000, 0)) end
end
-- 4. R with the radio up puts it away, and the same R held down doesn't bring it straight back
do
    local r = newPlayer("RecRadio", "cp")
    local function Load(path)
        local was = SWEP
        SWEP = {}
        assert(loadstring(_WEAPONSRC[path], path))()
        local t = SWEP
        SWEP = was
        return setmetatable({ GetOwner = function() return r end }, { __index = t })
    end
    local radio, hands = Load("weapons/weapon_lc_radio.lua"), Load("weapons/weapon_lc_hands.lua")
    if not r:HasWeapon("weapon_lc_hands") then r:Give("weapon_lc_hands") end
    if not r:HasWeapon("weapon_lc_radio") then r:Give("weapon_lc_radio") end
    r:SelectWeapon("weapon_lc_radio")
    r.lcLastWeapon = "weapon_lc_radio"
    r.keys = { [IN_RELOAD] = true }
    radio:Reload()
    ok(r:GetActiveWeapon():GetClass() == "weapon_lc_hands", "R with the radio up: your hands")
    hands:Reload()
    hands.nextReload = 0
    hands:Reload()
    ok(r:GetActiveWeapon():GetClass() == "weapon_lc_hands", "and with R still held, the hands don't draw the radio straight back out (it flashed and came back)")
    r.keys = {}
    hook.Run("KeyRelease", r, IN_RELOAD)
    ok(not LC.ReloadHeld(r), "let go of R")
    hands.nextReload = 0
    r.keys = { [IN_RELOAD] = true }
    hands:Reload()
    ok(r:GetActiveWeapon():GetClass() == "weapon_lc_radio", "and a fresh R draws it again, as before")
    LC.HoldReload(r)
    r.keys = {}
    ok(not LC.ReloadHeld(r), "(a missed let-go doesn't stick: R up is R up)")
    r:SetPos(Vector(-120000, -120000, 0))
end
-- 5. the editor in hand: no sleepiness
do
    local e = newPlayer("RecEditor", "citizen")
    e.admin = true
    local tool = { GetClass = function() return "gmod_tool" end, GetMode = function() return "livingcity_editor" end, IsValid = function() return true end }
    e.GetActiveWeapon = function() return tool end
    local t0 = CurTime()
    e.lcAwakeSince = t0 - 10 * 24 * 3600
    e:SetNW2Bool("lc_tired", true)
    LC.RestTick(t0)
    ok(not e:GetNW2Bool("lc_tired", false), "with the Living City editor in hand you're never exhausted")
    local awake = t0 - e.lcAwakeSince
    LC.RestTick(t0 + 500)
    ok(math.abs((t0 + 500 - e.lcAwakeSince) - awake) < 0.01, "and the hours with it out don't count as time awake")
    e.GetActiveWeapon = nil
    LC.RestTick(t0 + 505)
    ok(not e:GetNW2Bool("lc_tired", false), "put it away: not exhausted that instant (the owner, 11 November), six minutes to find a bed")
    LC.RestTick(t0 + 505 + 365)
    ok(e:GetNW2Bool("lc_tired", false), "after those six minutes you're as tired as you were")
    e.lcAwakeSince = CurTime() e:SetNW2Bool("lc_tired", false) LC.RestTick(CurTime())
    e:SetPos(Vector(-120000, -120000, 0))
end
-- 6. a dead rebel lies in the rebel's own clothes
do
    local npc = ents.Create("npc_citizen")
    npc:SetModel("models/humans/group03/male_07.mdl")
    npc:SetPos(Vector(-165000, 165000, 0))
    npc:SetSkin(2) npc:SetBodygroup(0, 3) npc:SetMaterial("models/rebel_test")
    local rag = LC.MakeBody(npc, "rebel")
    ok(IsValid(rag) and rag:GetModel() == npc:GetModel() and rag:GetSkin() == 2 and rag:GetBodygroup(0) == 3 and rag:GetMaterial() == "models/rebel_test",
        "a rebel's body has their model, skin, bodygroups (their gear) and material", rag and rag:GetModel())
    if IsValid(rag) then rag:Remove() end
    npc:Remove()
end
end
UnitLifeTests()
function RadioJobsTests() -- (the owner, 12 November: "if you hold a radio in your hands, you can open the 'Jobs' screen/board")
section("Jobs over the radio: the radio up opens your side's jobs from anywhere")
local u = newPlayer("RadioJobsUnit", "cp")
local sent = 0
local sbWas, tbWas = LC.SendBoard, LC.TransmitBands
LC.SendBoard = function(p) if p == u then sent = sent + 1 end end
if not u:HasWeapon("weapon_lc_hands") then u:Give("weapon_lc_hands") end
u:SelectWeapon("weapon_lc_hands")
local okA, why = LC.RadioJobs(u)
ok(not okA and why ~= nil and sent == 0, "without the radio up: no (and it says how)", tostring(why))
if not u:HasWeapon("weapon_lc_radio") then u:Give("weapon_lc_radio") end
u:SelectWeapon("weapon_lc_radio")
ok(LC.RadioHeld(u) and LC.RadioJobs(u) == true and sent == 1, "the radio up: the jobs board opens (F4's Jobs tab)")
ok(LC.TargetActions and LC.TargetActions.radiojobs ~= nil, "F1 has it while the radio is up (the action behind it)")
u.lcRadioJobsAt = 0
LC.TargetActions.radiojobs(u)
ok(sent == 2, "(and it works)")
-- right click on the radio: its own menu (the owner, 13 November), which has the jobs and, for an Insider, the switch
local was = SWEP
SWEP = {}
assert(loadstring(_WEAPONSRC["weapons/weapon_lc_radio.lua"], "weapon_lc_radio"))()
local radio = setmetatable({ GetOwner = function() return u end, GetNW2String = function(_, _, d) return d end,
    SetNW2String = function() end, SetNW2Int = function() end }, { __index = SWEP })
SWEP = was
LC.TransmitBands = function() return { "cp" } end
net.sent = {}
radio:SecondaryAttack()
ok(_lastnet("lc_radio_menu") ~= nil and sent == 2, "right click on the radio: the Radio menu opens (the jobs are on it)")
LC.TransmitBands = function() return { "cp", "resistance" } end
local tuned = 0
local tuneWas = LC.TuneTransmitter
LC.TuneTransmitter = function() tuned = tuned + 1 return "cp" end
ok(LC.TargetActions.radiotune and LC.TargetActions.radiotune(u) == true and tuned == 1, "with two bands (an Insider), Switch frequency on the Radio menu switches it")
LC.SendBoard, LC.TransmitBands, LC.TuneTransmitter = sbWas, tbWas, tuneWas
u:SelectWeapon("weapon_lc_hands")
u:SetPos(Vector(-120000, -120000, 0))
end
RadioJobsTests()

function RadioHQTests() -- (the owner, 13 November: HQ calls only with the radio out; right click opens the Radio menu; the resupply scanner)
section("HQ only over the radio: a unit's backup, 10-20, records, BOLO and resupply need the radio up")
local u = newPlayer("HQUnit", "cp")
u:SetPos(Vector(-161000, 91000, 0))
local okR, whyR = LC.RadioOnly(u)
ok(not okR and whyR == LC.RADIO_NEEDED, "a unit without the radio up: no (and it says how)", tostring(whyR))
local okB, whyB = LC.CallBackup(u)
ok(not okB and whyB == LC.RADIO_NEEDED, "no backup without it", tostring(whyB))
ok(LC.RadioChatBlocked(u, "bolo") and LC.RadioChatBlocked(u, "records"), "!bolo and !records: not without it")
local cit = newPlayer("HQCitizen", "citizen")
ok(LC.RadioOnly(cit) == true and not LC.RadioChatBlocked(cit, "records"), "everyone else's calls are as they were")
local _, why1020 = LC.Mark1020(u, true)
ok(why1020 ~= LC.RADIO_NEEDED, "the backup call's own 10-20 isn't held up (it went out on the radio)")
u:Give("weapon_pistol")
u:SelectWeapon("weapon_pistol")
_radioUp(u)
ok(LC.RadioOnly(u) == true and not LC.RadioChatBlocked(u, "bolo"), "with the radio up: yes")
ok(LC.BackupViolent(u), "a gun put away for the radio still counts as a gun out: backup comes armed")
u.lcGunOutAt = CurTime() - 21
u.lcShotAt = nil
ok(not LC.BackupViolent(u), "(20 seconds later, not any more)")
_setcvar("lc_radio_only", 0)
_radioDown(u)
ok(LC.RadioOnly(u) == true, "lc_radio_only 0: the old way")
_setcvar("lc_radio_only", 1)

section("Half-Life 2's ammo limits, not Garry's Mod's 9999 of everything")
ok(LC.AmmoMax("Pistol") == 150 and LC.AmmoMax("SMG1") == 225 and LC.AmmoMax("Buckshot") == 30 and LC.AmmoMax("AR2") == 60 and LC.AmmoMax("357") == 12,
    "pistol 150, SMG 225, shotgun 30, pulse rifle 60, .357 12 (the owner, 13 November)")
local am = newPlayer("AmmoCap", "cp")
am.ammo = { Pistol = 400, SMG1 = 100, AR2 = 999 }
LC.ClampAmmo(am)
ok(am:GetAmmoCount("Pistol") == 150 and am:GetAmmoCount("SMG1") == 100 and am:GetAmmoCount("AR2") == 60, "anyone over a limit is cut down to it; under it, left alone")
ok(LC.AmmoCapped("Pistol", 400) == 150 and LC.AmmoCapped("Pistol", 20) == 20, "rounds put back (waking from a dream, after a story) stop at the limit")
am.ammo = { Buckshot = 99 }
hook.Run("PlayerSpawn", am)
_run(1)
ok(am:GetAmmoCount("Buckshot") == 30, "and on every spawn and respawn (and after a close call, and waking from a dream)", am:GetAmmoCount("Buckshot"))
_setcvar("lc_hl2_ammo", 0)
ok(LC.AmmoMax("Pistol") == nil, "lc_hl2_ammo 0: Garry's Mod's own again")
_setcvar("lc_hl2_ammo", 1)
am:SetPos(Vector(-120000, -120000, 0))

section("Resupply: what a unit is shortest of, and what the crate holds")
local r = newPlayer("RSUnit", "cp")
r:SetPos(Vector(-162000, 92000, 0))
r:SetNW2Int("lcf_rank", 2)
r.weps = { "weapon_pistol" }
r.active = "weapon_pistol"
r.ammo = { Pistol = 10 }
r.maxhp = 100
r:SetHealth(40)
r.armor = 40
local needs = LC.ResupplyNeeds(r)
ok(#needs == 2 and needs[1].kind == "ammo" and needs[1].ammo == "Pistol" and needs[2].kind == "health",
    "pistol rounds under 30% first, then health (the vest at 40 of 50 is fine)", (needs[1] and needs[1].kind or "-") .. ", " .. (needs[2] and needs[2].kind or "-"))
r:SetHealth(5)
r.ammo = { Pistol = 40 } -- (just under 30% of Half-Life 2's 150)
needs = LC.ResupplyNeeds(r)
ok(needs[1] and needs[1].kind == "health" and string.find(needs[1].label, "two", 1, true), "near death: health first, two vials")
r.armor = 5
r.ammo = { Pistol = 10, SMG1 = 0, Buckshot = 0 }
r.weps = { "weapon_pistol", "weapon_smg1", "weapon_shotgun" }
needs = LC.ResupplyNeeds(r)
ok(#needs == 3, "never more than three", #needs)
local give, words, essential = LC.ResupplyContents(r)
local all = table.concat(words, ", ")
ok(essential and string.find(all, "flashbang", 1, true), "a Metrocop's crate has a flashbang", all)
ok(LC.CuffCount(r) >= LC.CP_CUFFS or string.find(all, "cuffs", 1, true), "and cuffs back up to issue, if short", all)
r:SetNW2Int("lcf_rank", 1)
ok(LC.ResupplyGrenade(r) == "gren_smoke", "a Recruit's: smoke")
r:SetNW2Int("lcf_rank", 5)
ok(LC.ResupplyGrenade(r) == "gas_bomb", "the Overwatch's: a poison gas bomb")
r:SetNW2Int("lcf_rank", 2)
-- stocked: nothing to send
r.ammo = { Pistol = 72 }
r.weps = { "weapon_pistol" }
r:SetHealth(100)
r.armor = 50
for _ = 1, LC.CP_CUFFS do if LC.CuffCount(r) < LC.CP_CUFFS then LC.GiveItem(r, "zipties", 1) end end
_radioUp(r)
local okS, whyS = LC.RequestResupply(r)
ok(not okS and string.find(whyS or "", "stocked", 1, true), "stocked: HQ sends nothing", tostring(whyS))
-- short of rounds, but indoors
r.ammo = { Pistol = 5 }
local tl = util.TraceLine
util.TraceLine = function(t) return { HitSky = false, HitPos = t.start + Vector(0, 0, 120), Hit = true, Fraction = 0.01 } end
local okI, whyI = LC.RequestResupply(r)
ok(not okI and string.find(whyI or "", "open sky", 1, true), "indoors or underground: no scanner can reach you", tostring(whyI))
util.TraceLine = function(t) return { HitSky = true, HitPos = t.start + Vector(0, 0, 2000), Hit = true, Fraction = 0.1 } end
local okO, whyO = LC.RequestResupply(r)
util.TraceLine = tl
ok(okO == true and IsValid(LC.ResupplyOut[r]), "under open sky: a scanner is on its way", tostring(whyO))
local again, whyA = LC.RequestResupply(r)
ok(not again and string.find(whyA or "", "already", 1, true), "one at a time", tostring(whyA))
local sc = LC.ResupplyOut[r]
ok(sc and sc.lcDrop and sc.lcTop and sc.lcDrop.z < sc.lcTop.z and sc.lcDrop.z <= r:GetPos().z + 170, "it comes down the shaft of sky above where you called from")
ok(sc and sc.lcHeading and math.abs(sc.lcHeading.x) + math.abs(sc.lcHeading.y) == 1, "and leaves north, south, east or west")
LC.ResupplyOut[r] = nil
if IsValid(sc) then sc:Remove() end
local okW, whyW = LC.RequestResupply(r)
ok(not okW and string.find(whyW or "", "Next one in", 1, true), "then not again for a while", tostring(whyW))
-- the crate broke: what's in it lies on the ground
local spilled = LC.ResupplySpill({ lcFor = r, lcWords = { "x" }, lcGive = { { cls = "item_ammo_pistol", n = 2 }, { item = "gren_flash", n = 1 } } }, r:GetPos())
ok(#spilled == 3, "the crate breaks and leaves what was in it on the ground", #spilled)
for _, e in ipairs(spilled) do if IsValid(e) then e:Remove() end end
-- the Radio menu's actions
ok(LC.TargetActions.resupply ~= nil and LC.TargetActions.radiotune ~= nil, "Request resupply and Switch frequency: the Radio menu's actions")
_radioDown(r)
r:SetPos(Vector(-120000, -120000, 0))
u:SetPos(Vector(-120000, -120000, 0))
end
RadioHQTests()

function Freq7KitTests() -- (the owner, 13 November: no Freq 7 broadcasting without a transmitter; Fighters are issued one)
section("Freq 7: no broadcasting without a transmitter, and a Fighter's issued radio and transmitter")
local m = newPlayer("F7Member", "resistance")
m:SetNW2Int("lcf_rank", 2)
m:SetPos(Vector(-167000, 97000, 0))
LC.GiveItem(m, "radio_tuned", 1)
local okB, whyB = LC.RebelCallBackup(m)
ok(not okB and string.find(whyB or "", "transmitter", 1, true), "a Freq 7 radio alone can't call for backup", tostring(whyB))
local okP, whyP = LC.RebelSendPosition(m)
ok(not okP and string.find(whyP or "", "transmitter", 1, true), "nor send their position", tostring(whyP))
ok(LC.IssueRebelRadio(m) == 0 and not LC.HasItem(m, "radio_transmitter"), "a Member isn't issued one")
ok(not LC.IssuedLocked(m, "radio_tuned"), "and can sell or hand over their own radio, as before")
local f = newPlayer("F7Fighter", "resistance")
f:SetNW2Int("lcf_rank", 3)
f:SetPos(Vector(-167100, 97000, 0))
hook.Run("LivingCityRankChanged", f, "resistance", 3)
ok(LC.HasItem(f, "radio_tuned") and LC.HasItem(f, "radio_transmitter"), "promoted to Fighter: a Freq 7 radio and a transmitter, issued")
ok(LC.SendsOnFreq7(f), "so they can send on Freq 7")
ok(LC.IssuedLocked(f, "radio_transmitter") and LC.IssuedLocked(f, "radio_tuned") and LC.SellPrice(f, "radio_transmitter") == nil, "theirs to keep: not sold, dropped, stashed or handed over")
ok(string.find(LC.IssuedWhy(f, "radio_transmitter"), "Freq 7 kit", 1, true) ~= nil, "(and it says so in the Resistance's words, not the Combine's)")
LC.GiveItem(f, "radio_transmitter", 1)
ok(not LC.IssuedLocked(f, "radio_transmitter"), "a spare can still go")
LC.TakeItem(f, "radio_transmitter", 2)
hook.Run("PlayerSpawn", f)
_run(2)
ok(LC.HasItem(f, "radio_transmitter"), "lost: a new one at the next spawn")
for _, p in ipairs({ m, f }) do p:SetPos(Vector(-120000, -120000, 0)) end
end
Freq7KitTests()

function GasMaskTests() -- (the owner, 13 November: gas masks, hands to the face, running from the gas)
section("Gas masks: off a uniform or the dead, four broken make one, a rebel in three carries one")
ok(LCS.Items.gas_mask and LCS.Items.gas_mask.contraband and LCS.Items.gas_mask_broken and LCS.Items.gas_mask_broken.contraband, "a gas mask, whole or broken, is contraband")
local rec = LCS.RecipesById.gas_mask
ok(rec and rec.needs.gas_mask_broken == 4, "four broken masks make one")
local whole, broken = 0, 0
for _ = 1, 400 do if LC.DeadUnitMask() == "gas_mask" then whole = whole + 1 else broken = broken + 1 end end
ok(whole > 140 and broken > 140, "a dead unit's mask: whole about half the time, else broken", whole .. " / " .. broken)
local reb = newPlayer("GMRebel", "resistance")
reb:SetPos(Vector(-163000, 93000, 0))
LC.GiveItem(reb, "uniform_cp", 1)
local okS = LC.ScavengeGasMask(reb)
_run(6)
ok(okS and LC.HasItem(reb, "gas_mask") and not LC.HasItem(reb, "uniform_cp"), "Scavenge gas mask: cut out of a uniform (the uniform's used up)")
local unit = newPlayer("GMUnit", "cp")
unit:SetPos(Vector(-163500, 93000, 0))
ok(not LC.ScavengeGasMask(unit), "a unit has their own")
_setcvar("lc_gasmask_rebels", 1)
local nr, nrst = LC.SpawnRebel(Vector(-164000, 94000, 4), nil)
ok(LC.NPCHasGasMask(nr, nrst), "a Resistance fighter can carry one")
local nc, ncst = LC.SpawnCitizen and LC.SpawnCitizen(Vector(-164000, 94100, 4)) or nil
if ncst then ok(not LC.NPCHasGasMask(nc, ncst), "a citizen never: it's contraband") end
_setcvar("lc_gasmask_rebels", 0)
local nr2, nr2st = LC.SpawnRebel(Vector(-164000, 94200, 4), nil)
ok(not LC.NPCHasGasMask(nr2, nr2st), "lc_gasmask_rebels 0: none do")
for _, n in ipairs({ nr, nc, nr2 }) do if IsValid(n) then n:Remove() end end
_setcvar("lc_gasmask_rebels", 0.33)

section("In the gas: masks go on by themselves, everyone else covers their mouth, coughs and runs, away from Combine units first")
local G = Vector(-166000, 96000, 0)
for npc in pairs(LC.NPCs) do if IsValid(npc) and npc:GetPos():Distance(G) < 3000 then npc:Remove() end end
local masked, mst = LC.SpawnRebel(G + Vector(30, 0, 4), nil)
mst.gasMask = true
local bare, bst = LC.SpawnRebel(G + Vector(-30, 0, 4), nil)
bst.gasMask = false
reb:SetPos(G + Vector(0, 30, 0))
reb:SetHealth(100)
local plain = newPlayer("GMPlain", "citizen")
plain:SetPos(G + Vector(0, -30, 0))
plain:SetHealth(100)
local mhp, bhp = masked:Health(), bare:Health()
LC.Detonate("gas", G, unit)
_run(1.5)
ok(masked:Health() == mhp and masked:GetNW2Bool("lc_gasmask_on", false), "a fighter with a mask puts it on and takes no harm")
ok(bare:Health() < bhp and bare:GetNW2String("lc_handface", "") == "mouth", "one without covers their mouth and chokes")
ok((bst.gasFleeUntil or 0) > CurTime() and bst.gasFleeTo ~= nil, "and runs from it")
ok(reb:Health() == 100 and reb:GetNW2Bool("lc_gasmask_on", false), "a player with a mask in their pockets puts it on by themselves")
ok(plain:Health() < 100 and plain:GetNW2String("lc_handface", "") == "mouth", "a player without one coughs with a hand over their mouth")
-- where to run: never the way the Combine units are, while there's another way out
local g = LC.GasClouds[#LC.GasClouds]
local from = bare:GetPos()
local spots = {}
for i = -1, 1 do spots[#spots + 1] = Vector(g.pos.x + g.r + 260, g.pos.y + i * 150, 0) end
local dest = LC.GasFleeSpot(bare, g, spots)
ok(LC.GasCombineOnTheWay(from, dest, spots) == 0 and dest:Distance(Vector(g.pos.x, g.pos.y, from.z)) > g.r, "it runs out of the gas the way with no Combine unit on it")
local ring = {}
for i = 0, 15 do local a = math.rad(i * 22.5) ring[#ring + 1] = Vector(g.pos.x + math.cos(a) * (g.r + 260), g.pos.y + math.sin(a) * (g.r + 260), 0) end
local dest2 = LC.GasFleeSpot(bare, g, ring)
ok(dest2 ~= nil and dest2:Distance(Vector(g.pos.x, g.pos.y, from.z)) > g.r, "surrounded: out of the gas all the same, into them if it must")
-- the gas gone: the masks come off by themselves
_run(25)
ok(not masked:GetNW2Bool("lc_gasmask_on", false) and not reb:GetNW2Bool("lc_gasmask_on", false), "once out of it a few seconds, the masks come off by themselves")
for _, n in ipairs({ masked, bare }) do if IsValid(n) then n:Remove() end end
for _, p in ipairs({ reb, plain, unit }) do p:SetPos(Vector(-120000, -120000, 0)) end
end
GasMaskTests()

