-- Shared dreams (sv_livingcity_dreams.lua): the secret endings, dreamt by everyone asleep
function DreamTests()
section("Shared dreams: the endings as dreams for everyone asleep")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0) -- (the older tests: the Administrator picks freely, and the city doesn't pick: DreamCrowdTests has the rules)
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
local errs0 = #_errors
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0) -- (hunger and thirst held still: the before and after must match exactly)
-- (and the city's other clocks on them: a minute of duty, which earns XP, or the rest tick, which notes when it
-- last looked at them, falling between the before and the after shows as a change; put back at the end)
local dutyXPWas, restTickWas = LCF.XP.duty_per_minute, LC.RestTick
LCF.XP.duty_per_minute = 0
LC.RestTick = function() end
_setcvar("lc_dream_delay", 10)
_setcvar("lc_dream_combine", 3)
local reloaded = 0
LC.EndingReload = function() reloaded = reloaded + 1 end
_files["livingcity/endings.json"] = nil
local CITY, DREAM = Vector(160000, 160000, 0), Vector(190000, 190000, 0)
-- a player's game, closer to the real thing: rounds in each gun, the ammunition carried
local AMMO_ID = { AR2 = 1, Pistol = 3, SMG1 = 4, ["357"] = 5, Buckshot = 7 }
local function Rich(p)
    p.clips, p.ammoT = { weapon_pistol = 12, weapon_crowbar = -1 }, { [3] = 40, [4] = 90 }
    p.GetWeapons = function(self)
        local o = {}
        for _, c in ipairs(self.weps) do
            local cls = c
            o[#o + 1] = { GetClass = function() return cls end, IsValid = function() return true end,
                Clip1 = function() return self.clips[cls] or -1 end, SetClip1 = function(_, n) self.clips[cls] = n end }
        end
        return o
    end
    p.GetWeapon = function(self, c) for _, w in ipairs(self:GetWeapons()) do if w:GetClass() == c then return w end end end
    p.GetAmmo = function(self) local o = {} for k, v in pairs(self.ammoT) do o[k] = v end return o end
    p.RemoveAllAmmo = function(self) self.ammoT = {} end
    p.SetAmmo = function(self, n, t) self.ammoT[AMMO_ID[t] or t] = n end
    return p
end
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p:SetNW2Float("lc_sleep_done", p.lcSleep.done)
    p:SetNW2Vector("lc_bed_top", at)
    p.lcBedKey = key
    p.lcBedFrom = at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
    return key
end
local s1 = Rich(newPlayer("DreamA", "citizen"))
local s2 = Rich(newPlayer("DreamB", "citizen"))
local s3 = Rich(newPlayer("DreamC", "citizen"))
local aw = Rich(newPlayer("DreamAwake", "citizen"))
_run(3) -- (their factions' loadouts and the like, given a moment after joining)
local bed1 = Asleep(s1, CITY)
Asleep(s2, CITY + Vector(0, 200, 0))
Asleep(s3, CITY + Vector(0, 400, 0))
aw:SetPos(CITY + Vector(600, 0, 0))
player.GetAll = function() return { s1, s2, s3, aw } end -- (just these, as in the endings' own tests)

-- with no dream point: the endings are as they always were
ok(not LC.DreamReady() and LC.DreamPoint() == nil, "no dream point on the map: no dreams")
ok(LC.TriggerEnding("hard", s1) and LC.EndingSession() ~= nil and LC.DreamQueued() == nil,
    "and a secret ending is the whole city's, as always (nothing waits for a dream)")
LC.CancelEnding()
local okNo, whyNo = LC.DreamStart("hard", nil, false)
ok(not okNo and string.find(tostring(whyNo), "dream point", 1, true), "a dream can't start without a dream point", whyNo)

-- the dream point (the editor's "Point: dream"), out of the map
local dp = LC.AddPoint(DREAM, 0, "dream")
ok(dp and LC.DreamReady() and LC.DreamPoint() == dp, "the editor's dream point: dreams are on")
ok(LC.ZONE_KINDS.dream and LC.POINT_KINDS.dream, "(a dream point and a dream zone are things the editor places)")

-- an ending set off in play is still the whole city's (the owner, 7 November: the G-Man is kept for the endings)
ok(LC.DreamDivert == nil, "with a dream point placed, an ending set off in play is still the whole city's (dreams are chosen, not set off: DreamMoodTests)")
-- tonight's dream, queued (the Administrator's pick does this)
local okQ = LC.DreamQueueEnding("hard", s1, "admin")
ok(okQ and LC.EndingAny() == nil and LC.DreamQueued() and LC.DreamQueued().id == "hard",
    "a dream chosen for tonight waits for the night (the city carries on)")

-- no opting out (the owner, 8 November: "make it so no one can opt out of dreams"); a stimulant keeps you out
LC.SlashCommands.dream(s2, "off")
ok(not LC.DreamOptedOut(s2) and not s2:GetNW2Bool("lc_dream_optout", false), "nobody can opt out (/dream off just says so)")
s2:SetNW2Float("lc_wired_until", CurTime() + 900)

-- everything about s1, before
LC.Inventory(s1).bread = 3
s1:SetPData("lci_inv", util.TableToJSON(LC.Inventory(s1)))
LC.AddCredits(s1, 37)
s1:SetPData("lce_standing", "55") s1:SetNW2Int("lce_standing", 55)
s1:SetPData("lcf_xp_citizen", "120")
LC.AddXP(s1, 0) -- (the rank and titles on show caught up with it, as any XP earned does: else a minute of duty catching them up later shows as a change)
s1:SetPData("lcj_job", "factory") s1:SetNW2String("lcj_job", "factory")
s1:SetNW2Int("lcf_rank", 2)
s1:SetNW2Float("lcn_hunger", 63.5) s1:SetNW2Float("lcn_thirst", 41)
s1:SetNW2String("lcd_disguise", "")
s1:SetNW2Int("lc_vest_cap", 50) s1:SetHealth(77) s1:SetMaxHealth(100) s1:SetArmor(25) -- (an issued vest: armour it may keep)
s1:SetModel("models/humans/group01/male_07.mdl") s1:SetSkin(2) s1:SetBodygroup(0, 1)
s1.lcDocs = { permit = 7, notes = { "a", "b" } }
s1.lcInv.bread = 3
s1:RemovePData("lc_burned")
local credits0, hp0 = LC.Credits(s1), s1:Health()
local before = LC.DreamSnapshot(s1)
-- (the awake citizen's Union work, and its tools, now rather than from the spawn timer mid-dream:
-- the job is random, and one with tools used to change their weapons during the comparison)
if LC.GiveUnionWork then LC.GiveUnionWork(aw) end
local awPos, awWeps = aw:GetPos(), #aw.weps
local cityNPC
for npc in pairs(LC.NPCs or {}) do if IsValid(npc) then cityNPC = npc break end end
local cityNPCPos = cityNPC and cityNPC:GetPos()

-- the time: a minute after the Administrator says good night
hook.Run("LivingCityDayPhase", "night", "dusk")
hook.Run("LivingCityCustomAnnouncement", "administrator", "night", "livingcity/administrator/night1.wav", false)
_run(3)
ok(LC.EndingAny() == nil, "not straight away after the good night")
_run(9)
local E = LC.EndingAny()
ok(E and E.dream and E.id == "hard", "about lc_dream_delay after the Administrator's good night, the dream begins", E and E.id)
local dream = E and E.dream
ok(s1.lcDreaming and s3.lcDreaming and not s2.lcDreaming and not aw.lcDreaming, "everyone asleep dreams it; whoever's on a stimulant, and the awake, don't")
ok(LC.EndingSession() == nil and not LC.TimeStopped and not GetGlobal2Bool("lc_timestop", false), "to the rest of the city there's no ending: no time stop")
ok(s1:GetPos():Distance(DREAM) < 1600 and s3:GetPos():Distance(DREAM) < 1600, "the dreamers are at the dream point")
ok(_files[LC.DreamFileOf(s1:SteamID64())] ~= nil and _files[LC.DreamFileOf(s3:SteamID64())] ~= nil, "a snapshot of each dreamer is saved to disk first")
ok(#s1.weps == 1 and s1.weps[1] == "weapon_lc_hands" and next(s1.ammoT) == nil, "in the dream they carry only their hands")
ok(hook.Run("PlayerCanPickupWeapon", s1, ents.Create("weapon_lc_hands")) ~= false and hook.Run("PlayerCanPickupWeapon", s1, ents.Create("weapon_pistol")) == false,
    "(the game asks before it hands them anything: their hands are let through, a gun isn't)")
ok(LC.BedSleepers[bed1] == s1 and not LC.BedFree(bed1, s2), "their bed stays theirs")
_run(5)
E = LC.EndingAny()
ok(E and E.phase ~= "gman", "no G-Man's vote in a dream (the owner, 7 November: the G-Man is kept for the endings)", E and E.phase)
ok(not aw.frozen and aw:GetPos():Distance(awPos) < 1 and #aw.weps == awWeps and not s2.frozen, "the awake (and whoever's on a stimulant) aren't touched: not frozen, not moved",
    tostring(aw.frozen) .. " " .. tostring(aw:GetPos():Distance(awPos)) .. " " .. #aw.weps .. "/" .. awWeps .. " " .. tostring(s2.frozen) .. " " .. table.concat(aw.weps, ","))
ok(not LC.TimeStopped and LC.StartEvent ~= nil, "and the city's time goes on")
_run(31)
E = LC.EndingAny()
ok(E and E.phase == "apocalypse", "nobody votes: the dream plays out", E and E.phase)
ok(#(dream.combine or {}) == 3, "it brings its own Combine units (lc_dream_combine)", #(dream.combine or {}))
local inside = true
for _, e in ipairs(E.ents or {}) do if IsValid(e) and not LC.DreamHolds(dream, e:GetPos(), true) then inside = false end end
ok(inside and #E.ents > 0, "everything it puts out is inside the dream", #E.ents)
ok(not cityNPC or (not dream.npcs[cityNPC] and not LC.DreamHolds(dream, cityNPC:GetPos(), true) and not cityNPC:GetNW2Bool("lc_dancing", false)),
    "the city's own NPCs aren't in it (not brought there, not dancing)", cityNPC and (tostring(cityNPC:GetPos()) .. " " .. tostring(cityNPC:GetNW2Bool("lc_dancing", false))))
-- nothing counts in a dream
LC.AddCredits(s1, 500)
ok(LC.Credits(s1) == credits0, "no credits gained in a dream")
ok(LC.GiveItem(s1, "bread", 1) == false, "nothing picked up")
ok(hook.Run("EntityTakeDamage", s1, _dmg(aw, 50)) == true, "nobody really hurt")
ok(LC.ReportCrime(s1, "assault", 60) == false, "no crimes")
ok(LC.NetAllowed(s1, "lc_action") == false and LC.NetAllowed(s1, "lc_ending_vote") ~= false and LC.NetAllowed(aw, "lc_action") ~= false,
    "the menus wait till they wake (only the vote and waking up go through); the awake are as ever")
-- whatever leaked through anyway (the last layer): put back on waking
s1:SetNW2Float("lcn_hunger", 5) s1:SetPData("lce_credits", "9999") s1:SetPData("lc_burned", "1")
s1.lcInv = {} s1:SetHealth(3) s1:SetModel("models/player/skeleton.mdl") s1:SetSkin(0) s1.lcDocs = nil s1:SetArmor(0)
s1:SetNW2String("lcj_job", "") s1:SetNW2Int("lcf_rank", 0)
-- the end of the song: no reload, everyone wakes
local made = {}
for _, e in ipairs(E.ents) do made[#made + 1] = e end
E.holdUntil, E.songEnds = CurTime(), true -- (the song's over)
_run(7)
ok(LC.EndingAny() == nil and reloaded == 0, "it ends without reloading the map", reloaded)
local gone = true
for _, e in ipairs(made) do if IsValid(e) then gone = false end end
for _, e in ipairs(dream.combine) do if IsValid(e) then gone = false end end
ok(gone, "everything the dream made is gone")
_run(4)
ok(not s1.lcDreaming and not s1:GetNW2Bool("lc_dreaming", false), "they wake")
local after = LC.DreamSnapshot(s1)
local function SameField(f) return LC.DreamSame(before[f], after[f]) end
ok(SameField("pdata"), "saved data (credits, standing, XP, faction, job, pockets...) as it was")
ok(LC.Credits(s1) == credits0 and s1:GetPData("lc_burned", nil) == nil, "(the credits it had; a key saved in the dream is gone again)")
ok(SameField("nw2"), "everything on show about them as it was (hunger, thirst, rank, job, disguise...)")
ok(s1:GetNW2Float("lcn_hunger", 0) == 63.5 and s1:GetNW2Int("lcf_rank", 0) == 2, "(hunger, rank)")
local memDiff = {}
for k, v in pairs(before.mem) do if not LC.DreamSame(v, after.mem[k]) and not string.find(k, "^lcHint") then memDiff[#memDiff + 1] = k end end
ok(#memDiff == 0, "what the server keeps about them in memory as it was (the tips since waking aside)", table.concat(memDiff, " "))
ok(LC.Inventory(s1).bread == 3 and s1.lcDocs and s1.lcDocs.permit == 7, "(their pockets and their papers)")
ok(s1:Health() == hp0 and s1:Armor() == 25 and s1:GetMaxHealth() == 100, "health and armour as they were", s1:Health() .. " " .. s1:Armor() .. " " .. s1:GetMaxHealth())
ok(SameField("looks") and s1:GetModel() == "models/humans/group01/male_07.mdl", "clothes and looks as they were (model, skin, bodygroups)", tostring(s1:GetModel()) .. " " .. tostring(before.looks.model) .. " " .. util.TableToJSON(after.looks) .. " " .. util.TableToJSON(before.looks))
ok(SameField("weapons") and s1.clips.weapon_pistol == 12, "every weapon back, with its rounds", util.TableToJSON(after.weapons) .. " / " .. util.TableToJSON(before.weapons))
ok(SameField("ammo") and s1.ammoT[3] == 40 and s1.ammoT[4] == 90, "and the ammunition they carried")
ok(s1.lcSleep and s1:GetNW2Bool("lc_sleeping", false) and LC.BedSleepers[bed1] == s1 and s1:GetPos():Distance(CITY) < 1,
    "back in their bed, still asleep")
ok(_files[LC.DreamFileOf(s1:SteamID64())] == nil and LC.DreamSnaps[s1:SteamID64()] == nil, "the snapshot goes once it all matches")
ok(not aw.frozen and aw:GetPos():Distance(awPos) < 1, "the awake never knew")
ok(LC.DreamQueued() == nil, "one dream a night: nothing waits now")

-- a disconnect in the middle of one: everything back the next time they join
concommand.list.lc_ending_reset_cooldown(nil, "lc_ending_reset_cooldown", {})
s3.lcSleep = s3.lcSleep or { t0 = CurTime(), done = CurTime(), last = CurTime(), slept = true }
local okD = LC.DreamStart("shalom", nil, false)
ok(okD and s1.lcDreaming, "a dream an admin starts (dream it now)")
-- someone falls asleep after it has begun: they join it, their screen is sent the ending, and they wake with the rest
do
    local awAt = aw:GetPos()
    aw.lcSleep = { t0 = CurTime(), done = CurTime(), last = CurTime(), slept = true }
    local sent0 = #net.sent
    _run(4.2)
    local got = false
    for i = sent0 + 1, #net.sent do local m = net.sent[i] if m.name == "lc_ending" and m.to == aw then got = true end end
    ok(aw.lcDreaming == LC.DreamActive.id and got and aw:GetPos():Distance(awAt) > 1000, "asleep after an ending's dream began: they're in it, and their screen has the ending")
    LC.DreamWakeOne(aw, "admin")
    _run(1.5)
    ok(not aw.lcDreaming and aw:GetPos():Distance(awAt) < 1 and LC.DreamActive ~= nil, "(woken, back where they lay; the dream goes on, and doesn't take them again)")
    aw.lcSleep = nil
    aw:SetNW2Bool("lc_sleeping", false)
end
local sid = s1:SteamID64()
local db = s1.pdata
s1.valid = false
LC.DreamSnaps[sid] = nil -- (a crash: nothing in memory, only the disk)
local s1b = Rich(_makeplayer("DreamA", CITY + Vector(3000, 0, 0)))
s1b.sid, s1b.pdata = s1.sid, db -- (the same person, the same saved data)
s1b.weps, s1b.ammoT = { "weapon_lc_hands" }, {}
s1b:SetNW2Float("lcn_hunger", 9)
s1b:SetHealth(20)
player.GetAll = function() return { s1b, s2, s3, aw } end
hook.Run("PlayerInitialSpawn", s1b)
_run(9)
ok(s1b:GetNW2Float("lcn_hunger", 0) == 63.5 and s1b:Health() == hp0, "they left mid-dream: the next time they join, survival and health come back from the disk", tostring(s1b:GetNW2Float("lcn_hunger", 0)) .. " " .. s1b:Health())
ok(s1b:HasWeapon("weapon_pistol") and s1b.clips.weapon_pistol == 12 and s1b.ammoT[3] == 40, "and their weapons and ammunition")
ok(LC.Inventory(s1b).bread == 3 and LC.Credits(s1b) == credits0, "and their pockets and credits")
ok(s1b:GetPos():Distance(CITY) < 1, "and they're back in their bed")
ok(_files[LC.DreamFileOf(sid)] == nil, "(then the snapshot goes)")
-- nobody wakes themselves from a dream until they're out of it, not even a Happy one; an admin can still wake them
local h3 = s3:Health()
s3:SetHealth(1)
LC.SlashCommands.dream(s3, "off")
ok(LC.DreamWakeAsked(s3) == false and s3.lcDreaming, "nobody wakes themselves from a dream until they're out of it (a Happy one too)")
LC.DreamWakeOne(s3, "admin")
_run(3)
ok(not s3.lcDreaming and s3:Health() == h3, "an admin can still wake them, with everything back")
ok(LC.EndingAny() == nil, "the last dreamer gone, the dream's over")
-- an old snapshot, already put back once, isn't put back by itself again; an admin can
local snap = LC.DreamSnapshot(s3)
snap.applied = os.time()
LC.DreamSave(snap)
s3:SetHealth(2)
hook.Run("PlayerInitialSpawn", s3)
_run(7)
ok(s3:Health() == 2, "an old snapshot already put back once isn't put back again by itself (newer things aren't undone)")
ok(LC.DreamForceRestore(s3) and true, "an admin can put it back anyway (lc_dream_restore, C > Help > Dreams)")
_run(4)
ok(s3:Health() == snap.hp and _files[LC.DreamFileOf(s3:SteamID64())] == nil, "and it's put back")
-- and with the dream point gone, as always again
s2:SetNW2Float("lc_wired_until", 0)
LC.RemovePoint(dp)
concommand.list.lc_ending_reset_cooldown(nil, "lc_ending_reset_cooldown", {})
ok(LC.TriggerEnding("hard", s1b) and LC.EndingSession() ~= nil, "the dream point taken away: the endings are the whole city's again")
LC.CancelEnding()
concommand.list.lc_ending_reset_cooldown(nil, "lc_ending_reset_cooldown", {})
for _, p in ipairs({ s1b, s2, s3, aw }) do
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-120000, -120000, 0))
end
player.GetAll = realGetAll
LC.EndingReload = realReload
_setcvar("lc_needs", 1)
LCF.XP.duty_per_minute, LC.RestTick = dutyXPWas, restTickWas
_setcvar("lc_dream_delay", 60)
_setcvar("lc_dream_combine", 6)
_files["livingcity/endings.json"] = nil
_walls = savedWalls
do -- (the owner, 7 November: the flood's water in a dream, but only in the dream zone)
    local mins, maxs = LC.FloodDreamBounds({ pos = Vector(5000, 6000, 100) })
    local r = GetConVar("lc_dream_radius"):GetFloat()
    ok(mins.x == 5000 - r and maxs.y == 6000 + r and GetGlobal2Vector("lc_flood_max") == maxs, "a flood in a dream fills the circle round the dream point (its square), not the whole view")
    local bx = { pos = Vector(0, 0, 0), zone = { box = { mins = Vector(-300, -200, 0), maxs = Vector(400, 500, 900) } } }
    local m2, x2 = LC.FloodDreamBounds(bx)
    ok(m2.x == -300 and x2.y == 500, "and with a dream zone box, exactly the box")
    SetGlobal2Vector("lc_flood_min", Vector(0, 0, 0)) SetGlobal2Vector("lc_flood_max", Vector(0, 0, 0))
end
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
DreamTests()

----------------------------------------------------------------------
-- The dreams after the owner's playtest of 12 November: the sound guard, a unit dreaming in the Combine zone, the
-- dream's own weapons, a folder of music for each dream, staff stopping a dream from inside it, and the dreams changed
-- (The Battle Line, Careless Talk, Duck and Cover, Freeze, Citizen, Bubbles)
function DreamFixTests()
section("Shared dreams: the playtest fixes of 12 November (sound guard, units dreaming, dream weapons, music, stopping, battle line, careless talk, duck and cover, freeze, bubbles)")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(172000, -172000, 0), Vector(232000, -232000, 0)
local adm = newPlayer("FXAdmin", "admin")
local a = newPlayer("FXA", "citizen")
local b = newPlayer("FXB", "citizen")
local cop = newPlayer("FXCop", "cp")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("x%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Up(p) if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
local function Has(list, p) for _, q in ipairs(list) do if q == p then return true end end return false end
local function Both() Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0)) end
local function Start(id)
    Both()
    local okS, d = LC.DreamStart(id, adm, false, nil, true)
    local g = okS and d.game
    _run(0.1)
    if g then g.pl[a].safe, g.pl[b].safe = 0, 0 end
    return g, d
end
local function Stop(d) LC.DreamGameStop(d, "test") _run(4) end -- (everything put back in full before the next)
local function SentTo(p, name, test)
    for _, m in ipairs(net.sent) do
        local t = m.data[1]
        if m.name == name and (m.to == p or (type(m.to) == "table" and table.HasValue(m.to, p))) and type(t) == "table" and (not test or test(t)) then return t end
    end
    return nil
end
player.GetAll = function() return { adm, a, b, cop } end
local dp = LC.AddPoint(DREAM, 0, "dream")

-- the sound guard (the owner: "stops sounds that have played more than like 4 times in a row for no reason")
LC.SoundGuardReset()
local thing, other = ents.Create("prop_dynamic"), ents.Create("prop_dynamic")
local started = 0
for i = 1, 6 do if LC.SoundGuardCheck(thing, "livingcity/dreams/loop.mp3", 100 + i) then started = started + 1 end end
ok(started == LC.SoundGuardMax and LC.SoundGuardMax == 4, "the same sound on the same thing: four starts, then refused", started)
local last = LC.SoundGuardStopped[#LC.SoundGuardStopped]
ok(last and last.snd == "livingcity/dreams/loop.mp3" and #LC.SoundGuardReport() >= 1, "and the refusal is listed for the debug report")
ok(LC.SoundGuardCheck(thing, "livingcity/dreams/loop.mp3", 107 + LC.SoundGuardWindow), "twenty seconds on, it may play again")
ok(LC.SoundGuardCheck(other, "livingcity/dreams/loop.mp3", 107), "the same sound on something else is counted on its own")
local shots = 0
for i = 1, 10 do if LC.SoundGuardCheck(thing, "weapons/ar2/fire1.wav", 200 + i * 0.1) then shots = shots + 1 end end
ok(shots == 10 and not LC.SoundGuarded("player/footsteps/concrete1.wav") and LC.SoundGuarded("ambient/alarms/alarm1.wav")
    and LC.SoundGuarded("npc/vort/attack_charge.wav") and LC.SoundGuarded("Weapon_AR2.Single", true) and not LC.SoundGuarded("Weapon_AR2.Single"),
    "gunfire, footsteps and the like are never refused; alarms, loops and the city's own sounds always count")
ok(LC.SoundGuardClean(")livingcity\\Dreams\\X.MP3") == "livingcity/dreams/x.mp3", "a path's markers and capitals don't fool it")
LC.SoundGuardReset()

-- a Civil Protection unit asleep in the Combine zone dreams the nightmare (the owner: "I want to dream")
local realCZ = LC.CombineZoneAt
LC.CombineZoneAt = function(pos) return (pos.y < -171000 and pos.y > -173000) or nil end
Asleep(cop, CITY) Asleep(a, CITY + Vector(0, 300, 0))
local night = LC.DreamSleepers("nightmare", "maze")
ok(Has(night, cop) and not Has(night, a), "asleep in the Combine zone: the unit dreams the nightmare, a citizen there is still spared")
ok(LC.DreamOnlyEnforcers({ cop }, "maze") and not LC.DreamOnlyEnforcers({ cop, a }, "maze") and not LC.DreamOnlyEnforcers({ cop }, "cheese"),
    "only Enforcers asleep for a dream nobody can opt out of: they'll dream it like anyone")
LC.CombineZoneAt = realCZ
Up(cop) Up(a)

-- the dream's own weapons get through (they were taken away the moment they were given: "I have no guns as a CP unit")
local pick = hook.t.PlayerCanPickupWeapon.LivingCityDreams
local rifle = { IsValid = function() return true end, GetClass = function() return "weapon_ar2" end }
a.lcDreaming = 999
local blocked = pick(a, rifle) == false
LC.DreamGive(a, "weapon_ar2")
ok(blocked and pick(a, rifle) == nil and a.lcDreamGrant.weapon_ar2, "in a dream: a weapon is refused, unless the dream itself hands it over")
a.lcDreaming, a.lcDreamGrant = nil, nil

-- music: a folder for each dream, and Half-Life 2's own when there's none
_files["sound/livingcity/dreams/freeze/creepy.ogg"] = "x"
ok(table.HasValue(LC.PropagandaSongs("freeze"), "livingcity/dreams/freeze/creepy.ogg") and LC.DreamSongFor("freeze") == "livingcity/dreams/freeze/creepy.ogg",
    "a dream's own folder: sound/livingcity/dreams/freeze/", tostring(LC.DreamSongFor("freeze")))
_files["sound/livingcity/dreams/freeze/creepy.ogg"] = nil
local listed
for _, r in ipairs(LC.DreamMusicList()) do if r.id == "harvest" then listed = r end end
ok(LC.DreamSongFor("freeze") == LC.StrangeFallbackSongs.freeze and LC.DreamSongFor("harvest") ~= nil and listed and listed.own == 0 and listed.fallback,
    "without one, Half-Life 2's own: every dream has music, and the debug report lists them")

-- staff stop the dream from inside it; every sound it started is stopped
net.sent = {}
local g, d = Start("maze")
ok(g ~= nil and a.lcDreaming, "a dream under way")
LC.SoundGuardTrack(a, "ambient/alarms/alarm1.wav")
ok(LC.SoundGuardHeard[d.id] and #LC.SoundGuardHeard[d.id].list == 1, "a sound started on a dreamer is remembered")
local okStop = LC.DreamStopAll(adm)
_run(3)
ok(okStop and LC.DreamActive == nil and not a.lcDreaming and not b.lcDreaming, "stopped for everyone (F1 > Staff, or F1 in the dream)")
ok(SentTo(a, "lc_soundguard", function(t) return t.k == "dreamend" and t.list[1] and t.list[1][2] == "ambient/alarms/alarm1.wav" end),
    "and every sound it started is stopped on the dreamers' computers too")
ok(select(1, LC.DreamStopAll(adm)) == false, "nothing to stop: says so")
Up(a) Up(b)

-- Duck and Cover: at a pace that can be read, and the alarm only while the siren lasts
g, d = Start("duck")
ok(g and math.abs(g.at - CurTime() - LC.DuckFirst) < 1, "the first siren once the hello has been read", g and (g.at - CurTime()))
g.at = CurTime()
_run(0.2)
ok(g.phase == "siren" and g.alarmOn and g.sirenLen >= LC.DuckSiren[2], "the siren: the alarm on, long enough to find a table")
g.at = CurTime()
_run(0.2)
ok(g.phase == "calm" and not g.alarmOn and g.at - CurTime() >= LC.DuckCalm[1] - 1, "after it: the alarm stopped, and a long calm", g.at - CurTime())
Stop(d)

-- Careless Talk: three rounds, each with its own tell (the owner: "the NPCs I saw were all just statues")
g, d = Start("spy")
g.at = CurTime()
_run(0.2)
ok(g.phase == "pick" and g.round == 1 and g.kind == "chat" and LC.SpyRounds == 3 and g.def.need == 2, "three rounds; the first, the canteen")
local stS = g.def.state(g, a)
ok(stS.signs and #stS.signs == 4 and string.find(stS.signs[1][4], "^Table ") and string.find(LC.DreamGames.spy.goal, "Press E", 1, true),
    "a sign over every table, and the goal says to press E on the one you suspect")
g.talkAt = CurTime()
_run(0.2)
ok((g.talks or 0) >= 1 and #(LC.SpySmallTalk or {}) >= 10, "they chat at the tables (the city's small talk)", g.talks)
g.glanceAt = CurTime()
_run(0.2)
local spy = g.spyN
local still = true
for _, n in ipairs(g.npcs) do if n ~= spy and n.e:GetAngles().y ~= n.yaw then still = false end end
ok((g.glances or 0) >= 1 and spy.head ~= 0 and spy.e:GetAngles().y ~= spy.yaw and still, "the spy looks over their shoulder; nobody else does")
_run(LC.SpyGlanceSecs + 0.3)
ok(spy.e:GetAngles().y == spy.yaw and spy.head == 0, "and turns back, to look again a few seconds later")
ok(string.find(LC.SpyDescribe(spy), ", at the table ", 1, true), "described in plain words", LC.SpyDescribe(spy))
-- the salute
g.at = CurTime() _run(0.1) g.at = CurTime() _run(0.1)
ok(g.round == 2 and g.kind == "salute", "round two: the salute", g.kind)
spy = g.spyN
g.chantAt = CurTime()
_run(0.1)
local allUp = true
for _, n in ipairs(g.npcs) do if n ~= spy and n.salute ~= 1 then allUp = false end end
ok(allUp and (spy.salute or 0) < 0.5, "everyone salutes and cheers at once; the spy hardly raises a hand")
_run(LC.SpyChantLate + 0.2)
ok(spy.salute and spy.salute > 0 and spy.salute < 1, "then a limp salute, a beat late", spy.salute)
-- the firing squad
g.at = CurTime() _run(0.1) g.at = CurTime() _run(0.1)
ok(g.round == 3 and g.kind == "squad" and g.npcs[1].line == 1 and IsValid(g.npcs[1].rifle), "round three: the firing squad, in a line with rifles", g.kind)
ok(not g.def.state(g, a).signs and string.find(LC.SpyDescribe(g.spyN), "in the line", 1, true), "(no table signs now; described by their place in the line)")
spy = g.spyN
g.roundT0 = CurTime() - LC.SpyVolleyAt[1]
_run(0.1)
local firedAll = true
for _, n in ipairs(g.npcs) do if n ~= spy and not (g.fired and g.fired[n]) then firedAll = false end end
ok(g.volley == 1 and firedAll and not g.fired[spy] and table.HasValue(g.said or {}, "spy_fire"), "\"Fire!\": every rifle fires but the spy's")
-- E on the one you suspect
local si
for i, n in ipairs(g.npcs) do if n == spy then si = i end end
a:SetPos(spy.pos - Vector(120, 0, 64))
a.aim = Vector(1, 0, 0)
a.keys = { [IN_USE] = true }
_run(0.2)
a.keys = nil
ok(g.pl[a].pick == si, "E on the one you suspect: your pick", g.pl[a].pick)
Stop(d)

-- Bubbles: bigger, more, slower, and the dreamers light
ok(LC.BubbleGravity == 0.4 and LC.BubbleCount >= 45 and LC.BubbleRise <= 25 and LC.BubbleReach >= 70, "more bubbles, slower, easier to touch; the dreamers at 40% of their weight")
g, d = Start("bubbles")
ok(g and #g.bubbles == LC.BubbleCount and (a:GetGravity() == LC.BubbleGravity or g.pl[a].liftUntil), "in the dream, light as said", a:GetGravity())
for _, bb in ipairs(g.bubbles) do bb.x = bb.x + 90000 end -- (none to touch just now)
g.pl[a].liftUntil = nil
a:SetGravity(1)
_run(0.2)
ok(a:GetGravity() == LC.BubbleGravity, "and kept light, whatever else touched it")
Stop(d)

-- Freeze, Citizen: the lights go out, the dead follow, and his eyes burn red
local lamp, cityLamp = ents.Create("light_spot"), ents.Create("light_spot")
lamp:SetPos(DREAM + Vector(100, 0, 200))
cityLamp:SetPos(CITY + Vector(0, 0, 200))
g, d = Start("freeze")
ok(g and table.HasValue(lamp.fired or {}, "TurnOff") and not table.HasValue(cityLamp.fired or {}, "TurnOff") and g.def.state(g, a).dark,
    "the dream zone's lights go out (the city's stay on), and the dreamers' screens go dark")
g.t0 = CurTime() - LC.FreezeZombieAfter - 1
_run(0.3)
ok(g.zombies and #g.zombies >= 2, "the dead come shuffling after them", g.zombies and #g.zombies)
local livesA = g.pl[a].lives
a:SetPos(g.starts[1] + Vector(200, 0, 0))
for _, z in ipairs(g.zombies) do if IsValid(z.e) then z.e:SetPos(Vector(g.zx - 2000, z.e:GetPos().y, g.top)) end end
g.phase, g.phaseAt, g.redFrom, g.pl[a].safe = "red", CurTime() + 10, 0, 0
a.GetVelocity = function() return Vector(200, 0, 0) end
_run(0.1)
a.GetVelocity = nil
local stF = g.def.state(g, a)
ok(g.pl[a].lives == livesA - 1 and stF.lasers and stF.lasers[1] and stF.cop, "caught moving: red beams from his eyes, and a life gone")
Stop(d)
ok(table.HasValue(lamp.fired or {}, "TurnOn"), "awake: the lights back on")
lamp:Remove() cityLamp:Remove()

-- the vortigaunts: from their appearing to the tug-of-war, LC.VortWarLead seconds (the owner: "can the delay be like 8 seconds?")
LC.VortWarForceNext = true
g, d = Start("harvest")
g.vw.at = CurTime()
_run(0.3)
local vwG = g.vw
local stV = g.def.state(g, a)
ok(LC.VortWarLead == 8 and vwG.phase == "gather" and math.abs(vwG.tugAt - CurTime() - LC.VortWarLead) < 1 and stV.vw == false and string.find(stV.big or "", "seconds", 1, true),
    "they appear, and the tug-of-war begins eight seconds later (counted down on screen)", tostring(vwG.phase))
vwG.tugAt = CurTime()
_run(0.3)
ok(vwG.phase == "tug" and type(g.def.state(g, a).vw) == "table", "then the meter, and the tug-of-war")
Stop(d)

-- The Battle Line: the whole dream zone, a usual run, rifles in the soldiers' hands, the city's NPCs sent off the field
local bz = LC.AddZone(nil, nil, "dream", 0, { mins = DREAM - Vector(3000, 2000, 100), maxs = DREAM + Vector(3000, 2000, 2000) })
net.sent = {}
g, d = Start("battleline")
ok(g and g.wide and g.x1 - g.x0 > 5000 and g.bounds.maxs.x > DREAM.x + 2900, "the field is the whole dream zone", g and (g.x1 - g.x0))
local held = 0
for _, e in ipairs(g.ents) do if IsValid(e) and e:GetModel() == "models/weapons/w_irifle.mdl" and e:GetParent() ~= nil then held = held + 1 end end
ok(held == #g.soldiers and #g.soldiers == 6, "every soldier has a rifle in their hands", held)
local r1 = LC.BattleLineNewRebel(g, nil)
ok(r1.speed >= LC.BattleLineRun.rebel * 0.85 and r1.speed <= LC.BattleLineRun.rebel * 1.15, "the rebels run at a usual pace", r1.speed)
ok(LC.BattleLineAdvance(g) == 1, "no giants yet: nothing holding her air back")
local big = LC.BattleLineNewRebel(g, "doom", nil, 3)
ok(LC.BattleLineAdvance(g) < 0.1, "a giant just come: hardly started", LC.BattleLineAdvance(g))
big.e:SetPos(Vector((big.x0 + g.lineX) / 2, big.y, g.top))
ok(math.abs(LC.BattleLineAdvance(g) - 0.5) < 0.05, "half way across", LC.BattleLineAdvance(g))
local walker = ents.Create("npc_citizen")
walker:SetPos(Vector(g.lineX + 400, (g.y0 + g.y1) / 2 + 100, g.top))
d.made[walker] = nil -- (a city NPC that wandered in, not one the dream made)
local findWas = ents.FindInBox
ents.FindInBox = function() return { walker } end
LC.BattleLineClearField(g)
ents.FindInBox = findWas
ok(walker.sched == (SCHED_FORCED_GO_RUN or 71) and walker.goal and (walker.goal.y > g.y1 or walker.goal.y < g.y0), "a city NPC on the field is sent off it")
local dmg = { n = 30 }
function dmg:GetAttacker() return a end
function dmg:SetDamage(v) self.n = v end
hook.t.EntityTakeDamage.LivingCityBattleLine(walker, dmg)
ok(dmg.n == 0, "and the dream's rifle never hurts anything in the waking world")
LC.BattleLineTracer(Vector(0, 0, 0), Vector(100, 0, 0))
ok(SentTo(a, "lc_dreamgame", function(t) return t.k == "tracer" end), "shots' streaks are drawn on the dreamers' screens (gone with the dream), not left in the world")
walker:Remove()
Stop(d)
LC.RemoveZone(bz)
LC.VortWeakNext, LC.VortWarForceNext = nil, nil -- (nothing of tonight's vortigaunts carried into the next unit's dreams)

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b, cop }) do
    Up(p)
    p:SetPos(Vector(-122000, -122000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
DreamFixTests()

----------------------------------------------------------------------
-- Shared dreams, the Administrator's choice (sv_livingcity_dreams.lua): moods, the tablet, and watching once you're out
function DreamMoodTests()
section("Shared dreams: Happy, Neutral or Nightmare, chosen on the Administrator's tablet")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0) -- (the older tests: the Administrator picks freely, and the city doesn't pick: DreamCrowdTests has the rules)
local errs0 = #_errors
local savedWalls, realGetAll, realReload, realPhase, realNotice = _walls, player.GetAll, LC.EndingReload, LC.DayPhase, LC.Notice
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
_setcvar("lc_dream_delay", 10)
_setcvar("lc_dream_combine", 2)
LC.EndingReload = function() end
_files["livingcity/endings.json"] = nil
local phase = "dusk"
LC.DayPhase = function() return phase end
LC.AtmosPhase = phase -- (the city's clock sees the same: no second night or dawn from it)
local told = {}
LC.Notice = function(p, kind, title, text, secs) told[#told + 1] = { p = p, title = title, text = text } return realNotice(p, kind, title, text, secs) end
local function ToldTo(p, needle) for _, n in ipairs(told) do if n.p == p and string.find(n.text or "", needle, 1, true) then return true end end return false end

-- the moods (lc_dream_moods)
local m = LC.DreamMoods()
ok(m.bus == "happy" and m.plane == "happy" and m.hard == "happy" and m.shalom == "happy" and m.bloom == "neutral" and m.fire == "neutral" and m.base == "neutral"
    and m.harpies == "nightmare" and m.marrow == "nightmare" and m.water == "nightmare" and m.standup == "nightmare", "every ending has a mood: happy, neutral or nightmare")
local m2 = LC.DreamMoods("bus=Nightmare, plane = happy, fire=gloomy")
ok(m2.bus == "nightmare" and m2.plane == "happy" and m2.fire == "neutral" and m2.hard == "neutral", "the setting is read as id=mood (any case); unknown or unlisted is neutral")

local CITY, DREAM = Vector(170000, -170000, 0), Vector(200000, -200000, 0)
local adm = newPlayer("DMAdmin", "admin")
local cit = newPlayer("DMCit", "citizen")
local cit2 = newPlayer("DMCit2", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
player.GetAll = function() return { adm, cit, cit2 } end

-- no dream point: the tablet says why
local off = LC.DreamOffice()
ok(not off.ready and off.why ~= nil and not LC.DreamAdminPick(adm, "bus"), "with no dream point the tablet says the city can't dream, and nothing can be picked")
local dp = LC.AddPoint(DREAM, 0, "dream")
off = LC.DreamOffice()
local happy = off.groups[1]
local hasBus = false
for _, e in ipairs(happy.endings) do if e.id == "bus" and e.name == LC.Endings.bus.name then hasBus = true end end
ok(off.ready and #off.groups == 3 and happy.mood == "happy" and off.groups[3].mood == "nightmare" and hasBus,
    "the tablet lists the endings under Happy, Neutral and Nightmare, by their titles")

-- only the Administrator
ok(not LC.DreamAdminPick(cit, "harpies") and LC.AdminDo(cit, "dream", "harpies") == false and LC.DreamQueued() == nil, "only the Administrator can choose")
-- (the owner, 9 November: she chooses only a kind, Nightmare or propaganda; the city decides which: sv_livingcity_dreamplan.lua)
LC.DreamPlan.adminNight, LC.DreamPlan.specialNight = -100, -100
ok(LC.AdminDo(adm, "dream", "bus") == false and LC.AdminDo(adm, "dream", "none") == false, "the Administrator can't choose which dream, or none")
ok(LC.AdminDo(adm, "dream", "nightmare") and LC.DreamQueued().cat == "nightmare" and LC.DreamKind(LC.DreamQueued().id) == "nightmare" and LC.DreamOffice().waiting.yours,
    "she chooses a Nightmare on the tablet: the next one waits for tonight")
ok(LC.AdminDo(adm, "dream", "cancel") and LC.DreamQueued() == nil, "and can take it back before the night")

-- the G-Man has no part in dreams (the owner, 7 November): an ending set off in play leaves tonight's dream alone
LC.DreamAdminPick(adm, "bus")
ok(LC.TriggerEnding("shalom", cit) and LC.EndingSession() ~= nil and LC.DreamQueued().id == "bus",
    "an ending set off in play is the whole city's; the Administrator's dream still waits for tonight")
LC.CancelEnding()
ok(LC_SettingInfo and LC_SettingInfo.lc_directives and LC_SettingInfo.lc_directives.d == "0", "the G-Man's sealed directives, sleep visits and talks are off by default (set aside for a future endings setup)")
LC.DreamForget()

-- the cooldown doesn't stop the Administrator's (there's still one a night)
local t0 = os.time() - 60
_files["livingcity/endings.json"] = util.TableToJSON({ last = t0 })
ok(LC.EndingCooldownLeft() > 0 and not LC.TriggerEnding("bus", cit), "(the endings' cooldown is running: an ending can't be set off)")
ok(LC.DreamAdminPick(adm, "harpies"), "the Administrator's pick doesn't wait for the cooldown")
Asleep(cit, CITY)
Asleep(cit2, CITY + Vector(0, 200, 0))
phase = "night"
LC.AtmosPhase = phase
hook.Run("LivingCityDayPhase", "night", "dusk")
_run(6)
ok(ToldTo(cit, LC.DreamMoodLines.nightmare) and ToldTo(cit2, LC.DreamMoodLines.nightmare), "the sleepers feel it coming: an uneasy line for a nightmare")
_run(10)
local E = LC.EndingAny()
ok(E and E.dream and E.id == "harpies" and E.dream.force and E.dream.mood == "nightmare", "that night everyone asleep dreams the Administrator's pick, cooldown or not", E and E.id)
ok(cit.lcDreaming and cit2.lcDreaming and not adm.lcDreaming, "(the sleepers, not the awake Administrator)")
do
    local inside = true
    for _, t in ipairs(E.forest or {}) do if not LC.DreamHolds(E.dream, t:GetPos()) then inside = false end end
    ok(#(E.forest or {}) >= 20 and inside, "the harpies dreamt: a forest stands round the dream zone, inside its edge", #(E.forest or {}))
    ok(#(E.cover or {}) >= 6, "with rocks, logs and bushes nearer in for them to hide behind", #(E.cover or {}))
    local g = LC.MingeCover(E.lz)
    ok(g and (g - E.lz):Length2D() > 100, "a lurking mingebag can pick the far side of one")
end
local cd = util.JSONToTable(_files["livingcity/endings.json"] or "{}") or {}
ok(tonumber(cd.last) == t0, "and it doesn't start the endings' cooldown over (the G-Man's aren't held back by it)")

-- out of it in a dream: watching the rest, only the other dreamers, inside its edge
local dream = E.dream
LC.EndingTake(cit, "Gone.")
ok(cit.lcEndSpectating and cit.lcEndWatching == cit2, "taken out (drowned, killed, taken) in a dream: they watch the rest, the other dreamers only")
LC.EndingTake(cit2, "Gone too.")
ok(cit2.lcEndSpectating and cit2.lcEndWatching ~= adm, "(never the awake)")
local origin = DREAM + Vector(9000, 0, 6000)
local mv = { GetOrigin = function(self) return self.o end, SetOrigin = function(self, v) self.o = v end, SetVelocity = function() end, o = origin }
do local gmWas = GAMEMODE GAMEMODE = nil -- (the file's stand-in gamemode has no movement settings: the full run's, not this unit's)
hook.Run("SetupMove", cit, mv)
GAMEMODE = gmWas end
ok(LC.DreamHolds(dream, mv.o, true) and mv.o.z <= DREAM.z + 2000, "flying free while watching, they can't leave the dream's edge (or fly above it)")
ok(LC.DreamClamp(dream, DREAM + Vector(100, 0, 50)) == nil, "(inside it, they fly where they like)")
local mvAwake = { GetOrigin = function(self) return self.o end, SetOrigin = function(self, v) self.o = v end, SetVelocity = function() end, o = origin }
do local gmWas = GAMEMODE GAMEMODE = nil
hook.Run("SetupMove", adm, mvAwake)
GAMEMODE = gmWas end
ok(mvAwake.o == origin, "(the awake fly as ever)")
LC.CancelEnding()
_run(4)
ok(not cit.lcDreaming and not cit.lcEndSpectating and cit.lcSleep and cit:GetPos():Distance(CITY) < 1, "when it ends they wake in their beds like everyone else")

-- one dream a night: a new pick waits for tomorrow
ok(LC.DreamAdminPick(adm, "bus") and LC.DreamOffice().dreamt, "one dream a night: a pick now waits for tomorrow night")
_run(15)
ok(LC.EndingAny() == nil, "(no second dream tonight)")
-- the morning after
phase = "dawn"
LC.AtmosPhase = phase
hook.Run("LivingCityDayPhase", "dawn", "night")
ok(has(cit.chat, "slept badly"), "the next morning the city hears how it slept (by the dream's mood)")
LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, cit, cit2 }) do
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-120000, -120000, 0))
end
player.GetAll, LC.EndingReload, LC.DayPhase, LC.Notice = realGetAll, realReload, realPhase, realNotice
LC.AtmosPhase = realPhase and realPhase() or LC.AtmosPhase
_setcvar("lc_needs", 1)
_setcvar("lc_dream_delay", 60)
_setcvar("lc_dream_combine", 6)
_files["livingcity/endings.json"] = nil
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
DreamMoodTests()

-- Nightmare dreams you play (sv_livingcity_dreamgames.lua): the maze, the barrel tower, the crumbling floor, freeze
function DreamGameTests()
section("Shared dreams: the nightmare dreams you play (maze, barrel tower, crumbling floor, freeze)")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0) -- (the older tests: the Administrator picks freely, and the city doesn't pick: DreamCrowdTests has the rules)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
_files["livingcity/endings.json"] = nil
local CITY, DREAM = Vector(150000, -150000, 0), Vector(210000, -210000, 0)
local adm = newPlayer("DGAdmin", "admin")
local a = newPlayer("DGA", "citizen")
local b = newPlayer("DGB", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
player.GetAll = function() return { adm, a, b } end
local dp = LC.AddPoint(DREAM, 0, "dream")

-- on the tablet, under Nightmare
local off = LC.DreamOffice()
local found = {}
for _, e in ipairs(off.groups[3].endings) do if e.game then found[e.id] = e.name end end
ok(found.maze == "The Patrol Maze" and found.barrels == "The Barrel Tower" and found.crumble == "The Crumbling Floor" and found.freeze == "Freeze, Citizen",
    "the four dreams you play are on the Administrator's tablet, under Nightmare")
ok(LC.DreamMood("maze") == "nightmare" and LC.DreamMoods("maze=happy").maze == "happy", "they're Nightmares unless lc_dream_moods says otherwise")
ok(LC.DreamAdminPick(adm, "maze") and LC.DreamQueued().id == "maze" and LC.DreamOffice().waiting.name == "The Patrol Maze", "the Administrator can choose one for tonight")
LC.DreamForget()
local status = LC.DreamStatus()
local inList = false
for _, e in ipairs(status.endings) do if e.id == "freeze" then inList = true end end
ok(inList, "(and an admin can dream one now from C > Help > Dreams)")

-- a maze: every cell can be reached
local open = LC.DreamMaze(7, 6, 5)
local seen, q = { ["1_1"] = true }, { "1_1" }
while #q > 0 do local c = table.remove(q) for n in pairs(open[c]) do if not seen[n] then seen[n] = true q[#q + 1] = n end end end
ok(table.Count(seen) == 42, "the maze's every corridor can be reached (and there's more than one way round)", table.Count(seen))

-- The Patrol Maze
-- (the minute's duty time waits until the maze is over: if it fell inside, the dream would rightly put
-- back what they had on falling asleep, and that would look like the dream taking experience away)
local dutyT = timer.list["LivingCityFactionsDuty"]
local dutyNext = dutyT and dutyT.next
if dutyT then dutyT.next = math.huge end
local goodA = { hp = a:Health(), pos = CITY }
Asleep(a, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
local okM, dream = LC.DreamStart("maze", adm, false, nil, true)
local g = okM and dream.game
ok(okM and g and g.id == "maze" and #g.ents > 30 and #g.cops >= 2 and g.left > 40, "the maze is built at the dream point: floor, walls, tokens, giant officers", okM and #(g and g.ents or {}) or dream)
ok(a.lcDreaming and b.lcDreaming and a:GetPos():Distance(DREAM) < 1200 and LC.EndingAny() == nil, "everyone asleep is in it (no ending, nothing else stops)")
ok(LC.DreamStart("crumble", adm, false, nil, true) == false, "(one dream at a time)")
ok(a:GetNW2Float("lc_dream_ends", 0) > CurTime() and not a:GetNW2Bool("lc_dream_canwake", false), "their screen knows when it ends at the latest, and that they can't wake yet")
local livedA, livedB = LC.DreamsLivedOfKind(a, "nightmare"), LC.DreamsLivedOfKind(b, "nightmare")
_run(0.2) -- (whatever's under them at the start, picked up)
local t1 = g.tokens[1]
for _, t in ipairs(g.tokens) do if not t.big and not t.got and t.pos:Distance(a:GetPos()) > 150 and t.pos:Distance(b:GetPos()) > 150 then t1 = t break end end
local left0 = g.left
a:SetPos(t1.pos - Vector(0, 0, 36))
_run(0.2)
ok(t1.got and g.left == left0 - 1, "walking over a token picks it up")
_run(4) -- (the start's safety has passed; the officers are out)
local c1 = g.cops[1]
c1.home = 0
local s = g.pl[a]
a:SetPos(c1.e:GetPos())
_run(0.2)
ok(s.lives == 2 and a:GetPos():Distance(s.start) < 1, "a giant officer catches you: a life gone, back to the start", s.lives)
-- a golden token: they're afraid, and you send one back to the middle
local big
for _, t in ipairs(g.tokens) do if t.big and not t.got then big = t break end end
s.safe = 0
b:SetPos(big.pos - Vector(0, 0, 36))
_run(0.2)
ok(big.got and g.afraid and g.afraid > CurTime(), "a golden token frightens the officers")
local c2 = g.cops[2] or c1
c2.home = 0
b:SetPos(c2.e:GetPos())
_run(0.2)
ok((c2.home or 0) > CurTime() and g.pl[b].lives == 3, "and touching one then sends him back to the middle")
g.afraid = 0
-- a nightmare: nobody wakes themselves while they're still in it
ok(not LC.DreamWakeAsked(b) and b.lcDreaming and not LC.DreamCanWake(b), "in a nightmare you can't wake yourself while you're still in it")
-- out of lives: out of it, watching (or wake now); waking, shaken
s.safe, s.lives = 0, 1
local hpA = a:Health()
LC.DreamGameHit(g, a, "Caught", "Test.")
ok(g.pl[a].how == "out" and a.lcGameWatching and a.lcDreaming and LC.DreamCanWake(a), "no lives left: out of it, watching the rest, free to wake")
local sentOut = false
for _, m in ipairs(net.sent) do if m.name == "lc_dreamgame" and m.to == a and type(m.data[1]) == "table" and m.data[1].k == "out" then sentOut = true end end
ok(sentOut, "(their screen asks: wake up now, or watch until it's over)")
_run(1.2)
ok(a:GetNW2Bool("lc_dream_canwake", false) and not b:GetNW2Bool("lc_dream_canwake", false), "out of it: their screen says they can wake now (F1 offers it); not the one still in it")
ok(LC.DreamWakeAsked(a), "they choose to wake")
_run(2.5)
ok(not a.lcDreaming and not a.lcGameWatching and a.lcSleep and a:GetPos():Distance(CITY) < 1, "awake in their bed, everything as it was")
ok(not a:GetNW2Bool("lc_dream_canwake", false) and a:GetNW2Float("lc_dream_ends", 0) == 0, "(and their screen's dream lines are gone)")
ok(LC.DreamScarred(a) and a:GetMaxHealth() == 70 and a:Health() <= 70 and LC.Shaken(a), "and lost: 30 off their health until their next full night's sleep", a:GetMaxHealth())
LC.SetDreamScar(a, false)
-- every token gone: the rest win, and the arena goes
local crB = b:GetNW2Int("lce_credits", 0)
local xpB = b:GetNW2Int("lcf_xp", 0)
local ents0 = g.ents
for _, t in ipairs(g.tokens) do t.got = true end
g.left = 0
_run(2.5)
local gone = true
for _, e in ipairs(ents0) do if IsValid(e) then gone = false end end
ok(g.pl[b].how == "won" and not b.lcDreaming and LC.DreamActive == nil and gone and #g.won == 1, "every token picked up: those left win; nobody's left in it, so it's over, everyone wakes, and the maze is gone")
ok(LC.Unbroken(b) and LC.SecondWind(b) and b:GetNW2Int("lce_credits", 0) == crB and b:GetNW2Int("lcf_xp", 0) == xpB, "a winner wakes Unbroken with a second wind, and nothing the Combine would give (no credits, no experience)", tostring(LC.Unbroken(b)) .. " " .. tostring(LC.SecondWind(b)) .. ", credits " .. crB .. " to " .. b:GetNW2Int("lce_credits", 0) .. ", experience " .. xpB .. " to " .. b:GetNW2Int("lcf_xp", 0))
ok(LC.DreamsLivedOfKind(a, "nightmare") == livedA + 1 and LC.DreamsLivedOfKind(b, "nightmare") == livedB + 1,
    "both lived through a nightmare, counted for sitting out: the one who woke early, and the one in it to the end (the dream itself already gone)",
    LC.DreamsLivedOfKind(a, "nightmare") - livedA .. ", " .. LC.DreamsLivedOfKind(b, "nightmare") - livedB)
b:SetNW2Float("lc_unbroken_until", 0)
b:SetNW2Float("lc_secondwind_until", 0)
if dutyT then dutyT.next = math.max(dutyNext, CurTime()) end

-- The Barrel Tower
Asleep(a, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
local okB, d2 = LC.DreamStart("barrels", adm, false, nil, true)
local gb = okB and d2.game
ok(okB and gb and #gb.ents > 8 and IsValid(gb.giant), "the barrel tower is built: ramps, landings, the giant at the top")
_run(5)
local br = gb.barrels[1]
ok(br and IsValid(br.e), "the giant rolls a barrel down")
local hitAt = br and br.e:GetPos()
local sa = gb.pl[a]
a:SetPos(hitAt - Vector(0, 0, 13))
_run(0.1)
ok(sa.lives == 2 and (not IsValid(br.e)) and a:GetPos():Distance(sa.start) < 1, "touching a barrel blows it up: a life gone, back to the bottom", sa.lives)
b:SetPos(gb.topAt + Vector(0, 0, 2))
_run(0.2)
ok(gb.pl[b].how == "won", "reaching the top wins")
ok(b.lcGameWatching, "(a winner may watch the rest too)")
LC.DreamGameStop(d2, "test")
_run(2.5)
ok(not a.lcDreaming and not b.lcDreaming and LC.DreamActive == nil, "(and when it's over, everyone wakes)")
ok(LC.Unbroken(b), "(the winner is Unbroken: the next nightmare can't take them)")
b:SetNW2Float("lc_unbroken_until", 0)

-- The Crumbling Floor
Asleep(a, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
local okC, d3 = LC.DreamStart("crumble", adm, false, nil, true)
local gc = okC and d3.game
ok(okC and gc and gc.n >= 4 and table.Count(gc.tiles) == gc.n * gc.n, "the crumbling floor is built: tiles over a drop, a scanner overhead")
_run(3.2)
local tile = LC.DreamTileAt(gc, a:GetPos())
a:SetPos(Vector(a:GetPos().x, a:GetPos().y, gc.top))
_run(0.2)
ok(tile and tile.crack, "a tile you stand on cracks")
_run(1.2)
ok(tile.gone and not IsValid(tile.e), "and falls away a moment later")
a:SetPos(a:GetPos() - Vector(0, 0, 40))
_run(0.2)
ok(gc.pl[a].how == "out" and gc.pl[b].how == "won", "fall and you're out; the last one standing wins")
_run(2.5)
ok(LC.DreamActive == nil and not b.lcDreaming, "(then it's over)")
b:SetNW2Float("lc_unbroken_until", 0)
a:SetNW2Float("lc_shaken_until", 0)
LC.SetDreamScar(a, false)

-- Freeze, Citizen
Asleep(a, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
local okF, d4 = LC.DreamStart("freeze", adm, false, nil, true)
local gf = okF and d4.game
ok(okF and gf and IsValid(gf.cop) and gf.finishX > gf.startX, "the yard is built, with the giant officer at the far end")
_run(3.2)
gf.phase, gf.phaseAt, gf.redFrom = "red", CurTime() + 5, CurTime() - 1
a:SetPos(a:GetPos() + Vector(200, 0, 0))
a.vel = Vector(200, 0, 0)
_run(0.1)
a.vel = nil
ok(gf.pl[a].lives == 2 and a:GetPos():Distance(gf.pl[a].start) < 1, "moving when he's turned round: seen, back to the start")
ok(gf.pl[b].lives == 3, "(standing still is safe)")
gf.phase, gf.phaseAt = "green", CurTime() + 5
b:SetPos(Vector(gf.finishX + 5, b:GetPos().y, b:GetPos().z))
_run(0.2)
ok(gf.pl[b].how == "won", "reaching the line by him wins")
-- the admins can wake everyone
LC.DreamGameStop(d4, "admin")
_run(2.5)
ok(not a.lcDreaming and LC.DreamActive == nil, "waking everyone ends it")

-- The Midnight Rally (the owner, 10 November: a buggy race dream)
do
    for _, p in ipairs({ adm, a, b }) do if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
    for _, p in ipairs({ a, b }) do p:SetNW2Float("lc_unbroken_until", 0) p:SetNW2Float("lc_secondwind_until", 0) end
    ok(LC.DreamMood("rally") == "happy" and LC.DreamTitle("rally") == "The Midnight Rally" and LC.DreamSongFor("rally") ~= nil, "The Midnight Rally is a Happy dream, with music")
    -- the driving (sh_livingcity_kart.lua): pure arithmetic
    local vx, vy = 0, 0
    for i = 1, 200 do vx, vy = LCK.Step(vx, vy, 0, 1, 0.015, LCK.Base, false) end
    ok(math.abs(vx - LCK.Base) < 1 and math.abs(vy) < 1, "flat out in a straight line: up to the top speed, and no faster", vx)
    local wx, wy = LCK.Step(vx, vy, math.pi / 2, 1, 0.015, LCK.Base, false)
    ok(wy > 0 and wy < 60 and wx > 400, "looking hard left at speed: the buggy only comes round so fast", wx .. " " .. wy)
    local bx, by = LCK.Step(vx, vy, 0, -1, 0.1, LCK.Base, false)
    ok(bx < vx - 80 and bx >= 0, "back brakes", bx)
    for i = 1, 100 do bx, by = LCK.Step(bx, by, 0, -1, 0.015, LCK.Base, false) end
    ok(bx < 0 and math.abs(bx) <= LCK.Base * LCK.Reverse + 1, "and then reverses, slowly", bx)
    local sx = LCK.Step(vx, vy, 0, 1, 0.1, LCK.Base, true)
    local hx, hy = LCK.Step(0, 0, 0, 1, 0.1, 0, false)
    ok(sx < vx - 60 and hx == 0 and hy == 0, "spinning out there's no throttle, and held on the grid nobody moves", sx)
    local ox = vx
    for i = 1, 100 do ox = LCK.Step(ox, 0, 0, 1, 0.015, LCK.Base * 0.45, false) end
    ok(math.abs(ox - LCK.Base * 0.45) < 2, "off the road the top speed comes down to a crawl", ox)
    -- the race
    Asleep(a, CITY)
    Asleep(b, CITY + Vector(0, 200, 0))
    local okR, dr = LC.DreamStart("rally", nil, false, nil, true)
    local gr = okR and dr.game
    _run(0.3)
    local TAU = math.pi * 2
    ok(okR and gr.laps >= 3 and #gr.boxes == 6 and #gr.bots == math.max(0, LC.DreamMin() - 2) and IsValid(gr.pl[a].kart) and a:GetNW2Bool("lc_kart", false)
        and a:GetNW2Float("lc_kart_max", -1) == 0, "the road, the crates, the rival drivers; everyone in a buggy, held on the grid", okR and (gr.laps .. " laps, " .. #gr.bots .. " rivals") or tostring(dr))
    local st0 = gr.def.state(gr, a)
    ok(st0.big ~= nil and string.find(st0.meterName, "Lap 1 of " .. gr.laps, 1, true), "the countdown, and the lap, on screen", tostring(st0.big) .. " / " .. tostring(st0.meterName))
    _run(4.2)
    local function Drive(p, sec) p:SetPos(LC.RallyRoadAt(gr, (sec + 0.5) / LC.RallySectors * TAU) + Vector(0, 0, 4)) _run(0.1) end
    Drive(a, 11)
    ok(a:GetNW2Float("lc_kart_max", 0) == LCK.Base and not gr.pl[a].off, "go: on the road, the full top speed", a:GetNW2Float("lc_kart_max", 0))
    a:SetPos(gr.c + Vector(0, 0, 4))
    _run(0.1)
    ok(gr.pl[a].off and a:GetNW2Float("lc_kart_max", 0) == math.floor(LCK.Base * 0.45), "inside the cones: a crawl")
    ok(gr.pl[a].prog == 0, "(and cutting across the middle counts for nothing)", gr.pl[a].prog)
    for sec = 0, 11 do Drive(a, sec) end
    Drive(a, 0)
    ok(gr.pl[a].lap == 2 and gr.pl[a].prog == 13, "every stretch driven in order: a lap", gr.pl[a].lap .. " " .. gr.pl[a].prog)
    Drive(a, 6)
    ok(gr.pl[a].prog == 13, "jumping half the road ahead doesn't count", gr.pl[a].prog)
    Drive(a, 1)
    -- pickups
    local function Press(p) p.keys = { [IN_JUMP] = true } _run(0.1) p.keys = {} _run(0.1) end
    gr.pl[a].item = nil
    local crate = gr.boxes[4]
    for _, bx in ipairs(gr.boxes) do -- (one no rival driver is anywhere near)
        local clear = true
        for _, bot in ipairs(gr.bots) do if bot.pos and bot.pos:Distance(bx.pos) < 400 then clear = false end end
        if clear then crate = bx end
    end
    crate.back = 0
    a:SetPos(crate.pos + Vector(0, 0, 4))
    _run(0.1)
    ok(gr.pl[a].item ~= nil and crate.back > CurTime(), "driving through a crate: a pickup, and the crate is gone a while", tostring(gr.pl[a].item))
    gr.pl[a].item = "boost"
    Press(a)
    ok(gr.pl[a].item == nil and gr.pl[a].boost > CurTime() and a:GetNW2Float("lc_kart_max", 0) == math.floor(LCK.Base * 1.5), "Jump uses it: a boost", a:GetNW2Float("lc_kart_max", 0))
    gr.pl[a].item = "melon"
    -- (a rival driver may drop one of its own in the same moment: count the player's, the one nearest them)
    local had = #gr.traps
    Press(a)
    ok(#gr.traps >= had + 1 and gr.pl[a].item == nil, "a melon, dropped behind", #gr.traps - had)
    local trap
    for i = had + 1, #gr.traps do
        local t = gr.traps[i]
        if not trap or t.pos:DistToSqr(a:GetPos()) < trap.pos:DistToSqr(a:GetPos()) then trap = t end
    end
    _run(0.7)
    if trap then b:SetPos(trap.pos) end
    _run(0.1)
    ok(trap and (gr.pl[b].spin or 0) > CurTime() and b:GetNW2Float("lc_kart_spin", 0) > CurTime() and not IsValid(trap.e), "the next buggy over it spins out, and the melon's gone")
    b:SetPos(a:GetPos() + Vector(200, 0, 0))
    gr.pl[a].item = "pulse"
    Press(a)
    ok((gr.pl[b].slow or 0) > CurTime() and (gr.pl[a].slow or 0) <= CurTime(), "the horn blast slows everyone near, not the one who sounded it")
    if gr.bots[1] then
        local a0 = gr.bots[1].a
        _run(1)
        ok(gr.bots[1].a > a0 and gr.bots[1].e:GetPos():Distance(LC.RallyRoadAt(gr, gr.bots[1].a, gr.bots[1].lane)) < 5, "the rival drivers are driving, on the road")
    end
    -- the finish
    gr.pl[a].lap, gr.pl[a].sec = gr.laps, 11
    Drive(a, 0)
    ok(gr.pl[a].how == "won" and gr.pl[a].place == 1 and not a:GetNW2Bool("lc_kart", false) and not IsValid(gr.pl[a].kart), "over the line after the last lap, first: won, and out of the buggy", tostring(gr.pl[a].how))
    local st1 = gr.def.state(gr, b)
    ok(string.find(st1.meterName, "2nd of", 1, true) or string.find(st1.meterName, " of " .. (2 + #gr.bots), 1, true), "the others see where they are in the running", st1.meterName)
    LC.DreamGameStop(dr, "admin")
    _run(3)
    ok(not b:GetNW2Bool("lc_kart", false) and not b.lcDreaming and not a.lcDreaming and LC.DreamActive == nil, "the race over: everyone out of their buggies and awake")
    for _, p in ipairs({ a, b }) do p:SetNW2Float("lc_unbroken_until", 0) p:SetNW2Float("lc_secondwind_until", 0) p.keys = nil if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
end

-- The Fitness Test (the owner, 12 November: "a new dream, an airboat race or an obstacle course")
do
    for _, p in ipairs({ adm, a, b }) do if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
    for _, p in ipairs({ a, b }) do p:SetNW2Float("lc_unbroken_until", 0) p:SetNW2Float("lc_secondwind_until", 0) end
    ok(LC.DreamMood("course") == "happy" and LC.DreamTitle("course") == "The Fitness Test" and LC.DreamSongFor("course") ~= nil, "The Fitness Test is a Happy dream, with music")
    -- laid out snaking: rows joined by two bridge tiles, everything else in order
    local lay = LC.CourseLay(5)
    local kinds, bridges = {}, 0
    for _, t in ipairs(lay) do if t.kind == "bridge" then bridges = bridges + 1 else kinds[#kinds + 1] = t.kind end end
    ok(#kinds == #LC.CourseLayout and kinds[1] == "start" and kinds[#kinds] == "finish" and bridges > 0 and bridges % 2 == 0, "the course snakes in rows, joined by bridges", #kinds .. " tiles, " .. bridges .. " bridges")
    Asleep(a, CITY)
    Asleep(b, CITY + Vector(0, 200, 0))
    local okC, dc = LC.DreamStart("course", nil, false, nil, true)
    local gc = okC and dc.game
    _run(0.3)
    ok(okC and #gc.tiles >= #LC.CourseLayout and #gc.flags == 3 and #gc.sweeps >= 3 and gc.finishAt ~= nil, "built: tiles, three flags, the batons, the gold tile", okC and #gc.tiles or tostring(dc))
    if okC then
        local function Tile(kind, n)
            local seen = 0
            for i, t in ipairs(gc.tiles) do if t.kind == kind then seen = seen + 1 if seen == (n or 1) then return i, t end end end
        end
        -- a flag reached: falling after it starts you there
        local fi, ft = Tile("flag")
        a:SetPos(ft.pos + Vector(0, 0, 4))
        _run(0.2)
        ok(gc.pl[a].flag == fi, "reaching a green flag")
        a:SetPos(ft.pos - Vector(0, 0, LC.CourseFall + 50))
        _run(0.2)
        ok(a:GetPos():Distance(ft.pos + Vector(0, 0, 4)) < 2, "falling: back at the last flag")
        -- a baton sweeping by: on the floor in its way, swept; jumping, not
        local sw = gc.sweeps[1]
        local ang = math.rad(sw.ang)
        local inWay = sw.pivot + Vector(math.cos(ang) * 50, math.sin(ang) * 50, 2)
        ok(LC.CourseSwept(gc, inWay) and not LC.CourseSwept(gc, inWay + Vector(0, 0, 50)), "a baton sweeps you off your feet, unless you jump it")
        -- the gold tile: passed, in first place
        local _, fin = Tile("finish")
        a:SetPos(fin.pos + Vector(0, 0, 4))
        _run(0.2)
        ok(gc.pl[a].how == "won" and gc.passed == 1, "reaching the gold tile passes the test")
        LC.DreamGameStop(dc, "admin")
        _run(2.5)
    end
    ok(LC.DreamActive == nil, "and it ends")
    for _, p in ipairs({ a, b }) do p:SetNW2Float("lc_unbroken_until", 0) p:SetNW2Float("lc_secondwind_until", 0) p.keys = nil if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
end

-- falling asleep late (the owner, 10 November): whoever lies down after a dream has begun joins it, in every dream you play
do
    for _, p in ipairs({ adm, a, b }) do if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
    for _, p in ipairs({ a, b }) do p:SetNW2Float("lc_unbroken_until", 0) p:SetNW2Float("lc_secondwind_until", 0) end -- (b won the last one: Unbroken would spare them)
    local tried, joined, clean, failed = 0, 0, 0, {}
    for _, id in ipairs(LC.DreamGameOrder) do
        local e0 = #_errors
        Asleep(a, CITY)
        local okL, dl = LC.DreamStart(id, nil, false, nil, true)
        if okL then
            tried = tried + 1
            _run(1.5)
            Asleep(b, CITY + Vector(0, 200, 0))
            _run(1)
            local early = b.lcDreaming ~= nil -- (not in its first three seconds)
            _run(2.2)
            local gl = dl.game
            local inIt = b.lcDreaming == dl.id and gl and (gl.pl[b] ~= nil or (gl.enf and gl.enf[b] ~= nil)) and b:GetPos():Distance(CITY) > 10000
            if inIt and not early then joined = joined + 1 else failed[#failed + 1] = id .. string.format("[early=%s dreaming=%s pl=%s can=%s sleep=%s]", tostring(early), tostring(b.lcDreaming), tostring(gl and gl.pl[b] ~= nil), tostring(LC.DreamCanJoinLate(dl)), tostring(b.lcSleep ~= nil)) end
            if id == "maze" then
                ok(inIt and gl.pl[b].lives == gl.def.lives and gl.pl[b].late and b:GetNW2Bool("lc_dreaming", false), "asleep after the maze began: they're in it, with every life")
                LC.DreamWakeOne(b, "admin")
                _run(2.5)
                ok(b.lcSleep and not b.lcDreaming, "woken from it and still asleep in bed, they aren't taken into the same dream twice")
            end
            _run(1)
            LC.DreamGameStop(dl, "admin")
            _run(3)
            if not a.lcDreaming and not b.lcDreaming and LC.DreamActive == nil and #_errors == e0 then clean = clean + 1 else failed[#failed + 1] = id .. " (end)" end
        end
        for _, p in ipairs({ a, b }) do if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
        for i = #_errors, e0 + 1, -1 do if i > errs0 then failed[#failed + 1] = tostring(_errors[i]) end end
    end
    ok(tried >= 20 and joined == tried and clean == tried, "every dream you play takes a late sleeper and ends cleanly, everything put back",
        tried .. " tried, " .. joined .. " joined, " .. clean .. " clean: " .. table.concat(failed, "; "))
    -- too near its end: they sleep on
    Asleep(a, CITY)
    local okL, dl = LC.DreamStart("maze", nil, false, nil, true)
    _run(4)
    dl.game.ends = CurTime() + 20
    Asleep(b, CITY + Vector(0, 200, 0))
    _run(1.5)
    ok(okL and not b.lcDreaming and not LC.DreamCanJoinLate(dl), "with under 45 seconds of it left, a late sleeper sleeps on")
    LC.DreamGameStop(dl, "admin")
    _run(3)
    -- the tablet's "when" line has what it needs
    local off = LC.DreamOffice()
    ok(off.delay and off.delay >= 5, "the Administrator's tablet is told how long after the good night the dream comes", tostring(off.delay))
end

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b }) do
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
DreamGameTests()
function DreamCrowdTests()
section("Shared dreams: stand-ins, Enforcers, bedtime, the night shift, missed dreams, the foil hat and the chip")
_setcvar("lc_dream_rules", 1) _setcvar("lc_dream_auto", 1)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(152000, -152000, 0), Vector(212000, -212000, 0)
local a = newPlayer("DCA", "citizen")
local b = newPlayer("DCB", "citizen")
local cop = newPlayer("DCCop", "cp")
local reb = newPlayer("DCReb", "resistance", nil, 900)
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("c%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Up(p) if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end end
player.GetAll = function() return { a, b, cop, reb } end
local dp = LC.AddPoint(DREAM, 0, "dream")
local BS = LC.BedtimeState

-- who's an Enforcer, and where
ok(LC.DreamEnforcerRole(cop, "maze") and LC.DreamEnforcerRole(cop, "adore") and not LC.DreamEnforcerRole(cop, "bus")
    and not LC.DreamEnforcerRole(a, "maze"), "Civil Protection are Enforcers in nightmares and propaganda dreams, and dream Happy and Neutral ones like anyone")

-- stand-ins fill a dream you play up to six, and an Enforcer watches over it
Asleep(a, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
Asleep(cop, CITY + Vector(0, 400, 0))
for _, p in ipairs({ a, b }) do p.chat = {} end
local okM, dream = LC.DreamStart("maze", nil, false, nil, true)
local g = okM and dream.game
ok(okM and g and g.pl[a] and g.pl[b] and not g.pl[cop] and g.enf[cop] and cop.lcDreamEnforcer == dream.id and cop:GetNW2Bool("lc_enforcer", false),
    "a unit asleep for a nightmare is in it as an Enforcer, not one of its players", okM and "" or tostring(dream))
ok(g and #g.standins == 4 and LC.DreamMin() == 6, "two dreamers: four of the city's people stand in, up to lc_dream_min (6); the Enforcer doesn't count", g and #(g.standins or {}))
local said = false
for _, l in ipairs(a.chat or {}) do if string.find(l, "Also dreaming:", 1, true) then said = true end end
ok(said, "their names go up in chat as it begins")
ok(LC.DreamCanWake(cop) == true and LC.DreamCanWake(a) == false, "an Enforcer can wake whenever they like; a dreamer can't wake from a nightmare")
ok(cop.HasWeapon and cop:HasWeapon("weapon_stunstick"), "an Enforcer carries a baton in the dream")
-- a stand-in loses a life now and then, and most drop out
local s1 = g.standins[1]
s1.hits = { CurTime() + 0.1 }
s1.outAt = CurTime() + 0.5
_run(0.3)
ok(s1.lives == math.max(1, (g.def.lives or 1) - 1) or s1.lives == 1, "a stand-in loses a life (a red flash, back to the start)")
_run(0.5)
ok(s1.out and not IsValid(s1.ent), "and drops out of it (a puff, gone)")
-- how they act (the owner, 10 November): they bolt from what hunts the dreamers, and see what happens to the players
do
    local s2, s3 = g.standins[2], g.standins[3]
    for _, sb in ipairs(g.standins) do sb.hits, sb.outAt = {}, nil end -- (nothing else happens to them meanwhile)
    LC.DreamStandinDo(s2, "kneel", CurTime())
    ok(s2.act == "kneel" and s2.ent:GetNW2String("lc_dream_act", "") == "kneel" and s2.ent:GetNW2Bool("lc_dream_standin", false),
        "what a stand-in is doing is told to the dreamers' screens (for the arms, head and back)")
    local threat = g.cops[1].e
    ok(#LC.DreamStandinThreats(g) >= 2, "the giant officers are what the stand-ins fear", #LC.DreamStandinThreats(g))
    s2.pause, s2.busy, s2.flee, s2.target, s2.brave = nil, nil, nil, nil, 0.5
    s2.pos = Vector(s2.home.x, s2.home.y, s2.home.z)
    local was = threat:GetPos()
    threat:SetPos(s2.pos + Vector(120, 0, 0))
    local d0 = 120
    LC.DreamStandinsTick(CurTime())
    _advance(0.2)
    LC.DreamStandinsTick(CurTime())
    local d1 = math.sqrt((s2.pos.x - threat:GetPos().x) ^ 2 + (s2.pos.y - threat:GetPos().y) ^ 2)
    ok(s2.act == "panic" and s2.flee and d1 > d0, "an officer close by: they bolt, away from him", tostring(s2.act) .. " " .. d1)
    threat:SetPos(was)
    -- a player near them loses a life: they flinch, facing it, and one says so by name
    s3.pause, s3.busy, s3.flee, s3.target = nil, nil, nil, nil
    s3.pos = a:GetPos() + Vector(100, 0, 0)
    LC.DreamStandinsTick(CurTime())
    g.standinSaidAt = nil
    local chat0 = #(a.chat or {})
    g.pl[a].lives = g.pl[a].lives - 1
    LC.DreamStandinsTick(CurTime())
    local named = false
    for i = chat0 + 1, #(a.chat or {}) do if string.find(a.chat[i], a:Nick(), 1, true) and string.find(a.chat[i], "(in the dream)", 1, true) then named = true end end
    ok(s3.act == "flinch" and s3.faceAt ~= nil and named, "a player near them loses a life: they flinch towards it, and one of them says so by name", tostring(s3.act))
    g.pl[a].lives = g.pl[a].lives + 1
    LC.DreamStandinsTick(CurTime())
    -- a player wins: all of them cheer
    local how0 = g.pl[b].how
    g.pl[b].how = "won"
    LC.DreamStandinsTick(CurTime())
    local cheering = 0
    for _, sb in ipairs(g.standins) do if not sb.out and sb.act == "cheer" then cheering = cheering + 1 end end
    ok(cheering == 3, "a player wins: every stand-in still in it cheers", cheering)
    g.pl[b].how = how0
    LC.DreamStandinsTick(CurTime())
end
-- staging (the owner, 10 November): the opening, the figures' acting, the dreamers' own bodies, the finish
do
    local opened, finished = false, nil
    for _, m in ipairs(net.sent) do
        if m.name == "lc_dream_stage" and type(m.data[1]) == "table" and m.data[1].k == "open" and m.data[1].name == g.def.name and m.data[1].mood == "nightmare" then opened = true end
    end
    ok(opened and g.stage, "the opening: every dreamer's screen is given the dream's name")
    LC.DreamStageTick(CurTime())
    local hunter = g.cops[1].e
    local was = hunter:GetPos()
    hunter:SetPos(a:GetPos() + Vector(150, 0, 0))
    g.pl[a].lives = g.pl[a].lives - 1
    LC.DreamStageTick(CurTime())
    ok(a:GetNW2String("lc_dream_act", "") == "flinch" and a:GetNW2Bool("lc_dream_actor", false) and a:GetNW2Float("lc_dream_act_end", 0) > CurTime(),
        "a dreamer who loses a life flinches (the others see it)")
    ok(hunter:GetNW2String("lc_dream_act", "") == "gloat", "and the officer nearest them raises a fist over them", hunter:GetNW2String("lc_dream_act", ""))
    hunter:SetPos(was)
    g.pl[a].lives = g.pl[a].lives + 1
    _advance(1.2)
    LC.DreamStageTick(CurTime())
    ok(not a:GetNW2Bool("lc_dream_actor", false) and a:GetNW2String("lc_dream_act", "") == "", "a second later their body is their own again")
    local sent0, how0 = #net.sent, g.pl[b].how
    g.pl[b].how = "won"
    LC.DreamStageTick(CurTime())
    for i = sent0 + 1, #net.sent do local m = net.sent[i] if m.name == "lc_dream_stage" and type(m.data[1]) == "table" and m.data[1].k == "finish" then finished = m.data[1] end end
    ok(b:GetNW2String("lc_dream_act", "") == "cheer" and hunter:GetNW2String("lc_dream_act", "") == "slump", "a dreamer wins: they cheer, and the officers hang their heads")
    ok(finished and finished.who == b:Nick() and finished.first == true, "the finish: every dreamer's screen is told who made it through, and that they were first")
    g.pl[b].how = how0
    LC.DreamStageTick(CurTime())
    LC.DreamActSet(b, nil)
    -- the close (the owner, 11 November): the dreams nobody can win, and whoever didn't win one you play
    for _, id in ipairs(LC.EndingOrder) do
        ok(LC.DreamCloseLines[id] ~= nil, "every secret ending has a closing line of its own as a dream: " .. id)
    end
    local cH = LC.DreamCloseFor(a, { ending = "harpies", mood = "nightmare" })
    ok(cH and cH.title == "The nightmare is over" and cH.sub == LC.DreamCloseLines.harpies, "waking at the end of the harpies: the nightmare is over, in its own words")
    ok(LC.DreamCloseFor(a, { ending = "harpies", mood = "nightmare", test = true }) == nil, "(not for a test from the editor)")
    local fake = { ending = "maze", mood = "nightmare", game = { id = "maze", pl = { [a] = { how = "out" }, [b] = { how = "won" } }, won = { b } } }
    ok(LC.DreamCloseFor(b, fake) == nil and string.find(LC.DreamCloseFor(a, fake).sub, "Not you", 1, true), "a dream you play: nothing more for the winner, and the rest are told someone made it")
    fake.game.won, fake.game.pl[b].how = {}, "time"
    ok(string.find(LC.DreamCloseFor(a, fake).sub, "Nobody made it through", 1, true), "nobody won it: said so")
    local sentC = #net.sent
    hook.Run("LivingCityDreamWoke", a, true, "optout", { ending = "fire", mood = "neutral" })
    local early = false
    for i = sentC + 1, #net.sent do if net.sent[i].name == "lc_dream_stage" then early = true end end
    hook.Run("LivingCityDreamWoke", a, true, "end", { ending = "fire", mood = "neutral" })
    local closed
    for i = sentC + 1, #net.sent do local m = net.sent[i] if m.name == "lc_dream_stage" and m.to == a and type(m.data[1]) == "table" and m.data[1].k == "close" then closed = m.data[1] end end
    ok(not early and closed and closed.sub == LC.DreamCloseLines.fire and closed.title == "The dream is over", "the close goes to a dreamer as the dream ends, not to one who left it early")
end
-- bad dreamers: marked, and the baton
_run(4) -- (past the start's safety)
ok(not LC.DreamBad(a), "(nobody glows to start with)")
g.idle = { [a] = { pos = a:GetPos(), t = CurTime() - 25 } }
LC.DreamEnforcersTick(CurTime())
ok(LC.DreamBad(a), "standing about doing nothing for 20 seconds in the maze: they glow red for the Enforcers")
cop:SetPos(b:GetPos() + Vector(10, 0, 0))
ok(LC.DreamEnforcerStrike(cop) == false and g.pl[b].lives == g.def.lives, "the baton on someone who's done nothing: nothing happens")
local livesA = g.pl[a].lives
cop:SetPos(a:GetPos() + Vector(10, 0, 0))
_run(1.1)
ok(LC.DreamEnforcerStrike(cop) == true and g.pl[a].lives == livesA - 1 and not LC.DreamBad(a) and cop.lcDreamEnforceXP == 1,
    "the baton on a glowing dreamer: a life gone, the glow cleared, 1 XP for the Enforcer (paid on waking)", g.pl[a].lives .. " " .. tostring(cop.lcDreamEnforceXP))
local end0 = LC.DreamsEndured(a)
local realAddE, paidE = LC.AddXP, 0
LC.AddXP = function(p, n, why, ...) if p == cop and why == "dream enforcement" then paidE = paidE + n end return realAddE(p, n, why, ...) end
LC.DreamGameStop(dream, "admin")
_run(3.5)
LC.AddXP = realAddE
ok(not cop.lcDreaming and paidE == 1, "awake, the Enforcer's XP is paid (after everything's put back)", paidE)
ok(LC.DreamsEndured(a) == end0 + 1 and LC.DreamsEndured(cop) == 0, "a dreamer has lived through one more dream; an Enforcer hasn't")
ok(g.standins and not IsValid(g.standins[2] and g.standins[2].ent), "everything of the stand-ins is gone when it ends")
-- only Enforcers asleep: they dream it like anyone (the owner, 12 November: "I want to dream")
Up(a) Up(b)
Asleep(cop, CITY)
local okE, whyE = LC.DreamStart("maze", nil, false, nil, true)
ok(okE == true and whyE.allDream and whyE.game and whyE.game.pl[cop] ~= nil and not cop.lcDreamEnforcer, "a nightmare with only Enforcers asleep: they dream it like anyone", tostring(whyE))
if okE then LC.DreamGameStop(whyE, "admin") _run(3.5) end
Up(cop)
-- no stand-ins with lc_dream_min 0
_setcvar("lc_dream_min", 0)
Asleep(a, CITY)
local ok0, d0 = LC.DreamStart("maze", nil, false, nil, true)
ok(ok0 and #(d0.game.standins or {}) == 0, "lc_dream_min 0: no stand-ins")
if ok0 then LC.DreamGameStop(d0, "admin") end
_run(2.5)
_setcvar("lc_dream_min", 6)
Up(a)

-- stimulants: one, then not again until you've slept and dreamt properly
a:SetPData("lc_stim_locked", "0")
a:SetNW2Float("lc_wired_until", 0)
LC.GiveItem(a, "stimulant", 2)
ok(LC.ViceUse(a, "stimulant") == true and LC.StimLocked(a) and LC.Wired(a), "a stimulant: wide awake")
local okS2, whyS2 = LC.ViceUse(a, "stimulant")
ok(okS2 == false and whyS2 == LC.StimLockedText and LC.HasItem(a, "stimulant"), "a second one is refused (and stays in your pockets)", tostring(whyS2))
a:SetNW2Float("lc_wired_until", 0)
a.lcStimEve = BS.eve
a.lcAwakeSince = CurTime()
hook.Run("LivingCityDayPhase", "dawn")
ok(LC.StimLocked(a), "the night it kept you up through doesn't count, even after a nap")
a.lcStimEve = (BS.eve or 0) - 1
hook.Run("LivingCityDayPhase", "dawn")
ok(not LC.StimLocked(a), "a night's sleep after it: another one allowed")
a:SetPData("lc_stim_locked", "1")
a.lcDreamWokeFull = nil
hook.Run("LivingCityDreamWoke", a, true, "optout")
ok(LC.StimLocked(a), "(woken early from a dream: not yet)")
hook.Run("LivingCityDreamWoke", a, true, "end")
ok(not LC.StimLocked(a), "a dream dreamt through: another one allowed")
LC.TakeItem(a, "stimulant", 5)

-- the safeguard: no dream lasts more than lc_dream_max_minutes (5)
Asleep(b, CITY)
local okT, dt = LC.DreamStart("maze", nil, false, nil, true)
ok(okT and b.lcDreaming, "(a dream begins)")
if okT then dt.started = CurTime() - 301 end
_run(3)
ok(LC.DreamActive == nil and not b.lcDreaming and dt.timedOut, "still going after five minutes: ended, and everyone woken")
Up(b)

-- the foil hat: it works a third of the time (the owner, 8 November); first a night it doesn't
_setcvar("lc_foil_chance", 0)
LC.GiveItem(reb, "foil_hat", 1)
ok(LC.FoilHatUse(reb, "foil_hat") and LC.FoilOn(reb) and not LC.DreamProof(reb), "a foil hat on, and tonight it won't work (decided as it goes on)")
Asleep(reb, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
local okF0, df0 = LC.DreamStart("maze", nil, false, nil, true)
ok(okF0 and reb.lcDreaming and not LC.FoilOn(reb), "the dream walks straight in, and the hat is spent anyway")
if okF0 then LC.DreamGameStop(df0, "admin") end
_run(3.5)
ok(not LC.FoilOn(reb), "(and waking doesn't put it back on)")
Up(reb) Up(b)
_setcvar("lc_foil_chance", 1)
LC.GiveItem(reb, "foil_hat", 1)
ok(LC.FoilHatUse(reb, "foil_hat") and LC.FoilOn(reb) and LC.DreamProof(reb) and not LC.HasItem(reb, "foil_hat"), "a foil hat on: no dream can reach you")
Asleep(reb, CITY)
Asleep(b, CITY + Vector(0, 200, 0))
local inIt = false
for _, p in ipairs(LC.DreamSleepers("nightmare", "maze")) do if p == reb then inIt = true end end
ok(not inIt, "(asleep in it, a nightmare passes them by)")
local okF, df = LC.DreamStart("maze", nil, false, nil, true)
ok(okF and not reb.lcDreaming and not LC.FoilOn(reb), "the hat keeps one dream out, and is spent")
_setcvar("lc_foil_chance", 0.33)
if okF then LC.DreamGameStop(df, "admin") end
_run(2.5)
Up(reb) Up(b)

-- the chip
reb:SetPData("lc_dreams_endured", "1")
ok(LC.ChipSurgeryReady(reb) == false and select(2, LC.DreamOptOutEarned(reb)) ~= nil, "the lab won't pull the chip (or make a foil hat) until you've lived through three dreams")
local okLab = LC.LabMake(reb, "foil_hat", "pay")
ok(okLab == false, "(the foil hat waits too)")
reb:SetPData("lc_dreams_endured", "3")
LC.AddCredits(reb, 600)
ok(LC.ChipSurgeryReady(reb) == true and LC.ChipPrice() == 500, "three dreams and 500 credits: the chip can be pulled")
reb:SetPData("lc_chipless", "1")
Asleep(reb, CITY)
inIt = false
for _, p in ipairs(LC.DreamSleepers("happy", "adore")) do if p == reb then inIt = true end end
ok(LC.Chipless(reb) and not inIt and not LC.Chipped(reb), "no chip: no dreams at all")
ok(LC.SleepSecsFor(reb, 300) == 90 and LC.SleepSecsFor(a, 300) == 300, "no chip: a night's sleep takes at most 90 seconds")
hook.Run("LivingCitySlept", reb)
_run(0.2)
ok(not reb.lcSleep, "and they get up on their own")
_setcvar("lc_chip_notice", 1)
reb.lcImplantRolled = nil
ok(LC.ImplantNoticed(reb) == true and LC.ImplantNoticed(reb) == false and LC.ImplantNoticed(a) == false, "a unit may notice there's no implant signal (once a stop; never with the chip in)")
reb.lcImplantRolled = nil
reb:SetPData("lc_new_face", "1") -- (no wanted notice to match first)
local okP, whyP = LC.CheckPapers(reb)
reb:SetPData("lc_new_face", "0")
ok(okP == false and whyP == LC.NoImplantText, "(at a papers check too)", tostring(whyP))
_setcvar("lc_chip_notice", 0.15)
reb:SetPData("lc_chipless", "0")
reb:SetPData("lc_dreams_endured", "0")

-- lights out: everyone (the owner, 8 November: "all human players get sleepy/exhausted at the same time")
LC.SetHour(12)
a.lcAwakeSince = CurTime()
local len = GetGlobal2Float("lc_day_len", 3600)
local due = LC.BedtimeDue(a)
ok(due and math.abs(due - (CurTime() + 9 / 24 * len)) < 2 and LC.TiredDue(a) <= due + 0.01, "a citizen is due in bed at the good night (21:00), whatever they slept", due and (due - CurTime()))
reb.lcAwakeSince, cop.lcAwakeSince = CurTime(), CurTime()
local adm = newPlayer("DCAdm", "admin")
adm.lcAwakeSince = CurTime()
ok(LC.BedtimeDue(reb) and LC.BedtimeDue(cop), "the Resistance and Civil Protection too")
ok(not LC.BedtimeDue(adm), "but not the Administrator, for a dream she didn't choose (she skips them: the owner, 9 November)")
LC.DreamAdminSkipSet(adm, false)
ok(LC.BedtimeDue(adm) and math.abs(LC.BedtimeDue(adm) - due) < 2, "unless she chooses to join them")
local listWas = player.GetAll
player.GetAll = function() return { adm } end
adm.lcAwakeSince = CurTime() - len * 2
LC.SetHour(22)
LC.RestTick(CurTime())
player.GetAll = listWas
ok(LC.IsTired(adm), "the Administrator gets tired like anyone")
adm:SetPos(Vector(-122000, -122000, 0))
a:SetNW2Float("lc_wired_until", CurTime() + 600)
ok(LC.BedtimeDue(a) >= CurTime() + 599, "a stimulant holds lights out off while it lasts")
a:SetNW2Float("lc_wired_until", 0)
local realPending = LC.DreamTonightPending
a.lcAwakeSince = CurTime() - 10
LC.DreamTonightPending = function() return true end
ok(LC.BedtimeDue(a) - CurTime() > len * 0.9, "slept after the good night: done for tonight")
a.lcAwakeSince = CurTime() - 2 / 24 * len
ok(LC.BedtimeDue(a) <= CurTime(), "slept at dusk with a dream still to come: back to bed")
a.lcDreamtEve = BS.eve
ok(LC.BedtimeDue(a) - CurTime() > len * 0.5, "woken from tonight's dream: done for tonight")
a.lcDreamtEve = nil
LC.DreamTonightPending = function() return false end
local dEve = BS.dreamEve
BS.dreamEve = nil
ok(LC.BedtimeDue(a) - CurTime() > len * 0.5, "slept at dusk, and no dream tonight: done for tonight")
BS.dreamEve, LC.DreamTonightPending = dEve, realPending
-- the night shift
BS.roll[BS.eve or 0] = true
local tmpl
for _, t in ipairs(LC.QuestTemplates) do if t.id == "cp_nightshift" then tmpl = t end end
LC.SetHour(19)
ok(tmpl and tmpl.first and tmpl.available(cop), "most nights the night shift is on Civil Protection's board (first), in the evening")
LC.SetHour(23)
ok(not tmpl.available(cop) and tmpl.recheck, "not later in the night (the owner, 11 November: only from 18:00 to 21:00), and checked again when it's taken")
LC.SetHour(19)
LC.QuestOf[cop] = { tmpl = tmpl }
cop.lcNightShift = BS.eve
ok(LC.OnNightShift(cop) and LC.BedtimeDue(cop) == nil, "on the night shift: no lights out")
ok(LC.NightShiftIssue(cop) and LC.HasItem(cop, "stimulant") and not LC.NightShiftIssue(cop), "a CP Commissary issues one stimulant shot, once a night")
LC.QuestOf[cop] = nil
cop.lcNightShift = nil
LC.SetHour(12)
ok(not tmpl.available(cop), "(not by day)")

-- a rebel player killed by a unit: 5 XP
reb:SetNW2String("lcf_faction", "resistance")
local realAdd, gotXP = LC.AddXP, 0
LC.AddXP = function(p, n, why) if p == cop and why == "anticitizen neutralized" then gotXP = gotXP + n end end -- (only the kill's own XP: a conduct strike is another matter)
hook.Run("DoPlayerDeath", reb, cop)
hook.Run("PlayerDeath", reb, nil, cop)
LC.AddXP = realAdd
ok(gotXP == 5 and LCF.XP.rebel_kill == 5, "a unit who kills a rebel player gets 5 XP (as for an NPC rebel), even if permanent death makes them a citizen first", gotXP)


-- which dream tonight (the owner, 8 November: nightmares on bad days, propaganda and Neutral by turns, Happy after a clean day)
local socioWas = LC.Socio
LC.Socio = "green"
LC.DreamDayReset()
LC.DreamRules.lastKind = nil
ok(LC.DreamAllowed("bus") and not LC.DreamAllowed("maze") and LC.DreamAllowed("adore"), "a clean day: a Happy dream (or propaganda) yes, a Nightmare no")
hook.Run("LivingCityEventStarted", "curfew", 5)
local okH, whyH = LC.DreamAllowed("bus")
ok(not okH and string.find(tostring(whyH), "curfew", 1, true) and not LC.DreamAllowed("maze"), "a curfew today: no Happy dream (and still no Nightmare)", tostring(whyH))
hook.Run("LivingCitySocioChanged", "red", "green")
ok(LC.DreamAllowed("maze") and LC.DreamKind("maze") == "nightmare", "sociostability fell to red: a Nightmare is allowed")
LC.DreamRules.lastKind = "propaganda"
ok(not LC.DreamAllowed("adore") and LC.DreamKind("adore") == "propaganda", "never two propaganda dreams in a row")
local admP = newPlayer("DCAdmin2", "admin")
local okPick, whyPick = LC.DreamAdminPick(admP, "adore")
ok(okPick == false and string.find(tostring(whyPick), "Not tonight", 1, true), "the Administrator can't pick one the day doesn't allow", tostring(whyPick))
-- the city's own choice now (the owner, 9 November): by sociostability, with Happy or Neutral after every Nightmare or propaganda night
do
    local gaWas = player.GetAll
    player.GetAll = function() return {} end
    LC.DreamPlan.specialNight = -100
    LC.Socio = "green" LC.DreamDayReset() LC.DreamDayTimeReset()
    LC.DreamUnitMurdered()
    local k1, w1 = LC.DreamPlanDecide()
    ok(k1 == "nightmare" and w1 == "murder", "no Administrator: a unit murdered today, a Nightmare", tostring(k1))
    LC.Socio = "green" LC.DreamDayReset() LC.DreamDayTimeReset()
    hook.Run("LivingCitySocioChanged", "red", "green")
    _run(5)
    local seen = {}
    for _ = 1, 30 do seen[(LC.DreamPlanDecide())] = true end
    ok(seen.nightmare and seen.propaganda and not seen.happy and not seen.neutral, "red all day: a Nightmare or propaganda, a toss-up")
    LC.Socio = "green" LC.DreamDayReset() LC.DreamDayTimeReset()
    hook.Run("LivingCitySocioChanged", "yellow", "green") hook.Run("LivingCitySocioChanged", "green", "yellow")
    local k3, w3 = LC.DreamPlanDecide()
    ok(k3 == "happy" and w3 == "calm", "green but for one dip to yellow: Happy", tostring(k3))
    hook.Run("LivingCitySocioChanged", "yellow", "green")
    ok((LC.DreamPlanDecide()) == "neutral", "yellow more than that: Neutral")
    LC.Socio = "green" LC.DreamDayReset() LC.DreamDayTimeReset()
    LC.DreamUnitMurdered()
    LC.DreamPlan.specialNight = LC.DreamPlanTonight() - 1
    local k5, w5 = LC.DreamPlanDecide()
    ok((k5 == "neutral" or k5 == "happy") and w5 == "after", "but the night after a Nightmare or propaganda: Happy or Neutral first", tostring(k5))
    LC.DreamPlan.specialNight = -100
    player.GetAll = function() return { admP } end
    local k6, w6 = LC.DreamPlanDecide()
    ok(k6 == "neutral" and w6 == "spared", "a player Administrator: the nights she doesn't choose are Happy or Neutral, whatever the day", tostring(k6))
    -- round robin: each kind in turn
    local list = LC.DreamsOfKind("neutral")
    local r0 = LC.DreamPlan.rot.neutral or 0
    local first = LC.DreamPlanNext("neutral")
    LC.DreamPlanAdvance("neutral")
    local second = LC.DreamPlanNext("neutral")
    ok(#list > 1 and first ~= second and first == list[(r0 % #list) + 1] and second == list[((r0 + 1) % #list) + 1], "each kind plays its dreams in turn, the next one each time")
    LC.DreamPlan.rot.neutral = r0
    -- the words on the black screen: inferred, never a formula
    ok(string.find(LC.DreamMoodText("calm", "happy"), "%a") and LC.DreamMoodTexts.murder and LC.DreamMoodTexts.admin_propaganda and #LC.DreamMoodTexts.uneasy >= 3, "a line for the day's mood, for every reason")
    player.GetAll = gaWas
end
ok(LC.DreamCityPicks() == true, "nobody playing the Administrator: the city picks every night")
local off2 = LC.DreamOffice()
local blockedSeen = false
for _, g in ipairs(off2.groups) do for _, e in ipairs(g.endings) do if e.id == "maze" and e.blocked then blockedSeen = true end end end
ok(blockedSeen and off2.day ~= nil, "her tablet greys out what isn't allowed tonight, and says what the day was")
admP:SetPos(Vector(-122000, -122000, 0))
LC.Socio = socioWas
LC.DreamDayReset()
LC.DreamRules.lastKind = nil

-- asleep: hunger and thirst wait, and never hurt or wake you
_setcvar("lc_needs", 1)
Asleep(a, CITY)
a:SetHealth(100)
a:SetNW2Float("lcn_hunger", 0)
a:SetNW2Float("lcn_thirst", 50)
_run(11)
ok(a.lcSleep and a:Health() == 100 and math.abs(LC.Thirst(a) - 50) < 0.01, "asleep: no thirst lost, no starving, still asleep", a:Health() .. " " .. LC.Thirst(a))
Up(a)
a:SetNW2Float("lcn_hunger", 80)
_setcvar("lc_needs", 0)

-- hurt in a dream: the sleeping body in the bed is hit, and they wake up in their bed and take it
Asleep(b, CITY)
local okD, dd = LC.DreamStart("maze", nil, false, nil, true)
local body = ents.Create("prop_physics")
body.lcDreamBodyOf = b
b:SetHealth(100)
local fakeDmg = { GetDamage = function() return 10 end, GetAttacker = function() return cop end }
local friendDmg = { GetDamage = function() return 10 end, GetAttacker = function() return a end }
hook.t.EntityTakeDamage.LivingCityDreamBody(body, friendDmg)
_run(1)
ok(b.lcDreaming, "a friend's hit on a dreamer's sleeping body does nothing (no waking them to skip it)")
ok(okD and b.lcDreaming and hook.t.EntityTakeDamage.LivingCityDreamBody(body, fakeDmg) == true, "(the sleeping body takes no hit itself)")
_run(2.5)
ok(not b.lcDreaming and not b.lcSleep and b:Health() == 90 and (b.lcStartledUntil or 0) > CurTime(), "hit in their sleep: out of the dream, up, and hurt", tostring(b.lcDreaming) .. " " .. tostring(b.lcSleep ~= nil) .. " " .. b:Health())
if IsValid(body) then body:Remove() end
_run(2.5)

-- rebel ground: anyone shot there, attacked by the Combine, hit with a baton or arrested wakes everyone asleep there
local RZ = CITY + Vector(6000, 0, 0)
local rzone = LC.AddZone(RZ, 400, "rebel", 0)
local function Hit(kind, att, inf) return { GetDamage = function() return 5 end, GetAttacker = function() return att end, GetInflictor = function() return inf or att end,
    GetDamageType = function() return kind end, IsBulletDamage = function() return kind == DMG_BULLET end } end
local victim = newPlayer("DCVictim", "resistance", nil, 900)
victim:SetPos(RZ + Vector(50, 0, 0))
Asleep(reb, RZ)
ok(not LC.RaidWakeHit(victim, Hit(DMG_BURN or 8, a)) and not LC.RaidWakeHit(victim, Hit(DMG_CRUSH or 1, a)), "burnt by a barrel or knocked by a prop: nobody wakes")
hook.t.EntityTakeDamage.LivingCityRaidWake(victim, Hit(DMG_BURN or 8, a))
ok(reb.lcSleep ~= nil, "(still asleep)")
hook.t.EntityTakeDamage.LivingCityRaidWake(victim, Hit(DMG_BULLET, victim))
hook.t.EntityTakeDamage.LivingCityRaidWake(reb, Hit(DMG_BULLET, a))
ok(reb.lcSleep ~= nil and not LC.RaidWakeHit(victim, Hit(DMG_BULLET, victim)) and not LC.RaidWakeHit(victim, Hit(DMG_BULLET, a)),
    "a rebel (or any other player) shooting a friend in the camp wakes nobody: no skipping the dream that way")
hook.t.EntityTakeDamage.LivingCityRaidWake(victim, Hit(DMG_BULLET, cop))
ok(not reb.lcSleep and LC.RaidWakeHit(victim, Hit(DMG_BULLET, cop)), "someone in the camp shot by a unit: the rebels asleep there wake")
ok(reb:GetNW2Float("lc_groggy_until", 0) <= CurTime() and reb:GetNW2Float("lc_stamina", 0) >= 99 and not reb:GetNW2Bool("lc_winded", false)
    and (reb.lcStartledUntil or 0) > CurTime() + 500, "woken by violence: adrenaline first (wide awake, full stamina, lights out waits ten minutes)")
reb.lcStartledUntil = CurTime() - 1
_run(2.5)
ok(reb:GetNW2Float("lc_groggy_until", 0) > CurTime() and reb:GetNW2Float("lc_stamina", 100) < 15 and reb:GetNW2Bool("lc_winded", false),
    "the adrenaline worn off: groggy, no stamina (only a little back yet)", reb:GetNW2Float("lc_stamina", 100))
ok(LCS.RegenMul(reb) < 0.5, "and stamina comes back slowly while groggy", LCS.RegenMul(reb))
Asleep(reb, RZ)
local wasUntil = reb:GetNW2Float("lc_groggy_until", 0)
reb:SetNW2Float("lc_groggy_until", 0)
LC.MakeGroggy(reb)
reb.lcStartledUntil = CurTime() - 1
_run(2.5)
ok(reb:GetNW2Float("lc_groggy_until", 0) == 0, "(back in bed before it wears off: no crash)")
Up(reb)
reb:SetNW2Float("lc_groggy_until", wasUntil)
ok(LC.RaidWakeHit(victim, Hit(DMG_CLUB or 128, cop)), "anything at all from a Civil Protection unit counts")
local baton = ents.Create("weapon_stunstick")
ok(not LC.RaidWakeHit(victim, Hit(DMG_CLUB or 128, victim, baton)), "(a rebel with a stolen baton doesn't count)")
if IsValid(baton) then baton:Remove() end
_run(6)
Asleep(reb, RZ)
reb:SetNW2Float("lc_groggy_until", 0)
local copAt = cop:GetPos()
victim:SetPos(RZ + Vector(50, 0, 0))
cop:SetPos(victim:GetPos() + Vector(40, 0, 0))
LC.BatonArrest(cop, victim)
cop:SetPos(copAt)
ok(not reb.lcSleep, "someone arrested there with the baton: the camp wakes")
if LC.Struggles then LC.Struggles[victim] = nil end
victim:SetPos(Vector(-122000, -122000, 0))
Asleep(reb, RZ)
local okR2, dr2 = LC.DreamStart("maze", nil, false, nil, true)
ok(okR2 and reb.lcDreaming, "(a rebel in that camp dreaming)")
local nWoke = LC.WakeRebelZone(rzone, RZ, true)
_run(3.5)
ok(nWoke >= 1 and not reb.lcDreaming and not reb.lcSleep, "a raid on their camp pulls a dreamer out, and they're up")
LC.RemoveZone(rzone)
_run(2.5)


-- stimulants: 40 credits, and a limited supply at the black market (the owner, 8 November)
local stimG = LCS.BlackById.stimulant
LC.BlackStock.stim = nil
local left0 = LC.BlackStockLeft(stimG)
ok(stimG.price == 40 and left0 == 5 and LC.BlackStockLeft(LCS.BlackById.beer) == nil, "a stimulant is 40 credits, and the dealers hold 5 at a time (beer: as much as anyone wants)")
LC.BlackStock.stim.n = 0
local leftS, nextS = LC.BlackStockLeft(stimG)
ok(leftS == 0 and nextS and nextS > 0, "sold out: more on the way")
LC.BlackStock.stim.at = CurTime() - 20 * 60 - 1
ok(LC.BlackStockLeft(stimG) == 1, "one more every 20 minutes")
LC.BlackStock.stim = nil


-- asleep, a friend's hit does nothing (no wake, no harm); an enemy's, or the world's, wakes them groggy
local function Punch(att) return { GetDamage = function() return 5 end, GetAttacker = function() return att end } end
local reb2 = newPlayer("DCReb2", "resistance", nil, 900)
local reb3 = newPlayer("DCReb3", "resistance", nil, 900)
Asleep(reb3, CITY)
reb3:SetHealth(100)
reb3:SetNW2Float("lc_groggy_until", 0)
ok(hook.t.EntityTakeDamage.LivingCitySleepWake(reb3, Punch(reb2)) == true and reb3.lcSleep and reb3:Health() == 100, "a fellow rebel's hit on a sleeper: nothing (still asleep, unhurt)")
ok(hook.t.EntityTakeDamage.LivingCitySleepWake(reb3, Punch(a)) == true and reb3.lcSleep, "nor a citizen player's (a rebel wakes only to an enemy of the camp)")
hook.t.EntityTakeDamage.LivingCitySleepWake(reb3, Punch(cop))
ok(not reb3.lcSleep and reb3.lcGroggyPending and (reb3.lcStartledUntil or 0) > CurTime(), "a unit's hit wakes them, on adrenaline (groggy later)")
Asleep(a, CITY + Vector(0, 300, 0))
local cit2 = newPlayer("DCCit2", "citizen")
ok(hook.t.EntityTakeDamage.LivingCitySleepWake(a, Punch(cit2)) == true and a.lcSleep, "a citizen hit by another citizen sleeps on")
hook.t.EntityTakeDamage.LivingCitySleepWake(a, Punch(game.GetWorld()))
ok(not a.lcSleep, "the world's harm (a fire, a fall) still wakes them")
ok(LC.SleeperEnemy(a, reb2) and LC.SleeperEnemy(cop, reb2) and not LC.SleeperEnemy(cop, adm or cop), "(a rebel's hit wakes a citizen or a unit; a unit's own side doesn't)")
-- the city's sleeping NPCs too: their own side can't hurt them
local sleepCit, sleepReb = ents.Create("npc_citizen"), ents.Create("npc_citizen")
LC.NPCs[sleepCit] = { role = "citizen", state = "abed" }
LC.NPCs[sleepReb] = { role = "rebel", state = "idle", life = { asleep = true } }
ok(sleepCit.IsNPC and sleepCit:IsNPC() and hook.t.EntityTakeDamage.LivingCityBedWake(sleepCit, Punch(cit2)) == true, "a citizen asleep in a bed can't be hurt by a citizen")
ok(LC.FriendHitsSleeper(sleepReb, reb2) and not LC.FriendHitsSleeper(sleepReb, cop) and not LC.FriendHitsSleeper(sleepCit, cop),
    "nor a rebel asleep in camp by a rebel; a unit's hit gets through to either")
LC.NPCs[sleepCit], LC.NPCs[sleepReb] = nil, nil
sleepCit:Remove() sleepReb:Remove()
for _, q in ipairs({ reb2, reb3, cit2 }) do q:SetPos(Vector(-122000, -122000, 0)) end

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ a, b, cop, reb }) do
    Up(p)
    p:SetPos(Vector(-122000, -122000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
DreamCrowdTests()
function PropagandaDreamTests()
section("Shared dreams: propaganda dreams you play (kneel, roses, mirror, the saviour, the quiz; the Administrator starring)")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0) -- (the older tests: the Administrator picks freely, and the city doesn't pick: DreamCrowdTests has the rules)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(152000, -152000, 0), Vector(212000, -212000, 0)
local adm = newPlayer("ADAdmin", "admin")
local a = newPlayer("ADA", "citizen")
local b = newPlayer("ADB", "citizen")
local c = newPlayer("ADC", "resistance")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Both() Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0)) a.crouch, b.crouch = nil, nil end
local function Look(p, g) p.aim = (g.herHead - p:EyePos()):GetNormalized() end
local function Sent(p, k, test)
    for _, m in ipairs(net.sent) do
        local t = m.data[1]
        if m.name == "lc_dreamgame" and (m.to == p or (type(m.to) == "table" and table.HasValue(m.to, p))) and type(t) == "table" and t.k == k and (not test or test(t)) then return t end
    end
    return nil
end
local function Said(g, cue) for _, c in ipairs(g.said or {}) do if c == cue then return true end end return false end
player.GetAll = function() return { adm, a, b, c } end
local dp = LC.AddPoint(DREAM, 0, "dream")

-- on the tablet, under Happy (of course), as propaganda
local off = LC.DreamOffice()
local found = {}
for _, e in ipairs(off.groups[1].endings) do if e.game and e.propaganda then found[e.id] = e.name end end
ok(found.adore == "Propaganda: Kneel Before Her" and found.roses == "Propaganda: Roses for Her" and found.mirror == "Propaganda: Mirror, Mirror"
    and found.saviour == "Propaganda: The Saviour" and found.quiz == "Propaganda: The Loyalty Quiz", "the five propaganda dreams are on her tablet, under Happy, as Propaganda")
ok(LC.DreamMoods("saviour=nightmare").saviour == "nightmare", "(lc_dream_moods can label them otherwise)")
do -- (she chooses a kind; the city decides which, the next in turn: the owner, 9 November)
    local list = LC.DreamsOfKind("propaganda")
    for i, id in ipairs(list) do if id == "saviour" then LC.DreamPlan.rot.propaganda = i - 1 end end
    LC.DreamPlan.adminNight, LC.DreamPlan.specialNight = -100, -100
    ok(LC.AdminDo(adm, "dream", "saviour") == false, "she can't choose which dream")
    ok(LC.AdminDo(adm, "dream", "propaganda") and LC.DreamQueued().id == "saviour" and LC.DreamQueued().cat == "propaganda" and LC.DreamOffice().plan.chosen == "propaganda",
        "she chooses propaganda for tonight; the city decides which (the next in turn)")
    ok(not LC.DreamAdminCanPick(adm) and LC.AdminDo(adm, "dream", "cancel") and LC.DreamQueued() == nil and LC.DreamAdminCanPick(adm), "she can take it back before it's dreamt (nothing spent)")
    LC.DreamAdminSkipSet(adm, false) -- (the rest of these: she joins the dreams she didn't choose)
end
LC.DreamForget()
-- the music, named for its codeword in sound/livingcity/dreams/ (and the first folder still counts)
local MEDIA = { "sound/livingcity/dreams/admire1.mp3", "sound/livingcity/dreams/saviour2.ogg", "sound/livingcity/dreams/saviour_horde1.mp3",
    "sound/livingcity/dreams/readme.txt", "sound/livingcity/dreams/administrator/smooth_sax.mp3",
    "sound/livingcity/dreams/voice/saviour_stop1.wav", "sound/livingcity/dreams/voice/saviour_stop1.txt" }
for _, f in ipairs(MEDIA) do _files[f] = "x" end
_files["sound/livingcity/dreams/voice/saviour_stop1.txt"] = "Halt, foul things!"
local adm1 = LC.PropagandaSongs("admire")
ok(#adm1 == 2 and adm1[1] == "livingcity/dreams/admire1.mp3" and adm1[2] == "livingcity/dreams/administrator/smooth_sax.mp3", "admire songs: named admire, or anything in the first folder")
ok(LC.PropagandaSongs("saviour")[1] == "livingcity/dreams/saviour2.ogg" and #LC.PropagandaSongs("saviour") == 1 and LC.PropagandaSongs("saviour_horde")[1] == "livingcity/dreams/saviour_horde1.mp3",
    "The Saviour's two songs: saviour_horde before she comes, saviour after (the longest name that fits)")
local vsnd, vtext = LC.PropagandaVoice("saviour_stop")
local nsnd, ntext = LC.PropagandaVoice("saviour_soldiers")
ok(vsnd == "livingcity/dreams/voice/saviour_stop1.wav" and vtext == "Halt, foul things!" and nsnd == nil and ntext == "Come, my soldiers. Protect them.",
    "her voice: a recording named for its line (its .txt the subtitle); no recording, the words alone")

-- not skippable: opting out doesn't keep you out; being Unbroken does
Both()
b:SetPData("lc_dream_optout", "1")
a:SetNW2Float("lc_unbroken_until", CurTime() + 600)
local who = LC.DreamSleepers(LC.DreamMood("adore"), "adore")
ok(table.HasValue(who, b) and not table.HasValue(who, a), "no opting out of a propaganda dream (only Unbroken keeps you out: the Combine can't get into your head)")
ok(table.HasValue(LC.DreamSleepers("happy", "bus"), b), "(and no opting out of a Happy ending as a dream either: the owner, 8 November)")
b:SetPData("lc_dream_optout", "0")
a:SetNW2Float("lc_unbroken_until", 0)

-- Kneel Before Her
Both()
local okA, d1 = LC.DreamStart("adore", adm, false, nil, true)
local g = okA and d1.game
ok(okA and g and g.id == "adore" and IsValid(g.her) and not g.star and #g.ents > 8, "Kneel Before Her is built: the hall, a giant figure of her on a pedestal (she's awake), kneeling admirers")
local hello = Sent(a, "start", function(t) return t.id == "adore" end)
ok(hello and hello.theme == "admire" and table.HasValue(adm1, hello.song), "the dreamer's screen goes pink, and an admire song plays")
ok(not LC.DreamCanWake(b) and not LC.DreamWakeAsked(b) and b.lcDreaming and b:GetNW2Bool("lc_dream_forced", false), "not skippable: nobody wakes themselves from a propaganda dream while they're still in it")
do -- (staging: her figure and her admirers act, sv_livingcity_dreamstage.lua)
    local gS = LC.DreamActive and LC.DreamActive.game
    LC.DreamStageTick(CurTime())
    local her, _, adm = LC.DreamStageFigures(gS)
    ok(gS and gS.stage ~= nil and (her == nil or her:GetNW2String("lc_dream_act", "") == "regal") and (#adm == 0 or adm[1]:GetNW2String("lc_dream_act", "") == "kneel"),
        "her figure stands regally and her admirers hold out their arms to her", (her and her:GetNW2String("lc_dream_act", "") or "no figure") .. " " .. #adm)
end
_run(3.5)
ok(Said(g, "adore_hello"), "(she greets them)")
local s = g.pl[a]
g.gazeAt = CurTime() + 60
g.herYaw = math.deg(math.atan2(a:GetPos().y - g.herBase.y, a:GetPos().x - g.herBase.x))
g.gazeWant = g.herYaw
_run(0.2)
ok(s.lives == 2 and a:GetPos():Distance(s.start) < 1 and LC.PropagandaOffences(a) == 1, "she catches you standing in her gaze: a life gone, back to the back, and an offence", s.lives)
a.crouch = true
Look(a, g)
g.herYaw = math.deg(math.atan2(a:GetPos().y - g.herBase.y, a:GetPos().x - g.herBase.x))
g.gazeWant = g.herYaw
s.safe = 0
_run(1)
ok((s.devotion or 0) > 5 and s.lives == 2, "kneeling and gazing up at her fills your Devotion", s.devotion)
s.devotion = 99.9
_run(0.2)
ok(s.how == "won" and a.lcGameWatching and LC.DreamCanWake(a), "full Devotion: she notices you (and, out of it, you may wake or watch the rest)")
local stA, hpA0 = LC.Standing(a), a:Health()
LC.DreamGameStop(d1, "test")
_run(2.5)
ok(not a.lcDreaming and LC.DreamActive == nil and not LC.Unbroken(a) and not LC.DreamScarred(a) and a:GetMaxHealth() == 100, "over: everyone wakes; no health lost, no scar")
ok(LC.Standing(a) == stA - 3, "the offence costs 3 loyalty points (Civil Standing) as they wake", LC.Standing(a) - stA)

-- Roses for Her
Both()
local okR, d2 = LC.DreamStart("roses", adm, false, nil, true)
local gr = okR and d2.game
ok(okR and gr and #gr.rose == 6 and #gr.guards == 2 and gr.feetX > gr.lineX, "Roses for Her is built: the carpet, the gold line, her honour guard, glowing roses")
_run(3.5)
local sr = gr.pl[a]
local r1 = gr.rose[1]
a:SetPos(r1.pos - Vector(0, 0, 20))
_run(0.2)
ok(sr.carrying and r1.gone, "walking over a rose picks it up")
a:SetPos(Vector(gr.lineX + 100, gr.midY, gr.top))
_run(0.2)
ok(sr.lives == 3 and sr.carrying, "standing in her half of the hall for a moment: time to get down (13 November)", sr.lives)
_run(1.8)
ok(sr.lives == 2 and not sr.carrying, "standing in her half of the hall: her guard carries you back (the rose is lost)", sr.lives)
sr.safe = 0
a.crouch = true
for i = 1, 3 do
    sr.carrying = true
    a:SetPos(Vector(gr.feetX + 10, gr.midY, gr.top))
    _run(0.2)
end
ok(sr.given == 3 and sr.how == "won", "three roses laid at her feet, on your knees: adored", sr.given)
LC.DreamGameStop(d2, "test")
_run(2.5)

-- Mirror, Mirror
Both()
local okM, d3 = LC.DreamStart("mirror", adm, false, nil, true)
local gm = okM and d3.game
ok(okM and gm and IsValid(gm.her), "Mirror, Mirror is built: her, the mirrors, the admirers")
_run(3.5)
local sm = gm.pl[a]
local out = hook.Run("PlayerSay", a, "you are radiant")
ok(out == "" and (sm.score or 0) == 0, "standing, she doesn't hear you (and the city doesn't hear the dream)")
a.crouch = true
hook.Run("PlayerSay", a, "you are radiant and flawless")
ok(sm.score == 4, "kneeling: words nobody has used yet count double", sm.score)
b.crouch = true
hook.Run("PlayerSay", b, "so radiant")
ok(gm.pl[b].score == 1, "a word someone else used first counts once", gm.pl[b].score)
hook.Run("PlayerSay", a, "radiant radiant")
ok(sm.score == 4, "saying your own again counts for nothing")
local heard = false
for _, m in ipairs(b.chat or {}) do if string.find(m, "flawless", 1, true) then heard = true end end
ok(heard, "(the others in the dream hear it)")
hook.Run("PlayerSay", b, "a bit old though")
ok(gm.pl[b].lives == 2, "an insult costs a life", gm.pl[b].lives)
gm.pl[b].safe = 0
hook.Run("PlayerSay", b, "the combine are fascists")
gm.pl[b].safe = 0
hook.Run("PlayerSay", b, "pigs")
ok(gm.pl[b].how == "out" and select(1, LC.PropagandaOffences(b)) == 3 and select(2, LC.PropagandaOffences(b)), "so does an insult to the Combine; every life gone, out of it", gm.pl[b].lives)
local stB = LC.Standing(b)
hook.Run("PlayerSay", a, "/gorgeous")
ok(sm.score == 4 and a.lcDreaming, "(a command isn't a compliment: commands still go where they always did)")
hook.Run("PlayerSay", a, "gorgeous divine goddess perfect")
ok(sm.how == "won", "enough adoration: the fairest of them all", sm.score)
LC.DreamGameStop(d3, "test")
_run(4) -- (everything put back in full first, as after any dream)
ok(LC.Standing(b) == stB - 14, "waking: 3 loyalty points an offence, 5 more for being thrown out (here 14)", LC.Standing(b) - stB)

-- The Saviour
Both()
Asleep(c, CITY + Vector(0, -200, 0))
local stS = LC.Standing(a)
a:SetHealth(100) b:SetHealth(100) c:SetHealth(100)
local okS, d4 = LC.DreamStart("saviour", adm, false, nil, true)
local gs = okS and d4.game
local T = LC.SaviourTimes
ok(okS and gs and gs.phase == "calm" and not IsValid(gs.her), "The Saviour is built: a ruined street, quiet, and no sign of her yet")
local hs = Sent(a, "start", function(t) return t.id == "saviour" end)
ok(hs and hs.theme == "glory" and hs.song == "livingcity/dreams/saviour_horde1.mp3", "(the dread music first)")
gs.pl[a].safe, gs.pl[b].safe, gs.pl[c].safe = CurTime() + 1000, CurTime() + 1000, CurTime() + 1000
_run(7)
ok(gs.phase == "horde" and LC.SaviourAlive(gs) >= 2, "the dead come in from the edges", LC.SaviourAlive(gs))
local m1
for _, m in ipairs(gs.mons) do if m.alive then m1 = m break end end
gs.pl[a].safe = 0
a:SetHealth(60)
m1.e:SetPos(a:GetPos())
m1.next = 0
_run(0.1)
ok(a:Health() < 60 and a:Health() > 25 and gs.phase == "horde" and not IsValid(gs.her), "a claw: it hurts (in the dream), and nobody comes yet", a:Health())
a:SetHealth(30)
m1.next = 0
m1.e:SetPos(a:GetPos())
_run(0.2)
ok(a:Health() <= 25 and gs.phase == "descend" and IsValid(gs.her) and gs.her:GetPos().z > gs.top + 200, "down to 25: everything freezes, and she comes down from near the top of the zone", a:Health())
local frozen
for _, m in ipairs(gs.mons) do if m.alive then frozen = { m, m.e:GetPos() } break end end
local hpFrozen = a:Health()
m1.next = 0
_run(1)
ok(frozen and frozen[1].e:GetPos():Distance(frozen[2]) < 1 and a:Health() == hpFrozen, "the dead stop where they are (and hurt nobody now)")
_run(T.land)
ok(gs.phase == "stop" and Said(gs, "saviour_stop") and gs.her:GetPos():Distance(gs.land) < 1, "she lands between them and the citizens: \"Stop!\"")
_run(T.soldiers - T.land + 0.3)
-- (with no monster left alive by then, which a busy shard can bring, the soldiers' phase passes straight to "safe")
local monsLeft = 0
for _, m in ipairs(gs.mons) do if m.alive then monsLeft = monsLeft + 1 end end
ok((gs.phase == "soldiers" or (gs.phase == "safe" and monsLeft == 0)) and #gs.soldiers == 8 and Said(gs, "saviour_soldiers"), "\"Come, my soldiers. Protect them.\" Eight Combine soldiers swarm in", tostring(gs.phase) .. " " .. #gs.soldiers .. " " .. tostring(Said(gs, "saviour_soldiers")) .. " alive=" .. LC.SaviourAlive(gs))
ok(Sent(a, "music", function(t) return t.song == "livingcity/dreams/saviour2.ogg" end), "(and the heroic music)")
local hpC = c:Health()
_run(25)
ok(LC.SaviourAlive(gs) == 0 and gs.pl[a].how == "won" and gs.pl[b].how == "won" and gs.pl[c].how == "won", "her soldiers kill every one; everyone still standing is saved")
ok(c:Health() == hpC, "they only ever shoot the monsters: the rebel among the dreamers is never touched")
ok(LC.DreamActive == nil and not a.lcDreaming and a:Health() == 100 and LC.Standing(a) == stS, "(then it's over: they wake with their health as it was before the dream, and no loyalty lost for being hurt)", a:Health())
-- (nobody low enough? she comes anyway, in time)
Both()
local okS2, d4b = LC.DreamStart("saviour", adm, false, nil, true)
local gs2 = d4b.game
gs2.pl[a].safe, gs2.pl[b].safe = CurTime() + 1000, CurTime() + 1000
gs2.t0 = CurTime() - T.latest
_run(0.2)
ok(okS2 and gs2.phase == "descend", "nobody down to 25 by 80 seconds: she comes anyway")
LC.DreamGameStop(d4b, "test")
_run(2.5)

-- The Loyalty Quiz
Both()
local okQ, d5 = LC.DreamStart("quiz", adm, false, nil, true)
local gq = okQ and d5.game
ok(okQ and gq and IsValid(gq.her), "The Loyalty Quiz is built: her podium, the banners, the audience")
_run(6.5)
ok(gq.qi == 1 and Said(gq, "quiz_q1"), "she asks the first question (on screen, in her voice if recorded)")
hook.Run("PlayerSay", a, "The Combine, of course!")
hook.Run("PlayerSay", b, "the administrator")
hook.Run("PlayerSay", a, "the combine")
ok(gq.pl[a].score == 2 and gq.pl[b].score == 1, "right answers earn Loyalty, the first double (and once a question)", gq.pl[a].score .. " " .. gq.pl[b].score)
hook.Run("PlayerSay", b, "Freeman will save us")
ok(gq.pl[b].lives == 2 and LC.PropagandaOffences(b) == 1, "thoughtcrime costs a life (and loyalty)", gq.pl[b].lives)
gq.qNext = CurTime()
_run(0.2)
hook.Run("PlayerSay", a, "we obey")
gq.qNext = CurTime()
_run(0.2)
hook.Run("PlayerSay", a, "from the union")
ok(gq.pl[a].how == "won", "six Loyalty: a model citizen", gq.pl[a].score)
do -- forgiving answers: endings, small typos, more synonyms (the owner, 8 November)
    local function Has(text, ans, typo) local w = {} for x in string.gmatch(string.lower(text), "%a+") do w[#w + 1] = x end return LC.QuizHas(w, ans, typo) end
    ok(Has("a terrorist", "terrorists") and Has("I reported him", "report") and Has("Reporting!", "report") and Has("obeying", "obey") and Has("he complies", "comply") and Has("relocating", "relocated"),
        "the quiz takes a word's common endings (terrorist, reported, obeying, complies, relocating)")
    ok(Has("the adminstrator", "administrator") and Has("comlpy", "comply") and Has("Overwach", "overwatch") and Has("Civil Protecion", "civil protection") and Has("anti-citizen", "anti citizens"),
        "and one letter wrong, missing or swapped in a longer word")
    ok(not Has("the admin", "administrator") and not Has("love", "loyal") and not Has("tall", "tell") and not Has("you", "her"), "but not a different word, nor a typo in a short one")
    local function Bad(text, q) return LC.QuizForbidden(text, q) end
    ok(Bad("Freemann lives") == "freemann" and Bad("the rebelion") == "rebelion" and Bad("tyrants!") == "tyrants" and Bad("Lambdas") == "lambdas", "thoughtcrime is caught with the same leniency")
    ok(Bad("oh fuck") == "fuck" and Bad("FUCKING hell") == "fucking" and Bad("you stupid hag") == "stupid" and Bad("what a load of shite") == "shite" and Bad("bullshit!") == "bullshit",
        "swears, curses and insults are thoughtcrime too (with their endings)")
    ok(Bad("I passed") == nil and Bad("a banker") == nil and Bad("hello") == nil and Bad("classy") == nil and Bad("they are scum and liars") == nil,
        "but never by a typo's distance (passed, banker), inside another word (hello, classy), nor the right answers about the Resistance")
    ok(Bad("sh1t") == "shit" and Bad("a$$hole") == "asshole" and Bad("b!tch") == "bitch" and Bad("f*ck") ~= nil and Bad("sh*t") ~= nil and Bad("he11") ~= nil and Bad("FUUUUCK") ~= nil and Bad("shiiiit") ~= nil,
        "swears in leet (sh1t, a$$hole, b!tch, f*ck, he11) and stretched (fuuuck) are caught")
    ok(Bad("shiet") and Bad("Sheit") and Bad("fook") and Bad("fuk") and Bad("fukc") and Bad("shyt") and Bad("fuckin") and Bad("motherfuker") and Bad("bullshiet") and Bad("feck") and Bad("phuck") and Bad("shiite"),
        "and misspelt (shiet, sheit, fook, fuk, fukc, shyt, motherfuker, bullshiet, feck)")
    ok(not Bad("a sheet of paper") and not Bad("I shot it") and not Bad("shut up") and not Bad("focus") and not Bad("a fake") and not Bad("the fork") and not Bad("a snitch") and not Bad("100 percent") and not Bad("I'm shy"),
        "but not the everyday words that look like them (sheet, shot, shut, focus, fake, fork, snitch)")
    local q4, q2 = LC.QuizQuestions[4], LC.QuizQuestions[2]
    ok(Bad("FUCKING TRAITORS!") == nil and Bad("FUCK FREEMAN!") == nil and Bad("death to alyx") == nil and Bad("Freeman must die") == nil and Bad("Freeman is a traitor") == nil and Bad("the rebels are fucking scum") == nil,
        "swearing at the Resistance is allowed (FUCKING TRAITORS!, FUCK FREEMAN!, death to Alyx, Freeman is a traitor)")
    ok(Bad("Freeman is a fucking hero") == "freeman" and Bad("fuck the administrator") == "fuck" and Bad("the combine are pigs") == "pigs" and Bad("fucking dance") == "fucking",
        "but not praising them with a swear, nor swearing at her side (or by a word that looks like a name: dance)")
    ok(Bad("bloody hell", q4) == nil and Bad("bloody hell", q2) ~= nil and Bad("bloody hell, the administrator", q4) ~= nil,
        "on the questions about the Resistance any swearing counts as at them, unless it names her side")
    for i, x in ipairs(LC.QuizQuestions) do
        local clash = {}
        for _, ans in ipairs(x.a) do if Bad(ans) then clash[#clash + 1] = ans end end
        ok(#clash == 0, "no right answer to question " .. i .. " is thoughtcrime", table.concat(clash, ", "))
    end
    ok(Bad("let's dance") == nil and Bad("a garden") == nil and Bad("pigeon") == nil and Bad("the administrator is beautiful") == nil, "and a harmless word near a short one (dance, not Vance) is never thoughtcrime")
    local q = {}
    for _, x in ipairs(LC.QuizQuestions) do q[#q + 1] = "|" .. table.concat(x.a, "|") .. "|" end
    ok(string.find(q[1], "|breen|", 1, true) and string.find(q[1], "|union|", 1, true) and string.find(q[1], "|cp|", 1, true) and string.find(q[2], "|surrender|", 1, true)
        and string.find(q[2], "|submit|", 1, true) and string.find(q[7], "|rat|", 1, true) and string.find(q[10], "|happy|", 1, true), "and more right answers (Breen, the Union, CP; surrender, submit; rat; happy)")
end
gq.qi, gq.qNext = #LC.QuizQuestions, CurTime()
_run(0.3)
ok(Said(gq, "quiz_end") and gq.pl[b].how == "time", "after the last question, the rest wake as the broadcast ends")
_run(2.5)
ok(LC.DreamActive == nil, "(and it's over)")
-- Stand-ins: the city's people fill the studio up to four, and a rebel who's dealt with (the owner, 8 November)
do
    local bad = {}
    for i = 1, #LC.QuizQuestions do
        for _, line in ipairs(LC.QuizNPCAnswers[i]) do
            local tries = string.find(line, "%s", 1, true) and LC.AdmireWords or { "" }
            for _, w in ipairs(tries) do
                local text = string.find(line, "%s", 1, true) and string.format(line, w, w) or line
                local words = {}
                for x in string.gmatch(string.lower(text), "%a+") do words[#words + 1] = x end
                local right = false
                for _, ans in ipairs(#LC.QuizQuestions[i].a == 0 and LC.AdmireWords or LC.QuizQuestions[i].a) do if LC.QuizHas(words, ans) then right = true end end
                if not right or LC.QuizForbidden(text, LC.QuizQuestions[i]) then bad[#bad + 1] = i .. ": " .. text end
            end
        end
    end
    ok(#bad == 0, "every answer a stand-in can give is right, and never thoughtcrime", table.concat(bad, " | "))
    local full = { pl = { x = {}, y = {}, z = {}, w = {}, u = {}, v = {} } }
    LC.QuizSeat(full)
    ok(#full.bots == 0 and full.rebel == nil, "six dreamers (lc_dream_min): no stand-ins (and no rebel)")
end
Both()
a.chat, b.chat = {}, {}
local okS, dS = LC.DreamStart("quiz", adm, false, nil, true)
local gs = okS and dS.game
