-- Ten more propaganda dreams (sv_livingcity_propagandamore.lua)
function PropagandaMoreTests()
section("Shared dreams: ten more propaganda dreams (harvest, shift, spy, newsreel, hate, mass games, guidance, scrap, flowers, duck and cover)")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0) -- (the older tests: the Administrator picks freely, and the city doesn't pick: DreamCrowdTests has the rules)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(162000, -162000, 0), Vector(222000, -222000, 0)
local adm = newPlayer("PMAdmin", "admin")
local a = newPlayer("PMA", "citizen")
local b = newPlayer("PMB", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Both() Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0)) a.crouch, b.crouch, a.keys, b.keys = nil, nil, nil, nil end
local function Said(g, cue) for _, c in ipairs(g.said or {}) do if c == cue then return true end end return false end
local function Start(id)
    Both()
    local okS, d = LC.DreamStart(id, adm, false, nil, true)
    local g = okS and d.game
    _run(0.1)
    if g then g.pl[a].safe, g.pl[b].safe = 0, 0 end
    return g, d
end
local function Stop(d) LC.DreamGameStop(d, "test") _run(2.5) end
local function Duck(p) p.crouch = nil _run(0.1) p.crouch = true _run(0.3) end
local function Jump(p) p.keys = nil _run(0.1) p.keys = { [IN_JUMP] = true } _run(0.1) p.keys = nil end
local function Sent(p, k, test)
    for _, m in ipairs(net.sent) do
        local t = m.data[1]
        if m.name == "lc_dreamgame" and (m.to == p or (type(m.to) == "table" and table.HasValue(m.to, p))) and type(t) == "table" and t.k == k and (not test or test(t)) then return t end
    end
    return nil
end
player.GetAll = function() return { adm, a, b } end
local dp = LC.AddPoint(DREAM, 0, "dream")

-- on her tablet under Happy, as propaganda; music and voices
local found = {}
for _, e in ipairs(LC.DreamOffice().groups[1].endings) do if e.game and e.propaganda then found[e.id] = e.name end end
local all = true
for _, id in ipairs(LC.PropagandaMore) do if not (found[id] and string.find(found[id], "^Propaganda: ")) then all = false end end
ok(all and #LC.PropagandaMore == 12 and found.battleline == "Propaganda: The Battle Line" and found.ravenholm == "Propaganda: Ravenholm" and found.duck == "Propaganda: Duck and Cover" and found.hate == "Propaganda: Two Minutes of Hate", "all ten are on her tablet, under Happy, as Propaganda")
local MEDIA = { "sound/livingcity/dreams/harvest1.mp3", "sound/livingcity/dreams/propaganda1.ogg" }
for _, f in ipairs(MEDIA) do _files[f] = "x" end
ok(LC.PropagandaSong({ "harvest", "propaganda" }) == "livingcity/dreams/harvest1.mp3" and LC.PropagandaSong({ "duck", "propaganda" }) == "livingcity/dreams/propaganda1.ogg",
    "music: the dream's codeword, or propaganda for any of them")
ok(LC.PropagandaCueWho.duck_siren == "Sunny the Scanner" and LC.PropagandaCues.newsreel_hello ~= nil, "each line has its speaker (Sunny the Scanner, and the Administrator for the rest)")
ok(LC.PropagandaCueWho.shift_hello == "The Administrator" and LC.PropagandaCueWho.spy_hello == "The Administrator" and LC.PropagandaCueWho.newsreel_hello == "The Administrator" and LC.PropagandaCueWho.hate_hello == "The Administrator" and LC.PropagandaCueWho.massgames_flip == "The Administrator", "the Foreman, the Loudspeaker, the Narrator, the Screen and the Conductor are all her now (the owner, 8 November)")
ok(LC.PropagandaCommas(1234567) == "1,234,567" and LC.HarvestPercent(0) == 100 and LC.HarvestPercent(3) > 600, "(the quota board's absurd numbers)")

-- Record Harvest
local st0 = LC.Standing(a)
local g, d = Start("harvest")
ok(g and #g.crates == 8 and IsValid(g.her) and g.depotX, "Record Harvest is built: the field, the crates, the depot, her on her pedestal")
ok(g.boards == 2, "the owner's RECORD HARVEST picture stands on a billboard at each side of the field (20 November)", tostring(g.boards))
local s = g.pl[a]
local function Take(i, rotten)
    for j, o in ipairs(g.crates) do if j ~= i then o.gone, o.pos = CurTime() + 1000, Vector(0, 0, -50000) end end -- (only this one anywhere near)
    local cr = g.crates[i]
    cr.rotten, cr.gone, cr.pos = rotten, nil, Vector(g.fieldX0 + 60, g.midY, g.top + 18)
    a:SetPos(cr.pos - Vector(0, 0, 18))
    _run(0.1)
end
Take(1, false)
ok(s.carrying and not s.carrying.rotten, "walking over a crate picks it up")
a:SetPos(Vector(g.depotX + 10, g.midY, g.top))
_run(0.1)
ok(s.given == 1 and g.tally == 1 and not s.carrying, "into the depot: the quota board climbs")
Take(2, true)
Duck(a)
ok(not s.carrying and LC.PropagandaOffences(a) == 0, "a spoiled crate: crouch to throw it away, no harm done")
a.crouch = nil
Take(3, true)
s.safe = 0
a:SetPos(Vector(g.depotX + 10, g.midY, g.top))
_run(0.1)
ok(s.lives == 2 and LC.PropagandaOffences(a) == 1 and g.tally == 1, "delivering spoiled grain is wrecking: a life, and an offence")
s.safe, s.given = 0, 4
Take(4, false)
a:SetPos(Vector(g.depotX + 10, g.midY, g.top))
_run(0.1)
ok(s.how == "won" and Said(g, "harvest_medal"), "five crates: she pins on the medal herself")
Stop(d)
ok(LC.Standing(a) == st0 - 3, "waking, the wrecking costs 3 loyalty points", LC.Standing(a) - st0)

-- The Union Shift
g, d = Start("shift")
s = g.pl[a]
ok(g and #g.stations == 12 and g.herBase ~= nil and g.foreman == nil, "The Union Shift is built: twelve work stations, and she watches the floor (no foreman)")
a:SetPos(g.stations[1])
Duck(a)
ok(s.pct == LC.ShiftStroke, "at a station, every crouch is a hammer blow", s.pct)
a:SetPos(g.stations[1] + Vector(0, 0, 0) + Vector(300, 0, 0))
if LC.ShiftAtStation(g, a) then a:SetPos(g.stations[1] + Vector(0, 400, 0)) end
Duck(a)
ok(s.pct == LC.ShiftStroke, "away from a station, nothing")
g.pl[b].lastStroke = CurTime() - LC.ShiftIdle - 1
_run(0.1)
ok(g.pl[b].lives == 2, "idle too long: she notices", g.pl[b].lives)
ok(Said(g, "shift_idle"), "and says so, in her voice if recorded")
a.crouch = nil
a:SetPos(g.stations[2])
s.pct, s.lastStroke = g.def.need - 5, CurTime()
local n0 = #g.ents
Duck(a)
ok(s.how == "won" and g.hero == a:Nick() and #g.ents == n0 + 1 and Said(g, "shift_hero"), "1400%: a Hero of Labour, and a giant portrait of the first")
Stop(d)

-- Careless Talk: a party game, everyone picks on their own, then the reveal
local function UseOn(p, n) p:SetPos(n.pos - Vector(100, 0, 64)) p.aim = Vector(1, 0, 0) p.keys = nil _run(0.1) p.keys = { [IN_USE] = true } _run(0.2) p.keys = nil end
g, d = Start("spy")
s = g.pl[a]
_run(8.2)
local spy = g.spyN
local same = 0
for _, n in ipairs(g.npcs) do if n.tbl == spy.tbl and n.man == spy.man and n.tint == spy.tint then same = same + 1 end end
ok(#g.npcs == 12 and g.phase == "pick" and g.round == 1 and spy and same == 1, "Careless Talk: round 1, twelve citizens, one spy nobody else looks like")
_run(LC.SpyClueAt[1] + 0.2)
ok(#g.clues == 1, "a clue is overheard")
local wrong, wi, si
for i, n in ipairs(g.npcs) do if n == spy then si = i elseif not wrong and n.tbl ~= spy.tbl then wrong, wi = n, i end end
UseOn(a, wrong)
ok(s.pick == wi and g.phase == "pick" and s.lives == 3, "E on someone is your pick: nothing happens yet", s.pick)
UseOn(a, spy)
ok(s.pick == si, "you can change your mind")
g.pl[b].pick = wi
ok(not Sent(b, "state", function(t) return t.big and string.find(t.big, "Your pick: " .. LC.SpyDescribe(spy), 1, true) end), "(nobody else sees your pick)")
g.at = CurTime()
_run(0.1)
ok(g.phase == "reveal" and s.score == 1 and s.lives == 3 and g.pl[b].lives == 2 and #g.results == 2 and Said(g, "spy_caught"),
    "time's up: the spy and everyone's pick revealed to all; right scores, a loyal citizen reported costs a life")
local z1 = spy.e:GetPos().z
_run(1)
ok(spy.e:GetModelScale() >= 5 and spy.e:GetPos().z > z1 + 50 and Sent(a, "state", function(t) return t.villains end), "unmasked, the spy swells to a red giant and floats off into the sky")
g.at = CurTime()
_run(0.1)
ok(g.phase == "pick" and g.round == 2 and g.kind == "salute" and not s.pick and #g.clues == 0 and spy.e:GetModelScale() == 1, "the next round: the salute (everyone their own size again) and a new spy")
g.pl[b].safe = 0
g.at = CurTime()
_run(0.1)
ok(g.pl[b].lives == 1, "reporting nobody costs a life too")
s.score, g.round, g.phase, g.at = g.def.need, LC.SpyRounds, "reveal", CurTime()
_run(0.1)
ok(s.how == "won", "found the spy in enough rounds by the last: a vigilant citizen")
Stop(d)

-- The Newsreel: everyone at once, each their own cue, then the reveal
g, d = Start("newsreel")
_run(8.2)
ok(g.phase == "roll" and g.take == 1 and g.pl[a].cue and g.pl[b].cue, "The Newsreel: the camera rolls and every dreamer is told what to do")
ok(hook.Run("PlayerSay", a, "*" .. g.pl[a].cue .. "s*") == "" and g.pl[a].did == g.pl[a].cue and not g.pl[a].score, "doing it in chat is kept for the cut (and stays in the dream)")
local other = ({ wave = "salute", salute = "cheer", cheer = "wave" })[g.pl[b].cue]
LC.PropagandaSay(b, other)
g.at = CurTime()
_run(0.1)
ok(g.phase == "cut" and g.pl[a].score == 1 and g.pl[b].lives == 2 and #g.results == 2, "cut: everyone's take shown; the right one scores, the wrong one costs a life")
g.pl[b].safe = 0
g.at = CurTime()
_run(0.1)
g.at = CurTime()
_run(0.1)
ok(g.pl[b].lives == 1, "doing nothing costs one too")
g.pl[a].score, g.take, g.phase, g.at = g.def.need, LC.NewsreelTakes, "cut", CurTime()
_run(0.1)
ok(g.pl[a].how == "won" and Said(g, "newsreel_end"), "enough good takes by the last: star of the screen")
Stop(d)

-- Two Minutes of Hate
g, d = Start("hate")
s = g.pl[a]
LC.PropagandaSay(a, "Traitor! Scum!")
LC.PropagandaSay(b, "traitor")
ok(IsValid(g.rebel) and g.rebel:GetModelScale() == 5, "a giant red rebel floats over the screen")
ok(s.score == 4 and g.pl[b].score == 1, "Two Minutes of Hate: jeers in chat, double for a word nobody has used yet", s.score)
LC.PropagandaSay(a, "but freeman is a hero")
