g.pl[b].lastJeer = CurTime() - LC.HateSilence - 1
_run(0.1)
ok(g.pl[b].lives == 2, "silence is noticed")
s.score = g.def.need - 1
LC.PropagandaSay(a, "coward")
ok(s.how == "won", "full Hatred wins")
Stop(d)

