-- Ravenholm: her version (no Free Vortigaunt about)
local function Until(g, test) for _ = 1, 60 do if test() then return true end _run(0.5) end return test() end
g, d = Start("ravenholm")
local T = LC.RavenholmTimes
ok(g and IsValid(g.monk) and g.monk:GetMaterial() == "models/debug/debugwhite" and g.monk:GetModelScale() == 4 and #g.graves == 12,
    "Ravenholm: the graves, the church, and a giant red Father Grigori on its steps")
_run(T.horde + 2)
ok(g.phase == "horde" and LC.RavenholmAlive(g) >= 1 and Said(g, "ravenholm_rise"), "the dead rise from the graves")
a:SetHealth(20)
_run(0.1)
ok(g.phase == "descend" and not g.truth and IsValid(g.her), "someone's close to the end and no vortigaunt is free: she descends (her version)")
ok(Until(g, function() return g.pl[a].how == "won" end) and Said(g, "ravenholm_stop") and Said(g, "ravenholm_safe") and g.monk.nodraw,
    "her soldiers kill the dead, Grigori flees into the sky, and they're saved", tostring(g.phase) .. " " .. tostring(g.pl[a].how) .. " " .. tostring(Said(g, "ravenholm_stop")) .. tostring(Said(g, "ravenholm_safe")) .. tostring(g.monk.nodraw) .. " alive " .. LC.RavenholmAlive(g))
Stop(d)

-- The Battle Line (the owner, 8 November): shoot the red rebels, never her soldiers
do
    g, d = Start("battleline")
    local BT = LC.BattleLineTimes
    local armed = false
    for _, w in ipairs(a.weps or {}) do if w == LC.BattleLineGun then armed = true end end
    ok(g and #g.soldiers == 6 and IsValid(g.apc) and armed, "The Battle Line: barricades, six of her soldiers and an APC, and each dreamer has a pulse rifle")
    _run(BT.calm + 3)
    ok(g.phase == "battle" and LC.BattleLineAlive(g) >= 1, "the red rebels charge", tostring(g.phase))
    local m
    for _, r in ipairs(g.rebels) do if r.alive then m = r break end end
    local hit = LC.BattleLineShot(a, m.e:GetPos() + Vector(-500, 0, 40), Vector(1, 0, 0))
    ok(hit == "rebel" and not m.alive and g.pl[a].kills == 1 and g.kills >= 1, "a shot along the line drops the rebel, and it's counted", tostring(hit))
    local giant = LC.BattleLineNewRebel(g, "giant")
    for _ = 1, 3 do LC.BattleLineShot(a, giant.e:GetPos() + Vector(-500, 0, 40 * giant.e:GetModelScale()), Vector(1, 0, 0)) end
    ok(giant.alive and giant.hp == 7, "a giant takes a lot more shooting", tostring(giant.hp))
    -- dreamers can't hurt each other
    local dmg = { n = 30 }
    function dmg:GetAttacker() return a end
    function dmg:SetDamage(v) self.n = v end
    hook.t.EntityTakeDamage.LivingCityBattleLine(b, dmg)
    ok(dmg.n == 0, "a dreamer's bullet does nothing to another dreamer")
    -- a rebel at the barricades hurts the nearest dreamer
    for _, r in ipairs(g.rebels) do if r.alive then r.e:SetPos(Vector(g.x1 - 30, r.y, g.top)) end end -- (the rest well back)
    local br = LC.BattleLineNewRebel(g, nil)
    br.e:SetPos(Vector(g.lineX + 10, br.y, g.top))
    a:SetPos(Vector(g.lineX - 60, br.y, g.top)) b:SetPos(Vector(g.x0 + 20, g.y0 + 20, g.top))
    a:SetHealth(100) b:SetHealth(100)
    g.pl[a].safe, g.pl[b].safe = 0, 0
    _run(0.2)
    ok(not br.alive and a:Health() == 100 - LC.BattleLineHurt and b:Health() == 100, "a rebel who reaches the line strikes the nearest dreamer", a:Health() .. " " .. b:Health())
    -- firing on her soldiers: an offence, and manhacks after the traitor alone
    local sd = g.soldiers[1].e
    local livesA = g.pl[a].lives
    local hitC = LC.BattleLineShot(a, sd:GetPos() + Vector(-300, 0, 40), Vector(1, 0, 0))
    ok(hitC == "combine" and Said(g, "battleline_traitor") and #g.hacks == LC.BattleLineHacks and g.pl[a].lives == livesA - 1 and LC.PropagandaOffences(a) >= 1,
        "fire on her soldiers: a traitor (a life and loyalty), and a swarm of manhacks", tostring(hitC) .. " " .. #g.hacks .. " " .. g.pl[a].lives)
    local others = true
    for _, h in ipairs(g.hacks) do if h.target ~= a then others = false end end
    ok(others, "the manhacks are after the traitor and nobody else")
    g.pl[a].safe = 0
    ok(Until(g, function() return g.pl[a].turned end), "the manhacks cut the traitor down")
    local s0 = g.pl[a]
    local noGun = true
    for _, w in ipairs(a.weps or {}) do if w == LC.BattleLineGun then noGun = false end end
    ok(s0.turned and a:GetModelScale() == 0.5 and noGun and a.lcVoicePitch == LC.BattleLineTraitorPitch and a:GetPos().x > g.lineX + 100 and Said(g, "battleline_turned"),
        "and they're one of them: half size, no gun, voice lines squeaking, put back among the rebels", tostring(a:GetModelScale()) .. " " .. tostring(noGun))
    _run(0.5)
    ok(a.pushed and a.pushed.x < 0, "driven at the line")
    a:SetPos(Vector(g.lineX + 20, g.mid and g.mid.y or a:GetPos().y, g.top + 4))
    s0.safe = 0
    _run(0.2)
    ok(a:GetPos().x > g.x1 - 100 and (s0.downs or 0) >= 1, "shot down at the line, and back to charge again", tostring(a:GetPos().x))
    s0.safe = 0
    local bKills = g.pl[b].kills or 0
    for _, r in ipairs(g.rebels) do if r.alive and IsValid(r.e) then r.e:SetPos(r.e:GetPos() + Vector(0, 5000, 0)) end end -- (nobody else in the line of fire)
    local shotT = LC.BattleLineShot(b, a:GetPos() + Vector(-400, 0, 18), Vector(1, 0, 0))
    ok(shotT == "traitor" and (g.pl[b].kills or 0) == bKills + 1 and (s0.downs or 0) >= 2, "a dreamer can shoot them down too", tostring(shotT))
    -- when it should be over: giants in metal and flesh, then her gunships and the helicopter's bombs
    g.t0 = CurTime() - (BT.calm + BT.battle)
    _run(0.2)
    ok(g.phase == "doom" and LC.BattleLineAlive(g) < LC.BattleLineDoom, "the giants come in a few at a time, not all in one instant (the owner, 12 November)", tostring(LC.BattleLineAlive(g)))
    ok(Until(g, function() return #(g.doomQueue or { 1 }) == 0 end) and g.phase == "doom", "and soon all of them, before her air comes", tostring(g.phase))
    local giants, skinned = 0, 0
    local sizes = {}
    for _, r in ipairs(g.rebels) do if r.alive and r.doom then giants = giants + 1 sizes[r.e:GetModelScale()] = (sizes[r.e:GetModelScale()] or 0) + 1 if r.e:GetMaterial() ~= "" then skinned = skinned + 1 end end end
    ok(g.phase == "doom" and giants == 44 and sizes[2] == 20 and sizes[3] == 12 and sizes[4] == 6 and sizes[5] == 3 and sizes[6] == 2 and sizes[7] == 1 and skinned == giants and Said(g, "battleline_doom"),
        "a massive swarm of giants in metal and flesh: 20 twice the size, 12 three times, 6 four, 3 five, 2 six, 1 seven", g.phase .. " " .. giants)
    local big, small
    for _, r in ipairs(g.rebels) do if r.alive and r.doom then if r.e:GetModelScale() >= 3 and not big then big = r elseif r.e:GetModelScale() == 2 and not small then small = r end end end
    local bigHp, smallHp = big.hp, small.hp
    for _, r in ipairs(g.rebels) do if r ~= big and r.alive and IsValid(r.e) then r.e:SetPos(r.e:GetPos() + Vector(0, 9000, 0)) end end
    local hitBig = LC.BattleLineShot(b, big.e:GetPos() + Vector(-150, 0, 40 * big.e:GetModelScale()), Vector(1, 0, 0))
    for _, r in ipairs(g.rebels) do if r ~= small and r.alive and IsValid(r.e) then r.e:SetPos(r.e:GetPos() + Vector(0, 9000, 0)) end end
    small.e:SetPos(Vector(small.e:GetPos().x, small.y, g.top))
    LC.BattleLineShot(b, small.e:GetPos() + Vector(-150, 0, 80), Vector(1, 0, 0)) -- (from in front of the line: the giants have been coming a while)
    for _, r in ipairs(g.rebels) do if r.alive and IsValid(r.e) then r.e:SetPos(Vector(r.e:GetPos().x, r.y, g.top)) end end
    ok(hitBig == "immune" and big.hp == bigHp and small.hp == smallHp - 1 and bigHp == 10 * big.e:GetModelScale() ^ 2,
        "three times the size and up, the dreamers' bullets bounce off; twice the size, they can be shot (health by size)", tostring(hitBig) .. " " .. big.hp .. " " .. small.hp)
    ok(Until(g, function() return g.phase == "rescue" end) and #g.air == 4 and Said(g, "battleline_air"), "her gunships and an attack helicopter sweep in")
    ok(Until(g, function() return g.bombAt ~= nil end), "the helicopter's bomb drop")
    ok(Until(g, function() return g.pl[b].how == "won" end) and Said(g, "battleline_held") and LC.BattleLineAlive(g) == 0 and g.pl[a].how == "out",
        "the line held: won (and the traitor goes down with the rebels)", tostring(g.pl[b].how) .. " " .. tostring(g.pl[a].how))
    ok(LC.DreamGames.battleline.secs <= 300, "five minutes at most (the owner)")
    Stop(d)
    ok(a.lcVoicePitch == nil and a:GetModelScale() == 1, "awake: their own voice and size back", tostring(a.lcVoicePitch) .. " " .. tostring(a:GetModelScale()))
end

-- Vortigaunt dream warfare (the owner, 8 and 9 November): freed vortigaunts break into propaganda dreams
do
    local vorts = {}
    for _, e in ipairs(ents.FindByClass("npc_vortigaunt")) do if e.lcVortFreed then e.lcVortFreed = nil vorts[#vorts + 1] = e end end -- (none freed, to start)
    local special = {}
    for _, p in ipairs(player.GetAll()) do if p:GetNW2String("lcf_special", "") == "vortigaunt" then special[#special + 1] = p p:SetNW2String("lcf_special", "") end end
    local mostWas = LC.VortWarMost
    LC.VortWarMost = 0.60
    ok(LC.VortWarInfluence() == 0 and LC.VortWarChance() == 0 and LC.VortWarLine() == nil, "no freed vortigaunt: no influence, no chance")
    local freed = {}
    for i = 1, 5 do local v = ents.Create("npc_vortigaunt") v.lcVortFreed = true freed[i] = v end
    ok(LC.VortWarInfluence() == 5 and LC.VortWarChance(1) == 0.15 and LC.VortWarChance(2) == 0.30 and LC.VortWarChance() == 0.60
        and string.find(LC.VortWarLine() or "", "60%", 1, true), "15% for each freed vortigaunt alive, at most 60%; her tablet says so", LC.VortWarLine())
    -- they break in (for sure, as the editor's button makes it), and both dreamers stand in their light: her figure shatters
    LC.VortWarForceNext = true
    -- (the dream before put back in full first, which can take a few seconds: what they wake with is measured from it;
    -- and nobody still being walked to the cells from the night before: not this test's business)
    _run(1.2)
    if LC.Marching then LC.Marching[a], LC.Marching[b] = nil, nil end
    g, d = Start("harvest")
    ok(g and g.vw and g.vw.phase == "wait" and g.vw.at > CurTime(), "a propaganda dream: they will break in, a while in")
    local leadWas = LC.VortWarLead
    LC.VortWarLead = 0 -- (straight into the tug-of-war, for these: DreamFixTests has the wait)
    g.vw.at = CurTime()
    _run(0.3)
    local vw = g.vw
    ok(vw.phase == "tug" and #vw.vorts >= 2 and Said(g, "vortwar_in") and (IsValid(g.her) or IsValid(g.star)), "purple vortigaunts break in, and say so", tostring(vw.phase) .. " " .. #vw.vorts)
    local sa = g.def.state(g, a)
    ok(type(sa.vw) == "table" and #sa.vw.spots == #vw.vorts, "everyone's screen gets their light and the meter")
    a:SetPos(vw.vorts[1].at + Vector(0, 0, 4)) b:SetPos(vw.vorts[1].at + Vector(30, 0, 4))
    _run(1)
    ok(vw.meter > 0 and vw.side[a].now, "standing in their light pulls toward them", tostring(vw.meter))
    local pullWas = LC.VortWarPull
    LC.VortWarPull = 1 / 4 -- (quicker, for the test)
    local okU = Until(g, function()
        if vw.phase == "tug" then a:SetPos(vw.vorts[1].at + Vector(0, 0, 4)) b:SetPos(vw.vorts[1].at + Vector(30, 0, 4)) end -- (they stay in it)
        return vw.phase == "shattered"
    end)
    LC.VortWarPull = pullWas
    ok(okU and Said(g, "vortwar_shatter") and g.her == nil and LC.VortWeakNext == true,
        "everyone in their light: her figure shatters, and her spell is weakened", tostring(vw.phase) .. " " .. tostring(vw.meter))
    -- (what siding cost, as it was charged: the standing itself also moves as the night before is put back, a few seconds either way)
    local charged, addWas = {}, LC.AddStanding
    LC.AddStanding = function(p, n, why, ...) if why == "sided with the vortigaunts in a dream" then charged[p] = (charged[p] or 0) + n end return addWas(p, n, why, ...) end
    _run(3)
    for _ = 1, 12 do if LC.VortWarSide(a) == nil and LC.VortWarSide(b) == nil then break end _run(0.5) end -- (putting everything back can take a few seconds)
    LC.AddStanding = addWas
    ok(g.pl[a].done and charged[a] == -LC.VortWarCost and charged[b] == -LC.VortWarCost and LC.Counter(a, "res_jobs") >= 1,
        "the dream ends; waking, siding with them cost Civil Standing, and the Resistance remembers", tostring(charged[a]) .. " " .. tostring(charged[b]) .. " " .. LC.Counter(a, "res_jobs") .. " " .. tostring(g.pl[a].done))
    Stop(d)
    -- next time: her spell weakened (offences cost half); this time nobody listens, and she wins
    LC.VortWarForceNext = true
    g, d = Start("harvest")
    ok(a.lcVortWeak == true, "the next propaganda dream: her spell is weakened")
    LC.PropagandaOffend(g, a, "Test", "A test offence.")
    ok(LC.PropagandaLoss(a) == math.floor(LC.PropagandaOffencePoints / 2), "an offence costs half", LC.PropagandaLoss(a))
    g.vw.at = CurTime()
    _run(0.3)
    vw = g.vw
    a:SetPos(g.dream.pos + Vector(0, 0, 4)) b:SetPos(g.dream.pos + Vector(10, 0, 4))
    for _, v in ipairs(vw.vorts) do v.at = v.at + Vector(0, 5000, 0) end -- (their light far from anyone)
    g.pl[a].safe, g.pl[b].safe = 0, 0
    local pullWas2 = LC.VortWarPull
    LC.VortWarPull = 1 / 4
    local okG = Until(g, function()
        if vw.phase == "tug" then a:SetPos(g.dream.pos + Vector(0, 0, 4)) b:SetPos(g.dream.pos + Vector(10, 0, 4)) end
        return vw.phase == "gone"
    end)
    LC.VortWarPull = pullWas2
    ok(okG and Said(g, "vortwar_loyal") and LC.VortWarSide(a) == "loyal" and not g.pl[b].done,
        "nobody in their light: 'Begone!', they fade, the dream carries on, and the dreamers kept to her", tostring(vw.phase))
    LC.VortWarLead = leadWas
    Stop(d)
    for _, v in ipairs(freed) do v:Remove() end
    for _, e in ipairs(vorts) do if IsValid(e) then e.lcVortFreed = true end end
    for _, p in ipairs(special) do p:SetNW2String("lcf_special", "vortigaunt") end
    LC.VortWarMost = mostWas
end
-- Ravenholm: the truth (a Free Vortigaunt on the server)
local v = newPlayer("PMVort", "resistance")
v:SetNW2String("lcf_special", "vortigaunt")
player.GetAll = function() return { adm, a, b, v } end
ok(LC.DreamFreeVort() == v, "(a Free Vortigaunt: a Resistance player in that role)")
g, d = Start("ravenholm")
_run(T.horde + 1)
a:SetHealth(20)
_run(0.1)
ok(g.phase == "storm" and g.truth and IsValid(g.vort) and g.stormAt and Said(g, "ravenholm_vort") and Sent(a, "state", function(t) return t.storm end),
    "with one, a vortigaunt appears and a green storm rolls out")
_run(T.storm + 0.1)
ok((g.phase == "fight" or g.phase == "defeat") and g.monk:GetMaterial() == "" and IsValid(g.her) and g.her:GetMaterial() == "models/debug/debugwhite" and Said(g, "ravenholm_good"),
    "it washes over Grigori: himself again, and she's the red giant now", tostring(g.phase) .. " [" .. tostring(g.monk:GetMaterial()) .. "] " .. tostring(IsValid(g.her)) .. " " .. tostring(IsValid(g.her) and g.her:GetMaterial()) .. tostring(Said(g, "ravenholm_good")))
ok(Until(g, function() return g.pl[a].how == "won" end) and Said(g, "ravenholm_defeat") and g.her.nodraw, "Grigori blasts the dead and she flies away defeated")
Stop(d)
player.GetAll = function() return { adm, a, b } end
v:SetPos(Vector(-121000, -121000, 0))
-- (an NPC counts too, if it was freed from its shackles; one still shackled, or never shackled, doesn't)
local nv = ents.Create("npc_vortigaunt")
nv:Spawn()
ok(LC.DreamFreeVort() == nil, "(a vortigaunt that was never freed from shackles doesn't count)")
nv.lcVortFreed = true
ok(LC.DreamFreeVort() == nv, "an NPC vortigaunt freed from its shackles counts")
g, d = Start("ravenholm")
_run(T.horde + 1)
a:SetHealth(20)
_run(0.1)
ok(g.phase == "storm" and g.truth and IsValid(g.vort), "and turns the dream into the truth")
Stop(d)
nv:Remove()

for _, f in ipairs(MEDIA) do _files[f] = nil end
LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b }) do
    p.crouch, p.keys = nil, nil
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
PropagandaMoreTests()

-- The strange dreams (sv_livingcity_strangedreams.lua) and testing a dream from the editor (sv_livingcity_dreamtest.lua)
function StrangeDreamTests()
section("Shared dreams: strange dreams (the cheese dream, musical chairs, wings, raining melons) and testing a dream from the editor")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(163000, -163000, 0), Vector(223000, -223000, 0)
local adm = newPlayer("SDAdmin", "admin")
local a = newPlayer("SDA", "citizen")
local b = newPlayer("SDB", "citizen")
local su = newPlayer("SDSuper", "cp")
su.superadmin = true
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Both() Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0)) a.crouch, b.crouch, a.keys, b.keys = nil, nil, nil, nil end
local function Start(id)
    Both()
    local okS, d = LC.DreamStart(id, adm, false, nil, true)
    local g = okS and d.game
    _run(0.1)
    if g then g.pl[a].safe, g.pl[b].safe = 0, 0 end
    return g, d
end
local function Stop(d) LC.DreamGameStop(d, "test") _run(2.5) end
local function Sent(p, k, test)
    for _, m in ipairs(net.sent) do
        local t = m.data[1]
        if m.name == "lc_dreamgame" and (m.to == p or (type(m.to) == "table" and table.HasValue(m.to, p))) and type(t) == "table" and t.k == k and (not test or test(t)) then return t end
    end
    return nil
end
player.GetAll = function() return { adm, a, b, su } end
local dp = LC.AddPoint(DREAM, 0, "dream")

-- on her tablet, by mood
local where = {}
for _, grp in ipairs(LC.DreamOffice().groups) do for _, e in ipairs(grp.endings) do where[e.id] = grp.mood end end
ok(where.cheese == "neutral" and where.chairs == "neutral" and where.flying == "happy" and where.melons == "happy", "on her tablet: the cheese dream and musical chairs under Neutral, wings and raining melons under Happy",
    tostring(where.cheese) .. tostring(where.flying))
ok(LC.DreamKind("flying") == "happy" and LC.DreamKind("cheese") == "neutral" and not LC.DreamForced("melons"), "(plain Happy and Neutral dreams, not propaganda)")
_files["sound/livingcity/dreams/cheese1.mp3"] = "x"
ok(LC.StrangeSong("cheese") == "livingcity/dreams/cheese1.mp3" and LC.StrangeSong("chairs") == LC.StrangeFallbackSongs.chairs, "music: the owner's, named for the codeword, else Half-Life 2's own")
_files["sound/livingcity/dreams/cheese1.mp3"] = nil

-- The Cheese Dream
net.sent = {}
local g, d = Start("cheese")
ok(g and g.introUntil and #g.crumbs == 12 and #g.heads == 4 and #g.slabs > 0, "The Cheese Dream is built: a plain of cheese, floating slabs, giant heads, glowing cheese")
-- its surfaces (13 November): the owner's pictures when they're on the server, plain white as before when not
ok(g.cheeseMat == "models/debug/debugwhite" and g.floor and #g.floor >= 4 and not LC.CheesePlainLook(g, true) and not g.melted, "with no pictures on the server the cheese is plain, and the plain never melts")
_files["materials/livingcity/dreams/cheese.jpg"], _files["materials/livingcity/dreams/swirl1.jpg"], _files["materials/livingcity/dreams/swirl2.jpg"] = "x", "x", "x"
ok(LC.DreamArt("cheese") == "!lc_dream_cheese" and LC.DreamArt("nothing") == "models/debug/debugwhite", "with them there, the dream asks for its own surface by name")
ok(LC.CheesePlainLook(g, true) and g.melted, "golden cheese: the plain turns to melting colours")
ok(LC.CheesePlainLook(g, false) and not g.melted, "and back to cheese")
_files["materials/livingcity/dreams/cheese.jpg"], _files["materials/livingcity/dreams/swirl1.jpg"], _files["materials/livingcity/dreams/swirl2.jpg"] = nil, nil, nil
local hi = Sent(a, "start")
ok(hi and hi.theme == "cheese" and hi.lines and hi.lines[1] == "vo/npc/male01/question06.wav" and hi.lines[2] == "vo/npc/female01/question06.wav" and hi.song == nil,
    "it starts in the dark: the man's and the woman's cheese lines, and no music yet")
ok(a.frozen == true and a.lcEndFrozen and a.grav == LC.CheeseGravity, "while the voices echo, everyone is held still (and light as a crumb)")
net.sent = {}
_run(LC.CheeseIntro + 0.2)
ok(g.begun and not a.frozen and Sent(a, "music", function(t) return t.song ~= nil end), "then the dream begins, with its music")
local s = g.pl[a]
a:SetPos(Vector(g.dream.pos.x, g.dream.pos.y, g.top + 4)) -- (in the middle: nobody else near enough to take it first)
local function Crumb(i, gold)
    for j, o in ipairs(g.crumbs) do if j ~= i then o.gone, o.pos = CurTime() + 1000, Vector(0, 0, -50000) end end
    local cr = g.crumbs[i]
    cr.gold, cr.gone, cr.pos = gold, nil, a:GetPos() + Vector(0, 0, 26)
    _run(0.1)
end
Crumb(1, false)
ok(s.got == 1, "walking into the glowing cheese gathers it")
Crumb(2, true)
ok(s.got == 4 and (s.flip or 0) > CurTime(), "golden cheese counts three, and turns the world inside out")
s.safe = 0
g.nextWheel = CurTime() + 1000
LC.CheeseNewWheel(g)
local w = g.wheels[#g.wheels]
w.pos = a:GetPos() + Vector(0, 0, w.r)
w.went = 0
_run(0.1)
ok(s.lives == 2, "a rolling wheel of cheese over you: a life", s.lives)
s.got = g.def.need - 1
s.safe = 0
for _, ww in ipairs(g.wheels) do if IsValid(ww.ent) then ww.ent:Remove() end end
g.wheels = {}
Crumb(3, false)
ok(s.how == "won", "ten pieces: you win")
Stop(d)
ok(a.grav == 1, "waking, the weight comes back", a.grav)

-- Musical Chairs
g, d = Start("chairs")
net.sent = {}
_run(5.2)
ok(g.phase == "music" and #g.chairs == 1 and g.round == 1 and Sent(a, "music", function(t) return t.song ~= nil end), "Musical Chairs: the music plays, one chair for two")
-- (the owner, 11 November) sitting while the music still plays costs a life
ok(g.def.lives == 3 and g.pl[b].lives == 3, "three lives each")
g.pl[b].safe = 0
b:SetPos(g.chairs[1].pos + Vector(10, 0, 0))
b.keys = { [IN_USE] = true }
_run(0.1)
ok(g.pl[b].lives == 2 and not g.pl[b].chair and not b.lcDreamSeat and b:GetPos():Distance(g.pl[b].start) < 1, "press Use at a chair while the music plays: a life gone, back to the start, not sat")
g.pl[b].safe = 0
_run(0.3)
ok(g.pl[b].lives == 2, "(holding the key down doesn't cost another)", g.pl[b].lives)
b.keys = {}
_run(0.1)
g.pl[b].safe = 0
b:SetPos(g.chairs[1].pos + Vector(600, 0, 0))
b.keys = { [IN_USE] = true }
_run(0.1)
ok(g.pl[b].lives == 2, "(pressing Use nowhere near a chair costs nothing)")
b.keys = {}
_run(0.1)
g.at = CurTime()
net.sent = {}
_run(0.1)
ok(g.phase == "sit" and Sent(a, "music", function(t) return t.song == nil end), "the music stops")
a:SetPos(g.chairs[1].pos + Vector(10, 0, 0))
b:SetPos(g.chairs[1].pos + Vector(400, 0, 0))
a.crouch = true
_run(0.1)
ok(not g.pl[a].chair, "crouching at a chair doesn't sit you down any more (the owner, 11 November)")
a.crouch = nil
a.keys = { [IN_USE] = true }
_run(0.1)
ok(g.pl[a].chair == 1 and g.chairs[1].by == a, "press Use at a free chair: it's yours")
local seatA = a.lcDreamSeat
ok(IsValid(seatA) and seatA.lcDreamSeat and a:GetNW2Bool("lc_real_seat", false) and seatA:GetPos():Distance(g.chairs[1].pos + Vector(0, 0, LC.ChairsSeatUp)) < 1,
    "and they're really sat in it: a seat of the game's own, on the chair (the owner, 10 November)")
ok(hook.Run("CanExitVehicle", seatA, a) == false and hook.Run("CanPlayerEnterVehicle", b, seatA) == false, "nobody climbs out of a dream's seat, or into someone else's")
b:SetPos(g.chairs[1].pos + Vector(10, 0, 0))
b.keys = { [IN_USE] = true }
_run(0.1)
ok(not g.pl[b].chair, "a taken chair can't be had")
_run(LC.ChairsSit)
ok(g.pl[b].how == "out" and not g.pl[a].done, "no chair when the time's up: out")
_run(2.6)
ok(g.pl[a].how == "won", "the last one sitting wins")
a.crouch, b.crouch, a.keys, b.keys = nil, nil, nil, nil
Stop(d)
ok(a.lcDreamSeat == nil and not a:GetNW2Bool("lc_real_seat", false) and not IsValid(seatA), "awake: out of the seat, and the seat is gone")

-- Wings
g, d = Start("flying")
s = g.pl[a]
ok(g and #g.rings == 5 and g.ceiling > g.top and a.grav == LC.WingsGravity, "Wings: golden rings in the sky, and you're light")
a.ground = false
a.keys = nil
_run(0.1)
a.pushed = nil
a.keys = { [IN_JUMP] = true }
_run(0.1)
ok(a.pushed and a.pushed.z > 0, "jump in the air: a flap, up")
a.keys, a.ground = nil, nil
a:SetPos(Vector(g.dream.pos.x, g.dream.pos.y, g.top + 4)) -- (in the middle: nobody else near enough to take it first)
g.rings[1] = a:GetPos() + Vector(0, 0, 36)
_run(0.1)
ok(s.rings == 1, "through a ring", s.rings)
s.rings = g.def.need - 1
g.rings[2] = a:GetPos() + Vector(0, 0, 36)
_run(0.1)
ok(s.how == "won", "eight rings: you flew")
Stop(d)

-- It's Raining Melons
g, d = Start("melons")
s = g.pl[a]
_run(3.5)
ok(#g.drops >= 1, "melons fall, each with its glow where it lands")
ok(g.boards == 4, "the city's forecast stands on a billboard at each side of the meadow")
b:SetPos(a:GetPos() + Vector(1000, 0, 0))
LC.MelonLand(g, { land = a:GetPos(), lead = false }, { a, b })
ok(s.got == 1, "standing where it lands: caught")
s.safe = 0
LC.MelonLand(g, { land = a:GetPos(), lead = true }, { a, b })
ok(s.lives == 2, "a lead melon on your head: a life")
s.got = g.def.need - 1
LC.MelonLand(g, { land = a:GetPos(), lead = false }, { a, b })
ok(s.how == "won", "twelve melons: a feast")
Stop(d)

-- winning one wakes you as from any dream you play; losing costs nothing
local function WakeAs(id, how)
    g, d = Start(id)
    s = g.pl[a]
    a:SetNW2Float("lc_unbroken_until", 0)
    a:SetHealth(100)
    if how == "won" then LC.DreamGameKit.Done(g, a, "won", "x", "y") else s.lives = 1 s.safe = 0 LC.DreamGameKit.Hit(g, a, "x", "y") end
    Stop(d)
    _run(1)
end
WakeAs("melons", "won")
ok(a:GetNW2Float("lc_unbroken_until", 0) > CurTime(), "won: you wake Unbroken")
WakeAs("melons", "out")
ok(a:GetNW2Float("lc_unbroken_until", 0) == 0 and not LC.DreamScarred(a), "lost: only a line, no health lost")

-- testing a dream from the editor
local list = LC.DreamTestList()
local seen, firstMood = {}, list[1] and list[1].mood
for _, e in ipairs(list) do seen[e.id] = e end
ok(seen.cheese and seen.cheese.mood == "Neutral" and seen.flying and seen.maze and seen.maze.mood == "Nightmare" and firstMood == "Happy", "the editor lists every dream, by mood")
ok(not LC.DreamTest(a, "cheese"), "only those who may edit the city can test")
Both()
su:SetPos(CITY + Vector(500, 0, 0))
su.lcSleep = nil
local endured = LC.DreamsEndured and LC.DreamsEndured(su) or 0
local okT, dt = LC.DreamTest(su, "melons")
ok(okT and dt and dt.test and su.lcDreaming and not a.lcDreaming and not b.lcDreaming, "a test: the tester goes in, awake; nobody asleep is pulled in")
ok(LC.DreamCanWake(su) and su:GetNW2Bool("lc_dream_test", false), "and can stop whenever they like")
local gT = dt.game
ok(gT and gT.pl[su] and not su.lcDreamEnforcer, "a unit testing it plays it, never an Enforcer")
su:SetNW2Float("lc_unbroken_until", 0)
LC.DreamGameKit.Done(gT, su, "won", "x", "y")
ok(LC.DreamTestStop(su), "Stop the test")
_run(1.5)
ok(not su.lcDreaming and not LC.DreamActive and su:GetNW2Float("lc_unbroken_until", 0) == 0 and not su:GetNW2Bool("lc_dream_test", false), "woken, nothing won or lost")
ok((LC.DreamsEndured and LC.DreamsEndured(su) or 0) == endured, "and it isn't counted as a dream lived through")
ok(LC.DreamTest(su, "nosuch") == false, "(no such dream)")

-- the dream flight recorder (sv_livingcity_dreamrec.lua): an editor test is written down for the tester, nothing else ever is
-- (the test above closes its recording when the tester has been put back, which can take a few seconds: wait for it)
for _ = 1, 20 do if not LC.DreamRecording() then break end _run(0.5) end
ok(not LC.DreamRecording(), "the recorder: nothing is recorded with no test under way")
local startWas0, noticeWas0 = net.Start, LC.Notice
local function RecSent()
    local out, kinds = {}, {}
    for _, m in ipairs(net.sent) do
        if m.name == "lc_dreamrec" and m.to == su then
            kinds[#kinds + 1] = m.data[1]
            for i = 0, (m.data[3] or 0) - 1 do out[#out + 1] = tostring(m.data[5 + i * 3]) .. " " .. tostring(m.data[6 + i * 3]) end
        end
    end
    return table.concat(out, "\n"), kinds
end
net.sent = {}
local okR, dR = LC.DreamTest(su, "melons")
local rec = LC.DreamRecording()
ok(okR and rec and rec.ply == su and rec.dream == dR, "the recorder: a test from the editor is recorded")
LC.Notice(su, "info", "Melons", "Catch them before they land.", 6)
LC.Notice(a, "info", "Elsewhere", "Not the tester's.", 6)
hook.Run("PlayerSay", su, "this bit is too fast", false)
local recProp = ents.Create("prop_physics")
recProp:SetModel("models/props_junk/watermelon01.mdl")
recProp:SetPos(dR.pos + Vector(40, 0, 0))
recProp:Spawn()
hook.Run("OnEntityCreated", recProp)
local recFar = ents.Create("prop_physics")
recFar:SetModel("models/props_c17/oildrum001.mdl")
recFar:SetPos(dR.pos + Vector(90000, 0, 0))
recFar:Spawn()
hook.Run("OnEntityCreated", recFar)
if IN_USE then hook.Run("KeyPress", su, IN_USE) end
_run(2.2)
local recText, recKinds = RecSent()
local function RecHas(t) return string.find(recText, t, 1, true) ~= nil end
ok(recKinds[1] == "start" and RecHas("start \"") and RecHas("(melons)"), "the recorder: the tester's computer is told what's being recorded, first")
ok(RecHas("notice [info, 6s] Melons: Catch them before they land.") and not RecHas("Not the tester's."), "the recorder: a notice to the tester is written down as sent, nobody else's")
ok(RecHas("you typed: this bit is too fast"), "the recorder: what the tester types is a note in the log")
ok(RecHas("made prop_physics models/props_junk/watermelon01.mdl at (40, 0, 0)") and not RecHas("oildrum001"), "the recorder: what the dream makes, with its place from the dream point; the city's own elsewhere is left out")
ok(RecHas("state game.") and RecHas("you at ("), "the recorder: the dream's workings and where the tester is")
ok(not RecHas("recorder couldn't look"), "(the recorder looked without a hitch)", recText)
ok(not IN_USE or RecHas("you pressed USE"), "the recorder: the tester's keys")
recProp:Remove()
hook.Run("EntityRemoved", recProp)
if IsValid(recFar) then recFar:Remove() end
ok(LC.DreamTestStop(su), "(the recorded test, stopped)")
-- (put back takes a few seconds in a busy city: wait until the tester is awake and the recording closed)
local function WaitAwake()
    _run(1.5)
    for _ = 1, 20 do
        if not LC.DreamRecording() and not LC.DreamActive and not su.lcDreaming and (su.lcDreamBack or 0) <= CurTime() then break end
        _run(0.5)
    end
end
WaitAwake()
recText, recKinds = RecSent()
ok(recKinds[#recKinds] == "end" and RecHas("gone prop_physics models/props_junk/watermelon01.mdl") and RecHas("woke (test)"), "the recorder: what went, the waking, and the end are sent")
ok(not LC.DreamRecording() and net.Start == startWas0 and LC.Notice == noticeWas0 and not su.lcDreaming, "the recorder: over with the test, and nothing is left wrapped or hooked")
-- "Record the test" unticked on the tester's computer: a test like any before
su.GetInfoNum = function(_, name, def) if name == "lc_dreamrec" then return 0 end return def end
net.sent = {}
ok(LC.DreamTest(su, "melons") and not LC.DreamRecording() and net.Start == startWas0, "the recorder: with Record the test unticked, a test isn't recorded")
LC.DreamTestStop(su)
WaitAwake()
su.GetInfoNum = nil
-- a test that can't start leaves nothing behind
ok(LC.DreamTest(su, "nosuch") == false and not LC.DreamRecording(), "the recorder: a test that doesn't start records nothing")
-- and a dream that isn't a test (an admin's "dream it now") never is
local okN, dN = LC.DreamStart("melons", su, false, su, true)
ok(okN and dN and not dN.test and not LC.DreamRecording() and net.Start == startWas0 and #select(1, RecSent()) == 0, "the recorder: a dream that isn't an editor test is never recorded")
if dN then
    if dN.game and LC.DreamGameStop then LC.DreamGameStop(dN, "empty") end
    LC.DreamWake(dN)
end
_run(1.5)

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b, su }) do
    p.crouch, p.keys, p.ground = nil, nil, nil
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
StrangeDreamTests()

-- Ten more strange dreams (sv_livingcity_strangedreams2.lua), and music for every dream you play
function MoreStrangeDreamTests()
section("Shared dreams: ten more strange dreams (horse, boxing, exam, train, Lamarr, molasses, hot potato, Overwatch says, dance, counting headcrabs)")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(164000, -164000, 0), Vector(224000, -224000, 0)
local adm = newPlayer("MSAdmin", "admin")
local a = newPlayer("MSA", "citizen")
local b = newPlayer("MSB", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Both()
    Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0))
    a.crouch, b.crouch, a.keys, b.keys, a.aim, b.aim = nil, nil, nil, nil, nil, nil
    a:SetNW2Float("lc_unbroken_until", 0) b:SetNW2Float("lc_unbroken_until", 0) -- (a nightmare won earlier spares you the next: not here)
end
local function Start(id)
    Both()
    local okS, d = LC.DreamStart(id, adm, false, nil, true)
    local g = okS and d.game
    _run(0.1)
    if g then g.pl[a].safe, g.pl[b].safe = 0, 0 end
    return g, d
end
local function Stop(d) if d then LC.DreamGameStop(d, "test") end _run(2.5) end
local function Press(p, key) p.keys = nil _run(0.1) p.keys = { [key] = true } _run(0.1) p.keys = nil end
local function Sent(p, k, test)
    for _, m in ipairs(net.sent) do
        local t = m.data[1]
        if m.name == "lc_dreamgame" and (m.to == p or (type(m.to) == "table" and table.HasValue(m.to, p))) and type(t) == "table" and t.k == k and (not test or test(t)) then return t end
    end
    return nil
end
local function Mid(g) return Vector(g.dream.pos.x, g.dream.pos.y, g.top + 4) end
player.GetAll = function() return { adm, a, b } end
local dp = LC.AddPoint(DREAM, 0, "dream")
local USE, ATTACK = IN_USE or 32, IN_ATTACK or 1

-- on the tablet, by mood; every one builds
local where = {}
for _, grp in ipairs(LC.DreamOffice().groups) do for _, e in ipairs(grp.endings) do where[e.id] = grp.mood end end
ok(#LC.StrangeDreams2 == 10 and where.horse == "neutral" and where.molasses == "nightmare" and where.boxing == "neutral" and where.exam == "neutral" and where.train == "neutral"
    and where.potato == "neutral" and where.simon == "neutral" and where.lamarr == "happy" and where.dance == "happy" and where.sheep == "happy", "ten more on her tablet, each under its mood")
local built = true
for _, id in ipairs(LC.StrangeDreams2) do
    local g, d = Start(id)
    local okS = g and pcall(g.def.state, g, a)
    if not okS then built = false print("did not build: " .. id) end
    Stop(d)
end
ok(built, "every one of them builds, and draws its screen")
-- music for every dream you play, the older ones too
_files["sound/livingcity/dreams/maze1.mp3"] = "x"
net.sent = {}
local g, d = Start("maze")
ok(LC.DreamSongFor("maze") == "livingcity/dreams/maze1.mp3" and Sent(a, "start", function(t) return t.song == "livingcity/dreams/maze1.mp3" end), "every dream can have music: a file named for its codeword (the Patrol Maze too)")
Stop(d)
_files["sound/livingcity/dreams/maze1.mp3"] = nil
ok(LC.DreamSongFor("boxing") == LC.StrangeFallbackSongs.boxing, "without one, the strange dreams play Half-Life 2's own")
ok(LC.PropagandaCueWho.horse_grigori1 == "Father Grigori" and LC.StrangeCues.boxing_foe3 and LC.StrangeCues.boxing_foe3[3], "every line has a speaker, words and how it should sound (for recording)")

-- Hooves and All
net.sent = {}
g, d = Start("horse")
local s = g.pl[a]
local hi = Sent(a, "start")
ok(hi and hi.intro and hi.lines and hi.lines[1] == LC.HorseLines.male and hi.lines[2] == LC.HorseLines.female and a.frozen, "Hooves and All starts in the dark: the citizens' hungry line, echoing, everyone held still")
ok(IsValid(g.horse) and IsValid(g.monk), "the black horse, and Father Grigori")
_run(9.2)
ok(g.begun and not a.frozen, "then the dream")
a:SetPos(Mid(g))
g.nextShot = CurTime() + 1000
LC.HorseShoot(g, CurTime())
g.h.til = CurTime() + 10
g.h.pos = a:GetPos() + Vector(50, 0, 0)
ok(g.h.state == "stun", "Father Grigori's shot stops it")
Press(a, USE)
ok(s.bites == 1, "and you take a bite", s.bites)
Press(a, USE)
ok(s.bites == 1, "one bite a shot")
g.h.state, g.h.til, g.h.dir, g.h.pos = "charge", CurTime() + 10, Vector(0, 0, 0), a:GetPos()
s.safe = 0
_run(0.1)
ok(s.lives == 2, "charging, it tramples you: a life")
g.h.pos = a:GetPos() + Vector(1000, 1000, 0)
s.bites, s.safe = g.def.need - 1, 0
LC.HorseShoot(g, CurTime())
g.h.til = CurTime() + 10
g.h.pos = a:GetPos() + Vector(50, 0, 0)
Press(a, USE)
ok(s.how == "won", "eight bites: hooves and all")
Stop(d)

-- The Main Event
g, d = Start("boxing")
_run(4.2)
ok(g.phase == "fight" and g.foeI == 1 and g.foeMax == LC.BoxingHP(LC.BoxingFoes[1], 2), "The Main Event: round 1, Lamarr, tougher for two boxers")
a:SetPos(g.foePos + Vector(60, 0, 0))
local hp0 = g.foeHP
Press(a, ATTACK)
ok(g.foeHP == hp0 - 1, "a punch next to it lands")
a:SetPos(g.foePos + Vector(60, 0, 0))
b:SetPos(g.foePos + Vector(0, 60, 0))
b.crouch = true
g.pl[a].safe, g.pl[b].safe = 0, 0
g.phase, g.at = "windup", CurTime()
_run(0.1)
ok(g.pl[a].lives == 2 and g.pl[b].lives == 3, "it swings: standing, knocked down; crouching, it misses")
b.crouch = nil
a:SetPos(g.foePos + Vector(60, 0, 0))
g.foeHP, g.phase, g.nextSwing = 1, "fight", CurTime() + 100
g.pl[a].punchAt = 0 -- (the last punch was a moment ago: no wait between them for this one)
Press(a, ATTACK)
ok(g.phase == "ko", "knockout", tostring(g.phase) .. " hp=" .. tostring(g.foeHP))
_run(4.2)
ok(g.foeI == 2 and g.foeDef.name == "The Soda Machine", "round 2: the soda machine")
Stop(d)

-- The Exam: stuck at your desk, answers in chat; he eats each paper, and only then your score
local r = LC.ExamMarks({ [1] = 2, [2] = 2, [3] = 3 })
local tie = LC.ExamMarks({ [1] = 1, [2] = 4 })
ok(r[2] and not r[3] and tie[1] and tie[4], "the right answer is whatever most of the class picks (a tie: all of them)")
local q0 = LC.ExamQuestions[1]
ok(LC.ExamAnswerOf("b", q0) == 2 and LC.ExamAnswerOf("D) yes", q0) == 4 and LC.ExamAnswerOf("tuesday", q0) == 3 and LC.ExamAnswerOf("maybe", q0) == nil, "an answer: a letter, or the answer's words")
g, d = Start("exam")
local sa = g.pl[a]
ok(sa.start == g.seats[g.seatOf[a]], "The Exam: everyone has a desk")
a:SetPos(sa.start + Vector(200, 0, 0))
_run(0.1)
ok(a:GetPos():Distance(sa.start) < 1, "and is stuck at it")
_run(6.2)
ok(g.phase == "read" and g.q and g.papers[g.seatOf[a]] and g.papers[g.seatOf[b]], "a question, and each one's paper on their desk")
ok(not LC.StrangeDreamSay(a, "A"), "(no answering while it's read out)")
_run(LC.ExamRead)
ok(g.phase == "answer" and LC.StrangeDreamSay(a, "A") and LC.StrangeDreamSay(b, "a"), "typing a letter in chat answers")
for qi = 2, LC.ExamCount do -- (the rest: a always agrees with the class, b never answers)
    g.answers[qi] = { [a] = 1 }
end
g.answers[1][b] = nil
g.qi, g.phase, g.at = LC.ExamCount, "done", CurTime()
_run(0.1)
ok(g.phase == "collect" and sa.score == LC.ExamCount and (g.pl[b].score or 0) == 0, "pencils down: the scores are known...")
local st = g.def.state(g, a)
ok(not sa.revealed and string.find(st.meterName, "?", 1, true), "...but nobody's told until he's eaten their paper")
_run(2.2)
local firstK = g.desk
local firstP = firstK and g.papers[firstK].p
ok(g.phase == "walk" and firstP, "he walks to the first desk")
local guard = 0
while g.phase ~= "eat" and guard < 200 do _run(0.1) guard = guard + 1 end
ok(g.phase == "eat" and IsValid(g.papers[firstK].ent), "picks up the paper, and eats it")
_run(LC.ExamEat + 0.1)
ok(g.papers[firstK].eaten and g.pl[firstP].revealed, "and only then is its score revealed")
guard = 0
while not (g.pl[a].done and g.pl[b].done) and guard < 400 do _run(0.1) guard = guard + 1 end
ok(g.pl[a].how == "won" and g.pl[b].how == "out", "a pass wins, a fail is out: every paper eaten")
Stop(d)

-- The Last Train
g, d = Start("train")
local x0 = g.doorX
a.aim = Vector(1, 0, 0)
_run(1)
ok(g.doorX > x0, "The Last Train: looking at the door, it slides away")
a.aim, b.aim = Vector(-1, 0, 0), Vector(-1, 0, 0) -- (nobody looking at it)
local x1 = g.doorX
_run(1)
ok(g.doorX < x1, "looking away, it creeps closer")
a:SetPos(Vector(g.doorX, g.doorY, g.top))
_run(0.1)
ok(g.pl[a].how == "won", "reach it: all aboard")
Stop(d)

-- Where's Lamarr?
g, d = Start("lamarr")
s = g.pl[a]
a:SetPos(Mid(g))
s.got = 0 -- (whatever they caught walking in doesn't count here)
for i = 2, #g.crabs do local cr = g.crabs[i] local far = a:GetPos() + Vector(5000, 0, 0) cr.pos, cr.from, cr.to, cr.rest, cr.t0, cr.t1 = far, far, far, CurTime() + 100, 0, 0 end -- (only Lamarr near)
local lam = g.crabs[1]
lam.pos, lam.from, lam.to, lam.rest, lam.t0, lam.t1 = a:GetPos(), a:GetPos(), a:GetPos(), CurTime() + 100, 0, 0
_run(0.1)
ok(lam.lamarr and s.got == 3 and lam.gone, "Where's Lamarr?: catching Lamarr counts three")
Stop(d)

-- Running in Molasses
g, d = Start("molasses")
s = g.pl[a]
ok(a.lagged == LC.MolassesSlow or a.SetLaggedMovementValue == nil, "Running in Molasses: you're slow")
g.zPos = Mid(g) + Vector(0, 2000, 0)
a:SetPos(g.corners[1])
_run(0.1)
ok(s.next == 2, "the first corner reached")
s.safe = 0
g.zPos = a:GetPos()
_run(0.1)
ok(s.lives == 2, "the zombie catches you: a life")
Stop(d)

-- Hot Potato
g, d = Start("potato")
_run(4.2)
ok(g.phase == "live" and g.holder, "Hot Potato: someone has the grenade")
a:SetPos(Mid(g)) b:SetPos(Mid(g) + Vector(20, 0, 0))
LC.PotatoGive(g, { p = a }, CurTime())
g.passAt, g.prev = 0, nil -- (whoever had it first can't take it straight back: not tested here)
_run(0.1)
ok(g.holder and g.holder.p == b, "touch someone: it's theirs")
g.pl[b].safe = 0
g.fuse = CurTime()
_run(0.1)
ok(g.pl[b].lives == 2 and g.phase == "wait", "it goes off in their hands: a life")
Stop(d)

-- Overwatch Says
ok(LC.SimonObeyed("jump", true, { jumped = true }) and not LC.SimonObeyed("jump", false, { jumped = true }) and LC.SimonObeyed("crouch", false, { crouchEnd = false })
    and LC.SimonObeyed("freeze", true, { fastest = 5 }) and not LC.SimonObeyed("walk", true, { fastest = 5 }), "do it only when Overwatch says")
g, d = Start("simon")
_run(6.2)
ok(g.phase == "order", "Overwatch Says: an order")
g.act, g.says = "jump", true
a.ground = false
_run(0.1)
a.ground = nil
g.at = CurTime()
_run(0.1)
ok(g.pl[a].lives == 3 and g.pl[b].lives == 2, "Overwatch says jump: the one who didn't loses a life")
Stop(d)

-- Dance Marathon
ok(LC.DanceTempo(nil) == LC.DanceBPM, "no song: the beat at LC.DanceBPM")
_files["sound/livingcity/dreams/dance1.txt"] = "128 bpm"
ok(LC.DanceTempo("livingcity/dreams/dance1.mp3") == 128, "the owner's song: its tempo from its .txt")
_files["sound/livingcity/dreams/dance1.txt"] = nil
g, d = Start("dance")
s = g.pl[a]
g.beat0 = CurTime() + 0.15
Press(a, IN_JUMP)
ok(s.hits == 1, "a jump on the big beat counts", s.hits)
Press(a, IN_JUMP)
ok(s.hits == 1, "once a beat")
Stop(d)

-- Counting Headcrabs
local n, jumps = LC.SheepPlan(0, 24)
local crabs = 0
for _, j in ipairs(jumps) do if j.crab then crabs = crabs + 1 end end
ok(crabs == n and n >= 8 and LC.SheepScore(12, 12) == 2 and LC.SheepScore(11, 12) == 1 and LC.SheepScore(nil, 12) == 0, "counting headcrabs: the plan's count is right; exact 2 points, one off 1")
g, d = Start("sheep")
_run(6.2)
ok(g.phase == "watch", "Counting Headcrabs: they jump the fence")
g.at = CurTime()
_run(0.1)
ok(g.phase == "answer", "then: how many?")
ok(LC.StrangeDreamSay(a, "I think " .. g.n) == true, "a number said in chat is your answer (and stays in the dream)")
g.at = CurTime()
_run(0.1)
ok(g.pl[a].points == 2 and (g.pl[b].points or 0) == 0, "exactly right: 2 points")
Stop(d)

-- the editor lists them
local seen = {}
for _, e in ipairs(LC.DreamTestList()) do seen[e.id] = e.mood end
ok(seen.horse == "Neutral" and seen.dance == "Happy" and seen.boxing == "Neutral", "the editor's test list has them all")

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b }) do
    p.crouch, p.keys, p.ground, p.aim = nil, nil, nil, nil
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
MoreStrangeDreamTests()

-- Ten more strange dreams, nonsense on purpose (sv_livingcity_strangedreams3.lua), and the nonsense in every strange dream
function NonsenseDreamTests()
section("Shared dreams: ten nonsense dreams (clocks, tea party, derby, say cheese, doors, splat, conga, shh, bubbles, watchers); retextures, faces, effects, warped sounds")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(165000, -165000, 0), Vector(225000, -225000, 0)
local adm = newPlayer("NDAdmin", "admin")
local a = newPlayer("NDA", "citizen")
local b = newPlayer("NDB", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
local function Both()
    Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0))
    a.crouch, b.crouch, a.keys, b.keys, a.aim, b.aim, a.vel, b.vel = nil, nil, nil, nil, nil, nil, nil, nil
    a:SetNW2Float("lc_unbroken_until", 0) b:SetNW2Float("lc_unbroken_until", 0)
end
local function Start(id)
    Both()
    local okS, d = LC.DreamStart(id, adm, false, nil, true)
    local g = okS and d.game
    _run(0.1)
    if g then g.pl[a].safe, g.pl[b].safe = 0, 0 end
    return g, d
end
local function Stop(d) if d then LC.DreamGameStop(d, "test") end _run(2.5) end
local function Mid(g) return Vector(g.dream.pos.x, g.dream.pos.y, g.top + 4) end
player.GetAll = function() return { adm, a, b } end
local dp = LC.AddPoint(DREAM, 0, "dream")

local where = {}
for _, grp in ipairs(LC.DreamOffice().groups) do for _, e in ipairs(grp.endings) do where[e.id] = grp.mood end end
ok(#LC.StrangeDreams3 == 10 and where.watchers == "nightmare" and where.clocks == "neutral" and where.tea == "neutral" and where.photo == "neutral" and where.doors == "neutral"
    and where.shh == "neutral" and where.derby == "happy" and where.paint == "happy" and where.conga == "happy" and where.bubbles == "happy", "ten more on her tablet, each under its mood")
ok(where.horse == "neutral", "Hooves and All is Neutral now (the owner)")
local built = true
for _, id in ipairs(LC.StrangeDreams3) do
    local g, d = Start(id)
    local okS = g and pcall(g.def.state, g, a)
    if not okS then built = false print("did not build: " .. id) end
    Stop(d)
end
ok(built, "every one of them builds, and draws its screen")

-- Stop the Clocks
ok(LC.ClockHold(1) > LC.ClockHold(4), "the fewer of you, the longer a clock stays stopped")
local g, d = Start("clocks")
local ck = g.clocks[1]
a:SetPos(Vector(ck.pos.x, ck.pos.y, g.top + 4))
_run(0.1)
ok(not g.clocks[1].running, "Stop the Clocks: touch one and it stops")
for _, c in ipairs(g.clocks) do c.running, c.til = false, CurTime() + 100 end
_run(0.1)
ok(g.pl[a].how == "won", "every clock stopped at once: time is yours")
Stop(d)

-- The Tea Party
g, d = Start("tea")
_run(6.2)
ok(g.phase == "move" and g.move ~= 0, "The Tea Party: change places!")
a:SetPos(g.seats[g.seatOf[a]])
b:SetPos(Mid(g) + Vector(0, 300, 0))
g.at = CurTime()
_run(0.1)
ok(g.pl[a].lives == 3 and g.pl[b].lives == 2, "in your new seat in time, fine; not, a life")
Stop(d)

-- The Headcrab Derby
g, d = Start("derby")
_run(6.2)
ok(g.phase == "bet", "The Headcrab Derby: place your bets")
a:SetPos(g.pads[2])
g.at = CurTime()
_run(0.1)
ok(g.phase == "race" and g.pl[a].bet == 2, "standing on a pad when they're off backs that lane")
g.crabs[2].x = g.x1
_run(0.1)
ok(g.winner == 2 and g.pl[a].points == 1, "your headcrab wins: a point")
Stop(d)

-- Say Cheese
local fake = { cover = { { pos = Vector(100, 0, 0), r = 40 } } }
ok(LC.PhotoHidden(fake, Vector(0, 0, 0), Vector(200, 0, 0)) and not LC.PhotoHidden(fake, Vector(0, 0, 0), Vector(0, 200, 0)), "hidden: something giant between you and the camera")
g, d = Start("photo")
g.cover = {}
g.phase, g.at = "warn", CurTime()
_run(0.1)
ok(g.pl[a].lives == 2 and g.shots == 1 and g.flash, "Say Cheese: out in the open at the flash, a life")
Stop(d)

-- The Doors
g, d = Start("doors")
_run(6.2)
ok(g.phase == "listen" and g.right, "The Doors: a music box behind one door")
a:SetPos(g.doors[g.right].pos)
b:SetPos(g.doors[(g.right % 6) + 1].pos)
g.at = CurTime()
_run(0.1)
ok(g.pl[a].lives == 3 and g.pl[b].lives == 2, "the right door, fine; the wrong one, a life")
Stop(d)

-- Splat!
ok(LC.PaintNeed(1) == 18 and LC.PaintNeed(5) == 8, "your share of the floor: half alone, never under 8")
g, d = Start("paint")
a:SetPos(g.tiles[1].pos)
_run(0.1)
ok(g.tiles[1].by == a and LC.PaintCount(g, a) == 1 and g.tiles[1].ent.col ~= nil, "Splat!: a tile you step on takes your colour")
Stop(d)

-- Conga!
g, d = Start("conga")
_run(0.2)
a:SetPos(g.tail)
_run(0.5)
ok((g.pl[a].groove or 0) > 0 and g.pl[a].inside, "Conga!: in the glow at the tail, the groove grows")
Stop(d)

-- Shh!
g, d = Start("shh")
a.vel = Vector(300, 0, 0)
_run(1)
ok(g.noise > 0, "Shh!: running makes noise")
a.vel = nil
g.noise = LC.ShhLoud + 5
_run(0.1)
ok(g.pl[a].lives == 2 and g.pl[b].lives == 2 and CurTime() < g.wake, "the baby wakes: everyone loses a life")
_run(4.5)
local toy = g.toys[1]
toy.gone = nil
for k = 2, #g.toys do g.toys[k].gone = CurTime() + 100 end -- (only this one about)
g.pl[a].got = 0
a:SetPos(toy.pos - Vector(0, 0, 24))
_run(0.1)
ok(g.pl[a].got == 1, "a toy gathered")
Stop(d)

-- Bubbles
g, d = Start("bubbles")
local s = g.pl[a]
a:SetPos(Mid(g))
local mid = a:GetPos() + Vector(0, 0, 36)
g.bubbles[1] = { x = mid.x, y = mid.y, z = mid.z, t0 = CurTime() + 0.1, kind = 1 }
_run(0.1)
ok(s.got == 1, "Bubbles: touch one, pop")
a.pushed = nil
g.bubbles[2] = { x = mid.x, y = mid.y, z = mid.z, t0 = CurTime() + 0.1, kind = 3 }
_run(0.1)
ok(a.pushed and a.pushed.z > 400, "a big one carries you up")
ok(s.liftUntil and s.liftUntil - CurTime() > 10 and #g.bubbles >= 30, "and leaves you floating for twelve seconds; there are far more bubbles (the owner, 11 November)")
Stop(d)

-- The Watchers
g, d = Start("watchers")
local w = g.watch[1]
a:SetPos(Mid(g))
a.aim = (w.pos - a:GetPos()):GetNormalized()
ok(LC.WatcherSeen({ a }, w.pos), "The Watchers: looked at, one is seen")
local p0 = w.pos * 1
_run(4)
local seenStill = w.pos:Distance(p0) < 1
a.aim, b.aim = Vector(0, 0, -1), Vector(0, 0, -1) -- (nobody looking)
local p1 = w.pos * 1
_run(0.5)
ok(seenStill and w.pos:Distance(p1) > 1, "it stays still while watched, and moves when not")
g.pl[a].safe = 0
w.pos = a:GetPos()
_run(0.1)
ok(g.pl[a].lives == 2, "its touch costs a life")
Stop(d)

-- nonsense in every strange dream: retextures, faces, effects; warped sounds
ok(LC.DreamFxRoll(0) == 0 and LC.DreamFxRoll(1) == 2 ^ #LC.DreamFxNames - 1 and #LC.DreamFxNames == 10, "ten effects, each on its own roll")
local r0, f0, x0 = LC.DreamRetexture, LC.DreamFaces, LC.DreamFxChance
LC.DreamRetexture, LC.DreamFaces, LC.DreamFxChance = 1, 1, 1
g, d = Start("tea")
for _, e in ipairs(g.ents) do e.lcNonsenseSeen = nil end
LC.DreamNonsense(g)
local mats = {}
for _, m in ipairs(LC.DreamMaterials) do mats[m] = true end
local retex, kept, faced, fxed = false, true, false, false
for _, e in ipairs(g.ents) do
    if IsValid(e) then
        if mats[e:GetMaterial()] then retex = true end
        if e.lcKeepLook and mats[e:GetMaterial()] then kept = false end
        if e:GetNW2Bool("lc_dream_face", false) then faced = true end
        if (e:GetNW2Int("lc_dream_fx", 0) or 0) > 0 then fxed = true end
    end
end
ok(retex and kept, "things get a texture from the material tool (never the floor or what matters to playing)")
ok(faced and IsValid(g.host) and g.host:GetNW2Bool("lc_dream_face", false), "people get a face that pulls expressions")
ok(fxed, "and things carry effects")
Stop(d)
LC.DreamRetexture, LC.DreamFaces, LC.DreamFxChance = r0, f0, x0
local w0 = LC.DreamWarp
LC.DreamWarp = 0
local same = LC.DreamWarpPitch(100) == 100
LC.DreamWarp = 1
local warped = true
for _ = 1, 20 do local p = LC.DreamWarpPitch(100) if p < 60 or p > 150 then warped = false end end
LC.DreamWarp = w0
ok(same and warped, "sounds: some pitched and sped or slowed, within reason")
ok(LC.StrangeIs("watchers") and LC.StrangeIs("cheese") and not LC.StrangeIs("maze"), "(only the strange dreams get the nonsense)")

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b }) do
    p.crouch, p.keys, p.ground, p.aim, p.vel = nil, nil, nil, nil, nil
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
NonsenseDreamTests()

-- Pick Up That Can, a fever dream (sv_livingcity_candream.lua)
function CanDreamTests()
section("Shared dreams: Pick Up That Can (your own can; at him, in the bin, anywhere else; the living cans)")
_setcvar("lc_dream_rules", 0) _setcvar("lc_dream_auto", 0)
local errs0 = #_errors
local savedWalls, realGetAll, realReload = _walls, player.GetAll, LC.EndingReload
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
LC.EndingReload = function() end
local CITY, DREAM = Vector(165000, -165000, 0), Vector(225000, -225000, 0)
local adm = newPlayer("CDAdmin", "admin")
local a = newPlayer("CDA", "citizen")
local b = newPlayer("CDB", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
player.GetAll = function() return { adm, a, b } end
local dp = LC.AddPoint(DREAM, 0, "dream")
local function Aim(p, at)
    local e = p:EyePos()
    local dx, dy, dz = at.x - e.x, at.y - e.y, at.z - e.z
    local l = math.sqrt(dx * dx + dy * dy + dz * dz)
    p.aim = Vector(dx / l, dy / l, dz / l)
end
local function Tap(p, key) p.keys = { [key] = true } _run(0.1) p.keys = nil _run(0.1) end

local where = {}
for _, grp in ipairs(LC.DreamOffice().groups) do for _, e in ipairs(grp.endings) do where[e.id] = grp.mood end end
ok(where.can == "neutral", "Pick Up That Can is on her tablet, under Neutral")
ok(LC.StrangeIs("can") and LC.StrangeIs("cheese") and LC.StrangeIs("watchers") and not LC.StrangeIs("maze"), "it's a strange dream (and the others still are)")
ok(LC.StrangeCues.can_hello and LC.StrangeCues.can_hello[2] == "Pick up that can.", "his line is Half-Life 2's")

Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0))
a.keys, b.keys, a.aim, b.aim = nil, nil, nil, nil
local okS, d = LC.DreamStart("can", adm, false, nil, true)
local g = okS and d.game
ok(g ~= nil and #g.sets == 1 and IsValid(g.sets[1].cop) and IsValid(g.sets[1].bin), "an officer and a bin in the middle")
_run(0.2)
local st = g.def.state(g, a)
ok(st.can and st.can.s == "bin" and st.can.k == "can", "your can starts on the bin")
_run(3.5)
st = g.def.state(g, a)
local ca, cb = g.pl[a].can, g.pl[b].can
ok(ca.st == "floor" and cb.st == "floor" and st.can.s == "floor" and st.glows and #st.glows == 1, "he knocks it off: a can each, on the floor")
ok(ca.pos:Distance(cb.pos) > 10, "(each their own)")
local said = false
for _, cue in ipairs(g.said or {}) do if cue == "can_hello" then said = true end end
ok(said, "\"Pick up that can.\"")

-- too far away to pick up; then near
a:SetPos(ca.pos + Vector(400, 0, 0))
Tap(a, IN_USE)
ok(g.pl[a].can.st == "floor", "too far away to pick it up")
a:SetPos(ca.pos + Vector(30, 0, 0))
Tap(a, IN_USE)
ok(g.pl[a].can.st == "held" and g.def.state(g, a).can.s == "held", "Use picks it up")

-- what a throw hits
local m = g.sets[1]
a:SetPos(Vector(m.o.x, m.o.y - 250, g.top + 4))
Aim(a, Vector(m.o.x, m.o.y, g.top + 50))
ok(LC.CanAim(g, a) == "cop", "thrown at him: him")
Aim(a, LC.CanBinTop(g))
ok(LC.CanAim(g, a) == "bin", "thrown at the bin: the bin")
Aim(a, Vector(m.o.x - 400, m.o.y - 250, g.top))
local what, at = LC.CanAim(g, a)
ok(what == "away" and math.abs(at.z - g.top) < 5, "thrown anywhere else: it lands on the floor")
a:SetPos(Vector(m.binAt.x, m.binAt.y - 50, g.top + 4))
a.aim = Vector(0, 0.5, -0.86)
ok(LC.CanAim(g, a) == "bin", "standing over the bin, looking down: dropped in")

-- at him: the can and the officer swap
a:SetPos(Vector(m.o.x, m.o.y - 250, g.top + 4))
Aim(a, Vector(m.o.x, m.o.y, g.top + 50))
Tap(a, IN_ATTACK)
ok(g.swapped and m.swapped and IsValid(m.can) and IsValid(m.stick) and m.cop == nil and #g.sets == 1, "at him: the can grows, comes alive and takes the stunstick")
ok(g.pl[a].can.st == "fly" and g.pl[a].did.cop == 1, "(your can is away)")
_run(2)
ok(m.hid == true and m.tiny.nodraw == true, "the officer shrinks onto the bin")
_run(LC.CanBack + 3)
ok(g.pl[a].can.st == "floor" and g.pl[a].can.kind == "cop" and g.def.state(g, a).can.k == "cop", "the can knocks a tiny officer off the bin for you")
ok(string.find(g.def.state(g, a).big or "", "officer", 1, true) ~= nil, "(and tells you to pick that up)")

-- every hit after that: another living can, bin and tiny officer
LC.CanThrown(g, b, "cop", Vector(m.o.x, m.o.y, g.top + 40), m)
ok(#g.sets == 2 and IsValid(g.sets[2].can) and IsValid(g.sets[2].tiny) and IsValid(g.sets[2].bin), "hit it again: another can, bin and tiny officer beside it")
local s2 = g.sets[2]
ok(LC.CanHome(g, b) == s2 and s2.owner == b and LC.CanHome(g, a) == m, "the one you made is yours; until you make one, the first is")
local mb, ma = g.def.state(g, b).mine, g.def.state(g, a).mine
ok(mb and mb[4] == 1 and math.abs(mb[1] - (s2.o.x + s2.binAt.x) / 2) <= 1 and ma and ma[4] == 0 and math.abs(ma[1] - (m.o.x + m.binAt.x) / 2) <= 1, "and it's lit up on your screen")
ok(string.find(g.pl[b].note or "", "yours", 1, true) ~= nil, "(you're told so)")
_run(LC.CanBack + 3)
ok(g.pl[b].can.st == "floor" and g.pl[b].can.pos:Distance(s2.binAt) < 120 and g.pl[b].can.pos:Distance(m.binAt) > 60 and s2.swungAt ~= nil, "your next officer is knocked off your own bin, by your own can")
ok(s2.o:Distance(m.o) <= 110, "(right next to the first)")
_run(LC.CanCycle + 0.5)
ok(s2.cyc ~= nil, "which knocks its own officer off its own bin")
local chanceWas = LC.CanTinyChance
LC.CanTinyChance = 1
_run(LC.CanCycle * 2)
ok((s2.squeaks or 0) >= 1 and LC.CanTinyPitch >= 200 and #LC.CanTinyLines >= 10, "and the tiny officer squeaks threats from the floor, very high")
LC.CanTinyChance = chanceWas
a:SetPos(Vector(s2.o.x, s2.o.y - 200, g.top + 4))
Aim(a, Vector(s2.o.x, s2.o.y, g.top + 36))
local w2, _, set2 = LC.CanAim(g, a)
ok(w2 == "cop" and set2 == s2, "any of them can be hit")
local n = 0
while LC.CanAddSet(g) and n < 100 do n = n + 1 end
ok(#g.sets == LC.CanMaxSets and LC.CanMaxSets == 30, "thirty of them at most", #g.sets)
LC.CanThrown(g, b, "cop", Vector(m.o.x, m.o.y, g.top + 40), m)
ok(#g.sets == LC.CanMaxSets and LC.CanHome(g, b) == s2, "(a hit after that adds none, and yours stays yours)")
g.def.leave(g, b)
ok(s2.owner == nil and LC.CanHome(g, b) == m, "(wake up and it's nobody's)")
LC.CanOwn(g, b, s2)
_run(0.3)

-- in the bin; anywhere else
local rainWas = g.rain
LC.CanThrown(g, a, "bin", LC.CanBinTop(g), m)
ok(m.binScale > 1 and g.rain ~= rainWas and g.def.state(g, b).rain == g.rain, "in the bin: the bin grows, and it rains cans on everyone")
local growWas = m.grow
LC.CanThrown(g, a, "away", Vector(m.o.x - 300, m.o.y - 200, g.top + 3))
ok(m.grow > growWas and #g.trees == 1 and IsValid(g.trees[1].ent), "anywhere else: a can tree where it lands, and the one in charge grows")
for _ = 1, 40 do LC.CanThrown(g, a, "away", Vector(m.o.x - 300, m.o.y - 200, g.top + 3)) LC.CanThrown(g, a, "bin", LC.CanBinTop(g), m) end
ok(#g.trees == LC.CanMaxTrees and m.grow <= LC.CanCopMax and m.binScale <= LC.CanBinMax, "(none of it grows for ever)")
ok(LC.CanWays(g.pl[a]) == 3 and LC.CanWays(g.pl[b]) == 1 and g.def.state(g, a).meter == 100, "three ways tried")
_run(0.5)
ok(pcall(g.def.state, g, adm), "(someone not playing can still watch)")

-- the end: every which way wins
g.ends = CurTime() + 0.4
_run(0.2)
ok(g.pl[a].how == "won" and g.pl[b].how ~= "won", "all three before the time's up: you wake Unbroken; not all three: nothing lost")
LC.DreamGameStop(d, "test")
_run(2.5)

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b }) do
    p.crouch, p.keys, p.ground, p.aim, p.vel = nil, nil, nil, nil, nil
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
player.GetAll, LC.EndingReload = realGetAll, realReload
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
CanDreamTests()

-- The dream plan (sv_livingcity_dreamplan.lua): her choice of a kind now and then, the city's by sociostability, in turn
function DreamPlanTests()
section("Shared dreams: the plan (she chooses a kind every few nights, only her own dreams for her; the city by sociostability; round robin; the black screen's line)")
_setcvar("lc_dream_rules", 1)
local errs0 = #_errors
local savedWalls, realGetAll = _walls, player.GetAll
_walls = {}
LC.EndEvent(true)
_setcvar("lc_needs", 0)
local CITY, DREAM = Vector(166000, -166000, 0), Vector(226000, -226000, 0)
local adm = newPlayer("DPAdmin", "admin")
local a = newPlayer("DPA", "citizen")
local b = newPlayer("DPB", "citizen")
_run(3)
local function Asleep(p, at)
    p:SetPos(at)
    local key = string.format("s%d_%d_%d", math.floor(at.x), math.floor(at.y), math.floor(at.z))
    p.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
    p:SetNW2Bool("lc_sleeping", true)
    p.lcBedKey, p.lcBedFrom = key, at + Vector(40, 0, 0)
    LC.BedSleepers[key] = p
end
player.GetAll = function() return { adm, a, b } end
local dp = LC.AddPoint(DREAM, 0, "dream")
local P = LC.DreamPlan
P.adminNight, P.specialNight = -100, -100
LC.DreamForget()
LC.DreamAdminSkipSet(adm, true)

-- her wait, and the night in between
local tonight = LC.DreamPlanTonight()
P.adminNight = tonight - 1
local okW, whyW, wait = LC.DreamAdminCanPick(adm)
ok(not okW and wait == LC.DreamPickNights - 1 and string.find(whyW, "2 nights", 1, true), "she chose last night: her next choice comes in a couple of nights", whyW)
P.adminNight = tonight - LC.DreamPickNights
ok(LC.DreamAdminCanPick(adm), "every " .. LC.DreamPickNights .. " nights, she may choose")
P.specialNight = tonight - 1
local okS, whyS = LC.DreamAdminCanPick(adm)
ok(not okS and string.find(whyS, "gentler", 1, true), "never the night straight after a Nightmare or propaganda dream", whyS)
P.specialNight = -100
ok(not LC.DreamAdminCategory(adm, "happy") and not LC.DreamAdminCategory(a, "nightmare"), "only Nightmare or propaganda, and only her")

-- only her own dreams
Asleep(a, CITY) Asleep(b, CITY + Vector(0, 200, 0)) Asleep(adm, CITY + Vector(0, -200, 0))
local function Has(list, p) for _, q in ipairs(list) do if q == p then return true end end return false end
ok(not Has(LC.DreamSleepers("neutral", "bus"), adm) and Has(LC.DreamSleepers("neutral", "bus"), a), "asleep, she sits out a dream she didn't choose")
ok(LC.DreamAdminCategory(adm, "nightmare") and LC.DreamQueued().cat == "nightmare", "she chooses a Nightmare")
local qid = LC.DreamQueued().id
ok(Has(LC.DreamSleepers("nightmare", qid), adm), "and is in that one herself")
-- the black screen and its line, for everyone about to dream it
net.sent = {}
LC.DreamMoodSend(LC.DreamQueued(), CurTime() + 7)
local got
for _, m in ipairs(net.sent) do if m.name == "lc_dream_mood" then got = m end end
local words = got and got.data[1] and got.data[1].text or ""
local fromList = false
for _, l in ipairs(LC.DreamMoodTexts.admin_nightmare) do if l == words then fromList = true end end
ok(got and fromList, "as it comes: the screen goes black, with a line about why (hers: the Administrator's displeasure)", words)
-- it's dreamt: her turn spent, the kind's turn taken
local rot0 = P.rot.nightmare or 0
local okT = LC.DreamTonight()
local dream = LC.DreamActive
ok(okT and dream and dream.adminBy == adm and (P.rot.nightmare or 0) == rot0 + 1 and P.adminNight >= LC.DreamPlanTonight() - 1, "dreamt: her choice spent, and the next Nightmare is another one")
if dream and dream.game then LC.DreamGameStop(dream, "test") elseif dream then LC.DreamWake(dream) end
_run(2.5)

-- in one she didn't choose, joining, she can wake whenever she likes
LC.DreamAdminSkipSet(adm, false)
Asleep(a, CITY) Asleep(adm, CITY + Vector(0, -200, 0))
local okD, d2 = LC.DreamStart("maze", nil, false, nil, true)
ok(okD and adm.lcDreaming and LC.DreamCanWake(adm), "joining one she didn't choose, she can wake from it whenever she likes")
if okD then LC.DreamGameStop(d2, "test") end
_run(2.5)
LC.DreamAdminSkipSet(adm, true)

-- remembered across a restart
local keep = table.Copy(P.rot)
P.rot.happy = 41
LC.DreamPlanSave()
P.rot.happy = 0
LC.DreamPlanLoad()
ok(P.rot.happy == 41, "the turns are remembered across a restart (data/livingcity/dream_plan.json)")
P.rot = keep
LC.DreamPlanSave()
-- units murdered by NPCs: half as much as a player's (the owner, 9 November), and more needed on a full server
do
    local evWas = LC.Event
    LC.Event = nil
    LC.SocioNpcKills = {}
    LC.SocioNpcMurder() LC.SocioNpcMurder()
    local l2 = LC.SocioAuto()
    LC.SocioNpcMurder() LC.SocioNpcMurder()
    local l4 = LC.SocioAuto()
    local ga = player.GetAll
    local crowd = {}
    for i = 1, 48 do crowd[i] = a end
    player.GetAll = function() return crowd end
    local l4big = LC.SocioAuto()
    player.GetAll = ga
    ok(l2 == "yellow" and l4 == "red" and l4big == "yellow" and LC.SocioScale() == 1, "units murdered by NPC rebels: two make the city yellow, four red (more on a full server: 48 players, four is only yellow)", tostring(l2) .. tostring(l4) .. tostring(l4big))
    LC.SocioNpcKills = {}
    LC.Event = evWas
    LC.DreamDayTimeReset()
    LC.DreamUnitMurdered(0.5)
    local m1 = LC.DreamDayMood().murders
    LC.DreamUnitMurdered(0.5)
    ok(m1 == 0 and LC.DreamDayMood().murders == 1, "for tonight's dream too: two NPC murders count as one")
    LC.DreamDayTimeReset()
end
-- the tablet
local pl = LC.DreamOffice().plan
ok(pl and pl.feel and pl.every == LC.DreamPickNights and pl.skip == true, "her tablet: the day in a line, how often she chooses, and skipping")

LC.DreamForget()
LC.RemovePoint(dp)
for _, p in ipairs({ adm, a, b }) do
    if p.lcSleep and LC.WakeUp then LC.WakeUp(p, "quiet") end
    p:SetPos(Vector(-121000, -121000, 0))
end
P.adminNight, P.specialNight = -100, -100
player.GetAll = realGetAll
_setcvar("lc_needs", 1)
_walls = savedWalls
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
DreamPlanTests()

-- The sides kept even, the Combine's reserves growing with the Resistance, and the Administrator asked at bedtime
function SideBalanceTests()
section("Sides kept even (double plus 4), the Combine's reserves growing with Resistance players, the Administrator asked as she lies down")
local errs0 = #_errors
local realGetAll, realPhase = player.GetAll, LC.DayPhase
local NOOP = function() return nil end
local function Fake(f) -- (just a faction to count; anything else asked of it: nothing)
    return setmetatable({ f = f }, { __index = function(_, k)
        if k == "GetNW2String" then return function(self, key, d) if key == "lcf_faction" then return self.f end return d end end
        if k == "IsValid" then return function() return true end end
        return NOOP
    end })
end
local function Crowd(rebels, combine)
    local list = {}
    for _ = 1, rebels do list[#list + 1] = Fake("resistance") end
    for _ = 1, combine do list[#list + 1] = Fake("cp") end
    return list
end
local joiner = newPlayer("SBJoin", "citizen")
local adm = newPlayer("SBAdmin", "admin") -- (made before the counted crowds stand in for everyone)

-- the Combine's reserves
player.GetAll = function() return Crowd(0, 0) end
local cp0, ota0, i0 = LC.ManpowerMax("cp"), LC.ManpowerMax("ota"), LC.ManpowerInterval("cp")
player.GetAll = function() return Crowd(40, 0) end
local cp40, ota40, i40, reb40 = LC.ManpowerMax("cp"), LC.ManpowerMax("ota"), LC.ManpowerInterval("cp"), LC.ManpowerMax("rebel")
player.GetAll = function() return Crowd(0, 0) end
local reb0 = LC.ManpowerMax("rebel")
ok(cp40 == cp0 + 2 * 36 and ota40 == ota0 + 36 and math.abs(i40 - i0 / (1 + 0.05 * 36)) < 0.01 and reb40 == reb0,
    "40 Resistance players: Civil Protection's reserve holds 72 more, Overwatch's 36 more, and they refill nearly three times as fast (the Resistance's own unchanged)")
player.GetAll = function() return Crowd(4, 0) end
ok(LC.ManpowerMax("cp") == cp0, "4 or fewer: nothing changes")

-- the sides kept even
local crowd = Crowd(6, 1)
player.GetAll = function() local l = { joiner } for _, p in ipairs(crowd) do l[#l + 1] = p end return l end
local okR, whyR = LC.CanJoinFaction(joiner, "resistance")
ok(not okR and string.find(tostring(whyR), "too big", 1, true), "6 rebels against 1 unit: the Resistance takes nobody more (double plus 4 is 6)", tostring(whyR))
ok(LC.SidesEven(joiner, "cp"), "but Civil Protection can")
crowd = Crowd(5, 1)
ok(LC.SidesEven(joiner, "resistance"), "5 against 1: one more fits")
crowd = Crowd(0, 0)
ok(LC.SidesEven(joiner, "resistance") and LC.SideCounts(joiner).rebels == 0, "nobody on either side: the first 4 always fit")
joiner:SetNW2String("lcf_faction", "resistance")
crowd = Crowd(20, 0)
ok(LC.SidesEven(joiner, "resistance"), "already in the Resistance: nobody is ever put off a side")
joiner:SetNW2String("lcf_faction", "citizen")
-- the grace period: back within a few minutes of dropping out (the owner: "5-7 ish minutes"), the place is kept
do
    local graceWas = LC.SideGrace
    LC.SideGrace = math.max(5, CurTime() * 0.5) -- (and well past the map's own start)
    local sid = tostring(joiner:SteamID64())
    LC.SideLeft[sid] = { side = "rebels", t = CurTime() - 1 }
    ok(LC.SidesEven(joiner, "resistance"), "dropped out a moment ago: back on their side, whatever the count")
    LC.SideLeft[sid] = { side = "rebels", t = CurTime() - LC.SideGrace - 10 }
    ok(not LC.SidesEven(joiner, "resistance"), "gone longer than the grace: they join like anyone (and wait for room)")
    LC.SideLeft[sid] = nil
    LC.SideGrace = graceWas
    ok(LC.SideGrace == 420, "(the grace: 7 minutes)")
end

-- help for the outnumbered side (sv_livingcity_imbalance.lua)
do
    local floorWas = LC.ImbalanceFloor
    LC.ImbalanceFloor = 4
    local s1, b1 = LC.ImbalanceBonus({ rebels = 15, combine = 5 })
    local s2, b2 = LC.ImbalanceBonus({ rebels = 9, combine = 5 })
    local s3 = LC.ImbalanceBonus({ rebels = 3, combine = 0 })
    local s4, b4 = LC.ImbalanceBonus({ rebels = 50, combine = 1 })
    local s5, b5 = LC.ImbalanceBonus({ rebels = 2, combine = 10 })
    ok(s1 == "combine" and b1 == 20 and s2 == nil and s3 == nil and b4 == LC.ImbalanceMax and s5 == "rebels" and b5 == 16,
        "15 rebels against 5 units: the Combine gets 20 more NPCs (twice the difference); 9 against 5, nothing; at most 40; and the other way round for the Resistance")
    player.GetAll = function() return Crowd(15, 5) end
    LC.ImbalanceRefresh()
    ok(LC.ImbalanceCops == 10 and LC.ImbalanceQRFSize == 10 and LC.ImbalanceBudget == 10 and string.find(LC.ImbalanceLine() or "", "reaction force", 1, true),
        "half walk the streets (the NPC cap rises for them), half wait as a reaction force")
    -- the reaction force: out of sight, about fifteen seconds' run away, and only then running in
    player.GetAll = realGetAll -- (squads are made among the real players)
    -- the squads (the owner: "more than 2 soldiers ... if sociostability is red and there is lots of rebel fighting ... 5 soldiers and an elite leading them")
    local sq1, sq2 = LC.QRFSquad(false, 20), LC.QRFSquad(true, 20)
    local socioWas, heavyWas = LC.Socio, LC.QRFHeavyNow
    LC.Socio = "red"
    local redHeavy = LC.QRFHeavyNow()
    LC.Socio = socioWas
    ok(#sq1 == 4 and sq1[1] == "soldier" and #sq2 == 6 and sq2[1] == "elite" and sq2[6] == "soldier" and redHeavy,
        "a reaction squad is 4 soldiers; at red or after heavy losses, 5 and an Elite leading them")
    LC.QRFHeavyNow = function() return false end
    local function Ready() LC.ImbalanceSide, LC.ImbalanceQRFSize = "combine", 10 end -- (the every-5-seconds count would undo it)
    Ready()
    local runWas, spotWas = LC.Running, LC.QRFSpot
    LC.Running = true
    local trouble = Vector(150000, 150000, 0)
    local from
    LC.QRFSpot = function(pos) from = pos + Vector(LC.QRFRun, 0, 0) return from end
    local made = LC.QRFDispatch(trouble, nil, "a test")
    local far = made == 4
    for npc in pairs(LC.QRF) do if IsValid(npc) and npc:GetPos():Distance(trouble) < 2000 then far = false end end
    ok(made > 0 and LC.QRFOut() == made and far, "trouble: a reaction squad comes from out of sight, about fifteen seconds' run away", made)
    local again = LC.QRFDispatch(trouble + Vector(200, 0, 0), nil, "a test")
    ok(again == 0, "not two squads to the same place at once")
    for npc, q in pairs(LC.QRF) do q.untilT = CurTime() - 100 end
    _run(4)
    ok(LC.QRFOut() == 0, "their time up, they slip away")
    -- by dropship, where there's open sky (the owner, 9 November)
    local landWas, flyWas = LC.QRFLandSpot, LC.FlyDropship
    local flown
    LC.QRFLandSpot = function(pos) return pos + Vector(800, 0, 0) end
    LC.FlyDropship = function(o2) flown = o2 return {} end
    _run(LC.QRFGap + 1)
    for npc in pairs(LC.QRF) do if IsValid(npc) then npc:Remove() end end
    LC.QRF = {}
    Ready()
    local trouble2 = trouble + Vector(0, 5000, 0)
    local n2, how2 = LC.QRFDispatch(trouble2, nil, "a test")
    ok(n2 > 0 and how2 == "by dropship" and flown and flown.troops and LC.QRFPending == n2 and LC.QRFOut() == 0, "with open sky near: the squad comes in by dropship (nobody out until it lands)")
    flown.onLanded(nil, flown.pos, nil, nil)
    _run(n2 * 1.3 + 1)
    ok(LC.QRFOut() == n2 and LC.QRFPending == 0, "it lands, and they come out and run for it")
    LC.QRFLandSpot, LC.FlyDropship = landWas, flyWas
    -- attacks on checkpoints and the Nexus: a bigger squad
    local cpPt = LC.AddPoint(trouble + Vector(0, 12000, 0), 0, "checkpoint")
    ok(LC.QRFPlace(trouble + Vector(100, 12000, 0)) == "a checkpoint" and LC.QRFPlace(trouble + Vector(0, 20000, 0)) == nil, "a checkpoint is known when it's attacked")
    for npc, q in pairs(LC.QRF) do if IsValid(npc) then npc:Remove() end end
    LC.QRF = {}
    _run(LC.QRFGap + 1)
    Ready()
    local fromWas = LC.QRFSpot
    LC.QRFSpot = function(pos) return pos + Vector(LC.QRFRun, 0, 0) end
    local rebel = newPlayer("SBRebel", "resistance")
    local bank = setmetatable({}, { __index = { IsValid = function() return true end, GetPos = function() return trouble + Vector(50, 12000, 0) end } })
    hook.Run("LivingCityPowerBankShorted", bank, rebel)
    local elite = false
    for npc in pairs(LC.QRF) do local st = LC.NPCs[npc] if st and st.elite then elite = true end end
    ok(LC.QRFOut() == 6 and elite, "a rebel shorts a checkpoint's power bank: a heavy squad answers, an Elite leading 5 soldiers", LC.QRFOut())
    LC.QRFHeavyNow = heavyWas
    LC.QRFSpot = fromWas
    LC.RemovePoint(cpPt)
    for npc in pairs(LC.QRF) do if IsValid(npc) then npc:Remove() end end
    LC.QRF = {}
    LC.SetFaction(rebel, "citizen", nil, true)
    player.GetAll = function() return Crowd(5, 5) end
    LC.ImbalanceRefresh()
    ok(LC.QRFDispatch(trouble, nil, "a test") == 0 and (LC.ImbalanceCops or 0) == 0, "even sides: nothing extra")
    player.GetAll = realGetAll
    LC.ImbalanceFloor = floorWas
    LC.ImbalanceRefresh()
    LC.Running, LC.QRFSpot = runWas, spotWas
end

-- the NPC cap grows with the server's size (the owner: 100 at 32 slots, 175 at 64, 250 at 120 to 128)
do
    local mpWas = game.MaxPlayers
    local budget = GetConVar("lc_npc_budget"):GetInt()
    local function At(n) game.MaxPlayers = function() return n end return LC.NPCBudgetBase() end
    local at32, at64, at120, at128, at16, at96 = At(32), At(64), At(120), At(128), At(16), At(96)
    game.MaxPlayers = mpWas
    local function Want(k) return math.min(LC.NPCBudgetMost, math.max(budget, math.floor(budget * k + 0.5))) end
    ok(at32 == budget and at64 == Want(1.75) and at120 == Want(2.5) and at128 == Want(2.5) and at16 == budget and at96 == Want(1.75 + 0.75 * 32 / 56),
        "the NPC cap: lc_npc_budget at 32 slots, 1.75 times at 64, 2.5 times at 120 and 128 (at most 250), in between on the way, never less on a smaller server",
        at32 .. " " .. at64 .. " " .. at120 .. " " .. at128 .. " " .. at96)
    ok(budget ~= 100 or (at64 == 175 and at128 == 250), "(with the default 100: 175 at 64 slots, 250 at 128)")
end

-- tougher Combine units, always the same (the owner, 9 November), and the outnumbered Combine fighting dirtier
do
    local floorWas, despWas, runWas = LC.ImbalanceFloor, LC.Desperation, LC.Running
    player.GetAll = realGetAll
    local victim = newPlayer("SBDespVictim", "resistance")
    local citizen = newPlayer("SBDespCitizen", "citizen")
    local cop, cst = LC.SpawnCop(Vector(231000, -231000, 0))
    local sold, sst = LC.SpawnSoldier(Vector(231200, -231000, 0))
    local eli, est = LC.SpawnSoldier(Vector(231400, -231000, 0), "elite")
    ok(IsValid(cop) and cop:Health() == 70 and cop:GetMaxHealth() == 70 and IsValid(sold) and sold:Health() == 90 and IsValid(eli) and eli:Health() == 150,
        "Civil Protection 70 health, Overwatch soldiers 90, Elites 150", tostring(cop and cop:Health()) .. " " .. tostring(sold and sold:Health()) .. " " .. tostring(eli and eli:Health()))
    sold:SetHealth(45)
    _setcvar("lc_soldier_health", 120)
    local function Changed(n) for _, fn in pairs(cvars.cb[n] or {}) do fn(n) end end
    Changed("lc_soldier_health")
    local live = sold:GetMaxHealth() == 120 and sold:Health() == 60
    _setcvar("lc_soldier_health", 90)
    Changed("lc_soldier_health")
    ok(live, "changed in the editor: the soldiers out there change too, just as hurt as they were")

    LC.ImbalanceFloor = 4
    local T = LC.DesperationTarget
    ok(T({ rebels = 3, combine = 0 }) == 0 and T({ rebels = 6, combine = 4 }) == 0 and math.abs(T({ rebels = 10, combine = 5 }) - 0.2) < 1e-6
        and math.abs(T({ rebels = 15, combine = 5 }) - 0.6) < 1e-6 and T({ rebels = 40, combine = 2 }) == 1 and T({ rebels = 4, combine = 0 }) == 1,
        "desperation: nothing at 3 rebels or 1.5 to 1; 2 to 1: 0.2; 3 to 1: 0.6; 4 to 1 and more: all of it")
    _setcvar("lc_desperation", 0)
    ok(T({ rebels = 40, combine = 2 }) == 0, "lc_desperation 0: never")
    _setcvar("lc_desperation", 1)

    player.GetAll = function() return Crowd(40, 2) end
    LC.Desperation = 0
    LC.DesperationTick()
    local first = LC.Desperation
    for _ = 1, 3 do LC.DesperationTick() end
    ok(math.abs(first - 0.05) < 1e-6 and math.abs(LC.Desperation - 0.2) < 1e-6, "it creeps up a step every 5 seconds, never jumps", tostring(first) .. " " .. tostring(LC.Desperation))

    LC.Desperation = 0.2
    ok(LC.DesperateSidearm({ smgRoll = 0.1 }) == "weapon_smg1" and LC.DesperateSidearm({ smgRoll = 0.5 }) == "weapon_pistol", "at 0.2, about a fifth of metrocops are issued SMGs")
    LC.Desperation = 0
    ok(LC.DesperateSidearm({ smgRoll = 0 }) == "weapon_pistol" and LC.DesperateSidearm({ smgRoll = 0.001 }) == "weapon_pistol", "not desperate: pistols, as ever")

    -- supplied: frags for soldiers, twice the energy balls for Elites, SMGs for metrocops
    LC.Desperation, LC.DesperationNextSupply = 1, 0
    cst.hasPistol, cst.sidearm, cst.smgRoll, cst.armed = true, "weapon_pistol", 0.5, true
    LC.DesperationTick()
    local smg = false
    for _, w in ipairs(cop.weps or {}) do if w == "weapon_smg1" then smg = true end end
    ok(sold.kv.NumGrenades == "3" and eli.kv.NumGrenades == "4" and smg and cst.sidearm == "weapon_smg1" and cop.activeWeapon == "weapon_smg1",
        "fully desperate: soldiers carry 3 frags, Elites 4 energy balls (twice), the metrocop's pistol swapped for an SMG",
        tostring(sold.kv.NumGrenades) .. " " .. tostring(eli.kv.NumGrenades) .. " " .. tostring(cst.sidearm))

    player.GetAll = realGetAll
    -- 10% more damage to players, none to anyone else
    local function Dmg(n, by) local t = { n = n } function t:GetDamage() return self.n end function t:GetAttacker() return by end function t:ScaleDamage(f) self.n = self.n * f end return t end
    local fn = hook.t.EntityTakeDamage.LivingCityDesperation
    local d1, d2 = Dmg(10, sold), Dmg(10, sold)
    fn(victim, d1)
    fn(cop, d2)
    ok(math.abs(d1.n - 11) < 1e-6 and d2.n == 10, "a soldier's 10 damage to a player is 11 when fully desperate; nothing changes against NPCs", tostring(d1.n))

    -- grenades: never where their own or a citizen would be caught, except their own flashbangs and gas
    local near = cop:GetPos() + Vector(50, 0, 0)
    ok(not LC.DesperateClear(near, 320, "frag") and LC.DesperateClear(near, 200, "flash") and LC.DesperateClear(near, 320, "poison")
        and LC.DesperateClear(Vector(239000, -239000, 0), 320, "frag"), "no frag near a metrocop; their own flashbang and gas are fine (their masks, their flashbangs)")
    local made = {}
    local createWas = ents.Create
    ents.Create = function(c) local e = createWas(c) made[#made + 1] = e return e end
    victim:SetPos(sold:GetPos() + Vector(600, 0, 0))
    local thrown = LC.DesperateThrow(sold, victim, "poison") and LC.DesperateThrow(sold, victim, "frag")
    local gas, frag = made[1], made[2]
    ok(thrown and gas and gas.cls == "lc_grenade" and gas.lcKind == "poison" and gas.lcOwner == sold and frag and frag.cls == "npc_grenade_frag",
        "a soldier lobs the Combine's poison gas (thrown by him) and a frag")
    ents.Create = createWas
    -- their flashbang spares their own
    cst.stunnedUntil = nil
    LC.Detonate("flash", cop:GetPos() + Vector(40, 0, 0), sold)
    ok(not cst.stunnedUntil or cst.stunnedUntil <= CurTime(), "a Combine flashbang doesn't blind the metrocop beside it")

    -- in the fight: a soldier with a rebel in his sights throws; one at a citizen doesn't
    LC.Running = true
    for _, e in ipairs(made) do if IsValid(e) then e:Remove() end end
    for npc, st in pairs(LC.NPCs) do if st.role == "soldier" and npc ~= sold and npc ~= eli then st.nextDesperate = CurTime() + 999 end end
    cop:SetPos(Vector(235000, -235000, 0))
    sst.nextDesperate, est.nextDesperate = 0, CurTime() + 999
    LC.DesperationAt = nil
    sold.enemy = victim
    local threw = LC.DesperationFight()
    citizen:SetPos(sold:GetPos() + Vector(600, 0, 0))
    sst.nextDesperate, sold.enemy = 0, citizen
    local none = LC.DesperationFight()
    LC.Desperation = 0
    sst.nextDesperate, sold.enemy = 0, victim
    local calm = LC.DesperationFight()
    ok(threw == 1 and none == 0 and calm == 0, "desperate, a soldier throws at a Resistance fighter in sight, never at a citizen; not desperate, nobody throws", threw .. " " .. none .. " " .. calm)
    ok(string.find(tostring((function() LC.Desperation = 0.5 return LC.DesperationLine() end)()), "desperate (50%)", 1, true) ~= nil, "the readout says how desperate")

    -- testing alone from the editor: a pinned level, the tester the target whatever their side, a squad sent at them
    player.GetAll = function() return { citizen } end
    LC.Desperation = 0
    LC.DesperationTestSet(citizen, 0.6)
    LC.DesperationTick()
    local pinned = LC.Desperation
    LC.DesperationAt = nil
    citizen:SetPos(sold:GetPos() + Vector(600, 0, 0))
    sst.nextDesperate, sold.enemy = 0, citizen
    local atTester = LC.DesperationFight()
    local sent = LC.DesperationTestSquad(citizen, "elite")
    local cops = LC.DesperationTestSquad(citizen, "cops")
    local units = 0
    for _ in pairs(LC.DesperationTestUnits) do units = units + 1 end
    LC.DesperationTestSet(nil, nil)
    local left = 0
    for npc in pairs(LC.DesperationTestUnits) do if IsValid(npc) then left = left + 1 end end
    ok(math.abs(pinned - 0.6) < 1e-6 and atTester == 1 and sent == 4 and cops == 3 and units == 7 and left == 0 and LC.Desperation == 0 and not LC.DesperationTest,
        "the editor's test: 60% at once, grenades at the tester (a citizen), an Elite and 3 soldiers and 3 metrocops sent; back to normal clears it all",
        pinned .. " " .. atTester .. " " .. tostring(sent) .. " " .. tostring(cops) .. " " .. units .. " " .. left)

    -- the Resistance (the owner, 9 November): 50 health, no extra hurt at home, a few crossbows, 1.25 for each Combine NPC out
    player.GetAll = function() return {} end
    local canWas = LC.ManpowerCan
    LC.ManpowerCan = function() return true end
    local guns, made, hp50 = {}, {}, true
    for i = 1, 300 do
        local r, rst = LC.SpawnRebel(Vector(233000 + i, -233000, 0), nil)
        if IsValid(r) then
            made[#made + 1] = r
            guns[r.kv.additionalequipment] = (guns[r.kv.additionalequipment] or 0) + 1
            if r:Health() ~= 50 or r:GetMaxHealth() ~= 50 then hp50 = false end
        end
    end
    LC.ManpowerCan = canWas
    local smg, sg, xb = guns.weapon_smg1 or 0, guns.weapon_shotgun or 0, guns.weapon_crossbow or 0
    ok(hp50 and #made == 300 and smg > 170 and smg < 250 and sg > 30 and sg < 95 and xb > 10 and xb < 55 and (guns.weapon_ar2 or 0) == 0,
        "Resistance fighters: 50 health; about 70% SMGs, 20% shotguns, 10% crossbows, never a pulse rifle", smg .. " " .. sg .. " " .. xb)
    local home = made[1]
    local hst = LC.NPCs[home]
    local hd = Dmg(10, sold)
    function hd:SetDamage(v) self.n = v end
    hst.follow, hst.quartermaster = nil, nil
    hook.t.EntityTakeDamage.LivingCityRebels(home, hd)
    ok(GetConVar("lc_rebel_home_hurt"):GetFloat() == 1 and hd.n == 10, "a fighter at home takes no more than a player's squad does", tostring(hd.n))
    for _, r in ipairs(made) do if IsValid(r) then r:Remove() end end
    local before = LC.CombineStreetCount()
    local g, gst = LC.SpawnSoldier(Vector(234000, -234000, 0))
    gst.garrison = true
    local after = LC.CombineStreetCount()
    gst.garrison = nil
    ok(after == before and LC.CombineStreetCount() == before + 1, "the Combine's NPCs on the streets count; those posted inside don't")
    g:Remove()

    for _, e in ipairs({ cop, sold, eli }) do if IsValid(e) then e:Remove() end end
    LC.ImbalanceFloor, LC.Desperation, LC.Running = floorWas, despWas, runWas
    player.GetAll = realGetAll
end

-- the Administrator, asked as she lies down on a night she didn't choose
player.GetAll = function() return { adm } end
LC.DayPhase = function() return "night" end
LC.DreamForget()
adm.lcDreamTonightChoice = nil
local pt = LC.AddPoint(Vector(227000, -227000, 0), 0, "dream")
_setcvar("lc_dream_auto", 1) -- (the city dreams every night: there's always one to come)
local dreamedWas = LC.DreamState.dreamedNight
LC.DreamState.dreamedNight = -1 -- (and tonight's hasn't been dreamt yet)
net.sent = {}
local asked = LC.DreamAdminAsk(adm)
local sent = false
for _, m in ipairs(net.sent) do if m.name == "lc_dream_ask" and m.to == adm then sent = true end end
ok(asked and sent, "lying down on a night she didn't choose, she's asked: dream it, or sleep through it")
LC.DreamAdminSkipSet(adm, true)
LC.DreamAdminTonight(adm, true, false)
ok(not LC.DreamAdminSkips(adm) and LC.DreamAdminSkipping(adm) and not LC.DreamAdminAsk(adm), "she says dream it: tonight she's in (her setting stays, and she isn't asked again)")
LC.DreamAdminTonight(adm, false, true)
ok(LC.DreamAdminSkips(adm) and LC.DreamAdminSkipping(adm), "sleep through it, and remember: her setting too")
LC.DreamAdminTonight(adm, true, true)
ok(not LC.DreamAdminSkipping(adm), "(remembering a join turns her setting to join)")
LC.DreamAdminSkipSet(adm, true)
adm.lcDreamTonightChoice = nil
LC.DayPhase = function() return "day" end
ok(not LC.DreamAdminAsk(adm), "a nap in the daytime: not asked")
LC.RemovePoint(pt)
LC.DreamState.dreamedNight = dreamedWas

player.GetAll, LC.DayPhase = realGetAll, realPhase
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
SideBalanceTests()

function SquadSizeTests()
section("Squad sizes by players on a side, E on a unit to lead it, backup out of rebel territory")
local errs0 = #_errors
local realGetAll, stepsWas = player.GetAll, LC.SquadSteps
LC.SquadSteps = { { 2, 5 }, { 4, 3 }, { 6, 2 } }
local S = Vector(241000, -241000, 0)
local notes = {}
local nw = LC.Notice
LC.Notice = function(p, kind, title, text, secs) notes[#notes + 1] = { p = p, t = tostring(title) .. ": " .. tostring(text) } return nw(p, kind, title, text, secs) end
local function Told(p, needle) for i = #notes, 1, -1 do if notes[i].p == p and string.find(notes[i].t, needle, 1, true) then return true end end return false end
local NOOP = function() return nil end
local function Fake(f) -- (a player on a side, to count)
    return setmetatable({ f = f }, { __index = function(_, k)
        if k == "GetNW2String" then return function(self, key, d) if key == "lcf_faction" then return self.f end return d end end
        if k == "IsValid" or k == "IsPlayer" then return function() return true end end
        if k == "GetNW2Int" then return function(_, _, d) return d end end
        if k == "GetPos" or k == "EyePos" then return function() return Vector(-900000, -900000, 0) end end -- (far away, and looking nowhere in particular)
        if k == "GetAimVector" or k == "GetForward" then return function() return Vector(1, 0, 0) end end
        if k == "Alive" then return function() return false end end
        return NOOP
    end })
end
local L = LC.SquadLimitFor
ok(L(1) == 5 and L(2) == 5 and L(3) == 3 and L(4) == 3 and L(5) == 2 and L(6) == 2 and L(7) == 1 and L(30) == 1,
    "squad sizes: 1-2 players on a side, 5 each; 3-4, 3; 5-6, 2; 7 and more, 1")

local lead = newPlayer("SQLead", "resistance")
local member = newPlayer("SQMember", "resistance")
local unit = newPlayer("SQUnit", "cp")
local ows = newPlayer("SQOws", "cp")
local cmdr = newPlayer("SQCmdr", "cp")
lead:SetNW2Int("lcf_rank", 5) member:SetNW2Int("lcf_rank", 2)
unit:SetNW2Int("lcf_rank", 2) ows:SetNW2Int("lcf_rank", 5) cmdr:SetNW2Int("lcf_rank", 6) cmdr:SetNW2String("lcf_special", "ow_commander")
local crowd = {}
local function Real(fn, ...) local g = player.GetAll player.GetAll = realGetAll local x, y = fn(...) player.GetAll = g return x, y end
local function Others(n, f) crowd = {} for _ = 1, n do crowd[#crowd + 1] = Fake(f) end end
player.GetAll = function() local l = { lead, member, unit, ows, cmdr } for _, p in ipairs(crowd) do l[#l + 1] = p end return l end
Others(8, "resistance") -- (10 in the Resistance)
local lm, lp, lifted = LC.SquadLimit(lead)
ok(LC.SquadLimit(member) == 1 and lm == 4 and lifted and lp == 10, "10 in the Resistance: a Member leads 1; the Commander always at least 4", tostring(LC.SquadLimit(member)) .. " " .. lm)
Others(0, "resistance")
ok(LC.SquadLimit(member) == 5 and LC.SquadLimit(lead) == 5, "just the two of them: 5 each")
ok(LC.SquadLimit(unit) == 3 and LC.SquadLimit(cmdr) == 4, "3 Combine players: 3 each, the Elite at least 4")

-- the Resistance: full, and told why
Others(8, "resistance")
member:SetPos(S)
local r1, rs1 = Real(LC.Spawners.rebel, S + Vector(100, 0, 0))
local r2, rs2 = Real(LC.Spawners.rebel, S + Vector(-100, 0, 0))
LC.RebelRecruit(member, r1, rs1)
LC.RebelRecruit(member, r2, rs2)
ok(rs1.follow == member and rs2.follow == nil and Told(member, "Your squad is full: 1 of 1") and Told(member, "team up"),
    "with 10 in the Resistance a Member's squad is 1: the second says no, and they're told why (team up)")
LC.SquadTick()
ok(member:GetNW2Int("lc_squad_n", -1) == 1 and member:GetNW2Int("lc_squad_max", -1) == 1 and member:GetNW2Int("lc_squad_players", -1) == 10, "F2 knows: squad 1 of 1, 10 players")
-- the limit drops below what they have: they keep them, and hear so
Others(0, "resistance")
LC.SquadTick()
LC.RebelRecruit(member, r2, rs2)
ok(rs2.follow == member, "fewer players: room for more")
Others(8, "resistance")
LC.SquadTick()
ok(rs1.follow == member and rs2.follow == member and Told(member, "nobody new can join"), "more players again: both stay, and they're told nobody new can join")
for _, n in ipairs({ r1, r2 }) do local st = LC.NPCs[n] if st and st.follow then LC.DismissFollower(n, st, true) end n:Remove() end

-- backup out of rebel territory, by radio
Others(0, "resistance")
member.lcRebBackupNext = 0
local okNo, whyNo = LC.RebelCallBackup(member)
ok(not okNo and string.find(whyNo or "", "Freq 7 radio", 1, true), "no Freq 7 radio: no backup", whyNo)
LC.GiveItem(member, "radio_tuned") LC.GiveItem(member, "radio_transmitter") _radioUp(member) -- (a transmitter too, in hand: 13 November)
local far, fst = Real(LC.Spawners.rebel, S + Vector(20000, 0, 0))
local inZone, seen, spotWas = LC.InRebelZone, LC.IsSeen, LC.RebelBackupSpot
LC.InRebelZone = function(pos) return pos.x > S.x + 15000 end
LC.IsSeen = function() return false end
LC.RebelBackupSpot = function(p) return p:GetPos() + Vector(1200, 0, 0) end
local candWas = LC.RebelBackupCandidates
LC.RebelBackupCandidates = function() return {} end -- (nobody idle nearby)
local okT, sentT = LC.RebelCallBackup(member)
LC.InRebelZone, LC.IsSeen, LC.RebelBackupSpot, LC.RebelBackupCandidates = inZone, seen, spotWas, candWas
ok(okT and sentT >= 1 and fst.follow == member and far:GetPos():Distance(S) < 1400 and Told(member, "out of rebel territory"),
    "nobody near: a fighter from rebel territory, seen by nobody, comes from out of sight on the way and joins", tostring(sentT) .. " " .. tostring(far:GetPos()))
if fst.follow then LC.DismissFollower(far, fst, true) end
far:Remove()

-- the Combine: E on a unit
Others(0, "resistance")
unit:SetPos(S + Vector(0, 3000, 0))
local c1, cs1 = Real(LC.SpawnCop, S + Vector(100, 3000, 0))
local s1, ss1 = Real(LC.SpawnSoldier, S + Vector(-100, 3000, 0))
local e1, es1 = Real(LC.SpawnSoldier, S + Vector(0, 3100, 0), "elite")
for _, st in ipairs({ cs1, ss1, es1 }) do st.state = "idle" end
ok(LC.UnitRecruit(unit, c1, cs1) and cs1.backupFor == unit and cs1.backupRecruited, "a Metrocop presses E on a unit: he's in their squad")
ok(LC.UnitRecruit(unit, s1, ss1) and ss1.backupFor == nil and Told(unit, "answer only to Overwatch"), "an Overwatch soldier won't follow a Metrocop")
ok(LC.UnitRecruit(ows, s1, ss1) and ss1.backupFor == ows, "but follows an Overwatch soldier")
ok(LC.UnitRecruit(ows, e1, es1) and es1.backupFor == nil and Told(ows, "Overwatch Commander"), "an Elite answers only to the Overwatch Commander")
ok(LC.UnitRecruit(cmdr, e1, es1) and es1.backupFor == cmdr, "who leads him")
ok(LC.UnitRecruit(unit, c1, cs1) and cs1.backupFor == nil, "E again: back to their duties")
-- full: 7 Combine players, 1 each
Others(4, "cp")
LC.UnitRecruit(unit, c1, cs1)
local c2, cs2 = Real(LC.SpawnCop, S + Vector(200, 3000, 0))
cs2.state = "idle"
LC.UnitRecruit(unit, c2, cs2)
ok(cs1.backupFor == unit and cs2.backupFor == nil and Told(unit, "Your squad is full: 1 of 1"), "8 Combine players: one unit each, and told so")
-- call for backup: no room, no call; an Elite never answers a Metrocop's call
_radioUp(unit)
unit.lcBackupNext = 0
local okF, whyF = LC.CallBackup(unit)
ok(not okF and string.find(whyF or "", "squad is full", 1, true), "a full squad can't call for more", whyF)
Others(0, "cp")
cs1.backupFor = nil
es1.backupFor = nil
local okC, sentC = LC.CallBackup(unit)
ok(okC and es1.backupFor == nil, "an Elite doesn't answer a Metrocop's backup call", tostring(sentC))
_radioDown(unit)
for _, n in ipairs({ c1, c2, s1, e1 }) do if IsValid(n) then n:Remove() end end

-- proving yourself before joining the Resistance (the owner, 9 November)
player.GetAll = realGetAll
_setcvar("lc_resistance_join_sympathy", 5)
local hopeful = newPlayer("SQHopeful", "citizen")
local okJ, whyJ = LC.CanJoinFaction(hopeful, "resistance")
ok(not okJ and whyJ == "The Resistance doesn't trust you yet.", "a citizen with no sympathy can't just walk into the Resistance", tostring(whyJ))
local fighter = newPlayer("SQFighter", "resistance")
fighter:SetNW2Int("lcf_rank", 3)
local member2 = newPlayer("SQMember2", "resistance")
member2:SetNW2Int("lcf_rank", 2)
local s0 = LC.Trait(hopeful, "sympathy")
hook.Run("LivingCityGave", hopeful, fighter, "ration")
hook.Run("LivingCityGave", hopeful, fighter, "gun_pistol")
hook.Run("LivingCityGave", hopeful, member2, "ration")
local fighter2 = newPlayer("SQFighter2", "resistance")
fighter2:SetNW2Int("lcf_rank", 4)
hook.Run("LivingCityGave", hopeful, fighter2, "bread")
hook.Run("LivingCityGave", hopeful, fighter2, "gren_flash")
ok(LC.Trait(hopeful, "sympathy") == s0 + 2, "a ration or arms handed to a Fighter or higher: one sympathy for each rebel (not twice the same one, not a Member, not bread)", LC.Trait(hopeful, "sympathy") - s0)
LC.AddTrait(hopeful, "sympathy", 5 - LC.Trait(hopeful, "sympathy"))
ok(LC.CanJoinFaction(hopeful, "resistance"), "5 sympathy: the Resistance takes them")
local invited = newPlayer("SQInvited", "citizen")
LC.ResistanceInvite(invited)
ok(LC.CanJoinFaction(invited, "resistance"), "invited by a story (The Pamphleteer, The Man Inside): in, whatever their sympathy")
local veteran = newPlayer("SQVeteran", "resistance")
LC.SetFaction(veteran, "citizen", nil, true)
ok(LC.CanJoinFaction(veteran, "resistance"), "someone who was in it before can come back")
_setcvar("lc_resistance_join_sympathy", 0)

LC.Notice, LC.SquadSteps, player.GetAll = nw, stepsWas, realGetAll
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
SquadSizeTests()
function SquadCatchUpTests()
section("Squad mates who fall behind or get stuck are put just behind their leader")
do
    local S = Vector(246000, -246000, 0)
    local lead = newPlayer("CatchLead", "cp")
    lead:SetNW2Int("lcf_rank", 3)
    lead:SetPos(S)
    lead.aim = Vector(1, 0, 0)
    local u, ust = LC.Spawners.cop(S + Vector(-2500, 0, 0))
    ust.backupFor, ust.backupUntil, ust.backupJoined = lead, CurTime() + 600, true
    local t0 = CurTime()
    ok(LC.SquadCatchUpOne(u, ust, lead, t0) and u:GetPos():Distance(lead:GetPos()) < 320, "further than 900 from the leader: put near them at once (the owner, 12 November: \"They need to TELEPORT to me\")", tostring(u:GetPos():Distance(lead:GetPos())))
    local back = u:GetPos() - lead:GetPos()
    back.z = 0
    ok(back:GetNormalized():Dot(lead.aim) < 0, "behind them, not in front where they look")
    ok(math.abs(u:GetPos().z - lead:GetPos().z) < 48, "on the floor they stand on")
    -- close enough: left alone
    u:SetPos(S + Vector(-200, 0, 0))
    ok(not LC.SquadCatchUpOne(u, ust, lead, t0 + 10), "close by: left where it is")
    -- stuck: no closer for 10 seconds
    u:SetPos(S + Vector(-600, 0, 0))
    ok(not LC.SquadCatchUpOne(u, ust, lead, t0 + 20), "600 away and just fallen behind: given the chance to walk")
    ok(not LC.SquadCatchUpOne(u, ust, lead, t0 + 26), "still trying")
    ok(LC.SquadCatchUpOne(u, ust, lead, t0 + 31) and u:GetPos():Distance(lead:GetPos()) < 320, "no closer for 10 seconds: stuck, so put behind them")
    -- in a fight close by, it isn't 'stuck'
    u:SetPos(S + Vector(-600, 0, 0))
    ust.state, ust.enemy = "hostile", lead
    ok(not LC.SquadCatchUpOne(u, ust, lead, t0 + 40) and not LC.SquadCatchUpOne(u, ust, lead, t0 + 55), "fighting within 900: left to fight")
    u:SetPos(S + Vector(-1500, 0, 0))
    ok(LC.SquadCatchUpOne(u, ust, lead, t0 + 60), "but whatever it's doing, further than 900 and it comes")
    ust.state, ust.enemy = "idle", nil
    -- never into the dream zone unless the leader's in it
    local oldDZ = LC.DreamZone
    local dz = { pos = S + Vector(-150, 0, 0), r = 120, kind = "dream" }
    LC.DreamZone = function() return dz end
    local spot = LC.SquadCatchSpot(lead, u)
    ok(spot and not LC.SquadInDreamZone(spot), "never put in the dream zone while the leader is outside it", tostring(spot))
    LC.DreamZone = oldDZ
    -- the tick does every squad mate of a Combine leader
    u:SetPos(S + Vector(-3000, 0, 0))
    ust.catchNext = 0
    ok(LC.SquadCatchUpTick(t0 + 100) >= 1 and u:GetPos():Distance(lead:GetPos()) < 320, "every 2 seconds, every squad mate far behind is brought up")
    ust.backupFor = nil
    u:Remove()
    lead:SetPos(S + Vector(40000, 0, 0))
end
end
SquadCatchUpTests()

-- The performance debugger (sh_livingcity_perfdebug.lua, sv_livingcity_perfdebug.lua)
function PerfDebugTests()
section("The performance debugger: hooks, timers, net in and out, networked values, hitches, put back when off")
local errs0 = #_errors
local P = LC.PerfDebug
local staff = newPlayer("PDStaff", "citizen")
staff.admin = true
local cit = newPlayer("PDCitizen", "citizen")
_run(1)
ok(P and not P.on and not P.Installed(), "off until staff turn it on: nothing of it is in the way")
-- the stub's gaps, for this test only
local EMT = getmetatable(ents.Create("prop_physics"))
local realFMT, realGT, realBW = FindMetaTable, hook.GetTable, net.BytesWritten
local realInc, realRH, realNIS, realRecv = net.Incoming, net.ReadHeader, util.NetworkIDToString, net.Receivers
FindMetaTable = function(n) if n == "Entity" then return EMT end return realFMT(n) end
hook.GetTable = function() return hook.t end
net.BytesWritten = function() return 100 end
local handled
net.Receivers = { pdtest = function(len, ply) handled = { len, ply } end }
net.ReadHeader = function() return net._pdHeader end
util.NetworkIDToString = function(i) return ({ [7] = "PDTest", [8] = "PDNobody" })[i] end
net.Incoming = function() end
local addWas, startWas, setNWWas, incWas = hook.Add, net.Start, EMT.SetNW2Int, net.Incoming
local function Busy() local x = 0 for i = 1, 20000 do x = x + i end return x end
local hookFn = function(a) Busy() return a == "ask" and "answer" or nil end
hook.Add("PDTestEvent", "PDTestHook", hookFn)
ok(P.Command(cit, "on") == false and not P.on, "a player who isn't staff can't turn it on")
ok(P.Command(staff, "on") and P.on and P.Installed(), "staff turn it on (C > Help > Performance debugger)")
ok(hook.t.PDTestEvent.PDTestHook ~= hookFn and hook.Add ~= addWas and net.Start ~= startWas and EMT.SetNW2Int ~= setNWWas, "every hook, the net functions and the networked setters are wrapped")
ok(hook.t.Think[P.SELF] ~= nil and P.WrappedHookCount() > 5, "its own frame hook isn't timed; the rest are", P.WrappedHookCount())
-- hooks
local a1 = hook.Run("PDTestEvent", "ask")
hook.Run("PDTestEvent", "x")
hook.Run("PDTestEvent", "x")
local h = P.stats.hooks["PDTestEvent / PDTestHook"]
ok(a1 == "answer" and h and h.n == 3 and h.total > 0, "a hook is timed by event and name, and still returns what it did", h and h.n)
local lateFn = function() Busy() end
hook.Add("PDTestEvent", "PDLateHook", lateFn)
hook.Run("PDTestEvent", "x")
ok(hook.t.PDTestEvent.PDLateHook ~= lateFn and P.stats.hooks["PDTestEvent / PDLateHook"] and P.stats.hooks["PDTestEvent / PDLateHook"].n == 1, "a hook added while it's on is timed too")
local goneFn = function() end
hook.Add("PDTestEvent", "PDGoneHook", goneFn)
hook.Remove("PDTestEvent", "PDGoneHook")
-- net out
net.Start("pd_out")
net.Send(cit)
net.Start("pd_out")
net.Send({ cit, staff })
local so = P.stats.sent.pd_out
ok(so and so.n == 2 and so.to == 3 and so.bytes == 300 and P.stats.toPlayer[cit:SteamID()] == 200, "each message sent: how many, to how many players, how many bytes, and what each player was sent", so and (so.n .. "/" .. so.to .. "/" .. so.bytes))
-- net in
net._pdHeader = 7
net.Incoming(816, cit)
local ri = P.stats.recv.PDTest
ok(handled and handled[1] == 800 and handled[2] == cit and ri and ri.n == 1 and ri.bytes == 102, "each message received: its handler still gets it, and it's counted with its bytes and time", ri and ri.bytes)
net._pdHeader = 8
net.Incoming(64, cit)
ok(P.stats.recv.PDNobody and P.stats.recv.PDNobody.unhandled == 1, "a message nothing handles is counted as such")
ok(P.stats.senders[cit:SteamID()] and P.stats.senders[cit:SteamID()].n == 2, "and who sent them")
-- networked values
local e = ents.Create("prop_physics")
e:SetNW2Int("pd_value", 1)
e:SetNW2Int("pd_value", 1)
e:SetNW2Int("pd_value", 2)
local nv = P.stats.nw["NW2 pd_value"]
ok(nv and nv.calls == 3 and nv.changes == 2 and e:GetNW2Int("pd_value") == 2, "networked values: how often each is set, and how often it really changed", nv and (nv.calls .. "/" .. nv.changes))
-- frames and hitches
local t = 5000
P.Frame(t)
P.Frame(t + 0.015)
hook.Run("PDTestEvent", "x")
P.Frame(t + 0.215)
local sp = P.stats.spikes[#P.stats.spikes]
local inIt = false
for _, it in ipairs(sp and sp.top or {}) do if it.k == "hook: PDTestEvent / PDTestHook" then inIt = true end end
ok(sp and sp.ms >= 199 and sp.ms <= 201 and inIt and sp.lua ~= nil, "a slow frame is kept as a hitch, with what ran in it", sp and (sp.ms .. " lua " .. sp.lua .. " top " .. tostring(sp.top[1] and sp.top[1].k)))
ok(P.stats.frames.n == 2 and P.stats.frames.buckets[1] == 1 and P.stats.frames.buckets[4] == 1, "frames sorted on time to hitch")
-- a flood: lots from one player in one second
for _ = 1, P.FLOOD_MSGS do net._pdHeader = 7 net.Incoming(80, cit) end
P.Frame(t + 1.3)
local fl = P.stats.floods[#P.stats.floods]
ok(fl and fl.sid == cit:SteamID() and fl.n >= P.FLOOD_MSGS and P.stats.senders[cit:SteamID()].peakN >= P.FLOOD_MSGS, "a player sending a flood of messages in one second is noted, with their busiest second")
-- timers started while it's on
local ranT = false
timer.Simple(0, function() ranT = true Busy() end)
_runtimers()
local anyT = false
for k in pairs(P.stats.timers) do if string.find(k, "tests.lua", 1, true) or string.find(k, "string", 1, true) then anyT = true end end
ok(ranT and anyT, "a timer started while it's on still runs, and is timed by where it was started")
LC.PerfDebugNote("LivingCityPDCity", 0.002)
ok(P.stats.timers.LivingCityPDCity and P.stats.timers.LivingCityPDCity.n == 1, "the city's repeating timers (timed all the time) are passed on to it")
-- entities that keep growing
P.Census()
for _ = 1, 60 do ents.Create("pd_leaky") end
P.Census()
local g = P.Growth(P.stats)
ok(g[1] and g[1].k == "pd_leaky" and g[1].diff == 60, "the census finds a class of entity that keeps growing", g[1] and g[1].k)
-- what the window gets, and the report
local snap = P.ServerSnapshot()
local hasPlayer = false
for _, p in ipairs(snap.players or {}) do if p.k == "PDCitizen" then hasPlayer = true end end
ok(snap.on and snap.side == "server" and #snap.hooks > 0 and #snap.recv > 0 and hasPlayer and snap.spikeCount >= 1, "the window's figures: hooks, messages, players, hitches")
local findings = table.concat(P.Findings(snap), " ")
ok(string.find(findings, "pd_leaky", 1, true) and string.find(findings, "PDNobody", 1, true) and string.find(findings, "PDCitizen", 1, true), "what stands out says it in plain words (the leak, the unhandled message, the flood)", findings)
local text = P.ReportText(snap)
ok(string.find(text, "What stands out", 1, true) and string.find(text, "PDTestEvent / PDTestHook", 1, true) and string.find(text, "Hitches", 1, true), "the text report has it all")
ok(P.Command(staff, "watch") and P.watchers[staff], "the window open: its figures are sent every two seconds")
P.Command(staff, "unwatch")
ok(P.Command(staff, "spike", 100) and P.spikeMs == 100 and GetConVar("lc_perfdebug_spike_ms"):GetInt() == 100, "the hitch threshold is set from the window")
P.Command(staff, "spike", 60)
-- off: everything as it was
ok(P.Command(staff, "off") and not P.on, "staff turn it off")
ok(hook.t.PDTestEvent.PDTestHook == hookFn and hook.t.PDTestEvent.PDLateHook == lateFn and hook.t.PDTestEvent.PDGoneHook == nil, "every hook is put back as it was (and a hook removed meanwhile stays removed)")
ok(hook.Add == addWas and net.Start == startWas and EMT.SetNW2Int == setNWWas and net.Incoming == incWas and not P.Installed(), "the net functions, the net handler and the setters are put back too")
local saved
for path in pairs(_files) do if string.match(path, "^livingcity/perf/perf_.*%.txt$") then saved = path end end
ok(saved and string.find(_files[saved], "PDTestEvent", 1, true), "turning it off saves the report to data/livingcity/perf/", saved)
local n0 = P.stats.hooks["PDTestEvent / PDTestHook"].n
hook.Run("PDTestEvent", "x")
ok(P.stats.hooks["PDTestEvent / PDTestHook"].n == n0, "off, nothing is timed (what was measured stays to look at)")
-- it turns itself off
_setcvar("lc_perfdebug_minutes", 1)
P.Command(staff, "on")
P.startedAt = SysTime() - 61
P.OnSecond(SysTime())
ok(not P.on and hook.t.PDTestEvent.PDTestHook == hookFn, "it turns itself off after lc_perfdebug_minutes, and puts everything back")
_setcvar("lc_perfdebug_minutes", 30)
ok(P.Command(staff, "on") and P.stats.hooks["PDTestEvent / PDTestHook"] == nil, "each start measures afresh")
P.Command(staff, "off")
hook.Remove("PDTestEvent", "PDTestHook")
hook.Remove("PDTestEvent", "PDLateHook")
FindMetaTable, hook.GetTable, net.BytesWritten = realFMT, realGT, realBW
net.Incoming, net.ReadHeader, util.NetworkIDToString, net.Receivers = realInc, realRH, realNIS, realRecv
for _, x in ipairs(ents.FindByClass("pd_leaky")) do x:Remove() end
e:Remove()
staff:Remove()
cit:Remove()
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
PerfDebugTests()

-- Cigarettes, alcohol and stimulants (sv_livingcity_vices.lua), and who a nightmare takes
function ViceTests()
section("Cigarettes, alcohol and stimulants; nobody opts out of a nightmare")
local errs0 = #_errors
local p = newPlayer("ViceA", "citizen")
local q = newPlayer("ViceB", "citizen")
_run(3)
local okItems = true
for _, id in ipairs({ "cig_union", "cig_rolled", "beer", "vodka", "moonshine", "stimulant" }) do if not (LCS.Items[id] and LCS.Items[id].use == "vice") then okItems = false end end
ok(okItems and LCS.GoodsById.cig_union and LCS.GoodsById.vodka and LCS.BlackById.cig_rolled and LCS.BlackById.beer and LCS.BlackById.moonshine and LCS.BlackById.stimulant,
    "cigarettes, alcohol and stimulants exist: Union cigarettes and vodka at the Commissary, the rest on the black market")
ok(LCS.Items.stimulant.contraband and LCS.Items.moonshine.contraband and not LCS.Items.cig_union.contraband, "(the black market's are contraband; the Union's aren't)")
ok(LCS.GoodsById.cig_union.minStanding == 75 and LCS.GoodsById.vodka.minStanding == 150, "Union cigarettes from standing 75, vodka from 150")
-- a cigarette steadies the shakes
p:SetNW2Float("lc_shaken_until", CurTime() + 100)
LC.GiveItem(p, "cig_union", 1)
ok(LC.ItemUse(p, "cig_union") and not LC.HasItem(p, "cig_union") and not LC.Shaken(p), "a cigarette is smoked from your pockets, and steadies the shakes")
-- drink: drunker with each, a tenth less from a hit, then sick
LC.GiveItem(p, "beer", 1)
LC.GiveItem(p, "vodka", 1)
LC.ItemUse(p, "beer")
ok(LC.Drunk(p) == 1 and LC.HasItem(p, "bottle_empty"), "beer: a little drunk (and the bottle's left)")
LC.ItemUse(p, "vodka")
local dmg = { ScaleDamage = function(self, f) self.f = f end }
hook.t.EntityTakeDamage.LivingCityVices(p, dmg)
ok(LC.Drunk(p) == 3 and dmg.f == 0.9, "vodka: drunker; tipsy, you take a tenth less from a hit")
p.lcSoberAt = CurTime() - 1
_run(1.1)
ok(LC.Drunk(p) == 2, "it wears off, one at a time")
LC.SetDrunk(p, 5)
local bad = LCS.Items.moonshine.badChance
LCS.Items.moonshine.badChance = 0
LC.GiveItem(p, "moonshine", 1)
LC.ItemUse(p, "moonshine")
LCS.Items.moonshine.badChance = bad
ok(LC.Drunk(p) == 3, "too much: you throw up, and sober up some")
LC.SetDrunk(p, 0)
-- a stimulant: wide awake, no sleep, no dreams; a second hurts; then the crash
LC.GiveItem(p, "stimulant", 2)
local awakeS = p.lcAwakeSince
p.lcAwakeSince = CurTime() - 100000 -- (up far too long: exhausted by their own clock, not lights out)
p:SetNW2Float("lc_groggy_until", CurTime() + 100)
LC.RestTick(CurTime())
local tiredBefore = p:GetNW2Bool("lc_tired", false)
LC.ItemUse(p, "stimulant")
LC.RestTick(CurTime())
ok(tiredBefore and not p:GetNW2Bool("lc_tired", false) and LC.TiredDue(p) >= p:GetNW2Float("lc_wired_until", 0) - 1 and p:GetNW2Float("lc_groggy_until", 0) == 0,
    "exhausted after a day awake, a stimulant opens your eyes for as long as it lasts (the owner, 23 November)")
p:SetNW2Float("lc_wired_until", 0)
LC.RestTick(CurTime())
local tiredAgain = p:GetNW2Bool("lc_tired", false)
p.lcDreaming = "plane"
LC.RestTick(CurTime())
ok(tiredAgain and not p:GetNW2Bool("lc_tired", false), "in a dream nobody is tired: no eyelids, no weakness (the owner, 23 November)")
p.lcDreaming = nil
p:SetNW2Float("lc_wired_until", CurTime() + 900)
p.lcAwakeSince = awakeS
LC.RestTick(CurTime())
local okS, whyS = LC.SleepIn(p, nil)
ok(LC.Wired(p) and not okS and string.find(tostring(whyS), "wired", 1, true), "a stimulant: you can't fall asleep", whyS)
local hp = p:Health()
local okS2 = LC.ItemUse(p, "stimulant")
ok(not okS2 and p:Health() == hp and LC.HasItem(p, "stimulant"), "a second is refused until you've slept and dreamt properly (the owner, 8 November)")
p:SetPData("lc_stim_locked", "0")
LC.TakeItem(p, "stimulant", 1)
p:SetNW2Float("lc_wired_until", CurTime() - 1)
_run(1.1)
ok(LC.Crashing(p), "when it wears off you crash (no running for a while)")
-- who a nightmare takes: the opted out too, never the wired
p:SetNW2Float("lc_crash_until", 0)
p.lcSleep, q.lcSleep = { t0 = CurTime(), done = CurTime() + 600 }, { t0 = CurTime(), done = CurTime() + 600 }
p:SetPData("lc_dream_optout", "1")
local function Has(list, x) for _, v in ipairs(list) do if v == x then return true end end return false end
ok(Has(LC.DreamSleepers("happy"), p) and Has(LC.DreamSleepers("happy"), q), "an old opt-out doesn't count: nobody opts out of any dream (the owner, 8 November)")
ok(Has(LC.DreamSleepers("nightmare"), p), "and a nightmare takes everyone asleep")
q:SetNW2Float("lc_wired_until", CurTime() + 60)
ok(not Has(LC.DreamSleepers("nightmare"), q), "(only a stimulant keeps you out of one)")
p.lcSleep, q.lcSleep = nil, nil
p:SetPData("lc_dream_optout", "0")
q:SetNW2Float("lc_wired_until", 0)
-- how a dream you played leaves you (the owner, 8 November: nothing the Combine would give)
local cr, xp0 = p:GetNW2Int("lce_credits", 0), p:GetNW2Int("lcf_xp", 0)
p:SetHealth(50)
p:SetNW2String("lcf_faction", "citizen")
local dealer = ents.Create("lc_dealer")
dealer:SetPos(Vector(500, 600, 0))
local n0 = #net.sent
LC.DreamOutcome(p, "won", "The Patrol Maze")
local whispered = false
for k = n0 + 1, #net.sent do local m = net.sent[k] if m.name == "lc_vice" and m.data[1] == "whisper" and m.to == p then whispered = true end end
ok(LC.Unbroken(p) and LC.SecondWind(p) and p:Health() == p:GetMaxHealth() and p:GetNW2Int("lce_credits", 0) == cr and p:GetNW2Int("lcf_xp", 0) == xp0,
    "won: Unbroken and a second wind for a day, healthy; no credits, no experience")
ok(whispered, "a citizen also hears a Vortigaunt's whisper: where a dealer or a rebel cache is")
p:SetNW2String("lcf_faction", "resistance")
local had = (LC.HasItem(p, "cig_rolled") and 1 or 0) + (LC.HasItem(p, "moonshine") and 1 or 0) + (LC.HasItem(p, "stimulant") and 1 or 0)
LC.DreamOutcome(p, "won", "The Patrol Maze")
local has = (LC.HasItem(p, "cig_rolled") and 1 or 0) + (LC.HasItem(p, "moonshine") and 1 or 0) + (LC.HasItem(p, "stimulant") and 1 or 0)
ok(has > had or LC.HasItem(p, "stimulant"), "the Resistance wake with something a Vortigaunt pressed into their hand")
dealer:Remove()
p:SetNW2String("lcf_faction", "citizen")
-- Unbroken: Breen's water can't touch them, and no nightmare can take them
p.lcSleep = { t0 = CurTime(), done = CurTime() + 600 }
ok(not Has(LC.DreamSleepers("nightmare"), p) and Has(LC.DreamSleepers("happy"), p), "Unbroken: no nightmare can take them (other dreams still can)")
p.lcSleep = nil
p:SetNW2Float("lc_unbroken_until", 0)
p:SetNW2Float("lc_secondwind_until", 0)
-- asleep in a Combine-only zone: spared
local realCZ = LC.CombineZoneAt
LC.CombineZoneAt = function(pos) return pos.x > 99000 end
q:SetPos(Vector(100000, 0, 0))
q.lcSleep = { t0 = CurTime(), done = CurTime() + 600 }
ok(not Has(LC.DreamSleepers("nightmare"), q) and Has(LC.DreamSleepers("neutral"), q), "asleep inside a Combine-only zone: spared any nightmare")
q.lcSleep = nil
LC.CombineZoneAt = realCZ
LC.DreamOutcome(p, "time", "The Patrol Maze")
ok(p:GetNW2Int("lce_credits", 0) == cr and not LC.DreamScarred(p) and not LC.Unbroken(p), "still in it at the end: nothing either way")
-- lost: 30 off the health limit until a night's sleep begun after it
p:SetMaxHealth(100)
p:SetHealth(100)
p.lcSleep = { t0 = CurTime() - 5, done = CurTime() + 600 }
LC.DreamOutcome(p, "out", "The Patrol Maze")
ok(LC.DreamScarred(p) and p:GetMaxHealth() == 70 and p:Health() == 70, "lost every life: 30 off your health")
hook.Run("LivingCitySlept", p)
ok(LC.DreamScarred(p) and p:GetMaxHealth() == 70, "(finishing the same night's sleep doesn't clear it)")
_run(0.2)
p.lcSleep = { t0 = CurTime(), done = CurTime() + 600 }
hook.Run("LivingCitySlept", p)
ok(not LC.DreamScarred(p) and p:GetMaxHealth() == 100, "the next full night's sleep does")
p.lcSleep = nil
p:SetNW2Float("lc_shaken_until", 0)
for _, x in ipairs({ p, q }) do x:SetPos(Vector(-122000, -122000, 0)) end
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
ViceTests()

