function QuickMoreTests()
section("More on F2: Inside, Freq 7, Me, a sentence, the Administrator's orders, a senior unit's sweep")
local far = Vector(-150000, 150000, 0)
local S0 = Vector(-90000, 90000, 0) -- (out of everyone's way)
for _, other in ipairs(player.GetAll()) do
    if other:GetPos():DistToSqr(S0) < 5000 * 5000 then other:SetPos(far) end
end
for n in pairs(LC.NPCs) do
    if IsValid(n) and n:GetPos():DistToSqr(S0) < 6000 * 6000 then n:SetPos(Vector(-400000, 400000, 0)) end
end
local notes = {}
local nw = LC.Notice
LC.Notice = function(p, kind, title, text, secs)
    notes[#notes + 1] = { p = p, t = tostring(title) .. ": " .. tostring(text) }
    return nw(p, kind, title, text, secs)
end
local function Told(p, needle)
    for i = #notes, 1, -1 do if notes[i].p == p and string.find(notes[i].t, needle, 1, true) then return true end end
    return false
end
local function Last(p) for i = #notes, 1, -1 do if notes[i].p == p then return notes[i].t end end return "" end
local function SentTo(name, p, from)
    for i = from + 1, #net.sent do
        local m = net.sent[i]
        if m.name == name then
            if m.to == p then return m end
            if istable(m.to) then for _, q in ipairs(m.to) do if q == p then return m end end end
        end
    end
    return nil
end

-- the Insider: what F2 > Inside greys out, and why
local ins = newPlayer("QMInsider", "cp")
ins:SetPos(S0)
ok(LC.QuickInfo(ins).ins == nil, "an ordinary unit's F2 has no Inside")
LC.StoryFlag(ins, "insider", true)
local nosy = newPlayer("QMNosy", "citizen")
nosy:SetPos(S0 + Vector(0, 200, 0))
local t = LC.QuickInfo(ins)
ok(t.ins and t.ins.watched and string.find(t.ins.watched, "hear", 1, true), "Inside: someone close enough to hear: greyed, and F2 says why", t.ins and t.ins.watched)
nosy:SetPos(far)
t = LC.QuickInfo(ins)
ok(t.ins and not t.ins.watched and t.ins.wait.tip == 0, "nobody watching: open now")
ok(t.ins.commissary == false, "away from the Commissary: supplies, the filters and the food greyed (Commissary only)")
local okT = LC.InsiderTip(ins, "they're coming tonight")
t = LC.QuickInfo(ins)
ok(okT and t.ins.wait.tip > 100 and t.ins.wait.tip <= 120, "after a tip-off, F2 says when the next one is open", t.ins.wait.tip)
LC.StoryFlag(ins, "insider", false)
ins:SetPos(far)

-- the Resistance: call for backup on Freq 7
local reb = newPlayer("QMRebel", "resistance", nil, 150) -- (a Member: fighters follow them)
local mate = newPlayer("QMMate", "resistance", nil, 150)
local cit = newPlayer("QMCitizen", "citizen")
local okNR, whyNR = LC.RebelCallBackup(reb)
ok(not okNR and string.find(whyNR or "", "Freq 7 radio", 1, true), "no Freq 7 radio: no calling for backup (the owner, 9 November)", whyNR)
LC.GiveItem(reb, "radio_tuned") LC.GiveItem(mate, "radio_tuned") LC.GiveItem(reb, "radio_transmitter") LC.GiveItem(mate, "radio_transmitter") -- (a transmitter too: 13 November)
_radioUp(reb) -- (in hand: no psychic calls, 13 November)
reb:SetPos(S0) mate:SetPos(S0 + Vector(2500, 0, 0)) cit:SetPos(S0 + Vector(0, 2500, 0))
mate.chat, cit.chat = {}, {}
local f1, fs1 = LC.Spawners.rebel(S0 + Vector(300, 0, 0))
local f2, fs2 = LC.Spawners.rebel(S0 + Vector(-300, 0, 0))
local f3, fs3 = LC.Spawners.rebel(S0 + Vector(0, 300, 0))
local f4, fs4 = LC.Spawners.rebel(S0 + Vector(0, -350, 0))
fs3.post = true -- (a lookout on his post never leaves it)
local before = #net.sent
local okB, sent = LC.RebelCallBackup(reb)
ok(okB and sent == 3, "Call for backup: idle fighters nearby come, as many as the squad has room for (3 here)", tostring(sent) .. " " .. Last(reb))
ok(fs3.follow == nil and ((fs1.follow == reb and 1 or 0) + (fs2.follow == reb and 1 or 0) + (fs4.follow == reb and 1 or 0)) == 3,
    "they stay with the caller, as if asked (a lookout keeps his post)")
ok(has(mate.chat, "needs backup"), "every Resistance player hears it on Freq 7", mate.chat[#mate.chat])
ok(not has(cit.chat, "needs backup"), "(a citizen without a Freq 7 radio hears nothing)")
ok(SentTo("lc_cpmark", mate, before) ~= nil and SentTo("lc_cpmark", cit, before) == nil, "the Resistance sees where they are, nobody else does")
local okB2, whyB2 = LC.RebelCallBackup(reb)
ok(not okB2 and string.find(whyB2 or "", "Again in", 1, true), "once every two minutes", whyB2)
ok((LC.QuickInfo(reb).reb or {}).backup > 0, "(and F2 greys it with how long)")
for _, n in ipairs({ f1, f2, f4 }) do local st = LC.NPCs[n] if st and st.follow then LC.DismissFollower(n, st, true) end end
-- a Sympathizer: heard, but fighters only follow Members and up
local sym = newPlayer("QMSym", "resistance")
LC.GiveItem(sym, "radio_tuned") LC.GiveItem(sym, "radio_transmitter") _radioUp(sym)
sym:SetPos(S0 + Vector(0, -200, 0))
local okS, sentS = LC.RebelCallBackup(sym)
ok(okS and sentS == 0 and Told(sym, "Members and up"), "a Sympathizer's call is heard, but no fighters come", Last(sym))
-- the Resistance's reserve too low (sv_livingcity_manpower.lua): nobody can be spared
_setcvar("lc_manpower", 1)
local pool = LC.ManpowerPool("rebel")
local had = pool.reserve
pool.reserve = 0
mate:SetPos(S0 + Vector(100, 100, 0))
_radioUp(mate)
local okR, sentR = LC.RebelCallBackup(mate)
ok(okR and sentR == 0 and Told(mate, "can't spare"), "with the reserve run down, the call goes out but no fighters come", Last(mate))
pool.reserve = had
_setcvar("lc_manpower", 0)
local okC = LC.RebelCallBackup(cit)
ok(not okC, "only the Resistance calls for backup on Freq 7")
-- send my position
mate:SetPos(S0 + Vector(2500, 0, 0))
mate.chat = {}
before = #net.sent
ok(LC.RebelSendPosition(reb) and #mate.chat == 1 and SentTo("lc_cpmark", mate, before) ~= nil, "Send my position: on Freq 7, and marked for the Resistance")
local okP2, whyP2 = LC.RebelSendPosition(reb)
ok(not okP2 and string.find(whyP2 or "", "Again in", 1, true), "(not twice in a row)", whyP2)
-- guide me to rebel ground, and to the lab: a marker, and the trail follows it
local rg = LC.NearestRebelGround(reb:GetPos())
local okG, whyG = LC.QuickMore(reb, "guide", "rebel")
if rg then
    ok(okG and reb.lcWaypoint and LC.GuideGoal(reb) == rg, "Guide me to rebel ground: marked, and the trail leads there", whyG)
    reb:SetPos(rg)
    ok(LC.GuideGoal(reb) == nil, "(there: the guidance ends)")
else
    ok(not okG and string.find(whyG or "", "no rebel ground", 1, true), "no rebel ground on the map: it says so", whyG)
end
ok(not LC.QuickMore(cit, "guide", "rebel"), "(only the Resistance is guided to rebel ground)")
reb:SetPos(S0)

-- a citizen: Me >
cit:SetPos(S0 + Vector(0, 400, 0))
cit:SetPData("lce_standing", 120)
local m = LC.QuickInfo(cit).me
ok(m and m.work and m.home and m.standing == 120 and m.next == 150 and string.find(m.nextWhat or "", "foreman", 1, true),
    "a citizen's F2 knows their work, rations, home and standing, and the next milestone (foreman at 150)", m and tostring(m.next))
ok(LC.QuickInfo(reb).me == nil and LC.QuickInfo(cit).reb == nil, "(each side hears only its own)")
LC.QuickMore(cit, "rations")
ok(Told(cit, "My rations") and Told(cit, "ration card"), "My rations: when the next is, and the cards held", Last(cit))
LC.QuickMore(cit, "work")
ok(Told(cit, "Find work"), "Find work", Last(cit))
LC.QuickMore(cit, "home")
ok(Told(cit, "My home"), "My home and rent", Last(cit))
LC.QuickMore(cit, "standing")
ok(Told(cit, "Civil Standing 120") and Told(cit, "Not wanted"), "My standing", Last(cit))
cit.lcGraceUntil = 0
LC.ReportCrime(cit, "Theft", 60)
LC.QuickMore(cit, "standing")
ok(Told(cit, "WANTED: Theft"), "wanted: it says so, and for what", Last(cit))
LC.ClearWanted(cit)
-- a prisoner: My sentence
local okN, whyN = LC.QuickMore(cit, "sentence")
ok(not okN and string.find(whyN or "", "not serving", 1, true), "no sentence out of a cell", whyN)
LC.Prisoners[cit] = { untilT = CurTime() + 125, reason = "Theft" }
LC.QuickMore(cit, "sentence")
ok(Told(cit, "You're in for: Theft") and Told(cit, "2:0"), "My sentence: what you're in for, and how long is left", Last(cit))
LC.Prisoners[cit] = nil
-- through the menu's own message, answered with what F2 greys
before = #net.sent
cit.lcQuickMoreNext = 0
net._q = { "standing", "", NULL }
net["recv_lc_quickmore"](0, cit)
ok(Told(cit, "Civil Standing") and SentTo("lc_quick_info", cit, before) ~= nil, "(from F2: done, and F2 hears what's greyed now)")

-- the City Administrator
local adm = newPlayer("QMAdmin", "admin")
local unit = newPlayer("QMUnit", "cp")
local staffer = newPlayer("QMStaff", "citizen")
staffer.IsAdmin = function() return true end
adm:SetPos(S0 + Vector(500, 500, 0)) unit:SetPos(S0 + Vector(600, 0, 0)) staffer:SetPos(S0 + Vector(0, 600, 0))
local okA, whyA = LC.AdminOrderArrest(adm, cit)
ok(okA and LC.PlayerIsWanted(cit) and cit:GetNW2String("lc_wanted_reason", "") == "By order of the Administrator", "Order the arrest: wanted, by order of the Administrator", whyA)
ok(cit:GetNW2Bool("lc_bolo", false) and Told(cit, "ordered your arrest"), "every unit has a BOLO, and they're told")
LC.ClearWanted(cit)
local okA2, whyA2 = LC.AdminOrderArrest(adm, cit)
ok(not okA2 and string.find(whyA2 or "", "Not yet", 1, true), "once every five minutes", whyA2)
ok((LC.QuickInfo(adm).adm or {}).arrest > 0, "(and F2 greys it with how long)")
adm.lcArrestNext = 0
ok(select(2, LC.AdminOrderArrest(adm, unit)) == "Not one of the city's own.", "never a unit")
ok(select(2, LC.AdminOrderArrest(adm, staffer)) == "Not a member of staff.", "never staff")
ok(not LC.AdminOrderArrest(unit, cit) and not LC.PlayerIsWanted(cit), "only the Administrator orders arrests")
for i = #(LC.BOLOs or {}), 1, -1 do if string.find(LC.BOLOs[i].text or "", "By order of the Administrator", 1, true) then table.remove(LC.BOLOs, i) end end
if LC.SyncBolos then LC.SyncBolos() end
-- open my tablet
before = #net.sent
ok(LC.QuickMore(adm, "office") and SentTo("lc_admin_office", adm, before) ~= nil, "Open my tablet: the office opens")
ok(not LC.QuickMore(cit, "office"), "(not for anyone else)")
-- the guards: hold here, and back to following
local okG0 = LC.AdminGuardOrder(adm, "hold")
local g = LC.Spawners.cop(adm:GetPos() + Vector(80, 0, 0))
LC.AdminGuards[g] = adm
ok(not okG0 and LC.AdminGuardOrder(adm, "hold") and adm.lcGuardHold, "Command the guards: hold here (not with no guards)")
local holdAt = adm:GetPos()
adm:SetPos(S0 + Vector(3500, 3500, 0))
LC.AdminGuardTick(CurTime())
ok(g:GetPos():DistToSqr(holdAt) < 300 * 300, "holding: they stay where she left them, however far she goes", tostring(g:GetPos()))
ok((LC.QuickInfo(adm).adm or {}).hold == true, "(F2 shows they're holding)")
ok(LC.AdminGuardOrder(adm, "follow") and adm.lcGuardHold == nil, "Follow me")
LC.AdminGuardTick(CurTime())
ok(g:GetPos():DistToSqr(adm:GetPos()) < 300 * 300, "following again: back at her side", tostring(g:GetPos()))
ok(not LC.AdminGuardOrder(cit, "hold"), "(only the Administrator commands them)")
for n, who in pairs(LC.AdminGuards) do if who == adm then if IsValid(n) then n:Remove() end LC.AdminGuards[n] = nil end end

-- a senior unit: call a sweep or a raid
local dl = newPlayer("QMLeader", "cp", nil, 600) -- (Division Leader)
local mc = newPlayer("QMMetro", "cp", nil, 150)
dl:SetPos(S0 + Vector(-500, 0, 0)) mc:SetPos(S0 + Vector(-600, 0, 0))
LC.EndEvent(true)
LC.OfficerSweepReset()
local pend = LC.PendingEvent
LC.PendingEvent = nil
ok(string.find(LC.OfficerSweepWhyNot(mc, "sweep") or "", "Division Leaders", 1, true), "a Metrocop can't call one")
ok(LC.QuickInfo(dl).sweep ~= nil and LC.QuickInfo(mc).sweep == nil, "(F2's Call a sweep > is for Division Leaders and up)")
local eb = LC.EndingBusy
LC.EndingBusy = function() return true end
ok(string.find(LC.OfficerSweepWhyNot(dl, "sweep") or "", "dreams", 1, true), "not while the city dreams or ends")
LC.EndingBusy = eb
ok(LC.OfficerSweepWhyNot(dl, "sweep") == nil, "a Division Leader can, with the city quiet", LC.OfficerSweepWhyNot(dl, "sweep"))
unit.chat = {}
ok(not LC.OfficerCallSweep(dl, "sweep") and LC.Event ~= "sweep", "not without the radio up (an HQ call, the owner, 13 November)")
_radioUp(dl)
ok(LC.OfficerCallSweep(dl, "sweep") and LC.Event == "sweep" and has(unit.chat, "orders a contraband sweep"), "the sweep starts (the city's own event), and units hear who ordered it", unit.chat[#unit.chat])
ok(string.find(LC.OfficerSweepWhyNot(dl, "raid") or "", "something on", 1, true), "not while the city has something on (a curfew, say)")
LC.EndEvent(true)
ok(string.find(LC.OfficerSweepWhyNot(dl, "raid") or "", "Dispatch allows another", 1, true), "one every fifteen minutes, city-wide")
LC.OfficerSweepNext = 0
ok(string.find(LC.OfficerSweepWhyNot(dl, "raid") or "", "Too soon after the last one", 1, true), "and the city's own pace: half the usual gap after any event")
LC.OfficerSweepReset()
LC.PendingEvent = "rations"
ok(string.find(LC.OfficerSweepWhyNot(dl, "raid") or "", "planned", 1, true), "not with the city's own next event about to begin")
LC.PendingEvent = pend

LC.Notice = nw
for _, n in ipairs({ f1, f2, f3, f4 }) do if IsValid(n) then n:Remove() end LC.NPCs[n] = nil end
for _, p in ipairs({ ins, nosy, reb, mate, cit, sym, adm, unit, staffer, dl, mc }) do LC.ClearWanted(p) p:SetPos(far) end
end
QuickMoreTests()

section("The v2.7 pieces: stamina, brandishing, obituaries, detentions, citizen numbers, the Administration path")
;(function()
    -- stamina
    local jogger = newPlayer("Jogger", "citizen")
    jogger.keys = { [IN_SPEED] = true }
    jogger.vel = Vector(250, 0, 0)
    for _ = 1, 100 do LCS.Tick(CurTime(), 0.2) end
    ok(jogger:GetNW2Float("lc_stamina", 100) == 0 and jogger:GetNW2Bool("lc_winded", false), "running tires you out: winded", jogger:GetNW2Float("lc_stamina", 100))
    jogger.keys, jogger.vel = nil, nil
    for _ = 1, 5 do LCS.Tick(CurTime() + 5, 0.2) end
    ok(jogger:GetNW2Bool("lc_winded", false), "and you stay winded a while")
    for _ = 1, 30 do LCS.Tick(CurTime() + 5, 0.2) end
    ok(not jogger:GetNW2Bool("lc_winded", false) and jogger:GetNW2Float("lc_stamina", 0) > 50, "rested, you get your breath back", jogger:GetNW2Float("lc_stamina", 0))
    jogger:SetNW2Float("lcn_hunger", 20)
    jogger:SetNW2Float("lc_rested_until", 0)
    local base = LCS.RegenMul(jogger)
    jogger:SetNW2Float("lcn_hunger", 80)
    jogger:SetNW2Float("lc_rested_until", CurTime() + 1000)
    ok(base == 1 and math.abs(LCS.RegenMul(jogger) - 1.5) < 0.01, "slept well and fed: your breath comes back faster", LCS.RegenMul(jogger))
    jogger:SetPos(Vector(-30000, 30000, 0))
    -- guns: on the streets, any gun in a citizen's hand is wanted at once
    local sbs, irz, cza, rcs, rsf, us, moh, nrz, ncz = LC.SeenBySecurity, LC.InRebelZone, LC.CombineZoneAt, LC.RebelCanSee, LC.RebelSetFoe, LC.UnitSees, LC.MakeOneHostile, LC.NearRebelZone, LC.NearCombineZone
    local waver = newPlayer("Waver", "citizen")
    if not waver:HasWeapon("weapon_pistol") then waver:Give("weapon_pistol") end
    waver:SelectWeapon("weapon_pistol")
    LC.SeenBySecurity = function() return true end
    LC.InRebelZone = function() return false end LC.NearRebelZone = LC.InRebelZone
    LC.CombineZoneAt = function() return nil end LC.NearCombineZone = LC.CombineZoneAt
    LC.BrandishTick(CurTime())
    ok(LC.PlayerIsWanted(waver) and has(waver.chat, "Weapon! Drop it"), "a citizen seen with a gun on the streets: wanted at once")
    ok(not waver:GetNW2Bool("lc_carry_lowered", false) and not LCL.Lowered(waver), "and on the streets a gun isn't carried lowered")
    LC.ClearWanted(waver)
    -- rebel ground: walking in with a gun up, a card; the fighters stand to; 10 seconds, then they fire
    LC.InRebelZone = function() return true end LC.NearRebelZone = LC.InRebelZone
    local fake = LC.Spawners.citizen(waver:GetPos() + Vector(200, 0, 0))
    local fst = LC.NPCs[fake]
    fst.role = "rebel"
    LC.RebelCanSee = function() return true end
    local foes = {}
    LC.RebelSetFoe = function(n, st2, e) foes[#foes + 1] = e end
    waver.chat = {}
    local t0 = CurTime()
    LC.BrandishTick(t0)
    ok(waver:GetNW2Bool("lc_carry_lowered", false) and waver:GetNW2Bool("lc_raised", false) and not LCL.Lowered(waver), "walking onto rebel ground with a gun out: it's still up")
    ok(has(waver.chat, "Lower that gun") and fst.lcAimAt == waver, "the fighters stand to, guns on you, and tell you to lower it")
    LC.BrandishTick(t0 + 4.5)
    ok(has(waver.chat, "Watch what you're doing"), "and again, a few seconds on")
    LC.BrandishTick(t0 + 6)
    ok(#foes == 0, "they give you time")
    LC.BrandishTick(t0 + 11)
    local allW = #foes > 0
    for _, e in ipairs(foes) do if e ~= waver then allW = false end end
    ok(allW, "still up after ten seconds: they open fire (on you, and only you)", #foes)
    waver:SetNW2Bool("lc_raised", false)
    foes = {}
    LC.BrandishTick(t0 + 20) LC.BrandishTick(t0 + 40)
    ok(#foes == 0 and LCL.Lowered(waver), "lowered (hold R) on their ground: left alone")
    -- the Combine's ground: the same for a recruit or metrocop, with the Overwatch's soldiers
    fst.role = "citizen"
    LC.InRebelZone = function() return false end LC.NearRebelZone = LC.InRebelZone
    LC.CombineZoneAt = function() return { kind = "combine" } end LC.NearCombineZone = LC.CombineZoneAt
    local mc = newPlayer("Metrocop", "cp")
    if not mc:HasWeapon("weapon_pistol") then mc:Give("weapon_pistol") end
    mc:SelectWeapon("weapon_pistol")
    fst.role = "soldier"
    LC.UnitSees = function() return true end
    local aimed = {}
    LC.MakeOneHostile = function(n, st2, e) aimed[#aimed + 1] = e end
    LC.BrandishTick(t0)
    ok(mc:GetNW2Bool("lc_carry_lowered", false) and has(mc.chat, "lower your weapon"), "a recruit on the Combine's ground with a gun up: told to lower it")
    LC.BrandishTick(t0 + 11)
    local allMc = #aimed > 0
    for _, e in ipairs(aimed) do if e ~= mc then allMc = false end end
    ok(allMc, "still up after ten seconds: the soldiers open fire (on them, and only them)", #aimed)
    local dl = newPlayer("DivLeader", "cp")
    dl:SetNW2Int("lcf_rank", 3)
    LC.BrandishTick(t0 + 12)
    ok(not dl:GetNW2Bool("lc_carry_lowered", false), "a Division Leader carries as they like")
    dl:SetPos(Vector(-30000, 30000, 0))
    fst.role = "citizen"
    LC.SeenBySecurity, LC.InRebelZone, LC.CombineZoneAt, LC.RebelCanSee, LC.RebelSetFoe, LC.UnitSees, LC.MakeOneHostile, LC.NearRebelZone, LC.NearCombineZone = sbs, irz, cza, rcs, rsf, us, moh, nrz, ncz
    if IsValid(fake) then fake:Remove() end
    waver.active, mc.active = nil, nil
    waver:SetNW2Bool("lc_carry_lowered", false) mc:SetNW2Bool("lc_carry_lowered", false)
    waver:SetPos(Vector(-30000, 30000, 0)) mc:SetPos(Vector(-30000, 30000, 0))
    -- obituaries
    local dead = newPlayer("Departed", "citizen")
    dead:SetNW2String("lc_cid", "48213")
    local line = LC.Obituary(dead, dead, nil)
    ok(line and line:find("48213", 1, true) and line:find("died", 1, true), "an obituary names them and their citizen number", line)
    -- finding by citizen number
    ok(LC.FindPlayer("#48213") == dead and LC.FindPlayer("48213") == dead, "admin commands find a player by citizen number")
    -- longer detentions the longer you were wanted
    local held = newPlayer("HeldLong", "citizen")
    LC.SetWanted(held, 600, "test")
    held.lcWantedSince = CurTime() - 240
    LC.DetainOnTheSpot(held, nil, "test")
    local secs = LC.Detained[held] and (LC.Detained[held].untilT - CurTime()) or 0
    ok(secs > 55 and secs <= 60.5, "wanted four minutes: held on the street longer (up to a minute)", secs)
    LC.Detained[held] = nil held:Freeze(false) LC.ClearWanted(held)
    held:SetPos(Vector(-30000, 30000, 0))
    -- the Administration path
    local clerk = newPlayer("ClerkPath", "citizen")
    clerk:SetPData("lc_played_min", 0)
    LC.Bump(clerk, "clerk_shifts", 6)
    local h, n = LC.AdminHours(clerk)
    ok(n == 6 and math.abs(h - 2) < 0.01, "each Records Clerk shift counts towards the hours to run for City Administrator", h)
    clerk:SetPos(Vector(-30000, 30000, 0))
    -- a unit facing a locked door a kick would open is told how
    local kd = ents.Create("prop_door_rotating")
    kd.mapid = 7702
    kd:SetPos(Vector(-160600, 160600, 0))
    kd.locked = true
    ok(LC.KickWouldOpen(kd), "a locked hinged door: a kick would open it (and a unit facing it is told how)")
    LC.SetDoorTag(kd, "locked")
    ok(not LC.KickWouldOpen(kd), "an always-locked door: no reminder (a kick doesn't give)")
    LC.SetDoorTag(kd, nil)
    -- the City Administrator's office door
    local odoor = ents.Create("func_door")
    odoor.mapid = 7701
    odoor:SetPos(Vector(-160500, 160500, 0))
    LC.SetDoorTag(odoor, "office")
    local outsider = newPlayer("Outsider", "citizen")
    odoor.fired = {}
    ok(hook.Run("PlayerUse", outsider, odoor) == false and not has(odoor.fired, "Open") and has(outsider.chat, "Administrator's office"), "the Administrator's office: locked to a citizen")
    local boss = newPlayer("TheAdministrator", "admin")
    odoor.fired = {}
    hook.Run("PlayerUse", boss, odoor)
    ok(has(odoor.fired, "Unlock") and has(odoor.fired, "Open"), "and opens for the Administrator", table.concat(odoor.fired, ","))
    LC.SetDoorTag(odoor, nil)
    outsider:SetPos(Vector(-30000, 30000, 0)) boss:SetPos(Vector(-30000, 30000, 0))
end)()

section("Sealed directives: how the endings start, and the G-Man's hand")
;(function()
    _run(0.1) -- (the office's acts are noted once everything's loaded)
    _setcvar("lc_directives", 1)
    local S = LC.DirectiveState
    local calls = {}
    local te, ga = LC.TriggerEnding, player.GetAll
    LC.TriggerEnding = function(id, by, now) calls[#calls + 1] = { id = id, by = by, now = now } return true end
    S.offer, S.esc = nil, nil
    -- (anyone left in the post by an earlier test steps down, so the directive comes to this one)
    for _, p in ipairs(player.GetAll()) do
        if p:GetNW2String("lcf_faction", "") == "admin" then LC.SetFaction(p, "citizen", nil, true) end
    end
    -- the bus: cheap bread, full bowls and a bonus, with six or more about
    local admin = newPlayer("Administrator", "admin")
    local crowd = {}
    for i = 1, 6 do crowd[i] = newPlayer("Crowd" .. i, "citizen") end
    local h0 = LC.DirectiveHeat("bus")
    LC.DirectiveNote("prices", "0.75")
    LC.DirectiveNote("rations", "generous")
    local h1, open1 = LC.DirectiveHeat("bus")
    ok(h1 > h0 and not open1, "the riddle's acts warm a directive up", h1)
    LC.DirectiveNote("bonus", "factory")
    local h2, open2 = LC.DirectiveHeat("bus")
    ok(open2, "all of them, and its seal breaks", h2)
    -- the Administrator's: sign or refuse
    S.offer = { id = "bus" }
    LC.DirectiveRoute(S.offer, CurTime())
    ok(S.offer.stage == "admin" and S.offer.to == admin, "an Administrator playing now gets it")
    ok(admin:GetNW2Float("lc_directive_until", 0) > CurTime() and not admin:GetNW2Bool("lc_directive_urgent", false), "a bar on their screen says one's waiting, and how long is left")
    LC.DirectiveTick(S.offer.deadline - 4 * 60)
    ok(S.offer.called and admin:GetNW2Bool("lc_directive_urgent", false) and _lastnet("lc_gman_vision") ~= nil, "five minutes left: the G-Man calls them back to it, and the bar turns urgent")
    ok(LC.DirectiveAnswer(admin, "bus", false) and S.esc and S.esc.level == 1 and S.refusals.bus == 1, "refused: the G-Man's escalation begins")
    ok(admin:GetNW2Float("lc_directive_until", 0) == 0, "answered: the reminder goes")
    ok(_lastnet("lc_gman_vision") ~= nil, "and he appears to the Administrator")
    LC.DirectiveTick(CurTime() + 21 * 60)
    ok(S.esc and S.esc.spreading, "twenty minutes on, the infestation spreads")
    LC.DirectiveTick(CurTime() + 31 * 60)
    ok(S.offer and S.offer.id == "bus" and S.offer.stage == "admin", "thirty minutes on, he brings the same directive back")
    ok(LC.DirectiveAnswer(admin, "bus", true) and calls[#calls].id == "bus" and calls[#calls].now == true and S.esc == nil, "signed: the ending starts, and his hand comes off the city")
    -- an order from the office
    LC.AdminDo(admin, "weedkiller")
    ok(LC.WeedkillerBanned(), "the Administrator can ban weedkiller (one of the new orders)")
    -- nobody to answer: a superadmin's popup
    admin:SetNW2String("lcf_faction", "citizen")
    local boss = newPlayer("SuperBoss", "citizen") boss.superadmin = true boss.admin = true
    S.offer = { id = "marrow" }
    LC.DirectiveRoute(S.offer, CurTime())
    ok(S.offer.stage == "staff" and _lastnet("lc_directive_staff") ~= nil, "no Administrator: a superadmin's popup")
    -- nobody at all: ten minutes' grace, then the G-Man's vote
    local plain = newPlayer("Nobody", "citizen")
    player.GetAll = function() return { plain } end
    S.deciderLeftAt = CurTime()
    S.offer = { id = "fire" }
    LC.DirectiveRoute(S.offer, CurTime())
    ok(S.offer.stage == "waiting", "the last one to decide just left: it waits for them")
    LC.DirectiveTick(CurTime() + 11 * 60)
    ok(calls[#calls].id == "fire" and calls[#calls].now == false, "ten minutes and nobody back: the G-Man's vote")
    player.GetAll = ga
    -- the rival, and the recall (Civil Protection and the Administration vote, not citizens)
    local sittingAdm = newPlayer("SittingAdmin", "admin")
    local hopeful = newPlayer("Hopeful", "citizen")
    hopeful:SetPData("lc_played_min", 60 * 20)
    local ga2 = player.GetAll
    player.GetAll = function() return { sittingAdm, hopeful } end
    ok(LC.GmanRival() == hopeful and hopeful:GetNW2Float("lc_gman_rival_until", 0) > CurTime(), "after a refusal, the G-Man picks a rival who could run for the office")
    player.GetAll = ga2
    local unit = newPlayer("RecallUnit", "cp")
    local cit2 = newPlayer("RecallCitizen", "citizen")
    ok(LC.AdminVoter(unit) and not LC.AdminVoter(cit2), "Civil Protection votes on the Administrator; citizens don't")
    local noVote = true
    for _, f in ipairs({ "resistance", "vort", "zombie", "stalker" }) do
        local q = newPlayer("NoVote" .. f, "citizen")
        q:SetNW2String("lcf_faction", f)
        if LC.AdminVoter(q) then noVote = false end
        q:SetNW2String("lcf_faction", "citizen") -- (back as they were: a player left a stalker is put in the next Combine zone a later test makes)
        q:SetPos(Vector(-30000, 30000, 0))
    end
    ok(noVote, "nor do rebels, vortigaunts, stalkers or the infected")
    ok(LC.CallRecall(hopeful) and LC.Recall ~= nil, "the rival calls a recall")
    LC.Recall.votes[unit] = true
    LC.Recall.ends = CurTime() - 1
    ok(LC.RecallTick(CurTime()) and hopeful:GetNW2String("lcf_faction", "") == "admin" and sittingAdm:GetNW2String("lcf_faction", "") ~= "admin", "more yes than no: the Administrator is out, and the rival is in")
    LC.SetFaction(hopeful, "citizen", nil, true)
    for _, p in ipairs({ sittingAdm, hopeful, unit, cit2 }) do p:SetPos(Vector(-30000, 30000, 0)) end
    -- glimpses of him, as a directive warms
    local seer = newPlayer("Seer", "citizen")
    S.esc = { id = "bus", level = 1, at = CurTime(), returnAt = CurTime() + 9999, steps = {}, spreads = 0 }
    local mr = math.random
    math.random = function(a, b) if a == nil then return 0 end return mr(a, b) end
    seer.lcGlimpseNext = 0
    LC.GmanGlimpseTick(CurTime())
    math.random = mr
    ok(seer.lcGlimpseNext > CurTime(), "someone glimpses the G-Man about the city")
    S.esc = nil
    seer:SetPos(Vector(-30000, 30000, 0))
    -- dreams
    local dreamer = newPlayer("Dreamer", "citizen")
    _setcvar("lc_gman_dream_chance", 100)
    ok(LC.GmanDream(dreamer) == "riddle", "asleep, the G-Man recites a riddle")
    _setcvar("lc_gman_dream_chance", 30)
    -- All your base, the city's own way: the master data core decoded at the Resistance's lab
    S.coreDecodedAt = nil
    local _, openB0 = LC.DirectiveHeat("base")
    local carrier = newPlayer("CoreCarrier", "resistance")
    local sciNear = LC.ScientistNear
    LC.ScientistNear = function() return true end -- (at the lab, by the scientist)
    LC.GiveItem(carrier, "data_chip", 1)
    ok(LC.DecodeChip(carrier, "data_chip") and S.coreDecodedAt == nil, "an ordinary data chip decoded doesn't touch All your base")
    LC.GiveItem(carrier, "master_chip", 1)
    ok(LC.DecodeChip(carrier, "master_chip"), "(the master data core, decoded by the lab's scientist)")
    local hB, openB, wayB = LC.DirectiveHeat("base")
    ok(not openB0 and openB and wayB == "city" and hB == 1, "the master data core carried to the lab: All your base's seal breaks, the city's own way", tostring(openB0) .. " " .. tostring(wayB))
    local _, openB2 = LC.DirectiveHeat("base", CurTime() + 31 * 60)
    ok(not openB2, "for half an hour (then it's cold again)")
    LC.ScientistNear = sciNear
    S.coreDecodedAt = nil
    carrier:SetPos(Vector(-30000, 30000, 0))
    LC.TriggerEnding = te
    S.offer, S.esc, S.deciderLeftAt = nil, nil, nil
    for _, p in ipairs(crowd) do p:SetPos(Vector(-30000, 30000, 0)) end
    for _, p in ipairs({ admin, boss, plain, dreamer }) do p:SetPos(Vector(-30000, 30000, 0)) end
    boss.superadmin, boss.admin = false, false
    _setcvar("lc_directives", 0)
end)()

----------------------------------------------------------------------
-- The Combine's own ground (sv_livingcity_combineground.lua): soldiers stay in, citizens stay out,
-- a stalker clears up in there, rebel warnings, dead headcrabs (the owner, 7 November)
----------------------------------------------------------------------
function CombineSoldiersHomeTests()
section("Overwatch soldiers stay inside the Combine zones unless deployed")
local socioWas, skirmWas, evWas = LC.Socio, LC.Skirmish, LC.Event
LC.Socio, LC.Skirmish, LC.Event = "green", nil, nil
-- no Combine zone at all: today's behaviour
local stash = {}
for i = #LC.Zones, 1, -1 do if LC.Zones[i].kind == "combine" then table.insert(stash, LC.Zones[i]) table.remove(LC.Zones, i) end end
local s, sst = LC.Spawners.soldier(Vector(-190000, 186000, 0))
ok(IsValid(s) and sst ~= nil, "a soldier to watch")
if not IsValid(s) then for _, z in ipairs(stash) do table.insert(LC.Zones, z) end return end
sst.routeGroup = nil
ok(not LC.SoldierHomeRule() and not LC.SoldierGoHome(s, sst, CurTime(), false), "no Combine zone placed: soldiers patrol as they always did")
ok(LC.SoldierHomeSpawnPos() == nil, "(and spawn where they always did)")
local hq = LC.AddZone(Vector(-190000, 190000, 0), 400, "combine", 0)
ok(LC.SoldierHomeRule(), "a Combine zone placed, nothing serious going on: soldiers stay home")
ok(LC.SoldierGoHome(s, sst, CurTime(), false) and sst.dest ~= nil and LC.InCombineZone(sst.dest) == hq,
    "a soldier out in the street with nothing to do walks back into the Combine zone", sst.dest)
-- the city's own way of choosing (sv_livingcity.lua): idle, it heads home
LC.SetState(s, sst, "idle") sst.dest, sst.untilT = nil, 0
_run(0.3)
ok(sst.dest ~= nil and LC.InCombineZone(sst.dest) == hq, "left to the city, an idle soldier heads into the Combine zone, not a checkpoint or the streets", sst.dest)
-- inside, they walk about it or stand post, and never leave it
s:SetPos(Vector(-190000, 190000, 0))
for _ = 1, 6 do
    LC.SetState(s, sst, "idle") sst.dest = nil
    LC.SoldierGoHome(s, sst, CurTime(), false)
    if sst.dest and not LC.InCombineZone(sst.dest) then ok(false, "a soldier inside walked out of it", sst.dest) break end
end
ok(true, "inside, they walk from spot to spot in the zone or stand post")
local sp = LC.SoldierHomeSpawnPos()
ok(sp ~= nil and LC.InCombineZone(sp) == hq, "the city's own soldiers spawn inside the Combine zone, out of sight", sp)
-- deployed: out they go
local caller = newPlayer("BackupCaller", "cp")
caller:SetPos(Vector(-30000, 30000, 0))
for _, f in ipairs({ { "backupFor", caller }, { "questLock", true }, { "workEscort", caller }, { "raid", {} }, { "skirmish", {} }, { "responder", caller }, { "cleanGuard", caller } }) do
    sst[f[1]] = f[2]
    ok(not LC.SoldierGoHome(s, sst, CurTime(), false), "deployed (" .. f[1] .. "): the soldier goes where they're sent")
    sst[f[1]] = nil
end
LC.Socio = LCCP.SocioOrder[#LCCP.SocioOrder]
ok(LC.SoldiersDeployed() ~= nil and not LC.SoldierGoHome(s, sst, CurTime(), false), "sociostability at its worst: soldiers out on the streets", LC.SoldiersDeployed())
LC.Socio = "green"
LC.Skirmish = { units = {} }
ok(LC.SoldiersDeployed() ~= nil and not LC.SoldierHomeRule(), "a firefight with the Resistance: soldiers out")
LC.Skirmish = nil
LC.Event = "lockdown"
ok(LC.SoldiersDeployed() ~= nil and not LC.SoldierHomeRule(), "a lockdown: soldiers out")
LC.Event = nil
ok(LC.SoldierHomeRule(), "over: back to the rule")
-- metrocops still walk the streets
local cop, cpst = LC.Spawners.cop(Vector(-190000, 186000, 0))
ok(IsValid(cop) and not LC.SoldierGoHome(cop, cpst, CurTime(), false), "metrocops aren't kept in: they walk the streets as before")
if IsValid(cop) then cop:Remove() end
s:Remove()
caller:SetPos(Vector(-30000, 30000, 0))
LC.RemoveZone(hq)
for _, z in ipairs(stash) do table.insert(LC.Zones, z) end
LC.Socio, LC.Skirmish, LC.Event = socioWas, skirmWas, evWas
end
CombineSoldiersHomeTests()

function CombineCitizensOutTests()
section("Citizens stay out of the Combine zones; a stalker clears up in there")
local evWas = LC.Event
LC.Event = nil
local C = Vector(-190000, -190000, 0)
local hq = LC.AddZone(C, 400, "combine", 0)
local c, cst = LC.Spawners.citizen(C + Vector(1500, 0, 0))
ok(IsValid(c) and cst ~= nil, "a citizen to watch")
if not IsValid(c) then LC.RemoveZone(hq) LC.Event = evWas return end
cst.profile = cst.profile or {}
ok(LC.CitizenBarredAt(c, cst, C) and LC.GoTo(c, cst, C, false, nil) == false, "a citizen's walk can't end inside a Combine zone")
ok(LC.GoTo(c, cst, C + Vector(1200, 0, 0), false, nil), "(outside it, it can)")
cst.jailUntil = CurTime() + 100
ok(not LC.CitizenBarredAt(c, cst, C), "a prisoner may be taken in")
cst.jailUntil = nil
cst.questLock = true
ok(not LC.CitizenBarredAt(c, cst, C), "someone a job or story is about may be there")
cst.questLock = nil
LC.SetState(c, cst, "escorted")
ok(not LC.CitizenBarredAt(c, cst, C), "an arrestee being walked to a cell may be there")
LC.SetState(c, cst, "idle")
-- work in there isn't theirs
local function Find(job, id)
    for _, t in ipairs(LC.NPCWorkTasks[job] or {}) do if t.id == id then return t end end
end
local litter = Find("sanitation", "litter")
local can = LC.SpawnWorldItem("can_empty", C + Vector(50, 0, 0))
can.lcDroppedAt = CurTime() - 400
local plan = litter and litter.find(c, cst, CurTime())
ok(litter ~= nil and plan == nil, "litter inside a Combine zone: the sanitation worker leaves it", plan and plan.key)
local can2 = LC.SpawnWorldItem("can_empty", C + Vector(1300, 200, 0))
can2.lcDroppedAt = CurTime() - 400
plan = litter and litter.find(c, cst, CurTime())
ok(plan ~= nil and plan.key == "item" .. can2:EntIndex(), "litter outside it: picked up as usual", plan and plan.key)
can2:Remove()
-- one found inside is walked out, or put out of sight
c:SetPos(C)
LC.SetState(c, cst, "idle") cst.dest = nil
LC.CombineGroundTick(CurTime())
ok(cst.dest ~= nil and not LC.InCombineZone(cst.dest), "a citizen found inside a Combine zone is walked straight out", cst.dest)
LC.CombineGroundTick(CurTime() + 25)
ok(not IsValid(c) or not LC.InCombineZone(c:GetPos()), "one who can't find the way is put outside, out of sight", IsValid(c) and c:GetPos())
if IsValid(c) then c:Remove() end
-- the stalker: litter and a body in there
local body = ents.Create("prop_ragdoll") body:SetPos(C + Vector(-60, 40, 0)) body:Spawn()
body.lcBody = {}
-- (older than the longest wait for a player mortician: 200 seconds. A citizen given Union work as a
-- mortician by an earlier test stretches the wait from 60 to that)
table.insert(LC.Bodies, { ent = body, born = CurTime() - 250 })
local chores = LC.CombineChores(CurTime())
local seen = {}
for _, j in ipairs(chores) do if j.ent then seen[j.ent] = j.kind end end
ok(seen[can] == "item" and seen[body] == "body", "what needs clearing inside a Combine zone: the litter and the body", #chores)
_setcvar("lc_zone_stalkers", 1)
LC.ZoneStalkersStaff(CurTime())
local res
for _, r in pairs(LC.ZoneStalkers) do if r.zone == hq then res = r end end
ok(res ~= nil and IsValid(res.npc) and res.npc:GetClass() == "npc_stalker", "the zone's own stalker comes for it", res and IsValid(res.npc) and res.npc:GetClass())
ok(res ~= nil and not LC.IsSeen(res.npc:GetPos() + Vector(0, 0, 40)) and LC.InCombineZone(res.npc:GetPos()) == hq, "it appeared out of sight, inside the zone")
for _ = 1, 240 do
    _run(0.5)
    LC.ZoneStalkersTick(CurTime())
    if not IsValid(can) and not IsValid(body) then break end
end
ok(not IsValid(can) and not IsValid(body), "the stalker picks each up (drags the body), takes it off out of sight, and it's gone", tostring(IsValid(can)) .. " " .. tostring(IsValid(body)))
ok(res ~= nil and IsValid(res.npc) and res.chore == nil, "and the stalker stays, for the next job")
for i = #LC.Bodies, 1, -1 do if LC.Bodies[i].ent == body then table.remove(LC.Bodies, i) end end
LC.RemoveZone(hq)
LC.ZoneStalkersTick(CurTime())
ok(res == nil or not IsValid(res.npc), "(the zone gone, so is its stalker)")
LC.Event = evWas
end
CombineCitizensOutTests()

function CombineRebelWarningTests()
section("No rebel territory warning inside a Combine zone")
local X = Vector(-185000, 185000, 0)
-- the owner's map: rebel ground right over the nexus (a circle reaches as far up and down as out)
local rz = LC.AddZone(X + Vector(0, 0, 300), 400, "rebel", 0)
local cz = LC.AddZone(nil, nil, "combine", 0, { mins = X + Vector(-300, -300, -16), maxs = X + Vector(300, 300, 200) })
local p = newPlayer("NexusClerk", "citizen")
p:SetPos(X)
ok(LC.InRebelZone(X), "(the rebel zone reaches down into the nexus)")
ok(LC.RebelEdgeLevel(p) == 0, "standing in the Combine zone: no rebel territory warning")
_run(0.6)
ok(p:GetNW2Int("lc_rebelzone", 0) == 0, "(nothing on screen)")
p:SetPos(X + Vector(0, 0, 350))
ok(LC.RebelEdgeLevel(p) == 2, "upstairs, out of the Combine zone and in the rebel one: the warning", LC.RebelEdgeLevel(p))
p:SetPos(X + Vector(350, 0, 350))
ok(LC.RebelEdgeLevel(p) == 1 or LC.RebelEdgeLevel(p) == 2, "(and the one a step before it)")
p:SetPos(X + Vector(0, 0, 400 + 300 + 200))
ok(LC.RebelEdgeLevel(p) == 0, "(nowhere near: nothing)")
p:SetPos(Vector(-30000, 30000, 0))
LC.RemoveZone(cz)
ok(LC.RebelEdgeLevel(p) == 0, "(far away)")
p:SetPos(X)
ok(LC.RebelEdgeLevel(p) == 2, "with no Combine zone there, the rebel warning shows as before")
p:SetPos(Vector(-30000, 30000, 0))
LC.RemoveZone(rz)
end
CombineRebelWarningTests()

function CrabCarcassCleanupTests()
section("Dead headcrabs get cleared away")
local Y = Vector(-185000, -185000, 0)
local function Find(job, id)
    for _, t in ipairs(LC.NPCWorkTasks[job] or {}) do if t.id == id then return t end end
end
local npc = ents.Create("npc_citizen") npc:SetPos(Y + Vector(300, 0, 0)) npc:Spawn()
local st = { role = "citizen", state = "idle", profile = { job = "sanitation" } }
local litter = Find("sanitation", "litter")
local crab = LC.SpawnWorldItem("raw_headcrab", Y)
crab.lcBorn = CurTime() - 30
ok(litter ~= nil and litter.find(npc, st, CurTime()) == nil, "a headcrab just killed: left a while for a player to take")
crab.lcBorn = CurTime() - 100
local plan = litter and litter.find(npc, st, CurTime())
ok(plan ~= nil and plan.key == "item" .. crab:EntIndex(), "a dead headcrab left lying: the street cleaners pick it up too, not only the morgue", plan and plan.key)
local bag = Find("mortuary", "crabs")
local mplan = bag and bag.find(npc, st, CurTime())
ok(mplan ~= nil, "(the morgue still bags them)")
-- nobody about to see it: gone, the way bodies go
crab.lcBorn = CurTime() - 1000
local fresh = LC.SpawnWorldItem("raw_fastcrab", Y + Vector(100, 0, 0))
ok(LC.CarcassDecayTick(CurTime()) >= 1 and not IsValid(crab), "a dead headcrab nobody cleared or took, with nobody near: it's gone after a while (lc_body_time)")
ok(IsValid(fresh), "(a fresh one stays)")
fresh.lcBorn = CurTime() - 1000
local watcher = newPlayer("CrabWatcher", "citizen")
watcher:SetPos(Y + Vector(200, 0, 0))
LC.CarcassDecayTick(CurTime())
ok(not IsValid(fresh), "and with someone standing right there too (the owner, 11 November: gone after 5 minutes, seen or not)")
do
    local cooked = LC.SpawnWorldItem("cooked_headcrab", Y + Vector(100, 60, 0))
    local dropped = LC.SpawnWorldItem("scrap", Y + Vector(100, 120, 0))
    local placed = LC.SpawnWorldItem("scrap", Y + Vector(100, 180, 0))
    dropped.lcPocketDrop = true
    cooked.lcBorn, dropped.lcBorn, placed.lcBorn = CurTime() - 1000, CurTime() - 1000, CurTime() - 1000
    dropped.lcDroppedAt = CurTime() - 10
    LC.CarcassDecayTick(CurTime())
    ok(not IsValid(cooked), "cooked meat left lying goes the same way")
    ok(IsValid(dropped), "something out of a player's pockets, just let go of again: it stays")
    dropped.lcDroppedAt = CurTime() - 1000
    LC.CarcassDecayTick(CurTime())
    ok(not IsValid(dropped) and IsValid(placed), "five minutes after it was dropped it's gone; an item nobody dropped is left alone")
    placed:Remove()
    local cremator = ents.Create("npc_stalker") cremator:Spawn() cremator.lcCremator = true
    ok(LC.CarcassItem("npc_headcrab", cremator) == "cooked_headcrab" and LC.CarcassItem("npc_crow", cremator) == "cooked_bird"
        and LC.CarcassItem("npc_headcrab", nil) == "raw_headcrab", "what a Cremator burns to death is left cooked; anyone else's kill is raw")
end
watcher:SetPos(Vector(-30000, 30000, 0))
local can = LC.SpawnWorldItem("can_empty", Y + Vector(-100, 0, 0))
can.lcBorn = CurTime() - 1000
LC.CarcassDecayTick(CurTime())
ok(IsValid(can) and not IsValid(fresh), "only dead headcrabs go: other things on the ground stay")
can:Remove()
npc:Remove()
end
CrabCarcassCleanupTests()

function ZoneStalkerTests()
section("Each Combine zone's stalkers: terminals, repairs, the animation")
-- the animation: a likely name first, then the model's own list, by what's in the names
local fake = ents.Create("npc_stalker")
fake:SetModel("models/test_stalker_a.mdl")
fake.seqs = { console_work = 7 }
local n1, i1 = LC.StalkerConsoleSequence(fake, true)
ok(n1 == "console_work" and i1 == 7, "a model with one of the likely names: that one", tostring(n1) .. " " .. tostring(i1))
fake:SetModel("models/test_stalker_b.mdl")
fake.seqs = { typing_loop = 2 }
fake.GetSequenceList = function() return { [0] = "idle01", [1] = "walk_all", [2] = "typing_loop", [3] = "death_console", [4] = "beamattack" } end
local n2, i2 = LC.StalkerConsoleSequence(fake, true)
ok(n2 == "typing_loop" and i2 == 2, "none of them: the model's own sequence that sounds most like console work (not a death or an attack)", tostring(n2) .. " " .. tostring(i2))
ok(LC.StalkerSequenceUsed == "typing_loop" and string.find(LC.StalkerSummary(), "typing_loop", 1, true) ~= nil, "the one used is in the debug report", LC.StalkerSummary())
fake:SetModel("models/test_stalker_c.mdl")
fake.seqs = {}
fake.GetSequenceList = function() return { [0] = "idle01", [1] = "walk_all" } end
local n3 = LC.StalkerConsoleSequence(fake, true)
ok(n3 == nil and LC.StalkerSequenceUsed == "none found", "nothing like it: none (they just stand at the terminal), and the report says so")
fake:Remove()

local evWas = LC.Event
LC.Event = nil
_setcvar("lc_zone_stalkers", 1)
local Z = Vector(-195000, 195000, 0)
local hq = LC.AddZone(Z, 500, "combine", 0)
local term = LC.AddPoint(Z + Vector(200, 0, 0), 90, "sterm", 0)
local now = CurTime()
LC.ZoneStalkersStaff(now)
local res
for _, r in pairs(LC.ZoneStalkers) do if r.zone == hq then res = r end end
ok(res ~= nil and IsValid(res.npc), "a Combine zone gets its resident stalker, out of sight")
if not res then LC.RemovePoint(term) LC.RemoveZone(hq) LC.Event = evWas return end
LC.ZoneStalkersStaff(now)
local count = 0
for _, r in pairs(LC.ZoneStalkers) do if r.zone == hq then count = count + 1 end end
ok(count == 1, "(as many as lc_zone_stalkers: one)", count)
res.npc.seqs = { console_work = 3 }
LC.StalkerConsoleSequence(res.npc, true)
for _ = 1, 60 do
    _run(0.5)
    LC.ZoneStalkersTick(CurTime())
    if res.phase == "working" then break end
end
ok(res.phase == "working" and res.npc:GetPos():Distance(term.pos) < 60 and res.term and res.term.key == "p1",
    "with nothing to do, it goes to the stalker terminal placed in its zone", tostring(res.phase) .. " " .. tostring(res.npc:GetPos()))
ok(IsValid(res.ss) and res.ss:GetClass() == "scripted_sequence", "and works it, the console animation looping")
-- a broken streetlight in there: the stalker's job, not the city's repairmen
local lamp = ents.Create("lc_streetlight") lamp:SetPos(Z + Vector(-250, 150, 0)) lamp:Spawn()
lamp:SetNW2Bool("lc_broken", true)
lamp.lcBrokenAt = CurTime() - 1000
local fixer = ents.Create("npc_citizen") fixer:SetPos(Z + Vector(1500, 0, 0)) fixer:Spawn()
local fst = { role = "citizen", state = "idle", profile = { job = "maintenance" } }
local lampTask
for _, t in ipairs(LC.NPCWorkTasks.maintenance or {}) do if t.id == "lamp" then lampTask = t end end
ok(lampTask ~= nil and lampTask.find(fixer, fst, CurTime()) == nil, "a broken streetlight inside a Combine zone: the city's repairman leaves it")
fixer:Remove()
local wentOut = false
for _ = 1, 120 do
    _run(0.5)
    LC.ZoneStalkersTick(CurTime())
    if res.chore then wentOut = true end
    if not lamp:GetNW2Bool("lc_broken", false) then break end
end
ok(wentOut and not lamp:GetNW2Bool("lc_broken", false), "the stalker leaves its terminal and repairs it", tostring(lamp:GetNW2Bool("lc_broken", false)))
for _ = 1, 60 do
    _run(0.5)
    LC.ZoneStalkersTick(CurTime())
    if res.phase == "working" then break end
end
ok(res.phase == "working" and res.npc:GetPos():Distance(term.pos) < 60, "and goes back to the terminal after", res.phase)
local spk = ents.Create("lc_loudspeaker") spk:SetPos(Z + Vector(0, -250, 0)) spk:Spawn()
spk:SetNW2Bool("lc_broken", true)
spk.lcBrokenAt = CurTime() - 1000
for _ = 1, 120 do
    _run(0.5)
    LC.ZoneStalkersTick(CurTime())
    if not spk:GetNW2Bool("lc_broken", false) then break end
end
ok(not spk:GetNW2Bool("lc_broken", false), "a broken loudspeaker in there too")
-- the map's own Combine console props, with no point placed
LC.RemovePoint(term)
local con = ents.Create("prop_physics") con:SetModel("models/props_combine/combine_interface001.mdl") con:SetPos(Z + Vector(-150, -150, 0)) con:Spawn()
LC.StalkerConsolePropsReset()
local terms = LC.StalkerTerminals(hq, CurTime())
ok(#terms == 1 and terms[1].key == "e" .. con:EntIndex(), "no terminal point: a Combine console prop in the zone will do", #terms)
con:Remove()
LC.StalkerConsolePropsReset()
-- one built into the map (prop_static, read from the map file like the sinks and stoves)
local stWas = LC.StaticTerminals
ok(LC.IsStalkerConsoleModel("models/props_combine/combine_interface002.mdl") and not LC.IsStalkerConsoleModel("models/props_c17/furnituresink001a.mdl"),
    "the map file's Combine consoles are known by their model (and a sink isn't one)")
ok(LC.IsTerminalModel("models/props_combine/masterinterface.mdl") and LC.IsMasterTerminalModel("models/props_combine/masterinterface.mdl"),
    "(the heist's own check still knows the master interface: the stalkers' list doesn't replace it)")
LC.StaticTerminals = { { kind = "terminal", pos = Z + Vector(120, 120, 0), ang = Angle(0, 90, 0), model = "models/props_combine/combine_interface002.mdl" } }
local sterms = LC.StalkerTerminals(hq, CurTime())
local syaw = sterms[1] and ((sterms[1].yaw % 360) + 360) % 360 or -1
ok(#sterms == 1 and sterms[1].key == "s1" and math.abs(syaw - 270) < 1, "a Combine console built into the map will do too: the stalker stands in front of it, facing it", #sterms .. " " .. tostring(sterms[1] and sterms[1].key) .. " " .. syaw)
LC.StaticTerminals = stWas
ok(#LC.StalkerTerminals(hq, CurTime()) == 0, "(neither: it stands where it is)")
-- one killed is replaced, a while later, out of sight
local old = res.npc
old:SetHealth(0)
now = CurTime()
LC.ZoneStalkersThink(now)
ok(LC.ZoneStalkers[old] == nil, "a stalker killed is gone from the zone")
old:Remove()
LC.ZoneStalkersStaff(now + 10)
count = 0
for _, r in pairs(LC.ZoneStalkers) do if r.zone == hq then count = count + 1 end end
ok(count == 0, "(not replaced at once)")
LC.ZoneStalkersStaff(now + 125)
count = 0
for _, r in pairs(LC.ZoneStalkers) do if r.zone == hq then count = count + 1 res = r end end
ok(count == 1, "replaced a couple of minutes later", count)
_setcvar("lc_zone_stalkers", 0)
LC.ZoneStalkersStaff(now + 130)
ok(not IsValid(res.npc), "lc_zone_stalkers 0: none")
_setcvar("lc_zone_stalkers", 1)
-- (the loudspeaker's utility box goes with it, as in the game: it is only made here when the fifteen-second timer
-- that makes them ticked while this one stood. Left behind, it sent the lab's repair job to a box nobody opens.)
if IsValid(spk.lcBox) then spk.lcBox:Remove() end
lamp:Remove() spk:Remove()
LC.RemoveZone(hq)
LC.ZoneStalkersTick(CurTime())
LC.Event = evWas
end
ZoneStalkerTests()

function CrematorTests()
section("The Cremator: its model found, the dead burnt where they lie, enemies burnt out")
local overWas = LC.CrematorModelOverride
local crZonesWas = LC.Zones
LC.Zones = {} -- (no infestation here: with one, it burns only the dead in or near it, CrematorGuardTests)
LC.CrematorModelOverride = nil
-- the model: none on the server, none walk
ok(LC.CrematorModel(true) == nil, "no Cremator model on the server: none found")
LC.CrematorsStaff(CurTime() + 5000)
local n0 = 0
for npc in pairs(LC.Cremators) do if IsValid(npc) then n0 = n0 + 1 end end
ok(n0 == 0 and string.find(LC.CrematorSummary(), "none found", 1, true) ~= nil, "so no Cremators, and the debug report says why", LC.CrematorSummary())
_files["models/player/cremator.mdl"] = "x"
_files["models/cremator_head.mdl"] = "x"
ok(LC.CrematorModel(true) == "models/player/cremator.mdl", "only a playermodel: that one (never a head or a gib)", tostring(LC.CrematorModel()))
_files["models/cremator.mdl"] = "x"
ok(LC.CrematorModel(true) == "models/cremator.mdl", "an NPC model as well: the NPC's first", tostring(LC.CrematorModel()))
_files["models/mine/burner.mdl"] = "x"
_setcvar("lc_cremator_model", "models/mine/burner.mdl")
ok(LC.CrematorModel() == "models/mine/burner.mdl", "lc_cremator_model set: that one", tostring(LC.CrematorModel()))
_setcvar("lc_cremator_model", "")
_files["models/mine/burner.mdl"], _files["models/player/cremator.mdl"], _files["models/cremator_head.mdl"] = nil, nil, nil

-- the animations: likely names first, then the model's own list by what's in the names
local fake = ents.Create("prop_dynamic")
fake:SetModel("models/test_cremator_a.mdl")
fake.seqs = { idle01 = 1, walk = 2, fireinout = 3 }
ok(LC.CrematorSequence(fake, "idle", true) == "idle01" and LC.CrematorSequence(fake, "walk", true) == "walk" and LC.CrematorSequence(fake, "fire", true) == "fireinout",
    "a model with the likely names: those")
fake:SetModel("models/test_cremator_b.mdl")
fake.seqs = {}
fake.GetSequenceList = function() return { [0] = "ref", [1] = "stand_idle", [2] = "walk_slow", [3] = "immolate_loop", [4] = "deathpose_fire", [5] = "crouch_walk_idle" } end
local si, sw, sf = LC.CrematorSequence(fake, "idle", true), LC.CrematorSequence(fake, "walk", true), LC.CrematorSequence(fake, "fire", true)
ok(si == "stand_idle" and sw == "walk_slow" and sf == "immolate_loop", "none of them: the model's own that sound most like it (not a death, not a crouch)",
    tostring(si) .. " " .. tostring(sw) .. " " .. tostring(sf))
ok(string.find(LC.CrematorSummary(), "immolate_loop", 1, true) ~= nil, "the ones used are in the debug report", LC.CrematorSummary())
fake:Remove()

-- one of them: an unseen walker with the model on it
local C0 = Vector(-180000, 150000, 0)
local r = LC.SpawnCremator(C0)
ok(r ~= nil and IsValid(r.npc) and r.npc:GetClass() == "npc_stalker" and IsValid(r.vis) and r.vis:GetClass() == "prop_dynamic"
    and r.vis:GetModel() == "models/cremator.mdl" and r.vis:GetNW2Bool("lc_cremator", false) == true, "a Cremator: a walker, and the model carried on it")
if not r then LC.CrematorModelOverride = overWas LC.Zones = crZonesWas _files["models/cremator.mdl"] = nil return end
ok(r.npc:Health() == 400 and r.npc:GetNW2Bool("lc_noragdoll", false) == true, "sturdy, and the walker leaves no body of its own")

-- a body: left a while for the living, then burnt where it lies
local suspWas = LC.MorticiansSuspended
local body = LC.SpawnBody("models/humans/group01/male_01.mdl", C0 + Vector(500, 0, 0))
local now = CurTime()
ok(LC.CrematorBody(C0, now) == nil, "a body just fallen is left (lc_cremator_grace)")
ok(LC.CrematorBody(C0, now + 100) == body, "after that it's the Cremator's")
LC.MorticiansSuspended = function() return true end
ok(LC.CrematorBody(C0, now + 100) == nil, "the morticians stood down by the Administrator: the dead wait for it too")
LC.MorticiansSuspended = suspWas
_setcvar("lc_cremator_grace", 0)
local cremated = 0
hook.Add("LivingCityCremated", "test_cremator", function(who, b) if who == r.npc and b == body then cremated = cremated + 1 end end)
local flamed = false
for _ = 1, 120 do
    _run(0.5)
    LC.CrematorsThink(CurTime())
    if r.phase == "burn" and r.vis:GetNW2Entity("lc_flame_to") == body then flamed = true end
    if not IsValid(body) then break end
end
hook.Remove("LivingCityCremated", "test_cremator")
ok(flamed, "it walks to the body and turns its flame on it", tostring(r.phase) .. " " .. tostring(r.npc:GetPos()))
ok(not IsValid(body) and cremated == 1 and (LC.CrematorsBurnt or 0) >= 1 and r.phase == "roam", "and the body is gone", tostring(IsValid(body)) .. " " .. cremated)
ok(not IsValid(r.vis:GetNW2Entity("lc_flame_to")), "the flame goes out")
_setcvar("lc_cremator_grace", 90)

-- who it goes for
local pc = newPlayer("CremCitizen", "citizen")
local cp = newPlayer("CremUnit", "cp")
local violentWas = LC.Violent
LC.Violent = function(p) return p == pc and pc.testViolent == true or p == cp end
ok(LC.CrematorEnemy(r, pc) == false, "a citizen doing no harm: left alone")
pc.testViolent = true
ok(LC.CrematorEnemy(r, pc) == true, "whoever the units would shoot: an enemy")
ok(LC.CrematorEnemy(r, cp) == false, "Civil Protection: never, armed or not")
pc.testViolent = nil
local reb = ents.Create("npc_citizen") reb:SetPos(C0 + Vector(9000, 0, 0)) reb:Spawn()
LC.NPCs[reb] = { role = "rebel", state = "idle" }
ok(LC.CrematorEnemy(r, reb) == true, "one of the Resistance's people out in the open: an enemy")
LC.NPCs[reb].casual = true
ok(LC.CrematorEnemy(r, reb) == false, "(acting casual: a citizen, to it)")
LC.NPCs[reb].role, LC.NPCs[reb].casual = "citizen", nil
ok(LC.CrematorEnemy(r, reb) == false, "one of the city's people: left alone")
LC.NPCs[reb] = nil
reb:Remove()

-- a headcrab near it: burnt out
local crab = ents.Create("npc_headcrab") crab:SetPos(r.npc:GetPos() + Vector(150, 0, 0)) crab:Spawn()
crab:SetHealth(500)
for _ = 1, 6 do
    _run(0.5)
    LC.CrematorsThink(CurTime())
end
ok(r.foe == crab and r.vis:GetNW2Entity("lc_flame_to") == crab and crab:Health() < 500, "an enemy in reach: the flame, and it burns", tostring(r.foe) .. " " .. tostring(crab:Health()))
crab:Remove()
_run(0.5)
LC.CrematorsThink(CurTime())
ok(r.foe == nil and not IsValid(r.vis:GetNW2Entity("lc_flame_to")), "the enemy gone: back to its rounds")

-- hurting it
ok(hook.Run("EntityTakeDamage", r.npc, _dmg(pc, 50, 8)) == true and r.npc:Health() == 400, "fire does nothing to it")
hook.Run("EntityTakeDamage", r.npc, _dmg(pc, 10, 2))
ok(LC.CrematorEnemy(r, pc) == true, "whoever attacks it is an enemy, citizen or not")
hook.Run("EntityTakeDamage", r.npc, _dmg(cp, 10, 2))
ok(LC.CrematorEnemy(r, cp) == true, "(a unit too)")
local killedBy
hook.Add("LivingCityCrematorKilled", "test_cremator", function(a) killedBy = a end)
local npcWas, visWas = r.npc, r.vis
ok(hook.Run("EntityTakeDamage", r.npc, _dmg(pc, 9999, 2)) == true and not IsValid(npcWas) and not IsValid(visWas) and killedBy == pc and LC.Cremators[npcWas] == nil,
    "killed: the Cremator is gone (another comes later, out of sight)")
hook.Remove("LivingCityCrematorKilled", "test_cremator")

-- its pace: the unseen walker's animation runs lc_cremator_speed (2) times faster
local rp = LC.SpawnCremator(C0)
local rate
rp.npc.SetPlaybackRate = function(_, x) rate = x end
rp.npc.GetPlaybackRate = function() return rate or 1 end
LC.CrematorsThink(CurTime() + 6000)
ok(rate == 2, "the Cremator moves twice the walker's own pace by default", tostring(rate))
_setcvar("lc_cremator_speed", 3)
LC.CrematorsThink(CurTime() + 6001)
ok(rate == 3, "lc_cremator_speed 3: three times", tostring(rate))
_setcvar("lc_cremator_speed", 99)
ok(LC.CrematorPace() == 4, "never past four times", tostring(LC.CrematorPace()))
_setcvar("lc_cremator_speed", 2)
rp.vis:Remove() rp.npc:Remove() LC.Cremators[rp.npc] = nil

-- lc_cremators 0: none
local r2 = LC.SpawnCremator(C0)
_setcvar("lc_cremators", 0)
LC.CrematorsStaff(CurTime() + 5000)
ok(r2 ~= nil and not IsValid(r2.npc), "lc_cremators 0: none")
_setcvar("lc_cremators", 1)
LC.Violent = violentWas
pc:Remove() cp:Remove()
_files["models/cremator.mdl"] = nil
LC.CrematorModelOverride = overWas
LC.CrematorModel(true)
for _, x in pairs(LC.Cremators) do if IsValid(x.vis) then x.vis:Remove() end if IsValid(x.npc) then x.npc:Remove() end LC.Cremators[x.npc] = nil end
LC.Zones = crZonesWas
end
CrematorTests()
function CrematorGuardTests() -- (the owner, 12 November: Cremators guard the infestation; morticians never go in)
section("Cremators guard the infestation, burn its dead, and walk with the cleanup crews; morticians stay out")
local overWas, zonesWas, guardsWas = LC.CrematorModelOverride, LC.Zones, LC.CleanupGuards
LC.CrematorModelOverride = nil
_files["models/cremator.mdl"] = "x"
LC.CrematorModel(true)
local G0 = Vector(-182000, -120000, 0)
local z = { pos = G0, r = 400, kind = "infest", group = 0 }
LC.Zones = { z }
LC.CleanupGuards = {}
ok(LC.CrematorTurf(G0 + Vector(900, 0, 0)) == z and LC.CrematorTurf(G0 + Vector(5000, 0, 0)) == nil, "in or near the infestation is the Cremators' ground; the city is not")
local r = LC.SpawnCremator(G0 + Vector(2500, 0, 0))
ok(r ~= nil, "(a Cremator)")
if not r then LC.Zones, LC.CleanupGuards, LC.CrematorModelOverride = zonesWas, guardsWas, overWas _files["models/cremator.mdl"] = nil return end
local t = CurTime() + 2000
r.pauseUntil = 0
for i = 1, 3 do LC.CrematorsThink(t + i) end
ok(r.zone == z and r.doing == "guarding the infestation", "it guards the infestation", tostring(r.doing))
ok(r.dest ~= nil and LCZ.Near(z, r.dest, 500), "and walks to a spot in it or a little outside it", tostring(r.dest))
ok(string.find(LC.CrematorSummary(), "1 guarding the infestation", 1, true) ~= nil, "the debug report says so", LC.CrematorSummary())
-- the dead: the infestation's are the Cremator's, the city's the morticians'
local cityBody = LC.SpawnBody("models/humans/group01/male_01.mdl", G0 + Vector(4400, 0, 0))
local zoneBody = LC.SpawnBody("models/humans/group01/male_02.mdl", G0 + Vector(150, 0, 0))
ok(LC.CrematorBody(r.npc:GetPos(), t + 200) == zoneBody, "it goes for the body in the infestation, not the nearer one in the city")
ok(LC.InInfest(zoneBody:GetPos()) and LC.UnclaimedBody(G0, 6000) == cityBody, "a Mortician is never sent into the infestation for one")
cityBody:Remove() zoneBody:Remove()
-- a cleanup crew going in: it walks with them, then back to its post
local crew = LC.SpawnCitizen(G0 + Vector(300, 200, 4))
LC.CleanupGuards[crew] = { units = {} }
for i = 4, 7 do LC.CrematorsThink(t + i * 3) end
ok(r.escort == crew and r.doing == "escorting the cleanup crew", "a cleanup crew under guard: the Cremator walks with them", tostring(r.doing))
ok(string.find(LC.CrematorSummary(), "1 escorting a cleanup crew", 1, true) ~= nil, "(the debug report says so)", LC.CrematorSummary())
local r2 = LC.SpawnCremator(G0 + Vector(2600, 0, 0))
if r2 then
    for i = 8, 10 do LC.CrematorsThink(t + i * 3) end
    ok(r2.escort == nil, "one Cremator to a crew: the other keeps its post")
    r2.vis:Remove() r2.npc:Remove() LC.Cremators[r2.npc] = nil
end
LC.CleanupGuards[crew] = nil
for i = 11, 13 do LC.CrematorsThink(t + i * 3) end
ok(r.escort == nil and r.doing == "guarding the infestation", "the crew done: back to guarding", tostring(r.doing))
-- no infestation marked: the streets, as before, and every body is fair game again
LC.Zones = {}
for i = 14, 16 do LC.CrematorsThink(t + i * 3) end
ok(r.zone == nil and string.find(LC.CrematorSummary(), "1 on the streets", 1, true) ~= nil, "no infestation marked: it walks the streets", LC.CrematorSummary())
if IsValid(zoneBody) then zoneBody:Remove() end
if IsValid(crew) then LC.NPCs[crew] = nil crew:Remove() end
r.vis:Remove() r.npc:Remove() LC.Cremators[r.npc] = nil
LC.Zones, LC.CleanupGuards, LC.CrematorModelOverride = zonesWas, guardsWas, overWas
_files["models/cremator.mdl"] = nil
LC.CrematorModel(true)
end
CrematorGuardTests()

function RebelPamphletTests()
section("The Resistance pamphlet: read, handed over, left lying about")
local it = LCS.Items.rebel_pamphlet
ok(it ~= nil and it.contraband == true and it.use == "rebelpamphlet", "the pamphlet is an item, and contraband")
ok(LCS.BlackById.rebel_pamphlet ~= nil and LCS.BlackById.rebel_pamphlet.qm == true and LCS.BlackById.rebel_pamphlet.count == 5, "the quartermaster sells them, five at a time (no dealer does)")
local seenWas, crimeWas, snitchWas, rollWas = LC.SeenBySecurity, LC.ReportCrime, LC.IsSnitch, LC.RebelPamphletRoll
LC.IsSnitch = function() return false end -- (nobody here informs until the test names one: with informants on, a citizen was one at random)
local seen, crimes = false, {}
LC.SeenBySecurity = function() return seen end
LC.ReportCrime = function(p, why) crimes[#crimes + 1] = { p, why } end
local P0 = Vector(-170000, 120000, 0)
local reb = newPlayer("PamRebel", "resistance")
local cit = newPlayer("PamCitizen", "citizen")
local cit2 = newPlayer("PamCitizen2", "citizen")
local cp = newPlayer("PamUnit", "cp")
reb:SetPos(P0) cit:SetPos(P0 + Vector(60, 0, 0)) cit2:SetPos(P0 + Vector(0, 60, 0)) cp:SetPos(P0 + Vector(-60, 0, 0))

-- reading one from the pockets
ok(LC.ReadRebelPamphlet(cit) == false, "none in your pockets: nothing to read")
LC.GiveItem(cit, "rebel_pamphlet", 1)
local s0 = LC.Trait(cit, "sympathy")
ok(LC.ReadRebelPamphlet(cit) == true and cit.lcDialog and cit.lcDialog.key == "rebelpamphlet", "Read: the sheet opens")
ok(LC.Trait(cit, "sympathy") == s0 + 1, "the first one a citizen ever reads: 1 sympathy", LC.Trait(cit, "sympathy") - s0)
LC.ReadRebelPamphlet(cit)
ok(LC.Trait(cit, "sympathy") == s0 + 1, "(only the first)")
ok(LC.DialogDo(cit, "help") == "help" and LC.DialogDo(cit, "nosuchpage") == nil, "its pages turn")

-- leaving one about
LC.GiveItem(reb, "rebel_pamphlet", 14)
local okL, left = LC.LeaveRebelPamphlet(reb)
ok(okL == true and IsValid(left) and left:GetClass() == "lc_rebelpamphlet" and LC.HasItem(reb, "rebel_pamphlet", 13) and not LC.HasItem(reb, "rebel_pamphlet", 14),
    "Leave a pamphlet here: it lies there, and it's out of your pockets")
ok(#crimes == 0, "nobody watching: no crime")
seen = true
local _, left2 = LC.LeaveRebelPamphlet(reb)
ok(#crimes == 1 and crimes[1][1] == reb and crimes[1][2] == "Distributing seditious material", "a unit watching: a crime", #crimes)
seen = false
for _ = 1, 6 do LC.LeaveRebelPamphlet(reb) end
local mine = 0
for _, e in ipairs(LC.RebelPamphlets) do if IsValid(e) and e.lcOwnerSid == reb:SteamID() then mine = mine + 1 end end
ok(mine == 6 and not IsValid(left), "no more than lc_rebel_pamphlets_max (6) of yours lying about: the oldest goes", mine)
ok(LC.LeaveRebelPamphlet(cit2) == false, "none to leave: no")

-- someone finds it
local found = LC.RebelPamphlets[#LC.RebelPamphlets]
cit2:SetPos(found:GetPos() + Vector(30, 0, 0))
local s2 = LC.Trait(cit2, "sympathy")
ok(LC.ReadRebelPamphlet(cit2, found) == true and LC.Trait(cit2, "sympathy") == s2 + 1, "a citizen presses E on it: reads it (their first: 1 sympathy)")
ok(LC.DialogDo(cit2, "_seize") == nil and IsValid(found), "(a citizen can't confiscate it)")
ok(LC.DialogDo(cit2, "_take") == "_take" and not IsValid(found) and LC.HasItem(cit2, "rebel_pamphlet"), "Pocket it: it's theirs now")
local found2 = LC.RebelPamphlets[#LC.RebelPamphlets]
for i = #LC.RebelPamphlets, 1, -1 do if IsValid(LC.RebelPamphlets[i]) then found2 = LC.RebelPamphlets[i] break end end
cp:SetPos(found2:GetPos() + Vector(30, 0, 0))
local s3 = LC.Trait(cp, "sympathy")
ok(LC.ReadRebelPamphlet(cp, found2) == true and LC.Trait(cp, "sympathy") == s3, "a unit reads it too (it wins nobody there)")
ok(LC.DialogDo(cp, "_take") == nil and LC.DialogDo(cp, "_seize") == "_seize" and not IsValid(found2), "Confiscate it: gone")
cit2:SetPos(P0 + Vector(0, 60, 0))
ok(LC.ReadRebelPamphlet(cit2, left2) == false, "(too far from one: no)")

-- handing one to the city's people
local function Citizen(off, extra)
    local n = ents.Create("npc_citizen") n:SetPos(P0 + off) n:Spawn()
    n:SetHealth(40)
    local st = { role = "citizen", state = "idle" }
    for k, v in pairs(extra or {}) do st[k] = v end
    LC.NPCs[n] = st
    return n, st
end
local have = function() local c = 0 while LC.HasItem(reb, "rebel_pamphlet", c + 1) do c = c + 1 end return c end
reb:SetPos(P0)
local n1, st1 = Citizen(Vector(80, 0, 0))
local before = have()
LC.RebelPamphletRoll = function() return 0.1 end
ok(LC.GiveRebelPamphlet(reb, n1) == true and st1.rebel == true and n1:GetNW2Bool("lc_prebel", false) == true and have() == before - 1,
    "handed to a citizen who listens: they take it, a sympathiser now")
local okA, whyA = LC.GiveRebelPamphlet(reb, n1)
ok(okA == false and whyA ~= nil and have() == before - 1, "(not the same one again straight away)")
local n2, st2 = Citizen(Vector(0, 80, 0))
LC.RebelPamphletRoll = function() return 0.9 end
ok(LC.GiveRebelPamphlet(reb, n2) == true and not st2.rebel and have() == before - 1, "one who won't: they push it back, and you keep it")
local n3, st3 = Citizen(Vector(-80, 0, 0))
LC.IsSnitch = function(n) return n == n3 end
ok(LC.GiveRebelPamphlet(reb, n3) == true and not st3.rebel and have() == before - 2 and #crimes == 1, "an informant takes it like anyone")
LC.NPCs[n1], LC.NPCs[n2], LC.NPCs[n3] = nil, nil, nil
_run(21)
-- Only the informant's report counts: what earlier tests leave running may report something else meanwhile.
local told = 0
for i = 2, #crimes do if crimes[i][1] == reb and crimes[i][2] == "Distributing seditious material" then told = told + 1 end end
ok(told == 1, "and Civil Protection hears of it a little later", #crimes)

-- the city walking past the ones lying about
for _, e in ipairs(LC.RebelPamphlets) do if IsValid(e) then e:Remove() end end
local _, lying = LC.LeaveRebelPamphlet(reb)
local now = CurTime()
n1:SetPos(lying:GetPos() + Vector(40, 0, 0))
st1.rebel = nil
LC.NPCs[n1] = st1
LC.RebelPamphletRoll = function() return 0.1 end
LC.RebelPamphletsTick(now)
ok(IsValid(lying) and lying.lcReadCount == 1 and st1.rebel == true, "a citizen walking past reads it, and may come round")
LC.RebelPamphletsTick(now)
ok(lying.lcReadCount == 1, "(once each)")
LC.NPCs[n1] = nil
n2:SetPos(lying:GetPos() + Vector(40, 0, 0))
LC.NPCs[n2] = { role = "cop", state = "idle" }
LC.RebelPamphletsTick(now)
ok(not IsValid(lying), "a unit walking past takes it away")
LC.NPCs[n2] = nil
local _, old = LC.LeaveRebelPamphlet(reb)
LC.RebelPamphletsTick(now + 29 * 60)
ok(IsValid(old), "one left lying stays lc_rebel_pamphlet_minutes (30)")
LC.RebelPamphletsTick(now + 31 * 60)
ok(not IsValid(old) and #LC.RebelPamphlets == 0, "then it's gone")

-- handing one to a player
reb:SetPos(P0) cit:SetPos(P0 + Vector(60, 0, 0))
local trWas = reb.GetEyeTrace
reb.GetEyeTrace = function() return { Entity = cit, HitPos = cit:GetPos(), Hit = true } end
local citHad = 0
while LC.HasItem(cit, "rebel_pamphlet", citHad + 1) do citHad = citHad + 1 end
ok(LC.GiveRebelPamphlet(reb, cit) == true and LC.HasItem(cit, "rebel_pamphlet", citHad + 1), "handed to a player: it's in their pockets")
reb.GetEyeTrace = trWas

LC.SeenBySecurity, LC.ReportCrime, LC.IsSnitch, LC.RebelPamphletRoll = seenWas, crimeWas, snitchWas, rollWas
n1:Remove() n2:Remove() n3:Remove()
reb:Remove() cit:Remove() cit2:Remove() cp:Remove()
end
RebelPamphletTests()

section("NPCs that fall out of the map")
;(function()
    local npc = LC.Spawners.citizen(Vector(-160000, -160000, 0))
    if not IsValid(npc) then ok(false, "a citizen to drop") return end
    local wasIn = util.IsInWorld
    util.IsInWorld = function(p) return p.z > -1000 end
    LC.RescueFallen(CurTime())
    npc:SetPos(Vector(-160000, -160000, -50000))
    LC.RescueFallen(CurTime())
    ok(npc:GetPos().z < -1000, "not moved at once (a moment out of the map is let be)")
    LC.RescueFallen(CurTime() + 3)
    ok(IsValid(npc) and npc:GetPos().z > -1000, "fallen out of the map for two seconds: put back where it last stood", npc:GetPos())
    npc.lcGoodPos = nil
    npc:SetPos(Vector(-160000, -160000, -50000))
    LC.RescueFallen(CurTime())
    LC.RescueFallen(CurTime() + 3)
    ok(not IsValid(npc), "nowhere to put it back: taken away")
    util.IsInWorld = wasIn
    -- an ending's ring with a crowd: everyone their own spot, spilling onto more rings
    local spots = LC.EndingRingSpots(Vector(-160000, 160000, 0), 60, 120, {})
    local close = 0
    for i = 1, #spots do for j = i + 1, #spots do if spots[i].pos:Distance(spots[j].pos) < 40 then close = close + 1 end end end
    ok(#spots == 120 and close == 0, "an ending's ring with 120 people in it: nobody stands inside anybody", close)
end)()

function BreathTests() -- (the owner, 7 November: the panting that never stopped)
section("Out of breath: the server never plays the panting (each game holds it on a handle)")
local runner = newPlayer("Panter", "citizen")
_run(0.2)
local n0 = #_sounds
runner:SetNW2Float("lc_stamina", 0)
runner:SetNW2Bool("lc_winded", false)
runner.lcRanAt = CurTime() -- (just stopped running: no breath back yet)
LCS.Tick(CurTime(), 0.2)
ok(runner:GetNW2Bool("lc_winded", false), "run out: winded")
local panted = false
for i = n0 + 1, #_sounds do if string.find(tostring(_sounds[i]), "breathe", 1, true) then panted = true end end
ok(not panted and runner.lcBreathAt == nil, "and the server plays no breathing (a looping sample it could never stop)")
ok(LCS.BreathTick == nil, "(the panting is only the players' own games': no server copy of it)")
runner.lcRanAt = nil
for _ = 1, 30 do LCS.Tick(CurTime(), 0.2) _advance(0.2) end
ok(not runner:GetNW2Bool("lc_winded", false), "breath back: no longer winded")
hook.Run("PlayerSpawn", runner)
ok(runner:GetNW2Float("lc_stamina", 0) == 100 and not runner:GetNW2Bool("lc_winded", true), "a new life starts with full breath")
runner:SetPos(Vector(-30000, 30000, 0))
end
BreathTests()

function SleepWarnTests() -- (the owner, 7 November: warnings, sleep from the first one, a citizen's hours, not mid-fight)
section("Sleep: two warnings, a bed from the first, citizens keep the city's hours, never mid-fight")
_setcvar("lc_bedtime", 0) -- (the usual clock only: lights out has its own tests, DreamCrowdTests)
local notes = {}
local noticeWas, nightWas = LC.Notice, LC.IsNight
LC.Notice = function(p, kind, title, text) notes[#notes + 1] = { p = p, title = title, text = text } end
local function Noted(p, title) for _, n in ipairs(notes) do if n.p == p and n.title == title then return true end end return false end
local function Count(p, title) local c = 0 for _, n in ipairs(notes) do if n.p == p and n.title == title then c = c + 1 end end return c end
local hourWas = LC.Hour()
LC.SetHour(13)
LC.IsNight = function() return false end
local unit = newPlayer("TiredUnit", "cp")
_run(0.2)
unit:SetPos(Vector(-26000, 26000, 0))
unit:SetNW2Float("lc_rested_until", 0)
unit.lcAwakeSince = CurTime()
local limit = LC.TiredDue(unit) - unit.lcAwakeSince
ok(limit > 600, "a Civil Protection unit: tired after a day awake (no hours to keep)", limit)
local bed = ents.Create("lc_bed") bed:SetPos(unit:GetPos() + Vector(40, 0, 0)) bed:Spawn()
-- well before: no sleeping in the day
unit.lcAwakeSince = CurTime() - (limit - 1000)
LC.RestTick(CurTime())
local okS, why = LC.SleepIn(unit, bed)
ok(not okS and why and string.find(why, "daylight", 1, true), "not tired yet, in the day: no sleeping", why)
-- six minutes before: the first warning, and a bed will do
unit.lcAwakeSince = CurTime() - (limit - 300)
LC.RestTick(CurTime())
ok(Noted(unit, "Getting tired") and not LC.IsTired(unit), "about six minutes before: the first warning (not exhausted yet)")
ok(unit:GetNW2Bool("lc_drowsy", false) and LC.IsDrowsy(unit), "drowsy from then on")
ok(LC.SleepIn(unit, bed), "and a bed lets you sleep, in broad daylight")
LC.WakeUp(unit, "quiet")
-- two minutes before: the second, once
unit.lcAwakeSince = CurTime() - (limit - 100)
LC.RestTick(CurTime())
LC.RestTick(CurTime())
ok(Count(unit, "Very tired") == 1 and Count(unit, "Getting tired") == 1, "about two minutes before: the second warning, once each")
-- the time comes mid-fight: the eyes wait
unit.lcAwakeSince = CurTime() - limit - 10
LC.NoteFight(unit)
LC.RestTick(CurTime())
ok(not LC.IsTired(unit), "exhausted in the middle of a fight: the eyes don't start closing yet")
unit.lcFightAt = nil
LC.RestTick(CurTime())
ok(LC.IsTired(unit) and Noted(unit, "Exhausted"), "the fight over: exhausted")
-- on a job: the job stays the next step
LC.QuestOf[unit] = { title = "Test job" }
local step = LC.RestStep(unit)
ok(step and not step.urgent, "on a job, sleep doesn't push the job off the screen (not urgent)")
LC.QuestOf[unit] = nil
ok(LC.RestStep(unit).urgent, "off the job, it's urgent again")
-- a citizen keeps the city's hours
local cit = newPlayer("DayCitizen", "citizen")
_run(0.2)
cit:SetPos(Vector(-26000, 26200, 0))
local len = GetGlobal2Float("lc_day_len", 1440)
LC.SetHour(13)
cit.lcAwakeSince = CurTime() - limit -- (awake a whole day, since one o'clock yesterday)
unit.lcAwakeSince = CurTime() - limit
ok(LC.TiredDue(unit) <= CurTime() + 1, "a unit awake a day: exhausted now, midday or not")
ok(LC.TiredDue(cit) > CurTime() + 60 and not LC.IsDrowsy(cit), "a citizen awake as long at midday: not yet, it waits for the evening", (LC.TiredDue(cit) - CurTime()) / len * 24)
LC.RestTick(CurTime())
ok(not LC.IsTired(cit), "(no eyes closing in the middle of the day)")
cit.lcAwakeSince = CurTime() - limit * 31 / 24 -- (up since six yesterday morning: the night skipped)
ok(LC.TiredDue(cit) <= CurTime(), "a night skipped: exhausted, whatever the hour")
LC.SetHour(23)
cit.lcAwakeSince = CurTime() - limit * 16 / 24 -- (up since seven this morning)
ok(LC.IsDrowsy(cit) and LC.TiredDue(cit) > CurTime(), "up since the morning, late in the evening: drowsy, a bed will do", (LC.TiredDue(cit) - CurTime()))
LC.SetHour(13)
cit.lcAwakeSince = CurTime() - limit * 6 / 24 -- (up since seven, now one o'clock)
ok(not LC.IsDrowsy(cit), "up since the morning, at midday: not tired")
LC.Notice, LC.IsNight = noticeWas, nightWas
LC.SetHour(hourWas)
bed:Remove()
for _, p in ipairs({ unit, cit }) do p.lcAwakeSince = CurTime() p:SetNW2Bool("lc_tired", false) p:SetPos(Vector(-30000, 30000, 0)) end
_setcvar("lc_bedtime", 1)
end
SleepWarnTests()

function PacingTests() -- (the owner, 7 November: "constant announcements ... I feel stressed just playing")
section("Pacing: one PA, a quiet gap before routine announcements, the server's own recordings first, events further apart")
local ann = function(from) local out = {} for i = from + 1, #net.sent do if net.sent[i].name == "lc_announce" then out[#out + 1] = net.sent[i].data[1] end end return out end
_setcvar("lc_announce_quiet", 90)
LC.AnnounceForceVoice = "overwatch"
LC.PAEndsAt, LC.LastPA = CurTime() - 500, CurTime() - 500
LC.PAMark(10)
ok(LC.PAQuiet() < 0, "someone speaking: the PA isn't quiet")
ok(LC.AnnounceTooSoon("dusk") and LC.AnnounceTooSoon("socio_yellow") and LC.AnnounceTooSoon("ambient"), "routine ones (the time of day, sociostability going yellow, the PA's remarks) wait for quiet")
ok(not LC.AnnounceTooSoon("curfew") and not LC.AnnounceTooSoon("socio_red") and not LC.AnnounceTooSoon("rations_soon"), "the things that matter are always said")
LC.PAEndsAt, LC.LastPA = CurTime() - 85, CurTime() - 95
ok(LC.AnnounceTooSoon("dusk"), "85 seconds of quiet after the last one finished: not yet")
LC.PAEndsAt = CurTime() - 91
ok(not LC.AnnounceTooSoon("dusk"), "a minute and a half: a routine one can be made")
LC.PAMark(6)
local e1 = LC.PAMark(6)
ok(e1 >= CurTime() + 12 - 0.01, "a second voice waits for the first to finish (one PA, shared)", e1 - CurTime())
-- Half-Life 2's line only where the server has none of its own
_files["sound/livingcity/overwatch/response1.wav"] = ""
LC.AnnounceRescan()
_advance(181)
LC.PAEndsAt, LC.LastPA = CurTime() - 500, CurTime() - 500
local n0 = #net.sent
LC.Announce("response", "npc/overwatch/cityvoice/f_protectionresponse_1_spkr.wav")
local got = ann(n0)
ok(#got == 1 and string.find(got[1], "livingcity/overwatch/response1", 1, true), "a response: the server's own recording, not Half-Life 2's", got[1])
n0 = #net.sent
LC.Announce("response", "npc/overwatch/cityvoice/f_protectionresponse_1_spkr.wav")
ok(#ann(n0) == 0, "a second response squad straight after: not announced again")
n0 = #net.sent
LC.Announce("rations")
got = ann(n0)
ok(#got == 1 and got[1] == "", "nothing of its own for rations: the banner and words, no Half-Life 2 voice (the owner, 9 November)", got[1])
_setcvar("lc_announce_stock", 1)
n0 = #net.sent
LC.Announce("rations")
got = ann(n0)
ok(#got == 1 and string.find(got[1], "npc/overwatch/", 1, true), "with lc_announce_stock 1: Half-Life 2's line", got[1])
_setcvar("lc_announce_stock", 0)
_files["sound/livingcity/overwatch/response1.wav"] = nil
LC.AnnounceRescan()
-- the PA's remarks (a wanted person, a sentence...): one in three minutes, and only after quiet
_advance(181)
LC.PAEndsAt, LC.LastPA = CurTime() - 500, CurTime() - 500
ok(LC.AnnounceLine("f_evasionbehavior_2_spkr.wav", "Someone is wanted."), "a remark on the PA when it's been quiet")
LC.PAEndsAt, LC.LastPA = CurTime() - 500, CurTime() - 500
ok(not LC.AnnounceLine("f_capitalmalcompliance_spkr.wav", "Someone else is wanted."), "not another for three minutes")
-- sociostability: said once in two minutes; a flicker in between waits, and red is said at once
local listener = newPlayer("SocioListener", "citizen")
_run(0.2)
local ovWas, socWas = LC.SocioOverride, LC.Socio
local function SaidSocio() for _, l in ipairs(listener.chat) do if string.find(l, "Sociostability:", 1, true) then return l end end return nil end
LC.SocioOverride = { level = "green", untilT = CurTime() + 1e6 }
LC.Socio = "green"
LC.SocioSaid.level, LC.SocioSaid.at = "green", CurTime()
listener.chat = {}
LC.SocioOverride = { level = "yellow", untilT = CurTime() + 1e6 }
LC.RefreshSocio()
ok(LC.Socio == "yellow" and not SaidSocio(), "yellow straight after the last one: not said yet")
_advance(121)
_runtimers()
ok(SaidSocio() and string.find(SaidSocio(), "MARGINAL", 1, true), "said once two minutes have passed (it still stands)", SaidSocio())
listener.chat = {}
LC.SocioOverride = { level = "red", untilT = CurTime() + 1e6 }
LC.RefreshSocio()
ok(SaidSocio() and string.find(SaidSocio(), "JUDGMENT", 1, true), "red: said at once")
LC.SocioOverride, LC.Socio = ovWas, socWas
LC.RefreshSocio(true)
listener:SetPos(Vector(-30000, 30000, 0))
-- the city's happenings about twice as far apart (old defaults moved on, chosen values kept)
local doubled = { lc_event_interval = "24", lc_skirmish_interval = "50", lc_train_minutes = "24", lc_rebel_spread_minutes = "40",
    lc_drop_cooldown = "60", lc_rebel_ops_minutes = "60", lc_loyalty_praise_minutes = "40", lc_announce_quiet = "90" }
local okD, bad = true, nil
for k, v in pairs(doubled) do if (_cvarDefaults or {})[k] ~= v then okD, bad = false, k .. "=" .. tostring((_cvarDefaults or {})[k]) end end
ok(okD, "events, skirmishes, trains, rebel growth, drops, the rebels' operations and the praise about twice as far apart; the PA quiet 90 seconds", bad)
_setcvar("lc_event_interval", 12)
_setcvar("lc_train_minutes", 15)
LC.EndingRetune()
ok(GetConVar("lc_event_interval"):GetString() == "24" and GetConVar("lc_train_minutes"):GetString() == "15", "a server still on the old default moves to the new one; a value someone chose stays")
_setcvar("lc_train_minutes", 24)
_setcvar("lc_announce_quiet", 0)
end
PacingTests()

function ScarcityTests() -- (later on 7 November, the owner: food scarcity, docs/dev/scarcity-audit.md items 1 to 8)
section("Food scarcity: slower rations, dearer food, emptier stores, fewer runs, birds and fish")
local want = { lc_ration_interval = "1500", lc_stock_eat = "20", lc_rebel_errand_minutes = "12", lc_birds = "4",
    lc_scavenge_refill = "1800", lc_fridge_refill = "900" }
local okD, bad = true, nil
for k, v in pairs(want) do if (_cvarDefaults or {})[k] ~= v then okD, bad = false, k .. "=" .. tostring((_cvarDefaults or {})[k]) end end
ok(okD, "a ration every 25 minutes, the city eats one per 20 out, rebel runs every 12 minutes, 4 birds, bins half an hour, fridges a quarter", bad)
_setcvar("lc_ration_interval", 600)
_setcvar("lc_fridge_refill", 300)
LC.EndingRetune()
ok(GetConVar("lc_ration_interval"):GetString() == "1500" and GetConVar("lc_fridge_refill"):GetString() == "300",
    "a server still on the old default moves to the new one; a value someone chose stays",
    GetConVar("lc_ration_interval"):GetString() .. "/" .. GetConVar("lc_fridge_refill"):GetString())
_setcvar("lc_fridge_refill", 900)
local G1 = LCS.GoodsById
ok(G1.ration.price == 15 and G1.bread.price == 15 and G1.milk.price == 15, "a ration, bread and milk cost 15 credits at the Commissary",
    tostring(G1.ration.price) .. "/" .. tostring(G1.bread.price) .. "/" .. tostring(G1.milk.price))
-- fishing: a longer cast, and a fish 30% of the time
local realR = math.random
local fisher = newPlayer("ScarceFisher", "citizen")
fisher:SetPos(Vector(-141000, 71000, 0))
fisher.water = 1
LC.GiveItem(fisher, "fishing_line")
fisher.lcLineUses = 5
math.random = function(a, b) if a == nil then return 0.4 end if b == nil then return realR(a) end return realR(a, b) end
ok(LC.ItemUse(fisher, "fishing_line"), "cast a line")
_run(30)
ok(LC.Busy(fisher), "a cast takes 25 to 45 seconds (it was 10 to 22)")
_run(16)
math.random = realR
ok(not LC.Busy(fisher) and not LC.HasItem(fisher, "raw_fish"), "and a roll that used to land a fish (58%) now comes up empty (30%)")
fisher:SetPos(Vector(-150000, 150000, 0))
-- birds: a killed one is replaced only after 90 seconds, one of a kind at a time
local wt = timer.list["LivingCityWildlife"]
local wasW, wasRun, wasRWP = LC.Wildlife, LC.Running, LC.RandomWanderPos
local wasVermin = GetConVar("lc_vermin"):GetInt()
LC.Wildlife, LC.WildlifeOwed, LC.WildlifeNextAt, LC.Running = {}, {}, {}, true
LC.RandomWanderPos = function() return Vector(-160000 + realR(-300, 300), 160000 + realR(-300, 300), 0) end
_setcvar("lc_birds", 2)
_setcvar("lc_vermin", 0)
local function Birds()
    local n, one = 0, nil
    for e, kind in pairs(LC.Wildlife) do if IsValid(e) and kind == "bird" then n, one = n + 1, e end end
    return n, one
end
local function Ticks(n) for _ = 1, n do wt.fn() end end
Ticks(10)
ok(Birds() == 2, "the city fills up with birds straight away", Birds())
local _, b1 = Birds()
hook.Run("OnNPCKilled", b1, fisher)
b1:Remove()
Ticks(10)
ok(Birds() == 1, "a bird that is killed isn't replaced at once", Birds())
_advance(91)
Ticks(10)
ok(Birds() == 2, "but is, a minute and a half later", Birds())
for e in pairs(LC.Wildlife) do if IsValid(e) then hook.Run("OnNPCKilled", e, fisher) e:Remove() end end
_advance(91)
Ticks(10)
ok(Birds() == 1, "two killed: only one comes back after 90 seconds", Birds())
_advance(91)
Ticks(10)
ok(Birds() == 2, "and the other 90 seconds after that", Birds())
for e in pairs(LC.Wildlife) do if IsValid(e) then e:Remove() end end
LC.Wildlife, LC.WildlifeOwed, LC.WildlifeNextAt, LC.Running, LC.RandomWanderPos = wasW, {}, {}, wasRun, wasRWP
_setcvar("lc_birds", 4)
_setcvar("lc_vermin", wasVermin)
end
ScarcityTests()

function CombineMusicTests() -- (the owner, 7 November: "as the combine nothing plays at all")
section("Civil Protection in action: a fight, a violent job, a raid or a sweep (their action music)")
local evWas, skWas = LC.Event, LC.Skirmish
LC.Event, LC.Skirmish = nil, nil
local unit = newPlayer("ActionUnit", "cp")
local rebel = newPlayer("ActionRebel", "resistance")
local cit = newPlayer("ActionCitizen", "citizen")
_run(0.2)
for _, p in ipairs({ unit, rebel, cit }) do p.lcFightAt, p.lcActionAt, p.lcShotTimes = nil, nil, nil p:SetNW2Float("lc_action_until", 0) end
LC.ActionTick(CurTime())
ok(unit:GetNW2Float("lc_action_until", 0) <= CurTime() and LC.InAction(unit) == nil, "on an ordinary patrol: no action music")
hook.t.EntityTakeDamage.LivingCityPacingFight(unit, _dmg(rebel, 5)) -- (this listener alone: others may stop the rest)
ok(LC.InFight(unit) and LC.InFight(rebel), "shot at: both of them are in a fight")
LC.ActionTick(CurTime())
ok(unit:GetNW2Float("lc_action_until", 0) > CurTime() and LC.InAction(unit) == "fight", "a unit who has been shot: in action (their game plays the combat music)")
-- (the owner, 14 November: "shooting an enemy twice", so a shot in the air or at a wall isn't action)
ok(LC.InAction(rebel) == nil and LC.InAction(cit) == nil, "the one who hit an enemy once, and the bystander: not in action")
for _ = 1, 5 do hook.t.EntityFireBullets.LivingCityPacingFight(rebel) end
ok(LC.InAction(rebel) == nil, "five shots into the air: still not")
local ally = newPlayer("ActionAlly", "resistance")
hook.t.EntityTakeDamage.LivingCityPacingFight(ally, _dmg(rebel, 5))
ok(LC.InAction(rebel) == nil, "hitting one of your own side: not an enemy, not counted")
hook.t.EntityTakeDamage.LivingCityPacingFight(unit, _dmg(rebel, 5))
LC.ActionTick(CurTime())
ok(LC.InAction(rebel) == "fight" and rebel:GetNW2Float("lc_action_until", 0) > CurTime(), "an enemy hit twice: in action, whatever their side")
ally:SetPos(Vector(-30000, 30000, 0))
hook.t.EntityTakeDamage.LivingCityPacingFight(cit, _dmg(rebel, 5))
ok(LC.InAction(cit) == "fight", "a citizen who has been shot: in action too")
_advance(35)
unit.lcFightAt = nil
ok(LC.InAction(unit) == nil and LC.InAction(rebel) == nil and LC.InAction(cit) == nil, "the fight over: out of action")
LC.QuestOf[unit] = { violent = true, stages = {} }
local qopWas = LC.QuestObjectivePos
LC.QuestObjectivePos = function() return unit:GetPos() + Vector(400, 0, 0) end
ok(LC.InAction(unit) == nil, "on a violent job, near where it happens, no shot fired: no action music any more")
LC.QuestObjectivePos = qopWas
LC.QuestOf[unit] = nil
-- (the owner, 12 November: a city event starting never starts the action music on its own)
LC.Event = "sweep"
ok(LC.InAction(unit) == nil, "civil status inspections (a sweep) going on: no action music by itself")
LC.Event = "raid"
ok(LC.InAction(unit) == nil, "a raid going on, the job not taken: none either")
LC.Event, LC.Skirmish = evWas, skWas
for _, p in ipairs({ unit, rebel, cit }) do p:SetPos(Vector(-30000, 30000, 0)) end
end
CombineMusicTests()
function ActionMusicRestTests() -- (the owner, 12 November: the action music played in bed and in a dream)
section("No action music while asleep, in bed or dreaming, nor from an event starting")
local evWas, skWas = LC.Event, LC.Skirmish
LC.Event, LC.Skirmish = "sweep", nil
local unit = newPlayer("RestUnit", "cp")
_run(0.2)
unit.lcFightAt = nil
unit:SetNW2Float("lc_action_until", 0)
LC.ActionTick(CurTime())
ok(unit:GetNW2Float("lc_action_until", 0) <= CurTime(), "inspections on, no fight, no job: no action music")
unit.lcFightAt, unit.lcActionAt = CurTime(), CurTime()
ok(LC.InAction(unit) == "fight", "(shot just now: action)")
unit:SetNW2Bool("lc_sleeping", true)
ok(LC.AtRest(unit) and LC.InAction(unit) == nil, "asleep: never in action, even with a fight just now")
unit:SetNW2Bool("lc_sleeping", false)
unit:SetNW2Bool("lc_dreaming", true)
ok(LC.InAction(unit) == nil, "in a dream: never in action")
unit:SetNW2Bool("lc_dreaming", false)
unit:SetNW2Vector("lc_bed_top", Vector(10, 10, 30))
ok(LC.InAction(unit) == nil, "lying in bed: never in action")
unit:SetNW2Vector("lc_bed_top", Vector(0, 0, 0))
ok(not LC.AtRest(unit) and LC.InAction(unit) == "fight", "up again: the fight counts")
LC.ActionTick(CurTime())
ok(unit:GetNW2Float("lc_action_until", 0) > CurTime(), "(in action: the music's mark set)")
unit:SetNW2Bool("lc_sleeping", true)
LC.ActionTick(CurTime())
ok(unit:GetNW2Float("lc_action_until", 0) <= CurTime(), "gone to bed in the middle of it: the action music's mark is taken off at once")
unit:SetNW2Bool("lc_sleeping", false)
local far = { zone = { pos = unit:GetPos() + Vector(5000, 0, 0) } }
unit.lcFightAt, unit.lcActionAt = nil, nil
LC.Skirmish = far
ok(LC.InAction(unit) == nil, "a skirmish 5000 units away: no action music")
LC.Skirmish = { zone = {} }
ok(LC.InAction(unit) == nil, "a skirmish nobody knows where: none either")
LC.Skirmish = { zone = { pos = unit:GetPos() + Vector(800, 0, 0) } }
ok(LC.InAction(unit) == nil, "a skirmish nearby, no shot fired or taken: no action music (13 November)")
LC.Event, LC.Skirmish = evWas, skWas
unit:SetPos(Vector(-30000, 30000, 0))
end
ActionMusicRestTests()
function PlaytestNov13Tests() -- (the owner's 13 November playtest notes, built 14 November)
section("The 13 November playtest: looping sounds, quest kills, wording, ammo, kin, sweeps in turn")
-- sounds that loop by themselves: read from the .wav's own data
local function le(n) return string.char(n % 256, math.floor(n / 256) % 256, math.floor(n / 65536) % 256, math.floor(n / 16777216) % 256) end
local fmt = "fmt " .. le(16) .. string.rep("\0", 16)
local data = "data" .. le(4) .. "abcd"
local function wav(extra) local body = "WAVE" .. fmt .. (extra or "") .. data return "RIFF" .. le(#body) .. body end
ok(LC.SoundLoopMarked(wav()) == false, "a plain .wav carries no loop mark")
ok(LC.SoundLoopMarked(wav("cue " .. le(28) .. le(1) .. string.rep("\0", 24))) == true, "a cue point in it: it loops by itself")
ok(LC.SoundLoopMarked(wav("smpl" .. le(36) .. string.rep("\0", 28) .. le(0) .. le(0))) == false, "a sampler part with no loops: it doesn't")
ok(LC.SoundLoopMarked(wav("smpl" .. le(36) .. string.rep("\0", 28) .. le(1) .. le(0))) == true, "a sampler part with a loop: it does")
ok(LC.SoundLoopMarked("not a wav") == false and LC.SoundLoopMarked(nil) == false, "(anything else: no)")
ok(LC.SoundLoops("player/heartbeat1.wav") and LC.SoundLoops("sound/player/breathe1.wav"), "the heartbeat and the breath are known to loop")
local lp = newPlayer("LoopHearer", "citizen")
ok(LC.SoundLoopSecs(lp, "player/heartbeat1.wav") <= 4, "a beat is stopped after one play", LC.SoundLoopSecs(lp, "player/heartbeat1.wav"))
ok(LC.SoundLoopSecs(lp, "ambient/alarms/alarm1.wav") == LC.SoundLoopMax, "any other self-looping sound on a player: 20 seconds at most")
LC.SoundLoopKeep(lp, "ambient/alarms/alarm1.wav", 45)
ok(LC.SoundLoopSecs(lp, "ambient/alarms/alarm1.wav") == 45, "unless whoever started it said how long")
ok(LC.SoundLoopWatch(lp, "player/heartbeat1.wav") == true and #LC.SoundLoopsGoing(lp) == 1, "started on a player: watched")
ok(LC.SoundLoopWatch(lp, "weapons/pistol/pistol_fire2.wav") == false, "(a sound that doesn't loop isn't)")
ok(LC.SoundLoopsStop(lp) == 1 and #LC.SoundLoopsGoing(lp) == 0, "death and spawn stop every one still going")
-- wording
ok(LC.SocioWhyShown("the mood of the city") == nil and LC.SocioWhyShown("curfew") == "curfew", "'the mood of the city' is never shown as the reason; the others are")
local lines = {}
for _, id in ipairs({ "healthvial", "battery", "bandage", "ration", "water", "medkit", "soap", "radio" }) do lines[LC.MarketExtraDesc(id)] = true end
local nLines = 0
for _ in pairs(lines) do nLines = nLines + 1 end
ok(nLines >= 3 and LC.MarketExtraDesc("battery") == LC.MarketExtraDesc("battery"), "the dealer's extra goods have different lines, each good always the same one", nLines)
local place = LC.DescribePlace(Vector(-90000, -90000, 0), Vector(-91000, -90000, 0))
ok(string.find(place, "%d") == nil and string.find(place, "to the ", 1, true) == 1, "a place with no name is 'to the east', with no distance", place)
-- ammo boxes
if LC.AmmoMax("Pistol") then
    local ap = newPlayer("AmmoFull", "resistance", nil, 900)
    ap.ammo = ap.ammo or {}
    if ap.SetAmmo then ap:SetAmmo(LC.AmmoMax("Pistol"), "Pistol") end
    if (ap:GetAmmoCount("Pistol") or 0) >= LC.AmmoMax("Pistol") then
        ok(LC.AmmoRoom(ap, "Pistol") == 0, "full of pistol rounds: no room")
        LC.GiveItem(ap, "ammo_pistol", 1)
        local okUse, why = LC.ArmsUse(ap, "ammo_pistol")
        ok(not okUse and LC.HasItem(ap, "ammo_pistol") and string.find(tostring(why), "can't carry", 1, true), "a box isn't loaded into full ammo: it stays in the pocket", why)
        if ap.SetAmmo then ap:SetAmmo(0, "Pistol") end
        ok(LC.AmmoRoom(ap, "Pistol") == LC.AmmoMax("Pistol"), "(empty: all the room)")
    end
    ap:SetPos(Vector(-150000, 150000, 0))
end
-- the infested don't hurt their own
local z1, z2, h1 = newPlayer("KinOne", "citizen"), newPlayer("KinTwo", "citizen"), newPlayer("KinHuman", "citizen")
local wasZ = LC.PlayerIsZombie
LC.PlayerIsZombie = function(p) return p == z1 or p == z2 end
ok(LC.InfestedKin(z1, z2) and not LC.InfestedKin(z1, h1) and not LC.InfestedKin(h1, z2) and not LC.InfestedKin(z1, z1), "two infested players are kin; a human and one aren't")
ok(hook.t.EntityTakeDamage.LivingCityInfestedKin(z1, _dmg(z2, 20)) == true, "one's blow on the other does no damage (a shove)")
ok(hook.t.EntityTakeDamage.LivingCityInfestedKin(h1, _dmg(z2, 20)) == nil, "(a human is hurt as ever)")
LC.PlayerIsZombie = wasZ
-- quest kills on the way there
local qp = newPlayer("EarlyKiller", "cp")
local qWas = LC.QuestOf[qp]
local fake = { stage = 1, done = false, owner = qp, stages = { { kind = "goto" }, { kind = "count", event = "killed", need = 3, filter = function(_, _, n) return n ~= "wrong" end } } }
LC.QuestOf[qp] = fake
LC.QuestEvent("killed", qp, "first")
LC.QuestEvent("killed", qp, "first")
LC.QuestEvent("killed", qp, "wrong")
LC.QuestEvent("killed", qp, "second")
ok(fake.stages[2].early == 2 and fake.stage == 1, "kills on the way to the fight are kept for the stage that asks for them (each once, only the right ones)", fake.stages[2].early)
LC.QuestOf[qp] = qWas
ok(LC.QuestNPCSide(nil) == nil and LC.QuestAssist(nil, nil) == 0, "(an ally's kill: nothing without an ally)")
-- sweeps take the camps in turn
local camps = LC.ZonesOfKindShared and LC.ZonesOfKindShared("rebel") or {}
if #camps >= 2 then
    local seen, distinct = {}, 0
    for i = 1, #camps do
        local z = LC.NextSweepZone(CurTime() + 100000 + i)
        if z and not seen[z] then seen[z] = true distinct = distinct + 1 end
    end
    ok(distinct == #camps, "every rebel camp has its sweep before any has a second", distinct .. " of " .. #camps)
end
-- the Cremator and the eerie music keep to the infestation
ok(LC.CrematorEscortHere(Vector(250000, 250000, 0)) == false and LC.ByInfest(Vector(250000, 250000, 0)) == false, "far from any infestation: no escort, no eerie music")
ok(LC.CrematorNearestNode(nil) == nil and LC.CrematorPace() == 2, "(the Cremator's pace is twice the walker's)")
for _, p in ipairs({ lp, z1, z2, h1, qp }) do p:SetPos(Vector(-150000, 150000, 0)) end
end
PlaytestNov13Tests()
function PlaytestNov14Tests() -- (the owner's answers, 14 November)
section("14 November: vortigaunts chosen at the start, the rescue, revive priority, every attacker counted")
-- a human can't take up the Free Vortigaunt role, nor the Vortigaunt faction
local hum = newPlayer("HumanNotVort", "resistance", nil, 2000)
ok(not LC.CanJoinFaction(hum, "resistance", "vortigaunt"), "a human can't take up the Free Vortigaunt role")
ok(not LC.CanJoinFaction(hum, "vort"), "nor become a shackled vortigaunt from F4")
ok(LCF.Get("resistance").specialsById.vortigaunt.hidden == true, "the Free Vortigaunt is off the Resistance's list")
-- the choice at a new life
local v = newPlayer("NewLifeVort", "citizen")
v:SetPData("lc_chosen", "0")
v.lcRaceAskedFor = nil
net.sent = {}
LC.OpenCharacterCreator(v)
local asked = false
for _, m in ipairs(net.sent) do if m.name == "lc_race_pick" then asked = true end end
ok(asked, "a new life is asked first: a citizen or a vortigaunt")
ok(LC.BecomeVortSlave(v) and v:GetNW2String("lcf_faction", "") == "vort" and LC.IsVortChar(v), "choosing the vortigaunt: shackled, in the Vortigaunt faction")
ok(string.find(v:GetNW2String("lc_char", ""), "Laborer VLB", 1, true) == 1, "with a laborer's designation, not a name", v:GetNW2String("lc_char", ""))
ok(not LC.CanJoinFaction(v, "citizen") and not LC.CanJoinFaction(v, "resistance"), "a vortigaunt can't become human")
ok(not LC.CanJoinFaction(v, "resistance", "vortigaunt"), "nor free itself from F4: the Resistance frees it")
local okCall, whyCall = LC.VortCall(v)
ok(not okCall and string.find(tostring(whyCall), "quiet", 1, true), "it can't reach out straight away", whyCall)
-- the rescue after 10 minutes shackled
v.lcVortShackledFor = 10 * 60 - 1
LC.VortRescueTick(CurTime())
ok(v.lcVortRescue ~= nil, "ten minutes shackled: a Resistance team comes for it")
v.lcVortRescue.untilT = CurTime() - 1
local seenWas = LC.SeenBySecurity
LC.SeenBySecurity = function() return false end
LC.VortRescueTick(CurTime())
LC.SeenBySecurity = seenWas
ok(v:GetNW2String("lcf_faction", "") == "resistance" and v:GetNW2String("lcf_special", "") == "vortigaunt", "and the shackles are cut: a Free Vortigaunt of the Resistance")
ok(LC.CanJoinFaction(v, "resistance", "vortigaunt"), "(theirs to keep)")
-- revive priority: under fire it fights; five seconds without a bullet, it goes to its leader
local lead = newPlayer("DownedLead", "cp")
local npcR, stR = LC.Spawners.cop(lead:GetPos() + Vector(60, 0, 4))
stR.backupFor, stR.backupUntil = lead, CurTime() + 300
local downWas = LC.IsDowned
LC.IsDowned = function(p) return p == lead end
stR.bulletHitAt = CurTime()
ok(LC.SquadReviveStep(npcR, stR, lead, CurTime()) == false, "hit by a bullet just now: it keeps fighting")
stR.bulletHitAt = CurTime() - 6
stR.state = "hostile"
ok(LC.SquadReviveStep(npcR, stR, lead, CurTime()) == true and stR.state ~= "hostile", "five seconds without a bullet: it breaks off and sees to its leader, even mid-fight")
LC.IsDowned = downWas
-- collapse: yellow crawls
ok(math.abs(LC.ChaosYellowRate - 0.0125) < 1e-6, "yellow fills the collapse at 5% of the quarter it did")
for _, p in ipairs({ hum, v, lead }) do p:SetPos(Vector(-150000, 150000, 0)) end
if IsValid(npcR) then npcR:Remove() end
end
PlaytestNov14Tests()
function NearYouTests() -- (14 November: the debug report's "Near you": who is near each player, and who jumped, appeared or was taken away)
    section("The debug report says who is near you, and who jumped or vanished there")
    local watcher = newPlayer("NearWatcher", "cp")
    watcher:SetPos(Vector(-160000, -160000, 0))
    local npc = LC.Spawners.cop(watcher:GetPos() + Vector(300, 0, 4))
    LC.NearWatchTick()
    npc:SetPos(watcher:GetPos() + Vector(900, 0, 4))
    LC.NearWatchTick()
    local report = LC.BuildReport()
    ok(string.find(report, "== Near you ==", 1, true) and string.find(report, "NearWatcher at", 1, true), "the report has a Near you section for each player")
    ok(string.find(report, "jumped npc_metropolice", 1, true) ~= nil, "a unit moved by the code near a player is noted as jumped")
    if IsValid(npc) then npc:Remove() end
    watcher:SetPos(Vector(-150000, 150000, 0))
end
NearYouTests()
function MapPATests() -- (14 November: the map's own Overwatch PA, in the owner's voice, every 15 seconds)
    section("The map's own PA lines: one every few minutes, never over the city's announcer")
    LC.MapPANext, LC.MapPAHeld, LC.MapPALet = 0, 0, 0
    local quietWas = LC.PAQuiet
    LC.PAQuiet = function() return 600 end
    local t0 = CurTime()
    ok(LC.MapPAAllowed("npc/overwatch/cityvoice/f_anticitizenreport_spkr.wav", t0) == true, "the map's first PA line plays")
    ok(LC.MapPAAllowed("npc/overwatch/cityvoice/f_innactionisconspiracy_spkr.wav", t0 + 15) == false, "another 15 seconds later is silenced")
    ok(LC.MapPAAllowed("npc/overwatch/cityvoice/f_capitalmalcompliance_spkr.wav", t0 + 5 * 60 + 1) == true, "five minutes on, one more")
    LC.PAQuiet = function() return 10 end
    ok(LC.MapPAAllowed("npc/overwatch/cityvoice/f_rationunitsdeduct_3_spkr.wav", t0 + 20 * 60) == false, "never right after the city's own announcer")
    ok(LC.MapPAAllowed("vo/npc/male01/hi01.wav", t0) == true, "anything else is untouched")
    ok(LC.MapPAHeld == 2 and LC.MapPALet == 2, "(counted for the debug report)")
    LC.PAQuiet = quietWas
    LC.MapPANext = 0
end
MapPATests()
-- The owner's 7 November playtest, part 2 (sv_livingcity_fieldops.lua and friends): a unit each.
function RetakeFieldTests()
    local function FieldPost(p, spec, tid, violent)
        spec.id = 81000 + math.random(1, 999999)
        spec.tmpl = spec.tmpl or { id = tid or "fieldtest" }
        spec.violent = violent
        spec.faction = LC.QuestFaction(p)
        spec.expiresPost = CurTime() + 999
        spec.data = spec.data or {}
        LC.Postings[spec.faction] = LC.Postings[spec.faction] or {}
        table.insert(LC.Postings[spec.faction], spec)
        p.lcqNext = 0
        LC.AcceptPosting(p, spec.id)
        return LC.QuestOf[p]
    end
    local function FieldTemplate(id)
        for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end
    end
    local function NetCount(name)
        local n = 0
        for _, m in ipairs(net.sent) do if m.name == name then n = n + 1 end end
        return n
    end
    section("Retake the block: armed backup, every rebel on the ground, no respawns, the counterattack, flashbangs that blind")
    _setcvar("lc_quest_allies", 0) -- (the squads have their own unit)
    local P = Vector(-186000, -186000, 0)
    -- backup comes armed to a gunfight
    local caller = newPlayer("BackupCaller", "cp", nil, 300)
    caller:SetPos(P)
    caller.lcShotAt = nil
    caller.active = nil
    ok(not LC.BackupViolent(caller), "hands empty, nobody shooting, no violent job: not a gunfight")
    caller:Give("weapon_pistol")
    caller:SelectWeapon("weapon_pistol")
    ok(LC.BackupViolent(caller), "a gun in hand: a gunfight")
    caller.active = nil
    local shooter = LC.SpawnRebel(P + Vector(900, 0, 4), nil)
    hook.Run("EntityTakeDamage", caller, _dmg(shooter, 5))
    ok(LC.BackupViolent(caller), "shot at in the last 30 seconds: a gunfight")
    caller.lcShotAt = CurTime() - 31
    ok(not LC.BackupViolent(caller), "31 seconds ago: not any more")
    if IsValid(shooter) then shooter:Remove() end
    caller:Give("weapon_pistol")
    caller:SelectWeapon("weapon_pistol")
    -- (the call goes out on the radio since 13 November: the gun just put away for it still counts)
    _radioUp(caller)
    local units = {}
    for i = 1, 3 do
        local c, cst = LC.SpawnCop(P + Vector(200 + i * 40, 0, 4))
        if IsValid(c) then cst.state = "idle" units[#units + 1] = c end
    end
    caller.lcBackupNext = 0
    LC.CallBackup(caller)
    local guns, smg, sticks = 0, 0, 0
    for _, c in ipairs(units) do
        local st = LC.NPCs[c]
        local w = c:GetActiveWeapon()
        local cls = w and w:GetClass() or ""
        if st and st.backupFor == caller and (cls == "weapon_pistol" or cls == "weapon_smg1") then guns = guns + 1 end
        if cls == "weapon_smg1" then smg = smg + 1 end
        if cls == "weapon_stunstick" then sticks = sticks + 1 end
    end
    ok(#units == 3 and guns == 3 and sticks == 0, "backup called with a gun out comes with guns, not stunsticks", guns .. " guns, " .. sticks .. " sticks")
    ok(smg >= 1 and smg < 3, "pistols and SMGs, both", smg)
    local u1 = units[1]
    if IsValid(u1) then
        LC.CalmOne(u1, LC.NPCs[u1], CurTime())
        ok(u1:GetActiveWeapon():GetClass() == "weapon_stunstick", "(calming down after a fight puts the stick back in hand)")
        LC.KeepBackupGunsOut()
        local cls = u1:GetActiveWeapon():GetClass()
        ok(cls == "weapon_pistol" or cls == "weapon_smg1", "while they're with you, the gun comes straight back out", cls)
    end
    for _, c in ipairs(units) do if IsValid(c) then LC.NPCs[c] = nil c:Remove() end end
    caller:SetPos(Vector(-150000, 150000, 0))

    -- retaking ground: every rebel on it, nobody new turns up, and they come back for it
    local G = Vector(-188000, -186000, 0)
    local camp = { pos = G + Vector(1800, 0, 0), r = 300, h = 200, kind = "rebel", group = 0 }
    local z = { pos = G, r = 300, h = 200, kind = "rebel", group = 0, grown = true, seed = camp }
    table.insert(LC.Zones, camp)
    table.insert(LC.Zones, z)
    local unit = newPlayer("RetakeAll", "cp", nil, 300)
    unit:SetPos(G + Vector(0, -3000, 0))
    local t = FieldTemplate("cp_retake")
    local spec = t and t.build(unit, z)
    ok(spec ~= nil and #spec.stages == 3, "the retake job builds: get there, clear it, hold it")
    local q = spec and FieldPost(unit, spec, "cp_retake", true)
    if q then
        q.tmpl = t
        unit:SetPos(G)
        _run(1)
        local st = q.stages[q.stage]
        ok(st.kind == "count" and st.untallied, "on the ground: the job is to clear it")
        ok(LC.RebelQuietAt(G, z.r) and LC.RebelQuietAt(camp.pos, camp.r), "and no new rebels turn up on it (or next door) while the team clears it")
        local fromThere = 0
        for _ = 1, 10 do
            local _, zz = LC.RebelSpawnPos()
            if zz == z or zz == camp then fromThere = fromThere + 1 end
        end
        ok(fromThere == 0, "the city's own spawning skips it", fromThere)
        local onIt = LC.RebelsOnGround(G, math.max(350, z.r + 150))
        ok(#onIt >= 3, "the rebels holding it are waiting", #onIt)
        -- three down isn't enough any more (the owner: 25 dead, and it only counted 3)
        for i = 1, math.min(3, #onIt - 1) do
            onIt[i]:SetHealth(0)
            hook.Run("OnNPCKilled", onIt[i], unit)
        end
        _run(1)
        ok(q.stages[q.stage] == st and string.find(st.text, "left)", 1, true) ~= nil, "three down and one still standing: not done yet", st.text)
        for _, npc in ipairs(LC.RebelsOnGround(G, math.max(350, z.r + 150))) do
            npc:SetHealth(0)
            hook.Run("OnNPCKilled", npc, unit)
        end
        _run(1)
        ok(q.stages[q.stage].kind == "hold", "every rebel on the ground down: now hold it")
        -- the counterattack
        local seen = LC.IsSeen
        LC.IsSeen = function() return false end
        q.data.waves.nextAt = CurTime()
        _run(1)
        local wave = 0
        for npc, wst in pairs(LC.NPCs) do
            if wst.wave and IsValid(npc) and wst.raid and wst.raid.target:Distance(G) < 300 then wave = wave + 1 end
        end
        ok(wave >= 3, "holding it, a wave of fighters comes to take it back", wave)
        -- one clock (21 November): the wave wiped out, the next comes 6 s later, not at its own time
        local w = q.data.waves
        ok(w.i == 1 and w.nextAt - CurTime() >= 7, "the next wave is due on the clock", w.i, w.nextAt - CurTime())
        for _, npc in ipairs(w.live) do if IsValid(npc) then npc:SetHealth(0) hook.Run("OnNPCKilled", npc, unit) end end
        _run(7)
        ok(w.i == 2 and #w.live >= 2, "wiped out, the next wave comes 6 seconds later", w.i, #w.live)
        LC.IsSeen = seen
        ok(LC.HoldWaveGap(w, 2) <= LC.HoldWaveGap(w, 1) and LC.HoldWaveGap({ secs = 285 }, 4) < LC.HoldWaveGap({ secs = 285 }, 2),
            "each wave sooner than the last (Valve's 70, 50, 40, 25, 9 s, scaled)")
        _run(36)
        ok(q.done, "held for 30 seconds: the ground is retaken")
        ok(not LC.RebelQuietAt(G, 0) or (LC.RebelQuiet[#LC.RebelQuiet] or {}).untilT < CurTime() + 200, "and the quiet lifts a couple of minutes after")
    end
    for npc, wst in pairs(LC.NPCs) do if wst.wave and IsValid(npc) then LC.NPCs[npc] = nil npc:Remove() end end
    for zi = #LC.Zones, 1, -1 do if LC.Zones[zi] == z then table.remove(LC.Zones, zi) end end
    for zi = #LC.Zones, 1, -1 do if LC.Zones[zi] == camp then table.remove(LC.Zones, zi) end end
    LC.RebelQuiet = {}
    unit:SetPos(Vector(-150000, 150000, 0))

    -- flashbangs blind, each for their own while
    local F = Vector(-190000, -186000, 0)
    local blinded = {}
    for i = 1, 6 do
        local r, rst = LC.SpawnRebel(F + Vector(i * 30, 0, 4), nil)
        if IsValid(r) then r:SetEnemy(unit) blinded[#blinded + 1] = { r, rst } end
    end
    LC.Detonate("flash", F + Vector(100, 0, 0), unit)
    local okAll, secs, cleared = true, {}, true
    for _, b in ipairs(blinded) do
        local left = (b[2].stunnedUntil or 0) - CurTime()
        if not b[2].flashBlind or left < 3.9 or left > 9.1 then okAll = false end
        secs[math.floor(left * 10)] = true
        if b[1]:GetEnemy() ~= NULL and b[1]:GetEnemy() ~= nil then cleared = false end
    end
    ok(#blinded == 6 and okAll, "a flashbang blinds the rebels in the blast for 4 to 9 seconds")
    ok(table.Count(secs) >= 2, "a different time for each of them", table.Count(secs))
    ok(cleared, "and they lose who they were shooting at")
    -- (the owner, 13 November: "cover their eyes with their hand (preferably left hand ...) and stumble about")
    local b1 = blinded[1][1]
    ok(b1:GetNW2String("lc_handface", "") == "eyes" and b1:GetNW2Float("lc_handface_until", 0) > CurTime() + 3, "they cover their eyes with their left hand for as long as they're blind")
    LC.FlashTick(CurTime() + 2.1)
    ok(b1:IsCurrentSchedule(SCHED_FORCED_GO), "and stumble about, not stand idle")
    -- (the owner, 11 November: "they never moved nor stopped shooting me". Blind, the guns are out of their hands)
    ok(LC.LastFlash and LC.LastFlash.blinded == 6 and has(unit.chat, "[Flashbang] 6 blinded"), "whoever threw it is told how many it caught")
    do
        local gunman, gst = blinded[1][1], blinded[1][2]
        local held = { { cls = "weapon_smg1", removed = false }, { cls = "weapon_pistol", removed = false } }
        local given, selected = {}, nil
        local ents2 = {}
        for i, h in ipairs(held) do
            local w = ents.Create(h.cls) w:Spawn()
            ents2[i] = w
        end
        gst.flashWeapons = nil
        gunman.GetWeapons = function() local out = {} for _, w in ipairs(ents2) do if IsValid(w) then out[#out + 1] = w end end return out end
        gunman.GetActiveWeapon = function() return ents2[1] end
        gunman.Give = function(_, cls) given[#given + 1] = cls end
        gunman.SelectWeapon = function(_, cls) selected = cls end
        LC.FlashDisarm(gunman, gst)
        ok(not IsValid(ents2[1]) and not IsValid(ents2[2]) and gst.flashWeapons and #gst.flashWeapons == 2, "blind, every weapon is out of their hands: nothing to shoot with")
        LC.FlashRearm(gunman, gst)
        ok(#given == 2 and selected == "weapon_smg1" and gst.flashWeapons == nil, "and back in them when it wears off, the one they held in hand")
        gunman.GetWeapons, gunman.GetActiveWeapon, gunman.Give, gunman.SelectWeapon = nil, nil, nil, nil
    end
    LC.FlashTick(CurTime() + 10)
    local over = true
    for _, b in ipairs(blinded) do if b[2].flashBlind then over = false end end
    ok(over, "and it wears off")
    for _, b in ipairs(blinded) do if IsValid(b[1]) then LC.NPCs[b[1]] = nil b[1]:Remove() end end
end
RetakeFieldTests()

function QuestSquadTests()
    local function FieldPost(p, spec, tid, violent)
        spec.id = 81000 + math.random(1, 999999)
        spec.tmpl = spec.tmpl or { id = tid or "fieldtest" }
        spec.violent = violent
        spec.faction = LC.QuestFaction(p)
        spec.expiresPost = CurTime() + 999
        spec.data = spec.data or {}
        LC.Postings[spec.faction] = LC.Postings[spec.faction] or {}
        table.insert(LC.Postings[spec.faction], spec)
        p.lcqNext = 0
        LC.AcceptPosting(p, spec.id)
        return LC.QuestOf[p]
    end
    local function FieldTemplate(id)
        for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end
    end
    local function NetCount(name)
        local n = 0
        for _, m in ipairs(net.sent) do if m.name == name then n = n + 1 end end
        return n
    end
    section("A squad of your own side on every violent job")
    _setcvar("lc_quest_allies", 2)
    local S = Vector(-192000, -186000, 0)
    local spot = LC.AlarmSquadSpot
    LC.AlarmSquadSpot = function(pos) return pos + Vector(600, 0, 0) end
    -- Civil Protection: a free unit nearby, and one brought in
    local cop = newPlayer("SquadCop", "cp", nil, 300)
    cop:SetPos(S)
    local near, nst = LC.SpawnCop(S + Vector(300, 0, 4))
    if nst then nst.state = "idle" end
    local q = FieldPost(cop, { title = "Squad test", reward = 1, limit = 300, desc = "",
        stages = { { kind = "hold", pos = S + Vector(0, 5000, 0), secs = 999, r = 50, text = "wait" } } }, "squadtest", true)
    local squad = q and LC.QuestSquadOf(q) or {}
    local armed, withMe = 0, 0
    for _, n in ipairs(squad) do
        local st = LC.NPCs[n]
        if st.backupFor == cop then withMe = withMe + 1 end
        local cls = n:GetActiveWeapon() and n:GetActiveWeapon():GetClass() or ""
        if cls == "weapon_pistol" or cls == "weapon_smg1" then armed = armed + 1 end
    end
    ok(#squad == 2 and withMe == 2, "a unit on a violent job gets two units with them", #squad)
    ok(armed == 2, "with guns, not sticks", armed)
    ok(IsValid(near) and LC.NPCs[near].questSquad == q, "a free unit nearby first")
    local spawned
    for _, n in ipairs(squad) do if LC.NPCs[n].qsSpawned then spawned = n end end
    ok(spawned ~= nil, "and the rest brought in out of sight")
    -- one down, another comes
    if IsValid(near) then near:SetHealth(0) end
    LC.QuestSquads[q].nextTop = 0
    LC.QuestSquadTick(CurTime())
    ok(#LC.QuestSquadOf(q) == 2, "one falls: another comes", #LC.QuestSquadOf(q))
    LC.FinishQuest(q, true)
    LC.QuestSquadTick(CurTime())
    local released = true
    for _, n in ipairs(squad) do
        local st = IsValid(n) and LC.NPCs[n]
        if st and (st.questSquad or st.backupFor == cop) then released = false end
    end
    ok(released and LC.QuestSquads[q] == nil, "the job's over: they go back to their own business")
    -- not violent: nobody
    local q2 = FieldPost(cop, { title = "Quiet test", reward = 1, limit = 300, desc = "",
        stages = { { kind = "hold", pos = S + Vector(0, 5000, 0), secs = 999, r = 50, text = "wait" } } }, "quiettest", false)
    ok(q2 and #LC.QuestSquadOf(q2) == 0, "an ordinary job: no squad")
    if q2 then LC.FinishQuest(q2, false) end
    -- the sweep brings its own team
    local q3 = FieldPost(cop, { title = "Sweep test", reward = 1, limit = 300, desc = "",
        stages = { { kind = "hold", pos = S + Vector(0, 5000, 0), secs = 999, r = 50, text = "wait" } } }, "cp_joinsweep", true)
    ok(q3 and #LC.QuestSquadOf(q3) == 0, "joining a sweep: the sweep team is the squad")
    if q3 then LC.FinishQuest(q3, false) end
    cop:SetPos(Vector(-150000, 150000, 0))
    -- the Overwatch: soldiers
    local ota = newPlayer("SquadOTA", "cp", nil, 2500)
    LC.Condition(ota)
    ota:SetPos(S + Vector(0, 3000, 0))
    local q4 = FieldPost(ota, { title = "OTA squad", reward = 1, limit = 300, desc = "",
        stages = { { kind = "hold", pos = S + Vector(0, 9000, 0), secs = 999, r = 50, text = "wait" } } }, "otatest", true)
    local soldiers = 0
    for _, n in ipairs(q4 and LC.QuestSquadOf(q4) or {}) do if LC.NPCs[n].role == "soldier" then soldiers = soldiers + 1 end end
    ok(LC.QuestFaction(ota) == "ota" and soldiers == 2, "the Overwatch get soldiers", soldiers)
    if q4 then LC.FinishQuest(q4, false) LC.QuestSquadTick(CurTime()) end
    ota:SetPos(Vector(-150000, 150000, 0))
    -- the Resistance: fighters who follow you
    local reb = newPlayer("SquadRebel", "resistance", nil, 900)
    reb:SetPos(S + Vector(0, -3000, 0))
    local q5 = FieldPost(reb, { title = "Rebel squad", reward = 1, limit = 300, desc = "",
        stages = { { kind = "hold", pos = S + Vector(0, -9000, 0), secs = 999, r = 50, text = "wait" } } }, "rebtest", true)
    local following = 0
    for _, n in ipairs(q5 and LC.QuestSquadOf(q5) or {}) do if LC.NPCs[n].follow == reb then following = following + 1 end end
    ok(following == 2, "the Resistance get two fighters who follow them", following)
    if q5 then
        local mates = LC.QuestSquadOf(q5)
        LC.FinishQuest(q5, true)
        LC.QuestSquadTick(CurTime())
        local home = true
        for _, n in ipairs(mates) do if IsValid(n) and LC.NPCs[n] and LC.NPCs[n].follow then home = false end end
        ok(home, "and they head home when it's done")
    end
    reb:SetPos(Vector(-150000, 150000, 0))
    -- switched off
    _setcvar("lc_quest_allies", 0)
    local q6 = FieldPost(cop, { title = "Off test", reward = 1, limit = 300, desc = "",
        stages = { { kind = "hold", pos = S + Vector(0, 5000, 0), secs = 999, r = 50, text = "wait" } } }, "offtest", true)
    ok(q6 and #LC.QuestSquadOf(q6) == 0, "lc_quest_allies 0: nobody")
    if q6 then LC.FinishQuest(q6, false) end
    _setcvar("lc_quest_allies", 2)
    LC.AlarmSquadSpot = spot
    for npc, st in pairs(LC.NPCs) do if st.qsSpawned and IsValid(npc) then LC.NPCs[npc] = nil npc:Remove() end end
end
QuestSquadTests()

function MissingZombineTests()
    local function FieldPost(p, spec, tid, violent)
        spec.id = 81000 + math.random(1, 999999)
        spec.tmpl = spec.tmpl or { id = tid or "fieldtest" }
        spec.violent = violent
        spec.faction = LC.QuestFaction(p)
        spec.expiresPost = CurTime() + 999
        spec.data = spec.data or {}
        LC.Postings[spec.faction] = LC.Postings[spec.faction] or {}
        table.insert(LC.Postings[spec.faction], spec)
        p.lcqNext = 0
        LC.AcceptPosting(p, spec.id)
        return LC.QuestOf[p]
    end
    local function FieldTemplate(id)
        for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end
    end
    local function NetCount(name)
        local n = 0
        for _, m in ipairs(net.sent) do if m.name == name then n = n + 1 end end
        return n
    end
    section("The Missing Unit, part 2: a zombine, no choice window")
    _setcvar("lc_quest_allies", 0)
    local Z = Vector(-194000, -186000, 0)
    local iz = { pos = Z, r = 300, kind = "infest", group = 0 }
    -- (the story picks one infestation at random: the others, such as the prelude's, are set aside for
    -- this unit so it always picks this one, and put back where they were at the end)
    local aside = {}
    for zi = #LC.Zones, 1, -1 do
        if LC.Zones[zi].kind == "infest" then table.insert(aside, 1, { zi, table.remove(LC.Zones, zi) }) end
    end
    table.insert(LC.Zones, iz)
    local function Start(p)
        local spec = LC.Chains.missing.parts.retaliation.build(p, { cause = "infestation" })
        if not spec then return nil end
        return FieldPost(p, spec, "missing/retaliation", false)
    end
    local function Fight(q, p)
        p:SetPos(Z)
        _run(1)
        for _ = 1, 3 do
            local zb = LC.SpawnZombie(Z + Vector(math.random(-80, 80), math.random(-80, 80), 4), iz)
            zb:SetHealth(0)
            hook.Run("OnNPCKilled", zb, p)
        end
        _run(0.5)
    end
    local cop = newPlayer("MissingCop", "cp", nil, 700)
    local choices = NetCount("lcq_choice_open")
    local q = Start(cop)
    ok(q ~= nil, "the infestation part starts")
    if q then
        Fight(q, cop)
        local st = q.stages[q.stage]
        local zb = q.data.zombine
        ok(st.kind ~= "choice" and IsValid(zb) and zb:GetClass() == "npc_zombine", "three down: a zombine appears, and no choice window", IsValid(zb) and zb:GetClass() or "none")
        ok(NetCount("lcq_choice_open") == choices, "nothing takes over the cursor in the middle of a fight")
        LC.FlushNotices()
        local told = _lastnet("lc_notice")
        ok(told ~= nil and told.to == cop, "a notice on screen says who it must be, and what to do")
        ok(string.find(st.text, "Kill him", 1, true) and string.find(st.text, "leave the infestation", 1, true), "kill him, or leave the infestation", st.text)
        if IsValid(zb) then
            zb:SetHealth(0)
            hook.Run("OnNPCKilled", zb, cop)
        end
        _run(0.5)
        ok(q.done and q.chainEnd == "mercy", "killed: his suffering is over (the old 'put him down' ending)", tostring(q.chainEnd))
    end
    cop:SetPos(Vector(-150000, 150000, 0))
    local cop2 = newPlayer("MissingCop2", "cp", nil, 700)
    local q2 = Start(cop2)
    if q2 then
        Fight(q2, cop2)
        local zb = q2.data.zombine
        cop2:SetPos(Z + Vector(3000, 0, 0))
        _run(3)
        ok(q2.done and q2.chainEnd == "left", "walk out of the infestation instead: a cleanup crew deals with him (the old 'leave him' ending)", tostring(q2.chainEnd))
        ok(not IsValid(zb), "and he's gone when the job's over")
    else
        ok(false, "(the second run didn't start)")
    end
    cop2:SetPos(Vector(-150000, 150000, 0))
    for zi = #LC.Zones, 1, -1 do if LC.Zones[zi] == iz then table.remove(LC.Zones, zi) end end
    for _, a in ipairs(aside) do table.insert(LC.Zones, math.min(a[1], #LC.Zones + 1), a[2]) end
end
MissingZombineTests()

function MarketTests() -- (the owner, 7 November: the Administrator's say over the Commissary; every seller playing off each other)
    section("The market: the Administrator's Commissary controls, demand, and the black market following shortages")
    _setcvar("lc_market", 1)
    _setcvar("lc_market_demand", 1)
    _setcvar("lc_market_scarce_stock", 2)
    local MS = LC.MarketState
    MS.rules, MS.stock, MS.restockAt, MS.demand = {}, {}, {}, {}
    local boss = newPlayer("MarketBoss", "admin")
    local cit = newPlayer("MarketCitizen", "citizen")
    local cop = newPlayer("MarketCop", "cp")
    LC.AddCredits(cit, 2000)
    local bread, coffee, healthkit = LCS.GoodsById.bread, LCS.GoodsById.coffee, LCS.GoodsById.healthkit
    -- untouched: everything as it was
    ok(LC.MarketCommissaryMul(bread) == 1 and LC.MarketMinStanding(bread) == bread.minStanding and LC.MarketBlackMul(LCS.BlackById.lockpick) == 1
        and #LC.MarketBlackList() == #LCS.Black and #LC.MarketLabList() == #LCS.Lab and LC.MarketBuyback("gun_pistol", 72) == 72,
        "nothing touched and nothing bought: every price, standing and list is as it always was")
    -- only the Administrator
    local okC, whyC = LC.MarketSet(cit, "bread", "restrict", "1")
    local okP = LC.MarketSet(cop, "bread", "price", "3")
    ok(not okC and not okP and whyC == "Only the City Administrator." and not LC.MarketRestricted(bread), "only the City Administrator can change the Commissary")
    ok(not LC.MarketSet(boss, "gren_gas", "restrict", "1"), "Civil Protection's own issue isn't hers to restrict")
    local panels = 0
    local realSend = LC.SendCompressed
    LC.SendCompressed = function(msg, tbl, rec) if msg == "lc_market_admin" then panels = panels + 1 end return realSend(msg, tbl, rec) end
    ok(not LC.MarketOpenAdmin(cit) and LC.MarketOpenAdmin(boss) and panels == 1, "the panel opens for the Administrator only")
    LC.SendCompressed = realSend
    -- restrict
    ok(LC.MarketSet(boss, "bread", "restrict", "1") and LC.MarketRestricted(bread), "she restricts bread")
    local c0 = LC.Credits(cit)
    ok(not LC.Buy(cit, "bread") and LC.Credits(cit) == c0, "a restricted good can't be bought")
    local can, why = LC.CanBuy(cit, bread)
    ok(not can and why == "Restricted by the Administrator.", "and the shop says why", why)
    local shopT
    LC.SendCompressed = function(msg, tbl, rec) if msg == "lce_shop" then shopT = tbl end return realSend(msg, tbl, rec) end
    LC.OpenShop(cit, true)
    LC.SendCompressed = realSend
    local row
    for _, g in ipairs(shopT and shopT.goods or {}) do if g.id == "bread" then row = g end end
    ok(row and row.ok == false and row.market == "Restricted by the Administrator", "it's still on the shelf, greyed, marked restricted", row and tostring(row.market))
    -- it turns up on the black market, at a premium
    local bm = LC.MarketBlackById("mkt_bread")
    local listed = false
    for _, g in ipairs(LC.MarketBlackList()) do if g.id == "mkt_bread" then listed = true end end
    ok(bm and listed and LC.BlackPrice(bm) > math.ceil(bread.price * 1.5), "restricted at the Commissary: the dealer has it, at a premium", bm and LC.BlackPrice(bm))
    ok(LC.MarketBlackNote(bm) == "Hard to get in the city", "and his window says why", tostring(LC.MarketBlackNote(bm)))
    local realAccess = LC.MarketAccess
    LC.MarketAccess = function() return true end
    local cb, bp = LC.Credits(cit), LC.BlackPrice(bm)
    ok(LC.BlackBuy(cit, "mkt_bread") and LC.HasItem(cit, "bread") and LC.Credits(cit) == cb - bp, "and sells it")
    -- the Resistance's side: the quartermaster's price and the scientist (tablets: he can make them)
    ok(LC.MarketSet(boss, "tablets", "restrict", "1"), "she restricts water tablets")
    local tabBM = LCS.BlackById.tablets
    ok(LC.BlackPrice(tabBM) >= math.floor(tabBM.price * 1.9), "the dealer's usual tablets double in price", LC.BlackPrice(tabBM))
    local labHas = LC.MarketLabById("mkt_tablets")
    ok(labHas and labHas.needs and labHas.needs.chemicals == 1 and LC.LabPrice(labHas) > 0, "the Resistance's scientist can make them while the Commissary won't sell them")
    ok(LC.QuartermasterPrice(tabBM) < LC.BlackPrice(tabBM), "the quartermaster sells them to his own cheaper than the dealer")
    -- unrestricted: it drops off again
    ok(LC.MarketSet(boss, "bread", "restrict", "0") and LC.MarketBlackById("mkt_bread") == nil and LC.MarketLabById("mkt_tablets") ~= nil,
        "on sale again: the dealer stops carrying bread")
    ok(not LC.BlackBuy(cit, "mkt_bread"), "and can't sell it any more")
    -- price
    ok(LC.MarketSet(boss, "coffee", "price", "2") and LC.GoodsPrice(cit, coffee) == math.max(1, math.floor(coffee.price * 2 * (LC.LoyalPriceMul(cit) or 1) + 0.5)),
        "a price at twice the usual costs twice as much")
    ok(LC.MarketSet(boss, "coffee", "price", "99") and LC.MarketCommissaryMul(coffee) == 5, "never more than five times")
    ok(LC.MarketSet(boss, "coffee", "price", "0.01") and LC.MarketCommissaryMul(coffee) == 0.5, "never less than half")
    ok(LC.MarketBlackById("mkt_coffee") == nil, "cheap at the Commissary: nothing for the dealer")
    LC.MarketSet(boss, "coffee", "price", "5")
    ok(LC.MarketBlackById("mkt_coffee") ~= nil, "five times the price: the dealer picks it up")
    -- standing
    ok(LC.MarketSet(boss, "bread", "standing", "400") and LC.MarketMinStanding(bread) == 400, "bread for the Exemplary only")
    local cs, wb = LC.CanBuy(cit, bread)
    ok(not cs and wb == "Requires Exemplary standing.", "a citizen is told what it needs", wb)
    LC.MarketSet(boss, "bread", "standing", "250")
    local _, wb2 = LC.CanBuy(cit, bread)
    ok(wb2 == "Requires 250 Civil Standing.", "a number of hers is said as it is", wb2)
    LC.AddStanding(cit, 300 - LC.Standing(cit))
    ok(LC.Buy(cit, "bread"), "with the standing, it's sold")
    ok(LC.MarketSet(boss, "bread", "standing", "default") and LC.MarketMinStanding(bread) == bread.minStanding, "and back to the usual")
    -- supply: scarce
    ok(LC.MarketSet(boss, "healthkit", "supply", "scarce") and LC.MarketStock("healthkit") == 2, "a medical kit made scarce: two at a time")
    LC.AddStanding(cit, 500 - LC.Standing(cit))
    ok(LC.Buy(cit, "healthkit") and LC.MarketStock("healthkit") == 1, "one bought, one left")
    ok(string.find(LC.MarketCommissaryNote(healthkit) or "", "Scarce: 1 left, more in", 1, true) ~= nil, "the shop says how many and when more come", LC.MarketCommissaryNote(healthkit))
    ok(LC.Buy(cit, "healthkit") and not LC.Buy(cit, "healthkit"), "then it's sold out")
    ok(LC.MarketBlackById("mkt_healthkit") ~= nil, "sold out at the Commissary: the dealer has them")
    MS.restockAt.healthkit = CurTime() - 1
    LC.MarketTick()
    ok(LC.MarketStock("healthkit") == 1, "one more comes in, slowly")
    LC.MarketSet(boss, "healthkit", "supply", "plentiful")
    ok(LC.MarketStock("healthkit") == nil and LC.MarketBlackById("mkt_healthkit") == nil, "plentiful: no limit, and the dealer drops them")
    -- demand
    _setcvar("lc_market_demand_halflife", 30)
    MS.demand = {}
    local lp = LCS.BlackById.lockpick
    local base = LC.BlackPrice(lp)
    for _ = 1, 8 do LC.MarketBought(lp, "black") end
    local up = LC.BlackPrice(lp)
    ok(up > base and up <= math.floor(base * 1.5 + 1), "everyone buying lockpicks puts the price up, within the cap", base .. " -> " .. up)
    ok(string.find(LC.MarketBlackNote(lp) or "", "In demand: price up", 1, true) ~= nil, "the dealer's window says so", LC.MarketBlackNote(lp))
    for _ = 1, 200 do LC.MarketBought(lp, "black") end
    ok(LC.BlackPrice(lp) <= math.floor(lp.price * 1.5 * (LC.BlackPriceMul and LC.BlackPriceMul() or 1) + 1), "never past the cap, however much is bought")
    _setcvar("lc_market_demand_halflife", 1)
    for _ = 1, 12 do LC.MarketTick() end
    ok(LC.BlackPrice(lp) == base, "demand cools, and the price comes back down", LC.BlackPrice(lp))
    for _ = 1, 8 do LC.MarketBought(lp, "black") end
    local hot = LC.BlackPrice(lp)
    LC.MarketSold("lockpick", 10)
    ok(LC.BlackPrice(lp) < hot, "selling them to the dealer brings it down too")
    _setcvar("lc_market_demand_halflife", 30)
    -- the quartermaster pays more for what's in demand, never what anyone could buy it for
    MS.demand = {}
    local gp = LCS.BlackById.gun_pistol
    local qmBase = math.floor(LCS.Items.gun_pistol.sell * 1.5 + 0.5)
    for _ = 1, 10 do LC.MarketBought(gp, "black") end
    local qmNow = LC.MarketBuyback("gun_pistol", qmBase)
    ok(qmNow > qmBase and qmNow < LC.QuartermasterPrice(gp) and qmNow < LC.BlackPrice(gp),
        "the quartermaster's buy-back follows demand, and stays under every price to buy one", qmBase .. " -> " .. qmNow)
    MS.demand = {}
    -- consequences
    LC.MarketSet(boss, "bread", "restrict", "1")
    local nR = LC.MarketRestrictedCount()
    local base = LC.RebelTarget and (function() local b = LC.MarketRebelBonus LC.MarketRebelBonus = function() return 0 end local v = LC.RebelTarget() LC.MarketRebelBonus = b return v end)()
    ok(nR >= 2 and LC.MarketRebelBonus() == math.min(6, nR), "each restriction drives another citizen to the Resistance: one more fighter each (at most lc_market_rebels_max)", nR .. " " .. LC.MarketRebelBonus())
    ok(math.abs(LC.MarketOpsMul() - math.max(0.5, 1 - nR * 0.1)) < 0.001, "and the Resistance's operations come sooner (10% a restriction, at most half the wait)", LC.MarketOpsMul())
    ok(not LC.RebelTarget or LC.RebelTarget() >= base, "rebel territory's own target counts them (as room allows)")
    local lvl = LC.SocioAuto and LC.SocioAuto()
    cit.lcMarketSympathy = nil -- (an earlier refusal in this unit used the half hour)
    local s0 = LC.Trait(cit, "sympathy")
    LC.Buy(cit, "bread")
    LC.Buy(cit, "bread")
    ok(LC.Trait(cit, "sympathy") == s0, "a citizen turned away doesn't earn sympathy any more (the owner, 9 November: it's the way into the Resistance)")
    ok(lvl == nil or LC.SocioAuto() == lvl, "sociostability itself isn't touched by restrictions (the owner, 7 November)")
    local mood = LC.MarketMood()
    ok(type(mood) == "string" and string.find(mood, "Resistance", 1, true) ~= nil and not string.find(mood, "%d"), "the Administrator hears it in plain words, not numbers", mood)
    -- announced
    cit.chat = {}
    LC.MarketFlushAnnounce()
    local heard = false
    for _, m in ipairs(cit.chat or {}) do if string.find(m, "By order of the City Administrator", 1, true) then heard = true end end
    ok(heard, "the city is told")
    -- persistence
    LC.MarketSet(boss, "coffee", "price", "3")
    LC.MarketSet(boss, "milk", "supply", "scarce")
    LC.MarketSave()
    ok(file.Exists(LC.MarketFile(), "DATA"), "saved per map", LC.MarketFile())
    LC.MarketReload()
    ok(LC.MarketRestricted(bread) and LC.MarketCommissaryMul(coffee) == 3 and LC.MarketStock("milk") == 2,
        "after a restart: restrictions, prices and supply are as she left them")
    -- off
    _setcvar("lc_market", 0)
    ok(LC.MarketCommissaryMul(coffee) == 1 and LC.MarketCommissaryBlock(cit, bread) == nil and #LC.MarketBlackList() == #LCS.Black,
        "lc_market 0: all of it off, prices as fixed")
    _setcvar("lc_market", 1)
    -- tidy up for whatever runs next
    LC.MarketAccess = realAccess
    MS.rules, MS.stock, MS.restockAt, MS.demand = {}, {}, {}, {}
    LC.MarketSave()
    LC.MarketFlushAnnounce()
    _setcvar("lc_market_demand", 0)
    _setcvar("lc_market_scarce_stock", 5)
    for _, p in ipairs({ boss, cit, cop }) do p:SetPos(Vector(-150000, 150000, 0)) end
end
MarketTests()

function CareerTests()
    local function FieldPost(p, spec, tid, violent)
        spec.id = 81000 + math.random(1, 999999)
        spec.tmpl = spec.tmpl or { id = tid or "fieldtest" }
        spec.violent = violent
        spec.faction = LC.QuestFaction(p)
        spec.expiresPost = CurTime() + 999
        spec.data = spec.data or {}
        LC.Postings[spec.faction] = LC.Postings[spec.faction] or {}
        table.insert(LC.Postings[spec.faction], spec)
        p.lcqNext = 0
        LC.AcceptPosting(p, spec.id)
        return LC.QuestOf[p]
    end
    local function FieldTemplate(id)
        for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end
    end
    local function NetCount(name)
        local n = 0
        for _, m in ipairs(net.sent) do if m.name == name then n = n + 1 end end
        return n
    end
    section("My career: rank, XP and the way to the Overwatch; who hid the contraband")
    local mc = newPlayer("CareerMetro", "cp", nil, 200)
    local info = LC.CareerInfo(mc)
    ok(info.rank == 2 and info.ranks[3].name == "Division Leader" and info.ranks[4].overwatch, "a metrocop sees every rank, and which need the conditioning")
    ok(string.find(info.steps[1], "400 more XP", 1, true) and string.find(info.steps[1], "Division Leader", 1, true), "and how much more XP to the next one", info.steps[1])
    local joined = table.concat(info.steps, " ")
    ok(string.find(joined, "Overwatch Candidate", 1, true) and string.find(joined, "fail", 1, true), "the way to the Overwatch, and that failing doesn't lock you out")
    LC.SendCareer(mc)
    ok(_lastnet("lc_career") ~= nil, "it's sent to their screen (C > My career)")
    -- a Division Leader: where the story stands
    local dl = newPlayer("CareerDvL", "cp", nil, 1300) -- (enough for the first Overwatch rank: the story is only offered then)
    local s = LC.Story(dl)
    s.flags.story_gate = { need = 3, base = tonumber(dl:GetPData("lcq_done", 0)) or 0 }
    joined = table.concat(LC.CareerInfo(dl).steps, " ")
    ok(string.find(joined, "Do 3 more jobs", 1, true), "waiting on a few more jobs: it says how many", joined)
    s.flags.story_gate = { need = 0, base = 0 }
    local cs = LC.ChainState(dl, "candidate")
    cs.part, cs.readyAt = "evaluation", os.time() + 600
    joined = table.concat(LC.CareerInfo(dl).steps, " ")
    ok(string.find(joined, "comes back to your board", 1, true), "a failed part: when it comes back", joined)
    -- turned it down: a reassessment, an hour later
    cs.part, cs.readyAt, cs.done = nil, nil, "human"
    hook.Run("LivingCityStoryEnded", dl, "candidate", "human")
    local can, wait = LC.CanReassess(dl)
    ok(not can and wait and wait > 3000, "turned the conditioning down: a reassessment in an hour")
    ok(not LC.CareerReassess(dl) and cs.done == "human", "not before")
    cs.endedAt = os.time() - 3700
    local i2 = LC.CareerInfo(dl)
    ok(i2.canReassess == true, "an hour on, the page offers it")
    _netcall("lc_career_ask", dl, "reassess")
    ok(cs.done == nil and cs.part == "evaluation", "asked: the Overwatch Candidate story is back from its first part")
    local back = false
    for _, p in ipairs(LC.StoryPostings(dl)) do if p.chain == "candidate" then back = true end end
    ok(back, "and on their board (F3)")
    -- conditioned: the next Overwatch rank
    local ow = newPlayer("CareerOW", "cp", nil, 1500)
    LC.Condition(ow)
    local i3 = LC.CareerInfo(ow)
    ok(i3.conditioned and string.find(i3.steps[1], "Combine Soldier", 1, true), "conditioned: the XP to the next Overwatch rank", i3.steps[1])
    do -- the conditioning (the owner, 11 November): only offered with the experience for the first Overwatch rank
        local short = newPlayer("CareerShort", "cp", nil, 700)
        local chain = LC.Chains.candidate
        ok(LC.ConditioningXPShort(short) == 500 and not chain.unlock(short), "a Division Leader 500 XP short of Combine Prison Guard: the story isn't offered yet")
        ok(string.find(table.concat(LC.CareerInfo(short).steps, " "), "500 more XP", 1, true), "and My career says how much more it takes")
        local cand = newPlayer("CareerCandidate", "cp", nil, 1300)
        ok(LCF.RankOf(cand).name == "Division Leader" and chain.unlock(cand), "with enough, still a Division Leader: it is offered")
        ok(LC.ConditionPromote(cand) and LC.Conditioned(cand) and LCF.RankOf(cand).name == "Combine Prison Guard"
            and LCF.IsOverwatch(cand), "accepting makes them a Combine Prison Guard at once", LCF.RankOf(cand).name)
        LC.ConditionPromote(short)
        ok((tonumber(short:GetPData("lcf_xp_cp", 0)) or 0) == 700, "no experience is ever given by it")
        ok(LC.ConditioningScene(cand) == true and cand.lcConditioning == true and #LC.ConditioningSounds >= 4, "the scene: black screen, held still, the machines")
        cand:SetPos(Vector(-150000, 150000, 0)) short:SetPos(Vector(-150000, 150000, 0))
    end
    for _, p in ipairs({ mc, dl, ow }) do p:SetPos(Vector(-150000, 150000, 0)) end

    -- the contraband sweep: track down who hid it
    _setcvar("lc_quest_allies", 0)
    if not LC.PrisonAvailable() then LC.AddPoint(Vector(-196000, -190000, 0), 0, "cell", 0) end
    local C = Vector(-196000, -186000, 0)
    local sweeper = newPlayer("Sweeper", "cp", nil, 300)
    sweeper:SetPos(C)
    local suspect = LC.SpawnCitizen and LC.SpawnCitizen(C + Vector(600, 0, 4))
    local witness = LC.SpawnCitizen and LC.SpawnCitizen(C + Vector(-300, 0, 4))
    for _, n in ipairs({ suspect, witness }) do if IsValid(n) then LC.NPCs[n].state = "idle" end end
    local t = FieldTemplate("cp_contraband")
    local spec = t.build(sweeper)
    local q = spec and FieldPost(sweeper, spec, "cp_contraband", false)
    if q then
        local st = q.stages[1]
        for e in pairs(st.items or {}) do LC.QuestEvent("used_item", sweeper, e) end
        ok(not q.done and #q.stages > 1, "three stashes found: the job goes on, to whoever hid them", #q.stages)
        local ask = q.stages[q.stage]
        ok(ask.event == "used_npc" and string.find(ask.text, "Ask around", 1, true), "first, ask around", ask.text)
        local who = q.data.suspect
        local other
        for npc, nst in pairs(LC.NPCs) do if nst.role == "citizen" and IsValid(npc) and npc ~= who then other = npc break end end
        if other then LC.QuestEvent("used_npc", sweeper, other, LC.NPCs[other]) end
        ok(q.data.target == who and q.stages[q.stage].kind == "target", "a witness points them out: find them (marked)")
        if IsValid(who) then
            sweeper:SetPos(who:GetPos())
            _run(1)
            ok(q.stages[q.stage].kind == "choice", "found: what to do with them")
            LC.ResolveChoice(sweeper, q.id, 1)
            _run(0.5)
            ok(q.stages[q.stage].kind == "target" and q.stages[q.stage].action == "arrest", "detain them: an arrest, the usual way")
            hook.Run("LivingCityIncarcerated", who, 60, "contraband", sweeper)
            _run(0.5)
            ok(q.done, "brought in: the sweep is done")
        end
    else
        ok(false, "(the sweep didn't start)")
    end
    sweeper:SetPos(Vector(-150000, 150000, 0))
end
CareerTests()

function LabDamageTests()
    local function FieldPost(p, spec, tid, violent)
        spec.id = 81000 + math.random(1, 999999)
        spec.tmpl = spec.tmpl or { id = tid or "fieldtest" }
        spec.violent = violent
        spec.faction = LC.QuestFaction(p)
        spec.expiresPost = CurTime() + 999
        spec.data = spec.data or {}
        LC.Postings[spec.faction] = LC.Postings[spec.faction] or {}
        table.insert(LC.Postings[spec.faction], spec)
        p.lcqNext = 0
        LC.AcceptPosting(p, spec.id)
        return LC.QuestOf[p]
    end
    local function FieldTemplate(id)
        for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end
    end
    local function NetCount(name)
        local n = 0
        for _, m in ipairs(net.sent) do if m.name == name then n = n + 1 end end
        return n
    end
    section("A Resistance lab shot up, wrecked, and repaired")
    _setcvar("lc_quest_allies", 0)
    _setcvar("lc_lab_health", 250)
    local savedGM = GAMEMODE
    GAMEMODE = { IsLivingCity = true }
    local LB = Vector(-198000, -186000, 0)
    local bench = ents.Create("lc_workbench") bench:SetPos(LB)
    bench:SetAngles(Angle(0, 0, 0))
    local sci = LC.SetupLab(bench)
    local cop = newPlayer("LabShooter", "cp", nil, 300)
    local reb = newPlayer("LabFixer", "resistance", nil, 900)
    _run(3) -- (settled at their spawn first: a rebel starts in rebel territory)
    hook.Run("EntityTakeDamage", bench, _dmg(reb, 200))
    ok(bench:GetNW2Int("lc_lab_dmg", 0) == 0, "the Resistance's own bullets don't count")
    hook.Run("EntityTakeDamage", bench, _dmg(cop, 70))
    ok(bench:GetNW2Int("lc_lab_dmg", 0) == 1 and not LC.LabBroken(bench), "shot: a part blows and it smokes, but it still works")
    ok(LC.ScientistNear(sci:GetPos()) == sci, "(the scientist still works at it)")
    hook.Run("EntityTakeDamage", bench, _dmg(cop, 200))
    ok(LC.LabBroken(bench) and LC.LabBroken(sci) and bench:GetNW2Int("lc_lab_dmg", 0) == 3, "shot to pieces: wrecked")
    ok(LC.ScientistNear(sci:GetPos()) == nil, "nothing can be made, decoded or done there")
    reb:SetPos(sci:GetPos() + Vector(40, 0, 0))
    local ok1 = LC.LabMake(reb, "ammo_smg", "pay")
    ok(not ok1, "not even for credits")
    local labs = NetCount("lc_lab")
    reb.lcLabUse = 0
    LC.UseScientist(reb, sci)
    ok(NetCount("lc_lab") == labs, "the scientist's shop doesn't open: he says why instead")
    local job
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_fixlab" and not p.dead then job = p end end
    ok(job ~= nil, "the Resistance get a job to fix it (F3)")
    -- the scientist taken: a separate thing, and needs no repair
    cop.lcLabUse = 0
    cop:SetPos(sci:GetPos() + Vector(40, 0, 0))
    LC.UseScientist(cop, sci)
    ok(LC.LabShut(sci) and LC.LabBroken(bench), "a unit can still take the scientist away")
    sci:SetNW2Float("lc_away_until", 0)
    cop:SetPos(Vector(-150000, 150000, 0))
    -- the job
    if job then
        reb.lcqNext = 0
        LC.AcceptPosting(reb, job.id)
        local q = LC.QuestOf[reb]
        ok(q ~= nil and q.tmpl.id == "res_fixlab", "a rebel takes it")
        if q then
            local st = q.stages[q.stage]
            if st.kind == "collect" then
                for e in pairs(st.items or {}) do LC.QuestEvent("used_item", reb, e) end
            end
            reb:SetPos(LB)
            _run(1)
            -- (the parts' searches, if the map had a yard, a shop or a box: done by hand, here at once)
            for _ = 1, 4 do
                local cs = q.stages[q.stage]
                if cs and cs.search and not q.done then
                    for e in pairs(cs.search) do if not q.done and q.stages[q.stage] == cs then LC.QuestSearchDone(reb, q, cs, e) end end
                end
            end
            reb:SetPos(LB)
            _run(2)
            ok(q.stages[q.stage].event == "game_done", "parts found and brought: now rewire the bench (the wiring game, no standing about)", tostring(q.stages[q.stage].kind))
            ok(LC.LabBroken(bench), "(still wrecked until it's done)")
            if LC.JobGames and LC.JobGames[reb] then LC.JobGameEnd(reb, "test") end
            LC.QuestEvent("game_done", reb)
            _run(1)
            ok(q.done and not LC.LabBroken(bench) and bench:GetNW2Int("lc_lab_dmg", 0) == 0, "repaired: the smoke and sparks stop")
            ok(LC.ScientistNear(sci:GetPos()) == sci, "and the lab works again")
        end
    end
    reb:SetPos(Vector(-150000, 150000, 0))
    -- knocked about but not wrecked: he patches it up himself, given time
    hook.Run("EntityTakeDamage", bench, _dmg(cop, 70))
    ok(bench:GetNW2Int("lc_lab_dmg", 0) == 1, "(shot again)")
    bench.lcLabHitAt = CurTime() - 700
    _run(11)
    ok(bench:GetNW2Int("lc_lab_dmg", 0) == 0, "left alone a while, the scientist patches up a bench that's only damaged")
    -- who is paid for wrecking it: a unit, not a citizen (the owner, 7 November)
    do
        local paid = {}
        local realXP, realCr = LC.AddXP, LC.AddCredits
        LC.AddXP = function(p, n, why) paid[#paid + 1] = { p = p, what = "xp", n = n } end
        LC.AddCredits = function(p, n, why) paid[#paid + 1] = { p = p, what = "cr", n = n } end
        local civ = newPlayer("LabWrecker", "citizen", nil, 300)
        local function Paid(p) local n = 0 for _, e in ipairs(paid) do if e.p == p then n = n + 1 end end return n end
        local b2 = ents.Create("lc_workbench") b2:SetPos(LB + Vector(3000, 0, 0))
        civ.chat = {}
        LC.WreckLab(b2, civ)
        ok(LC.LabBroken(b2) and Paid(civ) == 0 and not has(civ.chat, "[Civil Protection]"), "a citizen who wrecks a lab: wrecked, but no XP, no credits, no Civil Protection line", table.concat(civ.chat, " | "))
        local b3 = ents.Create("lc_workbench") b3:SetPos(LB + Vector(3000, 400, 0))
        cop.chat = {}
        LC.WreckLab(b3, cop)
        ok(Paid(cop) == 2 and has(cop.chat, "[Civil Protection]"), "a unit who wrecks one is paid, as before", Paid(cop))
        LC.AddXP, LC.AddCredits = realXP, realCr
        b2:Remove() b3:Remove()
    end
    _setcvar("lc_lab_health", 0)
    hook.Run("EntityTakeDamage", bench, _dmg(cop, 999))
    ok(bench:GetNW2Int("lc_lab_dmg", 0) == 0, "lc_lab_health 0: it can't be damaged")
    _setcvar("lc_lab_health", 250)
    bench:Remove()
    if IsValid(sci) then sci:Remove() end
    GAMEMODE = savedGM
end
LabDamageTests()

-- The owner was once dropped into a reconnect loop with "SendData reliable data too big (744335)"
-- with about 100 NPCs on the map: big and frequent sends to players are made safe
-- (sh_livingcity_net.lua, docs/dev/network-audit.md).
function NetSafetyTests()
    local N = LC.Net
    section("Network: big sends go in pieces, at a pace, and wait while a game loads")
    local function Since(n0, name)
        local out = {}
        for i = n0 + 1, #net.sent do if not name or net.sent[i].name == name then out[#out + 1] = net.sent[i] end end
        return out
    end
    local function Blob(n, seed)
        local t, x = {}, seed or 7
        for i = 1, n do x = (x * 1103515245 + 12345) % 2147483648 t[i] = string.char(97 + x % 26) end
        return table.concat(t)
    end
    local function Pump(secs) for _ = 1, math.floor(secs * 10 + 0.5) do _advance(0.1) N.PumpAll() end end

    -- cutting up and putting back together
    local data = Blob(70001)
    local pieces = N.Split(data, N.PIECE)
    ok(#pieces == 3 and #pieces[1] == N.PIECE and table.concat(pieces) == data and #N.Split("", 10) == 1,
        "a big send is cut into pieces of 30 KB (and nothing is still one piece)")
    local store = {}
    ok(N.Assemble(store, "x#1", 1, 3, pieces[1]) == nil and N.Assemble(store, "x#1", 2, 3, pieces[2]) == nil
        and N.Assemble(store, "x#1", 2, 3, pieces[2]) == nil, "the pieces wait for the rest (one that comes twice counts once)")
    ok(N.Assemble(store, "x#1", 3, 3, pieces[3]) == data and next(store) == nil, "the last piece in gives back the whole send, and nothing is left over")
    ok(N.Assemble(store, "y#2", 1, 1, "abc") == "abc", "a send in one piece is just that piece")

    local p = newPlayer("NetWatcher", "citizen")
    N.players[p], N.busy[p] = nil, nil
    local savedWait = N.READY_WAIT
    N.READY_WAIT = 90

    -- small: at once, exactly as before
    local n0 = #net.sent
    LC.SendCompressed("lc_nettest", { hello = "world" }, { p })
    local got = Since(n0)
    ok(#got == 1 and got[1].name == "lc_nettest" and got[1].data[1] == #got[1].data[2] and string.find(got[1].data[2], "world", 1, true) ~= nil,
        "a small send goes at once, as one message (its length, then the data)")

    -- big: in pieces, put back together into the same message
    n0 = #net.sent
    local big = { blob = Blob(150000, 3) }
    LC.SendCompressed("lc_nettest", big, p)
    ok(#Since(n0) == 0, "a send over 60 KB doesn't go as one message (the game couldn't take it)")
    Pump(4)
    local parts = Since(n0, "lc_big")
    local cstore, back = {}, nil
    for _, m in ipairs(parts) do
        local d = m.data
        local w = N.Assemble(cstore, d[1] .. "#" .. d[2], d[3], d[4], d[6])
        if w then back = { msg = d[1], data = w } end
    end
    ok(#parts == 6 and back and back.msg == "lc_nettest" and (util.JSONToTable(back.data) or {}).blob == big.blob,
        "it goes in pieces of 30 KB that put back together into the same send", #parts)

    -- a pace the game can take: never more than about 128 KB at once
    N.players[p], N.busy[p] = nil, nil
    n0 = #net.sent
    for i = 1, 4 do LC.SendCompressed("lc_nettest", { blob = Blob(50000, i) }, p) end
    local first = 0
    for _, m in ipairs(Since(n0)) do first = first + #(m.data[2] or "") end
    ok(first <= N.BURST + N.ONE_MAX and first < 4 * 50000, "four big sends at once don't all go in the same moment", first)
    Pump(6)
    ok(#Since(n0, "lc_nettest") == 4 and N.busy[p] == nil, "but they all get there, a few seconds at most", #Since(n0, "lc_nettest"))

    -- loading in: big sends wait for the game to be ready
    N.players[p], N.busy[p] = nil, nil
    N.Joining(p) -- (what joining does: hook PlayerInitialSpawn "LivingCityNet")
    n0 = #net.sent
    LC.SendCompressed("lc_nettest", { small = true }, p)
    LC.SendCompressed("lc_nettest", { blob = Blob(20000, 9) }, p)
    Pump(2)
    local sent = Since(n0, "lc_nettest")
    ok(#sent == 1 and string.find(sent[1].data[2], "small", 1, true) ~= nil, "while a game is loading in, small sends go and big ones wait")
    _netcall("lc_net_ready", p)
    Pump(0.1)
    ok(#Since(n0, "lc_nettest") == 2, "once the game says it's ready, the big one goes")
    N.Joining(p) -- (what joining does: hook PlayerInitialSpawn "LivingCityNet")
    n0 = #net.sent
    LC.SendCompressed("lc_nettest", { blob = Blob(20000, 10) }, p)
    _advance(N.READY_WAIT + 1) N.PumpAll()
    ok(#Since(n0, "lc_nettest") == 1, "and a game that never says so gets it after 90 seconds anyway")
    N.Joining(p)
    n0 = #net.sent
    for i = 1, 8 do LC.SendCompressed("lc_nettest", { blob = Blob(12000, 20 + i) }, p) end
    Pump(2)
    local early = #Since(n0, "lc_nettest")
    _netcall("lc_net_ready", p)
    Pump(2)
    ok(early >= 4 and early < 8 and #Since(n0, "lc_nettest") == 8, "a game loading in gets 64 KB in all; the rest waits for it, then follows", early)
    N.READY_WAIT = savedWait

    -- whole-state messages: at most once a second, the newest wins
    N.players[p], N.busy[p] = nil, nil
    n0 = #net.sent
    LC.SendCompressed("lc_public", { v = 1 }, { p })
    LC.SendCompressed("lc_public", { v = 2 }, { p })
    LC.SendCompressed("lc_public", { v = 3 }, { p })
    local pubs = Since(n0, "lc_public")
    ok(#pubs == 1 and (util.JSONToTable(pubs[1].data[2]) or {}).v == 1, "the territory map goes at once the first time")
    Pump(1.2)
    pubs = Since(n0, "lc_public")
    ok(#pubs == 2 and (util.JSONToTable(pubs[2].data[2]) or {}).v == 3, "changes in the same second are one more send, of the newest", #pubs)
    LC.SendCompressed("lc_public", { v = 3 }, { p })
    Pump(1.2)
    ok(#Since(n0, "lc_public") == 2, "the very same map again within the second isn't sent twice")

    -- everyone at once: one message, to the same list, as before
    local q = newPlayer("NetWatcher2", "citizen")
    N.players[p], N.busy[p] = nil, nil
    n0 = #net.sent
    local both = { p, q }
    LC.SendCompressed("lc_nettest", { all = 1 }, both)
    got = Since(n0)
    ok(#got == 1 and got[1].to == both, "a small send to several players is still one message to all of them")

    -- long global strings: the city's laws and the Administrator's broadcast past 511 characters
    local long = Blob(1300, 5)
    LC.SetGlobalLong("lc_nettest_g", long)
    ok(LC.GetGlobalLong("lc_nettest_g", "") == long and #(_globals.lc_nettest_g or "") <= 500, "a long global string is kept in parts of 500 and read back whole")
    LC.SetGlobalLong("lc_nettest_g", "short")
    ok(LC.GetGlobalLong("lc_nettest_g", "") == "short" and _globals.lc_nettest_g == "short", "a short one is one string, as before")
    local before = #(util.JSONToTable(LC.GetGlobalLong("lc_laws", "")) or {})
    local okL = LC.SetLaw(nil, nil, string.rep("Citizens will stand still when a unit passes. ", 4))
    local laws = util.JSONToTable(LC.GetGlobalLong("lc_laws", "")) or {}
    ok(okL and #laws == before + 1 and before > 0, "a law added past 511 characters of laws still reaches every law board", before .. " -> " .. #laws)
    LC.SetLaw(nil, #laws, "")

    -- the Endings menu's tuning, shared while a slider is dragged: at once, then at most twice a second
    _run(1)
    n0 = #net.sent
    LC.EndingTuneShare(nil)
    LC.EndingTuneShare(nil)
    LC.EndingTuneShare(nil)
    ok(#Since(n0, "lc_tune_all") == 1, "a burst of tuning changes is sent to everyone once at first")
    _run(0.6)
    ok(#Since(n0, "lc_tune_all") == 2, "and the latest once more, half a second later")

    N.players[p], N.busy[p], N.players[q], N.busy[q] = nil, nil, nil, nil
    p:Remove() q:Remove()
end
NetSafetyTests()

-- The people's names, jobs and what they're doing are kept off a joining player's first update:
-- the server keeps them in a table and answers each game's asks with the ones near it, only what
-- changed (sh_livingcity_npcstr.lua, docs/dev/network-audit.md).
function NPCStrTests()
    local S = LC.NPCStrNet
    section("NPC name tags: kept on the server, sent only near the player, only what changed")
    local O = Vector(9000, 9000, 0)
    local near = ents.Create("npc_citizen") near:SetPos(O + Vector(400, 0, 0))
    local far = ents.Create("npc_citizen") far:SetPos(O + Vector(6000, 0, 0))
    local p = newPlayer("TagWatcher", "citizen")
    p:SetPos(O)

    LC.SetNPCStr(near, "lc_pname", "Anya Petrova")
    LC.SetNPCStr(near, "lc_pjob", "Ration depot clerk")
    LC.SetNPCStr(near, "lc_doing", "sorting ration packs")
    LC.SetNPCStr(far, "lc_pname", "Viktor Lenz")
    ok(LC.NPCStr(near, "lc_pname", "x") == "Anya Petrova" and near:GetNW2String("lc_pname", "none") == "none",
        "a name is kept on the server, not as an engine networked string")
    ok(LC.NPCStr(far, "lc_doing", "idle") == "idle" and LC.NPCStr(nil, "lc_pname", "d") == "d",
        "never set: the default, as GetNW2String gave")
    LC.SetNPCStr(far, "lc_doing", "")
    ok(LC.NPCStr(far, "lc_doing", "x") == "", "set to nothing: nothing (not the default), as before")
    LC.SetNPCStr(near, "lc_role_test", "abc")
    ok(near:GetNW2String("lc_role_test", "") == "abc" and LC.NPCStr(near, "lc_role_test", "") == "abc",
        "any other key is still the engine's networked string")
    near:SetNW2String("lc_role_test", nil)

    -- what one answer to this player holds: { [idx] = { key = value } }, and the removed ones
    local function Ask(want)
        _advance(1)
        local n0 = #net.sent
        _netcall("lc_npcstr_ask", p, #(want or {}), unpack(want or {}))
        local m
        for i = n0 + 1, #net.sent do if net.sent[i].name == "lc_npcstr" and net.sent[i].to == p then m = net.sent[i] end end
        if not m then return nil end
        local d, i = m.data, 1
        local function R() local v = d[i] i = i + 1 return v end
        local got, gone = {}, {}
        for _ = 1, R() do gone[R()] = true end
        for _ = 1, R() do
            local idx, t = R(), {}
            for _ = 1, R() do local id = R() t[S.KEYS[id]] = R() end
            got[idx] = t
        end
        return got, gone
    end
    local got = Ask()
    local a = got and got[near:EntIndex()]
    ok(a and a.lc_pname == "Anya Petrova" and a.lc_pjob == "Ration depot clerk" and a.lc_doing == "sorting ration packs",
        "a game that asks is sent the name, job and doing of the people near it")
    ok(got and got[far:EntIndex()] == nil, "but not of someone across the map")
    got = Ask()
    ok(got == nil or got[near:EntIndex()] == nil, "asking again with nothing changed sends nothing about them")
    LC.SetNPCStr(near, "lc_doing", "on a break")
    got = Ask()
    a = got and got[near:EntIndex()]
    ok(a and a.lc_doing == "on a break" and a.lc_pname == nil and a.lc_pjob == nil, "a change sends only that value")
    got = Ask({ far:EntIndex() })
    local b = got and got[far:EntIndex()]
    ok(b and b.lc_pname == "Viktor Lenz" and b.lc_doing == "", "someone far away a label is reading is sent when the game asks after them")
    LC.SetNPCStr(far, "lc_doing", "walking home")
    got = Ask()
    ok(got == nil or got[far:EntIndex()] == nil, "once the game stops asking, far changes wait")
    far:SetPos(O + Vector(800, 0, 0))
    got = Ask()
    b = got and got[far:EntIndex()]
    ok(b and b.lc_doing == "walking home" and b.lc_pname == nil, "and come when they're near again, only what changed")

    -- removed: the game is told to forget that entity's tags
    local idx = near:EntIndex()
    near:Remove()
    ok(S.vals[near] == nil, "a removed NPC's tags are dropped on the server")
    local _, gone = Ask()
    ok(gone and gone[idx], "and the game is told to forget them")

    -- a game can't ask faster than about four times a second
    _advance(1)
    local n0 = #net.sent
    LC.SetNPCStr(far, "lc_doing", "a")
    _netcall("lc_npcstr_ask", p, 0)
    LC.SetNPCStr(far, "lc_doing", "b")
    _netcall("lc_npcstr_ask", p, 0)
    local c = 0
    for i = n0 + 1, #net.sent do if net.sent[i].name == "lc_npcstr" and net.sent[i].to == p then c = c + 1 end end
    ok(c == 1, "two asks in the same moment get one answer", c)

    -- what an answer can hold: many people at once stay well under one message's limit
    local crowd = {}
    for i = 1, 120 do
        local e = ents.Create("npc_citizen") e:SetPos(O + Vector(i * 5, 50, 0))
        LC.SetNPCStr(e, "lc_pname", "Citizen " .. i)
        LC.SetNPCStr(e, "lc_pjob", string.rep("j", 100))
        LC.SetNPCStr(e, "lc_doing", string.rep("d", 100))
        crowd[i] = e
    end
    local out1 = S.Changes(p)
    local bytes = 0
    for _, e in ipairs(out1) do for _, kv in ipairs(e[2]) do bytes = bytes + #kv[2] + 2 end end
    local out2 = S.Changes(p)
    ok(#out1 < 120 and bytes <= S.MAX_BYTES + 200 and #out1 + #out2 >= 120, "a crowd comes over two answers, each well under 64 KB", #out1 .. "+" .. #out2)
    LC.SetNPCStr(far, "lc_pname", "")
    local cl = S.Changes(p)
    ok(#cl == 1 and cl[1][1] == far:EntIndex() and cl[1][2][1][1] == 1 and cl[1][2][1][2] == "", "a cleared name is sent too (as nothing)")

    for _, e in ipairs(crowd) do e:Remove() end
    far:Remove()
    p:Remove()
    ok(S.sent[p] == nil and S.vals[far] == nil, "a player who leaves and the NPCs removed leave nothing behind")
end
NPCStrTests()

function KeyLayoutTests()

function TerritoryPathTests()
    section("Territory grows along the path nodes, eight feet tall (the owner, 7 November)")
    -- (the owner: "I have not seen rebel territory, nor infestation territory, expand a single time for
    -- weeks ... can we please make it so the territory expansion happens along path nodes?")
    for _, z in ipairs(LC.ZonesOfKind("rebel")) do LC.RemoveZone(z) end
    for _, z in ipairs(LC.ZonesOfKind("infest")) do LC.RemoveZone(z) end
    for n, st in pairs(LC.NPCs) do if IsValid(n) and (st.role == "zombie" or st.role == "rebel") then n:Remove() end end
    _setcvar("lc_territory_spread", 1)
    _setcvar("lc_zombies", 0)
    local wallsWas, groundWas = _walls, _groundFn
    _walls = {}
    -- an underground layout like rp_c18_ug's: a 600 x 600 room with two corridors 192 wide out of it,
    -- solid wall everywhere else; at the east end a ramp up, and a floor above the corridor
    local B = Vector(90000, 90000, 0)
    local function Room(x, y) return math.abs(x - B.x) <= 300 and math.abs(y - B.y) <= 300 end
    local function East(x, y) return x >= B.x + 300 and x <= B.x + 2300 and math.abs(y - B.y) <= 96 end
    local function North(x, y) return y >= B.y + 300 and y <= B.y + 1800 and math.abs(x - B.x) <= 96 end
    local function Ramp(x, y) return x > B.x + 2300 and x <= B.x + 2700 and math.abs(y - B.y) <= 96 end
    _groundFn = function(x, y)
        if x < 0 then return 0 end -- (open ground, far away: for the territory with no path nodes near it)
        if Room(x, y) or East(x, y) or North(x, y) then return 0 end
        if Ramp(x, y) then return (x - B.x - 2300) * 0.3 end
        return nil
    end
    local seed = LC.AddZone(nil, nil, "rebel", 0, { mins = B + Vector(-300, -300, -16), maxs = B + Vector(300, 300, 192) })
    -- the path nodes: one in the room, every 250 units down each corridor, up the ramp, and
    -- two links that climb: one straight up to the floor above, one far too steep for stairs
    local R0 = LC.AddNode(B, true)
    local E, N = {}, {}
    local prev = R0
    for i = 1, 8 do E[i] = LC.AddNode(B + Vector(300 + (i - 1) * 250, 0, 0), true) LC.ToggleLink(prev, E[i], true) prev = E[i] end
    prev = R0
    for i = 1, 6 do N[i] = LC.AddNode(B + Vector(0, 300 + (i - 1) * 250, 0), true) LC.ToggleLink(prev, N[i], true) prev = N[i] end
    local RP = LC.AddNode(B + Vector(2600, 0, 90), true) LC.ToggleLink(E[8], RP, true)
    local U = LC.AddNode(B + Vector(590, 0, 256), true) LC.ToggleLink(E[2], U, true)
    local U2 = LC.AddNode(B + Vector(900, 0, 256), true) LC.ToggleLink(U, U2, true)
    local S = LC.AddNode(B + Vector(1150, 60, 150), true) LC.ToggleLink(E[4], S, true)
    LC.SaveData()

    -- why it never grew: the old way looks for a round patch of floor at least ~280 units across
    -- past the edge, and a corridor is narrower than that; then waited a whole interval to try again
    local oldFails = 0
    for _ = 1, 20 do if not LC.TerritoryGrowthSpot(seed) then oldFails = oldFails + 1 end end
    ok(oldFails == 20, "the cause: in a room with corridors out of it, the old growth never found anywhere to go", oldFails .. " of 20 failed")

    -- the clock: due, but nobody holds it, so it tries again in a minute, not 40 minutes later
    local grewHeard = 0
    hook.Add("LivingCityTerritoryGrew", "TerritoryPathTests", function() grewHeard = grewHeard + 1 end)
    LC.TerritoryState[seed] = { nextGrow = 0, hits = 0, lastHit = -1e9 }
    _run(11)
    local st = LC.TerritoryState[seed]
    ok(LC.GrownCount("rebel") == 0 and grewHeard == 0, "with nobody holding it, it doesn't grow, and nothing is announced")
    ok(st.nextGrow - CurTime() <= 61 and st.lastWhy and string.find(st.lastWhy, "Resistance fighters", 1, true),
        "it tries again within a minute, and says why it didn't grow", tostring(st.lastWhy) .. " / " .. math.floor(st.nextGrow - CurTime()))
    local reb = LC.SpawnRebel(B + Vector(0, 0, 4), seed)
    st.nextGrow = 0
    _run(11)
    ok(LC.GrownCount("rebel") == 1 and grewHeard == 1, "held by a fighter, it grows on schedule, and that's announced once", LC.GrownCount("rebel") .. " / " .. grewHeard)
    ok(st.nextGrow - CurTime() > 25 * 60, "and the next growth is a whole lc_rebel_spread_minutes away", math.floor(st.nextGrow - CurTime()))
    local G = LC.TerritoryGround(seed)
    local function In(v) return LC.InRebelZone(B + v) end
    ok(G and G.cells and In(Vector(550, 0, 8)) and In(Vector(0, 550, 8)) and not In(Vector(800, 0, 8)),
        "the first growth takes the links out of the room's edge (both corridors), along the path nodes, no further")
    ok(G and G.where and G.where ~= "", "and where it grew is said", G and G.where)

    section("It follows the links outward, never up through a floor")
    _setcvar("lc_territory_max", 40)
    for _ = 1, 30 do if not LC.GrowTerritory(seed) then break end end
    local grownZones = 0
    for _, z in ipairs(LC.Zones) do if z.grown and z.seed == seed then grownZones = grownZones + 1 end end
    ok(grownZones == 1, "however far it grows, it's one zone (its cells), not one per link", grownZones)
    local allIn = true
    for _, n in ipairs(E) do if not LC.InRebelZone(n.pos + Vector(0, 0, 8)) then allIn = false end end
    for _, n in ipairs(N) do if not LC.InRebelZone(n.pos + Vector(0, 0, 8)) then allIn = false end end
    ok(allIn and LC.InRebelZone(RP.pos + Vector(0, 0, 8)), "every corridor node is taken, and up the ramp")
    ok(not LC.InRebelZone(U.pos + Vector(0, 0, 8)) and not LC.InRebelZone(U2.pos + Vector(0, 0, 8)) and not LC.InRebelZone(S.pos + Vector(0, 0, 8)),
        "never the link straight up to the floor above, nor one steeper than stairs")
    ok(In(Vector(925, 0, 90)) and not In(Vector(925, 0, 110)), "it's eight feet (96 units) tall, from the floor")
    ok(not In(Vector(700, 0, 260)), "the floor above the corridor isn't rebel ground")
    ok(not In(Vector(1300, 330, 10)) and not In(Vector(600, 600, 10)), "nor the solid ground either side of the corridors")
    ok(In(Vector(1300, 0, 10)) and LC.TerritorySeedAt(B + Vector(1300, 0, 10), "rebel") == seed,
        "the corridor is: everything that asks \"is this rebel ground\" sees it")
    ok(G.n >= 30 and #G.rects <= 14, "its cells are kept as a few rectangles", G.n .. " cells, " .. #G.rects .. " rectangles")
    local why = select(2, LC.GrowTerritory(seed))
    ok(why and string.find(why, "climb", 1, true), "with only the links that climb left, it says so", why)

    section("In the open it spreads wide, and fills the gaps")
    -- (the owner: "if there is a large open area we don't want the territory only expanding in a narrow corridor")
    local P = Vector(-60000, 60000, 0)
    local plaza = LC.AddZone(nil, nil, "rebel", 0, { mins = P + Vector(-100, -100, -16), maxs = P + Vector(100, 100, 192) })
    local grid = {}
    for i = 0, 4 do
        grid[i] = {}
        for j = 0, 4 do
            grid[i][j] = LC.AddNode(P + Vector(i * 400, j * 400, 0), true)
            if i > 0 then LC.ToggleLink(grid[i - 1][j], grid[i][j], true) end
            if j > 0 then LC.ToggleLink(grid[i][j - 1], grid[i][j], true) end
        end
    end
    LC.SaveData()
    local function Taken()
        local n = 0
        for i = 0, 4 do for j = 0, 4 do if LC.InRebelZone(grid[i][j].pos + Vector(0, 0, 8)) then n = n + 1 end end end
        return n
    end
    for _ = 1, 3 do LC.GrowTerritory(plaza) end
    ok(Taken() >= 7, "a few links at a time, so three growths reach well out across a square", Taken())
    local PG = LC.TerritoryGround(plaza)
    local cap = PG.n + 12
    _setcvar("lc_territory_cells", cap)
    for _ = 1, 10 do LC.GrowTerritory(plaza) end
    local capWhy = select(2, LC.GrowTerritory(plaza))
    ok(PG.n <= cap and capWhy and string.find(capWhy, "big", 1, true), "never more cells than lc_territory_cells", PG.n .. " of " .. cap .. ": " .. tostring(capWhy))
    _setcvar("lc_territory_cells", 600)
    for _ = 1, 30 do if not LC.GrowTerritory(plaza) then break end end
    local holes = 0
    for i = 0, 3 do for j = 0, 3 do if not LC.InRebelZone(P + Vector(200 + i * 400, 200 + j * 400, 8)) then holes = holes + 1 end end end
    ok(Taken() == 25 and holes == 0, "in the end the whole square, the gaps between the links filled in", Taken() .. " nodes, " .. holes .. " gaps")
    ok(#PG.rects * 10 <= PG.n, "and its cells merge into a handful of rectangles (one for every ten cells or fewer)", #PG.rects .. " for " .. PG.n)
    local t0 = os.clock()
    for k = 1, 20000 do LC.InRebelZone(P + Vector((k * 37) % 1700, (k * 53) % 1700, 8)) end
    ok(os.clock() - t0 < 2, "asking whether a spot is rebel ground is a lookup, not a search", string.format("%.3fs for 20000", os.clock() - t0))

    section("Grown ground comes back after a restart")
    local n0, s0 = G.n, G.steps
    LC.LoadData(false)
    for _, z in ipairs(LC.ZonesOfKind("rebel")) do
        if not z.grown and z.pos:Distance(B) < 50 then seed = z end
        if not z.grown and z.pos:Distance(P) < 50 then plaza = z end
    end
    G = LC.TerritoryGround(seed)
    ok(G and G.n == n0 and G.steps == s0 and In(Vector(1300, 0, 10)) and not In(Vector(700, 0, 260)),
        "all of it, cell for cell, attached to the zone you placed", G and (G.n .. " / " .. n0))
    ok(#(_files["livingcity/rp_test_territory.json"] or "") < 8000, "and the file it's kept in stays small", #(_files["livingcity/rp_test_territory.json"] or ""))

    section("Taken back the way it came: the furthest out first")
    local before = LC.TerritoryCellDistances(G, seed)
    local cop = newPlayer("PathRetaker", "cp")
    cop:SetPos(B + Vector(0, 200, 0))
    for _ = 1, 3 do
        local r = LC.SpawnRebel(B + Vector(60, 60, 4), seed)
        r:SetHealth(0)
        hook.Run("OnNPCKilled", r, cop)
    end
    _run(1)
    local minGone, maxLeft = 1e9, -1
    for k, d in pairs(before) do
        if G.cells[k] then maxLeft = math.max(maxLeft, d) else minGone = math.min(minGone, d) end
    end
    ok(G.n < n0 and minGone >= maxLeft - 0.01, "three kills take back the cells furthest from where it started", G.n .. " left; gone from " .. minGone .. ", left up to " .. maxLeft)
    ok(not LC.InRebelZone(RP.pos + Vector(0, 0, 8)) and In(Vector(550, 0, 8)), "the top of the ramp goes first, the room's doorway last")
    for _ = 1, 40 do if not LC.TerritoryGround(seed) then break end LC.RecedeTerritory(LC.TerritoryGround(seed), "test", cop) end
    ok(LC.TerritoryGround(seed) == nil and table.HasValue(LC.Zones, seed), "pushed all the way back, the zone you placed is still there")

    section("Staff can grow it now, from the admin tools")
    local sa, ad = newPlayer("PathSuper", "citizen"), newPlayer("PathAdmin", "citizen")
    sa.admin, sa.superadmin, ad.admin = true, true, true
    local okA, msgA = LC.AdminTool(ad, ad, "territory", "rebel")
    ok(not okA and msgA == "Superadmins only.", "an admin can't", msgA)
    local nBefore = LC.GrownCount("rebel")
    local okS, msgS = LC.AdminTool(sa, sa, "territory", "rebel")
    ok(okS and LC.GrownCount("rebel") == nBefore + 1 and string.find(msgS, "path nodes", 1, true), "a superadmin can: it grows one link, and says where", msgS)
    local status = LC.TerritoryStatus("rebel")
    ok(#status == 2 and string.find(status[1], "Rebel ground", 1, true), "the panel shows how each territory is doing", status[1])

    section("No path nodes near it: it grows the old way")
    local far = LC.AddZone(Vector(-90000, 90000, 0), 400, "rebel", 0)
    local round = LC.GrowTerritory(far)
    ok(round and not round.strip and round.r >= 200 and round.pos:Distance(far.pos) > far.r * 0.7,
        "a round patch out past its edge, on open floor, as before", round and round.r)

    hook.Remove("LivingCityTerritoryGrew", "TerritoryPathTests")
    if IsValid(reb) then reb:Remove() end
    for n, st2 in pairs(LC.NPCs) do if IsValid(n) and st2.role == "rebel" then n:Remove() end end
    LC.RemoveZone(far)
    LC.RemoveZone(plaza)
    LC.RemoveZone(seed)
    for i = 0, 4 do for j = 0, 4 do LC.RemoveNode(grid[i][j]) end end
    for _, n in ipairs({ R0, RP, U, U2, S }) do LC.RemoveNode(n) end
    for _, n in ipairs(E) do LC.RemoveNode(n) end
    for _, n in ipairs(N) do LC.RemoveNode(n) end
    cop:SetPos(Vector(-30000, 30000, 0))
    _setcvar("lc_territory_max", 6)
    _setcvar("lc_territory_spread", 0)
    _walls, _groundFn = wallsWas, groundWas
end
TerritoryPathTests()

-- Grown ground (cells along the path nodes) used to be asked as the circle round where it last grew
-- to (pos and r, a circle as big as it): the camp's dressing, the rebels' things, patrols, the dry
-- ground check when picking a spot, a fighter straying from home, and ground being cleared all
-- missed a corridor it took and counted the floor beside its front. Each now asks the cells.
function GrownGroundTests()
    section("Grown ground is its cells everywhere, not a circle round where it last grew to")
    for _, z in ipairs(LC.ZonesOfKind("rebel")) do LC.RemoveZone(z) end
    for _, z in ipairs(LC.ZonesOfKind("infest")) do LC.RemoveZone(z) end
    for n, st in pairs(LC.NPCs) do if IsValid(n) and (st.role == "zombie" or st.role == "rebel") then n:Remove() end end
    local wallsWas, groundWas = _walls, _groundFn
    _walls = {}
    local C = LCZ.CELL
    -- a room (placed), a corridor east out of it (floor 0, 20 cells by 2), and up at its far end a
    -- leg north on a floor 200 units higher (12 cells by 2): an L, nothing like a circle
    local B = Vector(547 * C, -547 * C, 0)
    local function Corr(x, y) return x >= 550 * C and x < 570 * C and y >= -548 * C and y < -546 * C end
    local function Leg(x, y) return x >= 568 * C and x < 570 * C and y >= -546 * C and y < -534 * C end
    _groundFn = function(x, y)
        if math.abs(x - B.x) <= 300 and math.abs(y - B.y) <= 300 then return 0 end
        if Leg(x, y) then return 200 end
        if Corr(x, y) then return 0 end
        return nil
    end
    local seed = LC.AddZone(nil, nil, "rebel", 0, { mins = B + Vector(-300, -300, -16), maxs = B + Vector(300, 300, 192) })
    local front = Vector(569 * C, -535 * C, 200) -- (where it last grew to: the far end of the leg)
    local G = LCZ.UnpackGround({ 550, -548, 569, -547, 0, -16, 96, 568, -546, 569, -535, 2, 184, 296 },
        { kind = "rebel", grown = true, seed = seed, group = 0, h = 96, steps = 3, pos = front, born = CurTime() })
    G.r = math.max(200, math.sqrt(G.n * C * C / math.pi))
    LC.Zones[#LC.Zones + 1] = G
    local start = Vector(551 * C, -547 * C, 8)          -- the corridor's near end, far from the front
    local beside = Vector(570 * C + 236, -535 * C, 208)  -- off the leg's end, beside the front
    ok(G.n == 64 and LC.InRebelZone(start) and not LC.InRebelZone(beside), "the test ground: an L of 64 cells, its corridor rebel ground, beside its front not", G.n)
    ok(start:Distance(front) > G.r * 3 and beside:Distance(front) < G.r * 0.9,
        "and the circle round its front would have it the other way round", math.floor(G.r))
    ok(LCZ.Within(G, start, 0.9) and not LCZ.Within(G, beside, 0.9) and not LCZ.Within(G, beside, 1),
        "close to it (a fighter home, a crate's spot): the corridor is, the floor beside the front isn't")
    ok(LCZ.Near(G, beside, 400) and not LCZ.Near(G, beside, 100) and math.abs(LCZ.EdgeDist(G, beside) - 236) < 1 and LCZ.EdgeDist(G, start) == 0,
        "near it, and how far out: measured from its nearest cell", LCZ.EdgeDist(G, beside))
    ok(LCZ.FloorAt(G, start) == 0 and LCZ.FloorAt(G, Vector(569 * C - 60, -540 * C, 210)) == 200 and LCZ.Contains(G, LCZ.Heart(G), 0),
        "its floor is each cell's own, and the middle to head for is on it")
    -- a zone you placed answers exactly as before
    local circ = LC.AddZone(B + Vector(-5000, 0, 0), 400, "nogo", 0)
    local same = true
    for i = 1, 200 do
        local p = circ.pos + Vector(math.cos(i) * (i * 4), math.sin(i) * (i * 4), (i % 7) * 20)
        if LCZ.Within(circ, p, 0.9) ~= (p:DistToSqr(circ.pos) < 360 * 360) or LCZ.Within(circ, p, 1.3) ~= (p:DistToSqr(circ.pos) < 520 * 520)
            or LCZ.Near(circ, p, 250) ~= (p:DistToSqr(circ.pos) < 650 * 650) then same = false end
    end
    ok(same and LCZ.Heart(circ) == circ.pos and LCZ.FloorAt(circ, circ.pos + Vector(100, 0, 50)) == circ.pos.z,
        "a zone you placed: the circle round its middle, exactly as before")
    LC.RemoveZone(circ)

    section("Picking a spot on grown ground: each cell's own floor is dry ground")
    local onCorr, onLeg, outside = 0, 0, 0
    for _ = 1, 40 do
        local p = LC.SpotInZone(G)
        if p then
            if not LCZ.Contains(G, p, 0) then outside = outside + 1 end
            if math.abs(p.z) < 1 then onCorr = onCorr + 1 elseif math.abs(p.z - 200) < 1 then onLeg = onLeg + 1 end
        end
    end
    ok(onCorr >= 8 and onLeg >= 4 and outside == 0,
        "spots on the lower corridor too (they were all taken for a ditch below the front's floor), never off the ground", onCorr .. " corridor, " .. onLeg .. " leg")

    section("Grown ground is dressed, lived in and cleared by its cells")
    local spots = LC.ZoneFloorSpots(G, 6)
    local far, offGround = 0, 0
    for _, s in ipairs(spots) do
        if not LCZ.Contains(G, s, 0) then offGround = offGround + 1 end
        if s:Distance(front) > G.r then far = far + 1 end
    end
    ok(#spots >= 6 and far >= 1 and offGround == 0, "spots to dress it reach along the corridor, and all on it", #spots .. " spots, " .. far .. " far")
    local big = LC.AddZone(front, G.r * 2, "rebel", 0)
    local dressWas = GetConVar("lc_dressing"):GetBool()
    _setcvar("lc_dressing", 1)
    LC.Dressed[G] = nil
    LC.DressingTick()
    ok(LC.Dressed[G] and LC.Dressed[G].want >= 3, "grown ground gets a whole camp's dressing, not a piece for being near a bigger zone's middle",
        LC.Dressed[G] and LC.Dressed[G].want)
    _setcvar("lc_dressing", dressWas and 1 or 0)
    LC.RemoveZone(big)
    local bench = ents.Create("lc_workbench") bench:SetPos(start + Vector(0, 0, -8)) bench:Spawn()
    local found = false
    for _, t in ipairs(LC.RebelZoneThings(G)) do if t.ent == bench then found = true end end
    ok(found, "a workbench down the corridor is one of its things, for the fighters to use")
    bench:Remove()
    local q = LC.QuietRebels(start, 150, 600)
    ok(LC.RebelQuietZone(G) and not LC.RebelQuietAt(G.pos, G.r), "a team clearing the corridor keeps new fighters off it (the circle round its front missed it)")
    q.untilT = 0
    ok(not LC.RebelQuietZone(G), "and once they're done, it doesn't")

    for i = #LC.Zones, 1, -1 do if LC.Zones[i] == G then table.remove(LC.Zones, i) end end
    LC.Dressed[G] = nil
    LC.RemoveZone(seed)
    _walls, _groundFn = wallsWas, groundWas
end
GrownGroundTests()
function GuardOrdersTests()
    section("The Administrator's guards: how close they follow, what they do when there's trouble, and stepping aside for their own side")
    -- (the owner, 8 November)
    local S = Vector(130000, -130000, 0) -- (out of everyone's way)
    for _, other in ipairs(player.GetAll()) do
        if other:GetPos():DistToSqr(S) < 5000 * 5000 then other:SetPos(Vector(-150000, 150000, 0)) end
    end
    for n in pairs(LC.NPCs) do
        if IsValid(n) and n:GetPos():DistToSqr(S) < 6000 * 6000 then n:SetPos(Vector(-400000, 400000, 0)) end
    end
    local notes = {}
    local nw = LC.Notice
    LC.Notice = function(p, kind, title, text, secs)
        notes[#notes + 1] = { p = p, t = tostring(title) .. ": " .. tostring(text) }
        return nw(p, kind, title, text, secs)
    end
    local function Told(p, needle)
        for i = #notes, 1, -1 do if notes[i].p == p and string.find(notes[i].t, needle, 1, true) then return true end end
        return false
    end
    local adm = newPlayer("GOAdmin", "admin")
    local cit = newPlayer("GOCitizen", "citizen")
    local unit = newPlayer("GOUnit", "cp", nil, 200)
    adm:SetPos(S)
    adm.lcGuardNext = CurTime() + 99999 -- (no new guards of her own: these are ours)
    local away = Vector(-160000, 160000, 0)
    local function Guard(pos)
        local npc, st = LC.ManpowerFree(LC.SpawnSoldier, pos)
        st.unmanaged, st.questLock, st.adminGuard = true, true, adm
        st.state = "adminguard"
        LC.AdminGuards[npc] = adm
        return npc, st
    end
    local g1, s1 = Guard(S + Vector(-70, 50, 4))
    local g2, s2 = Guard(S + Vector(-70, -50, 4))
    local function Reset()
        for _, g in ipairs({ g1, g2 }) do g.goal, g.enemy, g.sched = nil, nil, SCHED_IDLE_STAND end
        -- each at his own place, in the order the guards' tick takes them
        local i = 0
        for npc, who in pairs(LC.AdminGuards) do
            if who == adm and IsValid(npc) then i = i + 1 npc:SetPos(LC.AdminGuardSpot(adm, i, 2) + Vector(0, 0, 4)) end
        end
        s1.adminTarget, s2.adminTarget = nil, nil
    end
    local function Tick() LC.AdminGuardTick(CurTime()) end
    local function Flat(v) return Vector(v.x, v.y, 0) end

    -- only she gives them orders
    ok(not LC.AdminGuardOrder(cit, "far") and not LC.AdminGuardOrder(unit, "between"), "only the Administrator gives her guards orders")
    ok(not LC.QuickMore(cit, "guards", "holdfire") and (LC.AdminGuardPref(cit).mode == nil), "(not from anyone's F2 either)")
    ok(not LC.AdminGuardOrder(adm, "dance"), "(and only the orders there are)")
    local qi = LC.QuickInfo(adm).adm or {}
    ok(qi.dist == "medium" and qi.mode == "always", "until she picks: Medium, and as they always have (F2 marks them)", tostring(qi.dist) .. " " .. tostring(qi.mode))
    local spot = LC.AdminGuardSpot(adm, 1, 2)
    ok(spot:DistToSqr(S - adm:GetForward() * 70 - adm:GetRight() * 50) < 1, "and they follow exactly where they always have", tostring(spot))

    -- follow distance
    ok(LC.QuickMore(adm, "guards", "far") and LC.AdminGuardPref(adm).dist == "far" and Told(adm, "Far"), "Follow distance: Far (from F2, and she's told)")
    ok((LC.QuickInfo(adm).adm or {}).dist == "far", "(F2 shows Far now)")
    Reset()
    g1:SetPos(S + Vector(-200, 60, 4))
    Tick()
    ok(g1.goal == nil, "Far: a guard 200 units back is where he should be, and stays", tostring(g1.goal))
    g1:SetPos(S + Vector(500, 0, 4))
    Tick()
    local dFar = g1.goal and Flat(g1.goal):Distance(S) or 0
    ok(dFar > 240 and dFar < 300, "Far: one too far off goes to his place, well back from her", tostring(dFar))
    ok(LC.AdminGuardOrder(adm, "close"), "Follow distance: Close")
    Reset()
    g1:SetPos(S + Vector(200, 0, 4))
    Tick()
    local dClose = g1.goal and Flat(g1.goal):Distance(S) or 999
    ok(dClose < 60, "Close: right at her shoulder", tostring(dClose))
    local spots, apart = {}, true
    for i = 1, 4 do spots[i] = LC.AdminGuardSpot(adm, i, 4) end
    for i = 1, 4 do for j = i + 1, 4 do if spots[i]:Distance(spots[j]) < 40 then apart = false end end end
    ok(apart, "four guards stand in two rows, never on one spot")
    ok(LC.AdminGuardOrder(adm, "medium") and LC.AdminGuardSpot(adm, 1, 2):DistToSqr(spot) < 1, "Medium: as they always have")

    -- when there's trouble: stand between us
    local reb = newPlayer("GORebel", "resistance", nil, 900)
    reb:Give("weapon_smg1") reb:SelectWeapon("weapon_smg1")
    reb:SetPos(S + Vector(0, 600, 0))
    local reb2 = newPlayer("GORebel2", "resistance", nil, 900)
    reb2:Give("weapon_smg1") reb2:SelectWeapon("weapon_smg1")
    reb2:SetPos(away)
    ok(select(1, LC.AdminGuardThreat(adm, reb, g1)) and not LC.AdminGuardThreat(adm, unit, g1) and not LC.AdminGuardThreat(adm, cit, g1),
        "a threat: a Resistance fighter with a gun out (never a unit, nor a citizen going about their business)")
    ok(LC.AdminGuardOrder(adm, "between") and Told(adm, "Stand between us"), "When there's trouble: Stand between us")
    Reset()
    Tick()
    local function Between(g, th)
        if not g.goal then return false end
        local to, gv = Flat(th:GetPos()) - S, Flat(g.goal) - S
        return gv:Dot(to) > 0 and gv:Length() < to:Length() and gv:Length() <= 160
    end
    ok(Between(g1, reb) and Between(g2, reb), "both step out between her and the threat", tostring(g1.goal) .. " " .. tostring(g2.goal))
    ok(g1.goal and g2.goal and g1.goal:Distance(g2.goal) >= 30, "side by side, not on one spot")
    ok(g1.enemy == reb and g2.enemy == reb, "and they're on him")
    reb2:SetPos(S + Vector(600, 0, 0))
    Reset()
    Tick()
    ok(g1.enemy ~= g2.enemy and (g1.enemy == reb or g1.enemy == reb2) and (g2.enemy == reb or g2.enemy == reb2), "two threats: each guard covers a different one")
    ok(Between(g1, g1.enemy) and Between(g2, g2.enemy), "each between her and his own", tostring(g1.goal) .. " " .. tostring(g2.goal))
    -- someone pointing a gun at her: covered, but not shot at for it
    reb:SetPos(away) reb2:SetPos(away)
    local aimer = newPlayer("GOAimer", "citizen")
    aimer:Give("weapon_pistol") aimer:SelectWeapon("weapon_pistol")
    aimer:SetPos(S + Vector(0, -500, 0))
    aimer.aim = Vector(0, 0, 1)
    Reset()
    Tick()
    ok(not Between(g1, aimer) and not Between(g2, aimer), "a citizen with a pistol pointed at the sky isn't a threat")
    aimer.aim = ((S + Vector(0, 0, 40)) - aimer:EyePos()):GetNormalized()
    Reset()
    Tick()
    ok(Between(g1, aimer) and Between(g2, aimer), "one aiming at her is: they step in front of her")
    ok(g1.enemy == nil and g2.enemy == nil, "(but they don't open fire on someone only aiming)")
    aimer:SetPos(away)

    -- stay with me
    ok(LC.AdminGuardOrder(adm, "stay") and Told(adm, "Stay with me"), "When there's trouble: Stay with me")
    reb:SetPos(S + Vector(0, 600, 0))
    Reset()
    g1:SetPos(S + Vector(-70, 190, 4)) -- (a few steps after him)
    Tick()
    ok(g1.goal and Flat(g1.goal):Distance(S) < 100 and g1.enemy == reb, "one who steps off after a threat is called back to her side, still shooting", tostring(g1.goal))
    ok(g2.goal == nil and g2.enemy == reb, "one in his place stays there and shoots")
    s1.adminTarget, s2.adminTarget = reb, reb
    g1:SetPos(S + Vector(0, 350, 4))
    g1.goal = nil
    Tick()
    ok(g1.goal and Flat(g1.goal):Distance(S) < 100 and g1.enemy == reb, "even after someone who hurt her: they don't chase")
    -- as they always have, the same guard would go after them
    ok(LC.AdminGuardOrder(adm, "always"), "When there's trouble: as they always have")
    Reset()
    s1.adminTarget = reb
    g1:SetPos(S + Vector(0, 350, 4))
    Tick()
    ok(g1.goal == nil and g1.enemy == reb, "(as always: whoever hurt her, they go after)")
    Reset()
    g1:SetPos(S + Vector(-70, 120, 4))
    Tick()
    ok(g1.goal == nil, "(and a guard a few steps off is left be, as before)")
    reb:SetPos(away)
    -- as always, and by themselves: a zombie near her, they shoot without being told (the owner, 15 November)
    local zed = ents.Create("npc_zombie")
    zed:SetPos(S + Vector(400, 0, 0)) zed:Spawn()
    Reset()
    g1:SetPos(S + Vector(-70, 50, 4)) g2:SetPos(S + Vector(-70, -50, 4))
    Tick()
    ok(LC.IsMonster(zed) and g1.enemy == zed and g2.enemy == zed and g1.goal == nil, "a zombie by her: they shoot it by themselves, from where they are", tostring(g1.enemy))
    -- her order comes first
    s1.adminTarget = reb
    reb:SetPos(S + Vector(0, 500, 0))
    Tick()
    ok(g1.enemy == reb and (g2.enemy == zed or g2.enemy == reb), "whoever she orders killed comes first", tostring(g1.enemy == zed) .. " " .. tostring(g2.enemy == reb) .. " " .. tostring(LC.NPCs[g1] == s1) .. " " .. tostring(reb.hp or (reb.Health and reb:Health())))
    s1.adminTarget = nil
    reb:SetPos(away)
    -- and keeping up with her: fighting a few steps off they stay; far behind they break off and catch up
    Reset()
    g1:SetPos(S + Vector(-300, 0, 4))
    Tick()
    ok(g1.goal == nil and g1.enemy == zed, "fighting a little way off: they stay on it")
    Reset()
    g1:SetPos(S + Vector(-600, 0, 4))
    Tick()
    ok(g1.goal ~= nil and Flat(g1.goal):Distance(S) < 150, "too far behind her: they catch up", tostring(g1.goal))
    zed:Remove()
    Reset()

    -- hold fire unless fired on
    ok(LC.AdminGuardOrder(adm, "holdfire") and Told(adm, "Hold fire"), "When there's trouble: Hold fire unless fired on")
    reb:SetPos(S + Vector(0, 400, 0))
    local crab = ents.Create("npc_citizen")
    crab:SetPos(S + Vector(300, 300, 0))
    crab.hp = 50
    Reset()
    g1.enemy, g2.enemy = reb, crab
    Tick()
    ok(not IsValid(g1.enemy) and g1.rel[reb] == D_NU and not IsValid(g2.enemy) and g2.rel[crab] == D_NU, "they start nothing: whoever they turned on, they leave be")
    hook.Run("EntityTakeDamage", g2, _dmg(reb, 5))
    ok(s1.adminTarget == reb and s2.adminTarget == reb and g1.rel[reb] == D_HT, "fired on (one of them): they answer, all of them")
    Tick()
    ok(g1.enemy == reb and g2.enemy == reb, "and keep on him", tostring(g1.enemy))
    ok(LC.AdminGuardOrder(adm, "always") and g2.rel[crab] == D_HT, "a new order puts back how they felt about the rest")
    ok(LC.AdminGuardOrder(adm, "holdfire"), "(hold fire again)")
    adm.lcGuardHold = { pos = S, fwd = adm:GetForward(), right = adm:GetRight() }
    hook.t.PlayerDeath.LivingCityQuickMoreGuards(adm)
    ok(LC.AdminGuardPref(adm).mode == "holdfire" and adm.lcGuardHold == nil and LC.AdminGuardPrefs[adm:SteamID64()] ~= nil, "her orders are kept (by SteamID) through a death, for the session (Hold here isn't)")
    ok(LC.AdminGuardOrder(adm, "always"), "(back to as always)")
    crab:Remove()
    reb:SetPos(away)
    Reset()

    -- stepping aside: the Combine's own, only for their own side
    local W = S + Vector(2000, 0, 0)
    local function Walks(ply, npc, st)
        ply:SetPos(W)
        npc:SetPos(W + Vector(40, 0, 4))
        st.makeWayAt, st.makeWayBack = nil, nil
        ply.vel = Vector(150, 0, 0)
        local before = npc:GetPos()
        LC.MakeWayTick(CurTime() + 100)
        ply.vel = nil
        ply:SetPos(away)
        return npc:GetPos() ~= before
    end
    local cop, cst = LC.ManpowerFree(LC.SpawnCop, W + Vector(40, 0, 4))
    cst.state = "idle"
    local sol, sst = LC.ManpowerFree(LC.SpawnSoldier, W + Vector(40, 0, 4))
    sst.state = "idle"
    sol:SetPos(away)
    local civ = newPlayer("GOCiv", "citizen")
    local vort = newPlayer("GOVort", "vort")
    ok(Walks(unit, cop, cst), "a unit walks into a Metrocop: it steps aside")
    ok(not Walks(civ, cop, cst) and not Walks(reb, cop, cst) and not Walks(vort, cop, cst), "a citizen, a rebel, a vortigaunt: it doesn't")
    ok(LC.MakesWayFor(cop, cst, adm), "a Metrocop steps aside for the City Administrator too (the owner, 8 November)")
    cop:SetPos(away)
    ok(Walks(unit, sol, sst) and Walks(adm, sol, sst), "an Overwatch soldier steps aside for a unit, and for the Administrator")
    ok(not Walks(civ, sol, sst) and not Walks(reb, sol, sst), "not for a citizen or a rebel")
    sst.enemy = reb
    ok(not Walks(unit, sol, sst), "never in the middle of a fight")
    sst.enemy = nil
    sol.enemy = reb
    ok(not LC.MakesWayFor(sol, sst, unit), "(nor with an enemy in its sights)")
    sol.enemy = nil
    sol:SetPos(away)
    ok(Walks(adm, g1, s1) and s1.makeWayBack ~= nil, "her Elite steps aside when she walks into him")
    ok(not Walks(civ, g1, s1), "(but not for a citizen)")
    s1.adminTarget = reb
    ok(not LC.MakesWayFor(g1, s1, adm), "not while he's after someone")
    s1.adminTarget = nil
    s1.makeWayBack = CurTime() - 1
    g1:SetPos(S + Vector(-30, 90, 4))
    g1.goal = nil
    adm:SetPos(S)
    Tick()
    ok(g1.goal and Flat(g1.goal):Distance(S) < 100 and s1.makeWayBack == nil, "then back to his place beside her", tostring(g1.goal))
    local person = LC.Spawners.citizen and LC.Spawners.citizen(W + Vector(40, 0, 4))
    local pst = IsValid(person) and LC.NPCs[person]
    if pst then
        pst.state = "idle"
        ok(Walks(reb, person, pst), "the city's citizens still make way for anyone (as before)")
        person:Remove()
    end
    local busy = { state = "escort" }
    ok(not LC.MakesWayFor(cop, busy, unit), "(nor while escorting a prisoner)")

    cop:Remove() sol:Remove()
    for n, who in pairs(LC.AdminGuards) do if who == adm then if IsValid(n) then n:Remove() end LC.AdminGuards[n] = nil end end
    LC.AdminGuardPrefs[adm:SteamID64()] = nil
    for _, p in ipairs({ adm, cit, unit, reb, reb2, aimer, civ, vort }) do p:SetPos(away) end
    LC.SetFaction(adm, "citizen", nil, true)
    LC.Notice = nw
end
GuardOrdersTests()
    section("The keys: F1 quick menu, F2 your side's quick menu, F3 pockets, F4 jobs, career and factions in one window")
    -- (the owner, 7 November: "make F4 the hotkey for this, and then move inventory to F3 ... F2 can be the same BUT contextual")
    local kp = newPlayer("KeyLayout", "cp", nil, 200)
    local function Names()
        local t = {}
        for _, m in ipairs(net.sent) do t[#t + 1] = m.name end
        return table.concat(t, ",")
    end
    -- (the gamemode's own F1 and F2, loaded as "Load the gamemode" does: the file's stand-in gamemode has neither)
    local G = { BaseClass = { PhysgunPickup = function() return true end, PlayerDeath = function() end,
        CanTool = function() return true end, PlayerSpawnProp = function() return true end } }
    local GMWas, incWas, derWas = GM, include, DeriveGamemode
    GM, include, DeriveGamemode = G, function() end, function() end
    assert(loadstring(_GMSRC_SHARED, "gamemode/shared.lua"))()
    assert(loadstring(_GMSRC_INIT, "gamemode/init.lua"))()
    GM, include, DeriveGamemode = GMWas, incWas, derWas
    net.sent = {}
    G:ShowHelp(kp)
    ok(_lastnet("lcg_help") ~= nil, "F1 is still the quick menu (and the guide)")
    net.sent = {}
    G:ShowTeam(kp)
    hook.Run("ShowTeam", kp)
    local q2 = _lastnet("lcg_quick2")
    ok(q2 ~= nil and q2.to == kp and _lastnet("lci_inv") == nil, "F2 opens the second quick menu (your side, rank and job), not the pockets", Names())
    net.sent = {}
    hook.Run("ShowSpare1", kp)
    ok(_lastnet("lci_inv") ~= nil and _lastnet("lcq_board") == nil, "F3 opens the pockets, not the board", Names())
    net.sent = {}
    hook.Run("ShowSpare2", kp)
    ok(net.sent[1] and net.sent[1].name == "lc_hub" and _lastnet("lcq_board") and _lastnet("lcf_menu") and _lastnet("lc_career") and _lastnet("lci_inv") == nil,
        "F4 opens one window, then sends its tabs: the board (Jobs), the career and the factions", Names())
    net.sent = {}
    hook.Run("PlayerSay", kp, "!inv")
    hook.Run("PlayerSay", kp, "!jobs")
    hook.Run("PlayerSay", kp, "!faction")
    ok(_lastnet("lci_inv") and _lastnet("lcq_board") and _lastnet("lcf_menu"), "!inv, !jobs and !faction still open what they did", Names())
    -- the tips name the new keys: pockets are {gm_showspare1} (F3), the board {gm_showspare2} (F4)
    local wrong = {}
    for key, h in pairs(LC.HINTS or {}) do
        local texts = type(h.text) == "table" and h.text or { h.text }
        for _, t in pairs(texts) do
            if type(t) == "string" and (string.find(t, "pockets ({gm_showteam}", 1, true) or string.find(t, "board ({gm_showspare1}", 1, true)
                or string.find(t, "{gm_showspare1} board", 1, true) or string.find(t, "pockets, {gm_showteam}", 1, true)) then
                wrong[#wrong + 1] = key
            end
        end
    end
    ok(#wrong == 0, "every tip names F3 for the pockets and F4 for the board", table.concat(wrong, ", "))
    ok(string.find(LC.HintPlain(LC.HINTS.menus.text.default), "[F2] has what your side", 1, true) and string.find(LC.HintPlain(LC.HINTS.menus.text.default), "[F3] opens your pockets", 1, true),
        "the tip about the menus: F2 your side's, F3 pockets, F4 the rest", LC.HintPlain(LC.HINTS.menus.text.default))
    local ways = LC.WaysToGetBy and LC.WaysToGetBy(kp) or {}
    local opens = {}
    for _, w in ipairs(ways) do if w.open then opens[w.open] = true end end
    ok(not (opens.f2 or opens.f3 or opens.f4), "Ways to get by open the pockets or a tab of F4 by name, not by an old key")
end
KeyLayoutTests()

-- The owner, 7 November: "are NPC rebel raids, attacks, ops, etc even active? ... I have never actually
-- seen rebel NPCs doing anything." Raids and operations with real fighters, on a city whose NPC cap is
-- full (theirs is lc_npc_budget 10): the city's own NPCs moved or swapped, never more of them; findable,
-- honest, and bigger with the Commissary's restrictions (sv_livingcity_rebelevents.lua;
-- docs/dev/rebel-activity-audit.md).
function RebelEventTests()
    local FAR = Vector(-30000, 30000, 0)
    local savedWalls = _walls
    _walls = {}
    _setcvar("lc_auto_events", 0)
    _setcvar("lc_skirmishes", 0)
    for _, p in ipairs(player.GetAll()) do p:SetPos(FAR) end
    for n in pairs(LC.NPCs) do if IsValid(n) then n:Remove() end end
    _run(1)
    for _, z in ipairs(LC.ZonesOfKind("rebel")) do LC.RemoveZone(z) end
    local O = Vector(70000, 70000, 0)
    local rz = LC.AddZone(O, 500, "rebel", 0)
    local T = O + Vector(3000, 0, 0)
    local res = newPlayer("RaidRes", "resistance", nil, 200)
    local unit = newPlayer("RaidCP", "cp", nil, 200)
    res:SetPos(FAR + Vector(0, 300, 0))
    unit:SetPos(FAR + Vector(0, -300, 0))
    local marks = {}
    local realSend = LC.SendCompressed
    LC.SendCompressed = function(msg, tbl, to)
        if msg == "lc_cpmark" then for _, p in ipairs(to or {}) do marks[#marks + 1] = { p = p, t = tbl, at = CurTime() } end end
        return realSend(msg, tbl, to)
    end
    local radio = {}
    local realRadio = LC.RadioNotice
    LC.RadioNotice = function(band, text, ...) radio[#radio + 1] = band .. ": " .. tostring(text) if realRadio then return realRadio(band, text, ...) end end
    local function MarkFor(p, name, after)
        for _, m in ipairs(marks) do if m.p == p and m.t.name == name and m.at >= (after or 0) then return m end end
    end
    local function Said(band, needle)
        for _, l in ipairs(radio) do if string.sub(l, 1, #band) == band and string.find(l, needle, 1, true) then return true end end
        return false
    end
    local function Clear(sk)
        if not sk then return end
        if not sk.done then LC.EndSkirmish(sk, "test") end
        -- (an operation that got what it came for is done but still the city's skirmish, and
        -- EndSkirmish passes over a done one: let it go here, or no raid or sweep starts after)
        if LC.Skirmish == sk then LC.Skirmish = nil end
        for _, r in ipairs(sk.rebels) do if IsValid(r) then r:Remove() end end
        for _, u in ipairs(sk.units) do if IsValid(u) and LC.NPCs[u] and LC.NPCs[u].unmanaged then u:Remove() end end
        _run(1)
    end

    section("Rebel raids: real fighters on a city whose NPC cap is full, without adding to it")
    _setcvar("lc_npc_budget", 10)
    _setcvar("lc_rebels", 4)
    _run(60)
    local before = LC.CityNPCCount()
    ok(before >= 10 and LC.RebelsIn(rz) <= 2 and count("cop") == 0, -- (the quartermaster and, since 14 November, the medic keep their posts)
        "(the owner's setup) lc_npc_budget 10 is full of citizens: hardly a fighter at home and no unit on the street", before .. " NPCs, " .. LC.RebelsIn(rz) .. " at home, " .. count("cop") .. " units")
    local okR, why = LC.StartRebelRaid(rz, T)
    local sk = LC.Skirmish
    ok(okR and sk and #sk.rebels >= 4, "a raid still sets out with its fighters", tostring(why) .. " " .. (sk and #sk.rebels or 0))
    ok(sk and sk.swapped >= 3 and sk.spawned == 0 and LC.CityNPCCount() <= before,
        "citizens nobody could see made way for them: the city's NPC count didn't go up", sk and (sk.swapped .. " swapped, " .. LC.CityNPCCount() .. " NPCs"))
    _run(2.6) -- (the markers go out on a two-second timer: exactly two seconds caught it or not by what ran before)
    ok(MarkFor(res, "OUR FIGHTERS") ~= nil, "the Resistance see where their fighters are from the moment they set out")
    ok(MarkFor(unit, "ANTICITIZEN ATTACK") == nil, "Civil Protection don't, yet: nothing has happened")
    local dockAt, dockNear
    hook.Add("LivingCityRationsDocked", "RebelEventTests", function(pos)
        if dockAt then return end
        dockAt = CurTime()
        for _, r in ipairs(sk.rebels) do if IsValid(r) and r:GetPos():Distance(pos) < 1900 then dockNear = true end end
    end)
    local t0 = CurTime()
    for _ = 1, 60 do _run(1) if sk.arrivedAt then break end end
    ok(sk.arrivedAt ~= nil and not sk.done, "they get to the target", math.floor(CurTime() - t0) .. " s")
    ok(sk.ends >= (sk.arrivedAt or 0) + 140, "and the raid's clock starts there (a long walk doesn't use it up)")
    local hostile = 0
    for _, u in ipairs(sk.units) do
        local st = IsValid(u) and LC.NPCs[u]
        if st and st.state == "hostile" and st.armed then hostile = hostile + 1 end
    end
    ok(#sk.units >= 2 and hostile >= 2 and LC.CityNPCCount() <= before, "with no unit near, units are swapped in out of sight, guns drawn, still within the cap",
        #sk.units .. " sent, " .. hostile .. " hostile, " .. LC.CityNPCCount() .. " NPCs")
    _run(2)
    ok(MarkFor(unit, "ANTICITIZEN ATTACK", sk.arrivedAt) ~= nil, "now Civil Protection see the attack on their screens")
    local fighting = false
    for _ = 1, 20 do
        for _, r in ipairs(sk.rebels) do local st = LC.NPCs[r] if st and st.foe then fighting = true end end
        if fighting then break end
        _run(0.5)
    end
    ok(fighting, "and the raiders fight them")
    _run(20)
    ok(dockAt and dockAt >= sk.arrivedAt and dockNear, "rations are docked \"near a Resistance attack\" only once the fighters are really there", tostring(dockAt) .. " " .. tostring(sk.arrivedAt))
    hook.Remove("LivingCityRationsDocked", "RebelEventTests")
    -- (the owner, 23 November: "we need an overwatch squad to respond within 20-30 seconds to rebel attacks like that")
    for _ = 1, 10 do if sk.owSent or sk.done then break end _run(1) end
    local ow = 0
    for _, u in ipairs(sk.units) do local st = IsValid(u) and LC.NPCs[u] if st and st.role == "soldier" then ow = ow + 1 end end
    ok(sk.owSent and ow >= 1 and CurTime() - sk.arrivedAt <= 31, "within half a minute an Overwatch squad comes in to it", ow .. " soldiers, " .. math.floor(CurTime() - sk.arrivedAt) .. " s")
    local sent = {}
    for _, u in ipairs(sk.units) do if IsValid(u) and LC.NPCs[u] and LC.NPCs[u].unmanaged then sent[#sent + 1] = u end end
    sk.ends = CurTime()
    _run(3)
    ok(LC.Skirmish == nil and LC.EventRoom(sk) == 0 and LC.EventNPCCount() == 0, "when it ends, it's over: nothing more may come for it", tostring(LC.Skirmish) .. " " .. LC.EventNPCCount())
    _run(8)
    local left = 0
    for _, u in ipairs(sent) do if IsValid(u) and LC.NPCs[u] then left = left + 1 end end
    ok(left == 0, "the units withdraw out of sight", left)
    _run(30)
    ok(LC.CityNPCCount() <= 10, "and the city stays within its cap while the fighters go home", LC.CityNPCCount())
    Clear(sk)

    section("Rebel raids: the fighters at home go first; idle units are sent before any swap")
    _setcvar("lc_npc_budget", 500)
    for n in pairs(LC.NPCs) do if IsValid(n) then n:Remove() end end
    _setcvar("lc_citizens", 0)
    _setcvar("lc_cops", 0)
    _run(30)
    local home = {}
    for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "rebel" and st.zone == rz and not st.unmanaged then home[n] = true end end
    local nHome = table.Count(home)
    local idle, ist = LC.Spawners.cop(T + Vector(4000, 0, 4))
    ist.untilT, ist.nextInspect = CurTime() + 1000, CurTime() + 1000
    LC.StartRebelRaid(rz, T)
    local hk = LC.Skirmish
    local fromHome = 0
    for _, r in ipairs(hk.rebels) do if home[r] then fromHome = fromHome + 1 end end
    ok(nHome >= 4 and fromHome == 4 and #hk.rebels == 4 and hk.swapped == 0, "all four come from the fighters at home: nobody new", nHome .. " home, " .. fromHome .. " of " .. #hk.rebels)
    for _ = 1, 60 do _run(1) if hk.arrivedAt then break end end
    local sentIdle = false
    for _, u in ipairs(hk.units) do if u == idle then sentIdle = true end end
    ok(hk.arrivedAt and sentIdle and hk.swapped == 0, "an idle unit a street away is sent as he is", tostring(sentIdle) .. " " .. hk.swapped)
    Clear(hk)
    if IsValid(idle) then idle:Remove() end
    _setcvar("lc_citizens", 14)
    _setcvar("lc_cops", 4)

    section("Rebel raids: the allowance is only a last resort, and goes when the raid ends")
    _setcvar("lc_rebels", 0)
    for n in pairs(LC.NPCs) do if IsValid(n) then n:Remove() end end
    _setcvar("lc_npc_budget", 0)
    _run(1)
    radio = {}
    local none, whyNone = LC.StartRebelRaid(rz, T)
    ok(not none and LC.Skirmish == nil and not Said("resistance", "hitting the Combine"), "nobody to move or swap and no allowance (lc_event_npc_allowance 0): no raid, and nothing announced", tostring(whyNone))
    _setcvar("lc_event_npc_allowance", 2)
    LC.StartRebelRaid(rz, T)
    local ak = LC.Skirmish
    ok(ak and #ak.rebels == 2 and ak.spawned == 2 and LC.EventRoom(ak) == 0, "with lc_event_npc_allowance 2: two fighters above the cap, and no more", ak and (#ak.rebels .. " " .. ak.spawned))
    if ak then LC.EndSkirmish(ak, "test") end
    ok(ak and LC.EventRoom(ak) == 0 and LC.EventNPCCount() == 0, "ended: the allowance is gone")
    Clear(ak)
    _setcvar("lc_event_npc_allowance", 0)

    section("Rebel raids: a wall in the way doesn't stop them; a raid that never gets there says so")
    _setcvar("lc_npc_budget", 500)
    _walls = { { a = Vector(O.x + 900, O.y - 4000, 0), b = Vector(O.x + 900, O.y + 4000, 0) } }
    LC.StartRebelRaid(rz, T)
    local sw = LC.Skirmish
    for _ = 1, 90 do _run(1) if sw.arrivedAt then break end end
    local skips, near = 0, false
    for _, r in ipairs(sw.rebels) do
        local st = IsValid(r) and LC.NPCs[r]
        if st and st.raid and (st.raid.skips or 0) > 0 then skips = skips + 1 end
        if IsValid(r) and r:GetPos():Distance(T) < 1800 then near = true end
    end
    ok(sw.arrivedAt ~= nil and near and skips > 0, "fighters stuck behind a wall get past it where nobody sees, and reach the target", tostring(sw.arrivedAt) .. " skips " .. skips)
    _walls = {}
    Clear(sw)
    radio = {}
    LC.StartRebelRaid(rz, T)
    local nv = LC.Skirmish
    for _, r in ipairs(nv.rebels) do r.sim = false end -- (they don't move at all)
    nv.started = CurTime() - (LC.RaidWalkSecs + 1)
    _run(3)
    ok(nv.done and not nv.alerted and not Said("cp", "incursion") and Said("resistance", "couldn't get through"),
        "a raid that never reaches its target is called off: no fight claimed", table.concat(radio, " | "))
    Clear(nv)

    section("Rebel raids: the Commissary's restrictions make the parties bigger")
    local realCount = LC.MarketRestrictedCount
    local n = 0
    LC.MarketRestrictedCount = function() return n end
    _setcvar("lc_market_rebels_max", 0) -- (first just the raid scale: no fighters for the zones)
    local want = { [0] = 0, 0, 0, 1, 1, 2, 3, 4 }
    local got = {}
    local allOk = true
    for k = 0, 7 do
        n = k
        got[#got + 1] = LC.MarketRaidExtra()
        if LC.MarketRaidExtra() ~= want[k] or LC.RaidPartySize() ~= 4 + want[k] then allOk = false end
    end
    ok(allOk, "0 to 7 restrictions: no extra raiders, then one from 3, two from 5, and one more each past that", table.concat(got, ","))
    n = 15
    ok(LC.MarketRaidExtra() == 6, "never more than lc_market_raid_max (6)", LC.MarketRaidExtra())
    _setcvar("lc_market_rebels_max", 6)
    n = 3
    for r, st in pairs(LC.NPCs) do if IsValid(r) and st.role == "rebel" then r:Remove() end end
    local over = LC.MarketRebelOverflow()
    ok(over == 3 and LC.MarketRaidExtra() == 4, "fighters rebel territory can't take in (nobody home: no room, or the cap) go into the raids instead", over .. " " .. LC.MarketRaidExtra())
    _setcvar("lc_market_rebels_max", 0)
    n = 5
    LC.StartRebelRaid(rz, T)
    local big = LC.Skirmish
    ok(big and #big.rebels == 6, "five restrictions: a raid of six", big and #big.rebels)
    Clear(big)
    LC.MarketRestrictedCount = realCount
    _setcvar("lc_market_rebels_max", 6)

    section("Rebel operations: an announced attack on a supply drop has fighters at it")
    radio = {}
    _setcvar("lc_rebel_ops", 1)
    _setcvar("lc_rebel_react", 1)
    local S = O + Vector(2500, 900, 0)
    LC.Supply = { pos = S, startT = CurTime() - 60 }
    ok(LC.RebelReact(CurTime()), "the Resistance go for a supply drop")
    local op = LC.Skirmish
    ok(op and op.purpose == "supply" and #op.rebels >= 4, "with real fighters", op and #op.rebels)
    local atDrop
    hook.Add("LivingCityRebelOpDone", "RebelEventTests", function(_, s)
        for _, r in ipairs(s.rebels) do if IsValid(r) and r:GetPos():Distance(S) < 400 then atDrop = true end end
    end)
    for _ = 1, 60 do _run(1) if not op or op.arrivedAt then break end end
    ok(op and op.arrivedAt and #op.units >= 2, "units were sent to stop them", op and #op.units)
    for _, u in ipairs(op and op.units or {}) do if IsValid(u) then u:SetHealth(0) end end -- (a Resistance player saw to them)
    for _ = 1, 120 do _run(1) if not op or op.achieved then break end end
    ok(op and op.achieved and atDrop and Said("resistance", "supply drop"), "and \"they got into the supply drop\" only with fighters standing at it",
        tostring(op and op.achieved) .. " " .. tostring(atDrop) .. " " .. tostring(op and op.progress) .. " " .. table.concat(radio, " | "))
    hook.Remove("LivingCityRebelOpDone", "RebelEventTests")
    -- (it used to be marked done without ending, so LC.Skirmish stayed set and no raid or sweep ever came again)
    if op then op.ends = math.min(op.ends or math.huge, CurTime() + 5) end
    for _ = 1, 30 do _run(1) if not op or op.done then break end end
    ok(op and op.done and LC.Skirmish ~= op, "and then it ends like any other, so raids and sweeps can come again", tostring(op and op.done))
    Clear(LC.Skirmish)
    LC.Supply = nil
    _setcvar("lc_rebel_ops", 0)
    _setcvar("lc_rebel_react", 0.5)

    LC.SendCompressed = realSend
    LC.RadioNotice = realRadio
    _walls = savedWalls
    for n2 in pairs(LC.NPCs) do if IsValid(n2) then n2:Remove() end end
    LC.RemoveZone(rz)
    res:SetPos(FAR) unit:SetPos(FAR)
    _setcvar("lc_npc_budget", 500)
    _setcvar("lc_rebels", 0)
    _run(1)
end
RebelEventTests()


-- The owner, 7 November: "there needs to be a real hit to the resistance that is actually visible and
-- tangible ... there need to be actual manpower counters/trackers and a longer/realistic timer for
-- respawning either rebels or CP units" (sv_livingcity_manpower.lua).
function ManpowerTests()
    local FAR = Vector(-31000, 31000, 0)
    _setcvar("lc_auto_events", 0)
    _setcvar("lc_skirmishes", 0)
    _setcvar("lc_manpower", 1)
    for n in pairs(LC.NPCs) do if IsValid(n) then n:Remove() end end
    _run(1)
    LC.Manpower = {}
    LC.ManpowerOut = {}
    local res = newPlayer("MPRes", "resistance", nil, 200)
    local unit = newPlayer("MPUnit", "cp", nil, 200)
    local cit = newPlayer("MPCit", "citizen")
    for _, p in ipairs({ res, unit, cit }) do p:SetPos(FAR) end
    local radio = {}
    local realRadio = LC.RadioNotice
    LC.RadioNotice = function(band, text, ...) radio[#radio + 1] = band .. ": " .. tostring(text) if realRadio then return realRadio(band, text, ...) end end
    local function Said(band, needle)
        for _, l in ipairs(radio) do if string.sub(l, 1, #band) == band and string.find(l, needle, 1, true) then return true end end
        return false
    end
    local P = function(side) return LC.ManpowerPool(side) end
    local at = FAR + Vector(600, 0, 0)

    local freeWas = LC.ManpowerRebelsFree
    LC.ManpowerRebelsFree = 100000 -- (the Combine growing with Resistance players is tested on its own, in SideBalanceTests)
    for _, side in ipairs({ "rebel", "cp", "ota" }) do local p0 = P(side) p0.reserve = math.min(p0.reserve, LC.ManpowerMax(side)) end
    section("Manpower: a death draws the reserve down, and the replacement waits for a recruit")
    ok(P("rebel").reserve == 20 and P("cp").reserve == 20 and P("ota").reserve == 12, "a fresh city starts with full reserves (20 fighters, 20 units, 12 soldiers)",
        P("rebel").reserve .. "/" .. P("cp").reserve .. "/" .. P("ota").reserve)
    P("cp").reserve = 1
    local cop = LC.SpawnCop(at)
    ok(IsValid(cop) and P("cp").reserve == 0 and LC.ManpowerOut[cop] == "cp", "a unit coming out takes one from Civil Protection's reserve")
    cop:SetHealth(0)
    cop:Remove()
    ok(P("cp").reserve == 0 and P("cp").lost == 1, "killed: a loss for the day, and nothing comes back", P("cp").lost)
    ok(LC.SpawnCop(at) == nil, "with the reserve empty, no unit comes")
    LC.ManpowerTick(60)
    ok(P("cp").reserve == 0, "not a minute later either")
    LC.ManpowerTick(5 * 60)
    ok(P("cp").reserve == 1, "a new unit after lc_manpower_cp_minutes (5)", P("cp").reserve)
    local cop2 = LC.SpawnCop(at)
    ok(IsValid(cop2), "and only then does the replacement come")
    P("rebel").reserve = 0
    ok(LC.SpawnRebel(at, nil) == nil, "the Resistance the same: no fighter from an empty reserve")
    P("ota").reserve = 0
    ok(LC.SpawnSoldier(at) == nil, "and Overwatch")

    section("Manpower: one who goes home alive goes back in the reserve")
    P("cp").reserve = 10
    local walker = LC.SpawnCop(at)
    ok(P("cp").reserve == 9, "out: one fewer in reserve")
    walker:Remove()
    ok(P("cp").reserve == 10 and P("cp").lost == 1, "gone home unhurt: back in the reserve, and not a loss", P("cp").reserve .. " " .. P("cp").lost)
    if IsValid(cop2) then cop2:Remove() end
    ok(P("cp").reserve == 11, "the same for the replacement", P("cp").reserve)

    section("Manpower: the quartermaster, quest people and the like never touch a reserve")
    P("cp").reserve = 0
    local free = LC.ManpowerFree(LC.SpawnCop, at)
    ok(IsValid(free) and P("cp").reserve == 0 and LC.ManpowerOut[free] == nil, "spawned outside the reserve, even when it's empty")
    if IsValid(free) then free:Remove() end
    ok(P("cp").reserve == 0, "and not added to it when they go")

    section("Manpower: an empty reserve stops the top-ups")
    _setcvar("lc_cops", 3)
    P("cp").reserve = 0
    _run(20)
    ok(count("cop") == 0, "lc_cops 3 but no units in reserve: no patrols come", count("cop"))
    P("cp").reserve = 3
    _run(20)
    ok(count("cop") >= 1 and P("cp").reserve < 3, "units back in reserve: they come out again, from it", count("cop") .. " out, " .. P("cp").reserve .. " left")
    _setcvar("lc_cops", 0)
    for n, st in pairs(LC.NPCs) do if IsValid(n) and st.role == "cop" then n:Remove() end end
    _run(1)

    section("Manpower: raids and sweeps wait while a side is depleted, and its own hear why")
    for _, z in ipairs(LC.ZonesOfKind("rebel")) do LC.RemoveZone(z) end
    local O = Vector(72000, 72000, 0)
    local rz = LC.AddZone(O, 500, "rebel", 0)
    if LC.Skirmish then LC.EndSkirmish(LC.Skirmish, "test") end -- (nothing else on: the reserve is what stops it)
    P("rebel").reserve = 1
    local okR, why = LC.StartRebelRaid(rz, O + Vector(3000, 0, 0))
    ok(not okR and LC.Skirmish == nil and string.find(tostring(why), "reserve", 1, true) ~= nil, "a raid with only 1 fighter in reserve doesn't go", tostring(why))
    ok(Said("resistance", "No raids for now"), "and the Resistance hear why on the radio", table.concat(radio, " | "))
    ok(not LC.PlanRebelRaid(), "a planned raid isn't planned either")
    P("cp").reserve = 2
    local okS, whyS = LC.StartCombineSweep(rz)
    ok(not okS and string.find(tostring(whyS), "reserve", 1, true) ~= nil, "a sweep with 2 units in reserve waits too", tostring(whyS))
    ok(Said("cp", "sweeps postponed"), "and Civil Protection hear why")
    P("rebel").reserve = 20
    P("cp").reserve = 20

    section("Manpower: the Commissary's restrictions speed the Resistance's recruiting")
    local realCount = LC.MarketRestrictedCount
    LC.MarketRestrictedCount = function() return 0 end
    local base = LC.ManpowerInterval("rebel")
    LC.MarketRestrictedCount = function() return 4 end
    local quick = LC.ManpowerInterval("rebel")
    ok(quick < base * 0.7, "four restrictions: a recruit comes 60% faster (lc_manpower_restrict_pct 15 each)", math.floor(base) .. " s, then " .. math.floor(quick) .. " s")
    P("rebel").reserve = 5
    local lines = LC.ManpowerReadoutFor(res)
    ok(lines[3] and string.find(lines[3], "faster (Commissary restrictions", 1, true) ~= nil, "and the Resistance's page says why", table.concat(lines, " | "))
    LC.MarketRestrictedCount = realCount
    ok(LC.ManpowerInterval("cp") == 300, "Civil Protection's trickle is steady, whatever the Commissary does")
    local before = P("ota").reserve
    hook.Run("LivingCityOverwatchDrop", { expected = 4 })
    ok(P("ota").reserve == before + 4, "an Overwatch drop brings its soldiers as a batch", before .. " then " .. P("ota").reserve)

    section("Manpower: after a big loss, both sides hear it")
    radio = {}
    P("rebel").reserve = 6
    local fallen = {}
    for i = 1, 4 do
        local r = LC.SpawnRebel(at + Vector(i * 40, 0, 0), nil)
        fallen[#fallen + 1] = r
    end
    for _, r in ipairs(fallen) do if IsValid(r) then r:SetHealth(0) r:Remove() end end
    LC.ManpowerFightsOver(CurTime() + 30)
    ok(Said("resistance", "We lost four fighters") and Said("resistance", "stretched thin"), "the Resistance's radio: \"We lost four fighters ... We're stretched thin\"", table.concat(radio, " | "))
    ok(Said("cp", "four anticitizens neutralized"), "and Civil Protection hear it as good news")

    section("Manpower: what each side sees")
    P("rebel").reserve, P("rebel").lost, P("rebel").progress = 7, 3, 0
    lines = LC.ManpowerReadoutFor(res)
    ok(lines[1] == "Fighters: 7 in reserve (of 20), 3 lost today", "the Resistance: their fighters", lines[1])
    ok(lines[2] and string.find(lines[2], "^Next recruit in about %d+ minutes") ~= nil, "and when the next recruit comes", lines[2])
    lines = LC.ManpowerReadoutFor(unit)
    ok(lines[1] and string.find(lines[1], "^Civil Protection: %d+ in reserve %(of 20%)") and lines[3] and string.find(lines[3], "^Overwatch: ") ~= nil,
        "Civil Protection: their units and Overwatch's soldiers", table.concat(lines, " | "))
    P("cp").reserve = 20
    ok(LC.ManpowerReadoutFor(unit)[2] == "The reserve is full", "a full reserve says so")
    ok(#LC.ManpowerReadoutFor(cit) == 0, "a citizen sees neither")

    -- The owner, 7 November: the reserves on the Administrator's tablet and on the records terminal too.
    section("Manpower: the Administrator's tablet and the records terminal show the Combine's reserves")
    do
        local boss = newPlayer("MPAdmin", "admin")
        boss:SetPos(FAR + Vector(0, 200, 0))
        P("cp").reserve, P("cp").lost = 13, 2
        local want = table.concat(LC.ManpowerReadout("combine"), " | ")
        local sentT = {}
        local realSend = LC.SendCompressed
        LC.SendCompressed = function(msg, tbl, to) sentT[msg] = tbl return realSend(msg, tbl, to) end
        local function Open()
            sentT = {}
            LC.OpenAdminOffice(boss)
            LC.SendRecords(unit)
            return sentT.lc_admin_office, sentT.lc_records
        end
        local office, recs = Open()
        local om = office and office.manpower or {}
        ok(om[1] == "Civil Protection: 13 in reserve (of 20), 2 lost today" and om[2] ~= nil and om[3] and string.find(om[3], "^Overwatch: ") ~= nil and om[4] ~= nil,
            "the tablet's office: Civil Protection and Overwatch, in reserve, lost today, and the next recruit", table.concat(om, " | "))
        ok(table.concat(om, " | ") == want, "the same lines as F2 > Combine manpower and the unit tools", want)
        ok(recs and recs.manpower and table.concat(recs.manpower, " | ") == want, "the records terminal has them too",
            recs and table.concat(recs.manpower or {}, " | ") or "no records sent")
        _setcvar("lc_manpower", 0)
        office, recs = Open()
        ok(office and #(office.manpower or {}) == 0 and recs and #(recs.manpower or {}) == 0, "with manpower off (lc_manpower 0), neither shows it")
        _setcvar("lc_manpower", 1)
        LC.SendCompressed = realSend
        P("cp").reserve, P("cp").lost = 20, 0
        LC.SetFaction(boss, "citizen", nil, true) -- (steps down, so later tests find the office empty)
        boss:SetPos(Vector(-120000, -120000, 0))
    end

    section("Manpower: kept per map across restarts")
    P("rebel").reserve, P("rebel").lost, P("cp").reserve, P("ota").reserve = 4, 9, 17, 2
    local out = LC.SpawnRebel(at, nil)
    ok(P("rebel").reserve == 3, "one fighter out")
    LC.ManpowerSave()
    local saved = _files[LC.ManpowerFile()] or ""
    ok(string.find(saved, "reserve", 1, true) ~= nil, "saved to data/" .. LC.ManpowerFile())
    if IsValid(out) then out:Remove() end
    LC.ManpowerLoad()
    ok(P("rebel").reserve == 4 and P("rebel").lost == 9 and P("cp").reserve == 17 and P("ota").reserve == 2,
        "after a restart: the same reserves (the fighter who was out came home), and today's losses",
        P("rebel").reserve .. " " .. P("rebel").lost .. " " .. P("cp").reserve .. " " .. P("ota").reserve)

    LC.RadioNotice = realRadio
    LC.ManpowerRebelsFree = freeWas
    LC.RemoveZone(rz)
    for n2 in pairs(LC.NPCs) do if IsValid(n2) then n2:Remove() end end
    _setcvar("lc_manpower", 0)
    LC.Manpower = {}
    LC.ManpowerOut = {}
    _run(1)
end
ManpowerTests()

function CrabHuntTests() -- (the owner, 7 November: Resistance jobs to bring raw headcrabs back from the infestation for the crate)
    local CH = LC.CrabHunt
    local FAR = Vector(-33000, 33000, 0)
    local R0, I0 = Vector(-52000, 52000, 0), Vector(-50800, 52000, 0)
    local rz = LC.AddZone(R0, 400, "rebel", 0)
    local iz = LC.AddZone(I0, 400, "infest", 0)
    LC.EnsureRebelProps()
    local rp = LC.RebelProps[rz]
    local cache = rp and rp.cache
    -- every other camp's crate well stocked for now, so only ours is low
    local saved = {}
    for _, r in pairs(LC.RebelProps) do
        if IsValid(r.cache) and r.cache ~= cache then saved[r.cache] = r.cache.lcStock r.cache.lcStock = 99 end
    end
    local hunter = newPlayer("CrabHunter", "resistance", nil, 900)
    _runtimers() -- (the spawn's own placing runs a moment later: let it, or it moves the hunter mid-test)
    hunter:SetPos(R0 + Vector(0, 300, 0))

    section("Headcrab hunt: offered more while the crate is low, always when it's empty")
    ok(CH ~= nil and IsValid(cache), "(a camp with a crate, and infested ground nearby)")
    if not (CH and IsValid(cache)) then return end
    local realR = math.random
    math.random = function(a, b) if a == nil then return 0.99 end if b == nil then return realR(a) end return realR(a, b) end
    cache.lcStock = 50
    ok(not CH.Low(cache) and not CH.Available(), "a well-stocked crate: it comes up only now and then (not on this roll)")
    cache.lcStock = 2
    ok(CH.Low(cache) and CH.Available(), "a crate down to two meals: always on the board")
    math.random = function(a, b) if a == nil then return 0.01 end if b == nil then return realR(a) end return realR(a, b) end
    cache.lcStock = 50
    ok(CH.Available(), "and on a lucky roll even while the crate is full")
    math.random = realR

    section("Headcrab hunt: into the infested ground, kill headcrabs, bring the meat to the crate")
    LC.SweepCache(cache)
    ok((cache.lcStock or 0) == 0, "(an empty crate)")
    local q = inject(hunter, "res_crabhunt")
    ok(q ~= nil and string.find(q.title, "Headcrab hunt", 1, true) ~= nil and #q.stages == 3, "a Resistance member can take a headcrab hunt", q and q.title)
    if q then
        ok(string.find(q.desc, "empty", 1, true) ~= nil and string.find(q.desc, "headcrabs", 1, true) ~= nil, "it says the crate is empty and what to bring", q.desc)
        ok(q.stages[1].pos == iz.pos, "the hunting ground is the infested ground nearest the camp")
        ok(not q.violent, "no squad of fighters: it isn't a fight with the Combine")
        hunter:SetPos(I0)
        _run(1)
        ok(q.stage == 2, "in the infested ground, the hunt starts", q.stage)
        local crabs = q.data.crabs or {}
        ok(#crabs >= CH.NEED + 1, "a few more headcrabs crawl out for it", #crabs)
        local extra = #crabs > 0
        for _, n in ipairs(crabs) do if not (LC.NPCs[n] and LC.NPCs[n].unmanaged) then extra = false end end
        ok(extra, "on top of the usual number, and nothing replaces them")
        -- a zombie, or a headcrab far from the infestation, doesn't count
        local zomb = LC.SpawnZombie(I0 + Vector(30, 0, 4), iz, "npc_zombie")
        if IsValid(zomb) then zomb:SetHealth(0) hook.Run("OnNPCKilled", zomb, hunter) end
        local stray = ents.Create("npc_headcrab")
        stray:SetPos(FAR + Vector(3000, 0, 0))
        stray:Spawn()
        stray:SetHealth(0)
        hook.Run("OnNPCKilled", stray, hunter)
        ok((q.stages[2].got or 0) == 0, "a zombie, or a headcrab out in the city, doesn't count", q.stages[2].got)
        for i = 1, CH.NEED do
            local n = crabs[i]
            if IsValid(n) then n:SetHealth(0) hook.Run("OnNPCKilled", n, hunter) end
        end
        ok(q.stage == 3, "four headcrabs down: now bring the meat home", q.stage .. " " .. tostring(q.stages[2].got))
        _run(1)
        -- the meat: two now, two later
        LC.GiveItem(hunter, "raw_headcrab", 2)
        hunter:SetPos(cache:GetPos() + Vector(-60, 0, 0))
        _run(1)
        ok(q.stages[3].got == 2 and cache.lcStock == 2 and not LC.HasItem(hunter, "raw_headcrab"), "standing by the crate, the meat goes in: a meal each",
            tostring(q.stages[3].got) .. " " .. tostring(cache.lcStock))
        ok(not q.done, "half of it isn't the job done")
        local xp, realXP = {}, LC.AddXP
        LC.AddXP = function(p, n, why) if p == hunter then xp[#xp + 1] = n end return realXP(p, n, why) end
        LC.GiveItem(hunter, "raw_fastcrab")
        LC.GiveItem(hunter, "raw_poisoncrab")
        _run(1)
        LC.AddXP = realXP
        ok(q.done and cache.lcStock == 4, "any kind of headcrab will do: four in the crate, the job's done", cache.lcStock)
        ok(q.bonus == CH.EMPTY_BONUS and (xp[1] or 0) >= CH.REWARD + CH.EMPTY_BONUS, "and pays more for filling an empty crate", tostring(xp[1]))
    end
    hunter:SetPos(FAR)

    section("Headcrab hunt: a crate that runs empty puts it up straight away, with a notice")
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_crabhunt" then p.dead = true end end
    LC.SweepCache(cache)
    CH.nextPost = 0
    local notices, realNotice = {}, LC.Notice
    LC.Notice = function(p, kind, title, text, secs) if p == hunter then notices[#notices + 1] = text end return realNotice(p, kind, title, text, secs) end
    hunter.chat = {}
    local posted = CH.Check(CurTime())
    ok(posted ~= nil and posted.tmpl.id == "res_crabhunt" and posted.urgent, "an empty crate: a headcrab hunt goes up on the Operations board")
    ok(has(notices, "headcrab hunt") and has(hunter.chat, "Headcrab hunt"), "and the Resistance are told (on screen, and in chat)", notices[1])
    notices = {}
    ok(CH.Check(CurTime()) == nil and #notices == 0, "not again for a while")
    CH.nextPost = 0
    ok(CH.Check(CurTime()) == nil, "nor while one is still up")
    LC.Notice = realNotice
    if posted then posted.dead = true end
    LC.AddToCache(cache, 3)
    CH.nextPost = 0
    ok(CH.Check(CurTime()) == nil, "a crate with food in it posts nothing")

    -- put things back
    for c, n in pairs(saved) do if IsValid(c) then c.lcStock = n end end
    for n, st in pairs(LC.NPCs) do if IsValid(n) and st.zone == iz then n:Remove() end end
    CH.nextPost = CurTime() + 99999
    LC.RemoveZone(iz)
    LC.RemoveZone(rz)
    hunter.valid = false
    _run(1)
end
CrabHuntTests()



-- The owner, 7 November: what units confiscate is burned in public, in the square, the citizens made to
-- watch, the Resistance with a chance to snatch some back before it catches (sv_livingcity_evidence.lua).
function EvidenceTests()
_setcvar("lc_patdown", 0) -- (a unit that walks a wanted player in bags what is in their pockets: that would add to the stock counted here; PatdownTests has it)
    local FAR = Vector(29000, -29000, 0)
    local wasRunning, wasAuto, wasBudget = LC.Running, LC.EvidenceAuto, GetConVar("lc_npc_budget"):GetInt()
    LC.Running, LC.EvidenceAuto = true, false
    _setcvar("lc_npc_budget", 500)
    if LC.EvidenceBurn then LC.EvidenceFinish(LC.EvidenceBurn, true) end
    LC.EvidenceStock, LC.EvidenceAfterAt, LC.EvidenceNextAuto = {}, nil, 0
    local realEntsOf, realRadio, realSeen, realSquad = LC.EntsOf, LC.RadioNotice, LC.SeenBySecurity, LC.AlarmSquadSpot
    local speakers = {}
    LC.EntsOf = function(cls)
        if cls == "lc_loudspeaker" then return speakers end
        if cls == "lc_screen" or cls == "lc_dispenser" then return {} end
        return realEntsOf(cls)
    end
    local radio = {}
    LC.RadioNotice = function(band, text, ...) radio[#radio + 1] = band .. ": " .. tostring(text) if realRadio then return realRadio(band, text, ...) end end
    local function Find(id)
        for _, e in ipairs(LC.EvidenceStock) do if e.id == id or e.name == id then return e end end
    end
    local function Work(npc)
        local st = IsValid(npc) and LC.NPCs[npc]
        return st and st.npcWork and st.npcWork.id or nil
    end

    section("Evidence: what units confiscate goes into the evidence stock")
    local cit = newPlayer("EvCit", "citizen")
    cit:SetPos(FAR + Vector(0, 2000, 0))
    LC.GiveItem(cit, "radio", 2)
    hook.Run("LivingCityIncarcerated", cit)
    local r = Find("radio")
    ok(r and r.n == 2 and r.model == LCS.Items.radio.model, "arrest: both radios taken in processing are in the stock, as themselves", r and r.n)
    hook.Run("LivingCitySearched", nil, cit, { { id = "radio", n = 1 } }, { "weapon_pistol" })
    ok(Find("radio").n == 3 and Find("w:weapon_pistol") and Find("w:weapon_pistol").model == "models/weapons/w_pistol.mdl",
        "a search: the same kind adds up, and a gun goes in with its own model")
    LC.EvidenceAdd(nil, 1, "search", "a handful of pistol rounds")
    LC.EvidenceAdd(nil, 1, "search", "a lambda armband")
    ok(Find("ammo_pistol") and Find("a lambda armband") and Find("a lambda armband").id == nil,
        "what an NPC citizen had: the item it is where there's one, else just what it was")
    local item = ents.Create("lc_item")
    item:SetNW2String("lc_item", "radio_transmitter")
    LC.EvidenceFromEntity(item, "raid")
    hook.Run("LivingCityStashRaided", cit, { { id = "papers_forged", n = 1 } })
    ok(Find("radio_transmitter") and Find("papers_forged"), "a raid: what it finds lying about, and a stash it turns out")
    item:Remove()
    ok(LC.EvidenceTotal() == 8 and GetGlobal2Int("lc_evidence_n", 0) == 8 and string.find(GetGlobal2String("lc_evidence_list", ""), "Old radio x3", 1, true),
        "the units' menu sees how many and what (Unit tools, F2)", LC.EvidenceTotal())
    ok(string.find(LC.EvidenceStatus(), "In the evidence room: 8 items", 1, true), "and the admin tools say it in a line", LC.EvidenceStatus())

    section("Evidence: where it's burned, the square, or nowhere")
    local realPoints = LC.Points
    LC.Points = {}
    local okNo, whyNo = LC.EvidenceBurnNow(nil)
    ok(not okNo and string.find(whyNo or "", "Nowhere to burn it", 1, true) and LC.EvidenceTotal() == 8,
        "nothing placed anywhere: nothing burned, the stock kept, and it says what to place", whyNo)
    LC.Points = { { kind = "idle", pos = FAR + Vector(-400, 0, 0), yaw = 0 } }
    local p0 = LC.EvidenceSpot()
    ok(p0 and p0:Distance(FAR + Vector(-400, 0, 0)) < 1, "no loudspeaker: a place people stand about will do")
    LC.Points = realPoints
    local spk = ents.Create("lc_loudspeaker")
    spk:SetPos(FAR)
    spk:SetAngles(Angle(0, 0, 0))
    speakers[1] = spk
    local pile = LC.EvidenceSpot()
    ok(pile and pile:Distance(FAR + Vector(160, 0, 0)) < 1, "a loudspeaker (the PA): the pile goes in front of it", tostring(pile))

    section("Evidence: units carry it to the square, the PA calls, the citizens gather, it burns, it's gone")
    local cop = LC.SpawnCop(pile + Vector(300, 0, 0))
    local cits = {}
    for i = 1, 3 do cits[i] = LC.SpawnCitizen(pile + Vector(-200 - 60 * i, 200, 0)) end
    local res = newPlayer("EvThief", "citizen") -- (anyone but a unit; a hunted rebel standing there would only draw the units)
    local unit = newPlayer("EvUnit", "cp")
    local adm = newPlayer("EvAdmin", "citizen")
    adm.admin = true
    res:SetPos(FAR + Vector(0, 4000, 0))
    unit:SetPos(pile + Vector(120, 300, 0))
    adm:SetPos(FAR + Vector(0, -3000, 0))
    local okGo, msg = LC.EvidenceBurnNow(adm)
    local b = LC.EvidenceBurn
    ok(okGo and b and b.phase == "carry" and LC.EvidenceTotal() == 0, "burn it now (an admin): the stock goes to the fire", msg)
    ok(Work(cop) == "evidence_carry" and IsValid(LC.NPCs[cop].carry), "a unit nearby carries it there, a box in his hands", Work(cop))
    ok(not LC.EvidenceBurnNow(adm), "and only one burn at a time")
    _run(8)
    ok(b.carriers[1] and b.carriers[1].delivered and #b.props > 0 and b.phase == "pile", "he gets there and it's piled up, each thing as itself", b.phase .. " " .. #b.props)
    ok(Work(cop) == "evidence_carry" and not IsValid(LC.NPCs[cop].carry), "his hands empty, he stays to guard it")
    local pa = _lastnet("lc_announce")
    ok(pa and (pa.data[1] == "npc/overwatch/cityvoice/f_trainstation_assemble_spkr.wav" or (pa.data[1] == "" and not GetConVar("lc_announce_stock"):GetBool())), "the PA calls the citizens to assemble (silent without Half-Life 2's voice, lc_announce_stock 0: the words only)", pa and pa.data[1])
    ok(has(cit.chat, "being burned"), "and says what's being burned, and where")
    ok(has(radio, "resistance: They've piled up"), "Freq 7 hears where it is")
    local watching = 0
    for _, c in ipairs(cits) do if Work(c) == "evidence_watch" then watching = watching + 1 end end
    ok(watching == 3, "the citizens nearby come to watch", watching)
    local conf = 0
    for _, e in ipairs(b.props) do if LC.ContrabandOf(e) then conf = conf + 1 end end
    ok(conf == 0, "a block raid passing never takes the pile for contraband lying about")

    section("Evidence: before it catches, anyone but a unit can snatch something back; a unit seeing it makes them wanted")
    local function PropOf(id) for _, e in ipairs(b.props) do if IsValid(e) and e.lcEvidence.entry.id == id then return e end end end
    local rp = PropOf("radio")
    ok(IsValid(rp) and rp:GetModel() == LCS.Items.radio.model, "the radios lie in the pile, as radios")
    if not IsValid(rp) then return end
    res:SetPos(pile + Vector(80, 0, 0))
    local okU = LC.EvidenceSnatch(unit, rp)
    ok(not okU and IsValid(rp), "a unit can't take it out of the pile")
    local ret = hook.Run("PlayerUse", res, rp)
    ok(ret == false and LC.HasItem(res, "radio") and not IsValid(rp), "E on the radios: back in the citizen's pockets, gone from the pile")
    ok(LC.PlayerIsWanted(res), "a unit was watching: wanted")
    LC.SeenBySecurity = function() return false end
    unit:SetPos(pile + Vector(5000, 0, 0))
    res.lcEvidenceUseAt = 0
    local okS, msgS = LC.EvidenceSnatch(res, PropOf("w:weapon_pistol"))
    ok(okS and string.find(msgS or "", "Nobody saw", 1, true), "nobody looking: away with the pistol", msgS)
    local okL = LC.EvidenceSnatch(res, PropOf(nil))
    ok(not okL, "an armband isn't worth saving")
    LC.SeenBySecurity = realSeen

    section("Evidence: it catches, burns, and everything is cleaned up")
    local fires = #ents.FindByClass("env_fire")
    _run(21)
    ok(b.phase == "burning" and #ents.FindByClass("env_fire") == fires + 1, "it catches: fire (and smoke)", b.phase)
    local okLate, why = LC.EvidenceSnatch(res, PropOf("ammo_pistol"))
    ok(not okLate and string.find(why or "", "Too late", 1, true), "too late to snatch anything now", why)
    ok(GetGlobal2String("lc_evidence_burn", "") ~= "", "the units' menu shows it burning")
    local props = {}
    for _, e in ipairs(b.props) do props[#props + 1] = e end
    _run(51)
    local still = 0
    for _, e in ipairs(props) do if IsValid(e) then still = still + 1 end end
    ok(LC.EvidenceBurn == nil and still == 0 and #ents.FindByClass("env_fire") == fires, "burned out: the pile and the fire are gone", still)
    ok(Work(cop) == nil and Work(cits[1]) == nil, "and everyone goes back to what they were doing")
    ok(LC.EvidenceTotal() == 0 and GetGlobal2String("lc_evidence_burn", "x") == "", "nothing left in the evidence room")

    section("Evidence: never during an ending or a dream; called off, it all goes back in the stock")
    LC.EvidenceAdd("radio", 4, "search")
    local realBusy = LC.EndingBusy
    LC.EndingBusy = function() return true end
    ok(not LC.EvidenceBurnNow(adm), "an ending running: not even an admin starts one")
    LC.EndingBusy = realBusy
    ok(LC.EvidenceBurnNow(adm), "afterwards it starts")
    LC.EndingBusy = function() return true end
    _run(2)
    LC.EndingBusy = realBusy
    ok(LC.EvidenceBurn == nil and LC.EvidenceTotal() == 4, "an ending starting mid-burn calls it off, and the stock is back", LC.EvidenceTotal())
    local wasEvent = LC.Event
    LC.Event = "curfew"
    ok(not LC.EvidenceBurnNow(adm), "nor in a curfew (the citizens are indoors)")
    LC.Event = wasEvent

    section("Evidence: by itself, after a sweep, or once enough has built up")
    LC.EvidenceAuto = true
    LC.EvidenceTick(CurTime())
    ok(LC.EvidenceBurn == nil, "four in stock and no sweep: it waits")
    hook.Run("LivingCityEventEnded", "sweep")
    _run(10)
    ok(LC.EvidenceBurn == nil, "a sweep just ended: not straight away")
    _run(20)
    ok(LC.EvidenceBurn ~= nil, "a little after the sweep, it's burned")
    if LC.EvidenceBurn then LC.EvidenceFinish(LC.EvidenceBurn, false) end
    LC.EvidenceAdd("radio", 9, "search")
    LC.EvidenceTick(CurTime())
    ok(LC.EvidenceBurn == nil, "nine more right after: not two burns in ten minutes")
    LC.EvidenceNextAuto = 0
    LC.EvidenceTick(CurTime())
    ok(LC.EvidenceBurn ~= nil, "eight or more, and it's been a while: burned")
    if LC.EvidenceBurn then LC.EvidenceFinish(LC.EvidenceBurn, true) end
    LC.EvidenceAuto = false

    section("Evidence: with no unit free nearby, two come from out of sight, only under lc_npc_budget")
    for _, c in ipairs(cits) do if IsValid(c) then c:Remove() end end
    if IsValid(cop) then cop:Remove() end
    LC.AlarmSquadSpot = function(p) return p + Vector(900, 0, 0) end
    _setcvar("lc_npc_budget", LC.CityNPCCount and LC.CityNPCCount() or table.Count(LC.NPCs))
    LC.EvidenceBurnNow(adm)
    ok(LC.EvidenceBurn and #LC.EvidenceBurn.carriers == 0, "the cap is full: nobody spawned, it's piled up anyway")
    if LC.EvidenceBurn then LC.EvidenceFinish(LC.EvidenceBurn, true) end
    _setcvar("lc_npc_budget", 500)
    LC.EvidenceBurnNow(adm)
    local sp = LC.EvidenceBurn
    local counted = 0
    for npc in pairs(sp and sp.spawned or {}) do if LC.NPCs[npc] and LC.NPCs[npc].eventNPC then counted = counted + 1 end end
    ok(sp and #sp.carriers == 2 and counted == 2, "room under the cap: two units, counted against it", sp and #sp.carriers)
    if sp then LC.EvidenceFinish(sp, false) end
    _run(121)
    local gone = true
    for npc in pairs(sp and sp.spawned or {}) do if IsValid(npc) then gone = false end end
    ok(gone, "and they go again afterwards")

    -- put everything back
    for _, e in ipairs({ spk, res, unit, adm, cit }) do if IsValid(e) then e:Remove() end end
    LC.EntsOf, LC.RadioNotice, LC.SeenBySecurity, LC.AlarmSquadSpot = realEntsOf, realRadio, realSeen, realSquad
    LC.EvidenceStock, LC.EvidenceAfterAt, LC.EvidenceNextAuto = {}, nil, 0
    LC.Running, LC.EvidenceAuto = wasRunning, wasAuto
    _setcvar("lc_npc_budget", wasBudget)
    _run(1)
_setcvar("lc_patdown", 1)
end
EvidenceTests()

-- The owner, later on 7 November: save files are written safely (sv_livingcity_safefile.lua). A checked
-- copy first, the previous good file kept as <name>.bak.txt, an unreadable file read from its backup,
-- and one that can't be read at all never saved over with an empty default.
function SafeFileTests()
    local P = "livingcity/safetest.json"
    local TMP, BAK, UNR = LC.SafeTmpPath(P), LC.SafeBakPath(P), LC.SafeUnreadablePath(P)
    local function Clear() for _, p in ipairs({ P, TMP, BAK, UNR }) do _files[p] = nil end LC.SafeFileAllow(P) end
    local function V(p) local t = _files[p] and util.JSONToTable(_files[p]) return t and t.v end
    Clear()

    section("Save files: written through a checked copy, the previous one kept as a backup")
    ok(LC.SafeWrite(P, util.TableToJSON({ v = 1 })) == true and V(P) == 1, "a new save file is written and holds what was saved")
    ok(_files[TMP] == nil and _files[BAK] == nil, "the checked copy is gone once it's in place, and there's nothing to back up yet")
    LC.SafeWrite(P, util.TableToJSON({ v = 2 }))
    ok(V(P) == 2 and V(BAK) == 1, "saved again: the previous good file is kept as .bak.txt", tostring(V(BAK)))
    ok(BAK == P .. ".bak.txt" and TMP == P .. ".tmp.txt", "the extra files sit next to it and end in .txt (the data folder takes it)", BAK)
    local realWrite = file.Write
    file.Write = function(p, s) if p == TMP then s = string.sub(s, 1, 3) end return realWrite(p, s) end -- (a full disk: cut short)
    local okCut = LC.SafeWrite(P, util.TableToJSON({ v = 3 }))
    file.Write = realWrite
    ok(not okCut and V(P) == 2 and V(BAK) == 1 and _files[TMP] == nil, "a copy that doesn't read back whole changes nothing")
    local moved = 0
    file.Rename = function(a, b)
        if _files[a] == nil or _files[b] ~= nil then return false end
        _files[b], _files[a] = _files[a], nil
        moved = moved + 1
        return true
    end
    LC.SafeWrite(P, util.TableToJSON({ v = 4 }))
    file.Rename = nil
    ok(moved == 2 and V(P) == 4 and V(BAK) == 2 and _files[TMP] == nil, "with file.Rename (newer Garry's Mod) the files are moved, not copied", moved)

    section("Save files: an unreadable file is read from its backup")
    _files[P] = '{"v": 4, "cut sh'
    local t, how = LC.SafeReadJSON(P)
    ok(how == "backup" and istable(t) and t.v == 2, "a cut-off file loads its .bak.txt instead", how)
    ok(not LC.SafeFileBlocked(P), "and can be saved again")
    LC.SafeWrite(P, util.TableToJSON({ v = 5 }))
    ok(V(P) == 5 and V(BAK) == 2, "an unreadable file never becomes the backup", tostring(V(BAK)))
    ok(_files[UNR] == '{"v": 4, "cut sh', "it's kept aside once, as .unreadable.txt")
    _files[TMP], _files[P] = util.TableToJSON({ v = 6 }), nil
    t, how = LC.SafeReadJSON(P)
    ok(how == "backup" and t.v == 6, "gone in the middle of a swap: the checked copy (the newest) is used", how)
    _files[TMP] = nil
    t, how = LC.SafeReadJSON(P)
    ok(t == nil and how == "missing" and _files[BAK] ~= nil, "deleted by hand (to start it over): stays deleted, its old backup isn't brought back", how)
    Clear()
    t, how = LC.SafeReadJSON(P)
    ok(t == nil and how == "missing" and not LC.SafeFileBlocked(P), "no file at all: start fresh (nothing to protect)", how)

    section("Save files: a file nothing can read is never saved over")
    _files[P] = "{ broken"
    t, how = LC.SafeReadJSON(P)
    ok(t == nil and how == "failed" and LC.SafeFileBlocked(P), "nothing readable: the file is marked, not loaded", how)
    ok(LC.SafeWrite(P, util.TableToJSON({})) == false and _files[P] == "{ broken", "the empty default isn't saved over it")
    local sa, ad = newPlayer("SafeSuper", "citizen"), newPlayer("SafeAdmin", "citizen")
    sa.admin, sa.superadmin, ad.admin = true, true, true
    local okA, msgA = LC.AdminTool(ad, ad, "savefiles", "allow")
    ok(not okA and LC.SafeFileBlocked(P), "an admin can't let the city save over it", msgA)
    local okS, msgS = LC.AdminTool(sa, sa, "savefiles", "allow")
    ok(okS and not LC.SafeFileBlocked(P), "a superadmin can, from the admin tools", msgS)
    ok(LC.SafeWrite(P, util.TableToJSON({ v = 7 })) and V(P) == 7 and _files[UNR] == "{ broken", "then it saves, the unreadable file kept aside")
    _files[P], _files[BAK] = "{ broken", nil
    LC.SafeReadJSON(P)
    _files[P] = util.TableToJSON({ v = 8 })
    t, how = LC.SafeReadJSON(P)
    ok(how == "ok" and t.v == 8 and not LC.SafeFileBlocked(P), "a file that reads again lifts the mark")
    LC.SafeWrite(P, util.TableToJSON({ v = 9 }))
    LC.SafeDelete(P)
    ok(_files[P] == nil and _files[BAK] == nil and _files[TMP] == nil and LC.SafeReadJSON(P) == nil, "deleted with its backup (a dream snapshot put back never comes back)")
    Clear()

    section("Save files: a module's data isn't wiped by an unreadable file (outfits)")
    local OF = "livingcity/outfits.json"
    local keepMain, keepBak, keepOutfits = _files[OF], _files[OF .. ".bak.txt"], LC.Outfits
    LC.Outfits = { testjob = { list = { { pm = "models/test.mdl" } } } }
    LC.SaveOutfits()
    LC.Outfits.otherjob = { list = { { pm = "models/test2.mdl" } } }
    LC.SaveOutfits()
    _files[OF] = '{"testjob": {"li'
    LC.LoadOutfits()
    ok(istable(LC.Outfits.testjob), "a cut-off outfits file loads from its backup")
    _files[OF], _files[OF .. ".bak.txt"] = '{"testjob": {"li', nil
    LC.LoadOutfits()
    ok(LC.Outfits.testjob == nil and LC.SafeFileBlocked(OF), "with no backup either, the defaults are used and the file is marked")
    LC.SaveOutfits()
    ok(_files[OF] == '{"testjob": {"li', "saving the defaults doesn't wipe the real file")
    LC.SafeFileAllow(OF)
    _files[OF], _files[OF .. ".bak.txt"], _files[OF .. ".tmp.txt"], _files[OF .. ".unreadable.txt"] = keepMain, keepBak, nil, nil
    LC.Outfits = keepOutfits
end
SafeFileTests()

function CollapseTests()
section("The collapse: sociostability BLACK, the G-Man's offer, the Administrator's last stand, the heroes (the owner, 9 November)")
local CS = LC.CollapseState
_setcvar("lc_black_min_players", 0)
-- the others who hold the post step aside for the test (so the G-Man comes to this one)
local benched = {}
for _, p in ipairs(player.GetAll()) do if p:GetNW2String("lcf_faction", "") == "admin" then benched[#benched + 1] = p p:SetNW2String("lcf_faction", "citizen") end end
-- the chaos: red fills it, green drains it
LC.Chaos = 0
LC.ChaosStep("red", 60 * 150)
ok(math.abs(LC.Chaos - 0.5) < 0.01, "two and a half hours of red: the city is halfway to collapse (an hour of red adds 20%, since 14 November)", LC.Chaos)
LC.ChaosStep("yellow", 60 * 60)
ok(LC.Chaos > 0.5 and LC.Chaos < 0.53, "an hour of yellow barely moves it (5% of a quarter of red's pace, since 14 November)", LC.Chaos)
LC.ChaosStep("green", 60 * 30)
ok(LC.Chaos == 0, "and green drains it", LC.Chaos)
ok(not LC.SetSocio(nil, "black"), "nobody can set BLACK by hand: it's only reached")
-- step down
local adm = newPlayer("CollapseAdmin", "admin")
ok(LC.CollapseBegin("test") and LC.CollapseStage() == "offer" and GetGlobal2Bool("lc_collapse", false) and LC.Socio == "red", "the city collapses: BLACK, red underneath")
ok(CS.offeredTo == adm, "the G-Man comes to the sitting Administrator")
ok(adm.frozen == true, "he stands in front of them, and they can't walk away while he talks")
net.sent = {}
_run(10)
local inPerson = false
for _, m in ipairs(net.sent) do if m.name == "lc_collapse_gman" and m.to == adm then inPerson = true end end
ok(inPerson and adm.frozen == false, "in person, saying his lines; then they can move")
ok(LC.CollapseGmanWords("arrive") == "Is it really that time again?" and LC.CollapseGmanWords("refused") == "Not for long...", "his words are his clips' words (Half-Life 2's own where they fit)")
local offered = false
for _, m in ipairs(net.sent) do if m.name == "lc_collapse_offer" and m.to == adm then offered = true end end
ok(offered, "and puts his offer to them on screen")
ok(LC.CollapseAnswer(adm, "resign") and LC.CollapseStage() == nil and adm:GetNW2String("lcf_faction", "") == "citizen", "step down: a citizen again, and the collapse is over")
ok(not GetGlobal2Bool("lc_collapse", false) and LC.Chaos == 0, "the city calms (chaos gone)")
ok(not LC.CollapseAllowed(), "and not again for a while (lc_black_cooldown_hours)")
-- refuse: his steps, then the last stand
CS.cooldownUntil = 0
local adm2 = newPlayer("CollapseAdmin2", "admin")
local reb = newPlayer("CollapseRebel", "resistance", nil, 900)
local cop = newPlayer("CollapseCop", "cp")
reb:SetPos(Vector(9000, 9000, 0)) cop:SetPos(Vector(-9000, 9000, 0))
LC.CollapseBegin("test")
local gm = LC.CollapseGmanEnt()
ok(IsValid(gm) and gm:GetClass() == "lc_gman" and gm.lcFor == adm2 and gm:GetNW2Entity("lc_for") == adm2, "the G-Man is really there, in front of the Administrator, for them alone")
if gm.OnTakeDamage then gm:OnTakeDamage(_dmg(reb, 5000)) end
ok(IsValid(gm) and not gm.lcLeaveAt, "and nothing hurts him")
_run(10.5)
ok(LC.CollapseAnswer(adm2, "walkaway") and CS.walkAwayUntil and adm2:GetNW2Float("lc_gman_back_by", 0) > CurTime(), "shutting his window is walking away: \"Get back here...\", and 10 seconds to come back")
ok(LC.CollapseGmanUsed(adm2) and CS.walkAwayUntil == nil and adm2:GetNW2Float("lc_gman_back_by", 0) == 0, "E on him: back to his offer")
adm2:SetPos(gm:GetPos() + Vector(600, 0, 0))
LC.CollapseGmanTick(CurTime())
ok(CS.walkAwayUntil ~= nil, "walking off from him starts the 10 seconds too")
LC.CollapseGmanTick(CS.walkAwayUntil + 0.1)
ok(LC.CollapseStage() == "refused" and gm.lcLeaveAt ~= nil, "not back in time: a refusal, and he walks off")
adm2:SetPos(Vector(0, 0, 0))
LC.CollapseNext()
ok(CS.phase == 1, "his first step: crates about the city")
LC.CollapseNext()
local w = LC.CollapseGift(reb)
ok(w and reb:HasWeapon(w), "his second: people wake with weapons in their hands", w)
ok(not LC.CollapseGift(reb) and not LC.CollapseGift(cop), "once each, and never Civil Protection")
LC.CollapseNext()
ok(CS.forcedDark == true, "his third: the grid fails")
LC.CollapseNext()
ok(LC.CollapseStage() == "stand" and CS.boss == adm2 and adm2:Health() == 600, "his fourth: her last stand, in her office, 600 health", adm2:Health())
local guards = 0
for npc, st in pairs(LC.NPCs) do if IsValid(npc) and st.collapseGuard then guards = guards + 1 end end
ok(guards == 4, "four Overwatch Elites guard her", guards)
ok(GetGlobal2Entity("lc_collapse_boss") == adm2, "everyone's screen knows who she is")
-- her shield, and the transformer powering it (the owner, 10 November)
local pw = CS.power
ok(IsValid(pw) and pw:GetClass() == "lc_adminpower" and pw.lcCollapseTemp, "no transformer placed: the G-Man brings one beside her")
ok(GetGlobal2Entity("lc_collapse_power") == pw and LC.CollapseShieldUp(), "her shield is up while it stands (and everyone's screen knows where it is)")
local ShieldHook = hook.t.EntityTakeDamage.LivingCityCollapseShield
local d0 = _dmg(reb, 100)
ShieldHook(adm2, d0)
ok(d0:GetDamage() == 0 and adm2:Health() == 600, "her shield deflects every bullet", d0:GetDamage())
local fdmg = _dmg(cop, 50)
ShieldHook(adm2, fdmg)
ok(fdmg:GetDamage() == 0, "and Civil Protection can't hurt her")
local full = pw.lcPowerHP
LC.CollapsePowerHit(pw, _dmg(cop, 500))
ok(pw.lcPowerHP == full, "nor her transformer")
LC.CollapsePowerHit(pw, _dmg(reb, 350))
ok(pw:GetNW2Int("lc_power_smoke", 0) == 1 and math.abs(pw:GetNW2Float("lc_power_frac", 1) - 0.72) < 0.01, "shot: past three quarters, it smokes (1250, 350 off)", pw:GetNW2Float("lc_power_frac", 1))
LC.CollapsePowerHit(pw, _dmg(reb, 300))
ok(pw:GetNW2Int("lc_power_smoke", 0) == 2, "past half: smoke and sparks (and a small blast as it passed half)")
ok(LC.CollapseShieldUp(), "still standing: her shield still holds")
LC.CollapsePowerHit(pw, _dmg(reb, 5000))
ok(pw:GetNW2Bool("lc_power_down", false) and not LC.CollapseShieldUp(), "destroyed: her shield is down")
local d4 = _dmg(reb, 50)
ShieldHook(adm2, d4)
ok(d4:GetDamage() == 50, "now the bullets reach her", d4:GetDamage())
-- the heroes
local unit = LC.SpawnCop(Vector(9100, 9000, 4))
hook.Run("OnNPCKilled", unit, reb) hook.Run("OnNPCKilled", unit, reb)
ok(LC.HeroPick() == reb, "the hero's first pick: the rebellion's best killer of units")
ok(LC.HeroBegin("barney") == reb and reb.lcHero == "barney", "Barney: played by them")
_run(1.2)
ok(reb:GetNW2String("lc_char", "") == "Barney Calhoun" and reb:HasWeapon("weapon_ar2"), "named and armed as Barney")
local HeroDamage = hook.t.EntityTakeDamage.LivingCityCollapseHeroDamage
local d1 = _dmg(cop, 100)
HeroDamage(reb, d1)
ok(d1:GetDamage() == 50, "Barney takes half the damage", d1:GetDamage())
LC.HeroBegin("freeman", reb)
_run(1.2)
ok(reb.lcHero == "freeman" and reb:HasWeapon("weapon_rpg") and reb:GetNW2String("lc_char", "") == "Gordon Freeman", "then Gordon Freeman: the whole Half-Life 2 arsenal")
local d2 = _dmg(cop, 100)
HeroDamage(reb, d2)
ok(d2:GetDamage() == 20, "Freeman takes a fifth", d2:GetDamage())
local d3 = _dmg(reb, 10)
HeroDamage(cop, d3)
ok(d3:GetDamage() == 20, "and deals twice the damage", d3:GetDamage())
-- she falls
local credits = LC.Credits(reb)
adm2.alive = false
hook.Run("PlayerDeath", adm2, reb, reb)
_run(0.5)
ok(LC.CollapseStage() == nil and adm2:GetNW2String("lcf_faction", "") == "citizen", "she falls: the collapse is over, the office empty")
ok(LC.Credits(reb) == credits + 200, "everyone of the rebellion who was there is paid (lc_black_reward)", LC.Credits(reb) - credits)
ok(reb.lcHero == nil and reb:GetNW2String("lc_char", "") ~= "Gordon Freeman" and not reb:HasWeapon("weapon_rpg"), "and the hero is themselves again")
adm2.alive = true
-- the city's own Administrator: she refuses, and stands in person
CS.cooldownUntil = 0
local placed = ents.Create("lc_adminpower")
placed:SetPos(Vector(-60000, -60000, 0)) placed:Spawn()
local okS = LC.CollapseTest("stand")
ok(okS and IsValid(CS.boss) and CS.boss.lcCollapseBoss, "no player as the Administrator: the city's own stands in her office")
ok(CS.floatZ and math.abs(CS.floatZ - CS.office.z - 48) < 0.01 and CS.boss:GetPos().z > CS.office.z + 30, "she floats in her bubble (48 units up under a high ceiling)", CS.floatZ and (CS.floatZ - CS.office.z))
do
    local tl = util.TraceLine
    util.TraceLine = function(q) if q.endpos.z > q.start.z then return { Hit = true, HitPos = q.start + Vector(0, 0, 80), Fraction = 0.2 } end return tl(q) end
    ok(LC.CollapseFloatHeight(Vector(0, 0, 0)) == 8, "and lower under a low ceiling (never into it)", LC.CollapseFloatHeight(Vector(0, 0, 0)))
    util.TraceLine = tl
end
local squad = LC.CollapseSquad()
local sq = 0
for npc, st in pairs(LC.NPCs) do if IsValid(npc) and st.collapseSquad then sq = sq + 1 end end
local led = false
for npc, st in pairs(LC.NPCs) do if IsValid(npc) and st.collapseSquad and st.elite then led = true end end
ok(squad == 4 and sq >= 4 and led, "an Overwatch squad comes in from outside the fight (4 soldiers, an Elite leading)", squad)
local gapNow = LC.CollapseSquadGap(LC.CollapseRebelCount(true))
ok(CS.nextSquad and CS.nextSquad - CurTime() >= gapNow * 0.89 and CS.nextSquad - CurTime() <= gapNow * 1.11, "and the next in its time", CS.nextSquad and (CS.nextSquad - CurTime()))
ok(LC.CollapseSquadGap(1) == 100 and LC.CollapseSquadGap(20) == 15 and math.abs(LC.CollapseSquadGap(11) - 57.5) < 0.01, "squads every 100 seconds with 1 or 2 attacking her, every 15 with 20, in between in between")
ok(LC.CollapseScale(8, 100, 2) == 8 and LC.CollapseScale(8, 100, 20) == 100 and LC.CollapseScale(4, 25, 20) == 25 and LC.CollapseScale(8, 100, 40) == 100, "manhacks 8 to 100 and turrets 4 to 25 with the Resistance's numbers")
ok(CS.power == placed and CS.boss:GetPos():Distance(placed:GetPos()) < 400, "the fight is where her transformer is", tostring(CS.boss:GetPos()))
CS.boss:SetPos(Vector(-60000, -40000, 0))
ok(not LC.CollapseShieldUp(), "out of its reach (100 feet), her shield doesn't hold")
LC.CollapseTest("off")
-- the map's own desk, even a static prop (the owner, 10 November): read from the map file's static props
do
    local ffi = require("ffi")
    local function I32(n) n = n % 4294967296 return string.char(n % 256, math.floor(n / 256) % 256, math.floor(n / 65536) % 256, math.floor(n / 16777216) % 256) end
    local function I16(n) n = n % 65536 return string.char(n % 256, math.floor(n / 256)) end
    local function F32(x) local b = ffi.new("float[1]", x) return ffi.string(b, 4) end
    local function Name(n) return n .. string.rep("\0", 128 - #n) end
    local function Prop(x, y, z, mi) return F32(x) .. F32(y) .. F32(z) .. F32(0) .. F32(90) .. F32(0) .. I16(mi) .. string.rep("\0", 64 - 26) end
    -- the static props: two models, three props (a chair, Breen's desk near the transformer, a desk far away)
    local sprp = I32(2) .. Name("models/props_c17/chair02a.mdl") .. Name("models/props_combine/breenDesk.mdl") .. I32(1) .. I16(0) .. I32(3)
        .. Prop(-60100, -60000, 0, 0) .. Prop(-60300, -60000, 0, 1) .. Prop(10000, 10000, 0, 1)
    local headerLen = 8 + 64 * 16
    local glumpOfs = headerLen
    local glump = I32(1) .. I32(1936749168) .. I16(0) .. I16(10) .. I32(glumpOfs + 4 + 16) .. I32(#sprp)
    local lumps = {}
    for i = 0, 63 do lumps[#lumps + 1] = (i == 35) and (I32(glumpOfs) .. I32(#glump + #sprp) .. I32(0) .. I32(0)) or string.rep("\0", 16) end
    _files["maps/rp_test.bsp"] = "VBSP" .. I32(20) .. table.concat(lumps) .. glump .. sprp
    local props = LC.ReadStaticProps("maps/rp_test.bsp")
    ok(#props == 3 and props[2].model == "models/props_combine/breendesk.mdl" and math.abs(props[2].pos.x + 60300) < 0.01, "the map file's static props are read: models and places", #props)
    local desks = LC.DesksNear(Vector(-60000, -60000, 0), 1280)
    ok(#desks == 1 and string.find(desks[1].model, "breendesk", 1, true), "a desk within 100 feet of her transformer is found (not the chair, not the far one)", #desks)
    local power2 = ents.Create("lc_adminpower")
    power2:SetPos(Vector(-60000, -60000, 0)) power2:Spawn()
    LC.CollapseTest("stand")
    local at = IsValid(CS.boss) and CS.boss:GetPos()
    ok(at and CS.deskFrom and string.find(CS.deskFrom, "breendesk", 1, true) and at:Distance(Vector(-60300, -60000, 0)) < 110, "she makes her stand beside the map's own desk", tostring(at))
    LC.CollapseTest("off")
    power2:Remove()
    _files["maps/rp_test.bsp"] = nil
end
-- 2 or 3 transformers, each guarded by its number, each behind glass (the owner, 10 November)
do
    local t1, t2 = ents.Create("lc_adminpower"), ents.Create("lc_adminpower")
    t1:SetPos(Vector(-70000, -70000, 0)) t1:SetAngles(Angle(0, 90, 0)) t1:Spawn() t1.lcFixturePoint = { group = 1 }
    t2:SetPos(Vector(-70400, -70000, 0)) t2:Spawn() t2.lcFixturePoint = { group = 2 }
    placed.lcCollapseTemp = true -- (the earlier test's transformer set aside: just these two)
    local gp = LC.AdminGlassSpot(t1)
    ok(gp.y > t1:GetPos().y + 20 and math.abs(gp.x - t1:GetPos().x) < 1, "its glass screen stands on the side that faced whoever placed it", tostring(gp))
    CS.cooldownUntil = 0
    LC.CollapseTest("stand")
    ok(#(CS.powers or {}) == 2, "both transformers power her shield", #(CS.powers or {}))
    local hacks, turrets = 0, 0
    for _, e in ipairs(CS.npcs) do
        if IsValid(e) and e.lcCollapseGuardOf == t1 and e:GetClass() == "npc_manhack" then hacks = hacks + 1 end
        if IsValid(e) and e.lcCollapseGuardOf == t2 and e:GetClass() == "npc_turret_floor" then turrets = turrets + 1 end
    end
    local rb = CS.rebelsAtStart or 0
    local wantPanels = math.min(12, 4 + math.max(0, math.floor((rb - 8) / 2)))
    ok(hacks == LC.CollapseScale(8, 100, rb) and turrets == LC.CollapseScale(4, 25, rb) and #(CS.loose or {}) == wantPanels, "#1 a manhack swarm, #2 floor turrets, and shield panels round her office, by the Resistance's numbers", hacks .. " " .. turrets .. " " .. #(CS.loose or {}) .. " (" .. rb .. " Resistance)")
    local panel = CS.loose and CS.loose[1]
    ok(panel and panel:GetPos().z > CS.office.z + 20, "the panels fall out of the ceiling, not lying about her office", panel and tostring(panel:GetPos()))
    local tur, hk
    for _, e in ipairs(CS.npcs) do if IsValid(e) and e:GetClass() == "npc_turret_floor" then tur = e end end
    for _, e in ipairs(CS.npcs) do if IsValid(e) and e:GetClass() == "npc_manhack" then hk = e end end
    local friendly = _dmg(tur, 30)
    hook.t.EntityTakeDamage.LivingCityCollapseGuards(hk, friendly)
    ok(friendly:GetDamage() == 0, "the turrets don't shoot down the manhacks")
    local hack
    for _, e in ipairs(CS.npcs) do if IsValid(e) and e:GetClass() == "npc_manhack" then hack = e end end
    LC.CollapsePowerHit(t1, _dmg(hack, 500))
    ok(t1:GetNW2Float("lc_power_frac", 1) == 1, "her guards can't harm a transformer")
    CS.boss:SetPos(Vector(-70100, -70000, 0))
    LC.CollapsePowerHit(t1, _dmg(reb, 5000))
    ok(t1:GetNW2Bool("lc_power_down", false) and LC.CollapseShieldUp(), "one destroyed: the other still holds her shield")
    LC.CollapsePowerHit(t2, _dmg(reb, 5000))
    ok(not LC.CollapseShieldUp(), "all destroyed: her shield is down")
    LC.CollapseTest("off")
    ok(not t1:GetNW2Bool("lc_power_down", false) and not t2:GetNW2Bool("lc_power_down", false), "afterwards both stand ready again")
    t1:Remove() t2:Remove()
    placed.lcCollapseTemp = nil
end
-- in BLACK: a mandatory curfew, and the Nexus's suppression device (the owner, 10 November)
do
    CS.cooldownUntil = 0
    LC.CollapseTest("black")
    ok(LC.Event == "curfew", "BLACK puts a mandatory curfew in force", tostring(LC.Event))
    local zk, tl = LC.ZonesOfKind, util.TraceLine
    LC.ZonesOfKind = function(k) if k == "combine" then return { { kind = "combine", pos = Vector(-80000, -80000, 0), r = 300 } } end return zk(k) end
    local sky = true
    util.TraceLine = function(q) if q.endpos.z > q.start.z + 1000 then return { Hit = true, HitSky = sky, HitPos = q.endpos, Fraction = 1 } end return tl(q) end
    reb:SetPos(Vector(-79000, -80000, 0)) reb.alive = true
    local seen = false
    for _, e in ipairs(LC.SuppressorTargets()) do if e == reb then seen = true end end
    ok(seen, "a rebel under open sky near a Combine zone is a target")
    sky = false
    seen = false
    for _, e in ipairs(LC.SuppressorTargets()) do if e == reb then seen = true end end
    ok(not seen, "under a roof, they're not")
    sky = true
    net.sent = {}
    ok(LC.SuppressorFire(reb) and not LC.SuppressorFire(reb), "it fires one shell at a time")
    ok(_lastnet("lc_suppressor") ~= nil, "everyone sees its ring fade in on the ground")
    CS.shell.at = CurTime()
    LC.SuppressorTick(CurTime() + 0.01)
    ok(CS.shell == nil and CS.nextShell and CS.nextShell > CurTime(), "it lands, and the next waits its turn")
    -- the device itself, on the map: blow it up and the shelling stops
    local dev = ents.Create("lc_suppressor")
    dev:SetPos(Vector(-80500, -80000, 0)) dev:Spawn()
    LC.SuppressorsArm(true)
    ok(LC.SuppressorSource() == dev, "with a suppression device placed, the shells come from it")
    LC.SuppressorHit(dev, _dmg(cop, 5000))
    ok(not dev:GetNW2Bool("lc_power_down", false), "Civil Protection can't harm it")
    LC.SuppressorHit(dev, _dmg(reb, 450))
    ok(dev:GetNW2Int("lc_power_smoke", 0) == 2, "shot up, it smokes and sparks (800, 450 off)")
    LC.SuppressorHit(dev, _dmg(reb, 5000))
    ok(dev:GetNW2Bool("lc_power_down", false) and LC.SuppressorSource() == false and not LC.SuppressorFire(reb), "blown up: no more shells")
    ok(table.HasValue(LC.AnnounceTriggers, "socio_black") and table.HasValue(LC.AnnounceTriggers, "black_stand") and table.HasValue(LC.AnnounceTriggers, "suppressor_down"), "the collapse has its own announcements, in either voice")
    LC.ZonesOfKind, util.TraceLine = zk, tl
    LC.CollapseTest("off")
    ok(LC.Event ~= "curfew", "and the curfew lifts with BLACK", tostring(LC.Event))
    ok(not dev:GetNW2Bool("lc_power_down", false), "afterwards the device is whole again")
    dev:Remove()
end
CS.cooldownUntil = 0
LC.CollapseTest("stand")
local ownBoss = CS.boss
-- time runs out with no heroes: Overwatch crushes it
_setcvar("lc_black_heroes", 0)
CS.standUntil = CurTime()
LC.CollapseStandTick(CurTime() + 1)
ok(LC.CollapseStage() == nil and math.abs(LC.Chaos - 0.5) < 0.01, "time runs out: the uprising is crushed, chaos halved")
_setcvar("lc_black_heroes", 1)
LC.CollapseTest("off")
ok(IsValid(placed) and not placed:GetNW2Bool("lc_power_down", false), "afterwards her transformer stands ready again")
placed:Remove()
LC.Chaos = 0
for _, p in ipairs(benched) do p:SetNW2String("lcf_faction", "admin") end
end
CollapseTests()

function TeamChatTests()
section("Team chat (U) and no Half-Life 2 Overwatch voice (the owner, 9 November)")
local tcCop, tcOta = newPlayer("TCCop", "cp"), newPlayer("TCAdmin", "admin")
local tcReb, tcVort, tcCit = newPlayer("TCRebel", "resistance", nil, 900), newPlayer("TCVort", "vort"), newPlayer("TCCitizen", "citizen")
local function sees(listener, speaker, team) return hook.Run("PlayerCanSeePlayersChat", "hi", team, listener, speaker) end
ok(sees(tcOta, tcCop, true) == true, "team chat: Civil Protection and the Administrator read each other")
ok(sees(tcReb, tcCop, true) == false and sees(tcCit, tcCop, true) == false, "and nobody else on the server does")
ok(sees(tcVort, tcReb, true) == true, "free vortigaunts and the Resistance are one side")
ok(sees(tcReb, tcCop, false) == nil, "ordinary chat is left as it was")
ok(LC.StockVoice("npc/overwatch/cityvoice/f_protectionresponse_1_spkr.wav") == "", "Half-Life 2's own Overwatch line: not said (the banner and words only)")
ok(LC.StockVoice("livingcity/overwatch/curfew1.wav") == "livingcity/overwatch/curfew1.wav", "the owner's own recordings still play")
_setcvar("lc_announce_stock", 1)
ok(LC.StockVoice("npc/overwatch/cityvoice/f_protectionresponse_1_spkr.wav") ~= "", "with lc_announce_stock 1, Half-Life 2's lines come back")
_setcvar("lc_announce_stock", 0)
net.sent = {}
LC.Announce("response", "npc/overwatch/cityvoice/f_protectionresponse_1_spkr.wav", "Test")
local sentPath
for _, m in ipairs(net.sent) do if m.name == "lc_announce" then sentPath = m.data[1] end end
ok(sentPath == "", "an announcement with no recording of the owner's goes out silent", tostring(sentPath))
end
TeamChatTests()

function FeedbackTests()
section("Bug reports and feedback from players (the owner, 14 November)")
local fb = newPlayer("FBPlayer", "citizen")
local name = LC.Feedback(fb, "  The bin wouldn't empty.  ")
local saved = name and file.Read(name) or ""
ok(name ~= nil and string.find(name, "livingcity/feedback/", 1, true) == 1, "a report is saved in data/livingcity/feedback/", tostring(name))
ok(string.find(saved, "The bin wouldn't empty.", 1, true) ~= nil and string.find(saved, "FBPlayer", 1, true) ~= nil, "with their words and who sent it")
ok(string.find(saved, "MISCOUNT DEBUG REPORT", 1, true) ~= nil, "and a debug report in the same file")
local again, why, secs = LC.Feedback(fb, "And another thing.")
ok(again == nil and why == "wait" and secs > 0 and secs <= 60, "a second one straight away is refused: one a minute", tostring(why))
local other = newPlayer("FBOther", "citizen")
ok(LC.Feedback(other, "Mine, a second report.") ~= nil, "someone else's is not held up by it")
ok(LC.Feedback(other, "   ") == nil, "an empty one is nothing")
ok(LC.Feedback(other, "ok") == nil and LC.Feedback(other, "!!!!!!!!!!!!!!!!!!") == nil and LC.Feedback(other, 42) == nil and LC.Feedback(other, { "x" }) == nil,
    "nor is one too short, all punctuation, or not text at all")
ok(LC.FeedbackClean("line one\n\nMISCOUNT DEBUG REPORT\r\n\tfake   one\0") == "line one MISCOUNT DEBUG REPORT fake one", "line breaks and control characters become single spaces: it stays one line")
ok(LC.FeedbackClean(string.rep("x", 9000)) == nil, "something far too big is thrown away whole")
do
    local adm = newPlayer("FBAdmin", "citizen")
    adm.IsAdmin = function() return true end
    local got = {}
    local notice = LC.Notice
    LC.Notice = function(p, kind, title, text) got[#got + 1] = { p, title, text } end
    local okN = LC.Feedback(newPlayer("FBTeller", "citizen"), "The cart rolled through the wall.")
    LC.Notice = notice
    local mine, teller = nil, false
    for _, n in ipairs(got) do if n[1] == adm then mine = n end if n[1]:Nick() == "FBTeller" then teller = true end end
    ok(okN ~= nil and mine and not teller and string.find(mine[2], "FBTeller", 1, true) ~= nil and string.find(mine[3], "The cart", 1, true) ~= nil,
        "an admin who is on is told a report came in, and from whom", tostring(#got))
end
_run(61)
ok(LC.Feedback(fb, "And another thing.") ~= nil, "a minute later they can send another")
local long = file.Read(LC.Feedback(newPlayer("FBLong", "citizen"), string.rep("x", 5000)))
ok(string.find(long, string.rep("x", 1000), 1, true) ~= nil and string.find(long, string.rep("x", 1001), 1, true) == nil, "a very long one is cut to 1000 letters")
end
FeedbackTests()

function ErrorsFileTests()
section("Every error in one file: grouped, counted, kept over restarts (the owner, 14 November)")
local keepErr = LC.Err
LC.Err = { list = {}, by = {}, since = os.time(), boots = 1, lost = 0, loaded = true }
local function entry(part)
    for _, e in ipairs(LC.Err.list) do if string.find(e.msg, part, 1, true) then return e end end
end
-- LC.Try is pcall
local a, b, c = LC.Try(function(x) return x, "two" end, 1)
ok(a == true and b == 1 and c == "two", "LC.Try gives back what pcall gives: true and every value")
local function boom() error("boom-swallowed") end
local bad, why = LC.Try(boom)
ok(bad == false and string.find(tostring(why), "boom-swallowed", 1, true) ~= nil, "and false with the error when it fails")
local sw = entry("boom-swallowed")
ok(sw ~= nil and sw.realm == "hidden" and sw.n == 1, "an error a protected call swallowed is written down", sw and sw.realm)
ok(sw ~= nil and string.find(tostring(sw.where), "tests.lua", 1, true) ~= nil, "with the line that made the call", sw and tostring(sw.where))
for _ = 1, 4 do LC.Try(boom) end
ok(#LC.Err.list == 1 and sw.n == 5, "the same one again is counted, not listed again", #LC.Err.list .. " / " .. tostring(sw and sw.n))
ok(select("#", LC.Try(nil)) == 2 and LC.Try(nil) == false, "calling nothing fails as pcall does, without an error of its own")
local objOk, obj = LC.Try(function() error({ code = 7 }) end)
ok(objOk == false and istable(obj) and obj.code == 7, "an error that isn't text comes back untouched")
-- reported by the code that caught it: the same entry, named
LC.Err.list, LC.Err.by = {}, {}
local _, err2 = LC.Try(function() error("boom-reported") end)
local before = #_errors
LC.Error("the test's job", err2)
local rep = entry("boom-reported")
ok(#LC.Err.list == 1 and rep.n == 1 and rep.told == true and rep.where ~= nil, "an error caught and then reported is one entry, counted once", #LC.Err.list .. " / " .. tostring(rep and rep.n))
ok(#_errors == before + 1, "LC.Error still tells the console, as before")
_errors[#_errors] = nil
LC.Error("somewhere else", "a plain complaint")
ok(entry("a plain complaint") ~= nil and entry("a plain complaint").realm == "caught", "what the code reports by itself is listed too")
_errors[#_errors] = nil
-- the game's own errors
LC.Err.list, LC.Err.by = {}, {}
hook.Run("OnLuaError", "gamemodes/livingcity/gamemode/modules/server/sv_x.lua:12: attempt to index a nil value", "server",
    { { File = "gamemodes/livingcity/gamemode/modules/server/sv_x.lua", Line = 12, Function = "Poll" }, { File = "lua/includes/modules/timer.lua", Line = 3, Function = "" } }, "Miscount")
local se = entry("attempt to index a nil value")
ok(se ~= nil and se.realm == "server" and string.find(se.stack, "sv_x.lua:12 in Poll", 1, true) ~= nil and string.find(se.stack, "timer.lua:3", 1, true) ~= nil,
    "a Lua error on the server is kept with its whole trace", se and se.stack)
hook.Run("OnLuaError", "lua/includes/extensions/net.lua:32: bad argument #1 to 'WriteString'", "server",
    { { File = "lua/includes/extensions/net.lua", Line = 32, Function = "WriteString" }, { File = "gamemodes/livingcity/gamemode/modules/server/sv_y.lua", Line = 80, Function = "Send" } }, "")
ok(entry("bad argument #1") ~= nil, "one raised in the game's own files is kept when the gamemode's code is further down the trace")
hook.Run("OnLuaError", "addons/other/lua/autorun/thing.lua:5: nope", "server", { { File = "addons/other/lua/autorun/thing.lua", Line = 5, Function = "f" } }, "other")
ok(entry("nope") == nil, "another addon's error is not ours to keep")
LC.ErrorNote("server", "Entity [41][npc_citizen] has no brain at 0x1f00ab")
LC.ErrorNote("server", "Entity [97][npc_citizen] has no brain at 0x2a11cd")
ok(entry("has no brain").n == 2, "the same error about another entity or address is the same error")
-- players' games
local e1, e2, e3 = newPlayer("ErrOne", "citizen"), newPlayer("ErrTwo", "citizen"), newPlayer("ErrThree", "citizen")
_netcall("lc_clerror", e1, "client", "gamemodes/livingcity/gamemode/modules/client/cl_x.lua:9: hud broke\ncl_x.lua:9 in Paint", 3)
local ce = entry("hud broke")
ok(ce ~= nil and ce.realm == "client" and ce.n == 3 and ce.players == 1 and string.find(ce.stack, "in Paint", 1, true) ~= nil, "a player's game sends its errors, with how many times", ce and (ce.n .. " / " .. tostring(ce.players)))
_netcall("lc_clerror", e1, "client", "gamemodes/livingcity/gamemode/modules/client/cl_x.lua:9: hud broke\ncl_x.lua:9 in Paint", 50)
ok(ce.n == 3, "one message every two seconds from a player, no more")
_netcall("lc_clerror", e2, "client", "gamemodes/livingcity/gamemode/modules/client/cl_x.lua:9: hud broke\ncl_x.lua:9 in Paint", 1)
ok(ce.n == 4 and ce.players == 2, "the same error on a second player's game: one entry, two players", ce.n .. " / " .. tostring(ce.players))
_netcall("lc_clerror", e3, "client", "addons/other/thing.lua:1: not ours", 1)
ok(entry("not ours") == nil, "a player's error from another addon is left out")
_run(3)
_netcall("lc_clerror", e3, "hidden", "cl_y.lua:4: swallowed over there\ncl_y.lua:20", 2)
ok(entry("swallowed over there") ~= nil and entry("swallowed over there").realm == "client hidden", "and what a protected call swallowed on a player's game")
-- the file
_files["livingcity/errors.txt"], _files["livingcity/errors.json"] = nil, nil
_run(11)
local txt = _files["livingcity/errors.txt"] or ""
ok(string.find(txt, "MISCOUNT ERRORS", 1, true) == 1 and string.find(txt, "hud broke", 1, true) ~= nil and string.find(txt, "at cl_x.lua:9 in Paint", 1, true) ~= nil,
    "a new error is in data/livingcity/errors.txt within ten seconds", string.sub(txt, 1, 80))
ok(string.find(txt, "a player's game (2 players)", 1, true) ~= nil and string.find(txt, "#1  4 times", 1, true) ~= nil, "the most frequent first, with whose game and how many players")
ok(_files["livingcity/errors.json"] ~= nil, "and kept in errors.json for the next start")
local wrote = _files["livingcity/errors.txt"]
ce.n, LC.Err.dirty = ce.n + 1, true
_files["livingcity/errors.txt"] = nil
_run(30)
ok(_files["livingcity/errors.txt"] == nil, "a count going up is not written every ten seconds")
_run(100)
ok(_files["livingcity/errors.txt"] ~= nil and _files["livingcity/errors.txt"] ~= wrote, "it is written within two minutes")
LC.Err.dirty = true
_files["livingcity/errors.txt"] = nil
hook.Run("ShutDown")
ok(_files["livingcity/errors.txt"] ~= nil, "and when the server shuts down")
-- a restart
local had = #LC.Err.list
LC.Err = { list = {}, by = {}, since = os.time(), boots = 0, lost = 0, loaded = true }
LC.ErrorsLoad()
ok(#LC.Err.list == had and entry("hud broke") ~= nil and entry("hud broke").n == 5 and entry("hud broke").boot == 0, "after a restart the list is read back, counts kept", #LC.Err.list .. " of " .. had)
LC.ErrorNote("client", "gamemodes/livingcity/gamemode/modules/client/cl_x.lua:9: hud broke")
ok(#LC.Err.list == had and entry("hud broke").n == 6 and entry("hud broke").boot == 1, "the same error after the restart adds to it")
local old = util.JSONToTable(_files["livingcity/errors.json"])
old.list[1].last = os.time() - 15 * 86400
local gone = old.list[1].msg
_files["livingcity/errors.json"] = util.TableToJSON(old)
LC.Err = { list = {}, by = {}, since = os.time(), boots = 0, lost = 0, loaded = true }
LC.ErrorsLoad()
ok(#LC.Err.list == had - 1 and entry(gone) == nil, "one not seen for two weeks is forgotten")
-- the menu and the commands
net.sent = {}
local errAdmin = newPlayer("ErrAdmin", "citizen")
errAdmin.admin, errAdmin.superadmin = true, true
concommand.list["lc_errors"](e1)
ok(_lastnet("lc_report") == nil, "someone who is not staff is not shown the list")
concommand.list["lc_errors"](errAdmin)
local shown = _lastnet("lc_report")
ok(shown ~= nil, "an admin is (F4 > Factions > Admin: errors)")
ok(LC.ErrorsCount() == #LC.Err.list and LC.ErrorsCount() > 0, "the button's number is how many different errors there are")
local report = LC.BuildReport()
ok(string.find(report, "Errors, grouped", 1, true) ~= nil and string.find(report, "x client: ", 1, true) ~= nil, "the debug report lists the most frequent")
concommand.list["lc_errors_clear"](e1)
ok(LC.ErrorsCount() > 0, "only a superadmin starts the list again")
concommand.list["lc_errors_clear"](errAdmin)
ok(LC.ErrorsCount() == 0 and string.find(_files["livingcity/errors_previous.txt"] or "", "hud broke", 1, true) ~= nil, "starting again keeps the old list as errors_previous.txt")
ok(string.find(_files["livingcity/errors.txt"] or "", "Nothing has gone wrong.", 1, true) ~= nil, "and the file says nothing has gone wrong")
-- a flood stays small
for i = 1, 260 do LC.ErrorNote("server", "flood number " .. string.rep("z", i)) end
ok(#LC.Err.list == 200 and LC.Err.lost == 60, "200 different errors are kept; the rest are only counted", #LC.Err.list .. " / " .. tostring(LC.Err.lost))
LC.Err.list, LC.Err.by, LC.Err.lost = {}, {}, 0
for i = 1, 80 do LC.Try(function() error("swallowed flood " .. string.rep("y", i)) end) end
ok(#LC.Err.list == 60, "and at most 60 of them swallowed ones, so they can't crowd the others out", #LC.Err.list)
ok(#LC.ErrorsText() > 0 and LC.Try(LC.ErrorsSave) == true, "the full list still writes")
_files["livingcity/errors.txt"], _files["livingcity/errors.json"], _files["livingcity/errors_previous.txt"] = nil, nil, nil
LC.Err = keepErr
end
ErrorsFileTests()

function StockEatTests()
section("The city eats in proportion, and never the last quarter (the owner, 15 November)")
local set = _setcvar -- (through a local: a line starting _setcvar is replayed as a setting for every later section, run_section.py)
local keepOn, keepMax, keepEat = GetConVar("lc_stockpile"):GetInt(), GetConVar("lc_stock_max"):GetInt(), GetConVar("lc_stock_eat"):GetInt()
local keepRunning, keepCounts, keepCarry, keepStock = LC.Running, LC.RoleCounts, LC.StockEatCarry, LC.Stock()
set("lc_stockpile", 1)
set("lc_stock_max", 400)
set("lc_stock_eat", 20)
LC.Running = true
local minute = timer.list["LivingCityStock"].fn
local function hour(citizens)
    LC.RoleCounts = { citizen = citizens }
    LC.StockEatCarry = 0
    local before = LC.Stock()
    for _ = 1, 60 do minute() end
    return before - LC.Stock()
end
LC.StockAdd(300 - LC.Stock())
local three = hour(3)
ok(three == 9, "three citizens out eat nine rations in an hour (it was sixty: one a minute, however few)", three)
LC.StockAdd(300 - LC.Stock())
local twenty = hour(20)
ok(twenty == 60, "twenty eat sixty: a ration a minute for every lc_stock_eat", twenty)
LC.StockAdd(300 - LC.Stock())
ok(hour(0) == 0, "nobody out: nothing is eaten")
LC.StockAdd(300 - LC.Stock())
local fifty = hour(50)
ok(fifty == 150, "fifty eat a hundred and fifty", fifty)
LC.StockAdd(110 - LC.Stock())
local ate = hour(20)
ok(ate == 10 and LC.Stock() == 100 and LC.StockLevel() == "normal", "the city's own eating stops at the quarter line", ate .. " eaten, " .. LC.Stock() .. " left")
ok(hour(80) == 0 and LC.Stock() == 100, "however many are out")
local eater = newPlayer("QuarterEater", "citizen")
eater.lcnRationAt = 0
LC.GiveItem(eater, "ration_card", 5)
ok(LC.UseDispenser(eater, nil) and LC.Stock() == 99 and LC.StockLevel() == "short", "a ration handed out still takes one, under the line", LC.Stock())
ok(hour(20) == 0 and LC.Stock() == 99, "and what is under the line the city leaves alone")
LC.StockAdd(-LC.Stock())
ok(hour(20) == 0 and LC.Stock() == 0, "empty stays empty: nothing below nothing")
eater:SetPos(Vector(-30000, 30000, 0))
LC.Running, LC.RoleCounts, LC.StockEatCarry = keepRunning, keepCounts, keepCarry
LC.StockAdd(keepStock - LC.Stock())
set("lc_stock_max", keepMax)
set("lc_stock_eat", keepEat)
set("lc_stockpile", keepOn)
end
StockEatTests()

function CounterShiftTests()
section("The kitchen's counter shift: checking ration cards, not waiting for the line (the owner, 15 November)")
local set = _setcvar -- (through a local: a line starting _setcvar is replayed as a setting for every later section, run_section.py)
local keepGames = GetConVar("lc_jobgames"):GetInt()
local function counterShift(who)
    for _ = 1, 80 do
        who.lcStoryPostings = nil
        for _, sp in ipairs(LC.StoryPostings(who)) do
            if sp.chain == "shift" and string.find(sp.title, "The counter", 1, true) then return sp end
        end
    end
end
set("lc_jobgames", 0)
local old = newPlayer("CounterOld", "citizen")
LC.SetJob(old, "kitchen", true)
local was = counterShift(old)
ok(was ~= nil and was.stages[3].event == "served", "with lc_jobgames 0 the old shift is kept: it waits for the line", was and tostring(was.stages[3].event))
set("lc_jobgames", 1)
local clerk = newPlayer("CounterClerk", "citizen")
LC.SetJob(clerk, "kitchen", true)
local spec = counterShift(clerk)
ok(spec ~= nil, "the counter shift is still handed out")
ok(spec ~= nil and #spec.stages == 3 and spec.stages[3].kind == "count" and spec.stages[3].event == "game_done", "its last step is a game, not a wait at the counter",
    spec and tostring(spec.stages[3].event))
clerk.lcqNext = 0
LC.AcceptPosting(clerk, spec.id)
local q = LC.QuestOf[clerk]
clerk:SetPos(q.stages[1].pos)
_run(1)
ok(q.stages[q.stage].kind == "choice", "at the counter: the forged card, as before")
clerk.chat = {}
LC.ResolveChoice(clerk, q.id, 2)
local g = LC.JobGames[clerk]
ok(g ~= nil and g.kind == "papers", "then the cards: the papers game starts where they stand", g and g.kind)
ok(g ~= nil and g.title == "Ration cards" and has(clerk.chat, "[Rations] Citizens will walk up to you"), "worded for the counter, not the station", g and g.title)
ok(IsValid(g.current and g.current.npc), "the first citizen steps up")
_run(2)
ok(not q.done and LC.QuestOf[clerk] == q, "nobody in the ration line, and the shift does not wait on one")
LC.JobGameFinishForTest(clerk)
ok(q.done and LC.QuestOf[clerk] == nil, "the cards checked, the shift is done")
-- the station's own papers check is worded as it was
local porter = newPlayer("CounterPorter", "citizen")
porter.chat = {}
LC.JobGameStart(porter, "papers", nil, {})
ok(LC.JobGames[porter].title == "Papers check" and has(porter.chat, "[Station] Travelers will walk up to you"), "the station's papers check reads as before")
LC.JobGameEnd(porter, "quit")
set("lc_jobgames", keepGames)
for _, p in ipairs({ old, clerk, porter }) do if LC.QuestOf[p] then LC.AbandonQuest(p) end p:SetPos(Vector(-30000, 30000, 0)) end
end
CounterShiftTests()

function StoryPrisonerTests()
section("A story that frees a prisoner brings its own when the cells are empty (The Man Inside; the owner, 15 November)")
local unit = newPlayer("InsideUnit", "cp")
-- nobody jailed that the story could take, and no citizen free to arrest
local held = {}
for n, st in pairs(LC.NPCs) do if IsValid(n) and st.state == "jailed" and not st.questLock then st.questLock = held held[n] = st end end
local keepRandom = LC.QB.RandomCitizen
LC.QB.RandomCitizen = function() return nil end
local story = LC.Story(unit)
story.chains.inside = { part = "proof", data = {}, readyAt = 0 }
LC.SaveStory(unit)
unit.lcStoryPostings = nil
local spec
for _, sp in ipairs(LC.StoryPostings(unit)) do if sp.chain == "inside" then spec = sp end end
ok(spec ~= nil and spec.part == "proof", "The Man Inside, part 2, is on the board")
unit.lcqNext = 0
LC.AcceptPosting(unit, spec.id)
local q = LC.QuestOf[unit]
unit.chat = {}
LC.ResolveChoice(unit, q.id, 1)
LC.QB.RandomCitizen = keepRandom
local st = q and q.stages[q.stage]
ok(q ~= nil and not q.done and st.kind == "target" and st.action == "free", "with the cells empty and nobody to arrest, it is not called off", has(unit.chat, "Failed") and "failed" or tostring(st and st.kind))
local who = st and st.npc
local cellNear = false
for _, c in ipairs(LC.PointsOfKind("cell")) do if IsValid(who) and who:GetPos():DistToSqr(c.pos) < 40 * 40 then cellNear = true end end
ok(IsValid(who) and LC.NPCs[who] and LC.NPCs[who].state == "jailed" and cellNear, "a prisoner of the story's own is held in a cell", IsValid(who) and tostring(LC.NPCs[who] and LC.NPCs[who].state))
ok(IsValid(who) and LC.NPCs[who].questLock == q, "and is the job's: nobody lets them out first")
unit:SetPos(who:GetPos() + Vector(40, 0, 0))
LC.NPCs[who].nextUse = 0
hook.Run("PlayerUse", unit, who)
ok(q.stages[q.stage].kind == "escort" and LC.NPCs[who].state ~= "jailed", "E opens the cell, and they follow")
local dest = q.stages[q.stage].pos
who:SetPos(dest)
unit:SetPos(dest + Vector(50, 0, 0))
_run(1.5)
ok(q.done and not IsValid(who), "walked to safety, the part is done and the prisoner is gone")
for n, s2 in pairs(held) do if s2.questLock == held then s2.questLock = nil end end
if LC.QuestOf[unit] then LC.AbandonQuest(unit) end
unit:SetPos(Vector(-30000, 30000, 0))
end
StoryPrisonerTests()

function RobotTests()
section("Robot players: every job on the boards, taken and done the way a player would (the owner, 14 November)")
-- (their own run, from the city as the first 505 lines leave it: python3 _dev/robots.py. Inside the long run
-- the city is whatever the tests before left, and the same job would go differently from one run to the next.)
if not _ROBOTS_ON then return end
local robots = assert(loadstring(_ROBOTSRC, "robots.lua"))()
local rep = robots({ ok = ok, newPlayer = newPlayer, withRoll = withRoll, only = _ROBOT_ONLY, modes = _ROBOT_MODES, budget = _ROBOT_BUDGET })
_ROBOT_REPORT = rep.text
end
RobotTests()


section("The owner's 14 November notes: stores, Civil Protection's toughness, the medic, jobs, water, the vest")
;(function() -- (its own function: the file's main chunk is at Lua's limit on locals)
    local function T(id) for _, x in ipairs(LC.QuestTemplates) do if x.id == id then return x end end end
    -- the stores: an NPC served at a line costs a ration only while rations are handed out
    local was = LC.Event
    LC.StockAdd(200 - LC.Stock())
    LC.Event = nil
    hook.Run("LivingCityServed", nil, 1)
    ok(LC.Stock() == 200, "an NPC served at a line outside a handout takes nothing from the stores", LC.Stock())
    LC.Event = "rations"
    hook.Run("LivingCityServed", nil, 1)
    ok(LC.Stock() == 199, "during a handout it takes one", LC.Stock())
    LC.Event = was
    ok(string.find(LC.StockLedgerLine(), "ration line (handout) -1", 1, true) ~= nil, "and the stores' ledger says where it went", LC.StockLedgerLine())
    -- players' shots at Civil Protection NPCs hit harder; soldiers and NPCs' shots are as before
    local shooter = newPlayer("CPShooter14", "citizen")
    local c, cs = LC.Spawners.cop(Vector(-61000, -61000, 0))
    ok(IsValid(c) and math.abs(LC.CPDamageTakenMul(c, shooter) - 1.5) < 0.001, "a player's shot at a metrocop does half again (about 10 pistol hits)")
    local sol = LC.Spawners.soldier and LC.Spawners.soldier(Vector(-61200, -61000, 0))
    if IsValid(sol) then ok(LC.CPDamageTakenMul(sol, shooter) == 1, "a soldier is as tough as before") end
    ok(LC.CPDamageTakenMul(c, sol or c) == 1, "an NPC's shot at a metrocop is as before")
    if IsValid(c) then c:Remove() end
    if IsValid(sol) then sol:Remove() end
    -- Doctor the records: the Hacker's job only
    local rt = T("res_terminal")
    local reb = newPlayer("NotAHacker14", "resistance")
    ok(rt and not rt.available(reb), "Doctor the records isn't offered to a rebel who isn't a Hacker")
    reb:SetNW2String("lcf_special", "hacker")
    local GamesOn = GetConVar("lc_minigames")
    ok(rt and (rt.available(reb) or (GamesOn and not GamesOn:GetBool())), "but is to a Hacker")
    reb:SetNW2String("lcf_special", "")
    -- the board: fewer jobs, cycled sooner
    ok(LC.BoardPostSecs == 150, "a job stays on the board 150 seconds untaken")
    -- the Union shift is a job of your own, not a story
    local shift
    for _, ch in ipairs(LC.ChainList or {}) do if ch.id == "shift" then shift = ch end end
    ok(shift and shift.flat, "the Union shift is marked as a job of your own (YOUR JOB, not YOUR STORY)")
    -- water: a few feet from it will do
    local pcWas = util.PointContents
    local swimmer = newPlayer("WaterEdge14", "citizen")
    swimmer:SetPos(Vector(-98000, 0, 0))
    util.PointContents = function(p) return p.x < -98060 and (CONTENTS_WATER or 32) or 0 end
    ok(LC.NearWater(swimmer), "water a few feet away counts as near water (to fill a can)")
    util.PointContents = function() return 0 end
    ok(not LC.NearWater(swimmer), "and none is none")
    util.PointContents = pcWas
    -- the medic: a vial or a medkit for credits
    local mp = Vector(-62000, -62000, 0)
    local m, mst = LC.SpawnRebel(mp + Vector(0, 0, 4), nil)
    if IsValid(m) then
        mst.quartermaster, mst.medic = true, true
        local pat = newPlayer("Patient14", "resistance")
        pat:SetPos(mp + Vector(60, 0, 0))
        pat:SetHealth(30)
        LC.AddCredits(pat, 20 - LC.Credits(pat))
        ok(LC.MedicBuy(pat, "kit") and pat:Health() == 70 and LC.Credits(pat) == 12, "the medic's large medkit: 40 health for 8 credits", pat:Health() .. " " .. LC.Credits(pat))
        ok(LC.MedicBuy(pat, "vial") and pat:Health() == 80 and LC.Credits(pat) == 9, "his small health vial: 10 for 3")
        LC.AddCredits(pat, -LC.Credits(pat))
        ok(not LC.MedicBuy(pat, "vial"), "no credits, no care")
        ok(LC.NearQuartermaster(pat) == nil, "the medic isn't taken for the quartermaster")
        m:Remove()
    else
        ok(false, "a medic could be made")
    end
    -- a way out of a manhunt: given at Overwatch response, never posted
    local gg = T("res_goground")
    ok(gg and not gg.available(reb), "Go to ground is never on the board by itself")
    local hunted = newPlayer("Hunted14", "resistance")
    hunted.lcHeat = 0
    ok(not LC.ManhuntWayOut(hunted), "no manhunt, no Go to ground")
    -- the black card before a dream: four lines from what the dream is
    local intro = LC.DreamIntro({ id = "x", name = "X", mood = "nightmare", secs = 180, lives = 3, goal = "Do the thing." })
    ok(intro and intro.idea == "A nightmare." and intro.rules == "Do the thing." and string.find(intro.lose, "all 3 lives", 1, true) and string.find(intro.win, "3 minutes", 1, true),
        "a dream's card: what it is, the rules, to win, to lose", intro and (intro.idea .. " | " .. intro.win .. " | " .. intro.lose))
    local intro2 = LC.DreamIntro({ id = "y", mood = "happy", goal = "g" })
    ok(intro2 and string.find(intro2.lose, "can't be lost", 1, true), "a dream with no lives can't be lost")
    -- a close call: the Resistance wake in their camp, not a Union clinic
    ok(LC.CloseCallWakeSpot(reb, Vector(0, 0, 0)) == nil, "a rebel's close call doesn't wake them in the Union clinic")
    -- what the Resistance's people say: in chat as before, recordable
    local said
    local was2 = reb.ChatPrint
    reb.ChatPrint = function(_, t) said = t end
    LC.ResistanceSay(reb, nil, "on_watch")
    reb.ChatPrint = was2
    ok(said == "[Resistance] 'I'm on watch. Find someone else.'", "a lookout's line still shows in chat", said)
    -- a Hacker splices into a loudspeaker at its utility box; a unit cuts it out
    local sp = ents.Create("lc_loudspeaker")
    if IsValid(sp) then
        sp:SetPos(Vector(-63000, -63000, 200)) sp:Spawn()
        local box = ents.Create("lc_utilitybox")
        box:SetPos(Vector(-63000, -63000, 36)) box:Spawn()
        box.lcSpeaker = sp sp.lcBox = box
        local hk = newPlayer("Hacker14", "resistance")
        hk:SetNW2String("lcf_special", "hacker")
        hk:SetPos(Vector(-63020, -63000, 0))
        ok(LC.UseUtilityBox(hk, box), "a Hacker starts splicing into a loudspeaker at its box")
        _advance(LC.SpeakerHackTask + 1) _runtimers()
        ok(LC.SpeakerHacked(sp), "and it's the Resistance's", sp:GetNW2Float("lc_hacked_until", 0) .. " " .. CurTime())
        local heard = LC.SpeakerHackSay(nil, "Test words.", {})
        ok(#heard >= 1, "the Colonel's words come out of a hacked loudspeaker")
        local u = newPlayer("Cutter14", "cp")
        u:SetPos(Vector(-63020, -63010, 0))
        ok(LC.UseUtilityBox(u, box), "a unit starts cutting the splice out")
        _advance(LC.SpeakerCutTask + 1) _runtimers()
        ok(not LC.SpeakerHacked(sp), "and the loudspeaker is the city's again")
        box:Remove() sp:Remove()
    end
    -- the Extraction job: the fugitive hides in the Combine's city
    local ex = T("res_rescue")
    if ex then
        local spec = ex.build(reb)
        ok(spec == nil or string.find(spec.desc, "Combine's city", 1, true) ~= nil, "Extraction: the fugitive hides in the Combine's city and is brought back")
    end
end)()


section("The owner's 14 November answers: prison guards, the infested, Lamarr, dressed dreams, job boards")
;(function() -- (its own function: the file's main chunk is at Lua's limit on locals)
    local function T(id) for _, x in ipairs(LC.QuestTemplates) do if x.id == id then return x end end end
    -- the prison guard: four jobs, and the fourth done makes them a soldier
    local pg = newPlayer("Guard15", "ota")
    ok(LC.IsPrisonGuard(pg), "an Overwatch recruit starts as a Combine Prison Guard", pg:GetNW2Int("lcf_rank", 0))
    local cop = newPlayer("NotGuard15", "cp")
    local n = 0
    for _, id in ipairs({ "pg_inspect", "pg_question", "pg_break", "pg_riot" }) do if T(id) then n = n + 1 end end
    ok(n == 4, "four prison guard jobs", n)
    ok(not T("pg_riot").available(cop), "a metrocop doesn't get them")
    -- no "stand here" in any of them (the owner, 14 November)
    local standing = 0
    LC.PointsOfKind_was = LC.PointsOfKind
    for _, id in ipairs({ "pg_inspect", "pg_question", "pg_break", "pg_riot" }) do
        local okB, spec = pcall(T(id).build, pg)
        for _, st in ipairs(okB and spec and spec.stages or {}) do if st.kind == "hold" or st.kind == "survive" then standing = standing + 1 end end
    end
    ok(standing == 0, "none of the prison jobs is standing about", standing)
    -- searching by hand: E on a thing in the stage, held, searches it; the hidden one ends it
    do
        local q = { stages = {}, stage = 1, data = {}, ents = {}, members = { pg }, owner = pg, expires = CurTime() + 300, title = "Test search", board = "Directives", id = 99123, narration = {} }
        local a, b = ents.Create("prop_physics"), ents.Create("prop_physics")
        a:Spawn() b:Spawn()
        local st = { kind = "count", need = 2, got = 0, search = { [a] = true, [b] = true }, searched = {}, hidden = b, emptyWords = { "Nothing." } }
        local found = false
        st.foundFn = function() found = true return true end
        q.stages[1] = st
        LC.QuestOf[pg] = q
        ok(hook.t.PlayerUse.LivingCityQuestSearch(pg, a) == false, "E on a thing to search does nothing else for the job holder (the bed, the toilet: off)")
        LC.Searching[pg] = nil
        LC.QuestSearchDone(pg, q, st, a)
        ok(st.searched[a] and not found, "searched: nothing in that one")
        LC.QuestSearchDone(pg, q, st, b)
        ok(found, "the hidden one has it")
        LC.QuestOf[pg] = nil
        a:Remove() b:Remove()
    end
    -- questioning a prisoner who isn't a player: lies and silence until broken, then the truth
    do
        local pr, pst = LC.Spawners.citizen(Vector(-66000, -66000, 4))
        pst = pst or LC.NPCs[pr]
        pst.jailUntil = CurTime() + 600
        LC.OnNPCReachedCell(pr, pst, CurTime())
        pr:SetPos(pg:GetPos() + Vector(40, 0, 0))
        local q = { data = {}, stages = {}, stage = 1, members = { pg }, owner = pg, expires = CurTime() + 300, title = "Test question", board = "Directives", id = 99124, narration = {}, ents = {} }
        ok(LC.NPCInterrogationStart(pg, pr, q), "a guard starts questioning someone held in a cell")
        local s = LC.NPCInterrogations[pg]
        local start = s.resolve
        LC.NPCInterrogationDo(pg, "baton")
        ok(s.resolve == start - 1 and s.hits == 1, "the baton wears them down")
        s.resolve = 0
        LC.NPCInterrogationDo(pg, "ask", 1)
        _advance(2) _runtimers()
        ok(q.data.talked and LC.NPCInterrogations[pg] == nil, "broken, they tell the truth, and that ends it")
        pr:Remove()
    end
    -- the riot: the baton always quiets a prisoner; ordering them may not
    do
        local q = { data = {}, stages = {}, stage = 1, ents = {} }
        local r = ents.Create("npc_citizen") r:Spawn()
        q.stages[1] = { rioters = { [r] = { noise = 50, quiet = false } } }
        LC.QuestOf[pg] = q
        ok(LC.RiotQuiet(pg, r, "baton") and q.stages[1].rioters[r].quiet, "the baton quiets a rioting prisoner")
        LC.QuestOf[pg] = nil
        r:Remove()
    end
    LC.PointsOfKind_was = nil
    -- the lab and the quartermaster (the owner, 14 November): nothing he sells is the lab's
    ok(LC.QuartermasterStocks("gun_pistol") and not LC.QuartermasterStocks("vest_cell"), "the quartermaster stocks pistols, not charge cells")
    local dup = {}
    for _, r in ipairs(LCS.Lab) do if LC.QuartermasterStocks(r.out) then dup[#dup + 1] = r.id end end
    ok(#dup == 0 and LCS.LabById.vest_cell and LCS.LabById.firebomb and LCS.LabById.foil_hat and not LCS.LabById.radio_transmitter,
        "the lab makes only what the quartermaster doesn't sell: charge cells, firebombs, the foil hat", table.concat(dup, ", "))
    do
        local rr = newPlayer("LabBuyer15", "resistance", nil, 400)
        LC.AddCredits(rr, 500)
        local okP, whyP = LC.LabMake(rr, "gun_pistol", "pay")
        ok(not okP, "and won't make a pistol", whyP)
    end
    pg:SetPData("lc_pg_jobs", 0)
    for i = 1, 3 do LC.PrisonGuardJobDone(pg) end
    ok(LC.IsPrisonGuard(pg) and LC.PrisonGuardDone(pg) == 3, "three done: still a guard")
    ok(LC.PrisonGuardJobDone(pg) and not LC.IsPrisonGuard(pg), "the fourth: a Combine Soldier", pg:GetNW2Int("lcf_rank", 0))
    -- the infested: never chosen; turned when not got up; freed by death
    local cit = newPlayer("Turned15", "resistance", nil, 200)
    local okJoin = LC.CanJoinFaction(cit, "zombie", nil)
    ok(not okJoin, "nobody chooses the infestation")
    ok(LC.InfestedAttacker(ents.Create("npc_headcrab")) and not LC.InfestedAttacker(cit), "a headcrab is an infested attacker; a rebel isn't")
    LC.TurnInfested(cit)
    ok(LC.PlayerIsZombie(cit), "turned: one of the infested")
    local before = cit:GetNW2String("lc_char", "")
    cit.alive = false
    hook.Run("PlayerDeath", cit)
    cit.alive = true
    ok(not LC.PlayerIsZombie(cit) and cit:GetNW2String("lc_char", "") ~= before, "killed while infested: the character is dead, no close call (the owner, 14 November)", cit:GetNW2String("lc_char", ""))
    -- Lamarr: on Dr. Kleiner's bench only
    local bench = ents.Create("lc_workbench")
    if IsValid(bench) then
        bench:SetPos(Vector(-64000, -64000, 0)) bench:Spawn()
        local sci = bench.lcScientist
        if not IsValid(sci) then sci = ents.Create("lc_scientist") sci:Spawn() bench.lcScientist = sci end
        ok(IsValid(sci), "the bench has a scientist")
        if IsValid(sci) then
            sci.lcWho = "kleiner"
            local lam = LC.LabLamarr(bench)
            ok(IsValid(lam), "Lamarr sits on Dr. Kleiner's bench")
            if IsValid(lam) then
                sci:SetNW2Float("lc_away_until", CurTime() + 60)
                LC.LamarrSync(lam)
                ok(lam.lcHidden, "she's gone while he's taken away")
                sci:SetNW2Float("lc_away_until", 0)
                LC.LamarrSync(lam)
                ok(not lam.lcHidden, "and back when he is")
            end
            sci.lcWho = "eli"
            ok(LC.LabLamarr(bench) == nil and not IsValid(bench.lcLamarr), "and not on anyone else's")
        end
        bench:Remove()
    end
    -- the dreams' dressing leaves a dream with its own (or no arena box) alone
    ok(LC.DreamDress({ def = { id = "spy", noDress = true }, bounds = { mins = Vector(0, 0, 0), maxs = Vector(10, 10, 10) }, ents = {} }) == 0, "a dream that dresses itself is left alone")
    ok(LC.DreamDress({ def = { id = "x" }, ents = {} }) == 0, "and one with no arena box")
    -- a job board: whose follows where it stands; E opens your jobs, or says whose it is
    local jb = ents.Create("lc_jobboard")
    if IsValid(jb) then
        jb:SetPos(Vector(-65000, -65000, 0)) jb:Spawn()
        ok(LC.JobBoardSide(jb) == "citizen", "a job board in the city is the Union's")
        local c2 = newPlayer("BoardCitizen15", "citizen")
        local r2 = newPlayer("BoardRebel15", "resistance", nil, 200)
        ok(LC.UseJobBoard(c2, jb) and not LC.UseJobBoard(r2, jb), "a citizen's jobs open from it; a rebel is told it isn't theirs")
        LC.JobBoardRefresh(jb)
        ok(jb:GetNW2String("lc_board_name", "") == "Assignments", "its glass says whose board it is")
        jb:Remove()
    end
end)()


section("The play study: how the owner plays, written down as a model for the city's people (sv_livingcity_study.lua)")
;(function()
    local errs0 = #_errors
    local p = newPlayer("StudyOwner", "resistance")
    local other = newPlayer("StudyOther", "citizen")
    p.superadmin = true
    p:SetPos(Vector(-90000, 90000, 0))
    local runWas0, callWas0, noticeWas0 = hook.Run, hook.Call, LC.Notice
    local function Sent()
        local log, report, kinds = {}, {}, {}
        for _, m in ipairs(net.sent) do
            if m.name == "lc_study" and m.to == p then
                kinds[#kinds + 1] = m.data[1]
                for i = 0, (m.data[3] or 0) - 1 do
                    local line = tostring(m.data[5 + i * 3]) .. " " .. tostring(m.data[6 + i * 3])
                    if m.data[1] == "report" then report[#report + 1] = line else log[#log + 1] = line end
                end
            end
        end
        return table.concat(log, "\n"), table.concat(report, "\n"), kinds
    end
    local function Act(what, arg) net._q = { what, arg or "" } net["recv_lc_study_act"](0, p) end
    local function Has(text, t) return string.find(text, t, 1, true) ~= nil end

    ok(not LC.Studying(), "the study: off until someone switches it on")
    ok(select(1, LC.StudyStart(other)) == false and not LC.Studying(), "the study: only those who may use the editor can be studied")
    net.sent = {}
    Act("start")
    ok(LC.Studying() and LC.Studying().ply == p, "the study: switched on from the window")
    ok(select(1, LC.StudyStart(p)) == false, "(one at a time)")
    _run(3.2)
    -- a job, done well
    local q1 = { title = "Carry the parcel", tmpl = { id = "res_parcel" }, board = "The Resistance", stage = 1, stages = { { kind = "goto", text = "Go there." }, { kind = "use" } }, owner = p, members = { p } }
    LC.QuestOf[p] = q1
    _run(2.2)
    q1.stage = 2
    hook.Run("LivingCityScavenged", p, "a tin")
    hook.Run("LivingCityScavenged", other, "not the player's")
    hook.Run("LivingCityIsWanted", p)
    if IN_JUMP then hook.Run("KeyPress", p, IN_JUMP) end
    hook.Run("PlayerSay", p, "/radio", false)
    LC.Notice(p, "info", "Curfew", "Get indoors.", 6)
    _run(2.2)
    q1.done = true
    hook.Run("LivingCityQuestComplete", p, q1)
    LC.QuestOf[p] = nil
    _run(2.2)
    -- flying, and holding the editor's tool: not counted
    p:SetMoveType(MOVETYPE_NOCLIP)
    _run(3.2)
    ok(LC.Studying().pause and Has(LC.Studying().pause, "flying"), "the study: paused while flying")
    p:SetMoveType(MOVETYPE_WALK)
    _run(2.2)
    ok(not LC.Studying().pause, "the study: counting again on the ground")
    -- out of the game window, then away from the keys (the quiet time before is taken out too)
    Act("input", "0|0")
    _run(2.2)
    ok(Has(tostring(LC.Studying().pause), "away"), "the study: paused out of the game window")
    Act("input", "1|0")
    _run(2.2)
    local counted0 = 0
    for _, s in ipairs(LC.Studying().samples) do if not s.pause then counted0 = counted0 + 1 end end
    Act("input", "1|91")
    _run(2.2)
    local counted1 = 0
    for _, s in ipairs(LC.Studying().samples) do if not s.pause then counted1 = counted1 + 1 end end
    ok(Has(tostring(LC.Studying().pause), "away from the keys") and counted1 < counted0, "the study: away from the keys pauses it, and the quiet time before it was noticed isn't counted either")
    Act("input", "1|0")
    _run(2.2)
    -- a dream is its own context
    p.lcDreaming = 99
    _run(2.2)
    p.lcDreaming = nil
    _run(2.2)
    -- a job that fails is kept out; a job that went wrong is struck by hand
    local q2 = { title = "The glitched one", tmpl = { id = "res_glitch" }, board = "The Resistance", stage = 1, stages = { { kind = "goto" } }, owner = p, members = { p } }
    LC.QuestOf[p] = q2
    _run(3.2)
    q2.done = true
    hook.Run("LivingCityQuestFailed", p, q2)
    LC.QuestOf[p] = nil
    _run(2.2)
    local q3 = { title = "Done but wrong", tmpl = { id = "res_wrong" }, board = "The Resistance", stage = 1, stages = { { kind = "goto" } }, owner = p, members = { p } }
    LC.QuestOf[p] = q3
    _run(3.2)
    q3.done = true
    hook.Run("LivingCityQuestComplete", p, q3)
    LC.QuestOf[p] = nil
    _run(2.2)
    Act("strike_job")
    ok(#LC.Studying().struck == 1 and LC.Studying().quests[3].struck, "the study: the last job can be struck")
    Act("stop")
    local log, report, kinds = Sent()
    ok(not LC.Studying() and hook.Run == runWas0 and hook.Call == callWas0 and LC.Notice == noticeWas0, "the study: stopped, and nothing is left wrapped or hooked")
    ok(kinds[1] == "start" and Has(log, "who resistance, ") and Has(log, "what in the city") and Has(log, "place no zone (open ground)"), "the study: who, in what and where are written down")
    ok(Has(log, "job taken: \"Carry the parcel\" [res_parcel] from The Resistance") and Has(log, "job stage 2 (use)") and Has(log, "\"Carry the parcel\" complete"), "the study: a job, its stages and how it ended")
    ok(Has(log, "event Scavenged: a tin") and not Has(log, "not the player's") and not Has(log, "IsWanted"), "the study: the gamemode's own events about the player, nobody else's, and no questions")
    ok(Has(log, "event command /radio") and Has(log, "told [info] Curfew: Get indoors.") and (not IN_JUMP or Has(log, "event jumped: at ")), "the study: commands, what they're told, and jumps with the spot on the map")
    ok(Has(log, "pause flying (noclip)") and Has(log, "pause playing again") and Has(log, "what in a dream ("), "the study: pauses, and a dream as its own context")
    ok(Has(log, "\"The glitched one\" failed") and Has(log, "kept out of the baselines") and Has(log, "strike the job \"Done but wrong\""), "the study: a failed job is kept out, a struck one is marked")
    ok(not Has(log, "couldn't look"), "(the study looked without a hitch)", log)
    ok(Has(report, "LIVING CITY: A PLAY STUDY") and Has(report, "== THE CITY | resistance, ") and Has(report, "== A DREAM (") and Has(report, "no zone (open ground): "), "the report: a table for each who and what, by place")
    ok(Has(report, "paused, flying (noclip)") and Has(report, "paused, away from the keys") and Has(report, "kept out, a job that failed") and Has(report, "kept out, struck"), "the report: what wasn't counted, and why")
    ok(Has(report, "\"Carry the parcel\" [res_parcel]") and Has(report, "[kept out of the tables]") and Has(report, "[STRUCK by the player: not in the tables]"), "the report: every job, with the ones left out marked")
    ok(Has(report, "Scavenged") and Has(report, "== WHERE ON THE MAP") and Has(report, "(-89984 89984 64)"), "the report: what happened, and where on the map")
    ok(kinds[#kinds] == "status" and kinds[#kinds - 1] == "end", "the report is sent, then the end")
    -- discarding keeps nothing
    net.sent = {}
    Act("start")
    _run(2.2)
    Act("discard")
    local _, report2, kinds2 = Sent()
    local discarded = false
    for _, m in ipairs(net.sent) do if m.name == "lc_study" and m.data[1] == "end" and m.data[2] == "discard" then discarded = true end end
    ok(not LC.Studying() and report2 == "" and discarded and hook.Run == runWas0, "the study: a discarded session sends no report")
    ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
    p:SetPos(Vector(-121000, -121000, 0))
    other:SetPos(Vector(-121000, -121000, 0))
end)()


function Nov14B_RankTests() -- (the owner, 14 November: "I set myself to Lieutenant via the admin tools ... it still says I am a member")
section("14 November, B1: a rank or XP given by staff carries the Resistance's trust, and the cage opens for a Lieutenant")
_setcvar("lc_fighter_trust_jobs", 3)
_setcvar("lc_rebel_cage", 1)
local adm = newPlayer("B1Admin", "resistance") adm.admin = true
ok(adm:GetNW2Int("lcf_rank", 1) == 1 and (LC.ResistanceTrust(adm)) == 0, "a new member: Sympathizer, no jobs done for them yet")
local good, msg = LC.AdminTool(adm, adm, "xp", 1000)
ok(good == true and adm:GetNW2Int("lcf_rank", 1) == 4 and string.find(msg or "", "Lieutenant", 1, true) ~= nil, "+1000 XP from the admin tools: a Lieutenant, and the admin is told so", msg)
ok(LC.RebelMayHold(adm) == true, "the cage opens for them")
ok(LC.CanJoinFaction(adm, "resistance", "hacker") == true, "and the Hacker's role is open to them")
LC.AdminTool(adm, adm, "resetme")
ok(adm:GetNW2Int("lcf_rank", 1) == 1, "reset: a Sympathizer again")
good, msg = LC.AdminTool(adm, adm, "rank", 4)
ok(good == true and adm:GetNW2Int("lcf_rank", 1) == 4 and string.find(msg or "", "is now Lieutenant", 1, true) ~= nil, "set to rank 4 by the admin tools: a Lieutenant", msg)
-- XP earned without the jobs is held as before, and the career page says why
local raw = newPlayer("B1Raw", "resistance")
raw:SetPData("lcf_xp_resistance", 1000)
LC.AddXP(raw, 0)
ok(raw:GetNW2Int("lcf_rank", 1) == 2 and not LC.RebelMayHold(raw), "XP earned without the jobs still stops at Member (trust before a gun is as it was)")
local info = LC.CareerInfo(raw)
ok(string.find(info.steps[1] or "", "3 more", 1, true) ~= nil and string.find(info.steps[1] or "", "Earn 0", 1, true) == nil, "the career page says what holds them back: three more jobs, not 'Earn 0 more XP'", info.steps[1])
LC.AdminTool(adm, raw, "xp", 50)
ok(raw:GetNW2Int("lcf_rank", 1) == 4, "XP from staff on top of a Fighter's XP gives the trust with it")
local low = newPlayer("B1Low", "resistance")
LC.AdminTool(adm, low, "xp", 200)
ok(low:GetNW2Int("lcf_rank", 1) == 2 and (LC.ResistanceTrust(low)) == 0, "below a Fighter's XP nothing but the XP changes")
-- the console's own commands do the same
local con = newPlayer("B1Con", "resistance")
con:SetPData("lcf_xp_resistance", 900)
LC.StaffTrust(con) LC.AddXP(con, 0, "by staff")
ok(con:GetNW2Int("lcf_rank", 1) == 4, "LC.StaffTrust: what lcf_setxp and lcf_promote call")
for _, p in ipairs({ adm, raw, low, con }) do p:SetPos(Vector(-30000, 30000, 0)) end
end
Nov14B_RankTests()

function Nov14B_CageTests() -- (the owner, 14 November: "Rebel NPCs are spawning inside the cage prison cell ... make sure that prisoners don't spawn outside the map brushes/walls")
section("14 November, B2: nobody held is stood in the map's wall, and rebels stay out of the cage")
_setcvar("lc_rebel_cage", 1)
local VM = getmetatable(Vector(0, 0, 0))
local hadRotate = VM.Rotate
if not hadRotate then
    function VM:Rotate(a) local r = math.rad(a.y or 0) local x, y = self.x, self.y self.x, self.y = x * math.cos(r) - y * math.sin(r), x * math.sin(r) + y * math.cos(r) end
end
local was = ENT
ENT = {}
assert(loadstring(_ENTSRC["entities/lc_rebelcage.lua"], "lc_rebelcage"))()
local def = ENT
ENT = was
local P0 = Vector(-61000, 47000, 0)
local cage = ents.Create("lc_rebelcage")
cage:SetPos(P0)
cage:Spawn()
cage.lcHalf = 60
for _, k in ipairs({ "Inside", "Holds", "Slot", "Outside" }) do cage[k] = def[k] end
LC.CageForget()
-- in the open every place is where it always was, inside the panels
local allIn = true
for i = 1, 8 do if not cage:Holds(cage:Slot(i)) then allIn = false end end
ok(allIn and not cage:Holds(cage:Outside()), "in the open: eight places inside the four panels, and the way out is outside them")
-- the map's wall runs through the back of the cage (the cage clips into it)
local wall = { a = Vector(P0.x - 15, P0.y - 500, 0), b = Vector(P0.x - 15, P0.y + 500, 0) }
table.insert(_walls, wall)
local behind = 0
for i = 1, 8 do if cage:Slot(i).x < P0.x - 15 then behind = behind + 1 end end
ok(behind == 0, "with the wall through the back of the cage nobody is stood behind it", behind .. " behind the wall")
local s1 = cage:Slot(1)
ok(cage:Holds(s1) and s1.z == P0.z + 2, "a place pulled in from the wall is still in the cage, on its floor")
for i = #_walls, 1, -1 do if _walls[i] == wall then table.remove(_walls, i) end end
-- LC.CageAt, and the things that ask it
ok(LC.CageAt(P0 + Vector(20, -20, 0)) == cage and LC.CageAt(P0 + Vector(300, 0, 0)) == nil and LC.CageAt(P0 + Vector(0, 0, 400)) == nil, "LC.CageAt: the cage a spot is in; not beside it, not the floor above")
local z = { kind = "rebel", pos = P0, r = 50, radius = 50 }
local inCage = 0
local wasR = LCZ.RandomInside
LCZ.RandomInside = function() return P0 + Vector(10, 10, 0) end
for _ = 1, 5 do if LC.SpotInZone(z) then inCage = inCage + 1 end end
LCZ.RandomInside = function() return P0 + Vector(400, 10, 0) end
local out = LC.SpotInZone(z)
LCZ.RandomInside = wasR
ok(inCage == 0, "LC.SpotInZone never gives a spot in the cage (so nobody is spawned, stood or sent there)", inCage .. " of 5")
ok(out ~= nil, "and beside the cage it gives spots as before")
_setcvar("lc_manpower", 0)
local npc, st = LC.SpawnRebel(P0 + Vector(10, 0, 4), nil)
ok(IsValid(npc) and not cage:Holds(npc:GetPos()), "a rebel asked for in the cage appears outside its gate")
-- one who got in some other way is walked out; someone held stays
npc:SetPos(P0 + Vector(5, 5, 0))
local held, hst = LC.SpawnCitizen(P0 + Vector(400, 0, 0))
hst.leaveAt = nil
LC.RebelHeld[held] = { cage = cage, st = hst, at = CurTime(), slot = 1 }
held:SetPos(cage:Slot(1))
local moved = LC.CageSweep()
ok(moved == 1 and not cage:Holds(npc:GetPos()) and cage:Holds(held:GetPos()), "the sweep stands a stray outside the gate and leaves the prisoner where they are", tostring(moved))
LC.RebelHeld[held] = nil
if IsValid(npc) then npc:Remove() end
if IsValid(held) then held:Remove() end
cage:Remove()
LC.CageForget()
if not hadRotate then VM.Rotate = nil end
end
Nov14B_CageTests()

function Nov14B_LabSalesTests() -- (the owner, 14 November: "Rebel scientist needs to sell a charged vest, not the quartermaster", "combine bypass charges need to be only from the lab too")
section("14 November, B5: the charged vest and the bypass charge come from the lab alone")
ok(LCS.LabById.armor_vest ~= nil and LCS.LabById.bypass ~= nil, "the lab makes the powered vest and the bypass charge")
ok(LCS.BlackById.armor_vest.lab == true and LCS.BlackById.bypass.lab == true, "both are marked as the lab's on the black market's list (kept there for their price)")
ok(not LC.QuartermasterStocks("armor_vest") and not LC.QuartermasterStocks("bypass") and LC.QuartermasterStocks("gun_pistol"), "the quartermaster doesn't stock them (he still stocks pistols)")
local dup = {}
for _, r in ipairs(LCS.Lab) do if LC.QuartermasterStocks(r.out) then dup[#dup + 1] = r.id end end
ok(#dup == 0, "nothing is sold by both the lab and the quartermaster", table.concat(dup, ", "))
local pv, pb = LC.LabPrice(LCS.LabById.armor_vest), LC.LabPrice(LCS.LabById.bypass)
ok(pv > 0 and pv < 90 and pb > 0 and pb < 70, "the lab's price for each is under the old dealer's (90 and 70)", pv .. ", " .. pb)
-- nobody's list shows them, and nobody sells them
local buyer = newPlayer("B5Buyer", "resistance", nil, 400)
LC.AddCredits(buyer, 1000)
local wasAccess = LC.MarketAccess
LC.MarketAccess = function() return true end
net.sent = {}
LC.OpenMarket(buyer)
local m = _lastnet("lcu_market")
local t
for _, d in ipairs(m and m.data or {}) do
    if type(d) == "table" and d.goods then t = d elseif type(d) == "string" and not t then t = util.JSONToTable(d) end
end
local seen, pistols = 0, 0
for _, g in ipairs(t and t.goods or {}) do
    if g.id == "armor_vest" or g.id == "bypass" then seen = seen + 1 end
    if g.id == "gun_pistol" then pistols = pistols + 1 end
end
ok(t ~= nil and seen == 0 and pistols == 1, "the black market's window lists neither (pistols are still there)", tostring(seen) .. " listed, pistols " .. tostring(pistols))
local before = LC.Credits(buyer)
local okV = LC.BlackBuy(buyer, "armor_vest")
local okB = LC.BlackBuy(buyer, "bypass")
ok(not okV and not okB and LC.Credits(buyer) == before and not LC.HasItem(buyer, "armor_vest") and not LC.HasItem(buyer, "bypass"), "and a buy sent for one anyway is refused, nothing charged")
LC.MarketAccess = wasAccess
buyer:SetPos(Vector(-30000, 30000, 0))
end
Nov14B_LabSalesTests()

function Nov14B_SpawnTests() -- (the owner, 14 November: "resistance spawn points should be active for resistance human players based on the last one they were closest to, which survives server restarts")
section("14 November, B4: a Resistance player comes back at the spawn point they were last closest to, and a restart keeps it")
local A, B = Vector(-52000, 52000, 0), Vector(-47000, 52000, 0)
local pts = { { kind = "rspawn", pos = A }, { kind = "rspawn", pos = B } }
local wasPts = LC.PointsOfKind
LC.PointsOfKind = function(kind, group) if kind == "rspawn" then return pts end return wasPts(kind, group) end
local m = newPlayer("B4Member", "resistance", nil, 150) -- (a Member: not hunted, and it is theirs too)
ok(not LC.PlayerIsHunted(m), "(a Member passes for a citizen)")
m:SetPos(A + Vector(400, 100, 0))
ok(LC.RebelSpawnNote(m) == pts[1] and m:GetPData("lc_rspawn", "") ~= "", "near the first spawn point: it is remembered, in their saved data")
local function respawns(p, at, times)
    local n = 0
    for _ = 1, times do
        hook.Run("PlayerSpawn", p)
        _run(0.2)
        if p:GetPos():DistToSqr(at + Vector(0, 0, 4)) < 4 then n = n + 1 end
        p:SetPos(at + Vector(300, 0, 0)) -- (walks a little way off, still nearest to it)
    end
    return n
end
ok(respawns(m, A, 6) == 6, "six respawns, six times at that point (not any one of them)")
m.lcRSpawn = nil -- (a restart: only the saved data is left)
ok(respawns(m, A, 6) == 6, "after a restart it is still that one")
m:SetPos(B + Vector(-200, 0, 0))
LC.RebelSpawnNote(m)
ok(respawns(m, B, 6) == 6, "having gone to the other base, they come back there")
-- dying far from both: the one nearest to where they fell
m:SetPos(A + Vector(1500, 0, 0))
hook.Run("DoPlayerDeath", m)
hook.Run("PlayerSpawn", m)
_run(0.2)
ok(m:GetPos():DistToSqr(A + Vector(0, 0, 4)) < 4, "killed nearer the first: back at the first")
-- a point that has been taken away: any that is left
pts = { { kind = "rspawn", pos = B } }
m.lcRSpawn = nil
m:SetPos(Vector(-30000, 30000, 0))
hook.Run("PlayerSpawn", m)
_run(0.2)
ok(m:GetPos():DistToSqr(B + Vector(0, 0, 4)) < 4, "their point taken away with the editor: the one that is left")
-- nobody else is sent there
local cit = newPlayer("B4Cit", "citizen")
cit:SetPos(B + Vector(100, 0, 0))
ok(LC.RebelSpawnNote(cit) == nil and cit:GetPData("lc_rspawn", "") == "", "a citizen standing by one has nothing remembered")
LC.PointsOfKind = wasPts
for _, p in ipairs({ m, cit }) do p:SetPos(Vector(-30000, 30000, 0)) end
end
Nov14B_SpawnTests()

function Nov14B_CuffTests() -- (the owner, 14 November: "I don't see an option to cuff NPCs as a resistance member, but I have 5 pairs of cuffs in my pockets")
section("14 November, B6: F2 > Cuff them, for a Resistance Fighter or above with cuffs: to the holding cage")
_setcvar("lc_rebel_cage", 1)
_setcvar("lc_rebel_auto", 0)
_setcvar("lc_rebel_visitor", 0)
local P0 = Vector(-66000, 41000, 0)
local cage = ents.Create("lc_rebelcage")
cage:SetPos(P0)
cage:Spawn()
LC.CageForget()
local function person(off)
    local n, st = LC.SpawnCitizen(P0 + off)
    st.leaveAt = nil
    n.sim = false
    return n, st
end
local act = LC.TargetActions.cagecuff
ok(type(act) == "function", "F2's action for it is there")
local lt = newPlayer("B6Lt", "resistance", nil, 900)
local member = newPlayer("B6Member", "resistance", nil, 150)
local symp = newPlayer("B6Symp", "resistance", nil, 0)
local n1, st1 = person(Vector(400, 0, 0))
lt:SetPos(n1:GetPos() + Vector(60, 0, 0))
symp:SetPos(n1:GetPos() + Vector(-60, 0, 0))
LC.GiveItem(symp, "zipties", 2)
ok(symp:GetNW2Int("lcf_rank", 1) < 2 and not act(symp, n1) and LC.RebelHeld[n1] == nil and LC.CuffCount(symp) == 2, "a Sympathizer with cuffs takes nobody (Members and above)", symp:GetNW2Int("lcf_rank", 1))
ok(not act(lt, n1) and LC.RebelHeld[n1] == nil, "a Lieutenant with no cuffs: nothing happens")
LC.GiveItem(lt, "zipties", 5)
lt:SetPos(n1:GetPos() + Vector(900, 0, 0))
local far, why = act(lt, n1)
ok(not far and string.find(why or "", "closer", 1, true) ~= nil and LC.CuffCount(lt) == 5, "from too far: told to get closer, no cuffs used", why)
lt:SetPos(n1:GetPos() + Vector(60, 0, 0))
ok(act(lt, n1) == true and LC.RebelHeld[n1] ~= nil and st1.questLock == true and LC.CuffCount(lt) == 4, "up close with cuffs: they are taken for the cage, and one pair is used", tostring(LC.CuffCount(lt)))
n1:SetPos(P0 + Vector(60, 0, 0))
LC.CageTick(CurTime())
ok(#LC.CageList(cage) == 1 and st1.state == "detained", "at the cage they are locked in, as from the talk window")
ok(not act(lt, n1) and LC.CuffCount(lt) == 4, "someone already held isn't cuffed again")
-- no cage near enough: said so, no cuffs used
local n2 = person(Vector(9000, 0, 0))
lt:SetPos(n2:GetPos() + Vector(60, 0, 0))
local none, whyNone = act(lt, n2)
ok(not none and string.find(whyNone or "", "no cage", 1, true) ~= nil and LC.CuffCount(lt) == 4, "with no cage within reach: said so, no cuffs used", whyNone)
-- one of their own isn't theirs to cuff
local rb = LC.SpawnRebel(P0 + Vector(500, 300, 4), nil)
if IsValid(rb) then
    lt:SetPos(rb:GetPos() + Vector(60, 0, 0))
    ok(not act(lt, rb) and LC.RebelHeld[rb] == nil and LC.CuffCount(lt) == 4, "a rebel isn't cuffed by their own")
    rb:Remove()
end
-- a Member may cuff too (the owner, 15 November); the cage itself stays with Fighters and above
local n3, st3 = person(Vector(400, 200, 0))
member:SetPos(n3:GetPos() + Vector(60, 0, 0))
LC.GiveItem(member, "zipties", 2)
ok(member:GetNW2Int("lcf_rank", 1) == 2 and act(member, n3) == true and LC.RebelHeld[n3] ~= nil and LC.CuffCount(member) == 1, "a Member with cuffs takes them for the cage too, and one pair is used",
    member:GetNW2Int("lcf_rank", 1) .. " " .. tostring(LC.CuffCount(member)))
ok(not LC.RebelMayHold(member), "opening the cage is still for Fighters and above")
LC.CageFree(n1) LC.CageFree(n3)
for _, e in ipairs({ n1, n2, n3, cage }) do if IsValid(e) then e:Remove() end end
LC.CageForget()
for _, p in ipairs({ lt, member, symp }) do p:SetPos(Vector(-30000, 30000, 0)) end
end
Nov14B_CuffTests()
function Nov14F_DreamNightTests()
section("14 November night, F1: a night's sleep gives a dream when nobody chose one (the city's own pick)")
local errs0 = #_errors
local realGetAll, realPhase, realReload = player.GetAll, LC.DayPhase, LC.EndingReload
local savedWalls = _walls
_walls = {}
LC.EndingReload = function() end
_setcvar("lc_dream_rules", 1) _setcvar("lc_dream_auto", 1) _setcvar("lc_dream_every_night", 0) -- (the owner's server: all defaults)
local DS = LC.DreamState
local keep = { at = DS.at, queued = DS.queued, missed = DS.missedNight, dreamed = DS.dreamedNight }
local reb = newPlayer("F1Rebel", "resistance", nil, 900)
_run(2)
local BED, DREAM = Vector(-231000, 231000, 0), Vector(-262000, 262000, 0)
local pt = LC.AddPoint(DREAM, 0, "dream")
player.GetAll = function() return { reb } end
LC.DayPhase = function() return "night" end
if LC.DreamActive then LC.DreamWake(LC.DreamActive) end
LC.DreamForget()
reb:SetPos(BED)
reb.lcSleep = { t0 = CurTime() - 70, done = CurTime() - 10, last = CurTime(), slept = true }
reb:SetNW2Bool("lc_sleeping", true)
ok(LC.DreamQueued() == nil and LC.DreamCityPicks() == true, "(nobody chose tonight's dream: it is the city's to pick)")
hook.Run("LivingCityDayPhase", "night", "dusk")
ok(DS.at ~= nil, "(the night coming sets the time of tonight's dream)")
_run(70)
ok(LC.DreamActive ~= nil and reb.lcDreaming ~= nil, "a rebel asleep on rebel ground at night dreams, with nobody having chosen a dream", tostring(LC.DreamActive) .. " " .. tostring(reb.lcDreaming))
ok(string.find(LC.DreamDebugLine(), "the city picks every night", 1, true) ~= nil and string.find(LC.DreamDebugLine(), "last: ", 1, true) ~= nil,
    "the debug report has a dreams line: who picks, and the last one dreamt", LC.DreamDebugLine())
if LC.DreamActive then LC.DreamWake(LC.DreamActive) end
LC.DreamActive = nil
-- the city's own pick: not held back by the endings' cooldown, and one that can't be dreamt passes its turn on
local realStart, realCheck = LC.DreamStart, LC.DreamMissedCheck
local seen = {}
LC.DreamStart = function(id, by, vote, also, force) seen[#seen + 1] = { id = id, force = force } return false, "The dream couldn't be built here." end
LC.DreamForget()
DS.tries, DS.triesNight = nil, nil
local okT, whyT = LC.DreamTonight()
ok(okT == false and #seen == 1 and seen[1].force == true, "the city's own pick doesn't wait for the endings' cooldown (it is started the way the Administrator's is)", tostring(seen[1] and seen[1].force))
ok(DS.missedNight == DS.night and DS.queued == nil, "a pick that can't be dreamt isn't the end of the night: another is tried")
LC.DreamTonight()
ok(#seen == 2 and seen[2].id ~= seen[1].id, "and it is the next one, not the same again", tostring(seen[1] and seen[1].id) .. " " .. tostring(seen[2] and seen[2].id))
LC.DreamTonight()
ok(DS.missedNight ~= DS.night or DS.tries >= 3, "three tries a night at most")
DS.missedNight = nil
ok(string.find(LC.DreamDebugLine(), "didn't happen: The dream couldn't be built here.", 1, true) ~= nil, "and the debug report says why the last one didn't happen", LC.DreamDebugLine())
LC.DreamStart, LC.DreamMissedCheck = realStart, realCheck
LC.DreamForget()
DS.tries, DS.triesNight, DS.last = nil, nil, nil
reb.lcSleep = nil reb:SetNW2Bool("lc_sleeping", false)
LC.RemovePoint(pt)
DS.at, DS.queued, DS.missedNight, DS.dreamedNight = keep.at, keep.queued, keep.missed, keep.dreamed
player.GetAll, LC.DayPhase, LC.EndingReload = realGetAll, realPhase, realReload
_walls = savedWalls
reb:SetPos(Vector(-121000, -121000, 0))
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
Nov14F_DreamNightTests()

function Nov14F_RationsTests()
section("14 November night, F2 and F3: rations by day only, never from empty stores, deliveries sized to the city")
local errs0 = #_errors
local realHour, realCounts, realHuman = LC.Hour, LC.RoleCounts, LC.HumanAdministrator
local stockWas = LC.Stock()
_setcvar("lc_stockpile", 1)
LC.EndEvent(true)
LC.StockAdd(200 - LC.Stock())
-- the hours
ok(LC.RationsCanStart(true, 7) and LC.RationsCanStart(true, 12) and LC.RationsCanStart(true, 17.9), "the city hands rations out by day (07:00 to 18:00)")
ok(not LC.RationsCanStart(true, 18) and not LC.RationsCanStart(true, 21) and not LC.RationsCanStart(true, 23.5) and not LC.RationsCanStart(true, 3) and not LC.RationsCanStart(true, 6.9),
    "never in the evening or at night (the owner, 14 November: rations at 21:00)")
ok(LC.RationsCanStart(false, 22) == true, "a handout ordered by hand is the Administrator's choice, at any hour")
LC.Hour = function() return 21.5 end
local night = {}
for _ = 1, 300 do night[LC.PickAutoEvent()] = true end
ok(not night.rations and next(night) ~= nil, "at night the city's own timer never picks a ration handout")
LC.HumanAdministrator = function() return nil end
local okD, whyD = LC.AdminDecree("event", "rations")
ok(okD == false and string.find(tostring(whyD), "by day", 1, true) ~= nil, "the NPC Administrator can't call one at night either", tostring(whyD))
LC.Hour = function() return 12 end
local day = {}
for _ = 1, 300 do day[LC.PickAutoEvent()] = true end
ok(day.rations == true, "by day it still does")
-- nothing to give
LC.StockAdd(-LC.Stock())
ok(LC.StockLevel() == "empty" and not LC.RationsCanStart(false) and not LC.RationsCanStart(true), "empty stores: no handout, whoever asks")
local empty = {}
for _ = 1, 300 do empty[LC.PickAutoEvent()] = true end
ok(not empty.rations, "the city's timer doesn't pick one with nothing to give")
ok(LC.StartEvent("rations") == false and LC.Event ~= "rations", "and none starts (the owner: \"rations are empty, how are they being distributed?\")")
LC.StockAdd(200)
ok(LC.StartEvent("rations") == true and LC.Event == "rations", "with rations in the stores, by day, it starts as ever")
LC.EndEvent(true)
-- deliveries sized to the city
LC.StockAdd(100 - LC.Stock())
LC.RoleCounts = { citizen = 14 }
hook.Run("LivingCityTrainArrived", nil, {}, "City 14")
ok(LC.Stock() == 120, "a small city (the default): a train brings 20", LC.Stock())
hook.Run("LivingCitySupplyEnded", {}, 2)
ok(LC.Stock() == 160, "and a convoy 20 a load", LC.Stock())
LC.StockAdd(100 - LC.Stock())
LC.RoleCounts = { citizen = 80 }
ok(LC.StockEatRate() == 4, "a city of 80 eats four rations a minute (lc_stock_eat 20)")
hook.Run("LivingCityTrainArrived", nil, {}, "City 14")
ok(LC.Stock() == 180, "its train brings 80: twenty minutes of its eating", LC.Stock())
hook.Run("LivingCitySupplyEnded", {}, 2)
ok(LC.Stock() == 340, "and its convoy 80 a load", LC.Stock())
-- an hour of the owner's city with nobody doing anything, at the least: two trains, a convoy every five hours with
-- three of its five loads left (the rebels took two), the workers' 52 an hour, against 240 eaten and a handout's 8:
-- it holds (it lost about 135 an hour before)
local inn = 2 * LC.StockDelivery * LC.StockEatRate() + (3 * LC.StockDelivery * LC.StockEatRate()) / 5 + 52
ok(inn >= 60 * LC.StockEatRate() + 8, "what comes in an hour, at the least, covers what a city of 80 eats and hands out", inn .. " in, " .. (60 * LC.StockEatRate() + 8) .. " out")
-- stores emptied by the old sums start again from half, once
local path = "livingcity/" .. game.GetMap() .. "_stock.json"
local fileWas = _files[path]
_files[path] = util.TableToJSON({ stock = 0 })
LC.StockLoad()
ok(LC.Stock() == 200, "stores saved empty before this start again from half", LC.Stock())
LC.StockAdd(-LC.Stock())
LC.StockSave()
LC.StockLoad()
ok(LC.Stock() == 0, "once: emptied again and saved, they stay as they are", LC.Stock())
_files[path] = util.TableToJSON({ stock = 320 })
LC.StockLoad()
ok(LC.Stock() == 320, "(stores saved above half are left alone)", LC.Stock())
_files[path] = fileWas
LC.Hour, LC.RoleCounts, LC.HumanAdministrator = realHour, realCounts, realHuman
LC.StockAdd(stockWas - LC.Stock())
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
Nov14F_RationsTests()

function Nov14F_InfestedKinTests()
section("14 November night, F4: the infested and the infestation's own zombies don't hurt each other")
local errs0 = #_errors
local zp, hp = newPlayer("F4Infested", "citizen"), newPlayer("F4Human", "citizen")
local wasZ = LC.PlayerIsZombie
LC.PlayerIsZombie = function(p) return p == zp end
local zb = ents.Create("npc_zombie") zb:SetPos(Vector(-271000, -271000, 0)) zb:Spawn()
local hc = ents.Create("npc_headcrab") hc:SetPos(Vector(-271100, -271000, 0)) hc:Spawn()
local cit = ents.Create("npc_citizen") cit:SetPos(Vector(-271200, -271000, 0)) cit:Spawn()
zp:SetPos(Vector(-271050, -271000, 0))
local kin = hook.t.EntityTakeDamage.LivingCityInfestedKin
ok(LC.InfestedKin(zp, zb) and LC.InfestedKin(zb, zp) and LC.InfestedKin(zp, hc), "an infested player and a zombie or headcrab are kin, either way round")
ok(kin(zp, _dmg(zb, 20)) == true, "a zombie's swipe does an infested player no damage (the owner: \"Not only players but players vs npcs\")")
ok(kin(zb, _dmg(zp, 20)) == true and kin(hc, _dmg(zp, 20)) == true, "and an infested player's blow does a zombie or a headcrab none")
ok(kin(hp, _dmg(zb, 20)) == nil and kin(zb, _dmg(hp, 20)) == nil, "a human and a zombie hurt each other as ever")
ok(kin(cit, _dmg(zp, 20)) == nil and kin(zp, _dmg(cit, 20)) == nil, "so do an infested player and a citizen")
ok(not LC.InfestedKin(zb, hc), "(two NPCs are left to the game)")
-- backpedalling while shooting (the engine's own; the gamemode's part is firing on the move): kept
do
    local caps = 0
    local unit = { CapabilitiesAdd = function(_, c) caps = bit.bor(caps, c) end }
    local had = CAP_MOVE_SHOOT
    CAP_MOVE_SHOOT = had or 0x2000000 -- (the fake game has no such number)
    ok(LC.CombatMoveShoot == true and LC.CombatTune(unit, {}) == true and bit.band(caps, CAP_MOVE_SHOOT) ~= 0,
        "every fighter is still given firing on the move (what lets them backpedal while shooting: the owner, 14 November, \"make sure that stays\")", caps)
    CAP_MOVE_SHOOT = had
end
LC.PlayerIsZombie = wasZ
for _, e in ipairs({ zb, hc, cit }) do if IsValid(e) then e:Remove() end end
zp:SetPos(Vector(-121000, -121000, 0)) hp:SetPos(Vector(-121000, -121000, 0))
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
end
Nov14F_InfestedKinTests()
function Nov14A_CustodyTests()
section("14 November, group A: never cuffed while armed and fighting, always a struggle, three checks")
local C0 = Vector(-262000, 91000, 0)
local cellC = LC.AddPoint(C0 + Vector(1400, 0, 0), 0, "cell", 0)
LC.AddPoint(C0 + Vector(1400, 400, 0), 0, "release", 0)
local errs0 = #_errors
_setcvar("lc_arrest_struggle", 1)
local function fresh(p)
    p.lcFiredAt, p.lcAttackedSecurityAt, p.lcBrokeFree, p.lcHadChanceAt, p.lcInHandAt, p.lcStillSince, p.lcSubdue = nil, nil, nil, nil, nil, nil, nil
    p.lcGraceUntil, p.lcViolentUntil, p.lcJailOwed = nil, nil, nil
    if LC.Struggles[p] then LC.StruggleCancel(p) end
end
local function hands(p)
    if not p:HasWeapon("weapon_fists") then p:Give("weapon_fists") end
    p:SelectWeapon("weapon_fists")
end
local reb = newPlayer("A1Rebel", "resistance", nil, 900)
_run(0.3)
reb:SetPos(C0)
local sol, sst = LC.Spawners.soldier(C0 + Vector(60, 0, 0))
sol.sim = false
sst.untilT = 1e9
fresh(reb)
-- armed and fighting: what counts
hands(reb)
ok(not LC.ArmedAndFighting(reb), "bare hands and nothing done: not armed and fighting")
reb:Give("weapon_smg1") reb:SelectWeapon("weapon_smg1")
ok(LC.ArmedAndFighting(reb), "a gun in hand: armed and fighting")
hands(reb)
hook.Run("EntityFireBullets", reb, { Src = reb:GetPos() })
ok(LC.ArmedAndFighting(reb), "a shot just fired: armed and fighting, gun put away or not")
reb.lcFiredAt = CurTime() - 20
ok(not LC.ArmedAndFighting(reb), "(20 seconds after the last shot, hands empty: no longer)")
reb.lcAttackedSecurityAt = CurTime()
ok(LC.ArmedAndFighting(reb), "a unit just hurt: armed and fighting")
fresh(reb)
-- check 1: standing still with a gun out is aiming, not giving up
LC.ReportCrime(reb, "Assaulting Civil Protection", 300)
reb:SelectWeapon("weapon_smg1")
reb.lcStillSince = CurTime() - 10
ok(not LC.Subdued(reb), "check 1: standing still with a gun out is not 'subdued'")
ok(LC.NPCSubdue(sol, sst, reb, CurTime()) == false and not LC.Marching[reb] and not LC.Struggles[reb], "check 1: a unit beside them does not lay hands on them")
-- check 2: the gate refuses
ok(LC.NPCTakesIn(sol, reb) == false and not LC.InCustody(reb) and not LC.Struggles[reb], "check 2: the gate refuses anyone armed and fighting")
-- check 3: every door of custody refuses, and says so in the errors file
local e1 = #_errors
ok(LC.MarchToPrison(reb, sol, 180, "x") == false and not LC.Marching[reb], "check 3: no march to the cells")
ok(LC.DetainOnTheSpot(reb, sol, "x") == false and not LC.Detained[reb], "check 3: no street detention")
ok(LC.Incarcerate(reb, 180, "x", sol) == false and not LC.Prisoners[reb], "check 3: no cell")
ok(#_errors > e1 and tostring(_errors[#_errors]):find("custody refused", 1, true) ~= nil, "(and each refusal is written down: a path skipped the first two checks)", tostring(_errors[#_errors]))
for i = #_errors, e1 + 1, -1 do table.remove(_errors, i) end
-- E on a unit in a firefight is not a surrender
ok(LC.Surrender(reb, sol) == false and not LC.InCustody(reb), "pressing E on a unit with a gun out is not giving up")
-- the hit that used to be an arrest is just a hit
local function hit(by, who, amount, club)
    local d = _dmg(by, amount, club and DMG_CLUB or nil)
    return hook.Run("EntityTakeDamage", who, d), d
end
sst.enemy = reb
reb:SetHealth(25)
local blocked = hit(sol, reb, 10)
ok(blocked ~= true and not LC.InCustody(reb) and not LC.Struggles[reb], "hurt badly with a gun out: shot, not cuffed")
reb:SetHealth(100)
-- no longer fighting, on their feet: the struggle, never straight into cuffs
fresh(reb)
hands(reb)
reb.lcStillSince = CurTime() - 10
ok(LC.NPCTakesIn(sol, reb) == true and LC.Struggles[reb] ~= nil and LC.Struggles[reb].officer == sol and not LC.Marching[reb],
    "a unit laying hands on someone on their feet: the struggle first, no cuffs yet")
local sm = _lastnet("lc_struggle")
ok(sm and sm.to == reb and sm.data[1] == true and sm.data[2] == "resist" and sm.data[3] == "the soldier", "they see the struggle bar, against the soldier", sm and tostring(sm.data[3]))
ok(reb:GetNW2Float("lc_struggle_until", 0) > CurTime(), "(held where they stand while it lasts)")
local blocked2, d2 = hit(sol, reb, 10)
ok(blocked2 == true and d2:GetDamage() == 0, "nobody shoots or beats them while a unit has hold of them")
-- press hard: free, a head start, and wanted for it
for _ = 1, 48 do _netcall("lc_struggle_press", reb) _run(0.08) end
_run(1)
ok(LC.Struggles[reb] == nil and not LC.InCustody(reb) and (reb.lcBrokeFree or 0) > CurTime(), "pressing E hard enough: free, and not in custody")
ok(LC.NPCTakesIn(sol, reb) == false and LC.NPCSubdue(sol, sst, reb, CurTime()) == false, "(a head start: no unit grabs them again at once)")
-- do nothing: cuffed and walked in, and then (only then) the doors open
fresh(reb)
LC.ReportCrime(reb, "Curfew violation", 300)
reb:SetPos(C0)
sol:SetPos(C0 + Vector(60, 0, 0))
sst.stunnedUntil = 0
ok(LC.NPCTakesIn(sol, reb) == true and LC.Struggles[reb] ~= nil, "caught again: another struggle")
_run(5)
ok(LC.Struggles[reb] == nil and (LC.Marching[reb] ~= nil or LC.Prisoners[reb] ~= nil), "doing nothing: cuffed and taken in", tostring(LC.InCustody(reb)))
local m = LC.Marching[reb]
ok((m and m.reason or (LC.Prisoners[reb] and LC.Prisoners[reb].reason)) == "Curfew violation", "the charge is what they were wanted for")
LC.FreeFromCustody(reb)
ok(not LC.InCustody(reb) and not LC.IsTied(reb) and LC.WantedReason(reb) == "", "(and staff can take them out of it: below)")
-- drawing a gun while held: he lets go, and it is a fight
fresh(reb)
reb:SetPos(C0) sol:SetPos(C0 + Vector(60, 0, 0)) sst.stunnedUntil = 0 sst.marching, sst.questLock = nil, nil
hands(reb)
ok(LC.NPCTakesIn(sol, reb) == true and LC.Struggles[reb] ~= nil, "held again")
if not reb:HasWeapon("weapon_smg1") then reb:Give("weapon_smg1") end
reb:SelectWeapon("weapon_smg1")
_run(0.5)
ok(LC.Struggles[reb] == nil and not LC.InCustody(reb), "a gun drawn while held: the struggle ends, nobody is cuffed")
-- someone with their hands up goes quietly: no struggle, straight to the cuffs
fresh(reb)
hands(reb)
reb:SetPos(C0) sol:SetPos(C0 + Vector(60, 0, 0))
reb:SetNW2Bool("lc_handsup", true)
ok(LC.NPCTakesIn(sol, reb) == true and LC.Struggles[reb] == nil and LC.InCustody(reb), "hands up: taken in with no struggle (their own choice)")
reb:SetNW2Bool("lc_handsup", false)
LC.FreeFromCustody(reb)
-- from across the street nobody is cuffed by a bullet
fresh(reb)
sst.marching, sst.questLock = nil, nil
sst.enemy = reb
LC.ReportCrime(reb, "Curfew violation", 300)
reb:SetPos(C0) sol:SetPos(C0 + Vector(900, 0, 0))
reb:SetHealth(25)
local far = hit(sol, reb, 10)
ok(far ~= true and not LC.InCustody(reb) and not LC.Struggles[reb], "shot from across the street: no cuffs appear on them")
reb:SetHealth(100)

section("14 November, group A: units shoot back at the fighters shooting them")
local npcR, rstR = LC.Spawners.rebel(C0 + Vector(0, 600, 0))
local unitH, ustH = LC.Spawners.soldier(C0 + Vector(200, 600, 0))
npcR.sim, unitH.sim = false, false
local other = newPlayer("A1Other", "citizen")
LC.SetState(unitH, ustH, "hostile") ustH.enemy = other -- (already after someone else: he used to ignore the fighter)
local rels = {}
local addWas = unitH.AddEntityRelationship
unitH.AddEntityRelationship = function(self, e, d, pr) rels[e] = d if addWas then return addWas(self, e, d, pr) end end
hit(npcR, unitH, 5)
ok(rels[npcR] == D_HT and ustH.rebelFoes and ustH.rebelFoes[npcR] ~= nil, "a unit hit by a fighter hates that fighter, whoever else he was after")
ok(ustH.enemy == other, "(and keeps the enemy he had)")
ustH.rebelFoes[npcR] = CurTime() - 1
rstR.foe = nil
LC.UnitRebelFoesTick(CurTime())
ok(rels[npcR] == D_NU and ustH.rebelFoes[npcR] == nil, "left alone by that fighter for a while: back to ignoring each other")
unitH.AddEntityRelationship = addWas
npcR:Remove() unitH:Remove()

section("14 November, group A: the Administrator is immune to her own")
local adm = newPlayer("A2Admin", "admin")
_run(0.3)
adm:SetPos(C0 + Vector(0, -600, 0))
local cop, cst = LC.Spawners.cop(C0 + Vector(60, -600, 0))
cop.sim = false
ok(LC.IsAdministrator(adm), "(she is the Administrator)")
hit(adm, cop, 5)
ok(cst.enemy ~= adm and cst.state ~= "hostile" and cst.provokedBy ~= adm and not LC.PlayerIsWanted(adm), "she strikes a unit: nobody turns on her, nothing is remembered", tostring(cst.state))
LC.MakeCopsHostile(adm, adm:GetPos(), nil)
ok(cst.enemy ~= adm and cst.state ~= "hostile", "no unit can be set on her")
cst.enemy = adm
adm:SetHealth(15)
ok(LC.NPCTakesIn(cop, adm) == false and not LC.InCustody(adm) and not LC.Struggles[adm], "she is never taken in by a unit")
ok(LC.Incarcerate(adm, 180, "x", cop) == false and LC.MarchToPrison(adm, cop, 180, "x") == false and LC.DetainOnTheSpot(adm, cop, "x") == false,
    "(not by any door of custody either)")
local stopped, dd = hit(cop, adm, 30)
ok(stopped == true and dd:GetDamage() == 0, "a unit's blow or bullet does her no harm")
local guardShot = _dmg(sol, 40)
ok(hook.Run("EntityTakeDamage", adm, guardShot) == true and guardShot:GetDamage() == 0, "nor a soldier's (a guard firing past her)")
local cit = newPlayer("A2Cit", "citizen")
local byPlayer = _dmg(cit, 10)
ok(LC.AdministratorImmune(adm, byPlayer) ~= true and byPlayer:GetDamage() == 10, "(a person can still hurt her)")
adm:SetHealth(100)
LC.RefreshRelations()
ok(cst.rel and cst.rel[adm] == D_LI, "every unit holds her as one of their own")
-- her guards come armed
local bare = { GetActiveWeapon = function() return NULL end, Give = function(self, c) self.got = c end, IsValid = function() return true end }
ok(LC.AdminGuardArm(bare) == true and bare.got == "weapon_ar2", "a guard with empty hands is handed a pulse rifle")
local armed = { GetActiveWeapon = function() return sol end, Give = function(self, c) self.got = c end, IsValid = function() return true end }
ok(LC.AdminGuardArm(armed) == false and armed.got == nil, "(one who has his rifle is left alone)")

section("14 November, group A: the charge is the true one, a fair sentence, no way to shorten it, out of custody")
-- the old charge does not stay on their name
local con = newPlayer("A3Con", "citizen")
_run(0.3)
con:SetPos(C0 + Vector(0, 1400, 0))
local cop3, cst3 = LC.Spawners.cop(C0 + Vector(60, 1400, 0))
cop3.sim = false
LC.ReportCrime(con, "Carrying a weapon (a crowbar)", 60)
ok(LC.WantedReason(con) == "Carrying a weapon (a crowbar)", "wanted: the reason is known")
LC.ClearWanted(con)
ok(LC.WantedReason(con) == "" and con:GetNW2String("lc_wanted_reason", "x") == "", "no longer wanted: the reason is gone with it")
con:SetNW2String("lc_wanted_reason", "Carrying a weapon (a crowbar)") -- (as it used to be left)
con:SetNW2Bool("lc_handsup", true)
cst3.enemy = con
ok(LC.NPCTakesIn(cop3, con) == true and LC.InCustody(con), "taken in while not wanted for anything")
local mm = LC.Marching[con]
local charge = mm and mm.reason or (LC.Prisoners[con] and LC.Prisoners[con].reason)
ok(charge == "Resisting Civil Protection", "the charge is not an old one left on their name", tostring(charge))
con:SetNW2Bool("lc_handsup", false)
LC.FreeFromCustody(con)
-- a sentence adds up the offences of the last 30 minutes; the Resistance get longer (the owner, 15 November)
_setcvar("lc_sentences", 1)
_setcvar("lc_sentence_max", 30)
local function setStanding(p, v) LC.AddStanding(p, v - LC.Standing(p)) end
local function record(p)
    LC.RapClear(p)
    for _, r in ipairs({ "Murder of a Civil Protection officer", "Assaulting Civil Protection", "Sabotage" }) do
        hook.Run("LivingCityWanted", p, r, 60)
    end
end
local function age(p, mins) for _, c in ipairs(LC.RapSheet(p)) do c.at = os.time() - mins * 60 end end
record(con) setStanding(con, -40)
local secs, words = LC.SentenceFor(con, 180, "x", cop3)
ok(secs == 1800 and not tostring(words):find("Civil Standing", 1, true), "three grave offences in the last half hour: the whole of lc_sentence_max, whatever the Civil Standing", tostring(secs) .. " " .. tostring(words))
record(con) age(con, 31)
ok(LC.SentenceFor(con, 180, "x", cop3) == 180 and #LC.RapSheet(con) == 0, "the same offences from more than 30 minutes ago count for nothing: the plain lc_prison_time", #LC.RapSheet(con))
record(con) age(con, 31)
hook.Run("LivingCityWanted", con, "Curfew violation", 60)
ok(LC.SentenceFor(con, 600, "x", cop3) == 180, "an old record and one petty crime just now: 3 minutes")
hook.Run("LivingCityWanted", con, "Sabotage", 60)
age(con, 31)
hook.Run("LivingCityWanted", con, "Sabotage", 60)
ok(LC.SentenceFor(con, 180, "x", cop3) == 480, "an old offence done again counts from now (sabotage: 8 minutes)")
-- the Resistance: twice as long, 10 minutes at least, still no more than the most
LC.RapClear(reb)
hook.Run("LivingCityWanted", reb, "Curfew violation", 60)
local rs, rw = LC.SentenceFor(reb, 180, "x", cop3)
ok(rs == 600 and tostring(rw):find("longer for the Resistance", 1, true) ~= nil, "a Resistance member with one petty crime: 10 minutes, and told why", tostring(rs) .. " " .. tostring(rw))
LC.RapClear(reb)
hook.Run("LivingCityWanted", reb, "Assaulting Civil Protection", 60)
ok(LC.SentenceFor(reb, 180, "x", cop3) == 1200, "assaulting a unit (10): 20 minutes for the Resistance")
record(reb)
ok(LC.SentenceFor(reb, 180, "x", cop3) == 1800, "and never more than lc_sentence_max")
LC.RapClear(reb)
ok(LC.SentenceFor(reb, 180, "x", cop3) == 600, "a Resistance member with nothing on the record: 10 minutes, not lc_prison_time")
LC.RapClear(reb) LC.RapClear(con)
-- who is questioned in the cell: the Resistance, and anyone in for 10 minutes or more (the owner, 15 November)
local function jailedAndAsked(p, secs)
    fresh(p)
    LC.RapClear(p)
    p:SetPos(C0 + Vector(0, 1400, 0))
    p.lcExactSentence = true
    local inCell = LC.Incarcerate(p, secs, "x", nil) == true
    p.lcExactSentence = nil
    _run(14)
    local asked = LC.Interrogations[p] ~= nil
    if LC.EndInterrogation then LC.EndInterrogation(p) end
    LC.FreeFromCustody(p)
    return inCell, asked
end
local inC, asked = jailedAndAsked(con, 240)
ok(inC and not asked, "a citizen in for four minutes is left alone: no questioning", tostring(inC) .. " " .. tostring(asked))
inC, asked = jailedAndAsked(con, 600)
ok(inC and asked, "a citizen in for ten minutes is questioned", tostring(inC) .. " " .. tostring(asked))
inC, asked = jailedAndAsked(reb, 240)
ok(inC and asked, "a Resistance member is questioned whatever the sentence, on a first arrest too", tostring(inC) .. " " .. tostring(asked))
-- (the city stopped while the unit was on his way: nobody comes, so a stopped city stays empty)
do
    fresh(reb)
    reb:SetPos(C0 + Vector(0, 1400, 0))
    reb.lcExactSentence = true
    LC.Incarcerate(reb, 240, "x", nil)
    reb.lcExactSentence = nil
    local running = LC.Running
    LC.Running = false
    ok(LC.StartInterrogation(reb) == false and LC.Interrogations[reb] == nil, "with the city stopped, no unit comes to question anyone")
    LC.Running = running
    LC.FreeFromCustody(reb)
end
-- escaping and walking back in does not shorten a sentence
fresh(con)
LC.RapClear(con)
con:SetPos(C0 + Vector(0, 1400, 0))
con.lcExactSentence = true
ok(LC.Incarcerate(con, 1000, "x", nil) == true and LC.Prisoners[con] ~= nil, "(in a cell for 1000 seconds)")
con.lcExactSentence = nil
LC.EscapePrisoner(con)
ok(not LC.Prisoners[con] and LC.JailOwed(con) > 990, "escaped: what was left is still owed", tostring(LC.JailOwed(con)))
con.lcGraceUntil = nil
con:SetNW2Bool("lc_handsup", true)
con:SetPos(C0 + Vector(1380, 0, 0)) cop3:SetPos(C0 + Vector(1340, 0, 0)) -- (at the cells: straight in)
ok(LC.NPCTakesIn(cop3, con) == true and LC.Prisoners[con] ~= nil, "caught again", tostring(LC.InCustody(con)))
local left = LC.Prisoners[con] and (LC.Prisoners[con].untilT - CurTime()) or 0
ok(left > 990 + 300 and LC.JailOwed(con) == 0, "the new sentence is the escape (6 minutes) and the time they ran from, not 3 minutes", tostring(left))
con:SetNW2Bool("lc_handsup", false)
-- staff: out of custody at once, from every stage
ok(select(1, LC.AdminTool(admin, con, "free")) == true and not LC.InCustody(con) and not LC.PlayerIsWanted(con) and #LC.RapSheet(con) == 0,
    "Admin tools > Out of custody: out of a cell, not wanted, nothing on the record")
ok((con.lcProbationUntil or 0) <= CurTime(), "(and no probation for it)")
fresh(con)
con:SetPos(C0 + Vector(0, 1400, 0)) cop3:SetPos(C0 + Vector(60, 1400, 0))
cst3.marching, cst3.questLock = nil, nil
con:SetNW2Bool("lc_handsup", true)
LC.ReportCrime(con, "Curfew violation", 300)
ok(LC.NPCTakesIn(cop3, con) == true and LC.Marching[con] ~= nil and LC.IsTied(con), "(being marched, cuffed)", tostring(LC.InCustody(con)))
con:SetNW2Bool("lc_handsup", false)
LC.AdminTool(admin, con, "free")
ok(not LC.Marching[con] and not LC.IsTied(con) and not LC.InCustody(con) and not cst3.marching, "out of a march: cuffs off, the unit goes back to his day")
_run(12)
ok(not LC.InCustody(con), "(and it does not go ahead a few seconds later)")
LC.ReportCrime(con, "Curfew violation", 300)
ok(LC.NPCTakesIn(cop3, con) == true and LC.Struggles[con] ~= nil, "(held in a struggle)")
LC.AdminTool(admin, con, "free")
ok(LC.Struggles[con] == nil and con:GetNW2Float("lc_struggle_until", 0) == 0, "out of a struggle")
setStanding(con, 0)
ok(#_errors == errs0, "(no errors in any of it)", _errors[errs0 + 1])
for _, e in ipairs({ sol, cop, cop3 }) do if IsValid(e) then e:Remove() end end
for _, p in ipairs({ reb, adm, cit, con, other }) do p:SetPos(Vector(-121000, -121000, 0)) end
end
Nov14A_CustodyTests()


-- 15 November 2026: people stay (the owner: "they need to be persistent. They stay until they DIE")
function Nov15_PeopleStayTests()
section("People stay: no nameless extras, no timed swap-outs, home and back as themselves")
local P = LC.People
local function alive(role) local n = 0 for _, p in ipairs(P.list) do if p.alive and p.role == role then n = n + 1 end end return n end
local was = GetConVar("lc_citizens"):GetInt()
local set = _setcvar -- (through an alias: the runners keep a written-out setting line for every later section)
set("lc_citizens", 45)
LC.TopUpPeople()
ok(alive("citizen") >= 45, "there are at least as many named citizens as the streets want", alive("citizen"))
set("lc_citizens", was)

-- nobody is given a time to leave
local n, st = LC.SpawnCitizen(Vector(-31000, 30000, 0))
ok(IsValid(n) and st.profile ~= nil, "a citizen on the street is a named person")
ok(st.leaveAt == nil, "and has no timer that sends them away", tostring(st.leaveAt))
local who = st.profile

-- going home: at home for a while, not picked to come out, then free again
local before = 0
for _, c in pairs(LC.LeaveCounts) do before = before + c end
LC.StartLeaving(n, st, false, "worn down: gone home")
ok(who.wentHome ~= nil and who.wentHome >= 240 and who.wentHome <= 480, "someone worn down is home for four to eight minutes", tostring(who.wentHome))
ok(not who.moving, "going home is not leaving the city")
n:Remove()
hook.Run("EntityRemoved", n)
ok(who.alive == true and who.npc == nil, "indoors, they are still alive and still on the roster")
ok((who.homeUntil or 0) > CurTime(), "and at home for now", tostring(who.homeUntil))
local picked = false
for _ = 1, 40 do
    local p = LC.ClaimProfile("citizen")
    if p == who then picked = true end
end
ok(not picked, "while at home they are not brought out as if they were someone new")
who.homeUntil = CurTime() - 1
local back = false
for _, p in ipairs(P.list) do if p.alive and p.role == "citizen" and p ~= who then p.lastSeen = os.time() + 100000 end end
back = LC.ClaimProfile("citizen") == who
ok(back, "their time at home over, the same person comes back out")
for _, p in ipairs(P.list) do if p.lastSeen and p.lastSeen > os.time() + 1000 then p.lastSeen = os.time() end end

-- with everyone out or at home, the streets get nobody rather than a nameless extra
local held = {}
for _, p in ipairs(P.list) do
    if p.alive and p.role == "citizen" and not IsValid(p.npc) and (p.homeUntil or 0) <= CurTime() then held[#held + 1] = p p.homeUntil = CurTime() + 600 end
end
local size = GetConVar("lc_roster_size"):GetInt()
ok(alive("citizen") >= size and LC.PersonAvailable("citizen") == false, "everyone out or at home: nobody is free to come out")
for _, p in ipairs(held) do p.homeUntil = nil end
ok(LC.PersonAvailable("citizen") == true, "and when their time at home is over, they are")

-- the only way out short of dying: despair, with a train in
local n2, st2 = LC.SpawnCitizen(Vector(-31000, 30400, 0))
local p2 = st2.profile
local oldBoard = LC.TrainBoardingPos
LC.TrainBoardingPos = function() return nil end
LC.StartLeaving(n2, st2, false, "despair: gone home")
ok(not p2.moving and p2.wentHome ~= nil, "despair with no train in: they go home")
st2.leaving = nil
LC.TrainBoardingPos = function() return Vector(-31000, 30800, 0) end
LC.StartLeaving(n2, st2, false, "despair: gone home")
ok(p2.moving == true, "despair with a train in: they board it")
LC.TrainBoardingPos = oldBoard
n2:Remove()
hook.Run("EntityRemoved", n2)
ok(p2.alive == false and p2.moved ~= nil and not p2.died, "and are gone to another city: off the roster, not dead")
local n3, st3 = LC.SpawnCitizen(Vector(-31000, 31200, 0))
ok(st3.profile ~= p2, "someone who moved away does not come back")
if IsValid(n3) then n3:Remove() hook.Run("EntityRemoved", n3) end
end
Nov15_PeopleStayTests()

function Nov14E_CameraAimTests()
section("14 November notes, group E: the broadcast camera films the face")
local who = newPlayer("CamAimSpeaker", "citizen")
_run(1)
who:SetPos(Vector(-52000, 21000, 0))
local was = ENT
ENT = {}
assert(loadstring(_ENTSRC["entities/lc_broadcastcam.lua"], "lc_broadcastcam"))()
local def = ENT
ENT = was
local cam = ents.Create("lc_broadcastcam")
cam:SetPos(who:GetPos() + Vector(92, 0, 70))
cam:Spawn()
local aim = def.AimAt(cam, who)
local eye = who:EyePos()
ok(aim.z >= eye.z - 0.5, "it points at their face, not a foot below it (was 12 lower)")
