end
Nov17_AdminHeliTests()

-- The plot against her: an attempt under orders is a coordinated attack, a lone wolf's is not (the owner, 17 November)
function Nov17_AdminPlotTests()
section("17 November: an attempt on the Administrator under orders brings Resistance fighters round the stand; a lone wolf's brings nobody")
LC.EndEvent(true)
if LC.SpeechSession() then LC.EndSpeech() end
if LC.AdminExfil() then LC.AdminExfilEnd(false) end
LC.AdminPlotEnd()
local savedWalls = _walls
local set = _setcvar
local stopsWas, huntWas, manWas = GetConVar("lc_stops"):GetInt(), GetConVar("lc_admin_hunt"):GetInt(), GetConVar("lc_manpower"):GetInt()
set("lc_stops", 0)
set("lc_admin_hunt", 0) -- (the hunt is its own unit's: no squads here)
set("lc_manpower", 1)
set("lc_speech_muster", 60)
-- (18 November: each member a leader sends for has a price, lc_resistance_order_cost. The Resistance's fund holds
-- plenty while this unit runs, so every order in it is paid for out of the fund and nobody's own credits move; the
-- price itself, who pays it and where it goes back is Nov18_ResistanceFundTests' own.)
local fundWas = LC.ResistanceFund()
LC.ResistanceFundAdd(1000000)
-- (18 November: the job is on the board only while nobody leads the Resistance. A Commander or a Lieutenant an
-- earlier unit left playing is a Fighter while this one runs, and put back at its end.)
local strays = {}
for _, p in ipairs(player.GetAll()) do
    if p:GetNW2String("lcf_faction", "") == "resistance" and p:GetNW2Int("lcf_rank", 1) >= 4 then
        strays[p] = p:GetNW2Int("lcf_rank", 1)
        p:SetNW2Int("lcf_rank", 3)
    end
end
local X0 = Vector(152000, -144000, 0)
local function at(x, y) return X0 + Vector(x, y, 0) end
-- a square with a wall round it: the stand and the crowd inside, doorways outside the wall (nobody inside can
-- see those) and four spots inside in plain view
_walls = {
    { a = at(-900, -900), b = at(900, -900) }, { a = at(-900, 1400), b = at(900, 1400) },
    { a = at(-900, -900), b = at(-900, 1400) }, { a = at(900, -900), b = at(900, 1400) },
}
local stand = LC.AddPoint(at(0, 500), 270, "speech", 0)
local crowd = LC.AddPoint(at(0, 0), 90, "speechcrowd", 0)
local points = { stand, crowd }
local HIDDEN = { { 1100, 500 }, { 1100, 1000 }, { 1100, 0 }, { 1100, -400 }, { -1100, 500 }, { -1100, 1000 }, { -1100, 0 }, { -1100, -400 },
    { 0, 1600 }, { 500, 1600 }, { -500, 1600 }, { 0, -950 }, { 300, -950 }, { -300, -950 } }
local OPEN = { { 600, 500 }, { -600, 500 }, { 0, -600 }, { 400, 900 } }
for _, o in ipairs(HIDDEN) do points[#points + 1] = LC.AddPoint(at(o[1], o[2]), 0, "spawn", 0) end
for _, o in ipairs(OPEN) do points[#points + 1] = LC.AddPoint(at(o[1], o[2]), 0, "spawn", 0) end
local pool = LC.ManpowerPool("rebel")
local reserveWas = pool.reserve
pool.reserve = 20
local returned, baseReturn = 0, LC.ManpowerReturn
LC.ManpowerReturn = function(npc) if npc and npc.lcAdminPlot then returned = returned + 1 end return baseReturn(npc) end

local function heard(p, needle)
    local n = 0
    for _, v in ipairs(p.chat or {}) do if string.find(string.lower(tostring(v)), string.lower(needle), 1, true) then n = n + 1 end end
    return n
end
local function xp(p) return tonumber(p:GetPData("lcf_xp_resistance", 0)) or 0 end
local function inCrowd(p, x, y)
    p:SetPos(at(x, y))
    p.aim = Vector(0, 1, 0) -- (looking at the stand)
    p.lcProtectUntil = 0    -- (no longer new in the city)
    p.chat = {}
end
local adm = newPlayer("PlotAdministrator", "admin")
adm:SetPos(at(40000, 0))
local reb = newPlayer("PlotAssassin", "resistance", nil, 400)  -- (Fighters: nobody leads, so the job is on the board)
local wolf = newPlayer("PlotLoneWolf", "resistance", nil, 400)
local cit = newPlayer("PlotBystander", "citizen")
local cop = newPlayer("PlotUnit", "cp")
inCrowd(reb, 0, -300) inCrowd(wolf, 150, -300) inCrowd(cit, -150, -300) inCrowd(cop, 300, 200)
-- every word put on a screen by a notice from here on
local notices, baseNotice = {}, LC.Notice
LC.Notice = function(who, kind, title, text, ...) notices[#notices + 1] = tostring(title) .. " " .. tostring(text) return baseNotice(who, kind, title, text, ...) end

-- (and every line that reaches anyone's screen while the attack's own code runs: their coming, their fight, their going)
local function lines()
    local n = #notices
    for _, p in ipairs(player.GetAll()) do n = n + #(p.chat or {}) end
    return n
end
local during, baseStart, baseThink = 0, LC.AdminPlotStart, LC.AdminPlotThink
LC.AdminPlotStart = function(...) local n = lines() local r = baseStart(...) during = during + (lines() - n) return r end
LC.AdminPlotThink = function(...) local n = lines() local r = baseThink(...) during = during + (lines() - n) return r end
local function paid(p) -- (what the job's own line says it paid)
    for i = #(p.chat or {}), 1, -1 do
        local n = string.match(tostring(p.chat[i]), "Complete: Kill the Administrator %(%+(%d+) XP%)")
        if n then return tonumber(n) end
    end
    return 0
end
local function posted(p)
    for _, x in ipairs((LC.RefreshBoard(p))) do
        if x.tmpl and x.tmpl.id == "res_regicide" and not x.dead then return x end
    end
    return nil
end
local function attackers()
    local n = 0
    for npc in pairs(LC.NPCs) do if IsValid(npc) and npc.lcAdminPlot then n = n + 1 end end
    return n
end
-- her address over and everything of it gone, the assassin free and forgotten
local function tidy()
    if LC.AdminExfil() then
        local guards = LC.AdminExfil().guards
        LC.AdminExfilEnd(false)
        for _, g in ipairs(guards) do if IsValid(g) then g:Remove() end end
    end
    if LC.SpeechSession() then LC.EndSpeech() end
    LC.AdminPlotEnd()
    LC.EndEvent(true)
    LC.AdminAttemptSpoken()
    for _, e in ipairs(ents.FindByClass("lc_adminglass")) do e:Remove() end
    for _, p in ipairs({ reb, wolf }) do
        if LC.Prisoners[p] then LC.ReleasePrisoner(p) end
        LC.AdminForget(p)
        LC.ClearWanted(p)
        if LC.QuestOf[p] then LC.AbandonQuest(p) end
        p.lcqNext = 0
        -- (what the job paid would make a Lieutenant of them in time, and a leader: Fighters again)
        p:SetPData("lcf_xp_resistance", 400)
        LC.AddXP(p, 0)
    end
end
local function address()
    tidy()
    LC.CallSpeech(nil, nil)
    local S = LC.SpeechSession()
    return S and S.her
end
local function take(p)
    local j = posted(p)
    p.lcqNext = 0
    return j ~= nil and LC.AcceptPosting(p, j.id) == true
end
-- is Kill the Administrator on the board as it is sent to them?
local function onBoard(p)
    local sent, realSend = nil, LC.SendCompressed
    LC.SendCompressed = function(msg, tbl, rec) if msg == "lcq_board" and rec and rec[1] == p then sent = tbl end return realSend(msg, tbl, rec) end
    LC.SendBoard(p)
    LC.SendCompressed = realSend
    for _, x in ipairs(sent and sent.postings or {}) do if x.title == "Kill the Administrator" then return true end end
    return false
end

-- the job: on the Resistance's board while her address is on, and nobody else's
ok(posted(reb) == nil, "with no address on, Kill the Administrator is not on the Resistance's board")
local her = address()
ok(IsValid(her), "(the city is called to her address)")
local job = posted(reb)
ok(job ~= nil and job.title == "Kill the Administrator" and job.desc == "At her address. Our fighters open fire when you do.",
    "from the call it is on the Resistance's board: a title and one short line", job and job.desc)
ok(posted(cit) == nil and posted(cop) == nil and posted(adm) == nil, "and on nobody else's: not the citizens', the units' or her own")
ok(heard(reb, "New job") == 0 and heard(wolf, "Kill the Administrator") == 0, "(nobody is told in words that it is there)")
local st1 = job and job.stages[1]
ok(job and #job.stages == 1 and st1.kind == "count" and st1.event == "admin_attempt" and st1.pos:Distance(stand.pos) < 1,
    "its one step is making the attempt, marked at the stand: never a place to stand and wait")
local found = 0
for _, t in ipairs(LC.QuestTemplates) do
    if t.id == "res_regicide" then
        found = found + 1
        ok(t.factions.resistance and table.Count(t.factions) == 1 and not t.violent, "(the Resistance's alone; no squad of its own comes with it)")
    end
end
ok(found == 1, "(one such job)", found)

-- a lone wolf: her guards get her out, he is marked, and nobody comes
local r0 = pool.reserve
LC.AdminAttempt(her, wolf, "shot")
ok(LC.AdminExfil() ~= nil and LC.AdminNeverForgotten(wolf), "a lone wolf's attempt: her guards get her out and he is marked, as before")
_run(2)
ok(LC.AdminPlot() == nil and attackers() == 0, "and no fighter comes: he is on his own", attackers())
ok(posted(reb) == nil, "(the job nobody took is off the board with her address)")

-- Fighters and up only (the owner, 17 November): below that rank it is not on their board, and not theirs to take
her = address()
local low = newPlayer("PlotLowRank", "resistance", nil, 150)
_run(0.3)
local sentLow, realSendB = nil, LC.SendCompressed
LC.SendCompressed = function(msg, tbl, rec) if msg == "lcq_board" and rec and rec[1] == low then sentLow = tbl end return realSendB(msg, tbl, rec) end
LC.SendBoard(low)
LC.SendCompressed = realSendB
local onLow = false
for _, x in ipairs(sentLow and sentLow.postings or {}) do if x.title == "Kill the Administrator" then onLow = true end end
ok(LCF.RankOf(low).name == "Member" and sentLow ~= nil and not onLow, "a Member's board does not show Kill the Administrator", LCF.RankOf(low).name)
low.chat = {}
ok(not take(low) and LC.QuestOf[low] == nil and LC.AdminPlotHolds(low) == nil and #low.chat == 0, "nor can they take it, and nothing is said")
local sentReb
LC.SendCompressed = function(msg, tbl, rec) if msg == "lcq_board" and rec and rec[1] == reb then sentReb = tbl end return realSendB(msg, tbl, rec) end
LC.SendBoard(reb)
LC.SendCompressed = realSendB
local onReb = false
for _, x in ipairs(sentReb and sentReb.postings or {}) do if x.title == "Kill the Administrator" then onReb = true end end
ok(onReb and LCF.RankOf(reb).name == "Fighter", "a Fighter's board shows it", LCF.RankOf(reb).name)
low:Remove()
-- under orders: the job taken, the attempt made
ok(take(reb), "a member of the Resistance takes the job")
wolf.chat = {}
ok(not take(wolf) and LC.QuestOf[wolf] == nil and heard(wolf, "That job has enough people") == 1, "one holder at a time: a second cannot join it", table.concat(wolf.chat or {}, " | "))
ok(LC.AdminPlotHolds(reb) == "job" and LC.AdminPlotHolds(wolf) == nil and LC.AdminPlotHolds(cit) == nil, "holding it is what makes an attempt an ordered one")
local xp0, cr0 = xp(reb), LC.Credits(reb)
reb.chat, cit.chat, cop.chat, wolf.chat = {}, {}, {}, {}
notices = {}
r0 = pool.reserve
LC.AdminAttempt(her, reb, "shot")
local A = LC.AdminExfil()
local P = LC.AdminPlot()
local fighters = {}
for _, f in ipairs(P and P.fighters or {}) do
    fighters[#fighters + 1] = f
    f.sim = false -- (they stand where they are in this pretend world; a check puts one where it wants him)
end
ok(#fighters == 7 or #fighters == 8, "seven or eight fighters come out round the stand", #fighters)
ok(pool.reserve == r0 - #fighters, "each out of the Resistance's reserve, as any fighter sent", pool.reserve)
local seen, hers, own, apart, quarters, nq = 0, 0, 0, true, {}, 0
for i, f in ipairs(fighters) do
    local fst = LC.NPCs[f]
    if LC.IsSeen(f:GetPos() + Vector(0, 0, 50)) then seen = seen + 1 end
    if LC.AdminTargets[f] then hers = hers + 1 end
    if fst and fst.role == "rebel" and fst.unmanaged and f:GetClass() == "npc_citizen" and f:GetNW2Bool("lc_prebel", false) then own = own + 1 end
    for j = i + 1, #fighters do if f:GetPos():Distance(fighters[j]:GetPos()) < 250 then apart = false end end
    local d = f:GetPos() - stand.pos
    local quarter = math.floor((math.atan2(d.y, d.x) + math.pi) / (2 * math.pi) * 4) % 4
    if not quarters[quarter] then quarters[quarter] = true nq = nq + 1 end
end
ok(seen == 0, "none of them where a player can see as they appear", seen)
ok(nq == 4 and apart, "from every side of the stand, and no two together", nq)
ok(own == #fighters, "the Resistance's own fighters, on top of the city's numbers", own)
ok(hers == #fighters, "every one of them is someone her guards may hurt (LC.AdminTargets)", hers)
ok(A and A.attackers[reb] and LC.AdminNeverForgotten(reb) and LC.Standing(reb) == -999 and LC.PlayerIsWanted(reb),
    "the assassin's own punishment is as it was: marked, -999, wanted")
ok(LC.QuestOf[reb] == nil and xp(reb) >= xp0 + 250 and paid(reb) == 250 and heard(reb, "Complete: Kill the Administrator") == 1,
    "the job is done and paid as the attempt is made: 250 experience for trying", xp(reb) - xp0)
ok(LC.Credits(reb) == cr0 + 100, "and a stipend of 100 credits in all (the board's usual pay is part of it)", LC.Credits(reb) - cr0)
ok(LC.AdminPlotHolds(reb) == nil, "and it is over: nothing is held any more")

-- whom they fight, and whom they cannot hurt
local guard = A and A.guards[1]
local f1 = fighters[1]
cop:SetPos(at(40000, 500)) -- (the unit has run for it)
f1:SetPos(at(200, 300)) -- (one of them has come in through a doorway: her guards are in front of him)
LC.AdminPlotThink(CurTime())
local fst = LC.NPCs[f1]
local foe = fst and fst.foe
local foeSt = IsValid(foe) and LC.NPCs[foe]
ok(foeSt and LC.IsSecurity(foeSt) and f1.rel[foe] == D_HT and f1:GetEnemy() == foe, "a fighter who sees her guards fires on them", tostring(foe))
ok(IsValid(foe) and foe.rel[f1] == D_HT, "and the guard he fires on is his enemy too")
ok(fst.state == "event" and not fst.raid, "(the attack's own to move: no raid, no shout, no dispatch line)")
-- a unit player is theirs to fight as well (the two of them south of the wall, where no guard is in sight)
cop:SetPos(at(0, -1700))
local f2 = fighters[2]
local f2From = LC.NPCs[f2].plotFrom
f2:SetPos(at(60, -1700))
LC.NPCs[f2].foe, LC.NPCs[f2].plotLook = f2, 0 -- (whoever he was after from his doorway: nobody now)
LC.AdminPlotThink(CurTime())
local e2 = LC.NPCs[f2] and LC.NPCs[f2].foe
ok(e2 == cop and LC.NPCs[f2].rel[cop] == D_HT, "so is a unit player they can see",
    (e2 == f2 and "nobody" or tostring(e2 and e2.cls)) .. " at " .. tostring(IsValid(e2) and (e2:GetPos() - X0)) .. ", he at " .. tostring(f2:GetPos() - X0)
    .. ", sees the unit " .. tostring(LC.RebelCanSee(f2, cop, 2500)) .. ", a foe to them " .. tostring(LC.RebelLooksCombine(cop)))
f2:SetPos(f2From) -- (and back behind his own wall)
cop:SetPos(at(300, 200))
ok(IsValid(guard) and hook.Run("EntityTakeDamage", f1, _dmg(guard, 10)) ~= true and hook.Run("EntityTakeDamage", cit, _dmg(guard, 10)) == true,
    "her guards' fire hurts the fighters, and still never a bystander")
local npcCitizen = LC.Spawners.citizen and LC.Spawners.citizen(at(-200, -350))
ok(hook.Run("EntityTakeDamage", cit, _dmg(f1, 10)) == true and hook.Run("EntityTakeDamage", reb, _dmg(f1, 10)) == true,
    "a fighter's fire never hurts a citizen or one of the Resistance")
ok(IsValid(npcCitizen) and hook.Run("EntityTakeDamage", npcCitizen, _dmg(f1, 10)) == true, "nor one of the city's own citizens")
ok(hook.Run("EntityTakeDamage", cop, _dmg(f1, 10)) ~= true, "a unit it does")
f1.lcAdminPlot = nil
ok(hook.Run("EntityTakeDamage", cit, _dmg(f1, 10)) ~= true, "(that is the attack's own rule: any other fighter's stray round is as it was)")
f1.lcAdminPlot = true
if IsValid(npcCitizen) then npcCitizen:Remove() end
-- nobody of the Resistance, no citizen and never her is among those they may fight
local wrong = 0
for _ = 1, 6 do
    LC.AdminPlotThink(CurTime())
    for _, f in ipairs(fighters) do
        local e = IsValid(f) and LC.NPCs[f] and LC.NPCs[f].foe
        if e and e ~= f and (e == reb or e == wolf or e == cit or e == her or e == adm) then wrong = wrong + 1 end
    end
    _run(0.5)
end
ok(wrong == 0, "none of them takes a citizen, a Resistance player or her for a foe", wrong)

-- every one of them is at it: fighting one of the Combine, or (nobody in sight from behind his wall) running in
for _, f in ipairs(fighters) do if LC.NPCs[f] then LC.NPCs[f].goingTo = nil end end
LC.AdminPlotThink(CurTime())
local idle = 0
for _, f in ipairs(fighters) do
    local s = IsValid(f) and LC.NPCs[f]
    if s then
        local e = s.foe
        local fighting = IsValid(e) and e ~= f and (e == cop or (LC.NPCs[e] ~= nil and LC.IsSecurity(LC.NPCs[e])))
        local running = f.goal ~= nil and f.sched == SCHED_FORCED_GO_RUN
        if not fighting and not running then idle = idle + 1 end
    end
end
ok(idle == 0, "every one of them is fighting one of the Combine, or running in toward them", idle)

-- one falls: lost to the reserve, and not the assassin caught
local pend = LC.AdminAttemptPending()
local dead = fighters[#fighters]
dead:SetHealth(0)
hook.Run("OnNPCKilled", dead, guard, guard)
dead:Remove()
ok(pend ~= nil and not pend.caught, "a fighter falling is not the assassin caught: her next address still calls the traitor free")
ok(returned == 0, "(the dead are lost to the reserve)")

-- she is gone: they fight on a little, then break off and leave out of sight
_run(5)
LC.AdminExfilEnd(false)
LC.AdminPlotThink(CurTime())
ok(LC.AdminPlot() ~= nil and LC.AdminPlot().phase == "fight" and IsValid(fighters[2]), "she is away: they fight on a little while")
f1:SetPos(at(200, 300)) -- (still in the square, in plain view)
_run(42)
LC.AdminPlotThink(CurTime())
P = LC.AdminPlot()
local left = 0
for _, f in ipairs(fighters) do if IsValid(f) then left = left + 1 end end
ok(P ~= nil and P.phase == "leave" and left == 1 and IsValid(f1), "forty seconds in they break off: those nobody can see are gone, the one being watched is still running", left)
ok(LC.NPCs[f1] and LC.NPCs[f1].foe == f1 and not IsValid(f1:GetEnemy()) and f1.goal ~= nil and f1.goal:Distance(LC.NPCs[f1].plotFrom) < 5
    and f1.sched == SCHED_FORCED_GO_RUN, "he has let his enemy be and runs back the way he came", tostring(f1.goal and (f1.goal - X0)))
f1:SetPos(LC.NPCs[f1].plotFrom) -- (through his doorway, out of sight)
_run(2)
ok(not IsValid(f1) and LC.AdminPlot() == nil and attackers() == 0, "out of sight he is gone too, and it is over")
ok(returned == #fighters - 1, "the living are back in the Resistance's reserve, as after any skirmish", returned)
local said = {}
for _, needle in ipairs({ "fighter", "our people", "ambush", "coordinated" }) do
    for _, p in ipairs({ cit, cop, wolf, reb }) do
        for _, v in ipairs(p.chat or {}) do if string.find(string.lower(tostring(v)), needle, 1, true) then said[#said + 1] = p:Nick() .. ": " .. tostring(v) end end
    end
    for _, n in ipairs(notices) do if string.find(string.lower(n), needle, 1, true) then said[#said + 1] = "notice: " .. n end end
end
ok(#said == 0 and during == 0, "nothing about the attack was put on anyone's screen: no chat line, no notice, from their coming to their going", during .. " " .. table.concat(said, " | "))
ok(heard(reb, "Kill the Administrator") == 1, "(the assassin read one line of it: the job's own, done)", table.concat(reb.chat or {}, " | "))

-- a place with few doorways: two or three come out of each, a step apart, still where nobody can see
local few = LC.AdminPlotSpots(at(0, 9000), 8) -- (nothing of the city's within reach of there)
ok(#few == 0, "(nowhere of the city's to come from: nobody)", #few)
local lone = { LC.AddPoint(at(1100, 9500), 0, "spawn", 0), LC.AddPoint(at(-1100, 9500), 0, "spawn", 0), LC.AddPoint(at(0, 10600), 0, "spawn", 0) }
few = LC.AdminPlotSpots(at(0, 9500), 8)
local crowded, tight = 0, false
for i, a in ipairs(few) do
    local near = 0
    for j, b in ipairs(few) do
        if a:Distance(b) < 250 then near = near + 1 end
        if i ~= j and a:Distance(b) < 80 then tight = true end
    end
    if near > 3 then crowded = crowded + 1 end
end
ok(#few == 8 and crowded == 0 and not tight, "three doorways: all eight still come, two or three from each and a step apart", #few)
for _, pt in ipairs(lone) do LC.RemovePoint(pt) end

-- short of fighters: fewer; none left: nobody, and the job still pays
her = address()
ok(take(reb), "(the job again, at her next address)")
pool.reserve = 3
LC.AdminAttempt(her, reb, "shot")
P = LC.AdminPlot()
ok(P ~= nil and #P.fighters == 3 and pool.reserve == 0, "a reserve of three sends three", P and #P.fighters)
her = address()
ok(take(reb), "(and again)")
pool.reserve = 0
xp0 = xp(reb)
LC.AdminAttempt(her, reb, "shot")
ok(LC.AdminPlot() == nil and attackers() == 0, "an empty reserve sends nobody")
ok(LC.QuestOf[reb] == nil and xp(reb) >= xp0 + 250, "(the attempt was made all the same: the job is paid)")
pool.reserve = 20

-- her address ends with nothing tried: the job is called off
her = address()
ok(take(reb), "(taken once more)")
LC.EndSpeech()
_run(1.5)
ok(LC.QuestOf[reb] == nil and heard(reb, "Failed: Kill the Administrator") == 1 and attackers() == 0, "her address over with nothing tried: the job is called off")

-- a player in the post, shot in the game's own way; and dying of it pays more
tidy()
adm:SetPos(at(0, 520))
adm:SetHealth(100)
adm.lcProtectUntil = 0
ok(LC.CallSpeech(adm, "Citizens."), "(a player Administrator's address)")
ok(take(reb), "(the job is on the board for hers too)")
xp0 = xp(reb)
hook.Run("EntityTakeDamage", adm, _dmg(reb, 20))
_run(0.1)
P = LC.AdminPlot()
ok(LC.AdminExfil() ~= nil and P ~= nil and #P.fighters >= 7 and LC.QuestOf[reb] == nil, "a shot at a player Administrator by the one who holds the job: the same", P and #P.fighters)
local plain = paid(reb)
ok(plain == 250 and xp(reb) - xp0 >= 250, "(250 for the attempt)", plain)
tidy()
adm:SetPos(at(0, 520))
set("lc_admin_exfil", 0) -- (her guards' exit switched off: a hit that kills her is a kill)
LC.CallSpeech(adm, "Again.")
ok(take(reb), "(once more)")
reb.chat = {}
adm.alive = false
hook.Run("PlayerDeath", adm, reb, reb)
ok(LC.QuestOf[reb] == nil and paid(reb) >= plain + 40, "she dies of it: forty more", paid(reb))
ok(LC.AdminPlot() ~= nil, "(and the fighters come for her guards all the same)")
adm.alive = true
set("lc_admin_exfil", 1)

-- the leader's order (the owner, 18 November): sent for by name from F2, a word with the leader, then the order
tidy()
adm:SetPos(at(40000, 0))
do
local KEY = "lc_adminplot_order"
local function kept(p) return p:GetPData(KEY, "") end
local function pick(by, p, what) return LC.QuickMore(by, "plotorder", p:EntIndex() .. ":" .. what) == true end -- (as F2 sends it)
local function listed(by, p) -- (their line on the leader's list, or nil)
    for _, w in ipairs(LC.AdminPlotList(by) or {}) do if w.id == p:EntIndex() then return w end end
    return nil
end
local function word(p) -- (the job to speak with the leader, if they are in it)
    local q = LC.QuestOf[p]
    if q and not q.done and q.tmpl and q.tmpl.id == "res_word" then return q end
    return nil
end
local function tracker(p) -- (what their screen is sent of their job)
    local sent, realSend = nil, LC.SendCompressed
    LC.SendCompressed = function(msg, tbl, rec) if msg == "lcq_state" and rec and rec[1] == p then sent = tbl end return realSend(msg, tbl, rec) end
    p.lcQStateKey = nil
    LC.SendQuestState(p)
    LC.SendCompressed = realSend
    return sent or {}
end
local function press(a, b) -- (a walks up to b and presses E at them)
    a:SetPos(b:GetPos() + Vector(60, 0, 0))
    a.lookingAt = b
    hook.Run("KeyPress", a, IN_USE)
    a.lookingAt = nil
end
local radioed, baseRadio = 0, LC.RadioNotice
LC.RadioNotice = function(...) radioed = radioed + 1 return baseRadio(...) end
local function gone(p) hook.Run("PlayerDisconnected", p) p:Remove() end
local function fighter(name) local p = newPlayer(name, "resistance", nil, 400) p.chat, p.lcProtectUntil = {}, 0 return p end
local function back(p, name) -- (the same person joins again: a new connection, the same saved data)
    local n = _makeplayer(name, p:GetPos())
    n.sid, n.pdata = p.sid, p.pdata
    hook.Run("PlayerInitialSpawn", n)
    if n:GetNW2String("lcf_faction", "") ~= "resistance" then LC.SetFaction(n, "resistance", nil, true) end
    n.chat, n.lcProtectUntil = {}, 0
    return n
end
local sentFor = LC.AdminPlotSentFor
local name = LC.CharacterName
-- a job on the Resistance's board that anyone of theirs can take (nothing of the city's own: it is only there to be taken)
local nextPost = 990000
local function posting()
    nextPost = nextPost + 1
    local p = { id = nextPost, title = "Count the crates", desc = "", reward = 5, limit = 600, faction = "resistance", expiresPost = CurTime() + 900,
        tmpl = { id = "test_crates", factions = { resistance = true } }, data = {},
        stages = { { kind = "count", event = "test_crates", need = 1, text = "Count them." } } }
    LC.Postings.resistance = LC.Postings.resistance or {}
    table.insert(LC.Postings.resistance, 1, p)
    return p
end
local function failed(p) return heard(p, "Failed:") end

-- who may give it: a Commander; a Lieutenant when no Commander is playing; nobody else
ok(LC.AdminPlotLeading() == false and LC.AdminPlotLeader(reb) == false and LC.AdminPlotList(reb) == nil, "with only Fighters playing nobody leads, and nobody has the list")
local leader = newPlayer("PlotLieutenant", "resistance", nil, 900)
local member, second, third = fighter("PlotFighter"), fighter("PlotSecond"), fighter("PlotThird")
local lowly = newPlayer("PlotMember", "resistance", nil, 150)
inCrowd(leader, 100, -200) inCrowd(member, -100, -200) inCrowd(second, -200, -200) inCrowd(third, -300, -200) inCrowd(lowly, 200, -200)
ok(LCF.RankOf(leader).name == "Lieutenant" and LC.AdminPlotLeader(leader) == true and LC.AdminPlotLeading() == true,
    "a Lieutenant may give the order while no Commander is playing", LCF.RankOf(leader).name)
ok(LC.AdminPlotLeader(member) == false and LC.AdminPlotLeader(lowly) == false and LC.AdminPlotLeader(cit) == false
    and LC.AdminPlotLeader(cop) == false and LC.AdminPlotLeader(adm) == false, "nobody else may: not a Fighter, a Member, a citizen, a unit or her")
ok(LC.QuickInfo(leader).plot ~= nil and listed(leader, member) ~= nil, "(and the Lieutenant has the list on F2)")
local commander = newPlayer("PlotCommander", "resistance", nil, 1800)
inCrowd(commander, 0, -200)
ok(LCF.RankOf(commander).name == "Commander" and LC.AdminPlotLeader(commander) == true and LC.AdminPlotLeader(leader) == false,
    "with a Commander playing it is the Commander's alone: the Lieutenant may not", LCF.RankOf(commander).name)
ok(LC.AdminPlotList(leader) == nil and LC.QuickInfo(leader).plot == nil and not pick(leader, member, "give") and sentFor(member) == nil and #member.chat == 0,
    "(the Lieutenant's F2 has no list now, and a name sent all the same does nothing)")

-- the list: Fighters and up by name, the leader among them
ok(listed(commander, commander) and listed(commander, leader) and listed(commander, member) and listed(commander, second)
    and listed(commander, reb) and listed(commander, wolf), "the leader's list has the Resistance's Fighters and up, the leader among them")
ok(listed(commander, lowly) == nil and listed(commander, cit) == nil and listed(commander, cop) == nil and listed(commander, adm) == nil,
    "and nobody else: no Member, no citizen, no unit, not her")
local row = listed(commander, member)
ok(row and row.name == name(member) and row.has == nil, "(each by their name; nobody has anything of it yet)", row and row.name)
local f2 = LC.QuickInfo(commander).plot
ok(f2 ~= nil and #f2 == #LC.AdminPlotList(commander), "F2 sends the list to the leader")
ok(LC.QuickInfo(member).plot == nil and LC.QuickInfo(lowly).plot == nil and LC.QuickInfo(cit).plot == nil and LC.QuickInfo(cop).plot == nil,
    "and to nobody else")

-- a name sends for that member: one private line, and a job of their own at once
ok(LC.SpeechSession() == nil, "(no address is on: the leader prepares)")
local everyone = { commander, leader, member, second, third, lowly, reb, wolf, cit, cop, adm }
local function hush() for _, p in ipairs(everyone) do p.chat = {} end notices = {} radioed = 0 end
local function read(except) -- (lines on every screen but theirs)
    local n = #notices
    for _, p in ipairs(everyone) do if p ~= except then n = n + #(p.chat or {}) end end
    return n
end
hush()
ok(pick(commander, member, "give") and sentFor(member) == commander, "the leader picks a name on F2: that member is sent for")
local line = member.chat[1]
ok(#member.chat == 1 and line == "[Freq 7] " .. name(commander) .. " wants a word with you, in private.",
    "the member reads one line: who wants a word with them, in private", table.concat(member.chat, " | "))
ok(line and not string.find(string.lower(line), "administrator", 1, true) and not string.find(string.lower(line), "kill", 1, true), "(and not what about)")
ok(read(member) == 0 and radioed == 0, "nobody else reads anything: not the leader, another member, a citizen, a unit or her; nothing on the radio", read(member) .. " " .. radioed)
local q = word(member)
local tr = tracker(member)
ok(q ~= nil and q.title == "A word with " .. name(commander) and #q.stages == 1 and q.stages[1].text == "Speak with " .. name(commander) .. ", in private.",
    "and they are in a job of their own at once, with nothing to accept: a title and one line", q and q.title)
ok(tr.active == true and tr.title == (q and q.title) and tr.objective == (q and q.stages[1].text) and tr.ent == commander:EntIndex(),
    "on their screen as any job is, its marker on the leader", tostring(tr.title) .. " / " .. tostring(tr.ent))
ok(tr.nolimit == true and q ~= nil and q.expires - CurTime() > 86400 * 365, "it has no time limit: no clock on their screen")
ok(q ~= nil and q.reward == 0 and q.stages[1].kind == "count" and q.stages[1].secs == nil, "(nothing paid; its one step is an act, never a place to stand)")
ok(LC.AdminPlotHolds(member) == nil and kept(member) == "word" and listed(commander, member).has == "word" and listed(commander, second).has == nil,
    "the order is not theirs yet: the list shows them as sent for")
_run(6)
ok(word(member) == q and sentFor(member) == commander, "(and it stands as time goes by)")
hush()
ok(LC.AdminPlotAssign(commander, member) == false and pick(commander, member, "give") and word(member) == q and read(nil) == 0,
    "sent for a second time: nothing new, no second line, the same job")

-- until that word is had, every door that work comes through is shut, with one short reason
local first = name(commander) .. " wants a word with you first."
ok(LC.AdminPlotBusy(member) == first and LC.AdminPlotBusy(second) == nil and LC.AdminPlotBusy(cit) == nil and LC.AdminPlotBusy(commander) == nil,
    "until then no other work for them, and them alone: one short reason", tostring(LC.AdminPlotBusy(member)))
local post = posting()
member.chat, member.lcqNext = {}, 0
ok(LC.AcceptPosting(member, post.id) == false and word(member) == q and post.q == nil and #member.chat == 1 and member.chat[1] == "[Miscount] " .. first,
    "door 1, the board (a job taken or joined, a story's part, a Union shift, a job over the radio, a foreman's work order): shut", table.concat(member.chat, " | "))
local story = (LC.StoryPostings(member) or {})[1]
ok(story == nil or (LC.AcceptPosting(member, story.id) == false and word(member) == q), "(a story's part comes through that door: shut)")
local union
for _, o in ipairs(LCJ.Occupations) do union = union or o.id end
local okW, whyW = LC.SetJob(member, union)
ok(okW == false and whyW == first and member:GetNW2String("lcj_job", "") == "", "door 2, a Union job from F4: shut", tostring(whyW))
okW, whyW = LC.LaborCanAct(member, "assign")
ok(okW == false and whyW == first, "door 3, the Labor Assignment terminal: shut", tostring(whyW))
local planWas = LC.OpPlan
LC.OpPlan = { by = commander, label = "Raid the data terminal", kind = "heist", pos = at(0, 0), data = {}, fireAt = CurTime() + 600, joined = { [commander] = true } }
okW, whyW = LC.JoinOp(member)
ok(okW == false and whyW == first and LC.OpPlan.joined[member] == nil, "door 4, joining a planned operation: shut", tostring(whyW))
LC.OpPlan.joined[member] = true
ok(LC.JoinOp(member) == true and LC.OpPlan.joined[member] == nil, "(backing out of one they had joined is theirs still)")
LC.OpPlan = nil
member.lcJobOffer = { from = cit, at = CurTime() }
okW, whyW = LC.AcceptJob(member, true)
ok(okW == false and whyW == first and member.lcJobOffer ~= nil and member:GetPData("lc_employer", "") == "", "door 5, a stall owner's job offer: shut, and the offer waits", tostring(whyW))
member.lcJobOffer = nil
member.chat = {}
ok(LC.ManhuntWayOut(member) == false and #member.chat == 0, "(the job a hunted fighter is handed, to go to ground, is not handed to them either, and nothing is said)")
-- (planning an operation: someone who may plan one, sent for)
hush()
ok(pick(commander, leader, "give") and sentFor(leader) == commander and LC.CanPlanOp(leader) == true, "(the Lieutenant is sent for too)")
leader.lcOpTargets = { { label = "Raid the data terminal", kind = "heist", pos = at(0, 0), data = {} } }
okW, whyW = LC.PlanOp(leader, 1, 2)
ok(okW == false and whyW == name(commander) .. " wants a word with you first." and LC.OpPlan == nil, "door 4 again, planning an operation: shut", tostring(whyW))
leader.lcOpTargets = nil
LC.OpPlan = planWas
-- and it is not theirs to drop
member.chat = {}
ok(LC.DropQuest(member) == false and word(member) == q, "they cannot drop it")
_netcall("lcq_abandon", member)
hook.Run("PlayerSay", member, "!abandon", false)
ok(word(member) == q and sentFor(member) == commander and #member.chat == 0, "(not by the board's button, not by typing it; and nothing is said)", table.concat(member.chat, " | "))

-- way 1: the member presses E at the leader, within reach
hush()
member:SetPos(commander:GetPos() + Vector(600, 0, 0))
member.lookingAt = commander
hook.Run("KeyPress", member, IN_USE)
member.lookingAt = nil
ok(word(member) == q, "(E from across the square is not a word with anyone)")
press(member, second)
ok(word(member) == q, "(nor is E at someone else)")
cop:SetPos(commander:GetPos() + Vector(0, 40, 0)) -- (a unit right beside the leader: who else is near is never asked)
press(member, commander)
ok(word(member) == nil and LC.QuestOf[member] == nil and sentFor(member) == nil and LC.AdminPlotHolds(member) == "order" and kept(member) == "1",
    "way 1: the member presses E at the leader, within reach: the job is done and the order is theirs")
ok(tracker(member).active == false and read(nil) == 0 and radioed == 0, "it leaves their screen, and nothing is said: no line, to them or anyone", read(nil))
ok(LC.AdminPlotBusy(member) == nil and listed(commander, member).has == "order" and (member.lcqNext or 0) <= CurTime(), "other work is theirs again, with no wait; the list shows them under the order")
cop:SetPos(at(300, 200))
-- way 2: the leader presses E at the member
ok(pick(commander, second, "give") and word(second) ~= nil, "(another member is sent for)")
second.aim = Vector(-1, 0, 0)
commander:SetPos(second:GetPos() + Vector(60, 0, 0))
commander.aim = Vector(1, 0, 0) -- (looking the other way)
hook.Run("KeyPress", commander, IN_USE)
ok(word(second) ~= nil, "(E with their back to them is not a word)")
commander.aim = Vector(-1, 0, 0) -- (their way, near enough)
hook.Run("KeyPress", commander, IN_USE)
ok(word(second) == nil and LC.AdminPlotHolds(second) == "order" and kept(second) == "1", "way 2: the leader presses E at the member: done, and the order is theirs")
commander.aim = Vector(0, 1, 0)
-- way 3: the leader's list
ok(pick(commander, third, "give") and word(third) ~= nil and LC.AdminPlotHolds(third) == nil, "(a third is sent for)")
ok(not LC.AdminPlotSpoken(member, third) and not pick(leader, third, "spoken") and word(third) ~= nil, "(nobody but the leader says so)")
hush()
ok(pick(commander, third, "spoken") and word(third) == nil and LC.AdminPlotHolds(third) == "order" and kept(third) == "1" and read(nil) == 0,
    "way 3: the leader picks their name on the list again: done, the order is theirs, and nothing is said")
ok(pick(commander, third, "spoken") and LC.AdminPlotHolds(third) == "order" and pick(commander, third, "give") and LC.AdminPlotHolds(third) == "order" and word(third) == nil,
    "(a list out of date does no harm: spoken with, or sent for, again changes nothing)")
ok(pick(commander, wolf, "spoken") and sentFor(wolf) == nil and LC.AdminPlotHolds(wolf) == nil, "(and nobody is under the order who was never sent for)")
-- taken back: nothing is said
hush()
ok(pick(commander, third, "back") and LC.AdminPlotHolds(third) == nil and kept(third) == "" and listed(commander, third).has == nil, "their name once more takes it back")
ok(read(nil) == 0 and radioed == 0, "and nothing is said, to them or to anyone", read(nil))
-- only to Fighters and up of the Resistance, and only by the leader
ok(not pick(commander, lowly, "give") and not pick(commander, cit, "give") and not pick(commander, cop, "give") and not pick(commander, adm, "give")
    and sentFor(lowly) == nil and sentFor(cit) == nil and sentFor(cop) == nil and kept(lowly) == "" and kept(cit) == "" and LC.QuestOf[lowly] == nil,
    "a Member, a citizen, a unit or she cannot be sent for")
ok(not pick(member, wolf, "give") and not pick(lowly, wolf, "give") and not pick(cit, wolf, "give") and not pick(cop, wolf, "give") and sentFor(wolf) == nil,
    "and nobody but the leader sends for anyone")
ok(read(nil) == 0, "(nothing is said of any of that)", read(nil))
ok(pick(commander, commander, "give") and LC.AdminPlotHolds(commander) == "order" and word(commander) == nil and read(nil) == 0,
    "a leader who picks themselves has the order at once, and reads nothing")
pick(commander, commander, "back")
ok(LC.AdminPlotHolds(commander) == nil, "(and gives it up the same way)")

-- the attempt: the fighters come, the one who made it is paid what the job pays, and only their order is done
her = address()
ok(IsValid(her) and LC.AdminPlotHolds(member) == "order" and LC.AdminPlotHolds(second) == "order", "(two members under the order, given before her address was called)")
ok(sentFor(leader) == commander and LC.AdminPlotHolds(leader) == nil, "(and one sent for who has not spoken yet: not under it)")
local mxp, mcr, sxp, scr = xp(member), LC.Credits(member), xp(second), LC.Credits(second)
pool.reserve = 20
hush()
LC.AdminAttempt(her, member, "shot")
P = LC.AdminPlot()
ok(P ~= nil and #P.fighters >= 7 and pool.reserve == 20 - #P.fighters, "one of them makes the attempt: the fighters come", P and #P.fighters)
ok(xp(member) >= mxp + 250 and xp(member) < mxp + 300 and LC.Credits(member) == mcr + 100,
    "whoever makes the attempt under the order is paid what the job pays: 250 experience, 100 credits", (xp(member) - mxp) .. " " .. (LC.Credits(member) - mcr))
ok(LC.AdminPlotHolds(member) == nil and kept(member) == "", "their order is done")
ok(LC.AdminPlotHolds(second) == "order" and xp(second) == sxp and LC.Credits(second) == scr, "another member's stands, and pays them nothing yet")
ok(radioed == 0 and heard(commander, "Freq 7") == 0 and heard(commander, "The operation") == 0 and heard(commander, name(member)) == 0
    and heard(second, "fighter") == 0, "(nothing of it on the radio, and no word of it to the leader: the city's own alarm is all anyone reads)", radioed .. " " .. table.concat(commander.chat, " | "))
mxp = xp(member)
ok(LC.AdminPlotDied() >= 1 and xp(member) >= mxp + 250, "and 250 more if she dies of it after all (the roll in her office)", xp(member) - mxp)
-- someone sent for who has not spoken is no more than a lone wolf
her = address()
pool.reserve = 20
local lxp = xp(leader)
LC.AdminAttempt(her, leader, "shot")
ok(LC.AdminPlot() == nil and attackers() == 0 and xp(leader) < lxp + 250, "an attempt by someone sent for who has not spoken yet: nobody comes, nothing is paid")
tidy()
_run(1.5)
LC.AdminForget(leader) LC.ClearWanted(leader)
if LC.Prisoners[leader] then LC.ReleasePrisoner(leader) end
ok(LC.AdminPlotHolds(second) == "order", "her address over with nothing tried by them: their order stands for her next")
gone(member) -- (what the order paid has made a Lieutenant of them)
pick(commander, leader, "back")

-- kept with the character: gone from the server and back, with the leader who gave it gone too
gone(second)
gone(commander)
ok(LC.AdminPlotLeader(leader) == true, "(the Commander gone: the Lieutenant leads again)")
second = back(second, "PlotSecond")
inCrowd(second, -200, -200)
everyone = { leader, second, third, lowly, reb, wolf, cit, cop, adm }
ok(LCF.RankOf(second).name == "Fighter" and LC.AdminPlotHolds(second) == "order" and listed(leader, second) and listed(leader, second).has == "order",
    "under the order, they leave the server and come back: it is still theirs, and whoever leads now sees it", LCF.RankOf(second).name)
her = address()
sxp, scr = xp(second), LC.Credits(second)
pool.reserve = 20
LC.AdminAttempt(her, second, "shot")
P = LC.AdminPlot()
ok(P ~= nil and #P.fighters >= 7 and xp(second) >= sxp + 250 and LC.Credits(second) == scr + 100 and LC.AdminPlotHolds(second) == nil and kept(second) == "",
    "their attempt at her next address: the fighters come, they are paid, and it is done", P and #P.fighters)
tidy()

-- what else ends the order: an arrest, a new character, leaving the Resistance, falling below a Fighter
local function under(by, p) pick(by, p, "give") pick(by, p, "spoken") return LC.AdminPlotHolds(p) == "order" end
local e1, e2, e3, e4 = fighter("PlotArrested"), fighter("PlotReborn"), fighter("PlotLeaver"), fighter("PlotDemoted")
ok(under(leader, e1) and under(leader, e2) and under(leader, e3) and under(leader, e4), "(four more under the order, the Lieutenant's this time)")
if not LC.Incarcerate(e1, 60, "test") then hook.Run("LivingCityIncarcerated", e1, 60, "test") end -- (no cell free in this pretend city: as the cells say it)
ok(LC.AdminPlotHolds(e1) == nil and kept(e1) == "", "arrested: the order is no longer theirs")
if LC.Prisoners[e1] then LC.ReleasePrisoner(e1) end
ok(LC.AdminPlotHolds(e1) == nil, "(nor once they are out)")
LC.NewCharacter(e2, "test")
ok(LC.AdminPlotHolds(e2) == nil and kept(e2) == "", "someone new is under nobody's orders")
LC.SetFaction(e3, "citizen", nil, true)
ok(LC.AdminPlotHolds(e3) == nil and kept(e3) == "", "out of the Resistance: no longer theirs")
LC.SetFaction(e3, "resistance", nil, true)
ok(LCF.RankOf(e3).name == "Fighter" and LC.AdminPlotHolds(e3) == nil, "(nor when they come back to it)", LCF.RankOf(e3).name)
e4:SetPData("lcf_xp_resistance", 150)
LC.AddXP(e4, 0)
ok(LCF.RankOf(e4).name == "Member" and LC.AdminPlotHolds(e4) == nil and kept(e4) == "", "below a Fighter: no longer theirs", LCF.RankOf(e4).name)
e4:SetPData("lcf_xp_resistance", 400)
LC.AddXP(e4, 0)
ok(LCF.RankOf(e4).name == "Fighter" and LC.AdminPlotHolds(e4) == nil, "(nor when they are a Fighter again)", LCF.RankOf(e4).name)
ok(under(leader, e3), "(under it again)")
e3:SetNW2Int("lcf_rank", 2) -- (however they came to be less than a Fighter)
LC.AdminPlotWatch()
ok(LC.AdminPlotHolds(e3) == nil and kept(e3) == "", "(everyone is looked at every two seconds: whoever is no Fighter of the Resistance any more has none)")
e3:SetNW2Int("lcf_rank", 3)
for _, p in ipairs({ e1, e2, e3, e4 }) do gone(p) end

-- half after the first (the owner, 18 November: "Only the first should be paid that high, the rest maybe 1/2 or
-- less"): at one address the first under orders whose attempt counts is paid in full, and anyone else under the
-- leader's order whose attempt counts there half of each part; her next address starts again
do
local h1, h2, h3, h4 = fighter("PlotFirstShot"), fighter("PlotSecondShot"), fighter("PlotNextFirst"), fighter("PlotNextSecond")
ok(under(leader, h1) and under(leader, h2) and under(leader, h3) and under(leader, h4), "(four more under the Lieutenant's order)")
for p in pairs(LC.AdminPlotPaid) do LC.AdminPlotPaid[p] = nil end -- (whoever an earlier address paid is nothing to this one)
her = address()
local x1, c1, x2, c2 = xp(h1), LC.Credits(h1), xp(h2), LC.Credits(h2)
pool.reserve = 20
LC.AdminAttempt(her, h1, "shot")
P = LC.AdminPlot()
local came = P and #P.fighters or 0
ok(came >= 7 and xp(h1) - x1 >= 250 and xp(h1) - x1 < 300 and LC.Credits(h1) == c1 + 100 and LC.AdminPlotHolds(h1) == nil,
    "the first under orders whose attempt counts at an address is paid in full: 250 experience, 100 credits", (xp(h1) - x1) .. " " .. (LC.Credits(h1) - c1))
ok(xp(h2) == x2 and LC.Credits(h2) == c2 and LC.AdminPlotHolds(h2) == "order", "(another under the order has nothing of that)")
-- her guards have her: a second member joins in, and they mark them as an attacker (sv_livingcity_adminsecurity.lua)
ok(LC.AdminExfil() ~= nil and LC.AdminAttempt(LC.AdminExfil().her, h2, "shot") and LC.AdminExfil().attackers[h2] == true, "(a second joins in once her guards have her)")
LC.AdminPlotThink()
ok(xp(h2) - x2 >= 125 and xp(h2) - x2 < 150 and LC.Credits(h2) == c2 + 50,
    "the second under the order whose attempt counts at the same address is paid half of each part: 125 experience, 50 credits", (xp(h2) - x2) .. " " .. (LC.Credits(h2) - c2))
ok(LC.AdminPlotHolds(h2) == nil and kept(h2) == "", "and their order is done too")
ok(attackers() == came and pool.reserve == 20 - came, "(the fighters come once for an address, however many try)", attackers())
LC.AdminPlotThink()
ok(xp(h2) - x2 < 150 and LC.Credits(h2) == c2 + 50, "(once)")
x1, x2 = xp(h1), xp(h2)
ok(LC.AdminPlotDied() == 2 and xp(h1) - x1 >= 250 and xp(h1) - x1 < 300 and xp(h2) - x2 >= 125 and xp(h2) - x2 < 150,
    "she dies of it after all: 250 more for the first, half of that for the second", (xp(h1) - x1) .. " " .. (xp(h2) - x2))
-- her next address starts again; and the same with her guards' exit switched off (a grenade by her is how it is heard)
tidy()
set("lc_admin_exfil", 0)
her = address()
local x3, c3, x4, c4 = xp(h3), LC.Credits(h3), xp(h4), LC.Credits(h4)
pool.reserve = 20
hook.Run("LivingCityAdminAttempt", her, h3, "grenade")
ok(LC.AdminPlot() ~= nil and xp(h3) - x3 >= 250 and xp(h3) - x3 < 300 and LC.Credits(h3) == c3 + 100 and LC.AdminPlotHolds(h3) == nil,
    "her next address starts again: the first there is paid in full", (xp(h3) - x3) .. " " .. (LC.Credits(h3) - c3))
hook.Run("LivingCityAdminAttempt", her, h4, "grenade")
ok(xp(h4) - x4 >= 125 and xp(h4) - x4 < 150 and LC.Credits(h4) == c4 + 50 and LC.AdminPlotHolds(h4) == nil,
    "and whoever under the order tries after them there, half", (xp(h4) - x4) .. " " .. (LC.Credits(h4) - c4))
set("lc_admin_exfil", 1)
tidy()
for _, p in ipairs({ h1, h2, h3, h4 }) do -- (what it paid has made Lieutenants of some: gone, so the Lieutenant leads alone again)
    LC.AdminForget(p) LC.ClearWanted(p)
    if LC.Prisoners[p] then LC.ReleasePrisoner(p) end
    gone(p)
end
for p in pairs(LC.AdminPlotPaid) do LC.AdminPlotPaid[p] = nil end
end

-- sent for, layer 1: what happens to them, or to the leader, ends it at once and without a word
local s1, s2, s3, s4, s5 = fighter("PlotSentArrested"), fighter("PlotSentReborn"), fighter("PlotSentLeaver"), fighter("PlotSentDemoted"), fighter("PlotSentBack")
local sent = { s1, s2, s3, s4, s5 }
for _, p in ipairs(sent) do pick(leader, p, "give") end
local all = true
for _, p in ipairs(sent) do if not (word(p) and sentFor(p) == leader and #p.chat == 1) then all = false end end
ok(all, "(five sent for by the Lieutenant, each in the job, each told the one line)")
local function free(p) return word(p) == nil and LC.QuestOf[p] == nil and sentFor(p) == nil and kept(p) == "" and LC.AdminPlotBusy(p) == nil and failed(p) == 0 end
if not LC.Incarcerate(s1, 60, "test") then hook.Run("LivingCityIncarcerated", s1, 60, "test") end
ok(free(s1), "arrested: the job is gone and they are free of it, with no Failed line", table.concat(s1.chat, " | "))
if LC.Prisoners[s1] then LC.ReleasePrisoner(s1) end
LC.NewCharacter(s2, "test")
ok(free(s2), "someone new: gone", table.concat(s2.chat, " | "))
LC.SetFaction(s3, "citizen", nil, true)
ok(free(s3), "out of the Resistance: gone", table.concat(s3.chat, " | "))
s4:SetPData("lcf_xp_resistance", 150)
LC.AddXP(s4, 0)
ok(free(s4), "below a Fighter: gone", table.concat(s4.chat, " | "))
s5.chat = {}
ok(pick(leader, s5, "back") and free(s5) and #s5.chat == 0 and tracker(s5).active == false, "the leader takes it back (their name, as the list shows it): gone, and nothing is said")
for _, p in ipairs({ s1, s2, s3, s4 }) do gone(p) end

-- the leader goes: whoever leads now, title and marker following; nobody: free
local c2 = newPlayer("PlotCommanderTwo", "resistance", nil, 1800)
c2.chat = {}
ok(LC.AdminPlotLeader(c2) and not LC.AdminPlotLeader(leader), "(a Commander joins: the Lieutenant leads no more)")
ok(pick(c2, s5, "give") and sentFor(s5) == c2 and word(s5) ~= nil and word(s5).title == "A word with " .. name(c2), "(someone is sent for by the Commander)")
s5.chat = {}
gone(c2)
local w5 = word(s5)
ok(w5 ~= nil and sentFor(s5) == leader and w5.title == "A word with " .. name(leader) and w5.stages[1].text == "Speak with " .. name(leader) .. ", in private."
    and tracker(s5).ent == leader:EntIndex() and LC.AdminPlotBusy(s5) == name(leader) .. " wants a word with you first.",
    "the leader leaves the server with another leading: it is that one they speak with now, title and marker following", w5 and w5.title)
ok(#s5.chat == 0, "(and nothing more is said)", table.concat(s5.chat, " | "))
c2 = newPlayer("PlotCommanderThree", "resistance", nil, 1800)
LC.AdminPlotWatch()
ok(sentFor(s5) == c2 and word(s5) == w5 and w5.title == "A word with " .. name(c2), "the leader is a leader no more (a Commander has joined): the same", w5.title)
LC.NewCharacter(c2, "test")
ok(sentFor(s5) == leader and word(s5) == w5 and w5.title == "A word with " .. name(leader), "the leader dies for good: the same", w5.title)
gone(c2)
c2 = newPlayer("PlotCommanderFour", "resistance", nil, 1800)
LC.AdminPlotWatch()
LC.SetFaction(c2, "citizen", nil, true)
ok(sentFor(s5) == leader and word(s5) == w5, "the leader leaves the Resistance: the same")
gone(c2)
press(s5, leader)
ok(LC.AdminPlotHolds(s5) == "order" and word(s5) == nil, "(and a word with the one who leads now is the word: the order is theirs)")
pick(leader, s5, "back")
s5.chat = {}
ok(pick(leader, s5, "give") and word(s5) ~= nil, "(sent for again)")
s5.chat = {}
leader:SetPData("lcf_xp_resistance", 400)
LC.AddXP(leader, 0)
ok(LCF.RankOf(leader).name == "Fighter" and not LC.AdminPlotLeading() and free(s5) and #s5.chat == 0 and tracker(s5).active == false,
    "nobody leads any more: the job ends and they are free, and nothing is said", LCF.RankOf(leader).name .. " " .. table.concat(s5.chat, " | "))
leader:SetPData("lcf_xp_resistance", 900)
LC.AddXP(leader, 0)
ok(LC.AdminPlotLeader(leader) and sentFor(s5) == nil, "(the Lieutenant again; nobody is sent for by that alone)")

-- layer 2: everyone sent for is looked at every two seconds: the record and the job must agree
s5.chat = {}
pick(leader, s5, "give")
w5 = word(s5)
LC.QuestOf[s5], LC.ActiveQuests[w5], w5.done = nil, nil, true -- (the quest system has lost it: a reset, a clean-up)
ok(word(s5) == nil and LC.AdminPlotBusy(s5) ~= nil, "(the job lost by the quest system: the doors stay shut by the record)")
_run(2.5)
ok(word(s5) ~= nil and word(s5) ~= w5 and sentFor(s5) == leader and tracker(s5).nolimit == true, "a record with no job: the job is put back")
LC.AbandonQuest(s5) -- (dropped on their behalf by something else of the city's)
LC.AdminPlotWatch()
ok(word(s5) ~= nil and sentFor(s5) == leader, "(again, however it went)")
s5.chat = {}
local realGive, errsWas, byWas, logged = LC.GiveQuest, LC.Err.list, LC.Err.by, #_errors
LC.GiveQuest = function() return nil end
w5 = word(s5)
LC.QuestOf[s5], LC.ActiveQuests[w5], w5.done = nil, nil, true
LC.AdminPlotWatch()
ok(sentFor(s5) == leader and kept(s5) == "word", "the quest system will not take it back: once more at the next look")
LC.AdminPlotWatch()
ok(free(s5), "and failing twice, the record goes: they are free, never locked out of work by a job that is not there")
LC.GiveQuest = realGive
-- a job with no record behind it
s5.chat = {}
pick(leader, s5, "give")
local orphan = LC.GiveQuest(wolf, { tmpl = word(s5).tmpl, title = "A word with nobody", limit = false, stages = { { kind = "count", event = "plot_word", need = 1, text = "x" } } })
wolf.chat = {}
ok(orphan ~= nil and LC.QuestOf[wolf] == orphan, "(a job of that kind on someone nobody sent for)")
LC.AdminPlotWatch()
ok(LC.QuestOf[wolf] == nil and orphan.done == true and #wolf.chat == 0 and word(s5) ~= nil, "a job with no record: ended, without a word; the others' are left alone")
-- a leader no longer one, however it came about
leader:SetNW2Int("lcf_rank", 3)
LC.AdminPlotWatch()
ok(free(s5), "a leader no longer one, with nobody else leading, found at the next look: free")
leader:SetNW2Int("lcf_rank", 4)
-- nobody is kept from other work longer than an hour
s5.chat = {}
pick(leader, s5, "give")
LC.AdminPlotWatch(CurTime() + 3500)
ok(word(s5) ~= nil, "(fifty-eight minutes sent for: still)")
LC.AdminPlotWatch(CurTime() + 3601)
ok(free(s5) and #s5.chat == 1, "sent for longer than an hour: ended, whatever became of the leader", table.concat(s5.chat, " | "))

-- layer 3: the leader's list always takes it back, and an error frees whoever it was about
LC.Err.list, LC.Err.by = {}, {}
s5.chat = {}
pick(leader, s5, "give")
word(s5).ents = 5 -- (the job itself is broken: taking it out of the quest system fails)
ok(pick(leader, s5, "back") and free(s5) and #s5.chat == 1, "the job broken: the leader's list takes it back all the same")
pick(leader, s5, "give")
w5 = word(s5)
LC.QuestOf[s5], LC.ActiveQuests[w5], w5.done = nil, nil, true
LC.GiveQuest = function() error("the quest system is broken") end
LC.AdminPlotWatch()
LC.GiveQuest = realGive
ok(free(s5) and #LC.Err.list >= 1 and #_errors == logged + 1, "an error while it is looked at frees them, and is written in the errors file", #LC.Err.list .. " " .. (#_errors - logged))
LC.Err.list, LC.Err.by = errsWas, byWas
for i = #_errors, logged + 1, -1 do table.remove(_errors, i) end -- (that one was this check's own doing)

-- a reconnect keeps it: back in the job, pointed at whoever leads now (the same after the server starts again)
s5.chat = {}
pick(leader, s5, "give")
gone(s5)
local lost = 0
for x in pairs(LC.ActiveQuests) do if x.tmpl and x.tmpl.id == "res_word" then lost = lost + 1 end end
ok(lost == 0 and s5.pdata[KEY] == "word", "sent for, they leave the server: no job is left behind, and it is kept with the character")
s5 = back(s5, "PlotSentBack")
_run(2.5)
ok(word(s5) ~= nil and sentFor(s5) == leader and word(s5).title == "A word with " .. name(leader) and tracker(s5).nolimit == true and heard(s5, "wants a word") == 0,
    "and back: in the job again, pointed at whoever leads now, and not told twice", table.concat(s5.chat, " | "))
press(s5, leader)
ok(LC.AdminPlotHolds(s5) == "order", "(and done as before)")
pick(leader, s5, "back")
-- sent for while they hold another job: that job is kept, and this one begins the moment it ends
local held = posting()
s5.chat, s5.lcqNext = {}, 0
ok(LC.AcceptPosting(s5, held.id) == true and LC.QuestOf[s5] ~= nil and LC.QuestOf[s5].tmpl.id == "test_crates", "(a fighter with a job of their own)")
local theirs = LC.QuestOf[s5]
s5.chat = {}
ok(pick(leader, s5, "give") and heard(s5, "wants a word with you, in private") == 1 and LC.QuestOf[s5] == theirs and not theirs.done and sentFor(s5) == leader,
    "sent for while holding another job: told at once, and the job they hold is kept")
local other = posting()
ok(LC.AdminPlotBusy(s5) ~= nil and LC.AcceptPosting(s5, other.id) == false and LC.QuestOf[s5] == theirs, "(no other work meanwhile)")
LC.QuestEvent("test_crates", s5)
_run(0.6)
ok(theirs.done == true and word(s5) ~= nil and sentFor(s5) == leader, "the moment that job ends they are in this one")
press(leader, s5)
ok(LC.AdminPlotHolds(s5) == "order" and word(s5) == nil, "(and done as before)")
pick(leader, s5, "back")
held.dead, other.dead, post.dead = true, true, true

-- the job on the board: only while nobody leads
her = address()
ok(LC.AdminPlotLeading() and posted(reb) == nil and not onBoard(reb) and not onBoard(wolf) and not take(reb),
    "while a leader is playing the job is not on any Fighter's board, nor theirs to take: the order comes from the leader alone")
local hers = 0
for _, o in ipairs(LC.OpTargets()) do if o.kind == "regicide" or string.find(o.label, "Administrator", 1, true) then hers = hers + 1 end end
ok(LC.CanPlanOp(leader) and hers == 0 and LC.AdminPlotTarget == nil and LC.AdminPlotGo == nil, "and her life is no longer a target on the planning board, with her address on", hers)
gone(leader)
_run(1)
local job2 = posted(reb)
ok(not LC.AdminPlotLeading() and job2 ~= nil and onBoard(reb) and onBoard(wolf), "the leader gone: it is on the Fighters' board again, as before")
ok(heard(reb, "New job: Kill") == 0 and heard(wolf, "Kill the Administrator") == 0, "(and nobody is told so)")
local late = newPlayer("PlotLateLieutenant", "resistance", nil, 900)
reb.chat, reb.lcqNext = {}, 0
ok(job2 ~= nil and LC.AcceptPosting(reb, job2.id) ~= true and LC.QuestOf[reb] == nil and #reb.chat == 0 and not onBoard(reb),
    "a leader joins: at once it is not theirs to take nor on their board, and nothing is said", table.concat(reb.chat, " | "))
_run(1)
ok(posted(reb) == nil, "and the job nobody took is off the board")
gone(late)
_run(1)
ok(take(reb) and LC.AdminPlotHolds(reb) == "job", "(that leader gone again, a Fighter takes it)")
late = newPlayer("PlotLateLieutenant", "resistance", nil, 900)
_run(1)
ok(LC.AdminPlotLeading() and LC.QuestOf[reb] ~= nil and LC.AdminPlotHolds(reb) == "job" and onBoard(reb) and not onBoard(wolf),
    "whoever holds the job when a leader joins keeps it; it is on nobody else's board")
xp0 = xp(reb)
pool.reserve = 20
LC.AdminAttempt(her, reb, "shot")
ok(LC.AdminPlot() ~= nil and LC.QuestOf[reb] == nil and xp(reb) >= xp0 + 250, "and their attempt is the job's still: the fighters come, and it pays", xp(reb) - xp0)

LC.RadioNotice = baseRadio
tidy()
for _, p in ipairs({ second, third, lowly, s5, late }) do gone(p) end
end
-- back as it was
tidy()
LC.Notice = baseNotice
LC.AdminPlotStart, LC.AdminPlotThink = baseStart, baseThink
LC.ManpowerReturn = baseReturn
pool.reserve = reserveWas
for _, pt in ipairs(points) do LC.RemovePoint(pt) end
for _, p in ipairs({ adm, reb, wolf, cit, cop }) do
    hook.Run("PlayerDisconnected", p)
    p:Remove()
end
for p, r in pairs(strays) do if IsValid(p) then p:SetNW2Int("lcf_rank", r) end end
set("lc_stops", stopsWas)
set("lc_admin_hunt", huntWas)
set("lc_manpower", manWas)
set("lc_speech_muster", 120)
LC.ResistanceFundTake(LC.ResistanceFund())
LC.ResistanceFundAdd(fundWas)
_walls = savedWalls
end
Nov17_AdminPlotTests()

function Nov17_AdminRecruitTests()
section("17 November: a lone wolf who tried to kill the Administrator and got away is taken in by the Resistance")
LC.EndEvent(true)
if LC.SpeechSession() then LC.EndSpeech() end
if LC.AdminExfil() then LC.AdminExfilEnd(false) end
LC.AdminPlotEnd()
LC.AdminRecruitEnd()
local savedWalls = _walls
_walls = {}
local set = _setcvar
local stopsWas, huntWas, manWas = GetConVar("lc_stops"):GetInt(), GetConVar("lc_admin_hunt"):GetInt(), GetConVar("lc_manpower"):GetInt()
set("lc_stops", 0)
set("lc_admin_hunt", 0) -- (the hunt is its own unit's: no squads here)
set("lc_manpower", 1)
set("lc_speech_muster", 60)
-- (18 November: the job to kill her is on the board only while nobody leads the Resistance. A Commander or a
-- Lieutenant an earlier unit left playing is a Fighter while this one runs, and put back at its end.)
local strays = {}
for _, p in ipairs(player.GetAll()) do
    if p:GetNW2String("lcf_faction", "") == "resistance" and p:GetNW2Int("lcf_rank", 1) >= 4 then
        strays[p] = p:GetNW2Int("lcf_rank", 1)
        p:SetNW2Int("lcf_rank", 3)
    end
end
local W0 = Vector(-184000, -168000, 0)
local function at(x, y) return W0 + Vector(x, y, 0) end
local AWAY = at(60000, 0)       -- (nowhere near anyone)
local BARRACKS = at(-60000, 0)  -- (where the unit is when he is not about)
local SQUARE = at(0, -20000)    -- (a square in the city: doorways round it)
local CAMP = at(0, 30000)       -- (the Resistance's ground)
local SAID = "[Resistance] 'We saw what you did. You're with us now.'"
local KEY = "lc_adminrecruit"
ok(LC.ResistanceLines.saw_you == "We saw what you did. You're with us now.", "the line is one of the Resistance's own lines: it can be recorded", LC.ResistanceLines.saw_you)

-- her address, for the attempts
local stand = LC.AddPoint(at(0, 500), 270, "speech", 0)
local crowd = LC.AddPoint(at(0, 0), 90, "speechcrowd", 0)
local points = { stand, crowd }
points[#points + 1] = LC.AddPoint(at(-30000, -30000), 0, "cell", 0) -- (a cell that is free, whatever the tests before this left in the others)
-- the square: a doorway on each side of it. Someone standing in it looking north sees the northern one only.
for _, o in ipairs({ { 0, 800 }, { 0, -800 }, { 800, 0 }, { -800, 0 } }) do points[#points + 1] = LC.AddPoint(SQUARE + Vector(o[1], o[2], 0), 0, "spawn", 0) end
-- the camp, and one of the Resistance's people at home in it
local camp = LC.AddZone(CAMP, 500, "rebel", 0)
local pool = LC.ManpowerPool("rebel")
local reserveWas = pool.reserve
pool.reserve = 20
local host, hostSt = LC.SpawnRebel(CAMP + Vector(150, 0, 0), camp)
host.sim = false
hostSt.unmanaged, hostSt.questLock = true, true -- (he stays as he is for this)
local function hostHome() -- (at home, awake, with nobody to fight: whatever the camp's own life has had him do meanwhile)
    host:SetPos(CAMP + Vector(150, 0, 0))
    hostSt.foe = nil
    if hostSt.state == "detained" or hostSt.state == "jailed" or hostSt.state == "escorted" then LC.SetState(host, hostSt, "idle") end
end

local function heard(p, needle)
    local n = 0
    for _, v in ipairs(p.chat or {}) do if string.find(tostring(v), needle, 1, true) then n = n + 1 end end
    return n
end
local function kept(p) return p:GetPData(KEY, "") or "" end
local function faction(p) return p:GetNW2String("lcf_faction", "") end
local everyone = {}
local function person(name, side, xp)
    local p = newPlayer(name, side or "citizen", nil, xp)
    p:StripWeapons()
    p.testHome = (side == "cp") and BARRACKS or (AWAY + Vector(#everyone * 300, 0, 0))
    p:SetPos(p.testHome)
    p.aim = Vector(0, 1, 0)
    p.lcProtectUntil = 0 -- (no longer new in the city)
    p.chat = {}
    everyone[#everyone + 1] = p
    return p
end
-- every word put on a screen by a notice, and every line of chat, while this feature's own code runs
local notices, baseNotice = {}, LC.Notice
LC.Notice = function(who, kind, title, text, ...) notices[#notices + 1] = tostring(title) .. " " .. tostring(text) return baseNotice(who, kind, title, text, ...) end
local function lines()
    local n = #notices
    for _, p in ipairs(player.GetAll()) do n = n + #(p.chat or {}) end
    return n
end
local during, baseThink, baseAttempt, baseJoin = 0, LC.AdminRecruitThink, LC.AdminRecruitAttempt, LC.AdminRecruitJoin
LC.AdminRecruitThink = function(...) local n = lines() local r = baseThink(...) during = during + (lines() - n) return r end
LC.AdminRecruitAttempt = function(...) local n = lines() local r = baseAttempt(...) during = during + (lines() - n) return r end
LC.AdminRecruitJoin = function(...) local n = lines() local r = baseJoin(...) during = during + (lines() - n) return r end
-- every contact sent: was the spot he came out of in anyone's sight, and what he carried
local sent, baseSpawn = {}, LC.SpawnRebel
LC.SpawnRebel = function(pos, zone, weapon, ...)
    local seen = LC.IsSeen(pos + Vector(0, 0, 50))
    local npc, st = baseSpawn(pos, zone, weapon, ...)
    if weapon == "" and IsValid(npc) then sent[#sent + 1] = { npc = npc, seen = seen, pos = pos } end
    return npc, st
end
local function contacts()
    local n = 0
    for npc in pairs(LC.NPCs) do if IsValid(npc) and npc.lcAdminRecruit then n = n + 1 end end
    return n
end
local function tidy() -- (her address over and everything of it gone; the marks stay)
    if LC.AdminExfil() then
        local guards = LC.AdminExfil().guards
        LC.AdminExfilEnd(false)
        for _, g in ipairs(guards) do if IsValid(g) then g:Remove() end end
    end
    if LC.SpeechSession() then LC.EndSpeech() end
    LC.AdminPlotEnd()
    LC.EndEvent(true)
    LC.AdminAttemptSpoken()
    for _, e in ipairs(ents.FindByClass("lc_adminglass")) do e:Remove() end
end
local function address()
    tidy()
    LC.CallSpeech(nil, nil)
    local S = LC.SpeechSession()
    return S and S.her
end
local function leave(p) -- (gone from the server: a dropped connection, which nobody holds against them, sv_livingcity_conduct.lua)
    hook.Run("PlayerDisconnected", p)
    p:RemovePData("lc_combatlog")
    p.valid = false
end
local function rejoin(p) -- (and back, the same character)
    p.valid = true
    hook.Run("PlayerInitialSpawn", p)
    p.lcProtectUntil = 0
end
local function away(p) -- (they get away: out of every unit's sight, the units no longer after them)
    p:SetPos(p.testHome)
    LC.CalmCops(p)
end

local wolf = person("RecruitWolf")          -- goes to the Resistance
local stayer = person("RecruitStayer")      -- stays in the city: the Resistance comes
local fighter = person("RecruitFighter", "resistance", 400) -- one of the Resistance, with the job (Fighters both: nobody leads)
local loner = person("RecruitLoner", "resistance", 400)     -- one of the Resistance, with no job
local unit = person("RecruitUnit", "cp")
local rat = person("RecruitRat")
local pawn = person("RecruitPawn")          -- (a citizen who somehow holds the job)
local held = person("RecruitHeld")
local dead = person("RecruitDead")
rat:SetPData("lc_scar", "1")

-- a lone wolf's attempt at her address
local her = address()
ok(IsValid(her), "(the city is called to her address)")
wolf:SetPos(at(0, -300))
ok(LC.AdminRecruitOwed(wolf) == nil and kept(wolf) == "", "before anything: nothing is owed to anyone")
LC.AdminAttempt(her, wolf, "shot")
ok(LC.AdminExfil() ~= nil and LC.AdminNeverForgotten(wolf), "a citizen with no job and no order shoots at her: her guards get her out and he is marked, as before")
ok(LC.AdminRecruitOwed(wolf) ~= nil and tonumber(kept(wolf)) ~= nil, "a lone wolf: the Resistance owes him its welcome from that moment, kept with the character", kept(wolf))
-- one of the Resistance joins in on her guards with no job: a lone wolf too, but theirs already
loner:SetPos(at(100, -300))
LC.AdminAttempt(her, loner, "shot")
_run(1)
ok(LC.AdminNeverForgotten(loner) and LC.AdminRecruitOwed(loner) == nil and kept(loner) == "", "one of the Resistance who tries alone is marked, and owed nothing: theirs already")
away(wolf) away(loner)

-- under orders: the job taken, the attempt made
her = address()
local job
for _, x in ipairs((LC.RefreshBoard(fighter))) do if x.tmpl and x.tmpl.id == "res_regicide" and not x.dead then job = x end end
fighter.lcqNext = 0
ok(job ~= nil and LC.AcceptPosting(fighter, job.id) == true and LC.AdminPlotHolds(fighter) == "job", "(a member of the Resistance takes Kill the Administrator)")
_run(1)
fighter:SetPos(at(0, -300))
LC.AdminAttempt(her, fighter, "shot")
ok(LC.QuestOf[fighter] == nil and LC.AdminPlotHolds(fighter) == nil, "(an ordered attempt: the job is done)")
-- a citizen joins in on her guards beside them: no job of his own, so a lone wolf (and no hook says so: he is found by his mark)
stayer:SetPos(at(200, -300))
LC.AdminAttempt(her, stayer, "shot")
ok(LC.AdminNeverForgotten(stayer) and LC.AdminRecruitOwed(stayer) == nil, "(a citizen joins in on her guards: marked)")
_run(1)
ok(LC.AdminRecruitOwed(stayer) ~= nil and tonumber(kept(stayer)) ~= nil, "a citizen who joins in with no job of his own is a lone wolf too: owed")
ok(LC.AdminRecruitOwed(fighter) == nil and kept(fighter) == "", "whoever held the job is owed nothing: that was the Resistance's own attack")
away(stayer) away(fighter)
tidy()

-- held when the attempt was made is what counts, whichever piece of code hears of the attempt first
local holdsWas, pawnHolds = LC.AdminPlotHolds, true
LC.AdminPlotHolds = function(p) if p == pawn then return pawnHolds and "job" or nil end return holdsWas(p) end
_run(1)
pawnHolds = false -- (the attempt ended the job, and that was heard first)
LC.AdminAttacker(pawn)
hook.Run("LivingCityAdminExfil", her, pawn)
_run(4)
ok(LC.AdminNeverForgotten(pawn) and LC.AdminRecruitOwed(pawn) == nil and kept(pawn) == "", "the job held a moment before the attempt: under orders, owed nothing")
LC.AdminPlotHolds = holdsWas

-- nobody else: a unit, a marked rat
ok(LC.AdminAttacker(unit) == false and LC.AdminRecruitAttempt(unit) == false, "a unit is never marked for it, and owed nothing")
unit:SetPData("lc_regicide", tostring(os.time())) unit:SetNW2Bool("lc_regicide", true) -- (were one of the Combine's marked all the same)
ok(LC.AdminRecruitAttempt(unit) == false, "one of the Combine is not someone the Resistance comes for")
_run(4)
ok(LC.AdminRecruitOwed(unit) == nil and kept(unit) == "", "(nor a few seconds later)")
LC.AdminForget(unit)
LC.AdminAttacker(rat)
hook.Run("LivingCityAdminExfil", her, rat)
_run(4)
ok(LC.AdminNeverForgotten(rat) and LC.AdminRecruitOwed(rat) == nil and kept(rat) == "", "a marked rat who tries is owed nothing: the Resistance will never take them")
away(rat)

-- caught, or dead: off for good
LC.AdminAttacker(held) LC.AdminAttacker(dead)
_run(1)
ok(LC.AdminRecruitOwed(held) ~= nil and LC.AdminRecruitOwed(dead) ~= nil, "(two more lone wolves, owed)")
away(held) away(dead)
local jailed = LC.Incarcerate(held, 600, "test", nil)
ok(jailed == true and LC.AdminRecruitOwed(held) == nil and kept(held) == "over", "caught and put in a cell: it is off for good", kept(held))
LC.ReleasePrisoner(held)
held.lcGraceUntil = nil
local answer = hook.t.PlayerDeath.LivingCityAdminRecruit(dead, dead, dead) -- (this feature's own ear for a death, and nothing else's)
ok(LC.AdminRecruitOwed(dead) == nil and kept(dead) == "over" and answer == nil, "dead: off for good (and the death is left for everyone else to hear)", kept(dead))

-- way one: he goes to the Resistance
ok(faction(wolf) == "citizen" and heard(wolf, "We saw what you did") == 0, "(the lone wolf, free in the city: nothing said yet)")
wolf.chat = {}
hostHome()
local seenWas, wolfSeen = LC.SeenBySecurity, true
LC.SeenBySecurity = function(p, d) if p == wolf and wolfSeen then return true end return seenWas(p, d) end
wolf:SetPos(CAMP)
_run(3)
ok(heard(wolf, "We saw what you did") == 0 and LC.AdminRecruitOwed(wolf) ~= nil, "on rebel ground with a unit on his heels: nobody says anything yet")
wolfSeen = false
local asleepWas = LC.RebelAsleep
LC.RebelAsleep = function(st) if st == hostSt then return true end return asleepWas(st) end
hostHome()
_run(2)
ok(heard(wolf, "We saw what you did") == 0 and LC.AdminRecruitOwed(wolf) ~= nil, "the unit lost, the only one of theirs in sight asleep: still nothing")
LC.RebelAsleep = asleepWas
hostHome()
local aloud, emitWas = {}, host.EmitSound
host.EmitSound = function(self, path, ...) if string.find(tostring(path), "vo/npc/male01/hi0", 1, true) then aloud[#aloud + 1] = tostring(path) end end
_run(1)
host.EmitSound = emitWas
ok(heard(wolf, SAID) == 1 and heard(wolf, "[Resistance]") == 1, "awake: the nearest of the Resistance's people there says it to him, one line", table.concat(wolf.chat, " | "))
ok(#aloud == 1, "not recorded yet: he says a word of greeting aloud, once, so that it is heard", #aloud)
ok(LC.AdminRecruitOwed(wolf) == nil and faction(wolf) == "citizen", "(said, and a moment yet before it takes)")
local xp0 = tonumber(wolf:GetPData("lcf_xp_resistance", 0)) or 0
_run(2)
ok(faction(wolf) == "resistance" and wolf:GetPData("lcf_res_proven", "") == "1", "a moment later he is one of the Resistance, as after a story's invitation", faction(wolf))
ok(kept(wolf) == "done", "and it is done, kept with the character", kept(wolf))
ok(LC.InRebelZone(wolf:GetPos()), "on the Resistance's own ground", tostring(wolf:GetPos() - CAMP))
ok(xp0 == 0 and (tonumber(wolf:GetPData("lcf_xp_resistance", 0)) or 0) == LCF.Get("resistance").ranks[2].xp - 5 and LCF.RankOf(wolf).name == "Sympathizer",
    "a Sympathizer, one job short of a Member", wolf:GetPData("lcf_xp_resistance", 0))
-- where they arrive (the owner, 18 November): by the leader; else by a Lieutenant; else the rebel ground furthest from the Combine's
local far = LC.AddZone(at(0, 60000), 500, "rebel", 0)
local comb = LC.AddZone(at(0, 20000), 500, "combine", 0)
local realZones = LC.ZonesOfKindShared
LC.ZonesOfKindShared = function(kind)
    if kind == "rebel" then return { camp, far } elseif kind == "combine" then return { comb } end
    return realZones(kind)
end
local realColonel = LC.ColonelSpot
LC.ColonelSpot = function() return nil end -- (no camp of the Colonel's in this world, until it is given one below)
local s1 = LC.AdminRecruitSpot(wolf)
ok(s1 ~= nil and s1:Distance(at(0, 60000)) < 100, "nobody leading: the rebel ground furthest from the Combine's", tostring(s1))
local rs = LC.AddPoint(at(200, 60000), 0, "rspawn", 0)
s1 = LC.AdminRecruitSpot(wolf)
ok(s1 ~= nil and s1:Distance(at(200, 60000)) < 100, "at the Resistance's spawn point there, when it has one", tostring(s1))
local lt = person("RecruitLieutenant", "resistance", 900)
lt:SetPos(CAMP + Vector(-200, 0, 0))
s1 = LC.AdminRecruitSpot(wolf)
ok(LCF.RankOf(lt).name == "Lieutenant" and s1 ~= nil and s1:Distance(lt:GetPos()) < 100, "a Lieutenant on rebel ground: by him", tostring(s1))
local cmd = person("RecruitCommander", "resistance", 1800)
cmd:SetPos(at(-200, 60000))
s1 = LC.AdminRecruitSpot(wolf)
ok(LCF.RankOf(cmd).name == "Commander" and s1 ~= nil and s1:Distance(at(200, 60000)) < 100, "the leader on rebel ground: his zone, before the Lieutenant's (at its spawn point)", tostring(s1))
cmd:SetPos(at(40000, -40000))
s1 = LC.AdminRecruitSpot(wolf)
ok(s1 ~= nil and s1:Distance(lt:GetPos()) < 100, "a leader who is not on rebel ground is passed over", tostring(s1))
-- no Commander on rebel ground: Colonel Cubbage leads (the owner, 18 November), before any Lieutenant
LC.ColonelSpot = function() return at(100, 60000), 0 end
s1 = LC.AdminRecruitSpot(wolf)
ok(s1 ~= nil and s1:Distance(at(200, 60000)) < 100, "no Commander: by Colonel Cubbage's camp, before the Lieutenant's zone (at its spawn point)", tostring(s1))
cmd:SetPos(CAMP + Vector(200, 0, 0))
s1 = LC.AdminRecruitSpot(wolf)
ok(s1 ~= nil and s1:Distance(cmd:GetPos()) < 100, "a Commander who is playing comes before the Colonel", tostring(s1))
cmd:SetPos(at(40000, -40000))
LC.ColonelSpot = function() return at(30000, 30000), 0 end
s1 = LC.AdminRecruitSpot(wolf)
ok(s1 ~= nil and s1:Distance(at(30000, 30000)) < 100, "(his camp outside any drawn rebel zone: beside him all the same)", tostring(s1))
LC.ColonelSpot = function() return nil end
LC.ZonesOfKindShared = function(kind) if kind == "rebel" then return {} end return realZones(kind) end
ok(LC.AdminRecruitSpot(wolf) == nil, "no rebel ground at all: they stay where they stand")
LC.ZonesOfKindShared = realZones
LC.RemovePoint(rs) LC.RemoveZone(far) LC.RemoveZone(comb)
LC.ColonelSpot = realColonel
lt:SetPos(at(40000, -41000))
ok(heard(wolf, "You are now") == 0 and heard(wolf, "[Resistance]") == 1, "with no second line about it", table.concat(wolf.chat, " | "))
_run(10)
ok(heard(wolf, "We saw what you did") == 1 and contacts() == 0, "said once; and nobody was sent for him", heard(wolf, "We saw what you did"))
LC.SeenBySecurity = seenWas
-- the others in front of the same man: nothing
for _, p in ipairs({ loner, fighter, rat, held, dead, pawn }) do p.chat = {} p:SetPos(CAMP + Vector(0, 60, 0)) end
hostHome()
_run(3)
local said = 0
for _, p in ipairs({ loner, fighter, rat, held, dead, pawn }) do said = said + heard(p, "We saw what you did") end
ok(said == 0, "nothing is said to the one under orders, the one of the Resistance, the rat, the one who was caught, or the one who died", said)
ok(faction(rat) == "citizen" and faction(held) == "citizen" and faction(pawn) == "citizen", "(and none of them is taken in)")
for _, p in ipairs({ loner, fighter, rat, held, dead, pawn }) do away(p) end

-- way two: he stays in the city, and the Resistance comes to him
local rec = LC.AdminRecruitOwed(stayer)
ok(rec ~= nil and rec.tries == 0, "(the other lone wolf: still owed)")
stayer.chat = {}
stayer:SetPos(SQUARE)
stayer.aim = Vector(0, 1, 0)
stayer.lcWantedSeen = rec.at -- (the units saw him last as he made the attempt)
local early = 0
local function wait(untilT) -- (time passes: how many contacts were about, second by second)
    while CurTime() < untilT do _run(1) early = early + contacts() end
end
wait(rec.at + 112)
ok(early == 0 and #sent == 0, "under two minutes since the attempt: nobody comes yet", early)
stayer.lcWantedSeen = CurTime() -- (a unit catches sight of him, and loses him again)
local glimpsed = CurTime()
wait(glimpsed + 52)
ok(CurTime() - rec.at > 150 and early == 0 and #sent == 0 and rec.tries == 0, "two minutes on, but seen by a unit under a minute ago: nobody yet", early)
-- a unit has him in sight when the time comes: nobody is sent
unit:SetPos(SQUARE + Vector(0, 600, 0))
wait(glimpsed + 70)
ok(early == 0 and #sent == 0 and rec.tries == 0, "a minute unseen, with a unit looking at him now: nobody is sent", early)
ok(rec.nextTry - CurTime() > 100 and rec.nextTry - CurTime() <= 180, "it is tried again three minutes later", rec.nextTry - CurTime())
unit:SetPos(BARRACKS)
wait(CurTime() + 30)
ok(early == 0, "(not before)", early)
rec.nextTry = CurTime() + 2 -- (those minutes pass)
local r0 = pool.reserve
_run(4)
local c1 = rec.npc
local c1st = IsValid(c1) and LC.NPCs[c1]
ok(IsValid(c1) and #sent == 1 and sent[1].npc == c1 and rec.tries == 1, "the unit gone: a contact comes", #sent)
ok(#sent == 1 and sent[1].seen == false and sent[1].pos:Distance(SQUARE) > 390, "out of a doorway nobody can see, a walk away", #sent == 1 and sent[1].pos:Distance(SQUARE))
ok(c1st and c1st.role == "rebel" and c1:GetClass() == "npc_citizen" and pool.reserve == r0 - 1, "one of the city's own Resistance fighters, out of its reserve", pool.reserve)
ok(IsValid(c1) and c1.kv.additionalequipment == "" and c1st.casual == true, "with no gun, and in plain clothes: a citizen, to the units")
ok(c1st and c1st.state == "event" and c1st.unmanaged and not c1st.raid, "(the Resistance's own to move: no raid, no shout)")
ok(heard(stayer, "We saw what you did") == 0, "(he has said nothing yet: he is still on his way)")
-- a unit shoots at him: he does not turn on it
local cop = LC.Spawners.cop(AWAY + Vector(0, -8000, 0))
cop.sim = false
if IsValid(c1) then hook.Run("EntityTakeDamage", c1, _dmg(cop, 5)) end -- (no contact came: the checks above already failed; don't stop the run)
ok(c1st and c1st.state == "event" and c1st.foe == c1 and c1:GetEnemy() ~= cop, "hit by a unit he does not fight back: nobody's enemy")
cop:Remove()
-- a unit comes into the square while he is on his way: he turns back, and it is tried again later
unit:SetPos(SQUARE + Vector(0, 1200, 0))
_run(1)
ok(rec.npc == nil and LC.AdminRecruitLeaving[c1] ~= nil and heard(stayer, "We saw what you did") == 0, "a unit walks into the square: the contact turns back with nothing said")
ok(rec.nextTry - CurTime() > 170, "and it is tried again three minutes later", rec.nextTry - CurTime())
unit:SetPos(BARRACKS)
local gone = false
for _ = 1, 40 do _run(1) if not IsValid(c1) then gone = true break end end
ok(gone and pool.reserve == r0, "he goes back the way he came and is taken out of the city once nobody can see him: back in the reserve", pool.reserve)
rec.nextTry = CurTime() + 2 -- (those minutes pass)
_run(4)
local c2 = rec.npc
ok(IsValid(c2) and c2 ~= c1 and #sent == 2 and sent[2].seen == false and rec.tries == 2, "three minutes on: another contact, from out of sight again", #sent)
local from2 = IsValid(c2) and c2:GetPos()
local spoke = false
for _ = 1, 40 do _run(0.5) if heard(stayer, "We saw what you did") > 0 then spoke = true break end end
ok(spoke and heard(stayer, SAID) == 1 and heard(stayer, "[Resistance]") == 1, "he walks up to him and says it, one line", table.concat(stayer.chat, " | "))
ok(IsValid(c2) and c2:GetPos():Distance(SQUARE) <= 110 and c2:GetPos():Distance(from2) > 300, "from close by: he came all the way", IsValid(c2) and c2:GetPos():Distance(SQUARE))
_run(2)
ok(faction(stayer) == "resistance" and stayer:GetPData("lcf_res_proven", "") == "1" and LC.InRebelZone(stayer:GetPos()),
    "a moment later he is one of the Resistance, and on its own ground", faction(stayer))
stayer:SetPos(SQUARE) -- (for what follows: someone still standing in the square, watching the contact go)
ok(kept(stayer) == "done" and LC.AdminRecruitOwed(stayer) == nil, "and it is done, kept with the character", kept(stayer))
ok(heard(stayer, "You are now") == 0 and heard(stayer, "[Resistance]") == 1, "with no second line about it", table.concat(stayer.chat, " | "))
-- the contact: watched, he walks back the way he came; unseen, he is gone
local back = IsValid(c2) and (c2:GetPos() - SQUARE) or Vector(0, -1, 0)
back.z = 0
stayer.aim = back:GetNormalized() -- (the new man turns to look at him)
local near0 = IsValid(c2) and c2:GetPos():Distance(SQUARE) or 0
_run(10)
ok(IsValid(c2) and c2:GetPos():Distance(SQUARE) > near0 + 200, "the contact walks off, watched all the way", IsValid(c2) and c2:GetPos():Distance(SQUARE))
stayer.aim = -stayer.aim -- (and looks away)
_run(4)
ok(not IsValid(c2) and contacts() == 0 and next(LC.AdminRecruitLeaving) == nil and pool.reserve == r0, "out of sight he is taken out of the city: back in the reserve", pool.reserve)
_run(10)
ok(heard(stayer, "We saw what you did") == 1 and #sent == 2, "said once: nobody comes again", #sent)

-- kept over a reconnect: owed, and done
local third = person("RecruitThird")
LC.AdminAttacker(third)
_run(1)
ok(LC.AdminRecruitOwed(third) ~= nil, "(a third lone wolf, owed)")
away(third)
local owedAt = kept(third)
leave(third)
ok(LC.AdminRecruitOwed(third) == nil and kept(third) == owedAt and tonumber(owedAt) ~= nil, "gone from the server: what is owed stays with the character")
_run(2)
rejoin(third)
_run(4)
ok(LC.AdminRecruitOwed(third) ~= nil and LC.AdminRecruitOwed(third).tries == 0, "back on the server: still owed")
third.chat = {}
hostHome()
third:SetPos(CAMP)
_run(1)
ok(heard(third, SAID) == 1, "he walks in among the Resistance: spoken to")
-- gone from the server in the moment before it takes: nothing is lost
leave(third)
_run(3)
ok(faction(third) == "citizen" and kept(third) == owedAt, "gone from the server in the moment between the line and being taken in: still owed", kept(third))
rejoin(third)
hostHome()
third:SetPos(CAMP)
_run(4)
ok(heard(third, SAID) == 2, "back, among the Resistance: it is said to him again", heard(third, SAID))
_run(2)
ok(faction(third) == "resistance" and kept(third) == "done", "and this time he is taken in")
-- once for a character: put out of the Resistance by staff and marked for another attempt, nothing comes of it
LC.SetFaction(third, "citizen", nil, true, true)
LC.AdminAttacker(third)
hook.Run("LivingCityAdminExfil", her, third)
_run(4)
ok(faction(third) == "citizen" and LC.AdminRecruitOwed(third) == nil and kept(third) == "done", "once for a character: another attempt is owed nothing")
leave(third)
_run(1)
rejoin(third)
hostHome()
third:SetPos(CAMP)
_run(5)
ok(LC.AdminRecruitOwed(third) == nil and heard(third, "We saw what you did") == 2 and faction(third) == "citizen", "nor after a reconnect: that it was done is kept too")
-- a new character starts clean
hook.Run("LivingCityNewCharacter", third, "x", "test")
ok(kept(third) == "" and not LC.AdminNeverForgotten(third), "a new character: nothing is kept of it")
away(third)
LC.AdminAttacker(third)
_run(1)
ok(LC.AdminRecruitOwed(third) ~= nil, "(and may be owed it in their own right)", kept(third) .. (LC.Prisoners[third] and ", in a cell" or ""))

-- nothing but the line
ok(during == 4, "this feature's own code put the one line on a screen each time it was said (four times, to three people), and nothing else: no notice, no second line", during)

-- back as it was
tidy()
LC.AdminRecruitEnd()
LC.Notice = baseNotice
LC.AdminRecruitThink, LC.AdminRecruitAttempt, LC.AdminRecruitJoin = baseThink, baseAttempt, baseJoin
LC.SpawnRebel = baseSpawn
if IsValid(host) then host:Remove() end
LC.RemoveZone(camp)
for _, pt in ipairs(points) do LC.RemovePoint(pt) end
pool.reserve = reserveWas
for _, p in ipairs(everyone) do
    if LC.Prisoners[p] then LC.ReleasePrisoner(p) end
    LC.AdminForget(p)
    p:RemovePData(KEY)
    LC.ClearWanted(p)
    LC.CalmCops(p)
    if LC.QuestOf[p] then LC.AbandonQuest(p) end
    hook.Run("PlayerDisconnected", p)
    p:Remove()
end
for p, r in pairs(strays) do if IsValid(p) then p:SetNW2Int("lcf_rank", r) end end
set("lc_stops", stopsWas)
set("lc_admin_hunt", huntWas)
set("lc_manpower", manWas)
set("lc_speech_muster", 120)
_walls = savedWalls
end
Nov17_AdminRecruitTests()

function Nov18_ResistanceFundTests()
section("18 November: the Resistance's fund (half of every take from supplies raided and people saved), and the price of the leader's order")
-- The owner, 18 November: "the resistance leader can only order this if they've saved up enough money themselves to
-- put into this extra pay, or have gathered enough funds in a Resistance fund ... various successful missions where
-- supplies are raided or people saved (who then donate small amounts of credits that they may have saved) would all
-- be spit between the partakers of the activities and a general resistance fund".
local set = _setcvar
LC.EndEvent(true)
if LC.SpeechSession() then LC.EndSpeech() end
if LC.AdminExfil() then LC.AdminExfilEnd(false) end
LC.AdminPlotEnd()
local fundWas = LC.ResistanceFund()
local costWas = GetConVar("lc_resistance_order_cost"):GetInt()
local stopsWas, huntWas, manWas = GetConVar("lc_stops"):GetInt(), GetConVar("lc_admin_hunt"):GetInt(), GetConVar("lc_manpower"):GetInt()
set("lc_stops", 0)
set("lc_admin_hunt", 0)
set("lc_manpower", 1)
set("lc_speech_muster", 60)
-- (whoever an earlier unit left leading the Resistance is a Fighter while this one runs, and put back at its end)
local strays = {}
for _, p in ipairs(player.GetAll()) do
    if p:GetNW2String("lcf_faction", "") == "resistance" and p:GetNW2Int("lcf_rank", 1) >= 4 then
        strays[p] = p:GetNW2Int("lcf_rank", 1)
        p:SetNW2Int("lcf_rank", 3)
    end
end
local F0 = Vector(-118000, 92000, 0)
local fund = LC.ResistanceFund
local function setFund(n) LC.ResistanceFundTake(fund()) LC.ResistanceFundAdd(n) end
local function xp(p) return tonumber(p:GetPData("lcf_xp_resistance", 0)) or 0 end
local function rebel(name, x) local p = newPlayer(name, "resistance", nil, x or 400) p.chat, p.lcProtectUntil = {}, 0 return p end
local function share(p) -- (what the last "your share" line on their screen says they had)
    for i = #(p.chat or {}), 1, -1 do
        local n = string.match(tostring(p.chat[i]), "^%[Credits%] %+(%d+) %(your share%)$")
        if n then return tonumber(n) end
    end
    return 0
end
local function gone(p) hook.Run("PlayerDisconnected", p) p:Remove() end
local function back(p, name) -- (the same person joins again: a new connection, the same saved data)
    local n = _makeplayer(name, p:GetPos())
    n.sid, n.pdata = p.sid, p.pdata
    hook.Run("PlayerInitialSpawn", n)
    if n:GetNW2String("lcf_faction", "") ~= "resistance" then LC.SetFaction(n, "resistance", nil, true) end
    n.chat, n.lcProtectUntil = {}, 0
    return n
end
local jobPay = GetConVar("lc_economy"):GetBool() and GetConVar("lc_directive_pay"):GetInt() or 0 -- (what the board pays for any job)
local made = {} -- (everyone this unit made, to leave at its end)
local function keep(p) made[#made + 1] = p return p end

------------------------------------------------------------------------
-- the fund itself
------------------------------------------------------------------------
ok(costWas == 300, "the one setting: lc_resistance_order_cost is 300", costWas)
setFund(0)
ok(fund() == 0 and LC.ResistanceFundAdd(50, "test") == 50 and fund() == 50, "credits go into the Resistance's fund")
ok(LC.ResistanceFundTake(20, "test") == true and fund() == 30, "and come out of it")
ok(LC.ResistanceFundTake(31) == false and fund() == 30, "never more than it holds: false, and nothing is taken")
ok(LC.ResistanceFundAdd(10.9) == 40 and LC.ResistanceFundAdd(-5) == 40 and LC.ResistanceFundAdd(0) == 40, "a whole number of credits; adding less than one adds nothing", fund())
do
    local saved = util.JSONToTable(file.Read("livingcity/" .. game.GetMap() .. "_city.json", "DATA") or "") or {}
    ok(saved.fund == 40, "it is written with the state of the city the moment it changes", tostring(saved.fund))
    LC.LedgerReload()
    ok(fund() == 40, "and is there after a restart or a map change (read back from the file)", fund())
    LC.LedgerSave()
    LC.LedgerReload()
    ok(fund() == 40 and LC.Ledger().supply ~= nil, "(the city's own save keeps it, with the rest of the state of the city)")
end

------------------------------------------------------------------------
-- supplies raided
------------------------------------------------------------------------
local supWas = LC.Supply
local crate = ents.Create("lc_supply") crate:SetPos(F0) crate:Spawn()
local function drop(loads) -- (a supply drop down at F0, its crate holding that many loads)
    crate:SetNW2Int("lc_loads", loads)
    LC.Supply = { pos = F0, crate = crate, startT = CurTime() - 60, guards = {}, props = {}, raided = {}, loads = loads }
    return LC.Supply
end
local looter, a, b, far = keep(rebel("FundLooter")), keep(rebel("FundJoinerA")), keep(rebel("FundJoinerB")), keep(rebel("FundJoinerFar"))
local cit = keep(newPlayer("FundCitizen", "citizen"))
_run(3) -- (they have arrived: nothing of a first spawn moves them from here on)
cit.chat = {}
for _, p in ipairs({ a, b, far, cit }) do p:SetPos(F0 + Vector(9000, 0, 0)) end
do
    drop(5)
    looter:SetPos(F0 + Vector(40, 0, 0))
    setFund(0)
    local c0, n0 = LC.Credits(looter), LC.InvCount(looter)
    ok(LC.LootSupply(looter, crate), "(one of ours pries a load out of a supply convoy's crate)")
    _run(8.5)
    ok(crate:GetNW2Int("lc_loads", 0) == 4 and LC.InvCount(looter) > n0, "what the load holds is theirs, as before", table.concat(looter.chat, " | "))
    ok(fund() == 10 and LC.Credits(looter) == c0 + 10 and share(looter) == 10,
        "a load out of a supply convoy: a take of 20 on top, half to the fund and half to the one who pried it", fund() .. " " .. (LC.Credits(looter) - c0))
    local cc = LC.Credits(cit)
    cit.chat = {}
    hook.Run("LivingCitySupplyLooted", cit, { "Bread" })
    ok(fund() == 10 and LC.Credits(cit) == cc and #cit.chat == 0, "(a load taken by someone who is not of the Resistance: nothing to the fund or to them)",
        fund() .. " " .. table.concat(cit.chat, " | "))
    -- our fighters get into the crate: the city's own operation, nobody's plan
    hook.Run("LivingCityRebelOpDone", "supply", { purpose = "supply" })
    ok(fund() == 30, "our fighters' own raid on a supply drop: a take of 40, half to the fund; the other half is the fighters'", fund())
    hook.Run("LivingCityRebelOpDone", "supply", { purpose = "supply" })
    ok(fund() == 30, "(a crate already cleaned out is no success)", fund())
    LC.Supply = { pos = F0, startT = CurTime(), guards = {}, props = {}, raided = {}, loads = 5 }
    hook.Run("LivingCityRebelOpDone", "supply", { purpose = "supply" })
    LC.Supply = nil
    hook.Run("LivingCityRebelOpDone", "supply", { purpose = "supply" })
    ok(fund() == 30, "(nor one with no crate down yet, or with the drop gone)", fund())
    -- a planned operation: those who joined and were there share the other half
    drop(5)
    a:SetPos(F0 + Vector(100, 0, 0)) b:SetPos(F0 + Vector(-100, 0, 0)) far:SetPos(F0 + Vector(4000, 0, 0))
    for _, p in ipairs({ a, b, far }) do p.chat = {} end
    local plan = { by = a, label = "Hit the supply drop", kind = "supply", pos = F0, data = {}, joined = { [a] = true, [b] = true, [far] = true } }
    local ca, cb, cf, xa, xb = LC.Credits(a), LC.Credits(b), LC.Credits(far), xp(a), xp(b)
    hook.Run("LivingCityRebelOpDone", "supply", { purpose = "supply", planned = plan })
    ok(fund() == 50 and LC.Credits(a) - ca == 15 + 10 and LC.Credits(b) - cb == 15 + 10 and share(a) == 10 and share(b) == 10,
        "a planned raid on a supply drop that worked: half to the fund, the other half shared equally among those who joined and were there",
        fund() .. " " .. (LC.Credits(a) - ca) .. " " .. (LC.Credits(b) - cb))
    ok(LC.Credits(far) == cf and share(far) == 0, "(someone who joined and was not there has no share)")
    ok(xp(a) - xa == 35 and xp(b) - xb == 25, "what a planned operation pays already is unchanged: 15 credits and 25 experience each, the planner 10 more",
        (xp(a) - xa) .. " " .. (xp(b) - xb))
    drop(5)
    far:SetPos(F0 + Vector(0, 100, 0))
    ca = LC.Credits(a)
    hook.Run("LivingCityRebelOpDone", "supply", { purpose = "supply", planned = plan })
    ok(fund() == 72 and LC.Credits(a) - ca == 15 + 6 and share(far) == 6, "what does not divide equally stays with the fund: three share 20, 6 each and 22 to the fund", fund())
    for _, p in ipairs({ a, b, far }) do p.chat = {} end
    hook.Run("LivingCityRebelOpDone", "screen", { purpose = "screen", planned = plan })
    hook.Run("LivingCityRebelOpDone", "heist", { purpose = "heist" })
    hook.Run("LivingCityRebelOpDone", "ambush", { purpose = "ambush" })
    ok(fund() == 72 and share(a) == 0 and share(b) == 0,
        "(an operation with no supplies taken and nobody saved, a screen, a terminal, an ambush, gives the fund nothing and nobody a share)", fund())
end
LC.Supply = supWas
crate:Remove()

-- a job of one of the kinds that count, finished (the real template, one step of this test's own)
local function job(owner, id, mates, hold)
    local tmpl
    for _, t in ipairs(LC.QuestTemplates) do if t.id == id then tmpl = t end end
    if not tmpl then return nil end
    for _, p in ipairs({ owner, unpack(mates or {}) }) do
        if LC.QuestOf[p] then LC.AbandonQuest(p) end
        p.lcqNext = 0
    end
    local q = LC.GiveQuest(owner, { tmpl = tmpl, title = "Fund test " .. id, reward = 30, limit = 600,
        stages = { { kind = "count", event = "fund_test", need = 1, untallied = true, text = "Do it." } } })
    if not q then return nil end
    for _, m in ipairs(mates or {}) do
        q.members[#q.members + 1] = m
        LC.QuestOf[m] = q
    end
    if not hold then LC.QuestEvent("fund_test", owner) end
    return q
end
do
    setFund(0)
    for _, p in ipairs({ a, b }) do p.chat = {} end
    local ca, xa = LC.Credits(a), xp(a)
    local q = job(a, "res_supplyrun")
    ok(q ~= nil and q.done and fund() == 15 and LC.Credits(a) - ca == jobPay + 15 and share(a) == 15,
        "a crate of the Union's supplies stolen and brought home (the job): a take of 30, half to the fund, half to whoever did it", fund() .. " " .. (LC.Credits(a) - ca))
    ok(xp(a) - xa >= 30, "(what the job pays is unchanged)", xp(a) - xa)
    ca = LC.Credits(a)
    local cb = LC.Credits(b)
    q = job(a, "res_supplyrun", { b })
    ok(q ~= nil and fund() == 15 + 16 and LC.Credits(a) - ca == jobPay + 7 and LC.Credits(b) - cb == jobPay + 7,
        "two on the job share that half equally (7 each of 15, the odd one to the fund), each counted once", fund() .. " " .. (LC.Credits(a) - ca) .. " " .. (LC.Credits(b) - cb))
    ca = LC.Credits(a)
    q = job(a, "res_propaganda")
    -- (flyers bring nothing in: experience only since the owner's word of 19 November, Nov19_JobPayShownTests)
    ok(q ~= nil and q.done and fund() == 31 and LC.Credits(a) - ca == 0, "(any other job gives the fund nothing)", fund() .. " " .. (LC.Credits(a) - ca))
end

------------------------------------------------------------------------
-- people saved
------------------------------------------------------------------------
local inmate, breaker, mate = keep(rebel("FundInmate", 150)), keep(rebel("FundBreaker")), keep(rebel("FundMate"))
do
    LC.AddCredits(inmate, 55)
    local jailed = LC.Incarcerate(inmate, 600, "Test") and LC.Prisoners[inmate] ~= nil
    setFund(0)
    breaker.chat = {}
    local ci, cby, xby = LC.Credits(inmate), LC.Credits(breaker), xp(breaker)
    if jailed then LC.BreakOut(inmate, breaker) else hook.Run("LivingCityBreakout", inmate, breaker) end
    local d = fund()
    ok(d >= 5 and d <= 15 and LC.Credits(breaker) == cby + d and share(breaker) == d,
        "a prisoner got out of the cells: someone saved gives a small sum (10 to 30), half to the fund and half to whoever got the cell open", d)
    ok(LC.Credits(inmate) == ci and ci > 0, "a freed player's own pockets are untouched: nothing is taken from them", LC.Credits(inmate) - ci)
    ok(xp(breaker) - xby == (jailed and 50 or 0), "(the 50 experience a prison break pays is unchanged)", xp(breaker) - xby)
    if LC.Prisoners[inmate] then LC.ReleasePrisoner(inmate) end
    LC.ClearWanted(inmate)
    -- on the job with others: they share it; the one let out never does
    local q = job(breaker, "res_breakout", { mate, inmate }, true)
    local f0, cm = fund(), LC.Credits(mate)
    cby, ci = LC.Credits(breaker), LC.Credits(inmate)
    hook.Run("LivingCityBreakout", inmate, breaker)
    local got, each = fund() - f0, LC.Credits(breaker) - cby
    local take = got + 2 * each
    ok(q ~= nil and each >= 2 and LC.Credits(mate) - cm == each and take >= 10 and take <= 30 and take % 2 == 0 and each == math.floor(take / 4),
        "those on that job with them share its half equally", got .. " " .. each)
    ok(LC.Credits(inmate) == ci, "(the one let out has no share of their own rescue)")
    if q then LC.WithdrawQuest(q) end
    -- let out by our fighters' own operation: counted once the operation says it worked
    a:SetPos(F0 + Vector(100, 0, 0)) b:SetPos(F0 + Vector(-100, 0, 0)) inmate:SetPos(F0)
    local plan = { by = a, label = "Break them out", kind = "breakout", pos = F0, data = {}, joined = { [a] = true, [b] = true, [inmate] = true } }
    f0, ci = fund(), LC.Credits(inmate)
    local ca = LC.Credits(a)
    hook.Run("LivingCityBreakout", inmate, nil)
    ok(fund() == f0 and LC.Credits(a) == ca, "(let out by our fighters' own operation, nobody named: nothing yet)")
    hook.Run("LivingCityRebelOpDone", "breakout", { purpose = "breakout", planned = plan })
    got, each = fund() - f0, LC.Credits(a) - ca - 15
    take = got + 2 * each
    ok(each >= 2 and take >= 10 and take <= 30 and take % 2 == 0 and each == math.floor(take / 4) and LC.Credits(inmate) == ci + 15,
        "the operation says it worked: half to the fund, the other half among those who joined the plan and were there (never the one let out)", got .. " " .. each)
    f0 = fund()
    hook.Run("LivingCityRebelOpDone", "breakout", { purpose = "breakout", planned = plan })
    ok(fund() == f0, "(an operation that let nobody out is no success)")
    f0 = fund()
    hook.Run("LivingCityRebelOpDone", "breakout", {})
    hook.Run("LivingCityBreakout", inmate, nil)
    _run(1.5)
    hook.Run("LivingCityRebelOpDone", "breakout", {})
    ok(fund() == f0, "(nor is a breakout nobody named counted by an operation long after)")
    -- a vortigaunt cut loose
    local vort = ents.Create("npc_vortigaunt") vort:SetPos(F0 + Vector(300, 0, 0)) vort:Spawn()
    f0, cby = fund(), LC.Credits(breaker)
    hook.Run("LivingCityVortFreed", vort, breaker)
    d = fund() - f0
    ok(d >= 5 and d <= 15 and LC.Credits(breaker) == cby + d, "a vortigaunt cut loose by one of ours: the same", d)
    f0 = fund()
    local cc = LC.Credits(cit)
    hook.Run("LivingCityVortFreed", vort, nil)
    hook.Run("LivingCityVortFreed", vort, cit)
    ok(fund() == f0 and LC.Credits(cit) == cc, "(freed by the city's own team, or by someone who is not of the Resistance: nothing)")
    ci, cby = LC.Credits(inmate), LC.Credits(breaker)
    hook.Run("LivingCityVortFreed", inmate, breaker) -- (a player who was a shackled vortigaunt)
    ok(fund() > f0 and LC.Credits(inmate) == ci and LC.Credits(breaker) > cby, "(a player cut loose: the same, and nothing out of their pockets)")
    vort:Remove()
    -- the jobs where one of the city's own is saved
    for _, id in ipairs({ "res_jailbreak", "res_rescue", "res_freevort" }) do
        f0, cby = fund(), LC.Credits(breaker)
        q = job(breaker, id)
        d = fund() - f0
        ok(q ~= nil and q.done and d >= 5 and d <= 15 and LC.Credits(breaker) - cby == jobPay + d, "a job where someone is saved, finished (" .. id .. "): the same, on top of what it pays", d)
    end
end

------------------------------------------------------------------------
-- the leader's order has a price
------------------------------------------------------------------------
local notices, baseNotice = {}, LC.Notice
LC.Notice = function(who, kind, title, text, ...) notices[#notices + 1] = { p = who, t = tostring(title) .. ": " .. tostring(text) } return baseNotice(who, kind, title, text, ...) end
local KEY, PRICE = "lc_adminplot_order", "lc_adminplot_price"
local function kept(p) return p:GetPData(KEY, "") end
local function price(p) return p:GetPData(PRICE, "") end
local function pick(by, p, what) -- (as F2 sends it: done, or not and the one line why)
    local did, why = LC.QuickMore(by, "plotorder", p:EntIndex() .. ":" .. what)
    return did == true, why
end
local function under(by, p) pick(by, p, "give") pick(by, p, "spoken") return LC.AdminPlotHolds(p) == "order" end
local sentFor = LC.AdminPlotSentFor
local commander = rebel("FundCommander", 1800)
local f1, f2, f3, spender = keep(rebel("FundFighterOne")), keep(rebel("FundFighterTwo")), keep(rebel("FundFighterThree")), keep(rebel("FundSpender"))
local function who(p) return "300:" .. tostring(p:SteamID64()) .. ":" .. p:GetNW2String("lc_cid", "") end
local function quiet() for _, p in ipairs(player.GetAll()) do p.chat = {} end notices = {} end
ok(LC.AdminPlotLeader(commander) and LC.AdminPlotCost() == 300, "(a Commander leads; each member sent for costs 300)")
do
    -- out of the fund when it holds enough
    setFund(500)
    quiet()
    local c0 = LC.Credits(commander)
    ok(pick(commander, f1, "give") and sentFor(f1) == commander, "(the leader sends for a member)")
    ok(fund() == 200 and LC.Credits(commander) == c0 and price(f1) == "300:fund", "the price is charged the moment they are sent for: out of the Resistance's fund when it holds enough", fund() .. " " .. price(f1))
    ok(#notices == 0 and #commander.chat == 0 and #f1.chat == 1, "(and nothing is said of it: the member reads their one line, the leader nothing)", table.concat(commander.chat, " | "))
    ok(pick(commander, f1, "give") and pick(commander, f1, "spoken") and fund() == 200 and LC.AdminPlotHolds(f1) == "order" and price(f1) == "300:fund",
        "(sent for again, or spoken with: charged once)", fund())
    -- out of the leader's own credits when the fund is short
    LC.AddCredits(commander, 400 - LC.Credits(commander))
    quiet()
    ok(pick(commander, f2, "give") and sentFor(f2) == commander and fund() == 200 and LC.Credits(commander) == 100,
        "the fund short of it: out of the leader's own credits, all of it", fund() .. " " .. LC.Credits(commander))
    ok(price(f2) == who(commander) and #commander.chat == 0 and #notices == 0, "(kept with the order: who paid. Nothing is said)", price(f2))
    -- neither can pay: refused, with one short reason
    quiet()
    local sent, why = pick(commander, f3, "give")
    ok(sent == false and why == "Neither the fund nor you can pay 300 credits.", "neither the fund nor the leader can pay: refused, with one short reason", tostring(why))
    ok(sentFor(f3) == nil and kept(f3) == "" and price(f3) == "" and LC.QuestOf[f3] == nil and #f3.chat == 0, "nobody is sent for, and they read nothing")
    ok(fund() == 200 and LC.Credits(commander) == 100, "and nothing is charged", fund() .. " " .. LC.Credits(commander))
    ok(#notices == 1 and notices[1].p == commander and string.find(notices[1].t, "Neither the fund nor you can pay 300 credits.", 1, true) ~= nil and #commander.chat == 0,
        "the leader reads that one line, and nobody anything else", notices[1] and notices[1].t)
    -- a leader ordering themselves pays the same
    setFund(300)
    ok(pick(commander, commander, "give") and LC.AdminPlotHolds(commander) == "order" and fund() == 0 and price(commander) == "300:fund", "a leader who picks themselves pays the same", fund())
    ok(pick(commander, commander, "back") and LC.AdminPlotHolds(commander) == nil and fund() == 300 and price(commander) == "", "(and has it back with the order given up)", fund())
    setFund(0)
    LC.AddCredits(commander, 350 - LC.Credits(commander))
    ok(pick(commander, commander, "give") and LC.Credits(commander) == 50 and price(commander) == who(commander) and pick(commander, commander, "back") and LC.Credits(commander) == 350,
        "(out of their own credits when the fund is short, and back to them)", LC.Credits(commander))
    sent, why = pick(commander, f3, "give")
    ok(sent and fund() == 0 and LC.Credits(commander) == 50 and pick(commander, f3, "back") and LC.Credits(commander) == 350, "(the same for another member)")

    -- getting it back: taken back by the leader
    setFund(200)
    quiet()
    ok(pick(commander, f1, "back") and LC.AdminPlotHolds(f1) == nil and fund() == 500 and price(f1) == "", "the leader takes an order back: the price goes back where it came from, the fund", fund())
    local c1 = LC.Credits(commander)
    ok(pick(commander, f2, "back") and sentFor(f2) == nil and fund() == 500 and LC.Credits(commander) == c1 + 300 and price(f2) == "", "or the leader, who paid it out of their own credits", LC.Credits(commander) - c1)
    ok(#notices == 0 and #commander.chat == 0 and #f1.chat == 0 and #f2.chat == 0, "(nothing is said of it)")
    ok(pick(commander, f1, "back") and fund() == 500 and LC.Credits(commander) == c1 + 300, "(once)")
    -- what else ends an order before the attempt: an arrest, a new character, leaving the Resistance, falling below a Fighter
    local e1, e2, e3, e4, e5 = keep(rebel("FundArrested")), keep(rebel("FundReborn")), keep(rebel("FundLeaver")), keep(rebel("FundDemoted")), keep(rebel("FundWaiting"))
    setFund(1500)
    ok(under(commander, e1) and under(commander, e2) and under(commander, e3) and under(commander, e4) and pick(commander, e5, "give") and fund() == 0,
        "(four under the order and one sent for, all out of the fund)", fund())
    if not LC.Incarcerate(e1, 60, "test") then hook.Run("LivingCityIncarcerated", e1, 60, "test") end
    ok(LC.AdminPlotHolds(e1) == nil and fund() == 300 and price(e1) == "", "arrested before the attempt: it goes back", fund())
    if LC.Prisoners[e1] then LC.ReleasePrisoner(e1) end
    LC.NewCharacter(e2, "test")
    ok(LC.AdminPlotHolds(e2) == nil and fund() == 600 and price(e2) == "", "someone new: it goes back", fund())
    LC.SetFaction(e3, "citizen", nil, true)
    ok(fund() == 900 and price(e3) == "", "out of the Resistance: it goes back", fund())
    e4:SetPData("lcf_xp_resistance", 150)
    LC.AddXP(e4, 0)
    ok(fund() == 1200 and price(e4) == "", "below a Fighter: it goes back", fund())
    LC.AdminPlotWatch(CurTime() + 3500)
    ok(sentFor(e5) == commander and fund() == 1200, "(sent for fifty-eight minutes: still)")
    LC.AdminPlotWatch(CurTime() + 3601)
    ok(sentFor(e5) == nil and fund() == 1500 and price(e5) == "", "sent for an hour and never spoken with: it goes back", fund())
    ok(fund() == 1500, "(each of them once)")
    -- the price that was paid goes back, whatever the setting says by then
    set("lc_resistance_order_cost", 500)
    ok(LC.AdminPlotCost() == 500 and under(commander, f1) and fund() == 1000 and price(f1) == "500:fund", "(the setting changed: the next order costs that)", fund())
    set("lc_resistance_order_cost", 120)
    ok(pick(commander, f1, "back") and fund() == 1500, "(and what was paid is what goes back)", fund())
    -- at 0 an order is free
    set("lc_resistance_order_cost", 0)
    setFund(0)
    LC.AddCredits(commander, -LC.Credits(commander))
    ok(under(commander, f1) and price(f1) == "" and fund() == 0 and pick(commander, f1, "back") and fund() == 0 and LC.Credits(commander) == 0, "at 0 an order is free: nothing is charged, kept or given back")
    set("lc_resistance_order_cost", 300)
end
do
    -- a reconnect, theirs or the leader's, loses nothing: it still goes back where it came from
    setFund(300)
    LC.AddCredits(commander, 300 - LC.Credits(commander))
    local r1, r2 = rebel("FundAwayOne"), rebel("FundAwayTwo")
    ok(under(commander, r1) and price(r1) == "300:fund" and under(commander, r2) and price(r2) == who(commander) and fund() == 0 and LC.Credits(commander) == 0,
        "(one order out of the fund, one out of the leader's own credits)")
    gone(r1)
    gone(r2)
    ok(fund() == 0 and LC.Credits(commander) == 0, "leaving the server ends no order, and gives nothing back")
    r1, r2 = keep(back(r1, "FundAwayOne")), keep(back(r2, "FundAwayTwo"))
    gone(commander)
    commander = back(commander, "FundCommander")
    ok(LC.AdminPlotLeader(commander) and LC.AdminPlotHolds(r1) == "order" and LC.AdminPlotHolds(r2) == "order" and price(r1) == "300:fund" and price(r2) == who(commander),
        "they leave the server and come back, and so does the leader: the orders stand, and so does where each price came from", price(r1) .. " " .. price(r2))
    ok(pick(commander, r1, "back") and fund() == 300 and pick(commander, r2, "back") and LC.Credits(commander) == 300, "taken back then: each goes back where it came from, the fund and the leader",
        fund() .. " " .. LC.Credits(commander))
    -- the leader who paid can no longer be found: the fund has it
    setFund(0)
    ok(pick(commander, r2, "give") and LC.Credits(commander) == 0 and price(r2) == who(commander) and sentFor(r2) == commander, "(sent for, out of the leader's own credits)")
    gone(commander)
    ok(not LC.AdminPlotLeading() and sentFor(r2) == nil and kept(r2) == "" and price(r2) == "" and fund() == 300,
        "the leader gone and nobody leading: the one sent for is free, and the price goes to the fund when the leader who paid cannot be found", fund())
    commander = back(commander, "FundCommander")
    ok(LC.Credits(commander) == 0, "(the leader has not had it twice)")
    -- someone who paid and is no longer of the Resistance is not found either
    LC.AddCredits(commander, 300)
    setFund(0)
    ok(under(commander, r2) and LC.Credits(commander) == 0 and price(r2) == who(commander), "(under the order, out of the leader's own credits)")
    LC.SetFaction(commander, "citizen", nil, true)
    if not LC.Incarcerate(r2, 60, "test") then hook.Run("LivingCityIncarcerated", r2, 60, "test") end
    ok(LC.AdminPlotHolds(r2) == nil and fund() == 300 and LC.Credits(commander) == 0, "the leader who paid has left the Resistance: the price goes to the fund", fund())
    if LC.Prisoners[r2] then LC.ReleasePrisoner(r2) end
    LC.SetFaction(commander, "resistance", nil, true)
    commander:SetPData("lcf_xp_resistance", 1800)
    LC.AddXP(commander, 0)
end

------------------------------------------------------------------------
-- what F2 is sent
------------------------------------------------------------------------
do
    setFund(120)
    local t = LC.QuickInfo(f1)
    ok(t.reb ~= nil and t.reb.fund == 120 and t.plot == nil and t.plotcost == nil, "every member's F2 is sent what the fund holds (\"Fund: 120 credits\"); the price goes only with the leader's list", t.reb and t.reb.fund)
    t = LC.QuickInfo(commander)
    ok(LC.AdminPlotLeader(commander) and t.reb.fund == 120 and t.plot ~= nil and t.plotcost == 300, "the leader's: the fund, the list, and what each one sent for costs (\"(300 each)\")", tostring(t.plotcost))
    t = LC.QuickInfo(cit)
    ok(t.reb == nil and t.plot == nil and t.plotcost == nil, "(nobody outside the Resistance is sent either)")
    LC.QuickInfoSend(commander)
    local m = _lastnet("lc_quick_info")
    local got = m and util.JSONToTable(m.data[1]) or {}
    ok(m ~= nil and (m.to == commander or (type(m.to) == "table" and table.HasValue(m.to, commander))) and got.reb ~= nil and got.reb.fund == 120 and got.plotcost == 300,
        "and that is what reaches their game", m and m.data[1])
    LC.QuickInfoSend(f1)
    m = _lastnet("lc_quick_info")
    got = m and util.JSONToTable(m.data[1]) or {}
    ok(got.reb ~= nil and got.reb.fund == 120 and got.plot == nil and got.plotcost == nil, "(a member's: the fund, and no price)")
end

------------------------------------------------------------------------
-- her address: the job on the board costs nothing; made, the attempt spends what an order cost
------------------------------------------------------------------------
do
    setFund(300)
    ok(under(commander, spender) and fund() == 0 and price(spender) == "300:fund", "(one member under the order, paid for out of the fund)")
    gone(commander) -- (nobody leads: the job is on the board)
    local X0 = Vector(-128000, 112000, 0)
    local stand = LC.AddPoint(X0 + Vector(0, 500, 0), 270, "speech", 0)
    local crowd = LC.AddPoint(X0, 90, "speechcrowd", 0)
    local pool = LC.ManpowerPool("rebel")
    local reserveWas = pool.reserve
    pool.reserve = 0 -- (no fighters to send: the job and the order pay all the same)
    local holder = keep(rebel("FundJobHolder"))
    holder:SetPos(X0 + Vector(0, -300, 0)) spender:SetPos(X0 + Vector(150, -300, 0))
    LC.CallSpeech(nil, nil)
    local S = LC.SpeechSession()
    local her = S and S.her
    local job1
    for _, x in ipairs((LC.RefreshBoard(holder))) do
        if x.tmpl and x.tmpl.id == "res_regicide" and not x.dead then job1 = x end
    end
    setFund(700)
    holder.lcqNext = 0
    local ch = LC.Credits(holder)
    ok(IsValid(her) and not LC.AdminPlotLeading() and job1 ~= nil and LC.AcceptPosting(holder, job1.id) == true and LC.AdminPlotHolds(holder) == "job",
        "(her address on and nobody leading: a Fighter takes Kill the Administrator from the board)")
    ok(fund() == 700 and LC.Credits(holder) == ch and price(holder) == "", "the job from the board costs nothing: not the fund, not whoever takes it", fund())
    -- the member under the order makes the attempt: what the order cost is spent
    local xs, cs = xp(spender), LC.Credits(spender)
    ok(IsValid(her) and LC.AdminPlotAttempt(her, spender) == true and LC.AdminPlotHolds(spender) == nil and kept(spender) == "", "(the one under the order makes the attempt)")
    ok(fund() == 700 and price(spender) == "", "made, the attempt spends what the order cost for good: nothing goes back", fund())
    ok(xp(spender) - xs >= 250 and xp(spender) - xs < 300 and LC.Credits(spender) == cs + 100, "(and it pays them as it did: 250 experience, 100 credits)", (xp(spender) - xs) .. " " .. (LC.Credits(spender) - cs))
    LC.AdminPlotWatch()
    LC.NewCharacter(spender, "test")
    ok(fund() == 700, "(nor does anything that happens to them later give it back)", fund())
    -- the job is never halved, whoever went first
    holder.chat = {}
    ch = LC.Credits(holder)
    ok(IsValid(her) and LC.AdminPlotAttempt(her, holder) == true and LC.QuestOf[holder] == nil, "(the one who holds the job tries after them, at the same address)")
    local paidXP
    for i = #holder.chat, 1, -1 do paidXP = paidXP or tonumber(string.match(tostring(holder.chat[i]), "Complete: Kill the Administrator %(%+(%d+) XP%)")) end
    ok(paidXP == 250 and LC.Credits(holder) == ch + 100, "the job from the board is paid what it always paid, first or not: 250 experience, 100 credits", tostring(paidXP) .. " " .. (LC.Credits(holder) - ch))
    ok(fund() == 700, "(and the fund has nothing to do with it)", fund())
    if LC.AdminExfil() then LC.AdminExfilEnd(false) end
    if LC.SpeechSession() then LC.EndSpeech() end
    LC.AdminPlotEnd()
    LC.EndEvent(true)
    for p in pairs(LC.AdminPlotPaid) do LC.AdminPlotPaid[p] = nil end
    pool.reserve = reserveWas
    LC.RemovePoint(stand) LC.RemovePoint(crowd)
end

-- back as it was
LC.Notice = baseNotice
for _, p in ipairs(made) do
    if IsValid(p) then
        if LC.QuestOf[p] then LC.AbandonQuest(p) end
        if LC.Prisoners[p] then LC.ReleasePrisoner(p) end
        LC.ClearWanted(p)
        gone(p)
    end
end
for p, r in pairs(strays) do if IsValid(p) then p:SetNW2Int("lcf_rank", r) end end
set("lc_resistance_order_cost", costWas)
set("lc_stops", stopsWas)
set("lc_admin_hunt", huntWas)
set("lc_manpower", manWas)
set("lc_speech_muster", 120)
setFund(fundWas)
end
Nov18_ResistanceFundTests()

function Nov19_JobPayShownTests()
section("19 November: every job lists its credits, and what it puts in the Resistance's fund; Resistance jobs that bring nothing in pay experience only")
-- The owner, 19 November: "every job should list the credits a player will receive if successful, or at least the range
-- if dependent on success/metrics, and similarly the range of credits that will/can go into the resistance fund. this
-- means all players feel responsible for helping grow the resistance fund." And, the same day: "Only jobs that bring in
-- money: Raids, convoy hits, supply runs and rescues pay credits as now. Resistance jobs that bring in nothing (headcrab
-- hunts, deliveries, scouting and the like) pay experience only. Citizen and Civil Protection jobs keep paying, since the
-- Union pays them"; then "please be logical: a delivery would pay credits".
local jobPay = GetConVar("lc_economy"):GetBool() and GetConVar("lc_directive_pay"):GetInt() or 0
local made = {}
local function person(name, f, special, x)
    local p = newPlayer(name, f, special, x)
    p.chat, p.lcProtectUntil = {}, 0
    made[#made + 1] = p
    return p
end
local function xpOf(p) return tonumber(p:GetPData("lcf_xp_" .. p:GetNW2String("lcf_faction", ""), 0)) or 0 end
local function isRange(r) return istable(r) and tonumber(r[1]) ~= nil and tonumber(r[2]) ~= nil and r[1] >= 0 and r[1] <= r[2] end
local function feeds(spec) -- (does this job put anything in the fund, by the fund's own tables?)
    if istable(spec.tmpl) and LC.ResistanceFundJobKind(spec.tmpl.id) then return true end
    for _, st in ipairs(spec.stages or {}) do
        if st.kind == "count" and LC.ResistanceFundStepKinds[st.event] then return true end
    end
    return false
end
local nextPid = 919000
local function post(t, f, p) -- (built and put on the board as LC.RefreshBoard does; nil when it can't be here)
    local okA, avail = pcall(function() return not t.available or t.available(p) end)
    if not (okA and avail) then return nil end
    local spec
    for i = 1, 5 do
        local okB, s = pcall(t.build, p)
        if okB and s then spec = s break end
        if i == 2 then LC.BadDest = {} end
    end
    if not spec then return nil end
    nextPid = nextPid + 1
    spec.id, spec.tmpl, spec.violent, spec.faction = nextPid, t, t.violent, f
    spec.squad, spec.during = spec.squad or t.squad, t.during
    spec.expiresPost, spec.data = CurTime() + 999, spec.data or {}
    LC.Postings[f] = LC.Postings[f] or {}
    table.insert(LC.Postings[f], spec)
    return spec
end

------------------------------------------------------------------------
-- every job has a field for its side; every game says what it can pay
------------------------------------------------------------------------
do
    local missing, kinds = {}, { "sweep", "line", "papers", "wiring", "triage", "rubble", "parcel", "hack", "drop", "search",
        "laundry", "filing", "radio", "patdown", "breach", "scrub", "assemble" }
    for _, t in ipairs(LC.QuestTemplates) do
        if t.factions.resistance and type(t.brings) ~= "boolean" then missing[#missing + 1] = t.id end
    end
    ok(#missing == 0, "every job on the Resistance's board says whether it brings something in (brings = true or false)", table.concat(missing, ", "))
    local noRange = {}
    for _, k in ipairs(kinds) do
        local d = LC.JobGameDef(k)
        if not (d and d.payRange ~= nil) then noRange[#noRange + 1] = k end
    end
    ok(#noRange == 0, "every job game says what it can pay, beside its own pay (payRange)", table.concat(noRange, ", "))
    local lo, hi = LC.JobGamePay(nil, "rubble", {}, nil)
    ok(lo == 4 and hi == 6, "a game's range: the rubble pays a credit a block, 4 to 6", lo .. "-" .. hi)
    lo, hi = LC.JobGamePay(nil, "wiring", {}, { title = "Union shift: Sanitation: Community service" })
    ok(lo == 0 and hi == 0, "community service pays nothing for its game, as at the end of one", lo .. "-" .. hi)
end

------------------------------------------------------------------------
-- the fund's numbers come from the fund
------------------------------------------------------------------------
do
    local a, b, c, d = LC.ResistanceFundShares("run", 1)
    ok(a == 15 and b == 15 and c == 15 and d == 15, "a supply run done alone: 15 to the fund, 15 to whoever did it (half of 30 each)", a .. " " .. b .. " " .. c .. " " .. d)
    a, b, c, d = LC.ResistanceFundShares("run", 3)
    ok(a == 15 and b == 15 and c == 5 and d == 5, "three on it: 5 each, the fund 15", a .. " " .. b .. " " .. c .. " " .. d)
    a, b, c, d = LC.ResistanceFundShares("saved", 1)
    ok(a == 5 and b == 15 and c == 5 and d == 15, "someone saved: 10 to 30, half to the fund (5-15) and half to whoever did it", a .. " " .. b .. " " .. c .. " " .. d)
    a, b, c, d = LC.ResistanceFundShares("load", 1)
    ok(a == 10 and b == 10 and c == 10 and d == 10, "a load pried out of a supply crate: 10 and 10", a .. " " .. b .. " " .. c .. " " .. d)
    ok(LC.ResistanceFundJobKind("res_supplyrun") == "run" and LC.ResistanceFundJobKind("res_breakout") == "saved" and LC.ResistanceFundJobKind("res_crabhunt") == nil,
        "which jobs feed it is the fund's own list")
end

------------------------------------------------------------------------
-- every job on every board: what it says, and what finishing it pays
------------------------------------------------------------------------
local pool = {
    citizen = person("PayCitizen", "citizen"), cp = person("PayCop", "cp"), ota = person("PayOTA", "ota"),
    admin = person("PayAdmin", "admin"), resistance = person("PayRebel", "resistance", nil, 900), zombie = person("PayZombie", "zombie"),
}
local priest = person("PayPriest", "resistance", "chaplain", 200)
local said, finished, cant, wrong, noFund, badFund, untagged = 0, 0, {}, {}, {}, {}, {}
for _, t in ipairs(LC.QuestTemplates) do
    local sides = {}
    for f in pairs(t.factions) do sides[#sides + 1] = f end
    table.sort(sides)
    for _, f in ipairs(sides) do
        local p = (t.id == "res_ministry") and priest or pool[f]
        if p then
            if LC.QuestOf[p] then LC.AbandonQuest(p) end
            p.lcqNext = 0
            local spec = post(t, f, p)
            if not spec then
                -- (not on a board here: what it would say, from the template alone)
                local okP, credits = pcall(LC.PostingPay, p, { tmpl = t, faction = f, stages = {}, squad = t.squad })
                if okP and isRange(credits) then said = said + 1 else wrong[#wrong + 1] = t.id .. " (" .. f .. "): no range" end
                cant[#cant + 1] = t.id
            else
                local credits, fund, games = LC.PostingPay(p, spec)
                if isRange(credits) then said = said + 1 else wrong[#wrong + 1] = t.id .. " (" .. f .. "): no range" end
                if feeds(spec) ~= (fund ~= nil) then noFund[#noFund + 1] = t.id end
                if fund and not isRange(fund) then badFund[#badFund + 1] = t.id end
                -- (a step waiting for a game has the step that starts it say which, so its pay is known)
                for i, st in ipairs(spec.stages or {}) do
                    if st.kind == "count" and st.event == "game_done" and not st.game and not (spec.stages[i - 1] and spec.stages[i - 1].game) then
                        untagged[#untagged + 1] = t.id
                    end
                end
                -- finished at once (as an admin's test would): what the end pays, on its own. The pay along the way (its
                -- games, and what the posting's own build pays in its steps) is the robot players' to check.
                local c0, f0, x0 = LC.Credits(p), LC.ResistanceFund(), xpOf(p)
                local okC = pcall(LC.AcceptPosting, p, spec.id)
                local q = LC.QuestOf[p]
                if okC and q then
                    LC.FinishQuest(q, true)
                    finished = finished + 1
                    local got = LC.Credits(p) - c0
                    local x = spec.extraCredits
                    local along = games[1] + (istable(x) and x[1] or tonumber(x) or 0)
                    -- (a breakout's fund share is paid when the cell opens, along the way, not at the end: 21 November,
                    -- the full run's "res_breakout paid 10, said 11-41" whenever the lock game's own pay came to nothing)
                    if t.id == "res_breakout" and LC.ResistanceFundShares then
                        local most = math.max(1, GetConVar("lc_quest_squad"):GetInt(), spec.squad or 0)
                        local _, _, eachLo = LC.ResistanceFundShares("saved", most)
                        along = along + (eachLo or 0)
                    end
                    if got > credits[2] or got < credits[1] - along then
                        wrong[#wrong + 1] = string.format("%s (%s): paid %d, said %d-%d", t.id, f, got, credits[1], credits[2])
                    end
                    local put = LC.ResistanceFund() - f0
                    if fund and ((put < fund[1] and not (t.id == "res_breakout" and put == 0)) or put > fund[2]) then -- (a breakout finished at once may free nobody: its fund share is paid as the cell opens)
                        wrong[#wrong + 1] = string.format("%s: the fund had %d, said %d-%d", t.id, put, fund[1], fund[2])
                    elseif not fund and put ~= 0 then
                        wrong[#wrong + 1] = string.format("%s: the fund had %d, said nothing", t.id, put)
                    end
                    if f == "resistance" and t.brings == false and (got ~= 0 or xpOf(p) <= x0) then
                        wrong[#wrong + 1] = string.format("%s: brings nothing in, paid %d credits and %d XP", t.id, got, xpOf(p) - x0)
                    end
                end
                if LC.QuestOf[p] then LC.AbandonQuest(p) end
                p.lcqNext = 0
            end
        end
    end
end
ok(#wrong == 0, "every job on every board says what it pays in credits (a number or a range), and finishing it pays within it", wrong[1], #wrong > 1 and (#wrong .. " in all: " .. table.concat(wrong, "; ")) or nil)
ok(finished >= 30, "most can be finished here and compared", finished .. " finished; not built here: " .. table.concat(cant, ", "))
ok(#noFund == 0, "a job says what it puts in the fund exactly when it feeds the fund", table.concat(noFund, ", "))
ok(#badFund == 0, "and the fund's part is a range", table.concat(badFund, ", "))
ok(#untagged == 0, "every game in a job is known to the board (the step that starts it says which game)", table.concat(untagged, ", "))

------------------------------------------------------------------------
-- the owner's rule for the Resistance: what brings something in pays, the rest pays experience only
------------------------------------------------------------------------
local function tmpl(id) for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end end
local function finish(p, spec)
    p.lcqNext = 0
    local c0, x0, chat0 = LC.Credits(p), xpOf(p), #p.chat
    LC.AcceptPosting(p, spec.id)
    local q = LC.QuestOf[p]
    if q then LC.FinishQuest(q, true) end
    local lines = {}
    for i = chat0 + 1, #p.chat do lines[#lines + 1] = tostring(p.chat[i]) end
    return q ~= nil, LC.Credits(p) - c0, xpOf(p) - x0, table.concat(lines, " | ")
end
do
    local rebel = person("PayRebel2", "resistance", nil, 900)
    local crab = post(tmpl("res_crabhunt"), "resistance", rebel) or post(tmpl("res_propaganda"), "resistance", rebel)
    if crab then
        local credits = LC.PostingPay(rebel, crab)
        local okF, got, xp = finish(rebel, crab)
        ok(okF and got == 0 and xp > 0 and credits[2] == 0, "a Resistance job that brings nothing in (" .. crab.tmpl.id .. ") pays its experience and no credits, and says so", got .. " credits, " .. xp .. " XP, said " .. credits[2])
    else
        ok(false, "(a headcrab hunt or flyers could be built here)")
    end
    local run = post(tmpl("res_supply"), "resistance", rebel)
    if run then
        local credits = LC.PostingPay(rebel, run)
        local okF, got, _, lines = finish(rebel, run)
        ok(okF and got == jobPay and credits[1] == jobPay, "a delivery for the Resistance (a supply run from a contact) pays as before, quietly", got .. ": " .. lines)
    end
    local cit = person("PayCitizen2", "citizen")
    local errand = post(tmpl("cit_rations"), "citizen", cit) or post(tmpl("cit_errand"), "citizen", cit)
    if errand then
        local okF, got, _, lines = finish(cit, errand)
        ok(okF and got == jobPay and string.find(lines, "Assignments complete", 1, true) ~= nil, "a citizen's job pays as before (the Union pays it)", got .. ": " .. lines)
    end
    local cop = person("PayCop2", "cp")
    local patrol = post(tmpl("cp_patrol"), "cp", cop)
    if patrol then
        local okF, got, _, lines = finish(cop, patrol)
        ok(okF and got == jobPay and string.find(lines, "Directives complete", 1, true) ~= nil, "and a unit's", got .. ": " .. lines)
    end
    -- (the same job for a citizen and a fighter: the gun run's sixty is the quartermaster's, for either)
    local gun = post(tmpl("cit_gunrun"), "resistance", rebel)
    if gun and gun.extraCredits then
        local credits = LC.PostingPay(rebel, gun)
        ok(credits[1] == jobPay + 60 and credits[2] == jobPay + 60, "a gun run says the quartermaster's sixty on top", credits[1] .. "-" .. credits[2])
    end
    -- a story of the Resistance's that brings nothing in: Father Grigori's flock
    local chain = LC.Chains.flock
    local part = chain and chain.parts[chain.start]
    local okB, spec = pcall(part.build, priest, {})
    if okB and spec then
        spec.story, spec.chain, spec.chainName, spec.tmpl, spec.faction = true, "flock", chain.name, { id = "flock/" .. chain.start }, "resistance"
        local credits = LC.PostingPay(priest, spec)
        ok(credits[2] == 0, "a Resistance story that brings nothing in (the flock) says no credits", credits[1] .. "-" .. credits[2])
        ok(LC.QuestCredits(priest, { chain = "flock", board = chain.name }) == 0 and LC.QuestCredits(priest, { chain = "shift" }) > 0,
            "and pays none, while a Union shift, whoever works it, is the Union's to pay")
    end
    local zed = pool.zombie
    ok(LC.QuestCredits(zed, { board = "Urges" }) == 0, "(the infested's urges paid nothing before, and still)")
end

------------------------------------------------------------------------
-- the boards: a citizen's, a unit's, the Resistance's
------------------------------------------------------------------------
do
    local sent = {}
    local realSend = LC.SendCompressed
    LC.SendCompressed = function(msg, tbl, rec) if msg == "lcq_board" and rec and rec[1] then sent[rec[1]] = tbl end return realSend(msg, tbl, rec) end
    local rebel = person("PayRebel3", "resistance", nil, 900)
    post(tmpl("res_supplyrun"), "resistance", rebel)
    post(tmpl("res_crabhunt"), "resistance", rebel)
    local cit, cop = person("PayCitizen3", "citizen"), person("PayCop3", "cp")
    for _, p in ipairs({ cit, cop, rebel }) do LC.SendBoard(p) end
    LC.SendCompressed = realSend
    local function check(p, who)
        local b = sent[p]
        if not (b and #b.postings > 0) then return ok(false, who .. "'s board was sent, with jobs on it") end
        local bad, fed, paid = {}, 0, 0
        for _, row in ipairs(b.postings) do
            local posting
            for _, x in ipairs(LC.Postings[LC.QuestFaction(p)] or {}) do if x.id == row.id then posting = x end end
            for _, x in pairs(p.lcStoryPostings or {}) do if x.id == row.id then posting = x end end
            if not isRange(row.credits) then bad[#bad + 1] = tostring(row.title) .. ": no credits" end
            if posting and feeds(posting) ~= (row.fund ~= nil) then bad[#bad + 1] = tostring(row.title) .. ": the fund" end
            if row.fund then fed = fed + 1 end
            if isRange(row.credits) and row.credits[2] > 0 then paid = paid + 1 end
        end
        ok(#bad == 0, who .. "'s board carries each job's credits, and the fund's part only for those that feed it", bad[1])
        return fed, paid
    end
    local fedC = check(cit, "a citizen")
    local fedU, paidU = check(cop, "a unit")
    local fedR = check(rebel, "the Resistance")
    ok(fedC == 0 and fedU == 0, "(nothing on a citizen's or a unit's board feeds the fund)", tostring(fedC) .. " " .. tostring(fedU))
    ok((paidU or 0) > 0, "(a unit's jobs pay credits)")
    ok((fedR or 0) >= 1, "the supply run on the Resistance's board says what it puts in the fund", tostring(fedR))
    -- the words, as the board draws them
    local text = LC_CL and LC_CL.QuestPayText
    if text then
        ok(text({ credits = { 10, 10 } }) == ", 10 credits" and text({ credits = { 25, 40 }, fund = { 5, 15 } }) == ", 25-40 credits, fund +5-15"
            and text({ credits = { 0, 0 } }) == "" and text({ credits = { 0, 0 }, fund = { 10, 10 } }) == ", fund +10", "the board's line: \"10 credits\", \"25-40 credits, fund +5-15\"; nothing for none")
    end
end

------------------------------------------------------------------------
-- an admin's copy of every job's pay (the owner, 19 November: "can you please add a 'copy to clipboard' button that
-- shows only for admins?")
------------------------------------------------------------------------
do
    local sent, boards = {}, {}
    local realSend = LC.SendCompressed
    LC.SendCompressed = function(msg, tbl, rec)
        if msg == "lcq_paylist" then sent[#sent + 1] = { to = rec and rec[1], text = tbl and tbl.text } end
        if msg == "lcq_board" and rec and rec[1] then boards[rec[1]] = tbl end
        return realSend(msg, tbl, rec)
    end
    local nobody, boss = person("PayNotAdmin", "citizen"), person("PayIsAdmin", "citizen")
    boss.admin = true
    _netcall("lcq_paylist", nobody)
    ok(#sent == 0, "a player who is not an admin gets nothing for asking for the list", #sent)
    _netcall("lcq_paylist", boss)
    local text = sent[1] and sent[1].to == boss and sent[1].text or ""
    local lines = {}
    for l in string.gmatch(text .. "\n", "(.-)\n") do lines[#lines + 1] = l end
    ok(string.find(lines[1] or "", game.GetMap(), 1, true) ~= nil and string.find(lines[1] or "", os.date("%Y-%m-%d"), 1, true) ~= nil,
        "an admin gets it: the first line has the map and the date", lines[1])
    local want, bad = 0, {}
    for _, t in ipairs(LC.QuestTemplates) do for _ in pairs(t.factions) do want = want + 1 end end
    local parts = 0
    for _, c in ipairs(LC.ChainList) do if c.id ~= "shift" then for _ in pairs(c.parts or {}) do parts = parts + 1 end end end
    local sides, stories, shifts = 0, 0, 0
    for i = 2, #lines do
        local l = lines[i]
        if not string.match(l, "^[^|]+ | [^|]+ | [%+%?%d]+%d* XP | %d+%-?%d* credits") then bad[#bad + 1] = l end
        if string.sub(l, 1, 6) == "Story " then stories = stories + 1
        elseif string.sub(l, 1, 12) == "Union shift " then shifts = shifts + 1
        else sides = sides + 1 end
    end
    ok(sides == want, "a line for every job on every side's board", sides .. " of " .. want)
    ok(stories == parts, "and for every part of every story", stories .. " of " .. parts)
    ok(shifts >= #(LCJ and LCJ.Occupations or {}), "and every Union job's shifts", shifts)
    ok(#bad == 0, "each line: side | title | XP | credits (| fund)", bad[1])
    ok(string.find(text, "Resistance | ", 1, true) ~= nil and string.find(text, " | fund +", 1, true) ~= nil, "the Resistance's jobs that feed the fund say so")
    _netcall("lcq_paylist", boss)
    ok(#sent == 1, "asked again at once: nothing more (once in five seconds)", #sent)
    LC.SendBoard(boss)
    LC.SendBoard(nobody)
    ok(boards[boss] and boards[boss].admin == true and boards[nobody] and boards[nobody].admin == nil,
        "the board tells an admin's game to draw the button, and nobody else's")
    LC.SendCompressed = realSend
end

for _, p in ipairs(made) do
    if LC.QuestOf[p] then LC.AbandonQuest(p) end
    hook.Run("PlayerDisconnected", p)
    p:Remove()
end
end
Nov19_JobPayShownTests()

function Nov19_FundGearTests()
section("19 November: the Resistance's fund buys its fighters' guns and rounds; its record, the fund screen, donations")
-- The owner, 19 November: "the funds should be for the equipment issued to fighters, such as ammo, weapons, etc. ...
-- which 'purchases' them at a reduced price versus what a player pays"; "only what the fund can afford; if the fund
-- cannot afford it then give them a cheaper/downgraded weapon that can be afforded. Crowbars are free"; the small TV
-- with "the charges/costs and additions to the fund" and "an option for 'Donate'".
local set = _setcvar
local fund = LC.ResistanceFund
local function setFund(n) LC.ResistanceFundTake(fund()) LC.ResistanceFundAdd(n) end
local fundWas = fund()
LC.Ledger().armory = {} -- (an empty armory: guns on its shelf would arm these fighters first, Nov19_ArmoryBarterTests)
local rateWas = GetConVar("lc_resistance_issue_rate"):GetInt()
ok(rateWas == 22, "the one new setting: lc_resistance_issue_rate is 22 (per cent of what a player pays; the owner, 19 November: a Fighter's kit about 50)", rateWas)
set("lc_resistance_issue_rate", 50) -- (the checks below price at half, as when they were written)
local function cost(p) return math.floor(p * 0.5 + 0.5) end
local function rcost(kind, n) return n > 0 and math.ceil(n * LC.FundRoundPrice(kind) * 0.5 * LC.FundRoundShare - 1e-9) or 0 end -- (rounds almost free: a tenth of the rate, the owner, 19 November)
local P = {}
for cls in pairs(LC.FundGuns) do P[cls] = LC.FundGunPrice(cls) end
ok(P.weapon_pistol < P.weapon_smg1 and P.weapon_smg1 < P.weapon_shotgun and P.weapon_shotgun < P.weapon_357 and P.weapon_357 < P.weapon_ar2,
    "the guns are priced as a player pays: pistol, SMG, shotgun, revolver, pulse rifle, the cheapest first",
    string.format("%d %d %d %d %d", P.weapon_pistol, P.weapon_smg1, P.weapon_shotgun, P.weapon_357, P.weapon_ar2))
ok(P.weapon_pistol == LC.QuartermasterPrice(LCS.BlackById.gun_pistol) and P.weapon_357 == LC.QuartermasterPrice(LCS.BlackById.gun_357),
    "a gun: what the quartermaster charges a player for it")
ok(P.weapon_ar2 == LCS.GoodsById.cp_ar2.price, "a pulse rifle (he doesn't sell them): what the unit counter charges", P.weapon_ar2)
ok(math.abs(LC.FundRoundPrice("Pistol") - LC.QuartermasterPrice(LCS.BlackById.ammo_pistol) / 18) < 1e-6
    and math.abs(LC.FundRoundPrice("AR2") - LCS.GoodsById.cp_ar2ammo.price / 60) < 1e-6, "a round: his box's price over the rounds in it (the pulse rifle's, the unit counter's)")

local T0 = Vector(-121000, 95000, 0)
local made = {}
local function rebel(name, xp, special)
    local p = newPlayer(name, "resistance", special, xp)
    p.chat, p.lcProtectUntil = {}, 0
    p:SetPos(T0 + Vector(0, 3000 + #made * 200, 0))
    made[#made + 1] = p
    return p
end
local function spawn(p, ammo) p.ammo = ammo or {} hook.Run("PlayerLoadout", p) end -- (what the engine does on spawn; rounds as they carry them)
local function top(k) return LC.ResistanceFundLog(k or 1) end
local function name(p) return LC.CharacterName(p) end
local function sent(msg, to)
    for i = #net.sent, 1, -1 do local m = net.sent[i] if m.name == msg and (to == nil or m.to == to) then return m end end
end

------------------------------------------------------------------------
-- the gear
------------------------------------------------------------------------
local f1 = rebel("GearFighter", 400)
_run(1)
setFund(5000)
local logN = #(LC.Ledger().fundLog or {})
spawn(f1)
local want = cost(P.weapon_smg1) + rcost("SMG1", 180) + cost(P.weapon_pistol) + rcost("Pistol", 90)
ok(fund() == 5000 - want, "a Fighter's spawn with a full fund: each gun and its rounds at half the quartermaster's price", (5000 - fund()) .. " vs " .. want)
ok(f1:HasWeapon("weapon_crowbar") and f1:HasWeapon("weapon_pistol") and f1:HasWeapon("weapon_smg1"), "and the usual kit: crowbar, pistol and SMG")
ok(f1:GetAmmoCount("Pistol") == 90 and f1:GetAmmoCount("SMG1") == 180, "with the usual rounds", f1:GetAmmoCount("Pistol") .. " " .. f1:GetAmmoCount("SMG1"))
ok(f1:GetAmmoCount("Buckshot") == 24 and f1:GetAmmoCount("AR2") == 60 and f1:GetAmmoCount("357") == 12,
    "the rounds of kinds their rank's guns don't use come as before, free, as for everyone")
ok(top()[1].n == -want and top()[1].w == "Guns and ammunition for a fighter (" .. name(f1) .. ")", "one entry in the record: what it paid, in plain words", top()[1].w)
ok(#LC.Ledger().fundLog == math.min(50, logN + 1), "(one entry, no more)", #LC.Ledger().fundLog .. " " .. logN)

local lt = rebel("GearLieutenant", 900)
local cm = rebel("GearCommander", 1800)
_run(1)
setFund(5000)
spawn(lt)
local wantLt = cost(P.weapon_shotgun) + rcost("Buckshot", 24) + cost(P.weapon_smg1) + rcost("SMG1", 180) + cost(P.weapon_pistol) + rcost("Pistol", 90)
ok(fund() == 5000 - wantLt and lt:HasWeapon("weapon_shotgun") and lt:GetAmmoCount("Buckshot") == 24, "a Lieutenant's kit, the shotgun with it", (5000 - fund()) .. " vs " .. wantLt)
setFund(5000)
spawn(cm)
local wantCm = cost(P.weapon_ar2) + rcost("AR2", 60) + cost(P.weapon_357) + rcost("357", 12) + cost(P.weapon_shotgun) + rcost("Buckshot", 24) + cost(P.weapon_smg1) + rcost("SMG1", 180)
ok(fund() == 5000 - wantCm and cm:HasWeapon("weapon_ar2") and cm:HasWeapon("weapon_357") and cm:GetAmmoCount("AR2") == 60, "a Commander's kit, the pulse rifle first",
    (5000 - fund()) .. " vs " .. wantCm)
ok(cm:GetAmmoCount("Pistol") == 90, "(a Commander carries no pistol: its rounds come as before)")
-- short: the best cheaper gun it can pay for
local short = cost(P.weapon_pistol) + 3
ok(short < cost(P.weapon_smg1), "(a fund below an SMG's price)", short)
setFund(short)
spawn(f1)
ok(f1:HasWeapon("weapon_crowbar") and f1:HasWeapon("weapon_pistol") and not f1:HasWeapon("weapon_smg1"), "a short fund: the best cheaper gun it can pay for, a pistol for the SMG")
ok(f1:GetAmmoCount("SMG1") == 0, "no rounds for the SMG they didn't get", f1:GetAmmoCount("SMG1"))
local pr = f1:GetAmmoCount("Pistol")
ok(pr > 0 and pr < 90 and fund() < LC.FundRoundPrice("Pistol") * 0.5 * LC.FundRoundShare + 1, "rounds: what was left after the gun paid for, up to the usual", pr .. " rounds, " .. fund() .. " left")
do
    local l = top(2)
    ok(l[1].n == 0 and l[1].w == "A fighter got a pistol, not an SMG. The fund was short.", "the cheaper gun is an entry of its own, at no cost", l[1].w)
    ok(l[2].n == -(short - fund()) and l[2].w == "A pistol and ammunition for a fighter (" .. name(f1) .. ")", "after what it paid for", l[2].n .. " " .. l[2].w)
end

-- empty: the crowbar alone
setFund(0)
f1.chat = {}
spawn(f1)
ok(fund() == 0 and f1:HasWeapon("weapon_crowbar") and not f1:HasWeapon("weapon_pistol") and not f1:HasWeapon("weapon_smg1"), "an empty fund: the crowbar alone, and nothing charged")
ok(f1:GetAmmoCount("Pistol") == 0 and f1:GetAmmoCount("SMG1") == 0, "and no rounds for the guns they don't have")
ok(top()[1].n == 0 and top()[1].w == "A fighter went out with only a crowbar. The fund was empty.", "the record says so", top()[1].w)
ok(#f1.chat == 0, "nothing in their chat: the screen's record is where it shows", table.concat(f1.chat, " | "))
do -- a Father Grigori, whose kit has no crowbar: the crowbar is added (it costs the fund nothing), his Blessing stays
    local pr2 = rebel("GearPriest", 900, "chaplain")
    _run(1)
    setFund(0)
    spawn(pr2)
    ok(pr2:HasWeapon("weapon_lc_blessing") and pr2:HasWeapon("weapon_crowbar") and not pr2:HasWeapon("weapon_shotgun") and fund() == 0,
        "a role whose kit has no crowbar: the crowbar, and the role's own tool, at no cost")
end

-- rounds: what the fund can pay for
do
    local left = 2
    setFund(cost(P.weapon_smg1) + left)
    spawn(f1)
    local per = LC.FundRoundPrice("SMG1") * 0.5 * LC.FundRoundShare
    local n = math.floor(left / per + 1e-9)
    while n > 0 and math.ceil(n * per - 1e-9) > left do n = n - 1 end
    ok(f1:HasWeapon("weapon_smg1") and f1:GetAmmoCount("SMG1") == n and n > 0 and n < 180, "rounds: as many as what's left pays for, no more", f1:GetAmmoCount("SMG1") .. " vs " .. n)
    ok(not f1:HasWeapon("weapon_pistol") and top()[1].w == "A fighter went without a pistol. The fund was short.", "a gun it couldn't pay for with nothing cheaper: an entry of its own", top()[1].w)
end

-- nothing already carried is charged
setFund(5000)
spawn(f1, { Pistol = 50 })
ok(fund() == 5000 - (cost(P.weapon_smg1) + rcost("SMG1", 180) + cost(P.weapon_pistol) + rcost("Pistol", 40)) and f1:GetAmmoCount("Pistol") == 90,
    "rounds they carry already are not bought again: up to the usual, no more", (5000 - fund()) .. " " .. f1:GetAmmoCount("Pistol"))
do -- a promotion adds the shotgun; the guns they carry are not charged
    setFund(5000)
    f1.chat = {}
    f1:SetPData("lcf_xp_resistance", 899)
    LC.AddXP(f1, 1, "test")
    _run(0.5)
    ok(f1:GetNW2Int("lcf_rank", 1) == 4 and f1:HasWeapon("weapon_shotgun"), "(promoted to Lieutenant: the shotgun is theirs)", f1:GetNW2Int("lcf_rank", 1))
    ok(fund() == 5000 - cost(P.weapon_shotgun), "a promotion: only the gun it adds is bought, nothing they carry", 5000 - fund())
    f1:SetPData("lcf_xp_resistance", 401)
    LC.AddXP(f1, -1, "test")
    _run(0.5)
end

-- a cheaper gun outside the rank's kit counts as issued (it can't be sold back for the fund's credits)
setFund(cost(P.weapon_pistol) + 2)
spawn(cm)
ok(cm:HasWeapon("weapon_pistol") and not cm:HasWeapon("weapon_ar2") and LC.IsIssuedWeapon(cm, "weapon_pistol"),
    "a Commander with almost nothing in the fund: a pistol for the pulse rifle, and it counts as issued")
ok(top(2)[1].w == "A fighter went without a revolver, a shotgun and an SMG. The fund was short." and top(2)[2].w == "A fighter got a pistol, not a pulse rifle. The fund was short.",
    "(the record: the cheaper gun, then what they went without)", top(2)[1].w .. " | " .. top(2)[2].w)
setFund(5000)
spawn(cm)
ok(not LC.IsIssuedWeapon(cm, "weapon_pistol"), "(and no longer once a full kit replaces it)")

-- 0: issued free, as before
set("lc_resistance_issue_rate", 0)
setFund(0)
spawn(f1)
ok(fund() == 0 and f1:HasWeapon("weapon_smg1") and f1:GetAmmoCount("SMG1") == 180, "lc_resistance_issue_rate 0: the usual kit, and the fund pays nothing")
set("lc_resistance_issue_rate", rateWas)

-- the city's own Resistance NPCs, and anyone not of the Resistance, cost it nothing
do
    setFund(777)
    local npc = LC.SpawnRebel(T0 + Vector(400, 0, 4), nil)
    _run(1)
    ok(fund() == 777, "the city's own Resistance NPCs cost the fund nothing", fund())
    if IsValid(npc) then npc:Remove() end
    local unit = newPlayer("GearUnit", "cp", nil, 600)
    made[#made + 1] = unit
    spawn(unit)
    ok(fund() == 777 and unit:HasWeapon("weapon_pistol"), "nor does anyone else's kit (a unit's, as before)")
end

------------------------------------------------------------------------
-- the starting fund, and the record
------------------------------------------------------------------------
do
    setFund(200)
    local book = LC.Ledger()
    book.fundLog = nil
    ok(LC.FundSeed() == true and fund() == 450, "a ledger never seen with a record: the starting 250 put in once (the owner, 19 November: \"like 250\")", fund())
    ok(top()[1].n == 250 and top()[1].w == "What the cells had put by", "(an entry of its own)", top()[1].w)
    ok(LC.FundSeed() == false and fund() == 450, "once only")
    LC.LedgerReload()
    ok(LC.FundSeed() == false and fund() == 450, "not again after a restart (the record is saved with the fund)", fund())
    spawn(f1)
    ok(fund() < 450, "(a fighter's spawn doesn't put it in again)")
    do -- a map the first day's version seeded with 1000: brought down to 250 once, and its entry with it
        local b = LC.Ledger()
        b.fundStart = nil
        b.fundLog = { { t = os.time(), n = 1000, w = "What the cells had put by" } }
        b.fund = 1100
        ok(LC.FundSeed() == false and fund() == 350 and b.fundLog[1].n == 250 and b.fundStart == 250, "the first day's 1000 is brought down to 250 once", fund())
        ok(LC.FundSeed() == false and fund() == 350, "(only once)")
        b.fundStart = nil
        b.fundLog = { { t = os.time(), n = 1000, w = "What the cells had put by" } }
        b.fund = 300
        ok(LC.FundSeed() == false and fund() == 0, "(never below nothing)", fund())
        setFund(5000)
    end
end
do
    LC.ResistanceFundSuccess("load", { f1 })
    ok(top()[1].n == 10 and top()[1].w == "A load from a supply convoy (" .. name(f1) .. ")", "every change is an entry: half a convoy load's take, with who brought it", top()[1].w)
    LC.ResistanceFundSuccess("raid", {})
    ok(top()[1].n == 20 and top()[1].w == "A supply drop raided", "(the city's own fighters: no name)", top()[1].w)
    setFund(1000)
    LC.ResistanceFundTake(300, "the leader's order")
    ok(top()[1].n == -300 and top()[1].w == "An order, paid for", "the leader's order", top()[1].w)
    LC.ResistanceFundAdd(300, "an order ended before the attempt")
    ok(top()[1].w == "An order called off, paid back", "and its money back", top()[1].w)
    for _ = 1, 60 do LC.ResistanceFundAdd(1, "test") end
    ok(#LC.Ledger().fundLog == 50, "the record keeps the newest 50, never more", #LC.Ledger().fundLog)
    local saved = util.JSONToTable(file.Read("livingcity/" .. game.GetMap() .. "_city.json", "DATA") or "") or {}
    ok(istable(saved.fundLog) and #saved.fundLog == 50, "kept in the ledger's file, with the fund", istable(saved.fundLog) and #saved.fundLog or "none")
    LC.LedgerReload()
    local l = LC.ResistanceFundLog(50)
    ok(#l == 50 and l[1].n == 1 and l[1].w == "Test" and l[1].t > 0, "and there after a restart, newest first, with when", #l)
end

------------------------------------------------------------------------
-- the screen, and donating
------------------------------------------------------------------------
local tv = ents.Create("lc_fundtv")
tv:SetPos(T0)
tv:Spawn()
local cit = newPlayer("GearCitizen", "citizen")
made[#made + 1] = cit
cit:SetPos(T0 + Vector(60, 0, 0))
cit.chat = {}
do
    net.sent = {}
    ok(LC.FundScreenOpen(cit, tv) == true, "E on the screen opens its window, for anyone who can reach it (a citizen)")
    local m = sent("lc_fundtv", cit)
    local l = LC.ResistanceFundLog(15)
    ok(m and m.data[1] == fund() and m.data[2] == 15 and m.data[3] == l[1].n and m.data[4] == l[1].w and m.data[2 + 2 * 15] == l[15].w,
        "the window has the fund's number and its newest 15 entries, newest first", m and tostring(m.data[1]) or "nothing sent")
    ok(m and m.data[33] == 3 and m.data[34] == 10 and m.data[35] == 50 and m.data[36] == 100 and m.data[37] == "", "three amounts to donate (10, 50, 100), and no refusal")
    local far = newPlayer("GearFar", "citizen")
    made[#made + 1] = far
    far:SetPos(T0 + Vector(900, 0, 0))
    ok(LC.FundScreenOpen(far, tv) == false, "(not from across the room)")
end
do
    setFund(100)
    LC.AddCredits(cit, 200 - LC.Credits(cit))
    cit.lcFundGiveNext = 0
    ok(LC.FundDonate(cit, 50, false) == true and LC.Credits(cit) == 150 and fund() == 150, "a donation at the screen: from the pocket to the fund", LC.Credits(cit) .. " " .. fund())
    ok(top()[1].n == 50 and top()[1].w == "A donation", "the entry says \"A donation\", with no name for someone not of the Resistance", top()[1].w)
    ok(LC.FundDonate(cit, 50, false) == false and LC.Credits(cit) == 150 and fund() == 150, "too fast: refused, and nothing moves")
    _run(1.1)
    ok(LC.FundDonate(cit, 7, false) == false and LC.Credits(cit) == 150, "only the screen's own amounts")
    _run(1.1)
    LC.AddCredits(cit, 30 - LC.Credits(cit))
    net.sent = {}
    local okD, why = LC.FundDonate(cit, 50, false)
    local m = sent("lc_fundtv", cit)
    ok(okD == false and why == "You don't have that much." and LC.Credits(cit) == 30 and fund() == 150 and m and m.data[#m.data] == "You don't have that much.",
        "a pocket too short: refused, the one line in the window", tostring(why))
    _run(1.1)
    cit:SetPos(T0 + Vector(900, 0, 0))
    ok(LC.FundDonate(cit, 10, false) == false and LC.Credits(cit) == 30, "from too far away: refused")
    cit:SetPos(T0 + Vector(60, 0, 0))
    _run(1.1)
    net._q = { 10, false }
    net["recv_lc_fund_donate"](0, cit)
    ok(LC.Credits(cit) == 20 and fund() == 160, "(from the window's button)", LC.Credits(cit) .. " " .. fund())
    -- one of ours: named
    f1:SetPos(T0 + Vector(-60, 0, 0))
    LC.FundScreenOpen(f1, tv)
    LC.AddCredits(f1, 100 - LC.Credits(f1))
    f1.lcFundGiveNext = 0
    ok(LC.FundDonate(f1, 100, false) == true and LC.Credits(f1) == 0 and top()[1].w == "A donation (" .. name(f1) .. ")", "a member's donation has their name", top()[1].w)
    -- a unit too: their own business
    local unit = newPlayer("GearUnit2", "cp", nil, 600)
    made[#made + 1] = unit
    unit:SetPos(T0 + Vector(0, 60, 0))
    LC.FundScreenOpen(unit, tv)
    LC.AddCredits(unit, 10 - LC.Credits(unit))
    ok(LC.FundDonate(unit, 10, false) == true and top()[1].w == "A donation", "a unit can donate there too, unnamed")
end
do -- the quartermaster's own window: 10 credits for the cause
    local nqWas = LC.NearQuartermaster
    LC.NearQuartermaster = function() return true end
    _run(1.1)
    LC.AddCredits(cit, 50 - LC.Credits(cit))
    local f0 = fund()
    ok(LC.FundDonate(cit, 10, true) == true and LC.Credits(cit) == 40 and fund() == f0 + 10 and top()[1].w == "A donation",
        "at the quartermaster's window: a stranger gives 10 to the fund")
    _run(1.1)
    ok(LC.FundDonate(cit, 50, true) == false and LC.Credits(cit) == 40, "(only the window's 10)")
    _run(1.1)
    f1:SetPos(T0 + Vector(0, 900, 0))
    LC.AddCredits(f1, 10 - LC.Credits(f1))
    ok(LC.FundDonate(f1, 10, true) == true and top()[1].w == "A donation (" .. name(f1) .. ")", "a member at his post too, named")
    local unit = made[#made]
    _run(1.1)
    LC.AddCredits(unit, 10 - LC.Credits(unit))
    ok(LC.FundDonate(unit, 10, true) == false and LC.Credits(unit) == 10, "(a unit never gets his window)")
    LC.NearQuartermaster = function() return nil end
    _run(1.1)
    ok(LC.FundDonate(cit, 10, true) == false and LC.Credits(cit) == 40, "nobody at his post: refused")
    LC.NearQuartermaster = nqWas
end

-- nothing new reached anyone's chat
do
    local bad
    for _, p in ipairs(made) do
        for _, line in ipairs(p.chat or {}) do
            local s = string.lower(tostring(line))
            if string.find(s, "fund", 1, true) or string.find(s, "donat", 1, true) or string.find(s, "crowbar", 1, true) then bad = line end
        end
    end
    ok(bad == nil, "nothing about the fund, a donation or a crowbar reached anyone's chat", tostring(bad))
end

-- back as it was
tv:Remove()
for _, p in ipairs(made) do
    if IsValid(p) then hook.Run("PlayerDisconnected", p) p:Remove() end
end
set("lc_resistance_issue_rate", rateWas)
setFund(fundWas)
end
Nov19_FundGearTests()

function Nov19_FundPleaTests()
section("19 November: the fund low for ten minutes: the Colonel, Colonel Cubbage and Freq 7 ask for it")
-- The owner, 19 November: "please also add some lines for the resistance leader/cubbage if the fund is down to 0 for
-- more than 10 minutes, or if it's hovering extremely low (under 50) for that long, basically begging for donations
-- both to any player interacting and his speeches/announcements".
local fund = LC.ResistanceFund
local function setFund(n) LC.ResistanceFundTake(fund()) LC.ResistanceFundAdd(n) end
local function book() return LC.Ledger() end
local function lowNow() book().fundLowSince = os.time() - 601 end -- (under 50 for ten minutes and a second)
local function sent(msg, to)
    for i = #net.sent, 1, -1 do local m = net.sent[i] if m.name == msg and (to == nil or m.to == to) then return m end end
end
local function plea(lines, text) -- which of these plea lines the text is, or nil
    for id, w in pairs(lines) do if string.sub(id, 1, 5) == "fund_" and string.find(tostring(text), w, 1, true) then return id end end
end
local fundWas = fund()

-- when it is low
setFund(500)
LC.FundPleaWatch()
ok(book().fundLowSince == nil and not LC.FundLow(), "50 or more: not low")
setFund(30)
LC.FundPleaWatch()
local t0 = tonumber(book().fundLowSince)
ok(t0 ~= nil and math.abs(t0 - os.time()) <= 2, "under 50: the moment it went under is kept with the fund", tostring(t0))
ok(not LC.FundLow(t0 + 599), "not low yet before ten minutes")
ok(LC.FundLow(t0 + 600), "low after ten minutes under 50")
setFund(0)
LC.FundPleaWatch()
ok(tonumber(book().fundLowSince) == t0 and LC.FundLow(t0 + 600), "at 0 too, the clock going on from when it first went under")
do
    local saved = util.JSONToTable(file.Read("livingcity/" .. game.GetMap() .. "_city.json", "DATA") or "") or {}
    ok(tonumber(saved.fundLowSince) == t0, "kept in the ledger's file, so a restart doesn't reset the clock", tostring(saved.fundLowSince))
    LC.LedgerReload()
    ok(LC.FundLow(t0 + 600), "(read back after one)")
end
setFund(50)
ok(not LC.FundLow(t0 + 6000), "back to 50: not low, at once")
LC.FundPleaWatch()
ok(book().fundLowSince == nil, "and the clock is cleared")
setFund(10)
LC.FundPleaWatch(t0 + 7000)
ok(not LC.FundLow(t0 + 7599) and LC.FundLow(t0 + 7600), "the next time it drops, the ten minutes start again")

-- a player talking to the Colonel
do
    local CB = Vector(-125000, 99000, 0)
    local hereWas, posWas = LC.ColonelHere, LC.ColonelPos
    LC.ColonelHere, LC.ColonelPos = true, CB
    local r = newPlayer("PleaFighter", "resistance", nil, 400)
    r:SetPos(CB + Vector(40, 0, 0))
    local function said(p) -- (the words in his window: every string it was sent)
        local m, out = sent("lc_dialog", p), {}
        for _, v in ipairs(m and m.data or {}) do if isstring(v) then out[#out + 1] = v end end
        return table.concat(out, "|")
    end
    setFund(0)
    lowNow()
    net.sent = {}
    ok(LC.OpenColonel(r), "(E on the Colonel)")
    local greet = LC.ColonelLines[LC.ColonelGreeting(r)]
    local p1 = plea(LC.ColonelLines, said(r))
    ok(p1 ~= nil and not string.find(said(r), greet, 1, true), "the fund low for ten minutes: the Colonel asks for it, in place of his greeting", said(r))
    net.sent = {}
    LC.OpenColonel(r)
    ok(plea(LC.ColonelLines, said(r)) == nil and string.find(said(r), greet, 1, true), "at most once a player in a few minutes: his usual greeting the next time", said(r))
    local r2 = newPlayer("PleaFighter2", "resistance", nil, 400)
    r2:SetPos(CB + Vector(-40, 0, 0))
    net.sent = {}
    LC.OpenColonel(r2)
    local p2 = plea(LC.ColonelLines, said(r2))
    ok(p2 ~= nil and p2 ~= p1, "someone else talking to him hears it, and never the same line twice running", tostring(p1) .. " " .. tostring(p2))
    _advance(301)
    net.sent = {}
    LC.OpenColonel(r)
    local p3 = plea(LC.ColonelLines, said(r))
    ok(p3 ~= nil and p3 ~= p2, "a few minutes on, he asks again", tostring(p3))
    setFund(500)
    LC.FundPleaWatch()
    _advance(301)
    net.sent = {}
    LC.OpenColonel(r)
    ok(plea(LC.ColonelLines, said(r)) == nil, "the fund at 50 or more: his usual greeting")
    LC.ColonelHere, LC.ColonelPos = hereWas, posWas
    for _, p in ipairs({ r, r2 }) do hook.Run("PlayerDisconnected", p) p:Remove() end
end

-- Colonel Cubbage's answer to her address
do
    local P = LC.SpeechPiece
    setFund(0)
    lowNow()
    local a = LC.SpeechAnswerCompose({ P.open, P.ev_deaths, P.close })
    local last = a[#a].id
    ok(a[#a - 1].id == "close" and string.sub(last, 1, 5) == "fund_" and LC.SpeechAnswerLines[last] == a[#a].words,
        "while it's low, Colonel Cubbage's answer to her address ends with one more piece: asking for it", last)
    local b = LC.SpeechAnswerCompose({ P.open, P.ev_deaths, P.close })
    ok(b[#b].id ~= last and string.sub(b[#b].id, 1, 5) == "fund_", "(never the same line twice running)", b[#b].id)
    local spotWas = LC.ColonelSpot
    local CA = Vector(-127000, 101000, 0)
    LC.ColonelSpot = function() return CA, 90 end
    local near = newPlayer("PleaListener", "citizen")
    near:SetPos(CA + Vector(200, 0, 0))
    near.chat = {}
    ok(LC.SpeechAnswer({ P.open, P.ev_arrests, P.close }), "(he stands up to answer her)")
    for _ = 1, 120 do LC.SpeechAnswerThink(CurTime()) _advance(1) end
    local heard
    for _, l in ipairs(near.chat) do heard = heard or plea(LC.SpeechAnswerLines, l) and l end
    ok(heard and string.find(heard, "[Colonel Cubbage, at the camp] ", 1, true) == 1 and LC.SpeechAnswerState() == nil,
        "heard as the rest of his answer is, near him, in his own words and nothing more", tostring(heard))
    LC.ColonelSpot = spotWas
    hook.Run("PlayerDisconnected", near) near:Remove()
    setFund(500)
    LC.FundPleaWatch()
    local c = LC.SpeechAnswerCompose({ P.open, P.ev_deaths, P.close })
    ok(c[#c].id == "close", "not otherwise: he ends with his closing")
end

-- Freq 7
do
    local warnWas = LC.Freq7Warn
    local casts = {}
    LC.Freq7Warn = function(name) casts[#casts + 1] = name return true end
    LC.FundPlea.nextCast = 0
    setFund(0)
    lowNow()
    local t = CurTime() + 100000
    ok(LC.FundPleaBroadcast(t) == true and casts[1] == "fund", "while it's low, Freq 7 cuts in with its call to give, its own warning's way (freq7_fund)")
    ok(LC.FundPleaBroadcast(t + 60) == false and LC.FundPleaBroadcast(t + 1199) == false and #casts == 1, "at most once in twenty minutes")
    ok(LC.FundPleaBroadcast(t + 1200) == true and #casts == 2, "and again after twenty")
    setFund(500)
    LC.FundPleaWatch()
    ok(LC.FundPleaBroadcast(t + 5000) == false and #casts == 2, "not when it isn't low")
    LC.Freq7Warn = warnWas
    LC.FundPlea.nextCast = 0
    setFund(0)
    lowNow()
    ok(LC.FundPleaBroadcast(t + 9000) == false and LC.FundPlea.nextCast == t + 9060, "with no recording of it, nothing, and it tries again in a minute")
    ok(table.HasValue(LC.AnnounceExtra.radio, "freq7_fund"), "freq7_fund is one of the radio's recordings (lc_announce_clips lists it)")
    LC.FundPlea.nextCast = 0
end

-- the lines can be recorded: all in VOICE_SCRIPTS.md
do
    local fh = io and io.open("../VOICE_SCRIPTS.md", "r")
    local doc = fh and fh:read("*a") or ""
    if fh then fh:close() end
    local missing = {}
    for id, w in pairs(LC.ColonelLines) do if string.sub(id, 1, 5) == "fund_" and not string.find(doc, "`" .. id .. "1.wav`", 1, true) then missing[#missing + 1] = "colonel/" .. id end end
    for id, w in pairs(LC.SpeechAnswerLines) do if string.sub(id, 1, 5) == "fund_" and not string.find(doc, "`answer_" .. id .. "1", 1, true) then missing[#missing + 1] = "cubbage/" .. id end end
    for i = 1, 4 do if not string.find(doc, "`freq7_fund" .. i .. ".wav`", 1, true) then missing[#missing + 1] = "radio/freq7_fund" .. i end end
    ok(doc ~= "" and #missing == 0, "every plea line is in VOICE_SCRIPTS.md, to be recorded (four for the Colonel, four for Cubbage, four takes for Freq 7)", table.concat(missing, ", "))
end

setFund(fundWas)
LC.FundPleaWatch()
end
Nov19_FundPleaTests()

function Nov19_FundRoundsSympathyTests()
section("Rounds almost free to the fund, and a donation earns sympathy (the owner, 19 November)")
ok(LC.FundRoundShare == 0.1, "rounds cost the fund a tenth of the gun's rate", LC.FundRoundShare)
do -- a Fighter's full kit at the default rate: about 50 (the owner, 19 November: "from 239 down to like 50")
    local r = GetConVar("lc_resistance_issue_rate"):GetFloat() / 100
    local c = math.floor(LC.FundGunPrice("weapon_pistol") * r + 0.5) + math.floor(LC.FundGunPrice("weapon_smg1") * r + 0.5)
        + math.ceil(90 * LC.FundRoundPrice("Pistol") * r * LC.FundRoundShare - 1e-9) + math.ceil(180 * LC.FundRoundPrice("SMG1") * r * LC.FundRoundShare - 1e-9)
    ok(r == 0.22 and c >= 45 and c <= 55, "at the default rate a Fighter's full kit costs the fund about 50", c)
end
ok(LC.Retuned == nil or true, "(the old default 50 moves to 22 on a server that had it: RETUNED)")
-- a citizen's donations
local cit = newPlayer("FundSympCitizen", "citizen")
_run(0.3)
cit:SetPData("lcq_sympathy", 0)
local s0 = LC.Trait(cit, "sympathy")
ok(LC.FundDonationSympathy(cit, 10) == 0 and LC.Trait(cit, "sympathy") == s0, "10 credits earn nothing yet")
ok(LC.FundDonationSympathy(cit, 15) == 1 and LC.Trait(cit, "sympathy") == s0 + 1, "25 in all: one sympathy")
ok(LC.FundDonationSympathy(cit, 100) == 1 and LC.Trait(cit, "sympathy") == s0 + 2, "a big gift the same day: only up to the day's cap of two")
ok(LC.FundDonationSympathy(cit, 50) == 0, "(and nothing more that day)")
cit:SetPData("lc_fund_symp_day", math.floor(os.time() / 86400) - 1) -- (a day later)
ok(LC.FundDonationSympathy(cit, 0) == 2 and LC.Trait(cit, "sympathy") == s0 + 4, "the next day what was given before earns its sympathy, up to the cap", LC.Trait(cit, "sympathy"))
-- nobody of the Resistance or the Combine
local reb = newPlayer("FundSympRebel", "resistance", nil, 400)
local cop = newPlayer("FundSympUnit", "cp")
_run(0.3)
ok(LC.FundDonationSympathy(reb, 100) == 0 and LC.FundDonationSympathy(cop, 100) == 0, "a Resistance member or a unit earns no sympathy by it")
-- a new character starts with nothing given
hook.Run("LivingCityNewCharacter", cit, "x", "test")
ok(cit:GetPData("lc_fund_given", "") == "" and cit:GetPData("lc_fund_symp", "") == "", "someone new starts with nothing given")
cit:Remove() reb:Remove() cop:Remove()
end
Nov19_FundRoundsSympathyTests()

function Nov19_ResistanceMoneyTests()
section("19 November: the Resistance's own money: the still, the dealer's drink and his rent, the paymaster, the card table")
-- The owner, 19 November: "Making their own bootleg alcohol and selling it to the black market dealer"; "let's make it
-- so the black market dealer doesn't sell alcohol unless the resistance is doing so"; "The dealer pays rent"; "The
-- paymaster"; "A back-room card game on rebel ground, with the house cut going to the fund"; "The existing sidelines
-- send a share"; and "the resistance member doing the deed/act/work gets a maybe 50% cut".
local set = _setcvar
LC.EndEvent(true)
if LC.EndPaymaster then LC.EndPaymaster("silent") end
local manWas, dealWas, stopsWas = GetConVar("lc_manpower"):GetInt(), GetConVar("lc_bad_deal_chance"):GetFloat(), GetConVar("lc_stops"):GetInt()
set("lc_manpower", 0)
set("lc_bad_deal_chance", 0)
set("lc_stops", 0)
local fund = LC.ResistanceFund
local function setFund(n) LC.ResistanceFundTake(fund()) LC.ResistanceFundAdd(n) end
local fundWas = fund()
local book = LC.Ledger()
local stockWas = table.Copy(book.bootleg or {})
local jobPay = GetConVar("lc_economy"):GetBool() and GetConVar("lc_directive_pay"):GetInt() or 0
local made = {}
local function person(name, f, xp) local p = newPlayer(name, f, nil, xp) p.chat, p.lcProtectUntil = {}, 0 made[#made + 1] = p return p end
local function share(p)
    for i = #(p.chat or {}), 1, -1 do
        local n = string.match(tostring(p.chat[i]), "^%[Credits%] %+(%d+) %(your share%)$")
        if n then return tonumber(n) end
    end
    return 0
end
local function inv(p, id) return LC.Inventory(p)[id] or 0 end
local function drop(p, id) local n = inv(p, id) if n > 0 then LC.TakeItem(p, id, n) end end
local function said(p, from) local out = {} for i = (from or 0) + 1, #(p.chat or {}) do out[#out + 1] = tostring(p.chat[i]) end return out end
local M0 = Vector(-121000, 95000, 0)
local rz = LC.AddZone(M0, 900, "rebel", 0)
local rebel, helper = person("MoneyRebel", "resistance", 900), person("MoneyHelper", "resistance", 900)
local cit, cop = person("MoneyCitizen", "citizen"), person("MoneyCop", "cp")
_run(2)
for _, p in ipairs({ rebel, helper, cit }) do p:SetPos(M0 + Vector(0, 0, 0)) p.chat = {} end
cop:SetPos(M0 + Vector(20000, 0, 0)) cop.chat = {} -- (a unit near would put the rebel ground in the Combine's hands)

------------------------------------------------------------------------
-- the still
------------------------------------------------------------------------
do
    local R = LC.StillRecipe
    ok(R.batch == 8 and R.water == 2 and R.food == 1 and R.secs == 300, "a batch: a ration packet, 2 water and an empty bottle for each of 8 bottles, five minutes", R.batch .. " " .. R.water .. " " .. R.food .. " " .. R.secs)
    ok(LC.POINT_KINDS.still and LC.POINT_KINDS.cardtable, "both are placed with the editor and saved with the layout (point kinds still and cardtable)")
    local still = ents.Create("lc_still") still:SetPos(M0 + Vector(60, 0, 0)) still:Spawn()
    rebel:SetPos(M0 + Vector(20, 0, 0)) cit:SetPos(M0 + Vector(20, 20, 0))
    ok(LC.UseStill(cit, still) == false and #cit.chat == 0, "the still is the Resistance's: anyone else's E does nothing, and says nothing")
    drop(rebel, "bottle_empty")
    for _, id in ipairs(R.foods) do drop(rebel, id) end
    rebel.chat = {}
    ok(LC.UseStill(rebel, still) == false and #rebel.chat == 1 and string.find(rebel.chat[1], "You need a ration packet, 2 water and 8 empty bottles.", 1, true) ~= nil,
        "without the makings: one line, the whole recipe", table.concat(rebel.chat, " | "))
    LC.GiveItem(rebel, "ration", 1) LC.GiveItem(rebel, "bottle_dirty", 1) LC.GiveItem(rebel, "water_purified", 1) LC.GiveItem(rebel, "bottle_empty", 7)
    rebel.chat = {}
    ok(LC.UseStill(rebel, still) == false and #rebel.chat == 1, "(one empty bottle short: the same line)", table.concat(rebel.chat, " | "))
    LC.GiveItem(rebel, "bottle_empty", 1)
    local water0 = 0
    for _, id in ipairs(R.waters) do water0 = water0 + inv(rebel, id) end
    local e0, r0, m0 = inv(rebel, "bottle_empty"), inv(rebel, "ration"), inv(rebel, "moonshine")
    rebel.chat = {}
    ok(LC.UseStill(rebel, still) == true and #rebel.chat == 0, "with them: it starts brewing, without a word")
    local water1 = 0
    for _, id in ipairs(R.waters) do water1 = water1 + inv(rebel, id) end
    ok(inv(rebel, "bottle_empty") == e0 - 8 and inv(rebel, "ration") == r0 - 1 and water1 == water0 - 2, "it takes the recipe: 8 empty bottles, the ration and 2 water",
        inv(rebel, "bottle_empty") .. " " .. inv(rebel, "ration") .. " " .. water1)
    ok(still:GetNW2Float("lc_brew_done", 0) > CurTime(), "and brews, steaming (what the client draws while it works)")
    ok(LC.UseStill(rebel, still) == false and inv(rebel, "moonshine") == m0, "E again while it brews: nothing yet")
    -- nobody stands by it: the player goes off, and time passes
    rebel:SetPos(M0 + Vector(6000, 0, 0))
    _advance(R.secs + 1) _runtimers()
    ok(still:GetNW2Float("lc_brew_done", 0) <= CurTime() and inv(rebel, "moonshine") == m0, "it brews by itself with nobody near it (no step stands anyone anywhere)")
    rebel:SetPos(M0 + Vector(20, 0, 0))
    ok(LC.UseStill(helper, still) == true and inv(helper, "moonshine") >= 8, "E when it is done takes the bottles: eight moonshine (any of ours may take them)")
    LC.TakeItem(helper, "moonshine", 8) LC.GiveItem(rebel, "moonshine", 4)
    ok(still.lcBrew == nil and still:GetNW2Float("lc_brew_done", 0) == 0, "and it stands ready for the next batch")
    ok(LCS.Items.moonshine.contraband == true, "moonshine is contraband")
    local found = LC.SearchPockets(rebel, 1, true)
    local seized = false
    for _, f in ipairs(found) do if f.id == "moonshine" and f.n == inv(rebel, "moonshine") then seized = true end end
    ok(seized, "a unit's thorough search finds every bottle (and takes them)")
    still:Remove()
end

------------------------------------------------------------------------
-- the dealer's drink, and the sale split
------------------------------------------------------------------------
local dealer = ents.Create("lc_dealer") dealer:SetPos(M0 + Vector(0, 100, 0)) dealer:Spawn()
local sent
local realSend = LC.SendCompressed
local function window(p)
    sent = nil
    LC.SendCompressed = function(msg, tbl, rec) if msg == "lcu_market" and rec and rec[1] == p then sent = tbl end return realSend(msg, tbl, rec) end
    LC.OpenMarket(p)
    LC.SendCompressed = realSend
    return sent or { goods = {}, sell = {} }
end
local function listed(w, id) for _, g in ipairs(w.goods or {}) do if g.id == id then return g end end return nil end
local function sellRow(w, id) for _, s in ipairs(w.sell or {}) do if s.id == id then return s end end return nil end
do
    for _, p in ipairs({ rebel, helper, cit }) do p:SetPos(M0 + Vector(0, 60, 0)) end
    LC.AddCredits(cit, 500) LC.AddCredits(rebel, 100)
    book.bootleg = {}
    LC.LedgerSave()
    local w = window(cit)
    ok(#(w.goods or {}) > 0 and not listed(w, "moonshine") and not listed(w, "beer"), "the dealer sells no drink while nobody has sold him any: it is not on his list")
    ok(not listed(w, "vodka_black") and LCS.BlackById.vodka_black.gone, "his pre-war vodka is gone (there is none left in the city)")
    ok(LCS.GoodsById.vodka and not LCS.GoodsById.vodka.gone and LCS.GoodsById.vodka.civOnly, "the Union's own vodka for exemplary citizens at the Commissary is untouched")
    ok(LC.BlackBuy(cit, "moonshine") == false and LC.BlackBuy(cit, "vodka_black") == false and inv(cit, "moonshine") == 0, "and nobody can buy one off him")
    -- one of ours sells him moonshine: half to them, half to the fund
    setFund(100)
    drop(rebel, "moonshine") LC.GiveItem(rebel, "moonshine", 3)
    local price = LC.SellPrice(rebel, "moonshine")
    ok(LCS.Items.moonshine.resistanceSplit and LCS.Items.union_goods.resistanceSplit and LCS.Items.ration_forged.resistanceSplit,
        "the dealer's 50% split is read from the item's flag resistanceSplit: moonshine, skimmed Union machine parts, forged ration cards")
    w = window(rebel)
    ok(sellRow(w, "moonshine") and sellRow(w, "moonshine").price == math.floor(price * 0.5), "his window shows one of ours what they will have: half", tostring(sellRow(w, "moonshine") and sellRow(w, "moonshine").price) .. " of " .. price)
    local c0, n0 = LC.Credits(rebel), #rebel.chat
    ok(LC.DealerSell(rebel, "moonshine", true), "(one of ours sells him three bottles)")
    local yours = 3 * math.floor(price * 0.5)
    ok(LC.Credits(rebel) - c0 == yours and fund() == 100 + 3 * price - yours, "half of what he pays to the member, half to the fund", (LC.Credits(rebel) - c0) .. " " .. fund())
    local lines = said(rebel, n0)
    ok(#lines == 1 and string.find(lines[1], "for " .. yours .. " credits", 1, true) ~= nil, "the dealer's own line says what they had, and nothing else is said", table.concat(lines, " | "))
    ok(LC.BootlegLeft("moonshine") == 3, "each bottle sold him is one more in his stock", LC.BootlegLeft("moonshine"))
    w = window(cit)
    local g = listed(w, "moonshine")
    ok(g and g.ok and g.market and string.find(g.market, "3 left", 1, true) ~= nil and not listed(w, "beer"), "now he sells moonshine, and says how many are left", g and tostring(g.market))
    local cc = LC.Credits(cit)
    ok(LC.BlackBuy(cit, "moonshine") and inv(cit, "moonshine") == 1 and LC.BootlegLeft("moonshine") == 2, "each he sells takes one from it", LC.BootlegLeft("moonshine"))
    -- a restart keeps it
    local saved = util.JSONToTable(file.Read("livingcity/" .. game.GetMap() .. "_city.json", "DATA") or "") or {}
    ok(istable(saved.bootleg) and saved.bootleg.moonshine == 2, "his stock is written with the state of the city the moment it changes", tostring(saved.bootleg and saved.bootleg.moonshine))
    LC.LedgerReload()
    book = LC.Ledger()
    ok(LC.BootlegLeft("moonshine") == 2, "and is there after a restart or a map change", LC.BootlegLeft("moonshine"))
    -- a citizen sells him the same: paid in full, nothing to the fund
    LC.GiveItem(cit, "union_goods", 2)
    local f0, c1 = fund(), LC.Credits(cit)
    local gp = LC.SellPrice(cit, "union_goods")
    ok(LC.DealerSell(cit, "union_goods", true) and LC.Credits(cit) - c1 == 2 * gp and fund() == f0, "a citizen selling him skimmed machine parts is paid in full (their money is not the Resistance's)", (LC.Credits(cit) - c1) .. " " .. (fund() - f0))
    local cm = LC.Credits(cit)
    ok(LC.DealerSell(cit, "moonshine") and LC.Credits(cit) - cm == LC.SellPrice(cit, "moonshine") and LC.BootlegLeft("moonshine") == 3, "(and their bottle goes into his stock too)")
    LC.GiveItem(rebel, "union_goods", 2) LC.GiveItem(rebel, "ration_forged", 1)
    f0, c1 = fund(), LC.Credits(rebel)
    ok(LC.DealerSell(rebel, "union_goods", true) and LC.Credits(rebel) - c1 == 2 * math.floor(gp * 0.5) and fund() - f0 == 2 * gp - 2 * math.floor(gp * 0.5),
        "one of ours selling skimmed machine parts: half and half", (LC.Credits(rebel) - c1) .. " " .. (fund() - f0))
    local rp = LC.SellPrice(rebel, "ration_forged")
    f0, c1 = fund(), LC.Credits(rebel)
    ok(LC.DealerSell(rebel, "ration_forged") and LC.Credits(rebel) - c1 == math.floor(rp * 0.5) and fund() - f0 == rp - math.floor(rp * 0.5), "and a forged ration card")
    local qmWas = LC.AtQuartermaster
    LC.AtQuartermaster = function() return true end
    ok(LC.DealerSplit(rebel, "moonshine") == nil, "(never at the quartermaster: he is the Resistance's own)")
    LC.AtQuartermaster = qmWas
    ok(LC.DealerSplit(rebel, "bread") == nil and LC.DealerSplit(cit, "moonshine") == nil, "(nor for anything without the flag, nor for a citizen)")
end

------------------------------------------------------------------------
-- the dealer's rent
------------------------------------------------------------------------
do
    local at = dealer:GetPos()
    local rate, how = LC.DealerRentRate(at)
    ok(rate == 0.3 and how == "safe", "on rebel ground with no unit near and no lockdown: 30 per cent of every sale to the fund", tostring(rate) .. " " .. tostring(how))
    local f0, c0 = fund(), LC.Credits(cit)
    ok(LC.BlackBuy(cit, "water_purified"), "(a citizen buys water off him)")
    local paid = c0 - LC.Credits(cit)
    ok(paid > 0 and fund() - f0 == math.floor(paid * 0.3), "his rent: a share of what he took, in the fund", paid .. " paid, fund +" .. (fund() - f0))
    local u, ust = LC.Spawners.cop(at + Vector(800, 0, 0))
    ok(IsValid(u), "(a unit about)")
    rate, how = LC.DealerRentRate(at)
    ok(rate == 0.2 and how == "normal", "a unit within reach: 20 per cent", tostring(rate) .. " " .. tostring(how))
    u:SetPos(at + Vector(150, 0, 0))
    rate, how = LC.DealerRentRate(at)
    ok(rate == 0 and how == "held", "a unit right there: the Combine hold it, nothing", tostring(rate) .. " " .. tostring(how))
    u:Remove()
    local skWas = LC.Skirmish
    LC.Skirmish = { kind = "sweep", zone = rz, units = {}, rebels = {} }
    rate, how = LC.DealerRentRate(at)
    ok(rate == 0 and how == "held", "a sweep in that territory: nothing", tostring(rate) .. " " .. tostring(how))
    LC.Skirmish = skWas
    LC.Event = "lockdown"
    rate, how = LC.DealerRentRate(at)
    LC.Event = nil
    ok(rate == 0.2 and how == "normal", "a lockdown: 20 per cent", tostring(rate) .. " " .. tostring(how))
    rate, how = LC.DealerRentRate(M0 + Vector(20000, 0, 0))
    ok(rate == 0 and how == nil, "off rebel ground: no rent")
    local c1 = LC.Credits(rebel)
    f0 = fund()
    LC.BlackBuy(rebel, "water_purified")
    ok(fund() - f0 == math.floor((c1 - LC.Credits(rebel)) * 0.3) and share(rebel) == 0, "one of ours buying pays the same rent, and nobody is paid for it")
end

------------------------------------------------------------------------
-- the card table: a pot game, a fundraiser
------------------------------------------------------------------------
-- The owner, 19 November, on the first one (high card against the house, wins paid out of the fund): "I thought this
-- would be like a fundraiser card game where you play cards and you get like 70% of the winnings from the pot/pool and
-- the rest goes into the resistance fund; the resistance fund should not be drained from this".
do
    local tbl = ents.Create("lc_cardtable") tbl:SetPos(M0 + Vector(-100, 0, 0)) tbl:Spawn()
    local away = ents.Create("lc_cardtable") away:SetPos(M0 + Vector(30000, 0, 0)) away:Spawn()
    local at = tbl:GetPos()
    local function near(p, dx) p:SetPos(at + Vector(dx or 40, 0, 0)) end
    local function credits(p, n) LC.AddCredits(p, n - LC.Credits(p)) end
    local function fresh(p) p:RemovePData("lc_cards_hour") end
    local function window(p) for i = #net.sent, 1, -1 do local m = net.sent[i] if m.name == "lc_cards" and m.to == p then return m end end end
    local function seats() local T = LC.CardTableState(tbl) return T and T.seats or {} end
    local function seatOf(p) for i, s in ipairs(seats()) do if s.ply == p then return i, s end end end
    local cardsWas = LC.CardTableCards
    local function force(list) LC.CardTableCards = function(n) local o = {} for i = 1, n do o[i] = list[i] end return o end end
    local function unforce() LC.CardTableCards = cardsWas end
    for _, p in ipairs({ rebel, helper, cit }) do near(p) fresh(p) credits(p, 500) p.chat = {} end
    setFund(0)
    local takeWas, takes = LC.ResistanceFundTake, 0 -- (anything taken out of the fund from here on)
    LC.ResistanceFundTake = function(...) takes = takes + 1 return takeWas(...) end

    -- sitting, the city's people in the empty seats, standing up
    net.sent = {}
    ok(LC.OpenCardTable(cit, tbl) and seatOf(cit) == 1, "E on the card table sits you down and opens its window")
    local m = window(cit)
    ok(m and m.data[1] == tbl and m.data[2] == 1 and m.data[4] == true and m.data[9] == 4 and m.data[11] == true,
        "the window: seated, yours to pick the stake, four seats with yours among them", m and table.concat({ tostring(m.data[2]), tostring(m.data[4]), tostring(m.data[9]) }, " "))
    local names, distinct = 0, {}
    for i, s in ipairs(seats()) do
        if i > 1 and not s.ply and type(s.name) == "string" and s.name ~= "" and not distinct[s.name] then names = names + 1 distinct[s.name] = true end
    end
    ok(#seats() == 4 and names == 3, "a lone player has a game: the three empty seats are the Resistance's own people, by name", names)
    _netcall("lc_cards_deal", cit, tbl, 0, 0)
    m = window(cit)
    ok(LC.CardTableState(tbl) == nil and m and m.data[2] == 0, "closing the window stands you up; the last up, the table empties and the window closes")
    LC.OpenCardTable(cit, tbl)
    near(cit, 400)
    LC.CardTableCheck()
    ok(LC.CardTableState(tbl) == nil and window(cit).data[2] == 0, "walking off stands you up too")
    near(cit)

    -- only on rebel ground; never a unit
    cop:SetPos(at + Vector(-40, 0, 0))
    net.sent = {}
    cit:SetPos(away:GetPos() + Vector(40, 0, 0))
    ok(not LC.OpenCardTable(cit, away) and not LC.OpenCardTable(cop, tbl) and not window(cit) and not window(cop) and LC.CardTableState(tbl) == nil,
        "off rebel ground it does nothing; nor for a unit")
    near(cit)
    cop:SetPos(M0 + Vector(20000, 0, 0))

    -- the stake, picked by whoever sat first
    LC.OpenCardTable(rebel, tbl)
    LC.OpenCardTable(helper, tbl)
    ok(seatOf(rebel) == 1 and seatOf(helper) == 2 and #seats() == 4 and not seats()[3].ply and not seats()[4].ply,
        "a second player takes the seat of one of the city's people")
    ok(not LC.CardTableDeal(rebel, tbl), "no hand before the stake is picked")
    ok(not LC.CardTableStake(helper, tbl, 10) and window(helper).data[4] == false, "only whoever sat first picks the stake")
    ok(not LC.CardTableStake(rebel, tbl, 7) and LC.CardTableStake(rebel, tbl, 10) and LC.CardTableState(tbl).stake == 10, "one of the three: 5, 10 or 25")
    m = window(helper)
    ok(m and m.data[5] == 2, "and everyone at the table sees it", m and tostring(m.data[5]))

    -- a hand with two players: both stakes in, the winner 70 per cent, the fund the rest
    local r0, h0, f0 = LC.Credits(rebel), LC.Credits(helper), fund()
    local whys = {}
    local addWas = LC.ResistanceFundAdd
    LC.ResistanceFundAdd = function(n, why, ...) whys[#whys + 1] = why return addWas(n, why, ...) end
    force({ 14, 2, 3, 4 })
    local okD, hand = LC.CardTableDeal(rebel, tbl)
    unforce()
    LC.ResistanceFundAdd = addWas
    ok(okD and hand.pot == 30 and LC.Credits(rebel) - r0 == 21 - 10 and h0 - LC.Credits(helper) == 10 and fund() - f0 == 9,
        "both put 10 in, the city's two 5 each: a pot of 30, the ace takes 21 (70 per cent), the fund 9", okD and (hand.pot .. " " .. (LC.Credits(rebel) - r0) .. " " .. (fund() - f0)) or tostring(hand))
    ok(whys[1] == "The card table's cut", "on the fund's record as the card table's cut", tostring(whys[1]))
    m = window(helper)
    ok(m and m.data[7] == 30 and m.data[12] == 14 and m.data[13] == 21 and m.data[14] == true and m.data[17] == 2 and m.data[18] == 0,
        "the window: the pot, each seat's card, what the winner took and who dealt")
    ok(not LC.CardTableDeal(helper, tbl), "one hand every few seconds at most")
    _advance(4.1)
    r0, h0, f0 = LC.Credits(rebel), LC.Credits(helper), fund()
    force({ 13, 13, 3, 4 })
    okD, hand = LC.CardTableDeal(helper, tbl)
    unforce()
    ok(okD and LC.Credits(rebel) - r0 == 0 and LC.Credits(helper) - h0 == 0 and fund() - f0 == 10,
        "a tie splits the 21 (10 each) and what does not divide goes to the fund", (LC.Credits(rebel) - r0) .. " " .. (fund() - f0))
    _advance(4.1)
    r0, h0, f0 = LC.Credits(rebel), LC.Credits(helper), fund()
    force({ 2, 3, 14, 4 })
    okD, hand = LC.CardTableDeal(rebel, tbl)
    unforce()
    ok(okD and r0 - LC.Credits(rebel) == 10 and h0 - LC.Credits(helper) == 10 and fund() - f0 == 9 and seats()[3].won == 21,
        "one of the city's people wins like anyone (what they win goes home with them)")

    -- a player short of the stake is stood up; one short can't sit
    _advance(4.1)
    credits(helper, 3)
    net.sent = {}
    r0, f0 = LC.Credits(rebel), fund()
    force({ 2, 3, 4, 5 })
    okD, hand = LC.CardTableDeal(rebel, tbl)
    unforce()
    m = window(helper)
    ok(okD and not seatOf(helper) and LC.Credits(helper) == 3 and hand.pot == 25 and #seats() == 4,
        "a player short of the stake is stood up, and one of the city's people sits in for the hand")
    ok(m and m.data[2] == 2 and m.data[3] == 2, "their window says only that: short of the stake", m and (tostring(m.data[2]) .. " " .. tostring(m.data[3])))
    ok(LC.OpenCardTable(helper, tbl) and not seatOf(helper) and window(helper).data[3] == 2, "and E again does not sit them down while short")
    credits(helper, 500)

    -- a lone player at 25: the city's people put in 5 each, never more
    LC.CardTableStand(rebel, tbl)
    _advance(4.1)
    LC.OpenCardTable(cit, tbl)
    LC.CardTableStake(cit, tbl, 25)
    okD, hand = LC.CardTableDeal(cit, tbl)
    local theirs = 0
    for _, s in ipairs(okD and hand.hand or {}) do if not s.ply and s.put == 5 then theirs = theirs + 1 end end
    ok(okD and hand.pot == 40 and theirs == 3, "a lone player at 25 a hand puts 25 in against the city's three 5s", okD and hand.pot)

    -- the fund never goes down because of the table: 200 hands
    math.randomseed(1919)
    local down, total, cuts, wrong = false, 0, 0, 0
    f0 = fund()
    for i = 1, 200 do
        _advance(4.1)
        fresh(cit) credits(cit, 100)
        local was = fund()
        local okH, h = LC.CardTableDeal(cit, tbl)
        if not okH then wrong = wrong + 1 else
            if fund() < was then down = true end
            cuts = cuts + h.cut
            local put, won = 0, 0
            for _, s in ipairs(h.hand) do put, won = put + s.put, won + s.won if s.card < 2 or s.card > 14 then wrong = wrong + 1 end end
            if put ~= won + h.cut or h.pot ~= put then wrong = wrong + 1 end
            total = total + 1
        end
    end
    math.randomseed(os.time())
    ok(total == 200 and wrong == 0 and not down and fund() - f0 == cuts and cuts >= 200 * 12 and takes == 0,
        "over 200 hands the fund never goes down: it has its cut of every pot and pays nothing out", total .. " " .. wrong .. " " .. (fund() - f0) .. " " .. takes)

    -- the hourly cap: 20 hands a real hour, kept with the character over a reconnect
    LC.CardTableStand(cit, tbl)
    local regular = person("CardRegular", "citizen")
    regular:SetNW2String("lc_cid", "#41-207")
    near(regular) credits(regular, 500) regular.chat = {}
    LC.OpenCardTable(regular, tbl)
    LC.CardTableStake(regular, tbl, 5)
    local played = 0
    for i = 1, 20 do _advance(4.1) if LC.CardTableDeal(regular, tbl) then played = played + 1 end end
    _advance(4.1)
    net.sent = {}
    local c0 = LC.Credits(regular)
    ok(played == 20 and not LC.CardTableDeal(regular, tbl) and LC.Credits(regular) == c0 and LC.CardTableHandsLeft(regular) == 0,
        "20 hands in a real hour, then no more", played)
    m = window(regular)
    ok(m and m.data[3] == 1, "the window says only that: out of hands this hour")
    LC.OpenCardTable(rebel, tbl)
    _advance(4.1)
    force({ 2, 3, 4, 5 })
    okD, hand = LC.CardTableDeal(rebel, tbl)
    unforce()
    local _, rs = seatOf(regular)
    ok(okD and LC.Credits(regular) == c0 and rs and rs.card == 0 and hand.pot == 5 + 5 + 5, "while out of hands they sit out the others' hands, staking nothing")
    local saved = regular:GetPData("lc_cards_hour")
    hook.Run("PlayerDisconnected", regular)
    regular:Remove()
    LC.CardTableCheck()
    local back = person("CardRegularBack", "citizen")
    back:SetNW2String("lc_cid", "#41-207")
    back:SetPData("lc_cards_hour", saved)
    near(back) credits(back, 500)
    ok(not seatOf(regular) and LC.CardTableHandsLeft(back) == 0, "a reconnect keeps it (kept with the character)", tostring(saved))
    back:SetNW2String("lc_cid", "#77-310")
    ok(LC.CardTableHandsLeft(back) == 20, "(another character of theirs has their own hour)")
    back:SetNW2String("lc_cid", "#41-207")
    local first = tonumber(string.match(tostring(saved), "|(%d+)|%d+$")) or 0
    back:SetPData("lc_cards_hour", "#41-207|" .. (first - 3601) .. "|20")
    ok(LC.CardTableHandsLeft(back) == 20, "and once the hour has passed, they play again")

    -- over the wire: everything decided here
    LC.CardTableStand(back, tbl)
    _advance(4.1)
    fresh(rebel) credits(rebel, 500)
    LC.CardTableStake(rebel, tbl, 5)
    _netcall("lc_cards_deal", rebel, tbl, 2, 3)
    ok(LC.CardTableState(tbl).stake == 25, "the stake picked in the window")
    c0 = LC.Credits(rebel)
    _netcall("lc_cards_deal", rebel, tbl, 1, 0)
    ok(LC.Credits(rebel) ~= c0 and LC.CardTableHandsLeft(rebel) == 19, "Deal in the window deals a hand")
    c0 = LC.Credits(rebel)
    _netcall("lc_cards_deal", rebel, tbl, 1, 0)
    ok(LC.Credits(rebel) == c0, "asked again at once: refused")
    _advance(4.1)
    local hc = LC.Credits(helper)
    _netcall("lc_cards_deal", helper, tbl, 1, 0)
    ok(LC.Credits(helper) == hc and LC.CardTableHandsLeft(rebel) == 19, "from someone not seated: refused")
    near(rebel, 900)
    _netcall("lc_cards_deal", rebel, tbl, 1, 0)
    ok(LC.Credits(rebel) == c0 and not seatOf(rebel), "from across the room: refused, and stood up")
    near(rebel, 0)

    local said = {}
    for _, p in ipairs({ rebel, helper, cit, back }) do for _, s in ipairs(p.chat or {}) do said[#said + 1] = tostring(s) end end
    ok(#said == 0, "nothing of it in the chat: the seats, the cards and the result are in the window", table.concat(said, " | "))
    -- what it comes to (exact, over every four cards from a deck): the fund's cut a hand, and a lone player's loss
    local function odds(stake)
        local pot = stake + 3 * 5
        local win = math.floor(pot * 70 / 100)
        local mine, fundIn, n = 0, 0, 0
        for a = 0, 12 do for b = 0, 12 do for c = 0, 12 do for d = 0, 12 do
            -- (how many ways these four ranks come off a deck in this order)
            local w = 4 * (4 - (b == a and 1 or 0)) * (4 - (c == a and 1 or 0) - (c == b and 1 or 0)) * (4 - (d == a and 1 or 0) - (d == b and 1 or 0) - (d == c and 1 or 0))
            local best = math.max(a, b, c, d)
            local k = (a == best and 1 or 0) + (b == best and 1 or 0) + (c == best and 1 or 0) + (d == best and 1 or 0)
            local each = math.floor(win / k)
            if a == best then mine = mine + w * each end
            fundIn = fundIn + w * (pot - each * k)
            n = n + w
        end end end end
        return mine / n - stake, fundIn / n
    end
    local me5, f5 = odds(5)
    local me10, f10 = odds(10)
    local me25, f25 = odds(25)
    ok(math.abs(me5 + 1.50) < 0.01 and math.abs(me10 + 5.78) < 0.01 and math.abs(me25 + 18.00) < 0.01
        and math.abs(f5 - 6.01) < 0.01 and math.abs(f10 - 8.12) < 0.01 and math.abs(f25 - 12.00) < 0.01,
        "alone, a player loses about 1.50 a hand at 5, 5.78 at 10, 18.00 at 25; the fund has about 6.01, 8.12, 12.00",
        string.format("%.2f %.2f %.2f / %.2f %.2f %.2f", me5, me10, me25, f5, f10, f25))

    -- Twenty-one (the owner, 19 November: "can we have a few more simple card games"; their pick, the same pot)
    ;(function()
        if LC.CardTableState(tbl) then for _, s in ipairs(LC.CardTableState(tbl).seats) do if s.ply then LC.CardTableStand(s.ply, tbl) end end end
        _advance(4.1)
        for _, p in ipairs({ rebel, helper, cit }) do near(p) fresh(p) credits(p, 500) end
        setFund(0)
        LC.OpenCardTable(rebel, tbl)
        LC.OpenCardTable(helper, tbl)
        LC.CardTableStake(rebel, tbl, 10)
        ok(LC.CardTableTotal({ 14, 13 }) == 21 and LC.CardTableTotal({ 14, 14, 9 }) == 21 and LC.CardTableTotal({ 12, 11, 2 }) == 22 and LC.CardTableTotal({ 14, 5, 10 }) == 16,
            "Twenty-one: faces are 10, an ace 11 or 1")
        ok(not LC.CardTableGame(helper, tbl, 2) and not LC.CardTableGame(rebel, tbl, 3) and LC.CardTableGame(rebel, tbl, 2) and LC.CardTableState(tbl).game == 2,
            "whoever sat first picks the game: high card or Twenty-one")
        -- (the window: 9 the seats, five things for each of the four, then 30 the game, 31 a hand is on, 32 you may take a card)
        ok(window(helper).data[30] == 2, "and everyone's window is told", tostring(window(helper).data[30]))
        -- the deck in order: two each for the four seats (rebel 10 9, helper 8 5, the city's people 10 7 and 6 5),
        -- then what is drawn: the second of the city's people a 4 and a king (25), the helper a 9 (22)
        local r0, h0 = LC.Credits(rebel), LC.Credits(helper)
        force({ 10, 9, 8, 5, 10, 7, 6, 5, 4, 13, 9 })
        local okD, hand = LC.CardTableDeal(rebel, tbl)
        local T = LC.CardTableState(tbl)
        local _, rs = seatOf(rebel)
        local _, hs = seatOf(helper)
        ok(okD and T.round and #rs.cards == 2 and #hs.cards == 2 and LC.Credits(rebel) == r0 - 10 and LC.Credits(helper) == h0 - 10 and T.pot == 30,
            "Deal: the stakes go in (the city's people 5 each) and everyone has two cards", tostring(T.pot))
        local npc = {}
        for _, s in ipairs(T.seats) do if not s.ply then npc[#npc + 1] = s end end
        ok(npc[1].done and #npc[1].cards == 2 and npc[2].done and #npc[2].cards == 4 and LC.CardTableTotal(npc[2].cards) == 25,
            "the city's people take theirs at once: a card below 16 (on 17 they stay, on 15 they take one more)", #npc[2].cards .. " " .. LC.CardTableTotal(npc[2].cards))
        local w = window(helper)
        ok(w.data[31] == true and w.data[32] == true, "the window says a hand is on and that they may take a card")
        ok(not LC.CardTableDeal(helper, tbl) and not LC.CardTableStake(rebel, tbl, 5) and not LC.CardTableGame(rebel, tbl, 1),
            "no new hand, stake or game while one is on")
        ok(LC.OpenCardTable(cit, tbl) and not seatOf(cit) and window(cit).data[2] == 2, "nobody sits down in the middle of a hand")
        ok(LC.CardTableMove(rebel, tbl, false) and rs.done and not LC.CardTableMove(rebel, tbl, true) and T.round ~= nil, "Stay ends your part; the hand waits for the others")
        local fund0 = LC.ResistanceFund()
        ok(LC.CardTableMove(helper, tbl, true) and #hs.cards == 3 and T.round == nil, "Card gives you one; over 21 ends your part, and the last one done ends the hand")
        unforce()
        ok(rs.won == 21 and LC.Credits(rebel) == r0 - 10 + 21 and LC.Credits(helper) == h0 - 10 and LC.ResistanceFund() == fund0 + 9,
            "the nearest to 21 takes 70 per cent of the pot, the fund the rest", rs.won .. " " .. (LC.ResistanceFund() - fund0))
        ok(LC.CardTableHandsLeft(rebel) == 19, "a hand of Twenty-one is one of the hour's")
        -- over 21 is out, a tie splits; out of time, whoever is still thinking stays
        _advance(4.1)
        force({ 10, 13, 10, 12, 9, 8, 9, 8, 5, 5 })
        r0, h0, fund0 = LC.Credits(rebel), LC.Credits(helper), LC.ResistanceFund()
        LC.CardTableDeal(rebel, tbl)
        T = LC.CardTableState(tbl)
        ok(LC.CardTableMove(rebel, tbl, true) and select(2, seatOf(rebel)).done and LC.CardTableTotal(select(2, seatOf(rebel)).cards) == 25, "over 21 ends your part")
        _advance(21)
        LC.CardTableCheck()
        unforce()
        ok(T.round == nil and LC.Credits(rebel) == r0 - 10 and LC.Credits(helper) == h0 - 10 + 21 and LC.ResistanceFund() == fund0 + 9,
            "out of time the hand ends: whoever was over is out, the one who stayed on 20 wins", tostring(LC.Credits(helper) - h0))
        -- everyone over: the fund takes the pot
        _advance(4.1)
        LC.CardTableStand(helper, tbl)
        force({ 10, 6, 10, 5, 10, 4, 10, 3, 13, 12, 11, 10 })
        r0, fund0 = LC.Credits(rebel), LC.ResistanceFund()
        LC.CardTableDeal(rebel, tbl)
        LC.CardTableMove(rebel, tbl, true)
        unforce()
        T = LC.CardTableState(tbl)
        ok(T.round == nil and LC.Credits(rebel) == r0 - 10 and LC.ResistanceFund() == fund0 + T.pot and T.pot == 25, "with everyone over 21 the fund takes the pot", tostring(LC.ResistanceFund() - fund0))
        -- standing up in a hand leaves the stake; the last one up, the pot is the fund's
        _advance(4.1)
        force({ 5, 5, 10, 7, 10, 8, 10, 9 })
        r0, fund0 = LC.Credits(rebel), LC.ResistanceFund()
        LC.CardTableDeal(rebel, tbl)
        LC.CardTableStand(rebel, tbl)
        unforce()
        ok(LC.CardTableState(tbl) == nil and LC.Credits(rebel) == r0 - 10 and LC.ResistanceFund() == fund0 + 25, "standing up in a hand leaves your stake; the table empty, the pot is the fund's")
        -- over the wire
        _advance(4.1)
        LC.OpenCardTable(rebel, tbl)
        LC.CardTableStake(rebel, tbl, 5)
        _netcall("lc_cards_deal", rebel, tbl, 4, 2)
        ok(LC.CardTableState(tbl).game == 2, "the game picked in the window")
        force({ 10, 2, 10, 8, 10, 8, 10, 8, 3 })
        _netcall("lc_cards_deal", rebel, tbl, 1, 0)
        _netcall("lc_cards_deal", rebel, tbl, 3, 1)
        ok(LC.CardTableState(tbl).round and #select(2, seatOf(rebel)).cards == 3, "Card in the window")
        _netcall("lc_cards_deal", rebel, tbl, 3, 2)
        unforce()
        ok(LC.CardTableState(tbl).round == nil, "Stay in the window")
        _netcall("lc_cards_deal", rebel, tbl, 4, 1)
        ok(LC.CardTableState(tbl).game == 1 and select(2, seatOf(rebel)).cards == nil, "back to high card: the last hand's cards are cleared")
        -- suits: which of the four cards of a rank it is, for its picture; no two cards of a hand the same
        local ranks, suits = LC.CardTableCards(52)
        local seen, fine = {}, #ranks == 52 and #suits == 52
        for i = 1, 52 do
            local k = ranks[i] .. "/" .. suits[i]
            if seen[k] or suits[i] < 1 or suits[i] > 4 then fine = false end
            seen[k] = true
        end
        ok(fine, "a deck is thirteen ranks in four suits, each card once")
        _advance(4.1)
        LC.CardTableDeal(rebel, tbl)
        local _, mine = seatOf(rebel)
        local w = window(rebel)
        ok(mine.suit and mine.suit >= 1 and mine.suit <= 4 and w.data[34] == mine.suit, "a card's suit goes to the window with it", tostring(w.data[34]))
    end)()

    LC.ResistanceFundTake = takeWas
    if LC.CardTableState(tbl) then for _, s in ipairs(LC.CardTableState(tbl).seats) do if s.ply then LC.CardTableStand(s.ply, tbl) end end end
    tbl:Remove() away:Remove()
    for _, p in ipairs({ rebel, helper }) do p:SetPos(M0) end
    near(cit)
    cop:SetPos(at + Vector(-40, 0, 0)) -- (where this part has always left the unit)
    setFund(300)
end

------------------------------------------------------------------------
-- the paymaster
------------------------------------------------------------------------
do
    local dock = LC.AddPoint(M0 + Vector(-3000, 4000, 0), 0, "dock", 0)
    ok(LC.PaymasterEvery >= 280, "now and then, a little rarer than the supply convoy (about once in five hours of play)", LC.PaymasterEvery)
    local nightWas, autoWas = LC.IsNight, GetConVar("lc_auto_events"):GetInt()
    LC.IsNight = function() return false end
    set("lc_auto_events", 0)
    ok(not LC.PaymasterMayStart(), "not while the city's automatic events are off (as the supply convoy)")
    set("lc_auto_events", 1)
    LC.IsNight = function() return true end
    ok(not LC.PaymasterMayStart(), "never at night")
    LC.IsNight = function() return false end
    ok(LC.PaymasterMayStart(), "by day, he may set out")
    local mr = math.random
    math.random = function(lo, hi) if lo == nil then return 0 elseif hi == nil then return mr(lo) end return mr(lo, hi) end
    timer.list["LivingCityPaymasterClock"].fn()
    math.random = mr
    LC.IsNight = nightWas
    set("lc_auto_events", autoWas)
    local P = LC.Paymaster
    ok(P and IsValid(P.npc) and #P.escort == 2 and P.wages >= 80 and P.wages <= 200, "a Union paymaster sets out with the wages (80 to 200) and two units", P and (#P.escort .. " " .. P.wages))
    ok(P and LC.NPCs[P.npc] and LC.NPCs[P.npc].role == "citizen" and LC.NPCs[P.escort[1]].role == "cop", "a citizen in the Union's blue, and Civil Protection with him")
    ok(not LC.PaymasterMayStart(), "(one at a time)")
    local posted
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_paymaster" and not p.dead then posted = p end end
    ok(posted ~= nil and posted.title == "Rob the paymaster", "the Resistance's job while he walks is on their board")
    if posted then
        local credits, fundR = LC.PostingPay(rebel, posted)
        ok(fundR and fundR[1] == 40 and fundR[2] == 100 and credits[1] == jobPay and credits[2] == jobPay + 100,
            "its pay on the board: the job's own, up to half the satchel each, and the fund +40-100", credits[1] .. "-" .. credits[2] .. " fund " .. (fundR and (fundR[1] .. "-" .. fundR[2]) or "none"))
        ok(posted.tmpl.brings == true, "(a job that brings something in)")
    end
    local from = P.npc:GetPos()
    _run(3)
    ok(P.npc:GetPos():Distance(P.goal) < from:Distance(P.goal) - 100, "he walks to where the wages are paid", math.floor(from:Distance(P.goal) - P.npc:GetPos():Distance(P.goal)))
    -- one of ours takes the job; another has a go at his escort
    rebel.lcqNext = 0
    LC.AcceptPosting(rebel, posted.id)
    local q = LC.QuestOf[rebel]
    ok(q and q.tmpl.id == "res_paymaster", "(one of ours takes it)")
    local st = q and q.stages[q.stage]
    ok(st and st.npc == P.npc, "the job's marker follows him")
    rebel:SetPos(P.npc:GetPos() + Vector(40, 0, 0))
    helper:SetPos(P.npc:GetPos() + Vector(300, 0, 0))
    ok(not LC.RobPaymaster(rebel, P.npc) and LC.Paymaster == P, "with his escort beside him, E on him takes nothing")
    hook.Run("EntityTakeDamage", P.escort[1], _dmg(helper, 5))
    for _, g in ipairs(P.escort) do g:SetPos(P.npc:GetPos() + Vector(60, 0, 0)) g:SetHealth(0) hook.Run("OnNPCKilled", g, rebel, rebel) g:Remove() end
    setFund(100)
    local res0 = LC.Ledger().resistance or 50
    local c0, h0, take = LC.Credits(rebel), LC.Credits(helper), P.wages
    local seen, hostile = 0, 0
    local seenWas, hostileWas, crimeWas = LC.SeenBySecurity, LC.MakeCopsHostile, LC.ReportCrime
    LC.SeenBySecurity = function() return true end
    LC.MakeCopsHostile = function(...) hostile = hostile + 1 return hostileWas(...) end
    LC.ReportCrime = function(p, why, ...) if why == "Looting Union supplies" then seen = seen + 1 end return crimeWas(p, why, ...) end
    rebel.chat = {}
    hook.Run("PlayerUse", rebel, P.npc) -- (his escort gone: E on him)
    LC.SeenBySecurity, LC.MakeCopsHostile, LC.ReportCrime = seenWas, hostileWas, crimeWas
    local each = math.floor(math.floor(take * 0.5) / 2)
    ok(LC.Paymaster == nil and P.robbed, "his escort gone, E on him: he hands the satchel over")
    local other = {}
    for _, l in ipairs(rebel.chat) do if not string.find(l, "(your share)", 1, true) and not string.find(l, "[Credits]", 1, true) and not string.find(l, "complete", 1, true) and not string.find(l, "XP", 1, true) then other[#other + 1] = l end end
    ok(#other == 0, "nothing new is said: their share, and the job's own end", table.concat(other, " | "))
    ok(fund() - 100 == take - 2 * each and share(rebel) == each and share(helper) == each,
        "half to the fund, half shared among ours who took part (the one who took it and the one who went for his escort)", (fund() - 100) .. " " .. share(rebel) .. " " .. share(helper) .. " of " .. take)
    ok(LC.Credits(helper) - h0 == each, "(the helper had only their share)")
    ok(not LC.QuestOf[rebel] or LC.QuestOf[rebel].done, "the job is done")
    ok(LC.Credits(rebel) - c0 == each + jobPay, "and pays what its posting said: the job's own and the share", (LC.Credits(rebel) - c0) .. " " .. each)
    ok(seen == 1 and hostile >= 1, "seen at it: wanted, and the units after them, as at a looted supply drop")
    ok((LC.Ledger().resistance or 50) >= res0 and (LC.Ledger().resistance or 50) <= res0 + 1, "the Resistance's strength in the city goes up")
    -- a citizen: kills him, takes the satchel he drops, keeps it all
    for _, p in ipairs(made) do LC.ClearWanted(p) end
    ok(LC.StartPaymaster(), "(another day, another paymaster)")
    P = LC.Paymaster
    cit:SetPos(P.npc:GetPos() + Vector(40, 0, 0))
    local cc, f0 = LC.Credits(cit), fund()
    P.npc:SetHealth(0) hook.Run("OnNPCKilled", P.npc, cit, cit)
    ok(IsValid(P.satchel), "killed, he drops his satchel")
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_paymaster" and not p.q then ok(true, "(the job is still up while the satchel lies there)") break end end
    local sat = P.satchel
    cit.chat = {}
    hook.Run("PlayerUse", cit, sat)
    ok(#cit.chat == 0, "(and nothing is said: the credits are simply theirs)", table.concat(cit.chat, " | "))
    ok(LC.Credits(cit) - cc == P.wages and fund() == f0 and not IsValid(sat), "a citizen who takes it keeps the whole satchel; the fund gets nothing", (LC.Credits(cit) - cc) .. " " .. (fund() - f0))
    local left = 0
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_paymaster" and not p.dead then left = left + 1 end end
    ok(left == 0, "and the job comes off the board")
    -- he gets through: the job ends with him
    ok(LC.StartPaymaster(), "(and another)")
    P = LC.Paymaster
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_paymaster" and not p.dead and not p.q then posted = p end end
    helper.lcqNext = 0
    LC.AcceptPosting(helper, posted.id)
    local hq = LC.QuestOf[helper]
    P.npc:SetPos(P.goal)
    LC.PaymasterTick(CurTime())
    ok(LC.Paymaster == nil and hq and hq.done, "he gets where the wages are paid: it is over, and the job with him")
    ok(LC.ResistanceFundStepKinds.paymaster_robbed == "paymaster", "(the board reads the share from the fund's own tables)")
    local a, b, c, d = LC.ResistanceFundShares("paymaster", 1)
    ok(a == 40 and b == 100 and c == 40 and d == 100, "robbing him alone: 40 to 100 to the fund and as much to the one who did it", a .. " " .. b .. " " .. c .. " " .. d)
    a, b, c, d = LC.ResistanceFundShares("run", 1)
    ok(a == 15 and c == 15, "(the fund's other takes are as they were)")
    LC.RemovePoint(dock)
end

------------------------------------------------------------------------
-- back as it was
------------------------------------------------------------------------
if LC.EndPaymaster then LC.EndPaymaster("silent") end
dealer:Remove()
LC.RemoveZone(rz)
for _, p in ipairs(made) do
    if IsValid(p) then
        if LC.QuestOf[p] then LC.AbandonQuest(p) end
        LC.ClearWanted(p)
        hook.Run("PlayerDisconnected", p)
        p:Remove()
    end
end
book = LC.Ledger()
book.bootleg = stockWas
LC.LedgerSave()
setFund(fundWas)
set("lc_manpower", manWas)
set("lc_bad_deal_chance", dealWas)
set("lc_stops", stopsWas)
end
Nov19_ResistanceMoneyTests()

function Nov19_ArmoryBarterTests()
section("19 November: a gun you carry already goes in your pockets; the armory; the quartermaster paid through the fund; barter and goodwill")
-- The owner, 19 November: "if I already have an SMG or pistol then I can't pick up the SMG/Pistol on the ground: let's make it
-- so they are picked up and placed into the player's inventory and if sold to the quartermaster they go into the armory";
-- "they get like 5 credits from the resistance fund for each weapon"; "quartermaster purchases should go into the fund";
-- "a button ... that says 'Barter'"; "a Lieutenant should get like a 10 credit leeway and a Commander like a 20 credit
-- leeway ... the leeway/leniency needs to be it's own hidden value/fund that refills over time".
local fund = LC.ResistanceFund
local function setFund(n) LC.ResistanceFundTake(fund()) LC.ResistanceFundAdd(n) end
local fundWas = fund()
local book = LC.Ledger()
local armoryWas = table.Copy(istable(book.armory) and book.armory or {})
book.armory = {}
local nqWas, carryWas, sendWas = LC.NearQuartermaster, LC.CarryLimit, LC.SendCompressed
local bulkyWas, kgWas = GetConVar("lc_carry_bulky"):GetInt(), GetConVar("lc_carry_kg"):GetFloat()
LC.NearQuartermaster = function() return true end
local sentT = {}
LC.SendCompressed = function(msg, tbl, rec) sentT[msg] = tbl return sendWas(msg, tbl, rec) end
local T0 = Vector(-131000, 85000, 0)
local made = {}
local function mk(nm, faction, xp)
    local p = newPlayer(nm, faction, nil, xp)
    p.chat, p.lcProtectUntil = {}, 0
    p:SetPos(T0 + Vector(0, #made * 200, 0))
    made[#made + 1] = p
    local inv = LC.Inventory(p)
    for id in pairs(inv) do inv[id] = nil end
    return p
end
local function top(k) return LC.ResistanceFundLog(k or 1) end
local function name(p) return LC.CharacterName(p) end
local function gun(cls, p)
    local w = ents.Create(cls)
    w:SetPos(p:GetPos() + Vector(20, 0, 0))
    w:SetClip1(30)
    return w
end
local function pick(p, w) return hook.Run("PlayerCanPickupWeapon", p, w) end
local function trade(p, yours, his, credits)
    _run(1.1)
    return LC.BarterTrade(p, { yours = yours or {}, his = his or {}, credits = credits or 0 })
end
local function row(list, id) for _, r in ipairs(list or {}) do if r.id == id then return r end end end

------------------------------------------------------------------------
-- 1. a gun you carry already: into the pockets
------------------------------------------------------------------------
local fighter = mk("ArmFighter", "resistance", 400)
local citizen = mk("ArmCitizen", "citizen")
_run(1)
fighter.weps = { "weapon_crowbar", "weapon_pistol", "weapon_smg1" }
fighter.ammo = { SMG1 = 10 }
_setcvar("lc_carry_bulky", 1)
do
    local w = gun("weapon_smg1", fighter)
    local r = pick(fighter, w)
    ok(r == false and LC.HasItem(fighter, "gun_smg") and not w:IsValid(), "a fallen unit's SMG, when you carry one: into your pockets, gone from the ground")
    ok(fighter:GetAmmoCount("SMG1") == 40, "the rounds in it added to yours", fighter:GetAmmoCount("SMG1"))
    ok(LCS.Items.gun_smg.name == "SMG" and LCS.Items.gun_pistol.name == "Pistol" and LCS.Items.gun_ar2.name == "Pulse rifle" and LC.PocketGunItem("weapon_357") == "gun_357",
        "one pocket item for each gun, named plainly: Pistol, SMG, Shotgun, Revolver, Pulse rifle")
    local w2 = gun("weapon_357", fighter)
    ok(pick(fighter, w2) == nil and w2:IsValid() and not LC.HasItem(fighter, "gun_357"), "a class you don't carry: as before (the game hands it to you), nothing in the pockets")
    local w3 = gun("weapon_crowbar", fighter)
    ok(pick(fighter, w3) == nil and w3:IsValid(), "not a gun (a crowbar): as before")
    local w4 = gun("weapon_smg1", fighter)
    ok(pick(fighter, w4) == nil and w4:IsValid() and LC.Inventory(fighter).gun_smg == 1, "pockets full (a second large thing): it stays on the ground, as now")
    w4:Remove() w2:Remove() w3:Remove()
    local w5 = gun("weapon_pistol", fighter)
    w5.GetCreationTime = function() return CurTime() end
    ok(pick(fighter, w5) == nil and w5:IsValid() and not LC.HasItem(fighter, "gun_pistol"), "a gun the game is handing you that moment (a Give) is not pocketed")
    w5.GetCreationTime = nil
    w5:SetOwner(made[1])
    ok(pick(fighter, w5) == nil and not LC.HasItem(fighter, "gun_pistol"), "nor one in someone's hands")
    w5:SetOwner(nil)
    -- anything else that says no (a dream here) wins, whichever order the game asks in
    fighter.lcDreaming = true
    for _, rev in ipairs({ false, true }) do
        _HOOK_REVERSE = rev
        local r2 = pick(fighter, w5)
        ok(r2 == false and w5:IsValid() and not LC.HasItem(fighter, "gun_pistol"), "another answer says no (a dream): nothing pocketed, either order" .. (rev and " (reversed)" or ""))
    end
    _HOOK_REVERSE = nil
    fighter.lcDreaming = nil
    ok(pick(fighter, w5) == false and LC.HasItem(fighter, "gun_pistol") and not w5:IsValid(), "(and with nothing against it, the pistol goes in)")
    local f = LC.PatdownFinds(fighter)
    ok(f.gun_pistol == 1 and f.gun_smg == 1 and LCS.Items.gun_ar2.contraband == true, "a search finds a pocket gun, contraband as it is for a citizen")
    -- a unit leaves it; a citizen pockets one too; the pulse rifle
    local unit = mk("ArmUnit", "cp", 600)
    unit.weps = { "weapon_pistol" }
    local w6 = gun("weapon_pistol", unit)
    ok(pick(unit, w6) == nil and w6:IsValid() and not LC.HasItem(unit, "gun_pistol"), "a unit leaves it lying (as before)")
    w6:Remove()
    citizen.weps = { "weapon_ar2" }
    local w7 = gun("weapon_ar2", citizen)
    ok(pick(citizen, w7) == false and LC.HasItem(citizen, "gun_ar2"), "a citizen with a pulse rifle picks up another: into the pockets")
    citizen.weps = {}
end

------------------------------------------------------------------------
-- 2. selling to the quartermaster: the armory, 5 a gun out of the fund; everything he buys paid out of the fund
------------------------------------------------------------------------
_setcvar("lc_carry_bulky", 3)
setFund(100)
do
    local c0 = LC.Credits(fighter)
    LC.OpenMarket(fighter)
    local m = sentT.lcu_market
    local r = m and row(m.sell, "gun_smg")
    ok(m and m.quartermaster and m.barter == true and r and r.price == 5, "his window: a pocket gun at 5, and the Barter button", r and tostring(r.price) or "no row")
    _netcall("lcu_sell", fighter, "gun_smg", false)
    ok(not LC.HasItem(fighter, "gun_smg") and LC.Credits(fighter) == c0 + 5 and fund() == 95 and LC.ArmoryCount("weapon_smg1") == 1,
        "sold to him: 5 credits out of the fund, and the SMG in the armory", (LC.Credits(fighter) - c0) .. " " .. fund())
    ok(top()[1].n == -5 and top()[1].w == "An SMG for the armory (" .. name(fighter) .. ")", "the record says so", top()[1].w)
    fighter.weps[#fighter.weps + 1] = "weapon_357"
    _netcall("lcu_sell", fighter, "w:weapon_357", false)
    ok(not fighter:HasWeapon("weapon_357") and LC.ArmoryCount("weapon_357") == 1 and fund() == 90, "a gun in hand sold to him: the same, into the armory")
    _netcall("lcu_sell", fighter, "w:weapon_pistol", false)
    ok(fighter:HasWeapon("weapon_pistol") and LC.ArmoryCount("weapon_pistol") == 0 and fund() == 90, "(not one their side issued them)")
    -- a stranger, unnamed
    local cc = LC.Credits(citizen)
    _netcall("lcu_sell", citizen, "gun_ar2", false)
    ok(LC.Credits(citizen) == cc + 5 and LC.ArmoryCount("weapon_ar2") == 1 and top()[1].w == "A pulse rifle for the armory", "a stranger sells him one: the same, unnamed", top()[1].w)
    -- intel, skimmed parts, forged cards: out of the fund, at what he paid before; intel's experience as ever
    LC.GiveItem(fighter, "intel_patrol", 1)
    local ip = LC.QuartermasterBuyPrice(fighter, "intel_patrol")
    ok(ip == LC.SellPrice(fighter, "intel_patrol") and ip > 5, "intel: what he paid before", ip)
    local xp0 = tonumber(fighter:GetPData("lcf_xp_resistance", 0))
    c0 = LC.Credits(fighter)
    local fI = fund()
    _netcall("lcu_sell", fighter, "intel_patrol", false)
    ok(LC.Credits(fighter) == c0 + ip and fund() == fI - ip and tonumber(fighter:GetPData("lcf_xp_resistance", 0)) > xp0, "sold: out of the fund, and its experience", fI .. " -> " .. fund())
    ok(top()[1].n == -ip and top()[1].w == "Bought at the quartermaster's (" .. name(fighter) .. ")", "(the record)", top()[1].w)
    local forged = 0
    hook.Add("LivingCityForgedCard", "ArmTest", function(_, n) forged = forged + n end)
    LC.GiveItem(fighter, "ration_forged", 2)
    LC.GiveItem(fighter, "union_goods", 1)
    local f0 = fund()
    local fp, up = LC.QuartermasterBuyPrice(fighter, "ration_forged"), LC.QuartermasterBuyPrice(fighter, "union_goods")
    _netcall("lcu_sell", fighter, "ration_forged", true)
    _netcall("lcu_sell", fighter, "union_goods", false)
    hook.Remove("LivingCityForgedCard", "ArmTest")
    ok(forged == 2 and fund() == f0 - 2 * fp - up and not LC.HasItem(fighter, "ration_forged") and not LC.HasItem(fighter, "union_goods"),
        "forged cards (the forger's trail as before) and skimmed parts: out of the fund", fund() .. " " .. f0)
    -- the fund short: the sale doesn't fail, his barter opens with it on your side
    LC.GiveItem(fighter, "intel_checkpoint", 1)
    setFund(3)
    sentT.lc_barter = nil
    c0 = LC.Credits(fighter)
    _netcall("lcu_sell", fighter, "intel_checkpoint", false)
    local b = sentT.lc_barter
    ok(LC.HasItem(fighter, "intel_checkpoint") and LC.Credits(fighter) == c0 and fund() == 3 and b and b.pre and b.pre.intel_checkpoint == 1,
        "the fund can't pay: nothing sold, and the barter opens with it on your side", b and "barter sent" or "no barter")
    xp0 = tonumber(fighter:GetPData("lcf_xp_resistance", 0))
    ok(trade(fighter, { intel_checkpoint = 1 }) == true and LC.Credits(fighter) == c0 + 3 and fund() == 0 and tonumber(fighter:GetPData("lcf_xp_resistance", 0)) > xp0,
        "traded for nothing of his: the fund pays as far as it can, and intel still gives its experience", LC.Credits(fighter) - c0)
end

------------------------------------------------------------------------
-- 3. what a player pays him goes into the fund
------------------------------------------------------------------------
do
    setFund(50)
    LC.AddCredits(fighter, 500 - LC.Credits(fighter))
    local g = LCS.BlackById.ammo_pistol
    local p = LC.MarketPrice(fighter, g)
    ok(LC.BlackBuy(fighter, "ammo_pistol") and LC.Credits(fighter) == 500 - p and fund() == 50 + p, "bought from him: the credits go into the fund", fund())
    ok(top()[1].n == p and top()[1].w == "Sold at the quartermaster's (" .. name(fighter) .. ")", "(the record)", top()[1].w)
    LC.TakeItem(fighter, "ammo_pistol", 1)
end

------------------------------------------------------------------------
-- 4. the issue takes a fighter's guns from the armory first
------------------------------------------------------------------------
do
    -- (what a gun costs the fund, at the rate the server has: the rate and what rounds cost are the fund gear's own)
    local rate = math.max(0, GetConVar("lc_resistance_issue_rate"):GetFloat()) / 100
    local function cost(cls) return math.max(0, math.floor(LC.FundGunPrice(cls) * rate + 0.5)) end
    local f2 = mk("ArmIssue", "resistance", 400)
    _run(1)
    local function spawnCost(shelf)
        book.armory = shelf
        setFund(5000)
        f2.ammo = {}
        hook.Run("PlayerLoadout", f2)
        return 5000 - fund()
    end
    local full = spawnCost({}) -- (nothing on the shelf: the fund buys both guns and the rounds)
    local paid = spawnCost({ weapon_smg1 = 1 })
    ok(rate > 0 and f2:HasWeapon("weapon_smg1") and f2:HasWeapon("weapon_pistol") and LC.ArmoryCount("weapon_smg1") == 0 and paid == full - cost("weapon_smg1"),
        "a Fighter's spawn: the SMG off the armory's shelf at no cost, the pistol and the rounds bought", paid .. " vs " .. full .. " less " .. cost("weapon_smg1"))
    local l = top(2)
    ok(l[1].n == 0 and l[1].w == "An SMG from the armory, for a fighter (" .. name(f2) .. ")" and l[2].w == "A pistol and ammunition for a fighter (" .. name(f2) .. ")",
        "the record: what the fund paid for, and what came from the armory", l[1].w .. " | " .. l[2].w)
    local rounds = spawnCost({ weapon_smg1 = 1, weapon_pistol = 1 })
    ok(rounds == full - cost("weapon_smg1") - cost("weapon_pistol") and top()[1].w == "A fighter armed from the armory (" .. name(f2) .. ")",
        "both guns from the armory: the fund pays the rounds only", rounds .. " " .. top()[1].w)
    -- empty fund: what the armory has still arms them; a cheaper gun off the shelf counts as issued
    local cm = mk("ArmCommander", "resistance", 1800)
    _run(1)
    book.armory = { weapon_pistol = 1 }
    setFund(0)
    cm.ammo = {}
    hook.Run("PlayerLoadout", cm)
    ok(cm:HasWeapon("weapon_pistol") and not cm:HasWeapon("weapon_ar2") and LC.IsIssuedWeapon(cm, "weapon_pistol") and fund() == 0 and LC.ArmoryCount("weapon_pistol") == 0,
        "an empty fund: a pistol off the shelf for the Commander's pulse rifle, counted as issued (it can't be sold back)")
    book.armory = {}
end

------------------------------------------------------------------------
-- 5. barter: what each side holds, the totals and the checks, all on the server
------------------------------------------------------------------------
local lt = mk("ArmLieutenant", "resistance", 900)
_run(1)
lt.weps = {}
LC.AddCredits(lt, 200 - LC.Credits(lt))
LC.GiveItem(lt, "gun_pistol", 2)
setFund(500)
lt:RemovePData("lc_goodwill")
do
    ok(LC.BarterOpen(lt) == true, "the barter view opens for one of ours at his post")
    local b = sentT.lc_barter
    local r = b and row(b.yours, "gun_pistol")
    ok(r and r.n == 2 and r.price == 5 and #(b.his or {}) > 0, "yours: what he'd buy from your pockets, at what he pays; his: his stock, at what he charges")
    ok(b.goodwill == 10 and b.full == 10 and b.credits == 200 and b.fund == 500, "the bar's numbers reach the client (a Lieutenant: 10 of 10)", tostring(b.goodwill) .. "/" .. tostring(b.full))
    LC.BarterOpen(citizen)
    ok(#(sentT.lc_barter.his or {}) == 0, "a stranger: nothing of his (he sells nothing to strangers)")
end
-- his things worth a little more than one gun, a little less, and the cheapest
local his = sentT.lc_barter and LC.BarterOffer(lt).his or {}
local function combo(lo, hi) -- one of his things, and how many, worth more than lo and no more than hi
    for _, h in ipairs(his) do
        for k = 1, h.max do if h.price * k > lo and h.price * k <= hi then return h.id, k, h.price * k end end
    end
end
do
    local id, k, worth = combo(5, 12)
    ok(id ~= nil, "(something of his worth 6 to 12)", tostring(worth))
    local g0, c0, f0, a0 = LC.Goodwill(lt), LC.Credits(lt), fund(), LC.ArmoryCount("weapon_pistol")
    ok(trade(lt, {}, { [id] = k }, worth) == false, "a barter gives something of yours (credits alone are a purchase, not a barter)")
    ok(trade(lt, { gun_357 = 1 }, { [id] = k }) == false and trade(lt, { gun_pistol = 3 }, { [id] = k }) == false, "only what is really in your pockets, no more than you have")
    ok(trade(lt, { gun_pistol = 1 }, { nosuch = 1 }) == false and trade(lt, { gun_pistol = 1 }, { [id] = 99 }) == false, "only his stock, and a sensible number")
    ok(trade(lt, { gun_pistol = 1 }, { [id] = k }, 9999) == false, "credits you don't have: refused")
    ok(select(2, LC.BarterTrade(lt, { yours = { gun_pistol = 1 } })) == nil and LC.Credits(lt) == c0, "(and once a second at most: too soon, nothing moves)")
    local short = worth - 5
    ok(trade(lt, { gun_pistol = 1 }, { [id] = k }) == true, "one gun for his things worth a few credits more: he lets it go", short .. " short")
    ok(LC.Credits(lt) == c0 and fund() == f0 and LC.ArmoryCount("weapon_pistol") == a0 + 1 and LC.Inventory(lt).gun_pistol == 1,
        "no credits move; the gun is in the armory", LC.Credits(lt) - c0 .. " " .. fund() - f0)
    ok(math.abs(LC.Goodwill(lt) - (g0 - short)) < 0.01, "and the difference comes off the goodwill", LC.Goodwill(lt))
    local l = top(2)
    ok(l[1].n == 0 and l[1].w == string.format("Let %d credit%s go (%s)", short, short == 1 and "" or "s", name(lt)) and l[2].w == "A pistol for the armory (" .. name(lt) .. ")",
        "the record: the gun, and what he let go", l[1].w .. " | " .. l[2].w)
    LC.BarterOpen(lt)
    ok(math.abs(sentT.lc_barter.goodwill - (10 - short)) < 0.01 and sentT.lc_barter.full == 10, "closing and opening again gives nothing back", sentT.lc_barter.goodwill)
    -- more short than is left: refused (the Trade button is greyed for it)
    local left = math.floor(LC.Goodwill(lt) + 1e-9)
    local id2, k2, worth2 = combo(5 + left, 40)
    ok(id2 and trade(lt, { gun_pistol = 1 }, { [id2] = k2 }) == false and LC.Inventory(lt).gun_pistol == 1, "short by more than is left: refused, nothing moves", tostring(worth2))
    -- credits from your pocket make up the rest, into the fund
    local c1, f1 = LC.Credits(lt), fund()
    local need = worth2 - 5
    ok(trade(lt, { gun_pistol = 1 }, { [id2] = k2 }, need + 50) == true and LC.Credits(lt) == c1 - need and fund() == f1 + need, "credits from your pocket make up a difference (only what is needed), into the fund",
        (c1 - LC.Credits(lt)) .. " of " .. need)
    ok(top(2)[2].w == "Sold at the quartermaster's (" .. name(lt) .. ")" and top(2)[2].n == need, "(the record)", top(2)[2].w)
    -- room in the pockets (notes weigh nothing; his things do)
    LC.GiveItem(lt, "gun_pistol", 1)
    LC.GiveItem(lt, "intel_patrol", 1)
    LC.CarryLimit = function() return 0, 0 end
    local okH, whyH = trade(lt, { intel_patrol = 1 }, { [id] = k })
    LC.CarryLimit = carryWas
    ok(okH == false and whyH == "That's more than you can carry." and LC.HasItem(lt, "intel_patrol"), "his things won't fit in your pockets: refused, with the one line", tostring(whyH))
    LC.TakeItem(lt, "intel_patrol", 1)
    -- too far
    LC.NearQuartermaster = function() return nil end
    ok(trade(lt, { gun_pistol = 1 }, { [id] = k }) == false and LC.BarterOpen(lt) == false, "away from his post: nothing")
    LC.NearQuartermaster = function() return true end
    -- through the window's own message
    _run(1.1)
    sentT.lc_barter = nil
    _netcall("lc_barter", lt, 1)
    ok(sentT.lc_barter ~= nil, "the Barter button's message opens the view")
    _run(1.1)
    local g1 = LC.Goodwill(lt)
    _netcall("lc_barter", lt, 2, 0, 1, "gun_pistol", 1, 0)
    ok(not LC.HasItem(lt, "gun_pistol") and math.abs(LC.Goodwill(lt) - g1) < 0.01, "a trade from the view: one gun for nothing of his, paid out of the fund; the goodwill untouched")
end

------------------------------------------------------------------------
-- 6. goodwill: by rank, kept over a reconnect, refilling over 24 hours, never paid out
------------------------------------------------------------------------
do
    local sizes = {}
    for i, xp in ipairs({ 0, 150, 400, 900, 1800 }) do
        local p = mk("ArmRank" .. i, "resistance", xp)
        sizes[i] = LC.GoodwillFull(p)
    end
    ok(sizes[1] == 1 and sizes[2] == 3 and sizes[3] == 5 and sizes[4] == 10 and sizes[5] == 20, "the allowance by rank: Sympathizer 1, Member 3, Fighter 5, Lieutenant 10, Commander 20", table.concat(sizes, " "))
    local c = citizen
    local s = {}
    for i, sym in ipairs({ 0, 3, 7, 100 }) do c:SetPData("lcq_sympathy", sym) s[i] = LC.GoodwillFull(c) end
    ok(s[1] == 0 and s[2] == 1 and s[3] == 3 and s[4] == 3, "anyone else by sympathy, at most 3", table.concat(s, " "))
    c:SetPData("lcq_sympathy", 0)
    local now = os.time()
    lt:SetPData("lc_goodwill", string.format("%.4f:%d", 0, now - 12 * 3600))
    ok(math.abs(LC.Goodwill(lt) - 5) < 0.05, "empty, it fills again: half after 12 hours", LC.Goodwill(lt))
    lt:SetPData("lc_goodwill", string.format("%.4f:%d", 0, now - 30 * 3600))
    ok(LC.Goodwill(lt) == 10, "full after 24, and no more", LC.Goodwill(lt))
    lt:SetPData("lc_goodwill", string.format("%.4f:%d", 2, now))
    ok(LC.GoodwillSpend(lt, 3) == false and LC.GoodwillSpend(lt, 2) == true and math.floor(LC.Goodwill(lt) + 1e-9) == 0, "spent across trades: only what is left")
    -- a reconnect: what is kept with the character (PData) comes back as it was
    local saved = lt:GetPData("lc_goodwill")
    local back = mk("ArmLieutenant2", "resistance", 900)
    back:SetPData("lc_goodwill", saved)
    ok(math.floor(LC.Goodwill(back) + 1e-9) == 0 and string.match(tostring(saved), "^[%d%.]+:%d+$") ~= nil, "kept with the character over a reconnect or a restart", tostring(saved))
    hook.Run("LivingCityNewCharacter", back)
    ok(back:GetPData("lc_goodwill") == nil, "(someone new starts afresh)")
    -- never paid out: a trade that leans on it moves no credits; one that pays you doesn't touch it
    lt:RemovePData("lc_goodwill")
    LC.GiveItem(lt, "gun_pistol", 2)
    local id, k = combo(5, 9)
    local c0 = LC.Credits(lt)
    trade(lt, { gun_pistol = 1 }, { [id] = k })
    local g0 = LC.Goodwill(lt)
    ok(LC.Credits(lt) == c0 and g0 < 10, "it never pays out credits: only things of his, for a trade a little short")
    trade(lt, { gun_pistol = 1 })
    ok(LC.Credits(lt) == c0 + 5 and math.abs(LC.Goodwill(lt) - g0) < 0.01, "and a trade that pays you leaves it as it was")
end

------------------------------------------------------------------------
-- 7. no loop makes credits
------------------------------------------------------------------------
do
    local cm = mk("ArmLooper", "resistance", 1800)
    _run(1)
    cm.weps = {}
    setFund(100000)
    LC.AddCredits(cm, 2000 - LC.Credits(cm))
    local offer = LC.BarterOffer(cm)
    local bad
    for _, h in ipairs(offer.his) do
        local g = LCS.BlackById[h.id] or (LC.MarketBlackById and LC.MarketBlackById(h.id))
        local back = g and (g.item and (LC.QuartermasterBuyPrice(cm, g.item) or 0) * (g.count or 1)) or (g and g.weapon and LC.QuartermasterBuyPrice(cm, "w:" .. g.weapon)) or 0
        if back >= h.price then bad = h.id .. " " .. back .. " >= " .. h.price end
    end
    ok(bad == nil, "everything he sells, he buys back for less", tostring(bad))
    bad = nil
    for _, g in ipairs(LCS.Goods or {}) do
        local back = g.item and (LC.QuartermasterBuyPrice(cm, g.item) or 0) * (g.count or 1) or 0
        if back > 0 and back >= g.price then bad = g.id .. " " .. back .. " >= " .. g.price end
    end
    ok(bad == nil, "nor anything the Commissary sells", tostring(bad))
    local function wealth(p)
        local w = LC.Credits(p)
        for id, n in pairs(LC.Inventory(p)) do w = w + (LC.QuartermasterBuyPrice(p, id) or 0) * n end
        return w
    end
    local w0, rose = wealth(cm), nil
    for _, h in ipairs(offer.his) do -- buy each and sell it back
        local g = LCS.BlackById[h.id]
        if g and g.item and LC.BlackBuy(cm, h.id) then
            LC.QuartermasterBuy(cm, g.item, true)
            if wealth(cm) > w0 then rose = h.id end
            w0 = math.min(w0, wealth(cm))
        end
    end
    ok(rose == nil, "buying from him and selling it back, round and round: never more than you started with", tostring(rose))
    -- barter loops (a Commander with only guns in the pockets): guns for his things and back, until the goodwill is gone and after
    _setcvar("lc_carry_kg", 200)
    local bm = mk("ArmBarterLooper", "resistance", 1800)
    _run(1)
    bm.weps = {}
    LC.AddCredits(bm, 100 - LC.Credits(bm))
    LC.GiveItem(bm, "gun_pistol", 12)
    bm:RemovePData("lc_goodwill")
    local start = wealth(bm)
    his = LC.BarterOffer(bm).his -- (prices as they are now: buying moved some)
    local id, k = combo(5, 12)
    local g = LCS.BlackById[id]
    local used = 0
    for _ = 1, 12 do
        local g0 = LC.Goodwill(bm)
        if trade(bm, { gun_pistol = 1 }, { [id] = k }) then
            used = used + (g0 - LC.Goodwill(bm))
            if g and g.item then LC.QuartermasterBuy(bm, g.item, true) end
        end
    end
    ok(used > 0 and wealth(bm) - start <= used + 0.01 and used <= 20.01, "bartering in a loop: never more than the goodwill spent (20 at most, once a day) above where you started",
        string.format("%d gained, %.1f goodwill spent (%s x%d)", wealth(bm) - start, used, tostring(id), k or 0))
    local mid = wealth(bm)
    for _ = 1, 4 do trade(bm, { gun_pistol = 1 }, { [id] = k }) end
    ok(wealth(bm) <= mid, "and once it is spent, nothing more", (wealth(bm) - mid) .. "")
end

------------------------------------------------------------------------
-- 8. the gun run's crate, a gun given, and fencing
------------------------------------------------------------------------
do
    local runner = citizen
    LC.GiveItem(runner, "smuggled_supplies", 1)
    setFund(100)
    book.armory = {}
    local c0 = LC.Credits(runner)
    ok(LC.QuartermasterGunRun(runner, "smuggled_supplies") == true and LC.Credits(runner) == c0 + 60 and fund() == 40 and not LC.HasItem(runner, "smuggled_supplies"),
        "the gun run's crate: his sixty out of the fund, as the job always paid")
    ok(LC.ArmoryCount("weapon_pistol") == 1 and LC.ArmoryCount("weapon_smg1") == 1 and top()[1].w == "A crate of guns, brought in", "and its guns in the armory", top()[1].w)
    LC.GiveItem(runner, "smuggled_supplies", 1)
    setFund(10)
    sentT.lc_barter = nil
    ok(LC.QuartermasterGunRun(runner, "smuggled_supplies") == false and LC.HasItem(runner, "smuggled_supplies") and LC.Credits(runner) == c0 + 60
        and sentT.lc_barter and sentT.lc_barter.pre.smuggled_supplies == 1 and row(sentT.lc_barter.yours, "smuggled_supplies").price == 60,
        "the fund can't pay: the crate stays in their pockets, and his barter opens with it at 60")
    LC.TakeItem(runner, "smuggled_supplies", 1)
    LC.GiveItem(fighter, "gun_shotgun", 1)
    LC.QuartermasterDonate(fighter, "gun_shotgun")
    ok(LC.ArmoryCount("weapon_shotgun") == 1 and top()[1].n == 0 and top()[1].w == "A shotgun for the armory (" .. name(fighter) .. ")", "a gun given to him goes in the armory too", top()[1].w)
    local all = true
    for _, id in ipairs({ "gun_pistol", "gun_smg", "gun_shotgun", "gun_357", "gun_ar2" }) do
        local it = LCS.Items[id]
        if not (it.resistanceSplit and (it.sell or 0) > 0 and it.sell < (LC.FundGunPrice(it.weapon) or 0) and it.contraband) then all = false end
    end
    ok(all, "fencing: each pocket gun has the dealer's split flag and a dealer price below what it costs to buy")
    local saved = util.JSONToTable(file.Read("livingcity/" .. game.GetMap() .. "_city.json", "DATA") or "") or {}
    ok(istable(saved.armory) and tonumber(saved.armory.weapon_shotgun) == 1, "the armory is kept with the fund in the ledger's file")
end

-- nothing new in anyone's chat
do
    local bad
    for _, p in ipairs(made) do
        for _, line in ipairs(p.chat or {}) do
            local s = string.lower(tostring(line))
            for _, w in ipairs({ "barter", "goodwill", "armory", "fund" }) do
                if string.find(s, w, 1, true) then bad = line end
            end
        end
    end
    ok(bad == nil, "nothing about the armory, a barter or goodwill reached anyone's chat", tostring(bad))
end

-- back as it was
for _, p in ipairs(made) do
    if IsValid(p) then hook.Run("PlayerDisconnected", p) p:Remove() end
end
LC.NearQuartermaster, LC.CarryLimit, LC.SendCompressed = nqWas, carryWas, sendWas
_setcvar("lc_carry_bulky", bulkyWas)
_setcvar("lc_carry_kg", kgWas)
book.armory = armoryWas
setFund(fundWas)
end
Nov19_ArmoryBarterTests()

function Nov19_NoPackLoopTests()
section("Nothing bought in a pack and sold back one by one makes credits (the owner, 19 November)")
ok(LCS.Items.cig_rolled.sell == 1 and LCS.Items.cig_union.sell == 1, "a cigarette is bought back for 1, not 4 (five for 10 at the dealer)", LCS.Items.cig_rolled.sell)
local cit = newPlayer("PackLoopCitizen", "citizen")
_run(0.3)
local bad = {}
for _, list in ipairs({ LCS.Black or {}, LCS.Goods or {} }) do
    for _, g in ipairs(list) do
        if g.item and not g.lab and not g.cpOnly then
            local back = LC.SellPrice(cit, g.item)
            if back and back * (g.count or 1) >= g.price then bad[#bad + 1] = g.id .. " (" .. back .. " x " .. (g.count or 1) .. " for " .. g.price .. ")" end
        end
    end
end
ok(#bad == 0, "no pack the dealer or the Commissary sells is bought back for as much as it costs", table.concat(bad, ", "))
cit:Remove()
end
Nov19_NoPackLoopTests()

function Nov19_PosterTiltTests()
section("What is put up by hand hangs a little crooked (the owner, 19 November)")
local tilts, zero = {}, false
for i = 1, 200 do
    local t = LC.PosterTilt()
    tilts[#tilts + 1] = t
    if math.abs(t) < LC.PosterTiltRange[1] - 1e-6 or math.abs(t) > LC.PosterTiltRange[2] + 1e-6 then zero = true end
end
local left, right = 0, 0
for _, t in ipairs(tilts) do if t < 0 then left = left + 1 else right = right + 1 end end
ok(not zero and left > 40 and right > 40, "a tilt is between 1.5 and 5 degrees, left or right, never straight", left .. " left, " .. right .. " right")
local p = newPlayer("TiltHanger", "citizen")
_run(0.3)
p:SetPos(Vector(-150500, 151000, 0))
local e = LC.HangPoster and select(1, LC.HangPoster(p, "informants", Vector(-150500, 151100, 60), Vector(0, -1, 0)))
if IsValid(e) then
    local a, flat = e:GetAngles(), Vector(0, -1, 0):Angle()
    ok(math.abs(a.r - flat.r) >= 1.5 - 1e-6 and math.abs(a.r - flat.r) <= 5 + 1e-6 and math.abs(a.y - flat.y) < 1e-6 and math.abs(a.p - flat.p) < 1e-6,
        "a hung poster faces out of the wall as before, only turned a little about it", tostring(a))
    e:Remove()
else
    ok(false, "a poster is hung for the check", tostring(e))
end
p:Remove()
end
Nov19_PosterTiltTests()

section("Core contract: nothing load-bearing changes without the owner knowing (CORE.md)")
;(function() -- (its own function: the file's main chunk is at Lua's limit on locals)
    -- Everything here is something the owner's server, files or players depend on. The list is
    -- compared with _dev/core_snapshot.txt: a difference fails, and the runner writes the new list
    -- to _dev/core_snapshot.new.txt. Only with the owner's OK is that copied over the old one.
    local lines = {}
    local function Add(s) lines[#lines + 1] = s end
    for name, def in pairs(_cvarDefaults or {}) do
        if string.sub(name, 1, 2) == "lc" then Add("setting " .. name .. " = " .. def) end
    end
    for _, v in ipairs(LC.AnnounceVoices or {}) do Add("announce voice " .. v) end
    for _, t in ipairs(LC.AnnounceTriggers or {}) do Add("announce trigger " .. t) end
    for _, t in ipairs(LC.AnnounceRetired or {}) do Add("announce retired " .. t) end
    for v, ts in pairs(LC.AnnounceExtra or {}) do for _, t in ipairs(ts) do Add("announce " .. v .. " trigger " .. t) end end
    for _, r in ipairs(LC.AnnounceRoots or {}) do Add("announce folder sound/" .. r .. "<voice>/") end
    for _, id in ipairs(LC.EndingOrder or {}) do Add("ending " .. id .. " (" .. LC.Endings[id].name .. ")") end
    Add("ending songs folder sound/" .. tostring(LC.EndingRoot))
    Add("ending cooldown file data/" .. tostring(LC.EndingCooldownFile))
    Add("dream snapshots data/" .. tostring(LC.DreamDir) .. "<steamid64>.json")
    Add("ending tuning file data/" .. tostring(LC.EndingTuneFile))
    Add("rebel camp layout data/" .. tostring(LC.CampFile))
    local lp, map = LC.LayoutPath(), game.GetMap()
    local at = string.find(lp, map, 1, true)
    Add("layout file data/" .. (at and (string.sub(lp, 1, at - 1) .. "<map>" .. string.sub(lp, at + #map)) or lp))
    for _, f in ipairs(LCF.Factions or {}) do
        Add("faction " .. f.id .. " (" .. f.name .. ")")
        for i, r in ipairs(f.ranks or {}) do Add(string.format("faction %s rank %d %s at %s xp", f.id, i, r.name, tostring(r.xp))) end
        for _, s in ipairs(f.specials or {}) do Add("faction " .. f.id .. " special " .. s.id) end
    end
    for id in pairs(LCS and LCS.Items or {}) do Add("item " .. id) end
    for n in pairs(LC.SlashCommands or {}) do Add("chat command /" .. n) end
    for n in pairs(concommand.list or {}) do if string.sub(n, 1, 2) == "lc" then Add("console command " .. n) end end
    table.sort(lines)
    _CORE_NOW = table.concat(lines, "\n") .. "\n"
    if not _CORE_SNAPSHOT then
        ok(false, "the core snapshot (_dev/core_snapshot.txt) is missing: the runner wrote core_snapshot.new.txt")
        return
    end
    local have, had, diff = {}, {}, {}
    for l in string.gmatch(_CORE_NOW, "[^\n]+") do have[l] = true end
    for l in string.gmatch(_CORE_SNAPSHOT, "[^\n]+") do had[l] = true end
    for l in pairs(have) do if not had[l] then diff[#diff + 1] = "+ " .. l end end
    for l in pairs(had) do if not have[l] then diff[#diff + 1] = "- " .. l end end
    table.sort(diff)
    ok(#diff == 0, "the core is as the owner knows it: settings' defaults, announcement triggers and folders, endings, data files, "
        .. "factions and ranks, items and commands match _dev/core_snapshot.txt (a change needs the owner's OK first: CORE.md)",
        #diff .. " differences: " .. table.concat(diff, " | ", 1, math.min(#diff, 15)))
end)()

function DistrictInfestTests()
section("Infestation per district, and leaking next door (the owner, 18 November)")
_setcvar("lc_territory_spread", 1)
_setcvar("lc_zombies", 0)
local B0 = Vector(-36000, 36000, 0)
local mine = {}
local function Z(z) if z then mine[#mine + 1] = z end return z end
Z(LC.AddZone(B0, 200, "block", 91))
Z(LC.AddZone(B0 + Vector(2500, 0, 0), 200, "block", 92))
Z(LC.AddZone(B0 + Vector(0, 2600, 0), 200, "block", 93))
Z(LC.AddZone(B0 + Vector(9000, 9000, 0), 200, "block", 94))
LC.DistrictInfestForget()
ok(LC.DistrictInfest(91) == 0 and LC.DistrictInfestWord(LC.DistrictInfest(91)) == nil, "a district with no infestation scores 0 and says nothing", LC.DistrictInfest(91))
local seed = Z(LC.AddZone(B0 + Vector(-900, 0, 0), 300, "infest", 0))
LC.DistrictInfestForget()
ok(LC.DistrictInfest(91) == LC.DistrictInfestConst.POINTS_PLACED, "an infestation placed by a district counts for it", LC.DistrictInfest(91))
ok(LC.DistrictInfest(92) == 0, "and not for the district next door", LC.DistrictInfest(92))
local g1 = LC.GrowTerritory(seed, B0 + Vector(-900, 700, 0), 250)
local g2 = LC.GrowTerritory(seed, B0 + Vector(-900, -700, 0), 250)
local g3 = LC.GrowTerritory(seed, B0 + Vector(-1500, 0, 0), 250)
LC.DistrictInfestForget()
local v = LC.DistrictInfest(91)
ok(g1 and g2 and g3 and v == LC.DistrictInfestConst.POINTS_PLACED + 3 * LC.DistrictInfestConst.PATCH, "each patch it grows adds to it", v)
ok(LC.DistrictInfestWord(v) == "badly infested" and LC.DistrictInfestWord(30) == "infested" and LC.DistrictInfestWord(80) == "overrun", "words for it")
local found = false
for _, l in ipairs(LC.LedgerLines()) do if string.find(l, "Block 91", 1, true) and string.find(l, "badly infested", 1, true) then found = true end end
ok(found, "F2's state of the city says it after the district")
local nb = LC.DistrictNeighbours(91)
ok(#nb == 2 and table.HasValue(nb, 92) and table.HasValue(nb, 93), "next door is the two nearest blocks", table.concat(nb, ","))

section("A badly infested district leaks to the one next door")
local savedWander, savedContain = LC.RandomWanderPos, LC.ContainmentBlocks
LC.RandomWanderPos = function(role, near)
    if not near then return savedWander(role) end -- (everyone else wandering meanwhile)
    local a = math.random() * math.pi * 2
    return near + Vector(math.cos(a), math.sin(a), 0) * math.random(800, 1000)
end
LC.ContainmentBlocks = function() return true end
local z, m = LC.DistrictLeak(91)
ok(not z, "never past a checkpoint with power", m)
LC.ContainmentBlocks = function() return false end
local before = LC.GrownCount("infest")
z, m = LC.DistrictLeak(91)
if z then Z(z) end
LC.DistrictInfestForget()
ok(z and (m == 92 or m == 93) and LC.DistrictInfest(m) > 0, "the infestation turns up in a district next door", m)
ok(z and z.seed == seed and LC.GrownCount("infest") == before + 1, "as a patch of the infestation it came from (fought the same way)")
local s = LC.Ledger and LC.Ledger() or {}
local said = false
for _, l in ipairs(s.news or {}) do if string.find(l, "has spread from", 1, true) then said = true end end
ok(said, "the next City Bulletin says where it came from")
-- on its own, when it's due
LC.DistrictLeakAt[91] = CurTime() - 1
before = LC.GrownCount("infest")
_run(31)
ok(LC.GrownCount("infest") == before + 1, "left alone, it leaks on its own when due", LC.GrownCount("infest") - before)
ok((LC.DistrictLeakAt[91] or 0) > CurTime() + 60, "and not again straight away")
local lines = LC.DistrictInfestStatus()
ok(#lines > 0 and string.find(lines[1], "infestation", 1, true), "lc_territory and the admin panel list the scores", lines[1])
LC.RandomWanderPos, LC.ContainmentBlocks = savedWander, savedContain

section("Clearing it brings the score down")
for _, g in ipairs({ g1, g2, g3 }) do LC.RecedeTerritory(g, "test") end
LC.DistrictInfestForget()
ok(LC.DistrictInfest(91) == LC.DistrictInfestConst.POINTS_PLACED, "patches gone, the score drops", LC.DistrictInfest(91))
LC.QuietInfestation(seed.pos, 600)
LC.DistrictInfestForget()
ok(LC.DistrictInfest(91) == 0, "a cleared infestation counts nothing while it's quiet", LC.DistrictInfest(91))
LC.DistrictLeakAt[91] = CurTime() - 1
_run(31)
ok(LC.DistrictLeakAt[91] == nil, "and a district below the mark stops leaking")
LC.InfestQuiet = {}
for _, q in ipairs(LC.ZonesOfKind("infest")) do if q.seed == seed then LC.RecedeTerritory(q, "test") end end
for _, q in ipairs(mine) do if table.HasValue(LC.Zones, q) and not q.grown then LC.RemoveZone(q) end end
LC.DistrictInfestForget()
end
DistrictInfestTests()

function AdminSoloTests()
section("Testing alone: what one player can't set off, from the admin panel (the owner, 18 November)")
local solo = newPlayer("SoloTester", "citizen")
solo.admin, solo.superadmin = true, false
local okS, msg = LC.AdminTool(solo, solo, "solo", "black")
ok(not okS and string.find(tostring(msg), "Superadmins", 1, true), "superadmins only", msg)
solo.superadmin = true
local ranCmd
local rcc = RunConsoleCommand
RunConsoleCommand = function(c, ...) ranCmd = c end
okS, msg = LC.AdminTool(solo, solo, "solo", "bot")
RunConsoleCommand = rcc
ok(okS and ranCmd == "bot", "a stand-in player is a bot the server adds", msg)
local hadCall, hadPlaces = LC.CallSpeech, LC.SpeechPlaces
local called
LC.CallSpeech = function(by, text) called = { by = by } return true end
okS, msg = LC.AdminTool(solo, solo, "solo", "assassin")
ok(okS and called and called.by == nil, "the assassination test calls the city's own Administrator to her address", msg)
ok(solo:GetNW2String("lcf_faction", "") == "resistance" and solo:GetNW2Int("lcf_rank", 0) >= ((LC.AdminPlotMinRank and LC.AdminPlotMinRank()) or 3), "and makes them a Fighter, who may take the job", solo:GetNW2Int("lcf_rank", 0))
ok(string.find(tostring(msg), "Kill the Administrator", 1, true) ~= nil, "and says which job to take")
LC.CallSpeech = hadCall
local endEv = GetGlobal2String("lc_event", "")
if endEv ~= "" then LC.EndEvent(true) end
okS, msg = LC.AdminTool(solo, solo, "solo", "event:curfew")
ok(okS and GetGlobal2String("lc_event", "") == "curfew", "a city event starts from the panel", msg)
okS, msg = LC.AdminTool(solo, solo, "solo", "endevent")
ok(okS and GetGlobal2String("lc_event", "") == "", "and ends from it", msg)
okS, msg = LC.AdminTool(solo, solo, "solo", "nonsense")
ok(not okS, "an unknown test is refused")
LC.SetFaction(solo, "citizen")
end
AdminSoloTests()

function ShellingTests()
section("Headcrab shelling: canisters on a district the Resistance hold (the owner, 18 and 19 November)")
_setcvar("lc_territory_spread", 1)
_setcvar("lc_zombies", 0)
_setcvar("lc_ledger", 1)
local C = LC.ShellingConst
local function Shelled() local c = 0 for _, q in ipairs(LC.ZonesOfKind("infest")) do if q.grown and q.why == "shelled" then c = c + 1 end end return c end
local function Crabs() local c = 0 for _, st in pairs(LC.NPCs) do if st.role == "zombie" then c = c + 1 end end return c end
local B0 = Vector(-52000, -52000, 0)
local mine = {}
local function Z(z) if z then mine[#mine + 1] = z end return z end
Z(LC.AddZone(B0, 200, "block", 81))
Z(LC.AddZone(B0 + Vector(3600, 0, 0), 200, "block", 82))
local seed = Z(LC.AddZone(B0 + Vector(0, -2200, 0), 300, "infest", 0))
LC.DistrictInfestForget()
local savedWander, savedTrace, savedCreate, savedTrigger = LC.RandomWanderPos, util.TraceLine, ents.Create, LC.TriggerAnnouncements
local openAt, spread = B0 + Vector(2000, 0, 0), 900 -- (where the open ground nearest the tunnels is, when they're covered)
LC.RandomWanderPos = function(role, near)
    if not near then return openAt + Vector(math.random(-spread, spread), math.random(-spread, spread), 0) end
    local a = math.random() * math.pi * 2
    return near + Vector(math.cos(a), math.sin(a), 0) * math.random(700, 1100)
end
local covered = false -- (true: within 1500 of the block, a roof overhead: tunnels, sewers, rooms)
util.TraceLine = function(t)
    if t.endpos.z > t.start.z + 1000 then
        local dx, dy = t.start.x - B0.x, t.start.y - B0.y
        if covered and dx * dx + dy * dy < 1500 * 1500 then return { Hit = true, HitSky = false, HitPos = t.start, Fraction = 0 } end
        return { Hit = false, HitPos = t.endpos, Fraction = 1 }
    end
    return savedTrace(t)
end
local canisters = {}
ents.Create = function(cls) local e = savedCreate(cls) if cls == "env_headcrabcanister" then canisters[#canisters + 1] = e end return e end
local said = {}
LC.TriggerAnnouncements = function(trig, opts) said[#said + 1] = trig end
local function Settle() _run(C.SHELLS * C.GAP + C.FLIGHT + C.ADOPT + 2) end

LC.DistrictPush(81, -200)
ok(not table.HasValue(LC.ShellTargets(), 81), "a district in the Combine's hands is never a target")
LC.DistrictPush(81, 200)
ok(LC.DistrictOwner(81) == "resistance" and table.HasValue(LC.ShellTargets(), 81), "one in the Resistance's hands is")

-- staff, from the panel's call, on a district with open ground
local before, grownBefore = LC.DistrictInfest(81), Shelled()
LC.ShellNext = 0
local k, landed, under = LC.ShellDistrict(81, nil)
ok(k == C.SHELLS and landed == C.SHELLS and under == 0, "a shelling sends its canisters, on open ground in the district", tostring(k) .. " " .. tostring(landed) .. " " .. tostring(under))
ok(LC.ShellNext > CurTime() + 60, "and the next has to wait")
_run((C.SHELLS - 1) * C.GAP + 0.5) -- (all fired; the first lands at FLIGHT)
local fired, apart, in81 = 0, true, true
for i, c in ipairs(canisters) do
    if c.fired and table.HasValue(c.fired, "FireCanister") then fired = fired + 1 end
    if LC.LedgerBlockAt(c:GetPos()) ~= 81 then in81 = false end
    for j = i + 1, #canisters do if c:GetPos():Distance(canisters[j]:GetPos()) < 600 then apart = false end end
end
ok(#canisters == C.SHELLS and fired == C.SHELLS, "Half-Life 2's own headcrab canisters, fired", #canisters .. " " .. fired)
ok(in81 and apart, "all in that district, spread apart")
ok(tonumber(canisters[1].kv.HeadcrabCount) == C.CRABS and tonumber(canisters[1].kv.Damage) > 0 and tonumber(canisters[1].kv.spawnflags) == 8192, "each loaded with its headcrabs, landing where it is put")
ok(Shelled() == grownBefore, "nothing grows before they land")
local s = LC.Ledger()
local news = false
for _, l in ipairs(s.news or {}) do if string.find(l, "shelled", 1, true) and string.find(l, "with headcrabs", 1, true) then news = true end end
ok(news, "the next City Bulletin says which district was shelled")
ok(table.HasValue(said, "shelled"), "the PA's shelled line as they come in (where recorded)")
_run(C.FLIGHT)
local crab = ents.Create("npc_headcrab")
crab:SetPos(canisters[1]:GetPos() + Vector(30, 0, 0))
_run(1)
ok(LC.NPCs[crab] and LC.NPCs[crab].role == "zombie", "a canister's own headcrabs are the infestation's (counted and cleared like any)")
LC.DistrictInfestForget()
ok(Shelled() == grownBefore + C.SHELLS, "each canister down leaves a patch of the infestation", Shelled() - grownBefore)
local after = LC.DistrictInfest(81)
ok(after >= before + C.SHELLS * LC.DistrictInfestConst.PATCH - 1, "the district's infestation rises for everyone", before .. " -> " .. after)
local crabsBefore = Crabs()
local cut, cutPath
local savedClip, savedCut = LC.CubbageClip, LC.Freq7CutIn
LC.CubbageClip = function(id) return id == "shelled" and "livingcity/cubbage/answer_shelled1.wav" or nil end
LC.Freq7CutIn = function(path, text) cutPath, cut = path, text return true end
_run(C.ADOPT + 1)
ok(Crabs() >= crabsBefore + (C.SHELLS - 1) * C.CRABS, "a canister that let none out has them let out where it came down", Crabs() - crabsBefore)
_run(C.CUBBAGE_AFTER)
ok(cutPath and string.find(cutPath, "answer_shelled", 1, true) and cut == LC.SpeechAnswerLines.shelled, "a minute later Colonel Cubbage cuts in on Freq 7 (where recorded)", tostring(cutPath))
LC.CubbageClip, LC.Freq7CutIn = savedClip, savedCut

section("Headcrab shelling underground: the canister on the nearest open ground, the headcrabs in the tunnels")
covered = true
canisters = {}
LC.ShellNext = 0
grownBefore, crabsBefore = Shelled(), Crabs()
k, landed, under = LC.ShellDistrict(81, nil)
ok(k == C.SHELLS and under == C.SHELLS, "a district with no open sky: it all goes under cover", tostring(k) .. " " .. tostring(under))
ok(landed == C.SHELLS and #canisters == 0, "(the canisters are launched one after another)", tostring(landed))
_run((C.SHELLS - 1) * C.GAP + 0.5)
local outside, empty = true, true
for _, c in ipairs(canisters) do
    local dx, dy = c:GetPos().x - B0.x, c:GetPos().y - B0.y
    if dx * dx + dy * dy < 1500 * 1500 then outside = false end
    if tonumber(c.kv.HeadcrabCount) ~= 0 or tonumber(c.kv.Damage) ~= 0 or not table.HasValue(c.fired or {}, "OpenCanister") then empty = false end
end
ok(#canisters == C.SHELLS and outside, "each canister comes down on the open ground nearest the district", #canisters)
ok(empty, "empty and harmless, but it still opens (the pop, the hiss, the smoke)")
_run(C.FLIGHT)
LC.DistrictInfestForget()
local below = 0
for _, q in ipairs(LC.ZonesOfKind("infest")) do
    if q.grown and q.why == "shelled" then
        local dx, dy = q.pos.x - B0.x, q.pos.y - B0.y
        if dx * dx + dy * dy < 1500 * 1500 and LC.LedgerBlockAt(q.pos) == 81 then below = below + 1 end
    end
end
ok(Shelled() == grownBefore + C.SHELLS and below >= C.SHELLS, "the infestation takes root down in the district, under cover", Shelled() - grownBefore)
ok(Crabs() >= crabsBefore + C.SHELLS * C.CRABS, "and the headcrabs are down there as the canister lands", Crabs() - crabsBefore)
Settle()
-- the open ground above belongs to a block the Combine hold: no canister there, the headcrabs all the same
LC.DistrictPush(82, -200)
openAt, spread = B0 + Vector(2600, 0, 0), 250 -- (nearer block 82 than 81, and within reach)
canisters = {}
LC.ShellNext = 0
crabsBefore = Crabs()
k, landed, under = LC.ShellDistrict(81, nil)
_run((C.SHELLS - 1) * C.GAP + C.FLIGHT + 0.5)
ok(k == C.SHELLS and landed == 0 and #canisters == 0, "never a canister on a block the Combine hold above the tunnels", tostring(landed) .. " " .. #canisters)
ok(Crabs() >= crabsBefore + C.SHELLS * C.CRABS, "the headcrabs come all the same", Crabs() - crabsBefore)
Settle()
covered = false
openAt, spread = B0 + Vector(2000, 0, 0), 900

section("Headcrab shelling: her order, and the city's own only on the Resistance's ground in the open")
local adm = newPlayer("ShellAdministrator", "admin")
local cit = newPlayer("ShellCitizen", "citizen")
local okO, whyO = LC.OrderShelling(cit, 81)
ok(not okO and whyO, "only the City Administrator orders it", whyO)
LC.ShellNext = CurTime() + 600
okO, whyO = LC.OrderShelling(adm, 81)
ok(not okO and string.find(tostring(whyO), "ready", 1, true), "not before the canisters are ready", whyO)
LC.ShellNext = 0
okO, whyO = LC.OrderShelling(adm, 82)
ok(not okO and string.find(tostring(whyO), "Resistance", 1, true), "never a district the Resistance don't hold", whyO)
local m0, r0 = s.morale, s.resistance
okO, whyO = LC.OrderShelling(adm, 81)
ok(okO, "her order on a Resistance district goes ahead", whyO)
ok(s.morale == math.max(0, m0 + C.MORALE) and s.resistance == math.max(0, r0 + C.RESIST), "at a cost to morale and the Resistance", s.morale .. " " .. s.resistance)
ok(GetGlobal2Float("lc_shell_next", 0) > CurTime(), "her F2 knows when the next is ready")
Settle()
-- the city's own: nothing while the Resistance's ground stays indoors
local shelled
hook.Add("LivingCityShelled", "ShellTest", function(n) shelled = n end)
LC.ShellNext, LC.ShellCityNext = 0, 0
_run(61)
ok(shelled == nil, "the city's own never shell a district just because the Resistance hold it")
local rebelSeed = Z(LC.AddZone(B0 + Vector(0, 2600, 0), 300, "rebel", 0))
local patches = {}
for i = 1, C.OPEN_GROUND do
    local p = LC.GrowTerritory(rebelSeed, B0 + Vector(-1800 + i * 700, 3300, 0), 250)
    if p then patches[#patches + 1] = p end
end
ok(#patches == C.OPEN_GROUND, "(the Resistance's ground spreads into the open)", #patches)
LC.DistrictPush(81, -200)
_run(61)
ok(shelled == nil, "nor their ground in the open, in a district they don't hold")
LC.DistrictPush(81, 200)
_run(61)
ok(shelled == 81, "spread into the open in a district they hold: the city's own shell it", tostring(shelled))
ok((LC.ShellCityNext or 0) > CurTime() + 60 * 30, "and not again for a long while")
Settle()
local left = 0
for _, p in ipairs(patches) do if table.HasValue(LC.Zones, p) then left = left + 1 end end
ok(left <= #patches - math.min(C.SHELLS, #patches), "aimed at that ground: the headcrabs drive them off it", left)
local onIt = 0
for _, q in ipairs(LC.ZonesOfKind("infest")) do
    if q.grown and q.why == "shelled" then for _, p in ipairs(patches) do if q.pos:Distance(p.pos) < 50 then onIt = onIt + 1 end end end
end
ok(onIt >= math.min(C.SHELLS, #patches), "and the infestation takes it", onIt)
hook.Remove("LivingCityShelled", "ShellTest")
local lines = LC.ShellingStatus()
ok(#lines > 0 and string.find(table.concat(lines, " "), "rebel ground in the open", 1, true), "lc_territory says when the next can come and how much rebel ground is in the open", lines[1])

-- the admin panel's button (testing alone)
local solo = newPlayer("ShellSolo", "citizen")
solo.admin, solo.superadmin = true, true
LC.ShellNext = CurTime() + 999
local okS, msg = LC.AdminTool(solo, solo, "solo", "shell")
ok(okS and string.find(tostring(msg), "canister", 1, true), "F4 > Admin testing tools: shell a district now, without waiting", msg)
Settle()

-- clean up
LC.RandomWanderPos, util.TraceLine, ents.Create, LC.TriggerAnnouncements = savedWander, savedTrace, savedCreate, savedTrigger
LC.DistrictPush(81, -100)
LC.DistrictPush(82, 100)
for _, q in ipairs(LC.ZonesOfKind("infest")) do if q.seed == seed then LC.RecedeTerritory(q, "test") end end
for _, q in ipairs(LC.ZonesOfKind("rebel")) do if q.seed == rebelSeed then LC.RecedeTerritory(q, "test") end end
for npc, st in pairs(LC.NPCs) do if st.role == "zombie" and IsValid(npc) and npc:GetPos():Distance(B0) < 7000 then npc:Remove() LC.NPCs[npc] = nil end end
for _, q in ipairs(mine) do if table.HasValue(LC.Zones, q) and not q.grown then LC.RemoveZone(q) end end
LC.ShellNext, LC.ShellCityNext = 0, 0
LC.DistrictInfestForget()
_setcvar("lc_ledger", 0)
end
ShellingTests()

----------------------------------------------------------------------
function ScenePropsTests()
-- the owner's two props (19 November; sv_livingcity_sceneprops.lua): soupprep on a counter by the ration
-- plant's workplace, securitybank in each Resistance camp, by its notice board, back to a wall
section("Scene props: the ration plant's counter and the Resistance's monitors")
-- (the monitors in every camp are what the city does with the one-headquarters rule off, lc_base 0: with it on they are part
--  of the live base's office, BaseTests)
local baseOnWas = LC.BaseOn
LC.BaseOn = function() return false end
local SOUP, BANK = "models/props_lab/soupprep.mdl", "models/props_lab/securitybank.mdl"
local validWas, traceWas, createWas, runningWas = util.IsValidModel, util.TraceLine, ents.Create, LC.Running
local function Turn(a) return (a + 180) % 360 - 180 end
LC.Running = true

-- the models: looked up once; a server without one goes without
LC.SceneModelForget()
util.IsValidModel = function() return false end
ok(LC.SceneModel("soupprep") == nil and LC.SceneModel("securitybank") == nil, "a server without the models: neither is found")
util.IsValidModel = function(m) return m == SOUP end
ok(LC.SceneModel("soupprep") == nil, "and it isn't asked again (looked up once)")
LC.SceneModelForget()
ok(LC.SceneModel("soupprep") == SOUP and LC.SceneModel("securitybank") == nil, "one there: its path, the other still missing", tostring(LC.SceneModel("soupprep")))
util.IsValidModel = function() return false end
ok(LC.SceneModel("soupprep") == SOUP, "found once, kept")
LC.SceneModelForget()
util.IsValidModel = nil
ok(LC.SceneModel("securitybank") == nil, "(no IsValidModel: no file, no model)")
_files[BANK] = "mdl"
LC.SceneModelForget()
ok(LC.SceneModel("securitybank") == BANK, "(and with the file there, found)")
_files[BANK] = nil

util.IsValidModel = function(m) return m == SOUP or m == BANK end
LC.SceneModelForget()
LC.SceneBoundsForget()
ents.Create = function(cls)
    local e = createWas(cls)
    e.SetModel = function(self, m)
        self.model = m
        if m == SOUP then self.obbmin, self.obbmax = Vector(-12, -20, 0), Vector(12, 20, 14)
        elseif m == BANK then self.obbmin, self.obbmax = Vector(-16, -40, 0), Vector(16, 40, 90) end
    end
    return e
end

-- a ration plant: the floor, and a counter 40 deep and 160 long, 36 high, in front of the workplace
local K = Vector(-93000, 93000, 0)
local counter = { x1 = K.x + 60, x2 = K.x + 100, y1 = K.y - 80, y2 = K.y + 80, top = 36 }
local withCounter = true
util.TraceLine = function(t)
    local s, e = t.start, t.endpos
    if math.abs(s.x - e.x) < 0.01 and math.abs(s.y - e.y) < 0.01 and e.z < s.z and math.abs(s.x - K.x) < 2000 and math.abs(s.y - K.y) < 2000 then
        local on = withCounter and s.x >= counter.x1 and s.x <= counter.x2 and s.y >= counter.y1 and s.y <= counter.y2
        local z = on and counter.top or 0
        if s.z >= z and e.z <= z then
            return { Hit = true, HitPos = Vector(s.x, s.y, z), HitNormal = Vector(0, 0, 1), Fraction = (s.z - z) / (s.z - e.z) }
        end
        return { Hit = false, HitPos = e, HitNormal = Vector(0, 0, 1), Fraction = 1 }
    end
    return traceWas(t)
end
local num = LCJ.ById.kitchen.num
local function Soups()
    local n, one = 0, nil
    for _, e in pairs(LC.KitchenProps) do if IsValid(e) and e:GetPos():Distance(K) < 500 then n, one = n + 1, e end end
    return n, one
end
local pos, yaw = LC.CounterSpot(K)
ok(pos and math.abs(pos.z - 36.5) < 0.01 and pos.x > counter.x1 and pos.x < counter.x2 and pos.y > counter.y1 and pos.y < counter.y2,
    "a counter by the workplace: it goes on the counter top", tostring(pos))
ok(yaw and math.abs(Turn(yaw - 180)) < 0.01, "facing where the worker stands", yaw)
local wp = LC.AddPoint(K, 0, "work", num)
LC.EnsureKitchenProps()
local n, soup = Soups()
ok(n == 1 and soup:GetModel() == SOUP and soup.lcSceneProp == "soupprep" and soup.lcDressing and not soup.lcRebelProp,
    "the ration plant gets one, as set dressing (not loot, not a camp's thing)", n)
ok(LC.CampMovable and not LC.CampMovable(soup), "not carried off with a held E")
local wp2 = LC.AddPoint(K + Vector(-150, 0, 0), 0, "work", num)
LC.EnsureKitchenProps()
LC.EnsureKitchenProps()
ok(Soups() == 1 and IsValid(soup), "a second work point at the same plant: still the one")
LC.RemovePoint(wp)
LC.RemovePoint(wp2)
LC.EnsureKitchenProps()
ok(not IsValid(soup) and Soups() == 0, "the workplace taken out of the layout: it goes too")

-- no counter in reach, or no model: nothing
withCounter = false
ok(LC.CounterSpot(K) == nil, "no table or counter near the workplace: nowhere for it")
local wp3 = LC.AddPoint(K, 0, "work", num)
LC.EnsureKitchenProps()
ok(Soups() == 0, "and nothing is put there")
LC.RemovePoint(wp3)
LC.EnsureKitchenProps()
withCounter = true
util.IsValidModel = function(m) return m == BANK end
LC.SceneModelForget()
ok(LC.CounterSpot(K) == nil, "a server without the model: nothing, counter or not")
util.TraceLine = traceWas

-- the Resistance's monitors, in a camp of its own with a wall along one side
util.IsValidModel = function(m) return m == SOUP or m == BANK end
LC.SceneModelForget()
local B = Vector(-93000, 97000, 0)
local zone = LC.AddZone(B, 300, "rebel", 0)
local wall = { a = Vector(B.x - 400, B.y + 150, 0), b = Vector(B.x + 400, B.y + 150, 0) }
_walls[#_walls + 1] = wall
local o, face, walled = LC.SecurityBankSpot(zone)
ok(o and walled and math.abs(o.y - (B.y + 132)) < 1 and LCZ.Contains(zone, o, 0), "a wall near: it stands with its back to it, in the camp", tostring(o))
ok(face and math.abs(Turn(face + 90)) < 1, "facing out from the wall, into the camp", face)
LC.EnsureRebelProps()
local r = LC.RebelProps[zone]
local bank = r and r.bank
ok(IsValid(bank) and bank:GetModel() == BANK and bank.lcRebelProp == "bank" and bank.lcSceneProp == "securitybank" and bank.lcCampZone == zone,
    "every camp gets them: one of the camp's own things", tostring(bank))
ok(LC.CampMovable and LC.CampMovable(bank), "carried with a held E like the rest of the camp")
bank:SetPos(o + Vector(-120, -40, 0))
LC.CampSnapshot(zone)
local saved
for _, it in ipairs(LC.CampSaved(zone) or {}) do if it.prop == "bank" then saved = it end end
ok(saved and math.abs(saved.x - (o.x - 120)) < 1, "where it was set down is kept with the camp")
bank:Remove()
r.bankNext = 0
LC.EnsureRebelProps()
ok(IsValid(r.bank) and r.bank:GetPos():Distance(o + Vector(-120, -40, 0)) < 1, "and it's put back just there")
local list = LC.CampSaved(zone)
for i = #list, 1, -1 do list[i] = nil end
for i, w in ipairs(_walls) do if w == wall then table.remove(_walls, i) break end end
local o2, face2, walled2 = LC.SecurityBankSpot(zone)
ok(o2 and walled2 == false and LCZ.Contains(zone, o2, 0) and math.abs(Turn(face2 - math.deg(math.atan2(B.y - o2.y, B.x - o2.x)))) < 1,
    "no wall near: on the open floor, facing the middle of the camp", tostring(o2))
util.IsValidModel = function(m) return m == SOUP end
LC.SceneModelForget()
ok(LC.SecurityBankSpot(zone) == nil and LC.SecurityBankFor(zone) == nil, "a server without the model: no monitors")
local kept = r.bank
LC.RemoveZone(zone)
LC.EnsureRebelProps()
ok(not IsValid(kept) and LC.RebelProps[zone] == nil, "the camp gone: its monitors go with it")

-- clean up (no monitors or counters left in the other tests' camps and plants)
for _, rp in pairs(LC.RebelProps) do if IsValid(rp.bank) then rp.bank:Remove() end rp.bank = nil end
for k, e in pairs(LC.KitchenProps) do if IsValid(e) then e:Remove() end LC.KitchenProps[k] = nil end
util.IsValidModel, util.TraceLine, ents.Create, LC.Running = validWas, traceWas, createWas, runningWas
LC.SceneModelForget()
LC.SceneBoundsForget()
LC.BaseOn = baseOnWas
end
ScenePropsTests()

function Nov19_InformTests()
section("19 November: informing to Civil Protection, the assassin who got away")
LC.EndEvent(true)
local savedWalls = _walls
_walls = {}
local O = Vector(-352000, 151000, 0)
local function sent(name, needle)
    local m = _lastnet(name)
    for _, v in ipairs(m and m.data or {}) do if string.find(tostring(v), needle, 1, true) then return true end end
    return false
end
local cit = newPlayer("InfCitizen", "citizen")
local reb = newPlayer("InfAssassin", "resistance", nil, 900)
local mate = newPlayer("InfRebel", "resistance", nil, 900)
_run(0.5)
cit:SetPos(O) reb:SetPos(O + Vector(1500, 0, 0)) mate:SetPos(O + Vector(1400, 60, 0))
cit.aim, mate.aim = Vector(1, 0, 0), Vector(1, 0, 0)
LC.InformSightTick()
ok(not cit:GetNW2Bool("lc_inform_can", false) and #LC.InformOptions(cit) == 0, "nobody has tried anything: nothing to report")

-- the attempt: the assassin is marked, and gets away
reb:SetPData("lc_regicide", tostring(os.time()))
reb:SetNW2Bool("lc_regicide", true)
reb.lcRegicideReadAt = nil
ok(LC.AssassinFree(reb), "the would-be assassin, alive and free, is the one to report")
cit.aim = Vector(-1, 0, 0)
LC.InformSightTick()
ok(#LC.InformOptions(cit) == 0, "free but never seen: nothing to report (nothing on screen gives them away)")
cit.aim = Vector(1, 0, 0)
LC.InformSightTick()
ok(cit:GetNW2Bool("lc_inform_can", false) and LC.InformSeenAssassin(cit) == reb, "seen with their own eyes since the attempt: they can report it")
ok(not LC.MayInform(mate) and #LC.InformOptions(mate) == 0, "a member of the Resistance who saw them reports nothing")
local early = newPlayer("InfEarly", "citizen")
early.lcSawAssassin = { [reb:SteamID64()] = os.time() - 100 }
ok(LC.InformSeenAssassin(early) == nil, "seen before the attempt: it doesn't count (the owner: after the attempt)")
local old = newPlayer("InfOld", "citizen")
reb.lcRegicideAt, reb.lcRegicideReadAt = os.time() - 2000, CurTime()
old.lcSawAssassin = { [reb:SteamID64()] = os.time() - 901 }
ok(LC.InformSeenAssassin(old) == nil, "seen more than 15 minutes ago: too long ago")
old.lcSawAssassin = { [reb:SteamID64()] = os.time() - 880 }
ok(LC.InformSeenAssassin(old) == reb, "seen 14 and a half minutes ago: still counts")
reb.lcRegicideReadAt = nil

-- a unit: E on him opens the list, with the reward
local cop, cst = LC.SpawnCop(cit:GetPos() + Vector(70, 0, 4))
ok(IsValid(cop) and LC.InformUnit(cop), "(one of the city's units)")
ok(LC.InformOpen(cit, cop) and sent("lc_inform", "I know where the assassin is (250 credits, 250 standing)"),
    "E on a unit: Inform lists 'I know where the assassin is', with its reward")
ok(not LC.InformOpen(mate, cop), "(the list never opens for the Resistance)")
local credits0, standing0 = LC.Credits(cit), LC.Standing(cit)
local okDo, whyDo = LC.InformDo(cit, cop, "assassin")
local q = LC.QuestOf[cit]
ok(okDo and q and q.title == "Lead Civil Protection to the traitor", "chosen: the job 'Lead Civil Protection to the traitor'", tostring(okDo) .. " " .. tostring(whyDo) .. " " .. tostring(q))
ok(q and q.expires - CurTime() > 290 and q.expires - CurTime() <= 300.5, "with five minutes on the clock", q and (q.expires - CurTime()))
ok(cst.questLock and LC.InformLeads[cit] and LC.InformLeads[cit].escorts[1] == cop, "the unit comes along")
ok(#LC.InformOptions(cit) == 0, "(nothing more to report while leading)")
-- two soldiers join, ones nearby first
local s1 = LC.SpawnSoldier(cit:GetPos() + Vector(300, 0, 4))
local s2 = LC.SpawnSoldier(cit:GetPos() + Vector(-300, 0, 4))
if LC.InformLeads[cit] then LC.InformLeads[cit].soldiersAt = CurTime() - 1 end
LC.InformLeadTick(CurTime())
local L = LC.InformLeads[cit]
ok(L and #L.escorts == 3 and LC.NPCs[s1].questLock and LC.NPCs[s2].questLock, "two Overwatch soldiers nearby join the unit")
-- walking distance, not a straight line
local br = LC.BuildRoute
LC.BuildRoute = function(a, b) return { a + Vector(0, 900, 0), b + Vector(0, 900, 0), b } end
ok(LC.InformWalkDist(O, O + Vector(300, 0, 0)) > 800, "near in a straight line but a long walk round: not near (50 feet, walking)")
LC.BuildRoute = function() return false end
ok(LC.InformWalkDist(O, O + Vector(300, 0, 0)) == math.huge, "and no way through at all: not near")
LC.BuildRoute = br
LC.InformLeadTick(CurTime())
ok(LC.QuestOf[cit] == q and not q.done, "the units still far from the assassin: not done")
cop:SetPos(reb:GetPos() + Vector(-200, 0, 0))
LC.InformLeadTick(CurTime())
ok(q.done and LC.QuestOf[cit] == nil and LC.InformLeads[cit] == nil, "a unit within 50 feet of the assassin: done")
ok(LC.Credits(cit) - credits0 == 250 and LC.Standing(cit) - standing0 == 250, "paid 250 credits and 250 Civil Standing",
    (LC.Credits(cit) - credits0) .. " / " .. (LC.Standing(cit) - standing0))
ok(not cst.questLock and LC.ResponseSquads[cop] and LC.ResponseSquads[cop].target == reb, "and the units go for the assassin")

-- out of time: 10 standing, and ten minutes before reporting it again
cit.lcqNext = 0
cit.lcSawAssassin = { [reb:SteamID64()] = os.time() }
local cop2 = LC.SpawnCop(cit:GetPos() + Vector(70, 0, 4))
ok(LC.InformDo(cit, cop2, "assassin"), "(another report)")
local standing1 = LC.Standing(cit)
LC.FinishQuest(LC.QuestOf[cit], false, "out of time")
ok(LC.Standing(cit) - standing1 == -10 and not LC.NPCs[cop2].questLock, "out of time: 10 standing, and the unit goes back", LC.Standing(cit) - standing1)
ok(#LC.InformOptions(cit) == 0 and cit.lcInformWaits.assassin > CurTime() + 590, "and no new report of it for ten minutes")

-- the assassin taken by someone else mid-lead: it ends with nothing against anyone
cit.lcInformWaits, cit.lcqNext = nil, 0
ok(LC.InformDo(cit, cop2, "assassin"), "(a third report)")
local standing2 = LC.Standing(cit)
local held = LC.HeldByCombine
LC.HeldByCombine = function(p) return p == reb end
cit.chat = {}
LC.InformLeadTick(CurTime())
LC.HeldByCombine = held
ok(LC.InformLeads[cit] == nil and LC.QuestOf[cit] == nil and LC.Standing(cit) == standing2, "the assassin caught by others: it ends, no standing lost")

-- the poster
local poster = { EntIndex = function() return 2 end, IsValid = function() return true end }
setmetatable(poster, { __index = function() return function() end end })
ok(LC.InformPosterKind(Entity and IsValid(cop) and cop or poster) == nil or true, "(posters)")
reb:SetNW2Bool("lc_regicide", false)
ok(LC.InformPosterKind(cop) == nil, "nobody free: the plain curfew notices stay as they are")

for _, e in ipairs({ cop, cop2, s1, s2 }) do if IsValid(e) then e:Remove() end end
reb:RemovePData("lc_regicide")
_walls = savedWalls
end
Nov19_InformTests()


function Nov19_FiringSquadTests()
section("19 November: firing squads, ordered by the Administrator; the Resistance all told, and a real death")
LC.EndEvent(true)
local savedWalls = _walls
_walls = {}
local R0 = Vector(-366000, 171000, 0)
local function has(list, needle)
    for _, v in ipairs(list or {}) do if string.find(tostring(v), needle, 1, true) then return true end end
    return false
end
local said = {}
local ann = LC.Announce
LC.Announce = function(kind, path, detail) said[#said + 1] = tostring(kind) .. ": " .. tostring(detail) return ann(kind, path, detail) end
local cells = { LC.AddPoint(R0, 0, "cell", 0), LC.AddPoint(R0 + Vector(0, 400, 0), 0, "cell", 0), LC.AddPoint(R0 + Vector(0, 800, 0), 0, "cell", 0),
    LC.AddPoint(R0 + Vector(900, 0, 0), 0, "release", 0) }
local function jail(p, reason)
    for _, c in ipairs(cells) do if c.kind == "cell" and not LC.Occupied[c] then p.lcPreferCell = c break end end
    LC.Incarcerate(p, 900, reason)
    return LC.Prisoners[p] ~= nil
end
local adm = newPlayer("FSAdministrator", "admin")
local cop = newPlayer("FSCop", "cp")
local friend = newPlayer("FSFriend", "resistance", nil, 900)
local con = newPlayer("FSCondemned", "resistance", nil, 900)
local petty = newPlayer("FSPetty", "citizen")
_run(0.5)
adm:SetPos(R0 + Vector(3000, 0, 0)) friend:SetPos(R0 + Vector(-6000, 0, 0))
ok(jail(con, "Carrying a weapon") and jail(petty, "Loitering"), "(two in the cells)")
local okNo, whyNo = LC.FiringSquadOrder(adm, con)
ok(not okNo and string.find(tostring(whyNo), "execution wall", 1, true), "no execution wall on the map: no firing squad", tostring(whyNo))
local wall = LC.AddPoint(R0 + Vector(2000, 0, 0), 90, "execwall", 0)
local cands = LC.FiringSquadCandidates()
local listed, pettyListed = false, false
for _, c in ipairs(cands) do if c.ent == con then listed = c.why == "the Resistance" end if c.ent == petty then pettyListed = true end end
ok(listed and not pettyListed, "who may be shot: a member of the Resistance in the cells, not a citizen in for loitering")
ok(not LC.FiringSquadOrder(cop, con), "only the Administrator orders one")
ok(not LC.FiringSquadOrder(adm, petty), "and never for loitering")
friend.chat = {}
local done = {}
hook.Add("LivingCityFiringSquadDone", "FSTest", function(t, how) done[#done + 1] = how end)
ok(LC.FiringSquadOrder(adm, con) and LC.FiringSquad ~= nil, "the Administrator orders it")
ok(has(said, "execution: FSCondemned, enemy of the city, will be executed at the wall in two minutes"), "the PA says who, and when", said[#said])
ok(has(friend.chat, "New job: Stop the execution"), "every member of the Resistance online is given the job to stop it")
local posting
for _, x in ipairs(LC.Postings[LC.QuestFaction(friend)] or {}) do if x.tmpl and x.tmpl.id == "res_stopexec" and not x.dead then posting = x end end
ok(posting and (posting.squad or 0) >= 16, "one job all of them can work on together")
ok(not LC.FiringSquadOrder(adm, petty), "(one at a time)")
friend.lcqNext = 0
ok(posting and LC.AcceptPosting(friend, posting.id), "(a friend takes it)")
_run(6)
local F = LC.FiringSquad
ok(F and #F.squad == 4, "a squad of four Overwatch soldiers comes", F and #F.squad)
_run(26)
ok(F.atWall and con:GetPos():DistToSqr(wall.pos) < 50 * 50 and LC.IsTied(con), "half a minute on, the condemned is at the wall, cuffed")
_run(3)
ok(LC.Prisoners[con] ~= nil and not LC.ReportedEscape, "and it isn't counted as an escape from the cells")
LC.Untie(con, friend)
_run(1.5)
ok(LC.FiringSquad == nil and done[#done] == "rescued", "uncuffed before the volley: a rescue")
ok(LC.Prisoners[con] == nil and con:Alive(), "they're out of custody, alive (an escape: wanted for it)")
ok(LC.QuestOf[friend] == nil, "the job is done for whoever took it")

-- the volley: a real death
LC.Untie(con, nil, false)
ok(jail(con, "Carrying a weapon"), "(back in the cells)")
local endOfLife
hook.Add("PlayerDeath", "FSTest", function(v) if v == con then endOfLife = v.lcEndOfLife end end)
ok(LC.FiringSquadOrder(adm, con), "(ordered again)")
_run(125)
ok(done[#done] == "shot" and not con:Alive() and endOfLife == "executed", "nobody came: at two minutes the squad fires, and it is the character's end",
    tostring(done[#done]) .. " " .. tostring(endOfLife))
hook.Remove("PlayerDeath", "FSTest")

-- the whole squad brought down: a rescue
local con2 = newPlayer("FSCondemned2", "resistance", nil, 900)
_run(0.5)
ok(jail(con2, "Carrying a weapon"), "(someone else in the cells)")
ok(LC.FiringSquadOrder(adm, con2), "(ordered)")
_run(32)
for _, s in ipairs(LC.FiringSquad and LC.FiringSquad.squad or {}) do if IsValid(s.npc) then s.npc:Remove() end end
_run(1.5)
ok(done[#done] == "rescued" and LC.FiringSquad == nil, "the squad all down before the volley: a rescue too")

hook.Remove("LivingCityFiringSquadDone", "FSTest")
LC.Announce = ann
LC.RemovePoint(wall)
for _, c in ipairs(cells) do LC.RemovePoint(c) end
_walls = savedWalls
end
Nov19_FiringSquadTests()


function Nov19_RebelAnswerTests()
section("19 November: the Resistance's prisoners: letting go three ways, exchanges, bodies, the people's view, her answer")
LC.EndEvent(true)
LC.Exchange, LC.RebelAnswerPending = nil, nil -- (an earlier test's execution may have left one of either open)
local savedWalls = _walls
_walls = {}
local R0 = Vector(-382000, 191000, 0)
local said = {}
local ann = LC.Announce
LC.Announce = function(kind, path, detail) said[#said + 1] = tostring(kind) .. ": " .. tostring(detail) return ann(kind, path, detail) end
local function has(list, needle)
    for _, v in ipairs(list or {}) do if string.find(tostring(v), needle, 1, true) then return true end end
    return false
end
local Ld = LC.Ledger()
Ld.rebstanding = 0
local psy, mindOf, rnd = LC.Psy, LC.MindOf, math.random
local loyalNow = 0
LC.Psy = { Traits = function() return { loyal = loyalNow } end }
LC.MindOf = function() return {} end

-- how the people see them: felt, never shown as a figure
ok(LC.RebelStanding() == 0 and string.find(LC.RebelSentiment(), "Nobody is sure about us", 1, true), "at first: nobody is sure about them")
local cit = LC.SpawnCitizen and LC.SpawnCitizen(R0 + Vector(0, 0, 4)) or ents.Create("npc_citizen")
local cst = LC.NPCs[cit]
if not cst then cst = { role = "citizen" } LC.NPCs[cit] = cst end
cit.lcProfile = cit.lcProfile or { name = "Ada Test", id = "ra_ada" }
cit:SetPos(R0 + Vector(0, 0, 4))
hook.Run("LivingCityExecuted", nil, cit, true, true)
ok(LC.RebelStanding() == -8 and LC.RebelRuthless(), "a prisoner who had done nothing shot: the people think much less of them, and informers go quiet")
ok(LC.RebelStandingSnitchMul() < 1, "(for a while fewer citizens dare inform)", LC.RebelStandingSnitchMul())
Ld.rebstanding = 0
cst.snitch = true
hook.Run("LivingCityExecuted", nil, cit, true, true)
ok(LC.RebelStanding() == -1, "a confessed informer shot: most people shrug", LC.RebelStanding())
cst.snitch = nil
hook.Run("LivingCityExecJudged", nil, "expel")
ok(LC.RebelStanding() == 3, "the killer put out of the Resistance: some trust back")
Ld.rebstanding = -50
LC.RebelRuthlessUntil = nil
ok(string.find(LC.RebelSentiment(), "afraid of us", 1, true), "low: the leader's clipboard says people are afraid of them")
ok(LC.RebelStandingSnitchMul() > 1 and LC.RebelStandingSympathyMul() < 1, "and more turn informer, fewer sympathize")
math.random = function(a, b) if a then return 1 end return 0 end
cst.rebel = nil
loyalNow = 0.8
ok(string.find(tostring(LC.RebelGossip(cit, cst)), "Murderers", 1, true), "a loyal citizen calls it murder")
loyalNow = -0.8
ok(string.find(tostring(LC.RebelGossip(cit, cst)), "had it coming", 1, true), "a bitter one calls it justice")
Ld.rebstanding = 0
ok(LC.RebelGossip(cit, cst) == nil, "nothing to say while nobody is sure")
math.random = rnd

-- letting them go: a warning, blindfolded, turned
local cage = ents.Create("prop_physics")
cage:SetPos(R0 + Vector(400, 0, 0))
local function hold(npc)
    if npc == cit and not IsValid(cit) then -- (let go and left alone for a while, they may have gone indoors for good: one like them)
        cit = LC.SpawnCitizen and LC.SpawnCitizen(R0 + Vector(0, 0, 4)) or ents.Create("npc_citizen")
        cit:SetPos(R0 + Vector(0, 0, 4))
        cit.lcProfile = cit.lcProfile or { name = "Ada Test", id = "ra_ada" }
        npc = cit
    end
    local st = LC.NPCs[npc] or cst -- (the city may have tidied its own record of them away meanwhile)
    LC.NPCs[npc] = st
    LC.RebelHeld[npc] = { cage = cage, st = st, at = CurTime(), slot = 1 }
    st.questLock = true
end
LC.RebelIntel, LC.RebelLies = nil, 0
loyalNow = 0.8
hold(cit)
ok(LC.RebelReleaseHow(nil, cage, cit, "warn") ~= nil and LC.RebelHeld[cit] == nil, "let go with a warning: out of the cage")
_run(41)
ok(LC.RebelIntel and LC.RebelIntel.why == "a released prisoner talked", "a loyal one goes straight to a unit and tells them where the cage is")
LC.RebelIntel = nil
hold(cit)
local s0 = LC.RebelStanding()
LC.RebelReleaseHow(nil, cage, cit, "blind")
_run(41)
ok(LC.RebelIntel == nil and LC.RebelStanding() == s0 + 2, "blindfolded and walked out: nobody learns the way back")
loyalNow = -0.8
hold(cit)
math.random = function(a, b) if a then return 1 end return 0 end
LC.RebelReleaseHow(nil, cage, cit, "turn")
math.random = rnd
ok(LC.RebelLies == 1 and cit.lcTurned, "turned: they will feed the units lies")
LC.RebelIntelAdd(R0, "a body found")
ok(LC.RebelIntel == nil and LC.RebelLies == 0, "and the next thing the units think they've learned is one of those lies")

-- exchanges
local cells = { LC.AddPoint(R0 + Vector(3000, 0, 0), 0, "cell", 0), LC.AddPoint(R0 + Vector(3000, 400, 0), 0, "cell", 0), LC.AddPoint(R0 + Vector(3900, 0, 0), 0, "release", 0) }
local adm = newPlayer("RAAdministrator", "admin")
local lt = newPlayer("RALieutenant", "resistance", nil, 99999)
local jailed = newPlayer("RAJailed", "resistance", nil, 900)
_run(0.5)
jailed.lcPreferCell = cells[1]
LC.Incarcerate(jailed, 900, "Carrying a weapon")
hold(cit)
ok(LC.ExchangeRebel() ~= nil, "(one of ours in the Combine's cells)")
LC.Exchange = nil
local okX = LC.ExchangeOffer("resistance", lt, cit, jailed)
ok(okX and string.find(GetGlobal2String("lc_xchg", ""), "RAJailed", 1, true), "a Lieutenant offers a prisoner for one of ours: it waits on her F2")
local s1 = LC.RebelStanding()
LC.ExchangeAnswer(true, adm)
ok(LC.Prisoners[jailed] == nil and LC.RebelHeld[cit] == nil and LC.RebelStanding() == s1 + 2, "she accepts: both walk free, and the people think better of the Resistance")
ok(GetGlobal2String("lc_xchg", "") == "", "(the offer is gone)")
jailed.lcPreferCell = cells[1]
LC.Incarcerate(jailed, 900, "Carrying a weapon")
hold(cit)
LC.Exchange = nil
ok(LC.ExchangeOffer("combine", nil, cit, jailed), "she offers one the other way")
local s2 = LC.RebelStanding()
LC.ExchangeAnswer(false, lt)
ok(LC.RebelStanding() == s2 - 3 and LC.Prisoners[jailed] ~= nil, "refused: it costs the Resistance with the people")

-- the body, and her answer
LC.RebelAnswerPending = nil
local body = ents.Create("prop_ragdoll")
body:SetPos(R0 + Vector(-2000, 0, 0))
body.lcBody = true
LC.RebelBodies[body] = { name = "Ada Test", from = cage:GetPos(), t = CurTime() }
LC.RebelBodyTick()
ok(LC.RebelBodies[body] ~= nil, "a body nobody has seen is just a body")
local unit = LC.SpawnCop(body:GetPos() + Vector(200, 0, 4))
local s3 = LC.RebelStanding()
LC.RebelBodyTick()
ok(LC.RebelBodies[body] == nil and LC.RebelStanding() == s3 - 3 and LC.RebelIntel and LC.RebelIntel.pos == cage:GetPos(),
    "a unit finds it: evidence, pointing back to where it came from, and the people hear")
ok(LC.RebelAnswerPending and has(said, "rebel_killing: The Resistance murdered Ada Test. Love your neighbour, hate the traitor."),
    "the Administrator names who they killed, in her own slogan")
ok(string.find(GetGlobal2String("lc_rk_answer", ""), "Ada Test", 1, true), "and it waits on her F2 > City orders for an answer")
local s4 = LC.RebelStanding()
ok(LC.RebelAnswer(adm, "high") and LC.RebelAnswerPending == nil and LC.RebelStanding() == s4 - 4, "she takes the high ground: the Resistance sink further with the people")
-- with nobody playing her: the city's own answers within the minute; a wall and one of theirs in the cells: a reprisal
local wall = LC.AddPoint(R0 + Vector(5000, 0, 0), 0, "execwall", 0)
local auth = Ld.authority
Ld.authority = 60
if LC.FiringSquad then LC.FiringSquadFinish(LC.FiringSquad, "cancelled") end
LC.RebelKillingKnown("Ada Test", "body", body:GetPos())
LC.RebelAnswerTick(CurTime() + 301) -- (a player Administrator has five minutes; the city's own one)
ok(LC.FiringSquad and LC.FiringSquad.why == "reprisal" and LC.RebelAnswerPending == nil, "not answered in time: the city's own answers with a reprisal, one of theirs to the firing squad")
Ld.authority = auth
if LC.FiringSquad then LC.FiringSquadFinish(LC.FiringSquad, "cancelled") end

LC.Psy, LC.MindOf, math.random = psy, mindOf, rnd
LC.Announce = ann
LC.RebelIntel, LC.RebelLies, LC.RebelAnswerPending, LC.Exchange, LC.RebelRuthlessUntil = nil, 0, nil, nil, nil
Ld.rebstanding = 0
LC.RemovePoint(wall)
for _, c in ipairs(cells) do LC.RemovePoint(c) end
for _, e in ipairs({ unit, body, cage }) do if IsValid(e) then e:Remove() end end
_walls = savedWalls
end
Nov19_RebelAnswerTests()

function SewerFlushTests() -- (the owner, 19 November: the Administrator sends the units into the sealed quarter to open its door into the sewers)
    local F = LC.Flush
    section("Sewer flush: not on her tablet where the map has no sealed quarter")
    ok(F ~= nil and LC.OrderFlush ~= nil, "(the module is loaded)")
    if not (F and LC.OrderFlush) then return end
    _setcvar("lc_ledger", 1)
    _setcvar("lc_territory_spread", 1)
    F.Reset()
    local FAR = Vector(-33000, 33000, 0)
    local adm = newPlayer("FlushAdministrator", "admin")
    local cop = newPlayer("FlushRecruit", "cp")
    local ota = newPlayer("FlushSoldier", "ota")
    local late = newPlayer("FlushLate", "cp")
    local other = newPlayer("FlushOther", "cp")
    _runtimers()
    for _, p in ipairs({ cop, ota, late, other }) do p:SetPos(FAR) end
    local realSky, realSeen, realNotice, realXP, realActor = LC.TerritoryOpenSky, LC.IsSeen, LC.Notice, LC.AddXP, LC.QB.SpawnActor
    local RZ -- (the one rebel ground with a roof over it, when there is one)
    LC.TerritoryOpenSky = function(p) return not (RZ and p:DistToSqr(RZ) < 4) end
    LC.IsSeen = function() return false end
    local notices, xp = {}, {}
    LC.Notice = function(p, kind, title, text, secs) notices[#notices + 1] = { p = p, title = title, text = text } return realNotice(p, kind, title, text, secs) end
    LC.AddXP = function(p, n, why) xp[p] = (xp[p] or 0) + n return realXP(p, n, why) end
    local led = LC.Ledger()
    local savedRes, savedAuth, savedDay = led.resistance, led.authority, led.day
    led.resistance = 70
    ok(F.Map() == nil and F.State() == "", "no sealed quarter in this map: nothing on her tablet")
    local okO, whyO = LC.OrderFlush(adm)
    ok(not okO and string.find(tostring(whyO), "no sealed quarter", 1, true) ~= nil, "and the order is refused", whyO)
    local one, whyS = F.Start()
    ok(not one and string.find(tostring(whyS), "lc_raven_post", 1, true) ~= nil and string.find(tostring(whyS), "lc_raven_door_open", 1, true) ~= nil,
        "the staff's test button says which names the map lacks", whyS)

    -- the map's part, stood in for: the four relays and the five marks, and three places for the quarter's infected
    local G0 = Vector(52000, -52000, 0)
    local made, relay = {}, {}
    local function Mark(name, pos, cls)
        local e = ents.Create(cls or "info_target")
        e:SetPos(pos) e:SetName(name) e:Spawn()
        made[#made + 1] = e
        return e
    end
    for _, n in ipairs({ "lc_raven_gate_open", "lc_raven_gate_shut", "lc_raven_door_open", "lc_raven_door_shut" }) do relay[n] = Mark(n, G0 + Vector(0, 0, 500), "logic_relay") end
    local function Pulls(n) local c = 0 for _, i in ipairs(relay[n].fired or {}) do if i == "Trigger" then c = c + 1 end end return c end
    local post, inside = G0 + Vector(-192, 0, 16), G0 + Vector(192, 0, 16)
    local house, console, sewer = G0 + Vector(1200, 300, 16), G0 + Vector(1200, 2400, -340), G0 + Vector(1250, 3100, -330)
    Mark("lc_raven_post", post) Mark("lc_raven_inside", inside) Mark("lc_raven_house", house)
    Mark("lc_raven_console", console, "prop_dynamic") Mark("lc_raven_sewer", sewer)
    for i = 1, 3 do Mark("lc_raven_spawn", G0 + Vector(900 + i * 60, -200, 8)) end
    local seed = LC.AddZone(G0 + Vector(1250, 5200, -330), 300, "infest", 0)
    F.MapForget()
    local m = F.Map()
    ok(m ~= nil and m.post == post and m.console == console, "with the quarter's nine names in the map, it is found")
    if not m then return end
    ok(F.Side(inside, m) == true and F.Side(post, m) == false and F.Side(G0 + Vector(40, 0, 16), m) == nil and F.Side(FAR, m) == nil,
        "by the wall it knows who is in and who is out; right in the gateway, or far off, it says neither")

    section("Sewer flush: her order, only while the Resistance hold ground underground, and it opens nothing")
    local tmpl
    for _, t in ipairs(LC.QuestTemplates) do if t.id == "cmb_flush" then tmpl = t end end
    ok(tmpl ~= nil and tmpl.available(cop) == false, "the job is never on the boards by itself")
    okO, whyO = LC.OrderFlush(adm)
    ok(F.State() == "weak" and not okO and string.find(tostring(whyO), "underground", 1, true) ~= nil, "while the Resistance hold nothing underground it is greyed, and refused", whyO)
    local zUp = LC.AddZone(G0 + Vector(-3000, 3000, 16), 200, "rebel", 0)
    RZ = zUp.pos
    ok(F.State() == "weak", "rebel ground under a roof at street height is not underground")
    local zDown = LC.AddZone(G0 + Vector(1250, 4200, -400), 200, "rebel", 0)
    RZ = nil
    ok(F.State() == "weak", "nor is ground down there under the open sky")
    RZ = zDown.pos
    ok(F.State() == "ready", "with rebel ground under a roof and below the street, it is there")
    local zHQ = LC.AddZone(G0 + Vector(-1500, 0, 0), 300, "combine", 0)
    okO, whyO = LC.OrderFlush(cop)
    ok(not okO and string.find(tostring(whyO), "Administrator", 1, true) ~= nil, "only the City Administrator orders it", whyO)
    local okM, whyM = LC.TargetActions.flush(cop)
    ok(not okM and string.find(tostring(whyM), "[The office]", 1, true) ~= nil and LC.SlashCommands.flush == nil,
        "her tablet sends it by the menu's own call (no chat command), and a stale menu is told why not", whyM)
    SetGlobal2String("lc_event", "curfew")
    okO, whyO = LC.OrderFlush(adm)
    ok(not okO and string.find(tostring(whyO), "event", 1, true) ~= nil, "not while an event is on", whyO)
    SetGlobal2String("lc_event", "")
    notices = {}
    okO, whyO = LC.OrderFlush(adm)
    ok(okO == true, "she gives the order", whyO)
    local function Posted(f) for _, p in ipairs(LC.Postings[f] or {}) do if p.tmpl and p.tmpl.id == "cmb_flush" and not p.dead then return p end end end
    local pc, po = Posted("cp"), Posted("ota")
    ok(pc ~= nil and pc == po, "one job, the same one on Civil Protection's board and the Overwatch's")
    ok(Pulls("lc_raven_gate_open") == 0 and Pulls("lc_raven_door_open") == 0 and F.gate == "shut" and F.door == "shut", "the order itself opens nothing")
    local told = {}
    for _, n in ipairs(notices) do told[n.p] = (told[n.p] or 0) + 1 end
    ok(told[cop] == 1 and told[ota] == 1 and told[adm] == nil, "every unit is told once, and nobody else", tostring(told[cop]) .. " " .. tostring(told[ota]))
    okO, whyO = LC.OrderFlush(adm)
    ok(F.State() == "on" and not okO and string.find(tostring(whyO), "already", 1, true) ~= nil, "it can't be ordered twice over", whyO)
    if not pc then return end

    section("Sewer flush: the briefing, then a power bank and two turrets at the wall by any unit on the job, and the wall opens")
    for _, p in ipairs({ cop, ota, late }) do p.lcqNext = 0 end
    ok(LC.AcceptPosting(cop, pc.id) == true and LC.AcceptPosting(ota, pc.id) == true and LC.AcceptPosting(late, pc.id) == true, "a Recruit, a soldier and another unit take it")
    local q = LC.QuestOf[cop]
    ok(q ~= nil and LC.QuestOf[ota] == q and LC.QuestOf[late] == q and #q.members == 3, "and are on the one job together")
    if not q then return end
    ok(#q.stages == 5 and q.violent == true and q.title == "Flush the sewers", "five steps, and a squad comes as on any violent job", #q.stages)
    for _, st in ipairs(q.stages) do ok(st.kind ~= "hold" and st.kind ~= "survive", "no step is standing and waiting: " .. tostring(st.text)) end
    local officer = q.data.briefer
    ok(q.stage == 1 and IsValid(officer) and string.find(q.stages[1].text, "briefing", 1, true) ~= nil and (officer:GetPos().x - zHQ.pos.x) ^ 2 + (officer:GetPos().y - zHQ.pos.y) ^ 2 < 400 * 400,
        "first the briefing: an officer waits on the Combine's own ground nearest the wall")
    _run(2)
    ok(q.stage == 1, "nothing goes on until someone has heard him")
    cop.chat = {}
    if IsValid(officer) then hook.Run("LivingCityPlayerUsedNPC", cop, officer, LC.NPCs[officer]) end
    local briefed = false
    for _, l in ipairs(cop.chat or {}) do if string.find(l, "power bank and two turrets", 1, true) then briefed = true end end
    ok(q.stage == 2 and briefed, "one of them walks up and uses him: the plan in one line, and on to the wall", q.stage)
    ok(IsValid(officer) and not table.HasValue(q.ents, officer), "he goes about his day: he is not taken away with the job")
    local wallAim = { Hit = true, HitPos = post + Vector(-100, 60, 40), HitNormal = Vector(1, 0, 0) }
    local groundAim = { Hit = true, HitPos = post + Vector(-80, -60, -16), HitNormal = Vector(0, 0, 1) }
    cop.GetEyeTrace = function() return wallAim end
    other.GetEyeTrace = cop.GetEyeTrace
    ok(not LC.FlushKit(cop) and not LC.DeployPowerBank(cop), "away from the wall a Recruit still puts up nothing")
    for _, p in ipairs({ cop, ota, late, other }) do p:SetPos(post + Vector(-50, 0, -16)) end
    _run(1)
    ok(q.stage == 2 and q.stages[2].need == 3, "at the wall: a power bank and two turrets to put up", q.stage)
    ok(cop:GetNW2Bool("lc_flush_kit", false) and not other:GetNW2Bool("lc_flush_kit", false), "the unit tools show the two buttons to a unit on the job, and to no other Recruit")
    local okX = LC.DeployPowerBank(other)
    ok(not okX, "a unit who is not on the job is still refused")
    local okB, whyB = LC.DeployPowerBank(cop)
    local bank = cop.lcBank
    ok(okB and IsValid(bank), "the Recruit on the job puts the power bank up on the wall", whyB)
    _run(1)
    ok(q.stage == 2 and q.stages[2].got == 1 and Pulls("lc_raven_gate_open") == 0, "one of three: the wall stays shut", q.stages[2].got)
    cop.GetEyeTrace = function() return groundAim end
    local okT1, whyT1 = LC.DeployTurret(cop)
    groundAim = { Hit = true, HitPos = post + Vector(-80, 80, -16), HitNormal = Vector(0, 0, 1) }
    ota.GetEyeTrace = function() return groundAim end
    local okT2, whyT2 = LC.DeployTurret(ota)
    ok(okT1 and okT2, "and a turret each from the Recruit and the soldier", tostring(whyT1) .. " / " .. tostring(whyT2))
    _run(1)
    ok(q.stage == 3 and Pulls("lc_raven_gate_open") == 1 and F.gate == "open", "the last one up: the containment wall opens", q.stage)
    ok(not cop:GetNW2Bool("lc_flush_kit", false) and not LC.FlushKit(cop), "and the Recruit's leave to put those up is over")
    cop.lcTurretNext = 0
    ok(not LC.DeployTurret(cop), "another turret is refused him again")

    section("Sewer flush: the wall stays open a minute, shuts on whoever is outside, and they are off the job")
    cop:SetPos(inside + Vector(60, 0, -16))
    ota:SetPos(inside + Vector(80, 40, -16))
    _run(F.GATE_TAKES + 10)
    ok(q.stage == 3 and Pulls("lc_raven_gate_shut") == 0, "two in and one still outside: it waits for him")
    _run(F.GATE_OPEN)
    ok(q.stage == 4 and Pulls("lc_raven_gate_shut") == 1 and F.gate == "shut", "the minute up: it shuts", q.stage)
    ok(LC.QuestOf[late] == nil and #q.members == 2 and not F.inside[late], "the one left outside is off the job")
    ok(F.inside[cop] and F.inside[ota] and q.data.committed == true, "the two inside are shut in")
    other.lcqNext = 0
    ok(LC.AcceptPosting(other, pc.id) ~= true and LC.QuestOf[other] == nil, "nobody joins from outside now")
    F.gateNext = 0
    _run(3)
    ok(Pulls("lc_raven_gate_open") == 1, "and standing at the wall does not open it for them: the only way on is the door")
    ok(#(q.data.zombies or {}) == 3, "the quarter's infected are waiting, one at each of the map's marks", #(q.data.zombies or {}))
    local extra = true
    for _, n in ipairs(q.data.zombies or {}) do if not (LC.NPCs[n] and LC.NPCs[n].unmanaged) then extra = false end end
    ok(extra, "on top of the city's own number")

    section("Sewer flush: down the tunnel, whoever reaches the console rewires it, and the door opens")
    cop:SetPos(house)
    _run(1)
    ok(q.stage == 5, "the tunnel house found: now the console", q.stage)
    ota:SetPos(console + Vector(40, 0, 0))
    _run(1)
    local g = LC.JobGames[ota]
    ok(g ~= nil and g.kind == "wiring" and g.what == "the terminal" and q.data.wirer == ota, "the soldier reaches it first: the wiring is his")
    ok(LC.JobGames[cop] == nil, "and nobody else's")
    ota:Kill()
    _run(1)
    ok(LC.JobGames[ota] == nil and Pulls("lc_raven_door_open") == 0 and not q.done and not F.inside[ota], "he falls at it: the door stays shut, and the job goes on with the other")
    cop:SetPos(console + Vector(40, 0, 0))
    _run(1)
    ok(LC.JobGames[cop] ~= nil and q.data.wirer == cop, "the Recruit reaches it: now the wiring is his")
    local resBefore, grew = led.resistance, LC.TerritoryCanGrow(seed)
    cop.chat = {}
    xp = {}
    LC.JobGameEnd(cop, "done")
    ok(q.done and Pulls("lc_raven_door_open") == 1 and F.door == "open", "rewired: the Combine door opens, and the job is done")
    ok(led.resistance == resBefore + F.RESIST, "the Resistance lose strength for it", led.resistance)
    local flushed = 0
    for _, z in ipairs(LC.ZonesOfKind("infest")) do if z.grown and z.why == "flushed" and z.pos:DistToSqr(sewer) < 16 then flushed = flushed + 1 end end
    ok(not grew or flushed == 1, "the city's own infestation takes hold at the sewer end", flushed)
    local said = false
    for _, l in ipairs(cop.chat or {}) do if string.find(l, "Out the way you came, or on through the sewers", 1, true) then said = true end end
    ok(said and (xp[cop] or 0) > 0 and xp[ota] == nil, "the living are told the two ways out, and paid (who died in there is a new person, off the job)", tostring(xp[cop]) .. " " .. tostring(xp[ota]))
    ok(F.q == nil and F.State() == "done", "on her tablet: done today")

    section("Sewer flush: the wall lets the living back out, and wall and door shut themselves")
    F.gateNext = 0
    cop:SetPos(inside + Vector(60, 0, -16))
    _run(2)
    ok(Pulls("lc_raven_gate_open") == 2 and F.gate == "open" and F.letOut == true, "back at the wall after the door is open: it opens for him")
    cop:SetPos(post + Vector(-60, 0, -16))
    _run(2)
    ok(not F.inside[cop], "out on the city's side, he is out")
    _run(F.GATE_TAKES + F.OUT_OPEN)
    ok(Pulls("lc_raven_gate_shut") == 2 and F.gate == "shut", "and it shuts again behind him")
    F.Tick(CurTime() + F.DOOR_OPEN - 60)
    ok(F.door == "open" and Pulls("lc_raven_door_shut") == 0, "the sewer door stays open for ten minutes")
    F.Tick(CurTime() + F.DOOR_OPEN + 1)
    ok(F.door == "shut" and Pulls("lc_raven_door_shut") == 1, "then shuts itself")

    section("Sewer flush: once a city day; a squad lost inside, or nobody going in, costs her authority")
    okO, whyO = LC.OrderFlush(adm)
    ok(not okO and string.find(tostring(whyO), "today", 1, true) ~= nil, "not twice in a day", whyO)
    led.day = led.day + 1
    led.resistance = 70
    ok(F.State() == "ready" and LC.OrderFlush(adm) == true, "the next day she can order it again")
    local p2 = Posted("cp")
    ok(p2 ~= nil and p2 ~= pc, "(a new posting)")
    LC.QB.SpawnActor = function() return nil end
    if p2 then
        cop.lcqNext = 0
        cop:SetPos(FAR)
        ok(LC.AcceptPosting(cop, p2.id) == true, "the Recruit takes it alone")
        local q2 = LC.QuestOf[cop]
        cop:SetPos(post + Vector(-50, 0, -16))
        _run(2)
        ok(q2.stage == 3 and Pulls("lc_raven_gate_open") == 3, "with no officer to give the briefing the job goes straight on, and what was put up at the wall still stands: it opens", q2.stage)
        cop:SetPos(inside + Vector(60, 0, -16))
        _run(2)
        ok(q2.stage == 4 and Pulls("lc_raven_gate_shut") == 3, "everyone on the job inside: it shuts at once, not after the minute", q2.stage)
        local authBefore = led.authority
        cop:Kill()
        _run(1)
        ok(q2.done and LC.QuestOf[cop] == nil and Pulls("lc_raven_door_open") == 1, "he dies in there: the squad is lost and the door stays shut")
        ok(led.authority == authBefore + F.AUTHORITY, "and the Administrator's authority pays for it", led.authority)
        cop.alive = true
    end
    led.day = led.day + 1
    led.resistance = 70
    ok(LC.OrderFlush(adm) == true, "(a third day, a third order)")
    local p3 = Posted("cp")
    if p3 then
        late.lcqNext = 0
        late:SetPos(FAR)
        LC.AcceptPosting(late, p3.id)
        local q3 = LC.QuestOf[late]
        late:SetPos(post + Vector(-50, 0, -16))
        _run(2)
        ok(q3 ~= nil and q3.stage == 3 and F.gate == "open", "(the wall opens again)", q3 and (tostring(q3.stage) .. " got " .. tostring(q3.stages[2].got)))
        _run(F.GATE_TAKES + F.GATE_OPEN + 2)
        ok(q3 ~= nil and q3.done and F.gate == "shut" and not next(F.inside), "nobody goes in: the wall shuts and the job has failed")
    end

    -- as it was
    LC.TerritoryOpenSky, LC.IsSeen, LC.Notice, LC.AddXP, LC.QB.SpawnActor = realSky, realSeen, realNotice, realXP, realActor
    led.resistance, led.authority, led.day = savedRes, savedAuth, savedDay
    for _, f in ipairs({ "cp", "ota", "resistance" }) do
        for _, p in ipairs(LC.Postings[f] or {}) do if p.tmpl and (p.tmpl.id == "cmb_flush" or p.tmpl.id == "res_sealdoor") then p.dead = true end end
    end
    for _, z in ipairs({ zUp, zDown, zHQ }) do if z then LC.RemoveZone(z) end end
    if IsValid(officer) then officer:Remove() end
    if LC.Breach then LC.Breach.Reset() end
    for t, o in pairs(LC.DeployedTurrets) do if (o == cop or o == ota) and IsValid(t) then LC.DeployedTurrets[t] = nil t:Remove() end end
    if IsValid(bank) then LC.DeployedBanks[bank] = nil bank:Remove() end
    cop.lcBank = nil
    for _, z in ipairs(LC.ZonesOfKind("infest")) do if z.why == "flushed" then LC.RemoveZone(z) end end
    if seed then LC.RemoveZone(seed) end
    for _, e in ipairs(made) do if IsValid(e) then e:Remove() end end
    F.Reset()
    for _, p in ipairs({ adm, cop, ota, late, other }) do p.alive = true p:SetPos(FAR) end
end
SewerFlushTests()

function QuarterBreachTests() -- (the owner, 20 November: the Resistance shut the Combine's door from the quarter's side, and their leader has the wall opened from inside)
    local F, B = LC.Flush, LC.Breach
    section("The Resistance and the sealed quarter: shutting the Combine's door again from the far side")
    ok(F ~= nil and B ~= nil and LC.OrderBreach ~= nil, "(the modules are loaded)")
    if not (F and B and LC.OrderBreach) then return end
    _setcvar("lc_ledger", 1)
    _setcvar("lc_territory_spread", 1)
    F.Reset() B.Reset()
    local FAR = Vector(-33000, 33000, 0)
    local lead = newPlayer("BreachLeader", "resistance", nil, 900)
    local reb = newPlayer("BreachRebel", "resistance", nil, 900)
    local cop = newPlayer("BreachUnit", "cp")
    _runtimers()
    for _, p in ipairs({ lead, reb, cop }) do p:SetPos(FAR) end
    local realSeen, realNotice, realLeader, realSky = LC.IsSeen, LC.Notice, LC.AdminPlotLeader, LC.TerritoryOpenSky
    LC.IsSeen = function() return false end
    LC.AdminPlotLeader = function(p) return p == lead end
    local notices = {}
    LC.Notice = function(p, kind, title, text, secs) notices[#notices + 1] = { p = p, text = text } return realNotice(p, kind, title, text, secs) end
    local function Told(p) local c = 0 for _, n in ipairs(notices) do if n.p == p then c = c + 1 end end return c end
    local led = LC.Ledger()
    local savedRes, savedCmb, savedMor, savedDay = led.resistance, led.combine, led.morale, led.day
    led.resistance, led.combine, led.morale = 50, 50, 50

    -- the map's part, stood in for (the wall's inside console comes later)
    local G0 = Vector(52000, 52000, 0)
    local made, relay = {}, {}
    local function Mark(name, pos, cls)
        local e = ents.Create(cls or "info_target")
        e:SetPos(pos) e:SetName(name) e:Spawn()
        made[#made + 1] = e
        return e
    end
    for _, n in ipairs({ "lc_raven_gate_open", "lc_raven_gate_shut", "lc_raven_door_open", "lc_raven_door_shut" }) do relay[n] = Mark(n, G0 + Vector(0, 0, 500), "logic_relay") end
    local function Pulls(n) local c = 0 for _, i in ipairs(relay[n].fired or {}) do if i == "Trigger" then c = c + 1 end end return c end
    local post, inside = G0 + Vector(-192, 0, 16), G0 + Vector(192, 0, 16)
    local house, console, sewer = G0 + Vector(1200, 300, 16), G0 + Vector(1200, 2400, -340), G0 + Vector(1250, 3100, -330)
    local gateConsole = G0 + Vector(260, 200, 16)
    Mark("lc_raven_post", post) Mark("lc_raven_inside", inside) Mark("lc_raven_house", house)
    Mark("lc_raven_console", console, "prop_dynamic") Mark("lc_raven_sewer", sewer)
    for i = 1, 2 do Mark("lc_raven_spawn", G0 + Vector(900 + i * 60, -200, 8)) end
    local camp = LC.AddZone(G0 + Vector(1250, 4600, -330), 300, "rebel", 0)
    local seed = LC.AddZone(G0 + Vector(-4000, 0, 0), 300, "infest", 0)
    F.MapForget()
    local m = F.Map()
    ok(m ~= nil and m.gateConsole == nil, "(the quarter, without a console inside its wall yet)")
    if not m then return end
    local function Tmpl(id) for _, t in ipairs(LC.QuestTemplates) do if t.id == id then return t end end end
    local function Posted(id) for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == id and not p.dead then return p end end end

    ok(Tmpl("res_sealdoor").available(reb) == false and Posted("res_sealdoor") == nil, "with the Combine's door shut there is nothing to shut")
    notices = {}
    F.OpenDoor()
    local ps = Posted("res_sealdoor")
    ok(F.door == "open" and ps ~= nil, "the door opens: the answer is on the Resistance's board at once")
    ok(Told(lead) == 1 and Told(reb) == 1 and Told(cop) == 0, "and every member is told once, and no unit", Told(lead) .. " " .. Told(reb) .. " " .. Told(cop))
    if ps then
        reb.lcqNext = 0
        ok(LC.AcceptPosting(reb, ps.id) == true, "a member takes it")
        local q = LC.QuestOf[reb]
        ok(q ~= nil and #q.stages == 2 and not q.violent, "two steps and no briefing: there is no time", q and #q.stages)
        for _, st in ipairs(q.stages) do ok(st.kind ~= "hold" and st.kind ~= "survive", "no step is standing and waiting: " .. tostring(st.text)) end
        reb:SetPos(sewer + Vector(40, 0, 0))
        _run(1)
        ok(q.stage == 2 and q.stages[2].pos == console, "at the sewer end: now their console, on the far side", q.stage)
        reb:SetPos(console + Vector(40, 0, 0))
        _run(1)
        local g = LC.JobGames[reb]
        ok(g ~= nil and g.kind == "wiring" and q.data.wirer == reb, "at the console: the wiring is his")
        local resBefore = led.resistance
        LC.JobGameEnd(reb, "done")
        ok(q.done and F.door == "shut" and Pulls("lc_raven_door_shut") == 1, "rewired: the door shuts, and the job is done")
        ok(led.resistance == resBefore + B.RESIST, "the Resistance win back some strength", led.resistance)
    end
    -- the door shutting by itself ends the job
    F.OpenDoor()
    local ps2 = Posted("res_sealdoor")
    ok(ps2 ~= nil and ps2 ~= ps, "(open again: up again)")
    if ps2 then
        reb.lcqNext = 0
        reb:SetPos(FAR)
        LC.AcceptPosting(reb, ps2.id)
        local q = LC.QuestOf[reb]
        F.Tick(CurTime() + F.DOOR_OPEN + 1)
        _run(1)
        ok(F.door == "shut" and q ~= nil and q.done and LC.QuestOf[reb] == nil, "the door shuts by itself first: the job is over")
        ok(Tmpl("res_sealdoor").available(reb) == false, "and it is off the board")
    end

    section("The Resistance and the sealed quarter: the leader's order to open the wall from inside")
    ok(B.State() == "" and Tmpl("res_breach").available(lead) == false, "a quarter with no console inside its wall: no such order")
    local okS, whyS = B.Start()
    ok(not okS and string.find(tostring(whyS), "lc_raven_gate_console", 1, true) ~= nil, "the staff's test button says what the map lacks", whyS)
    Mark("lc_raven_gate_console", gateConsole, "prop_dynamic")
    F.MapForget()
    m = F.Map()
    ok(m ~= nil and m.gateConsole == gateConsole and B.State() == "ready", "with it, the order is there")
    B.Tick()
    ok(lead:GetNW2Bool("lc_res_leads", false) and not reb:GetNW2Bool("lc_res_leads", false), "on the leader's F2, and nobody else's")
    local okO, whyO = LC.OrderBreach(reb)
    ok(not okO and string.find(tostring(whyO), "leader", 1, true) ~= nil, "only the Resistance's leader gives it", whyO)
    local okM, whyM = LC.TargetActions.breach(reb)
    ok(not okM and string.find(tostring(whyM), "[Resistance]", 1, true) ~= nil and LC.SlashCommands.breach == nil, "by the menu's own call (no chat command)", whyM)
    notices = {}
    okO, whyO = LC.OrderBreach(lead)
    local pb = Posted("res_breach")
    ok(okO == true and pb ~= nil, "the leader gives it: one job on the Operations board", whyO)
    ok(Told(lead) == 1 and Told(reb) == 1 and Told(cop) == 0 and Pulls("lc_raven_gate_open") == 0, "every member is told once, and the order itself opens nothing")
    okO, whyO = LC.OrderBreach(lead)
    ok(B.State() == "on" and not okO and string.find(tostring(whyO), "already", 1, true) ~= nil, "not twice over", whyO)
    -- while it is up the wall is not the Administrator's to use
    local adm = newPlayer("BreachAdministrator", "admin")
    LC.TerritoryOpenSky = function(p) return p:DistToSqr(camp.pos) > 4 end
    local okF, whyF = LC.OrderFlush(adm)
    ok(F.State() == "busy" and not okF, "and while it is up the Administrator's own order waits", tostring(F.State()) .. " " .. tostring(whyF))
    if not pb then return end
    lead.lcqNext = 0
    ok(LC.AcceptPosting(lead, pb.id) == true, "the leader takes it himself")
    local q = LC.QuestOf[lead]
    if not q then return end
    ok(#q.stages == 4 and not q.violent and q.title == "Open the sealed quarter", "four steps", #q.stages)
    for _, st in ipairs(q.stages) do ok(st.kind ~= "hold" and st.kind ~= "survive", "no step is standing and waiting: " .. tostring(st.text)) end
    local runner = q.data.briefer
    -- (across the ground: the test world's floor is not at the camp's own height)
    local function Flat(v, w) return (v.x - w.x) ^ 2 + (v.y - w.y) ^ 2 end
    ok(q.stage == 1 and IsValid(runner) and Flat(runner:GetPos(), camp.pos) < 400 * 400, "first the plan: the cell's runner waits on rebel ground nearest the sewer end")
    lead.chat = {}
    if IsValid(runner) then hook.Run("LivingCityPlayerUsedNPC", lead, runner, LC.NPCs[runner]) end
    local planned = false
    for _, l in ipairs(lead.chat or {}) do if string.find(l, "In by the vent", 1, true) then planned = true end end
    ok(q.stage == 2 and planned, "he says it in one line", q.stage)
    lead:SetPos(console + Vector(60, 0, 0))
    _run(1)
    ok(q.stage == 3 and #(q.data.zombies or {}) == 2, "through the vent and in the tunnel: the quarter's infected are waiting", tostring(q.stage) .. " " .. #(q.data.zombies or {}))
    lead:SetPos(house)
    _run(1)
    ok(q.stage == 4 and q.stages[4].pos == gateConsole, "out by the tunnel house: now the wall's console, on the inside", q.stage)
    lead:SetPos(gateConsole + Vector(40, 0, 0))
    _run(1)
    ok(LC.JobGames[lead] ~= nil and LC.JobGames[lead].kind == "wiring", "at it: the wiring")
    local cmbBefore, morBefore, grew = led.combine, led.morale, LC.TerritoryCanGrow(seed)
    LC.JobGameEnd(lead, "done")
    ok(q.done and F.gate == "open" and Pulls("lc_raven_gate_open") == 1, "rewired: the wall opens onto the city, and the job is done")
    ok(led.combine == cmbBefore + B.COMBINE and led.morale == morBefore + B.MORALE, "the Combine lose strength and the city morale", led.combine .. " " .. led.morale)
    local breached = 0
    for _, z in ipairs(LC.ZonesOfKind("infest")) do if z.grown and z.why == "breached" and z.pos:DistToSqr(post) < 16 then breached = breached + 1 end end
    ok(not grew or breached == 1, "the city's own infestation takes hold in the street outside", breached)
    F.Tick(CurTime() + F.GATE_TAKES + B.HAVOC - 30)
    ok(F.gate == "open", "it stays open five minutes")
    F.Tick(CurTime() + F.GATE_TAKES + B.HAVOC + 1)
    ok(F.gate == "shut" and Pulls("lc_raven_gate_shut") == 1, "then shuts itself")
    okO, whyO = LC.OrderBreach(lead)
    ok(B.State() == "done" and not okO and string.find(tostring(whyO), "today", 1, true) ~= nil, "once a city day", whyO)

    -- as it was
    LC.IsSeen, LC.Notice, LC.AdminPlotLeader, LC.TerritoryOpenSky = realSeen, realNotice, realLeader, realSky
    led.resistance, led.combine, led.morale, led.day = savedRes, savedCmb, savedMor, savedDay
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and (p.tmpl.id == "res_sealdoor" or p.tmpl.id == "res_breach") then p.dead = true end end
    for _, z in ipairs(LC.ZonesOfKind("infest")) do if z.why == "breached" or z.why == "flushed" then LC.RemoveZone(z) end end
    for _, z in ipairs({ camp, seed }) do if z then LC.RemoveZone(z) end end
    if IsValid(runner) then runner:Remove() end
    for _, e in ipairs(made) do if IsValid(e) then e:Remove() end end
    F.Reset() B.Reset()
    for _, p in ipairs({ lead, reb, cop, adm }) do p.alive = true p:SetPos(FAR) end
end
QuarterBreachTests()

function DaylightTests() -- (the owner, 20 November: the map's own lights: the sun and sky by the hour, the dream room's, the darker places)
    local D = LC.Daylight
    section("The map's lights: the sun and the sky by the hour, where the map has given the sun a name")
    ok(D ~= nil, "(the module is loaded)")
    if not D then return end
    local function Cv(n) local c = GetConVar(n) return c and c:GetString() or nil end
    local saved = { atmos = Cv("lc_atmosphere"), light = Cv("lc_daynight_light"), dn = Cv("lc_daynight"), hour = LC.Hour(), phase = LC.AtmosPhase, style = LC.LightStyle }
    _setcvar("lc_atmosphere", 1) _setcvar("lc_daynight_light", 1) _setcvar("lc_daynight", 1)
    local made = {}
    local function Ent(cls, name, pos)
        local e = ents.Create(cls)
        e:SetPos(pos or Vector(0, 0, 0))
        if name then e:SetName(name) end
        e:Spawn()
        e.did = {}
        e.Fire = function(self, input, param) self.did[#self.did + 1] = { input, param } end
        made[#made + 1] = e
        return e
    end
    local function Last(e, input) for k = #e.did, 1, -1 do if e.did[k][1] == input then return e.did[k][2] or true end end return nil end
    for _, e in ipairs(ents.FindByClass("light_environment")) do e:Remove() end
    D.Reset()
    ok(D.Sun() == nil and not D.SunHooked(), "a map whose sun has no name: it cannot be faded, and nothing here says it can")
    LC.AtmosPhase, LC.LightStyle = "night", nil
    LC.ApplyLightStyle()
    ok(LC.LightStyle == "d", "there the old way stands: every light of the map dimmed for the night", LC.LightStyle)
    ok(D.SunLetter(12) == "m" and D.SunLetter(0) == "a" and D.SunLetter(23) == "a" and D.SunLetter(4.9) == "a", "the sun: full by day, out by night")
    ok(D.SunLetter(6) == "g" and D.SunLetter(20) == "g" and D.SunLetter(5.5) < D.SunLetter(6.5) and D.SunLetter(19.5) > D.SunLetter(20.5), "rising a step at a time through dawn, falling through dusk")
    ok(D.GloomLetter(0) == "e" and D.GloomLetter(12) == "m", "the quarter's own lights: low by night, never out")

    local sun = Ent("light_environment", "lc_sun", Vector(0, 0, 5000))
    local glow = Ent("env_sun", nil, Vector(0, 0, 5000))
    local gloom = Ent("light", "lc_raven_gloom", Vector(70000, 70000, 0))
    local sky = Ent("env_skypaint", nil, Vector(0, 0, 5000))
    -- (as the owner's map has it: black at every hour, with the stock star picture)
    local was = { TopColor = Vector(0, 0, 0), BottomColor = Vector(0, 0, 0), SunSize = 0, SunColor = Vector(0.6, 0.5, 0.2), SunNormal = Vector(0.4, 0, 0.01),
        DuskScale = 0.75, DuskIntensity = 0.7, DuskColor = Vector(0, 0.05, 0.12), DrawStars = true }
    local vals = {}
    for k, v in pairs(was) do
        vals[k] = v
        sky["Get" .. k] = function() return vals[k] end
        sky["Set" .. k] = function(_, x) vals[k] = x end
    end
    local function Same(a, b) if type(a) ~= "number" and type(a) ~= "boolean" and type(a) ~= "string" then return math.abs(a.x - b.x) + math.abs(a.y - b.y) + math.abs(a.z - b.z) < 0.001 end return a == b end
    local function AsSet() for k, v in pairs(was) do if not Same(vals[k], v) then return false, k end end return true end
    D.Reset()
    LC.SetHour(12)
    D.Tick()
    ok(D.SunHooked() and Last(sun, "FadeToPattern") == "m" and Last(gloom, "FadeToPattern") == "m", "with a name it is ours: at noon the sun and the quarter's lights are full")
    ok(Same(vals.TopColor, D.SKY.day.top) and Same(vals.BottomColor, D.SKY.day.bottom) and vals.SunSize == D.SUN_SIZE and vals.SunNormal.z > 0.9,
        "and the sky is painted for the day: grey-blue, a pale sun high in it")
    ok(vals.DrawStars == false and GetGlobal2Bool("lc_sky_stars", false) == true, "the stock star picture is off: each client draws its own stars")
    LC.AtmosPhase, LC.LightStyle = "night", nil
    LC.ApplyLightStyle()
    ok(LC.LightStyle == "m", "the map's other lights are no longer dimmed for the night: only the sun goes", LC.LightStyle)
    LC.SetHour(6)
    D.Tick()
    ok(Last(sun, "FadeToPattern") == "g" and vals.TopColor.z > D.SKY.night.top.z and vals.TopColor.z < D.SKY.day.top.z and vals.DuskIntensity > 1 and vals.SunNormal.z < 0.1,
        "at dawn the sun is half up and low in the east, the sky between night and day, and the horizon glows")
    LC.SetHour(0)
    D.Tick()
    ok(Last(sun, "FadeToPattern") == "a" and Last(gloom, "FadeToPattern") == "e" and Last(glow, "TurnOff") == true, "at midnight the sun is out, its glow is off, and the quarter's lights are low")
    ok(Same(vals.TopColor, D.SKY.night.top) and vals.SunSize == 0 and vals.SunNormal.z < 0 and vals.DuskIntensity == 0, "the sky is near black, the sun below the horizon")
    local n = #sun.did
    D.Tick()
    ok(#sun.did == n, "nothing is sent again while nothing changes")
    LC.SetHour(12)
    D.Tick()
    ok(Last(sun, "FadeToPattern") == "m" and Last(glow, "TurnOn") == true and Same(vals.TopColor, D.SKY.day.top), "and at noon it is day again")
    _setcvar("lc_daynight_light", 0)
    LC.SetHour(0)
    D.Tick()
    ok(not D.SunHooked() and Last(sun, "FadeToPattern") == "m" and AsSet() and GetGlobal2Bool("lc_sky_stars", false) == false,
        "with the night's dimming switched off in the settings: the sun stays full, and the sky is the map's own again, as it was set", select(2, AsSet()))
    _setcvar("lc_daynight_light", 1)

    section("The map's lights: the dream room's, set by the dream")
    local P = Vector(-70000, -70000, 0)
    local zone = { pos = P, r = 1000 }
    local a, b = Ent("light", "evr_l", P + Vector(1500, 0, 800)), Ent("light_spot", "evr_l", P + Vector(0, -1900, 800))
    local own = Ent("light", "lc_dream_light", P + Vector(30000, 0, 0))
    local far = Ent("light", "subway_flicker_light", P + Vector(9000, 0, 0))
    local quarter = Ent("light", "lc_raven_gloom", P + Vector(200, 0, 0))
    local white, red = D.DreamLights(zone)
    ok(#white == 3 and #red == 0, "the room's lights: every named light in or round the dream zone, and any named for it; not one far off, nor another place's", #white .. " " .. #red)
    local okU, whyU = D.SetDreamLights("purple", zone)
    ok(okU == false and whyU ~= nil, "a mode there is not is refused")
    ok(D.SetDreamLights("off", zone) == 3 and Last(a, "TurnOff") == true and Last(b, "TurnOff") == true and Last(far, "TurnOff") == nil, "off: every one of them out, and only them")
    D.SetDreamLights("flicker", zone)
    ok(Last(a, "SetPattern") == D.MODES.flicker.white and Last(a, "TurnOn") == true, "flicker: on, with a flickering pattern")
    D.SetDreamLights("red", zone)
    ok(Last(a, "SetPattern") == "e", "red, in a map with no red set: the room dimmed instead")
    local r1 = Ent("light", "lc_dream_red", P + Vector(1500, 0, 800))
    D.SetDreamLights("red", zone)
    ok(Last(a, "TurnOff") == true and Last(r1, "SetPattern") == "m" and a.did[#a.did][1] == "TurnOff", "with the red set: the white ones out and the red ones on")
    local realMood = LC.DreamMood
    LC.DreamMood = function(id) return ({ grim = "nightmare", sweet = "happy" })[id] or "neutral" end
    ok(D.ModeFor({ id = "harpies", zone = zone }) == "off" and D.ModeFor({ id = "grim", zone = zone }) == "red" and D.ModeFor({ id = "sweet", zone = zone }) == "on",
        "each dream's own: the one where every light goes out, a nightmare in red, a happy one as it is")
    r1:Remove()
    ok(D.ModeFor({ id = "grim", zone = zone }) == "dim", "a nightmare with no red set: dim")
    -- (this module's own listeners alone: the dream here is only a name and a zone, not a whole dream)
    hook.GetTable().LivingCityDreamStarted.LivingCityDaylight({ id = "grim", zone = zone })
    ok(Last(a, "SetPattern") == "e" and D.dreamMode == "dim", "as the dream starts the room is set")
    hook.GetTable().LivingCityDreamEnded.LivingCityDaylight({ id = "grim", zone = zone })
    ok(Last(a, "SetPattern") == "m" and a.did[#a.did][1] == "SetPattern" and D.dreamMode == "on", "and as it ends the lights are back on")
    LC.DreamMood = realMood
    local okN, whyN = D.SetDreamLights("off", { pos = Vector(90000, 90000, 0), r = 100 })
    ok(okN == 1 and Last(own, "TurnOff") == true, "(a light named for the dream room counts wherever it is)")
    own:Remove()
    okN, whyN = D.SetDreamLights("off", { pos = Vector(90000, 90000, 0), r = 100 })
    ok(okN == false and string.find(tostring(whyN), "no named lights", 1, true) ~= nil, "a room with no named lights: said so, nothing done", whyN)

    section("The map's lights: the darker places, from the map's marks")
    Ent("info_target", "lc_mood_dark", Vector(100, 200, 300))
    Ent("info_target", "lc_mood_dim", Vector(-100, -200, 300))
    Ent("info_target", "lc_mood_dim", Vector(-900, -200, 300))
    local dark, dim = 0, 0
    for _, m in ipairs(D.Moods()) do if m.k == "dark" then dark = dark + 1 elseif m.k == "dim" then dim = dim + 1 end end
    ok(dark == 1 and dim == 2, "one dark mark and two dim: what every client is sent", dark .. " " .. dim)
    local rep = D.Report()
    ok(string.find(rep, "named (lc_sun)", 1, true) ~= nil and string.find(rep, "1 dark mark, 2 dim", 1, true) ~= nil and string.find(rep, "painted", 1, true) ~= nil,
        "the staff's button says what the map has, in plain words", rep)

    -- as it was
    for _, e in ipairs(made) do if IsValid(e) then e:Remove() end end
    D.Reset()
    if saved.atmos then _setcvar("lc_atmosphere", saved.atmos) end
    if saved.light then _setcvar("lc_daynight_light", saved.light) end
    if saved.dn then _setcvar("lc_daynight", saved.dn) end
    LC.SetHour(saved.hour)
    LC.AtmosPhase, LC.LightStyle = saved.phase, nil
    LC.ApplyLightStyle()
end
DaylightTests()

function BaseTests()
-- the owner, 20 November: one Resistance headquarters at a time; its leader sets it up by raising a flag, and it moves
-- only by being packed up, ransacked by the Combine, or overrun and won back (sv_livingcity_base.lua)
section("The Resistance's headquarters: one base at a time, a flag raised by its leader")
local B = LC.Base
local was = {}
for _, k in ipairs({ "lc_base_setup_time", "lc_base_pack_time", "lc_base_stay", "lc_base_overrun", "lc_base_teardown" }) do was[k] = GetConVar(k):GetInt() end
ok(was.lc_base_setup_time == 300 and was.lc_base_pack_time == 180 and was.lc_base_stay == 600 and GetConVar("lc_base_radius"):GetInt() == 4800
    and GetConVar("lc_base_ransack_share"):GetInt() == 35 and LC.BaseOn() == true,
    "the settings: five minutes to set up within 300 feet (4800 units), three to pack, ten before it may be packed, 35 per cent taken in a ransack; on")
_setcvar("lc_base_setup_time", 5) _setcvar("lc_base_pack_time", 5) _setcvar("lc_base_stay", 0) _setcvar("lc_base_overrun", 3) _setcvar("lc_base_teardown", 2)
B.Reset()
local T0 = Vector(-300000, 300000, 0)
local far = T0 + Vector(0, 90000, 0)
local z1 = LC.AddZone(nil, nil, "rebel", 0, { mins = T0 + Vector(-400, -400, -16), maxs = T0 + Vector(400, 400, 192) })
local z2 = LC.AddZone(nil, nil, "rebel", 0, { mins = T0 + Vector(20000, -400, -16), maxs = T0 + Vector(20800, 400, 192) })
local boss = newPlayer("BaseCommander", "resistance", nil, 99999)
local foot = newPlayer("BaseFighter", "resistance", nil, 400)
local cop = newPlayer("BaseCop", "cp")
boss:SetPos(T0) foot:SetPos(far) cop:SetPos(far)
local deputy = newPlayer("BaseLieutenant", "resistance", nil, 900)
deputy:SetPos(far)
ok(LC.BaseMayLead(boss) == true and LC.BaseMayLead(deputy) == true and LC.BaseMayLead(foot) == false and LC.BaseMayLead(cop) == false,
    "a Commander or a Lieutenant may raise the flag, both at once; a Fighter may not, nor a unit", LCF.RankOf(deputy) and LCF.RankOf(deputy).name)
-- a bare pole stands in every rebel territory, for anyone to walk up to
B.Poles()
local p1, p2 = B.poles[LC.RebelLeader(z1)], B.poles[LC.RebelLeader(z2)]
ok(IsValid(p1) and IsValid(p2) and p1 ~= p2 and p1:GetNW2Bool("lc_flag_up", true) == false and p1:GetNW2Bool("lc_baseflag", false) == true,
    "each rebel territory has its own pole, bare until a flag is raised on it")
-- and one at each of the map's own spots for a pole, a territory over it or not (the owner, 20 November)
local mark = ents.Create("info_target") mark:SetName("lc_hq_setup_test") mark:SetPos(far + Vector(0, 3000, 0)) mark:Spawn()
local inside = ents.Create("info_target") inside:SetName("lc_hq_setup_inside") inside:SetPos(T0 + Vector(100, 100, 0)) inside:Spawn()
B.Poles()
local mp, np = nil, 0
for k, e in pairs(B.poles) do if IsValid(e) and isstring(k) then np = np + 1 if e:GetPos():DistToSqr(mark:GetPos()) < 100 then mp = e end end end
ok(IsValid(mp) and mp:GetNW2Bool("lc_baseflag", false) == true and np == 1,
    "a bare pole stands at the map's marker outside any territory too; a marker inside one is that territory's own pole, not a second", np)
boss:SetPos(mp:GetPos() + Vector(40, 0, 0))
ok(LC.BasePoleUse(boss) == false and B.S.state == nil, "at a marker's pole outside rebel territory not even the leader can raise a flag")
boss:SetPos(T0)
mark:Remove() inside:Remove()
B.Poles()
for k, e in pairs(B.poles) do if isstring(k) then np = -1 end end
ok(np ~= -1, "a marker that is gone takes its pole with it")
p1 = B.poles[LC.RebelLeader(z1)]
foot:SetPos(p1:GetPos() + Vector(40, 0, 0))
ok(LC.BasePoleUse(foot) == false and B.S.state == nil, "a Fighter pressing E at the pole raises nothing (the pole's own prompt tells him who can)")
foot:SetPos(far)
deputy:SetPos(p2:GetPos() + Vector(40, 0, 0))
ok(LC.BasePoleUse(deputy) == true and B.S.state == "raising" and B.S.zone == LC.RebelLeader(z2) and B.S.flag == p2,
    "a Lieutenant pressing E at a pole raises the flag on that pole, a Commander playing or not")
B.Tick(1)
deputy:SetPos(far)
boss:SetPos(p2:GetPos() + Vector(300, 0, 0))
local before = B.S.prog
B.Tick(1)
ok(B.S.prog > before, "whoever of those ranks is near keeps it climbing: the one who started it can leave")
ok(LC.BasePoleUse(boss) == false and B.S.state == "raising", "(E does nothing away from the pole)")
boss:SetPos(p2:GetPos() + Vector(40, 0, 0))
ok(LC.BasePoleUse(boss) == true and B.S.state == nil and IsValid(p2) and p2:GetNW2Bool("lc_flag_up", true) == false,
    "E at the pole again gives it up: the flag goes, the pole stays")
boss:SetPos(T0)
local function live() for _ = 1, 6 do B.Tick(1) end return B.S.state == "live" end
local function count() local n = 0 for _, e in pairs(B.S.props or {}) do if IsValid(e) then n = n + 1 end end return n end

-- who may raise it, and where
local did, why = LC.BaseRaise(foot)
ok(did == false and B.S.state == nil and why ~= nil, "a Fighter cannot raise the flag", tostring(why))
boss:SetPos(far)
ok(LC.BaseRaise(boss) == false and B.S.state == nil, "nor the leader anywhere but rebel territory")
boss:SetPos(T0)
did, why = LC.BaseRaise(boss)
ok(did == true and B.S.state == "raising" and IsValid(B.S.flag) and B.S.zone == LC.RebelLeader(z1),
    "the leader, standing in rebel territory, raises the flag: a pole where he stood", tostring(why))
ok(LC.BaseLive() == nil and count() == 0 and LC.BaseShows(z1) == false, "it is no headquarters yet, and no office shows")

-- the flag climbs while he is near and the ground is clear; its height is all that players are told
B.Tick(1) B.Tick(1)
local h = B.S.prog
ok(math.abs(h - 0.4) < 0.01 and math.abs(B.S.flag:GetNW2Float("lc_flag_h", 0) - 0.4) < 0.01, "the flag climbs with the time (two fifths up after 2 of 5 seconds)", h)
boss:SetPos(far)
B.Tick(1)
ok(B.S.prog == h, "and stops when the leader is out of reach")
boss:SetPos(T0)
cop:SetPos(T0 + Vector(100, 0, 0))
B.Tick(1)
ok(B.S.prog == h, "or while a unit stands on its ground")
cop:SetPos(far)
ok(live() and LC.BaseLive() == LC.RebelLeader(z1), "at the top it is the headquarters")
ok(count() == #LC.BaseOffice and IsValid(B.S.props.bank) and B.S.props.bank:GetModel() == "models/props_lab/securitybank.mdl" and B.S.props.desk.lcRebelProp == "desk",
    "and the office appears round the pole: the monitors, the desk and the rest, each one of the camp's things to carry", count())
ok(LC.BaseShows(z1) == true and LC.BaseShows(z2) == false, "this camp is the one whose office shows")

-- one at a time
boss:SetPos(T0 + Vector(20400, 0, 0))
did, why = LC.BaseRaise(boss)
ok(did == false and B.S.zone == LC.RebelLeader(z1), "no second flag while one flies", tostring(why))

-- packing up: not at once, and it takes time; where the office stood is kept for this place
boss:SetPos(T0)
_setcvar("lc_base_stay", 600)
did, why = LC.BaseStrike(boss)
ok(did == false and B.S.state == "live", "the flag cannot be struck as soon as it is up", tostring(why))
_setcvar("lc_base_stay", 0)
B.S.props.desk:SetPos(T0 + Vector(222, 111, 0))
ok(LC.BaseOrder(boss) == true and B.S.state == "striking", "the leader's one line on F2 strikes it")
ok(LC.BaseOrder(boss) == true and B.S.state == "live", "and, pressed again, hoists it back")
LC.BaseOrder(boss)
B.Tick(1) B.Tick(1)
ok(B.S.state == "striking" and B.S.prog < 1 and count() == #LC.BaseOffice, "it comes down over the packing time, the office still there")
for _ = 1, 4 do B.Tick(1) end
ok(B.S.state == nil and LC.BaseLive() == nil and not IsValid(B.S.flag), "at the bottom the headquarters is packed: no flag, no office, no base")
local gone = {}
hook.Add("LivingCityBaseGone", "BaseTests", function(z, how) gone[#gone + 1] = how end)
ok(LC.BaseRaise(boss) == true and live(), "(raised again in the same place)")
local d = B.S.props.desk:GetPos()
ok(math.abs(d.x - (T0.x + 222)) < 1 and math.abs(d.y - (T0.y + 111)) < 1, "the desk is where it was left here: each place's office is laid out once", tostring(d))

-- the Combine: a unit at the pole, with no rebel on the ground, tears it down and takes a share of the fund
LC.ResistanceFundAdd(1000, "test")
local fund = LC.ResistanceFund()
local seized
hook.Add("LivingCityBaseRansacked", "BaseTests", function(z, n, u) seized = { z, n, u } end)
cop:SetPos(B.S.pos + Vector(40, 0, 0))
ok(LC.BaseTear(cop) == false and B.S.tear == nil, "a unit cannot touch the flag while a rebel holds the ground")
boss:SetPos(far)
ok(LC.BaseTear(boss) == false and LC.BaseTear(cop) == true and B.S.tear ~= nil, "with the ground empty of rebels, a unit at the pole starts it down (nobody else can)")
B.Tick(1)
ok(B.S.flag:GetNW2Float("lc_flag_h", 1) < 1 and B.S.state == "live", "the flag comes down as the unit pulls")
foot:SetPos(T0)
B.Tick(1)
ok(B.S.tear == nil and B.S.state == "live" and B.S.flag:GetNW2Float("lc_flag_h", 0) == 1, "a rebel coming back stops it, and the flag is up again")
foot:SetPos(far)
LC.BaseTear(cop)
B.Tick(1) B.Tick(1)
local taken = math.floor(fund * 0.35)
ok(B.S.state == nil and LC.ResistanceFund() == fund - taken and seized and seized[2] == taken and seized[3] == cop and gone[#gone] == "ransacked",
    "torn down: no headquarters, the office gone, 35 per cent of the fund taken", LC.ResistanceFund(), fund, taken)

-- overrun: zombies on the ground and no rebel there; the office stays and can be won back
boss:SetPos(T0)
ok(LC.BaseRaise(boss) == false and B.S.state == nil, "no flag goes up with a unit standing there")
cop:SetPos(far)
ok(LC.BaseRaise(boss) == true and live(), "(raised a third time)")
boss:SetPos(far)
local crab = ents.Create("npc_headcrab")
crab:SetPos(B.S.pos + Vector(60, 0, 0))
crab:Spawn()
local g = B.Ground(B.S.pos, 700)
ok(g.wild == true and g.combine == false and #g.rebels == 0, "(a headcrab on the ground counts as the wild; so does a zombie player)")
crab:Remove()
local zed = newPlayer("BaseZombie", "zombie")
zed:SetPos(B.S.pos + Vector(60, 0, 0))
-- (the clock moved by hand, the base's own second and nothing else of the city's: what else runs in a second may move players)
local function pass(n) for _ = 1, n do _advance(1) B.Tick(1) end end
pass(5)
ok(B.S.state == "overrun" and LC.BaseLive() == nil and count() == #LC.BaseOffice and math.abs(B.S.flag:GetNW2Float("lc_flag_h", 0) - 0.5) < 0.01,
    "zombies on its ground with no rebel there: overrun, the flag at half mast, the office still standing", tostring(B.S.state))
boss:SetPos(T0 + Vector(20400, 0, 0))
ok(LC.BaseRaise(boss) == false and LC.BaseOrder(boss) == false, "no flag goes up elsewhere while it is overrun")
boss:SetPos(T0)
pass(3)
ok(B.S.state == "overrun", "a rebel walking in is not enough while they are still there")
zed:SetPos(far)
pass(22)
ok(B.S.state == "live" and LC.BaseLive() == LC.RebelLeader(z1), "cleared out and held a little: the headquarters is live again", tostring(B.S.state))

-- under a roof the pole is short (a base in the canal's shantytown shows no flag over the walls)
LC.BaseOrder(boss)
for _ = 1, 6 do B.Tick(1) end
ok(B.S.state == nil, "(struck and packed)")
local traceWas = util.TraceLine
util.TraceLine = function(t) return { Hit = true, HitPos = t.start + Vector(0, 0, 192) } end
ok(LC.BaseRaise(boss) == true and B.S.high == 176 and B.S.flag:GetNW2Float("lc_flag_top", 0) == 176, "raised under a roof 200 up, the pole is 176 tall, not 330", tostring(B.S.high))
util.TraceLine = traceWas
LC.BaseOrder(boss)
util.TraceLine = function() return { Hit = false } end
ok(LC.BaseRaise(boss) == true and B.S.high == 330, "and in the open it is the full 330")
util.TraceLine = traceWas

-- the camps' own monitors are part of the office now; with the feature off, each camp has its own as before
ok(LC.BaseOn() == true, "(on: the camps put out no monitors of their own, sv_livingcity_scavenge.lua)")

hook.Remove("LivingCityBaseGone", "BaseTests")
hook.Remove("LivingCityBaseRansacked", "BaseTests")
B.Reset()
for k, v in pairs(was) do _setcvar(k, v) end
LC.RemoveZone(z1) LC.RemoveZone(z2)
boss:Remove() foot:Remove() cop:Remove() zed:Remove() deputy:Remove()
end
BaseTests()

function IEDTests()
-- the owner, 20 November: IEDs set on the ground and blown by hand, on roads and on the tracks, where they stop the
-- trains until the Combine mend them (sv_livingcity_ied.lua)
section("IEDs: set, blown by hand, and what they do to the tracks")
local I = LC.IED
I.Reset()
ok(GetConVar("lc_ied_max"):GetInt() == 3 and GetConVar("lc_ied_arm"):GetInt() == 2 and GetConVar("lc_ied_radius"):GetInt() == 320
    and GetConVar("lc_ied_damage"):GetInt() == 220 and GetConVar("lc_ied_track"):GetInt() == 260, "the settings: three at once, live after 2 seconds, 220 over 320, the rails within 260")
ok(LCS.Items.ied ~= nil and LCS.Items.ied.contraband == true, "the IED is an item, and contraband")
local recipe
for _, r in ipairs(LCS.Lab) do if r.id == "ied" then recipe = r end end
ok(recipe ~= nil and recipe.needs.weedkiller == 2 and recipe.needs.scrap == 3 and recipe.needs.gun_parts == 1, "made at the lab: 2 weedkiller, 3 scrap, 1 gun parts")
local P0 = Vector(-310000, 310000, 0)
local reb = newPlayer("IEDRebel", "resistance", nil, 400)
local cop = newPlayer("IEDCop", "cp")
reb:SetPos(P0) cop:SetPos(P0 + Vector(0, 50000, 0))
local traceWas = util.TraceLine
local ground = true
util.TraceLine = function(t) return ground and { Hit = true, HitPos = t.endpos, HitNormal = Vector(0, 0, 1) } or { Hit = true, HitPos = t.endpos, HitNormal = Vector(1, 0, 0) } end
local did, why = LC.IEDPlant(reb)
ok(did == false and why ~= nil, "nothing to set without one", tostring(why))
LC.GiveItem(reb, "ied", 5)
LC.IEDSync(reb)
ok(reb:HasWeapon("weapon_lc_ied"), "carrying one puts the Detonator in your hands")
ground = false
ok(LC.IEDPlant(reb) == false and #I.set == 0, "it is set on the ground, not on a wall")
ground = true
ok(LC.IEDPlant(reb) == true and #I.set == 1 and I.set[1].lcOwner == reb and not LC.HasItem(reb, "ied", 5), "set: one on the ground, one fewer carried")
did, why = LC.IEDDetonate(reb)
ok(did == false and #I.set == 1, "it cannot be blown at once (not live for 2 seconds)", tostring(why))
LC.IEDPlant(reb) LC.IEDPlant(reb)
did, why = LC.IEDPlant(reb)
ok(did == false and #I.set == 3, "three of yours at once, no more", tostring(why))
ok(LC.IEDDetonate(cop) == false, "nobody else's hand blows them")

-- a unit who finds one takes it apart
cop:SetPos(I.set[3]:GetPos() + Vector(30, 0, 0))
ok(LC.IEDUnitUse(cop) == true and #I.set == 2, "a unit pressing E at one takes it apart")
ok(LC.IEDUnitUse(reb) == false, "(a rebel's E does nothing to them)")
cop:SetPos(P0 + Vector(0, 50000, 0))

-- blown by hand: a blast where each lay
local blasts = {}
hook.Add("LivingCityIED", "IEDTests", function(pos, by) blasts[#blasts + 1] = by end)
_advance(3)
ok(LC.IEDDetonate(reb) == true and #I.set == 0 and #blasts == 2 and blasts[1] == reb, "right click blows every live one of yours", #blasts)
LC.TakeItem(reb, "ied", 2)
LC.IEDSync(reb)
ok(not reb:HasWeapon("weapon_lc_ied"), "with none carried and none set, the Detonator goes")

-- on the tracks: the train's timetable stops and rubble marks the place; a unit mends it
local wrecked, mended = {}, {}
hook.Add("LivingCityTracksWrecked", "IEDTests", function(name, pos, by) wrecked[#wrecked + 1] = name end)
hook.Add("LivingCityTracksRepaired", "IEDTests", function(name, by) mended[#mended + 1] = by end)
local railsWas = I.Rails
local A, Bp = P0 + Vector(-2000, 300, 0), P0 + Vector(2000, 300, 0)
local train = ents.Create("prop_physics")
train:SetPos(A)
I.Rails = function() return { { name = "lc_train_9", a = A, b = Bp, train = train } } end
LC.GiveItem(reb, "ied", 2)
reb:SetPos(P0 + Vector(0, 2000, 0))          -- (far from the rails)
LC.IEDPlant(reb)
_advance(3)
LC.IEDDetonate(reb)
ok(#wrecked == 0 and LC.TracksWrecked() == false, "an IED on a road, away from the rails, leaves the trains alone")
reb:SetPos(P0 + Vector(0, 250, 0))           -- (beside them)
LC.IEDPlant(reb)
_advance(3)
LC.IEDDetonate(reb)
ok(#wrecked == 1 and wrecked[1] == "lc_train_9" and LC.TracksWrecked() == true and LC.TracksWrecked("lc_train_9") == true and IsValid(I.wrecks.lc_train_9.marker),
    "one beside the rails wrecks them: no train runs there, and rubble marks the place", #wrecked)
ok(math.abs(I.wrecks.lc_train_9.pos.y - (P0.y + 300)) < 1, "(the rubble lies on the rails, at the nearest point)")
ok(I.wrecks.lc_train_9.derailed == false, "(no train was passing: none is stopped)")
reb:SetPos(I.wrecks.lc_train_9.pos)
ok(LC.IEDUnitUse(reb) == false and LC.TracksWrecked() == true, "a rebel cannot mend them")
local gamesWas = LC.JobGameStart
local started
LC.JobGameStart = function(ply, kind, q, opts) started = { ply, kind, opts } LC.JobGames[ply] = { kind = kind, ply = ply, opts = opts, props = {}, notes = {}, pay = 0 } return true end
cop:SetPos(I.wrecks.lc_train_9.pos + Vector(40, 0, 0))
ok(LC.IEDUnitUse(cop) == true and started and started[2] == "wiring" and started[3].lcTrack == "lc_train_9" and LC.TracksWrecked() == true,
    "a unit pressing E at the rubble is given the rewiring game: mending is work, not waiting")
LC.JobGameStart = gamesWas
LC.JobGames[cop] = nil
ok(I.Repair("lc_train_9", cop) == true and LC.TracksWrecked() == false and #mended == 1 and mended[1] == cop, "mended: the rubble goes and the trains run again")
-- a train passing the blast is stopped where it is
train:SetPos(P0 + Vector(100, 300, 0))
I.Wreck({ name = "lc_train_9", a = A, b = Bp, train = train }, P0 + Vector(0, 300, 0), reb)
ok(I.wrecks.lc_train_9.derailed == true, "a train within 600 of the blast is stopped there")
I.Rails = railsWas
util.TraceLine = traceWas
hook.Remove("LivingCityIED", "IEDTests") hook.Remove("LivingCityTracksWrecked", "IEDTests") hook.Remove("LivingCityTracksRepaired", "IEDTests")
I.Reset()
train:Remove() reb:Remove() cop:Remove()
end
IEDTests()

function Nov21_StationScreenTests()
section("21 November: the train station's giant Breencast screen, Valve's curved one, as an editor entry")
local was = ENT
ENT = {}
assert(loadstring(_ENTSRC["entities/lc_screen.lua"], "lc_screen"))()
local def = ENT
ENT = was
local S, strips = def.ScreenSizes, def.StationStrips
ok(S and S.screen_station and S.screen_station.station == true, "a station screen kind")
ok(strips and #strips == 14, "Valve's 13 strips (14 edges)", strips and #strips)
local wide = strips and (strips[1][1] - strips[#strips][1])
ok(wide and math.abs(wide - 184) < 1, "184 wide, as Valve's", wide)
ok(strips and strips[7][5] > 320 and strips[7][4] > 90, "321 tall, its top leaning toward the watcher", strips and strips[7][4])
local M0 = Vector(-96000, -50000, 0)
local p = LC.AddPoint(M0, 0, "screen_station", 0)
ok(p ~= nil and p.kind == "screen_station", "the editor can place one")
LC.SyncFixtures()
local e
for _, f in pairs(LC.Fixtures) do if IsValid(f) and f.lcFixturePoint == p then e = f end end
ok(IsValid(e) and e:GetClass() == "lc_screen" and e.lcFixtureKind == "screen_station", "it is a city screen like the others (broadcasts show on it)")
ok(IsValid(e) and e:GetPos().z - M0.z >= 150, "and it hangs high, as Valve's does", IsValid(e) and e:GetPos().z)
LC.RemovePoint(p)
LC.SyncFixtures()
ok(not IsValid(e), "taken away with its point")
end
Nov21_StationScreenTests()

function TurretTests()
section("21 November: the Combine's barricade with its mounted gun (Valve's, by the canals' double gate), as an editor entry")
local T = LC.Turret
local was = ENT
ENT = {}
assert(loadstring(_ENTSRC["entities/lc_turret.lua"], "lc_turret"))()
local def = ENT
ENT = was
-- the gun as the game makes it (the harness doesn't give entities their scripts' methods): its own functions,
-- Spawn running Initialize, Remove running OnRemove, and what the engine does with its model
local createWas, effectWas = ents.Create, util.Effect
local flashes = 0
util.Effect = function(name) if name == "MuzzleFlash" then flashes = flashes + 1 end end
ents.Create = function(cls)
    local e = createWas(cls)
    if cls == "lc_turret" then
        for k, v in pairs(def) do e[k] = v end
        e.poses, e.shots, e.seqs = {}, {}, { idle = 1, idle_inactive = 2, activate = 3, retract = 4, fire = 5 }
        local none = function() end
        e.PhysicsInit, e.SetMoveType, e.SetSolid, e.SetCycle, e.NextThink, e.MuzzleFlash = none, none, none, none, none, none
        e.SetPoseParameter = function(self, k, v) self.poses[k] = v end
        e.ResetSequence = function(self, s) self.seq = s end
        e.SequenceDuration = function() return 0.4 end
        e.LookupAttachment = function() return 0 end
        e.GetAttachment = function() return nil end
        e.FireBullets = function(self, b) self.shots[#self.shots + 1] = b end
        e.Spawn = function(self) self:Initialize() end
        local rm = e.Remove
        e.Remove = function(self) if self.valid and self.OnRemove then self:OnRemove() end return rm(self) end
    end
    return e
end
local function Restore() ents.Create, util.Effect = createWas, effectWas end

-- placed with the editor, facing 90
local M0 = Vector(-97000, -52000, 0)
local p = LC.AddPoint(M0, 90, "mounted_gun", 0)
ok(p ~= nil and p.kind == "mounted_gun", "the editor can place one")
LC.SyncFixtures()
_run(0.3)
local gun
for _, f in pairs(LC.Fixtures) do if IsValid(f) and f.lcFixturePoint == p then gun = f end end
ok(IsValid(gun) and gun:GetClass() == "lc_turret" and gun.lcFixtureKind == "mounted_gun" and gun:GetModel() == "models/props_combine/bunker_gun01.mdl",
    "it is Valve's Combine bunker gun (lc_turret)")
if not IsValid(gun) then Restore() if p then LC.RemovePoint(p) LC.SyncFixtures() end return end
ok(math.abs(gun:GetPos().z - (M0.z + 33)) < 0.01 and math.abs(gun:GetPos().x - M0.x) < 0.01, "its foot 33 above the floor, as Valve's", gun:GetPos().z)
local parts = gun.lcParts or {}
ok(#parts == 2 and IsValid(parts[1]) and IsValid(parts[2]) and parts[1]:GetModel() == "models/props_combine/combine_barricade_short02a.mdl"
    and parts[2]:GetModel() == "models/props_combine/combine_barricade_short01a.mdl", "between Valve's two short Combine barricades")
local l, r = IsValid(parts[1]) and parts[1]:GetPos(), IsValid(parts[2]) and parts[2]:GetPos()
ok(l and r and l.x < M0.x - 30 and r.x > M0.x + 30 and math.abs(l.z - (M0.z + 23.03)) < 0.01, "one either side of it (its left is -x here), standing where Valve's do", l and l.x)
ok(IsValid(parts[1]) and parts[1].kv.solid == "6" and parts[1]:GetClass() == "prop_dynamic_override" and parts[1].lcTurretGun == gun,
    "solid, and part of the gun (E on a barricade is E on the gun)")
ok(gun.seq == gun.seqs.idle_inactive, "folded up while nobody mans it, as Valve's")

local cit = newPlayer("TGunner", "citizen")
local cop = newPlayer("TCop", "cp")
_run(1)
cit:SelectWeapon("weapon_pistol")
local press, keys, think = hook.t.KeyPress.LivingCityTurret, hook.t.StartCommand.LivingCityTurret, hook.t.Think.LivingCityTurret
local function Behind(ply) ply:SetPos(T.ToWorld(gun, -41, 0, -33)) ply.lookingAt = gun ply.aim = T.Dir(90, 0) end
local function Cmd(b)
    local c = { b = b or 0, cleared = false }
    function c:KeyDown(k) return k ~= nil and bit.band(self.b, k) ~= 0 end
    function c:RemoveKey(k) if k then self.b = bit.band(self.b, bit.bnot(k)) end end
    function c:GetButtons() return self.b end
    function c:SetButtons(v) self.b = v end
    function c:ClearMovement() self.cleared = true end
    function c:ClearButtons() self.b = 0 end
    return c
end

-- manned from behind, as in Valve's map
cit:SetPos(T.ToWorld(gun, 60, 0, -33)) cit.lookingAt = gun
press(cit, IN_USE)
ok(LC.TurretOf(cit) == nil, "E from in front of it does nothing: the gunner stands behind it")
Behind(cit)
press(cit, IN_USE)
ok(LC.TurretOf(cit) == gun and gun:GetNW2Entity("lc_turret_gunner") == cit and cit:GetNW2Entity("lc_turret") == gun, "E on it from behind mans it")
local w = cit:GetActiveWeapon()
ok(w and w:GetClass() == "weapon_lc_hands", "their own weapon is put away", w and w:GetClass())
ok(gun.seq == gun.seqs.activate, "and the gun unfolds")
Behind(cop) cop:SetPos(cop:GetPos() + Vector(20, 0, 0))
press(cop, IN_USE)
ok(LC.TurretOf(cop) == nil, "one gunner at a time")

-- holding attack: the gun fires, never their own weapon, and they stay put
local c = Cmd(bit.bor(IN_ATTACK, IN_FORWARD))
keys(cit, c)
ok(c.cleared and not c:KeyDown(IN_ATTACK) and gun.lcFire == true, "holding attack fires the gun, not their own weapon, and they stay put")
c = Cmd(T.FIRE_RELAY)
keys(cit, c)
ok(gun.lcFire == true and not c:KeyDown(T.FIRE_RELAY), "(the click their own computer passes on, on a key no weapon uses, fires it too)")
local s0 = #_sounds
for _ = 1, 20 do _advance(0.1) keys(cit, Cmd(IN_ATTACK)) think() end
local n = #gun.shots
ok(n >= 28 and n <= 31, "15 rounds a second, Valve's rate (two seconds held)", n)
local b = gun.shots[1] or {}
ok(b.Attacker == cit and b.Inflictor == gun, "every bullet is the gunner's: they are the attacker, the gun the inflictor (the laws and kills see who shot)")
ok(b.Damage == 5, "each does 5, Valve's own against players, to anyone (the owner, 21 November: \"this is the damage we want universally\")", b.Damage)
ok(b.TracerName == "AR2Tracer" and b.Tracer == 1 and b.AmmoType == "AR2" and b.Spread ~= nil and math.abs(b.Spread.x - 0.025) < 1e-6,
    "AR2 rounds and tracers, in Valve's small cone")
local snd = 0
for i = s0 + 1, #_sounds do if _sounds[i] == "Weapon_functank.Single" then snd = snd + 1 end end
ok(flashes >= n and snd == n, "a muzzle flash and Valve's func_tank shot for every round", snd)
ok(b.Src ~= nil and T.ToLocal(gun, b.Src) > 15 and b.Dir ~= nil and b.Dir.y > 0.99, "from the muzzle, straight ahead where they look", b.Dir and b.Dir.y)
ok(cit.lcFiredAt ~= nil and cit.lcFiredAt > CurTime() - 0.2, "and they count as having fired a gun (armed and fighting)")

-- the aim: toward their crosshair at Valve's rates, no further than 60 degrees from its facing
gun.lcFire = false
cit.aim = T.Dir(0, 0) -- (a quarter turn to its right)
_advance(0.1) think()
ok(math.abs(gun.lcYaw + 20) < 0.01, "it turns at Valve's 200 degrees a second", gun.lcYaw)
for _ = 1, 20 do _advance(0.1) think() end
ok(math.abs(gun.lcYaw + 60) < 0.01 and math.abs(gun:GetNW2Float("lc_turret_yaw", 0) + 60) < 0.06, "and no further than 60 degrees across", gun.lcYaw)
ok(math.abs((gun.poses.aim_yaw or 0) + 60) < 0.01, "(the model's own aim_yaw set to match)")
local before = #gun.shots
keys(cit, Cmd(IN_ATTACK)) _advance(0.1) think()
local last = gun.shots[#gun.shots] or {}
ok(#gun.shots > before and last.Dir and last.Dir.x > 0.85 and math.abs(last.Dir.y - 0.5) < 0.02, "the rounds go where the barrel points", last.Dir and last.Dir.x)
gun.lcFire = false
local traceWas = util.TraceLine
util.TraceLine = function(t) return { Hit = false, HitPos = t.endpos, Fraction = 1 } end
cit.aim = T.Dir(90, 80)
for _ = 1, 20 do _advance(0.1) think() end
ok(math.abs(gun.lcPitch - 60) < 0.01 and math.abs((gun.poses.aim_pitch or 0) - 67.5) < 0.01, "60 down at most (the model is level at its aim_pitch 7.5, as Valve set it)", gun.lcPitch)
cit.aim = T.Dir(90, -80)
for _ = 1, 20 do _advance(0.1) think() end
ok(math.abs(gun.lcPitch + 60) < 0.01, "and 60 up", gun.lcPitch)
util.TraceLine = traceWas
-- Valve's aim assistance for a player on the gun
local victim = { IsValid = function() return true end, IsNPC = function() return true end, IsPlayer = function() return false end,
    Health = function() return 50 end, WorldSpaceCenter = function() return T.ToWorld(gun, 400, 30, 10) end }
local hullWas = util.TraceHull
util.TraceHull = function(t) return { Hit = true, Entity = victim, HitPos = t.endpos } end
gun.lcYaw, gun.lcPitch = 0, 0
LC.TurretFire(gun, cit)
util.TraceHull = hullWas
last = gun.shots[#gun.shots] or {}
ok(last.Src and last.Dir and last.Dir:Dot((victim:WorldSpaceCenter() - last.Src):GetNormalized()) > 0.9999, "someone a round would just graze is hit square (Valve's aim assistance)")

-- letting go: E again, a jump, knocked off it, dying
_advance(0.5)
press(cit, IN_USE)
w = cit:GetActiveWeapon()
ok(LC.TurretOf(cit) == nil and gun:GetNW2Entity("lc_turret_gunner") == nil and cit:GetNW2Entity("lc_turret") == nil, "E again lets go")
ok(w and w:GetClass() == "weapon_pistol", "and their pistol is back in hand", w and w:GetClass())
ok(gun.seq == gun.seqs.retract, "the gun folds up")
c = Cmd(IN_ATTACK)
keys(cit, c)
ok(c:KeyDown(IN_ATTACK) and not c.cleared, "off it, their keys are their own again")
_advance(0.5) Behind(cit) press(cit, IN_USE)
ok(LC.TurretOf(cit) == gun, "(on it again)")
keys(cit, Cmd(IN_JUMP))
ok(LC.TurretOf(cit) == nil, "a jump lets go")
_advance(0.5) Behind(cit) press(cit, IN_USE)
cit:SetPos(cit:GetPos() + Vector(80, 0, 0))
_advance(0.1) think()
ok(LC.TurretOf(cit) == nil, "knocked off it, they let go")
_advance(0.5) Behind(cit) press(cit, IN_USE)
ok(LC.TurretOf(cit) == gun, "(on it again)")
cit:Kill()
ok(LC.TurretOf(cit) == nil and gun:GetNW2Entity("lc_turret_gunner") == nil, "dying lets go")

-- an officer on it (the owner, 21 November: "if there is an enemy within range of the turret and relatively in front of it, then yes")
local runWas = LC.Running
LC.Running = false -- (no city about: the officer is the test's)
local officer, ost = LC.SpawnCop(T.ToWorld(gun, -300, 200, -33))
local rebel = ents.Create("npc_citizen")
LC.NPCs[rebel] = { role = "rebel", state = "idle" }
rebel:SetPos(T.ToWorld(gun, -900, 0, -33))
gun.lcNPCNext = 0
LC.TurretWatch(CurTime())
ok(IsValid(officer) and ost ~= nil and ost.turretGun == nil and T.Gunners[gun] == nil, "a rebel behind it: no officer is sent to it")
rebel:SetPos(T.ToWorld(gun, 900, 100, -33))
LC.TurretWatch(CurTime())
ok(ost ~= nil and ost.turretGun == gun and ost.state == "turretgun" and T.Gunners[gun] == officer, "a rebel in front of it, in range: the nearest free officer is sent to it")
local function Steps(n) for _ = 1, n do _advance(0.1) _simulate(0.1) think() end end
local before2 = #gun.shots
Steps(30)
local spot = T.ToWorld(gun, T.SPOT.x, T.SPOT.y, T.SPOT.z)
ok(ost.turretPhase == "manning" and IsValid(officer) and officer:GetPos():Distance(spot) <= 40 and gun:GetNW2Entity("lc_turret_gunner") == officer,
    "he runs to the spot behind it, where Valve's Metrocop stands, and mans it", IsValid(officer) and officer:GetPos():Distance(spot))
last = gun.shots[#gun.shots] or {}
local toRebel = last.Src and (rebel:WorldSpaceCenter() - last.Src):GetNormalized()
ok(#gun.shots > before2 + 10 and last.Attacker == officer and last.Damage == 5 and toRebel and last.Dir:Dot(toRebel) > 0.995,
    "and fires it at the rebel, at Valve's rate, every round his own", #gun.shots - before2)
rebel:SetPos(T.ToWorld(gun, -900, 0, -33))
Steps(20)
ok(ost.turretGun == gun, "the rebel gone from in front of it: he stays on it a moment (Valve's persistence)")
Steps(20)
ok(ost.turretGun == nil and ost.state == "idle" and not ost.questLock and T.Gunners[gun] == nil and gun:GetNW2Entity("lc_turret_gunner") == nil,
    "then lets go, back to his beat")
_advance(T.RECALL + 0.1)
rebel:SetPos(T.ToWorld(gun, 900, 100, -33))
LC.TurretWatch(CurTime())
Steps(3)
ok(ost.turretGun == gun and ost.turretPhase == "manning", "(sent to it again for the next one)")
officer:SetHealth(10)
Steps(1)
ok(ost.turretGun == nil and T.Gunners[gun] == nil, "badly hurt, he breaks off")
officer:SetHealth(officer:GetMaxHealth())
_advance(T.RECALL + 0.1)
LC.TurretWatch(CurTime())
Steps(3)
ok(ost.turretGun == gun and ost.turretPhase == "manning", "(on it again)")
Behind(cop)
press(cop, IN_USE)
ok(LC.TurretOf(cop) == gun and T.Gunners[gun] == cop and ost.turretGun == nil and ost.state == "idle", "a player of the Combine pressing E takes it from him: a player comes first")
_advance(0.5)
press(cop, IN_USE)
ok(LC.TurretOf(cop) == nil, "(and lets it go)")
LC.NPCs[rebel] = nil rebel:Remove()
LC.NPCs[officer] = nil officer:Remove()
LC.Running = runWas

-- anyone may man it; the gun going lets its gunner go
_advance(0.5) Behind(cop)
press(cop, IN_USE)
ok(LC.TurretOf(cop) == gun and LC.TurretMayUse(cop, gun) and LC.TurretMayUse(cit, gun), "anyone may man it, a unit as well as a citizen (as the rebels take the Combine's guns)")
LC.RemovePoint(p)
LC.SyncFixtures()
ok(not IsValid(gun) and not IsValid(parts[1]) and not IsValid(parts[2]), "taken away with its editor point, its barricades with it")
ok(LC.TurretOf(cop) == nil and cop:GetNW2Entity("lc_turret") == nil, "and its gunner lets go")
Restore()
cit:Remove() cop:Remove()
end
TurretTests()

function IdlePoseTests()
section("21 November: Valve's idle spots, one pose each; bench seats 48 apart, two sits in turn")
local P0 = Vector(152000, -152000, 0)
local made, people = {}, {}
local function point(off, kind, yaw) local p = LC.AddPoint(P0 + off, yaw or 0, kind, 0) made[#made + 1] = p return p end
local function person(off, seqs)
    local n, st = LC.SpawnCitizen(P0 + off)
    n.seqs, n.sim, st.test, st.leaveAt = seqs, false, nil, nil
    st.state, st.untilT = "idle", CurTime() + 9999
    people[#people + 1] = n
    return n, st
end
local function playing(st) return st.ss and st.ss.kv.m_iszPostIdle, st.ss and st.ss.kv.m_iszPlay end
for _, k in ipairs({ "window", "armscrossed", "drinker", "couch", "bedside" }) do
    ok(LC.POINT_KINDS[k] and LC.BUSY_ACTS[k] ~= nil and LC.SITTABLE[k], "a " .. k .. " spot is placed with the editor, and citizens idle there", k)
end
-- a window: a man and a woman each have their own of Valve's two watchers
local man, mst = person(Vector(-30, 0, 0), { d1_t03_Tenements_Look_Out_Window_Idle = 11 })
ok(LC.StartBusy(man, mst, point(Vector(0, 0, 0), "window", 90)) and mst.state == "busy" and playing(mst) == "d1_t03_Tenements_Look_Out_Window_Idle",
    "a man at a window looks out of it (Valve's tenement watcher, d1_t03)", playing(mst))
local woman, wst = person(Vector(-30, 40, 0), { d1_t03_LookOutWindow = 12 })
ok(LC.StartBusy(woman, wst, point(Vector(0, 40, 0), "window", 90)) and playing(wst) == "d1_t03_LookOutWindow", "a woman has her own (d1_t03_LookOutWindow)", playing(wst))
-- a model without Valve's pose: the game's own idle, never a name the model lacks
local plain, pst = person(Vector(-30, 80, 0), {})
local win3 = point(Vector(0, 80, 0), "window", 90)
ok(not LC.StartBusy(plain, pst, win3) and pst.state ~= "busy", "nothing the model hasn't got is ever played")
local hadQ = ACT_BUSY_QUEUE
ACT_BUSY_QUEUE = hadQ or 9001
plain.acts = { [ACT_BUSY_QUEUE] = 4 }
plain.GetSequenceName = function() return "LineIdle01" end
ok(LC.StartBusy(plain, pst, win3) and playing(pst) == "LineIdle01", "a model with only the game's own stands there in it (the queue idle)", playing(pst))
ACT_BUSY_QUEUE = hadQ
-- arms crossed or hands in pockets: one of them for each person, always the same one
local stand = point(Vector(0, 120, 0), "armscrossed", 90)
local idler, ist = person(Vector(-30, 120, 0), { d1_t02_Playground_Cit1_Arms_Crossed = 1, d1_t02_Playground_Cit2_Pockets = 2 })
local _, l1 = LC.BusyPose(idler, ist, stand)
local _, l2 = LC.BusyPose(idler, ist, stand)
ok((l1 == "d1_t02_Playground_Cit1_Arms_Crossed" or l1 == "d1_t02_Playground_Cit2_Pockets") and l1 == l2, "standing about: arms crossed or hands in pockets, the same for the same person", l1)
-- a drinker's seat: Valve's seated drinker, a bottle out for one fond of a drink, and Valve's way up again
local seat = point(Vector(0, 160, 0), "drinker", 90)
local drinker, dst = person(Vector(-30, 160, 0), { drinker_sit = 1, drinker_sit_idle = 2, Sit_Chair_to_Idle = 3 })
local viceOf, vicesWas = LC.NPCViceOf, GetConVar("lc_npc_vices"):GetString()
LC.NPCViceOf = function(n) return n == drinker and 0.8 or 0 end
_setcvar("lc_npc_vices", 1)
local idle, play = nil, nil
ok(LC.StartBusy(drinker, dst, seat), "a citizen sits at a drinker's seat")
idle, play = playing(dst)
ok(play == "drinker_sit" and idle == "drinker_sit_idle", "Valve's seated drinker: sitting down, then the drinker's idle", tostring(play) .. " " .. tostring(idle))
ok(LC.NPCVices[drinker] and IsValid(LC.NPCVices[drinker].prop) and LC.NPCVices[drinker].untilT >= dst.untilT - 0.01, "fond of a drink: the bottle is out while they sit", LC.NPCVices[drinker] and LC.NPCVices[drinker].untilT)
LC.NPCViceOf = viceOf
_setcvar("lc_npc_vices", vicesWas)
if LC.NPCViceStop then LC.NPCViceStop(drinker) end
local before = {}
for _, e in ipairs(ents.FindByClass("scripted_sequence")) do before[e] = true end
LC.EndBusy(drinker, dst, true)
local exitSeq
for _, e in ipairs(ents.FindByClass("scripted_sequence")) do if not before[e] and IsValid(e) then exitSeq = e.kv.m_iszPlay end end
ok(exitSeq == "Sit_Chair_to_Idle", "getting up plays the way out of the seat", exitSeq)
-- a couch and a bed's edge
local cman, cst = person(Vector(-30, 200, 0), { sitcouch1 = 1, sitcouchknees1 = 2, laycouch1 = 3, laycouch1_exit = 4 })
local _, cl = LC.BusyPose(cman, cst, point(Vector(0, 200, 0), "couch", 90))
ok(cl == "sitcouch1" or cl == "sitcouchknees1" or cl == "laycouch1", "on a couch: one of Valve's couch poses", cl)
local bwoman, bst = person(Vector(-30, 240, 0), { d1_t03_Sit_Bed_Entry = 1, d1_t03_Sit_Bed = 2, d1_t03_Sit_Bed_Exit = 3 })
local be, bl, bx = LC.BusyPose(bwoman, bst, point(Vector(0, 240, 0), "bedside", 90))
ok(be == "d1_t03_Sit_Bed_Entry" and bl == "d1_t03_Sit_Bed" and bx == "d1_t03_Sit_Bed_Exit", "on a bed's edge: Valve's d1_t03 bed sit, in and out", tostring(bl))
-- bench seats: 48 apart along the bench, and Valve's two plaza sits in turn
local s1 = point(Vector(0, 400, 0), "sitchair", 0)
local at, yaw = LC.BenchSeatSnap(P0 + Vector(5, 430, 0), 10)
ok(math.abs((at - s1.pos):Length() - 48) < 0.01 and yaw == 0 and math.abs(at.x - s1.pos.x) < 0.01, "a seat placed beside another goes 48 from it along the bench, facing the same way", tostring(at))
local s2 = point(at - P0, "sitchair", yaw)
at, yaw = LC.BenchSeatSnap(s2.pos + Vector(0, 40, 0), 0)
local s3 = point(at - P0, "sitchair", yaw)
ok(math.abs((s3.pos - s2.pos):Length() - 48) < 0.01 and math.abs((s3.pos - s1.pos):Length() - 96) < 0.01, "and the next one 48 further on", tostring(s3.pos))
local far, fyaw = LC.BenchSeatSnap(P0 + Vector(0, 700, 0), 0)
ok(far == P0 + Vector(0, 700, 0) and fyaw == 0, "a seat nowhere near another stays where it is put")
local _, tyaw = LC.BenchSeatSnap(P0 + Vector(40, 400, 0), 180)
ok(tyaw == 180, "a chair facing the other way (across a table) is left alone")
local chair = point(Vector(0, 1000, 0), "sitchair", 0)
local i1, i2, i3 = LC.BenchSeatIndex(s1), LC.BenchSeatIndex(s2), LC.BenchSeatIndex(s3)
ok(i1 and i2 and i3 and i1 % 2 == i3 % 2 and i1 % 2 ~= i2 % 2 and LC.BenchSeatIndex(chair) == nil, "three seats in a row, counted along the bench; a lone chair is no bench",
    tostring(i1) .. tostring(i2) .. tostring(i3))
local benchSeqs = { Idle_to_d1_t01_BreakRoom_Sit01 = 1, d1_t02_Plaza_Sit01_Idle = 2, d1_t01_BreakRoom_Sit01_to_Idle = 3,
    d1_t01_BreakRoom_Sit02_Entry = 4, d1_t02_Plaza_Sit02 = 5, d1_t01_BreakRoom_Sit02_Exit = 6 }
local sitter, sst = person(Vector(-30, 400, 0), benchSeqs)
local _, b1 = LC.BusyPose(sitter, sst, s1)
local _, b2 = LC.BusyPose(sitter, sst, s2)
local _, b3 = LC.BusyPose(sitter, sst, s3)
ok(b1 == b3 and b1 ~= b2 and (b1 == "d1_t02_Plaza_Sit01_Idle" or b1 == "d1_t02_Plaza_Sit02") and (b2 == "d1_t02_Plaza_Sit01_Idle" or b2 == "d1_t02_Plaza_Sit02"),
    "along a bench, Valve's two plaza sits take turns seat by seat (d1_trainstation_02)", tostring(b1) .. " " .. tostring(b2) .. " " .. tostring(b3))
ok(select(2, LC.BusyPose(sitter, sst, chair)) == nil, "a lone chair keeps the game's own sit")
for _, n in ipairs(people) do if IsValid(n) then local st = LC.NPCs[n] if st and st.state == "busy" then LC.EndBusy(n, st, false) end n:Remove() end end
for _, p in ipairs(made) do LC.RemovePoint(p) end
end
IdlePoseTests()

function SeenMomentTests()
section("21 November: a moment waits until a player is looking (Valve's way); a mind's break is seen, not told")
local S0 = Vector(156000, -140000, 0)
local savedWalls = _walls
_walls = {}
local ply = newPlayer("Onlooker", "citizen")
ply:SetPos(S0 + Vector(-600, 0, 0))
local cit, cst = LC.SpawnCitizen(S0)
cit.sim, cst.test, cst.leaveAt = false, nil, nil
cst.state, cst.untilT = "idle", CurTime() + 9999
local spot = cit:GetPos() + Vector(0, 0, 48)
local function lookAt(p) ply.aim = (p - ply:EyePos()):GetNormalized() end
ply.aim = Vector(-1, 0, 0)
ok(LC.SpotWatched(spot) == nil, "a player 600 away looking the other way doesn't see it")
lookAt(spot)
ok(LC.SpotWatched(spot) == ply, "looking at it, within 1000 and in plain sight: seen")
_walls = { { a = S0 + Vector(-300, -200, 0), b = S0 + Vector(-300, 200, 0) } }
ok(LC.SpotWatched(spot) == nil, "a wall between: not seen")
_walls = {}
ply:SetPos(S0 + Vector(-1400, 0, 0)) lookAt(spot)
ok(LC.SpotWatched(spot) == nil, "1400 away: too far (Valve: 1000)")
ply:SetPos(S0 + Vector(-100, 0, 0)) ply.aim = Vector(-1, 0, 0)
ok(LC.SpotWatched(spot) == ply, "closer than 128: right there, seen whichever way they look")
-- a moment waits: the citizen stops where they are, and it happens once a player has had them in view a moment
ply:SetPos(S0 + Vector(-600, 0, 0)) ply.aim = Vector(-1, 0, 0)
local fired
LC.WhenSeen(cit, function(n, s, seen, who) fired = { seen = seen, who = who } end, { need = 1 })
ok(cst.state == "event" and not fired, "until then the citizen stops where they stand", cst.state)
local t0 = CurTime()
LC.StageTick(t0 + 0.5)
ok(not fired, "nobody looking: nothing yet")
lookAt(spot)
LC.StageTick(t0 + 1)
ok(not fired, "a glance is not enough: in view for a moment first")
LC.StageTick(t0 + 2.2)
ok(fired and fired.seen == true and fired.who == ply and cst.state == "idle", "in view for a second: it happens, and they go on with their day", cst.state)
fired = nil
ply.aim = Vector(-1, 0, 0)
LC.WhenSeen(cit, function(n, s, seen) fired = { seen = seen } end)
LC.StageTick(CurTime() + 14)
ok(not fired, "nobody looking: it waits")
LC.StageTick(CurTime() + 15.1)
ok(fired and fired.seen == false and cst.state == "idle", "and after 15 seconds it happens anyway (Valve's timeout)")
fired = nil
LC.WhenSeen(cit, function() fired = true end)
cst.state = "detained" -- (taken in meanwhile)
LC.StageTick(CurTime() + 16)
local left = false
for _, s in ipairs(LC.StagedMoments) do if s.npc == cit then left = true end end
ok(not fired and not left and cst.state == "detained", "taken by something else meanwhile: the moment is dropped, and they are left to it")
cst.state = "idle"
-- a break: a tantrum at a unit, seen, with a fist shaken and nothing in chat
_setcvar("lc_minds", 1)
_setcvar("lc_minds_act", 1)
if not cit.lcProfile then LC.AttachProfile(cit, cst, LC.NewPerson("citizen")) end
local m = LC.MindOf(cit.lcProfile)
LC.Psy.State(m)
local unit, ust = LC.SpawnCop(S0 + Vector(300, 0, 0))
ust = ust or LC.NPCs[unit]
unit.sim = false
cit.seqs = { g_fistshake = 41 }
cit.AddGestureSequence = function(self, s) self.gestured = s end
local arrest = LC.ArrestNPC
LC.ArrestNPC = function() return false end
ply.chat = {}
ply.aim = Vector(-1, 0, 0)
local did = LC.MindsAct(m, "tantrum", CurTime())
ok(did and cst.mindErrand ~= nil, "a tantrum: off to the nearest unit", did)
cit:SetPos(unit:GetPos() + Vector(50, 0, 0))
LC.MindsErrandTick(CurTime())
ok(cst.state == "event" and cit.gestured == nil, "there, they wait for someone to see it", cst.state)
lookAt(cit:GetPos() + Vector(0, 0, 48))
LC.StageTick(CurTime())
LC.StageTick(CurTime() + 2)
ok(cst.state == "detained" and cit.gestured == 41, "a player looking: they shake a fist in his face, and are stopped", cst.state)
ok(not has(ply.chat, "**"), "and nothing about it in chat: it was seen (house rule 10)", ply.chat[1])
LC.ArrestNPC = arrest
-- a brutal unit: the stick where a player can see it, and nothing in chat
cst.state = "idle"
cit:SetPos(S0) unit:SetPos(S0 + Vector(60, 0, 0))
ust.state, ust.subject, ust.questLock, ust.mindErrand = "idle", nil, nil, nil
if not unit.lcProfile then LC.AttachProfile(unit, ust, LC.NewPerson("cop")) end
local mu = LC.MindOf(unit.lcProfile)
LC.Psy.State(mu)
local hp = cit:Health()
did = LC.MindsAct(mu, "brutal", CurTime())
LC.MindsErrandTick(CurTime())
ok(cit:Health() == hp and cst.state == "event", "a brutal unit walks up; the beating waits for someone to see it", cst.state)
lookAt(cit:GetPos() + Vector(0, 0, 48))
LC.StageTick(CurTime())
LC.StageTick(CurTime() + 2)
ok(cit:Health() < hp and cst.state == "detained" and not has(ply.chat, "**"), "seen: the blow lands, and nothing in chat", cit:Health())
cit:Remove() unit:Remove()
ply:SetPos(Vector(-190000, 190000, 0))
_walls = savedWalls
end
SeenMomentTests()

function QuietCrowdTests()
section("21 November: a quiet crowd under the Combine's eye: a look, not a chat; a glance, not \"Excuse me\"")
local Q0 = Vector(160000, -128000, 0)
local a, ast = LC.SpawnCitizen(Q0)
local b, bst = LC.SpawnCitizen(Q0 + Vector(100, 0, 0))
for _, s in ipairs({ ast, bst }) do s.state, s.untilT, s.test, s.leaveAt, s.nextChat = "idle", CurTime() + 9999, nil, nil, 0 end
a.sim, b.sim = false, false
local function said(from, what) for i = from + 1, #_sounds do if string.find(_sounds[i], what or "vo/npc/", 1, true) then return true end end return false end
-- out of the Combine's sight two citizens still chat
local s0 = #_sounds
LC.TryChat(a, ast, CurTime())
ok(said(s0, "question"), "out of the Combine's sight, two citizens still talk")
-- a unit near: not a word; they look at him
local unit = LC.SpawnCop(Q0 + Vector(400, 200, 0))
unit.sim = false
s0 = #_sounds
a.lcLook = nil
LC.TryChat(a, ast, CurTime())
ok(not said(s0), "a unit within sight: not a word")
local want = (unit:GetPos() - a:GetPos()):Angle().y
ok(a.lcLook and a.lcLook.what == "unit" and math.abs(((a.yaw or 0) - want + 180) % 360 - 180) < 1, "they turn to look at the unit instead (Valve's cit_lookatcops)", a.lcLook and a.lcLook.what)
-- a player close by: it's the player they look at
local ply = newPlayer("Passerby", "citizen")
ply:SetPos(Q0 + Vector(-200, 0, 0))
LC.TryChat(a, ast, CurTime())
ok(a.lcLook.what == "player", "with a player close by, they look at the player (Valve's LookAtPlayer)")
unit:Remove()
ply:SetPos(Vector(-190000, 190000, 0))
-- by a city screen: they watch the screen
local scr = LC.AddPoint(Q0 + Vector(0, 600, 0), 0, "screen", 0)
s0 = #_sounds
LC.TryChat(a, ast, CurTime())
ok(not said(s0) and a.lcLook.what == "screen", "by a city screen: they watch it, quietly (Valve's lookatbreencast)")
LC.RemovePoint(scr)
-- in the ration line: quiet
ast.state = "inline"
s0 = #_sounds
LC.TryChat(a, ast, CurTime())
ok(not said(s0), "in the ration line: quiet")
ast.state = "idle"
-- a player brushing past: a glance, never "Excuse me"
ply:SetPos(a:GetPos() + Vector(-50, 0, 0))
ply.vel = Vector(200, 0, 0)
ast.nextBark, a.lcLook = 0, nil
s0 = #_sounds
LC.BarkPass(CurTime() + 1)
ok(not said(s0) and a.lcLook and a.lcLook.what == "player", "a player brushing past gets a glance, never \"Excuse me\"")
ply.vel = nil
-- pressing E still greets you
ast.nextUse, ast.state = 0, "idle"
s0 = #_sounds
hook.Run("PlayerUse", ply, a)
ok(said(s0, "/hi0") or said(s0, "/excuseme0"), "pressing E on them still gets a hello")
ply:SetPos(Vector(-190000, 190000, 0))
a:Remove() b:Remove()
end
QuietCrowdTests()

function AutoSpotTests()
section("21 November: the city finds idle spots by itself: couches, chairs, beds, windows under a roof, walls not of glass; sparingly")
local A0 = Vector(164000, -116000, 0)
local savedWalls, graphWas, staticWas, chanceWas, traceWas, czWas = _walls, LC.NavGraph, LC.StaticRest, LC.AUTO_CHANCE, util.TraceLine, LC.CombineZoneAt
_walls = {}
LC.AUTO_CHANCE = { couch = 1, bedside = 1, drinker = 1, window = 1, armscrossed = 1 } -- (every one found is a spot, so the caps can be seen)
LC.StaticRest = {}
local nodes, props, made = {}, {}, {}
local function node(x, y) nodes[#nodes + 1] = { pos = A0 + Vector(x, y, 0), adj = {}, comp = 1 } end
local function prop(model, x, y, yaw, mins, maxs)
    local e = ents.Create("prop_physics")
    e:SetModel(model) e:SetPos(A0 + Vector(x, y, 0)) e:SetAngles(Angle(0, yaw or 0, 0))
    e.obbmin, e.obbmax = mins, maxs
    props[#props + 1] = e
    return e
end
local function wall(x1, y1, x2, y2, glass) _walls[#_walls + 1] = { a = A0 + Vector(x1, y1, 0), b = A0 + Vector(x2, y2, 0), glass = glass } end
-- the world: a roof over the first part of it (sky beyond x 2100), and glass where a wall says so
local function onGlass(p)
    for _, w in ipairs(_walls) do
        if w.glass and math.abs(p.x - w.a.x) < 1 and p.y >= math.min(w.a.y, w.b.y) - 1 and p.y <= math.max(w.a.y, w.b.y) + 1 then return true end
    end
    return false
end
util.TraceLine = function(t)
    if t.endpos.z > t.start.z + 100 and math.abs(t.endpos.x - t.start.x) < 1 and math.abs(t.endpos.y - t.start.y) < 1 then -- straight up
        if t.start.x < A0.x + 2100 then return { Hit = true, HitSky = false, HitPos = t.start + Vector(0, 0, 120), Fraction = 0.25 } end
        return { Hit = true, HitSky = true, HitPos = t.endpos, Fraction = 0.9 }
    end
    local tr = traceWas(t)
    if tr.Hit and t.endpos.z >= t.start.z - 100 then tr.HitTexture = onGlass(tr.HitPos) and "GLASS/WINDOW001A" or "CONCRETE/CONCRETEWALL001A" end
    return tr
end
-- a couch with its back to a wall, a chair, a bed, a window under the roof, a window under the sky
local couch = prop("models/props_c17/furniturecouch001a.mdl", 0, 0, 0, Vector(-16, -40, 0), Vector(16, 40, 30))
wall(-20, -60, -20, 60) node(100, 0)
local chair = prop("models/props_c17/chair02a.mdl", 600, 0, 0) node(700, 0)
local bed = prop("models/props_c17/furniturebed001a.mdl", 1200, 0, 0) node(1300, 0)
wall(1900, -100, 1900, 100, true) node(1800, 0)
wall(2500, -100, 2500, 100, true) node(2400, 0)
-- a plain wall, and a glass one, under the sky (somewhere to stand, and not)
wall(3060, -100, 3060, 100) node(3000, 0)
wall(3660, -100, 3660, 100, true) node(3600, 0)
-- a couch where the editor already placed a spot, and one in a Combine-only zone
prop("models/props_c17/furniturecouch001a.mdl", 4200, 0, 0) node(4300, 0)
made[#made + 1] = LC.AddPoint(A0 + Vector(4220, 0, 0), 0, "sitchair", 0)
prop("models/props_c17/furniturecouch001a.mdl", 4800, 0, 0) node(4900, 0)
LC.CombineZoneAt = function(p) if p.x > A0.x + 4700 and p.x < A0.x + 5000 then return { kind = "combine" } end return czWas and czWas(p) end
-- a crowded room: three couches, two chairs and a bed in one area
for i = 0, 2 do prop("models/props_c17/furniturecouch001a.mdl", 6050 + i * 100, 0, 0) end
prop("models/props_c17/chair02a.mdl", 6050, 150, 0) prop("models/props_c17/chair02a.mdl", 6250, 150, 0)
prop("models/props_c17/furniturebed001a.mdl", 6400, 150, 0)
node(6150, 80) node(6350, 80)
-- one of the map's own static props
LC.StaticRest = { { kind = "couch", pos = A0 + Vector(7200, 0, 0), ang = Angle(0, 90, 0), model = "models/props_interiors/sofa01.mdl" } }
node(7300, 0)
-- a couch in the infestation (the owner: no citizen lounging on a couch in there)
prop("models/props_c17/furniturecouch001a.mdl", 8400, 0, 0) node(8500, 0)
local infest = LC.AddZone(A0 + Vector(8400, 0, 0), 300, "infest", 0)
LC.NavGraph = { nodes = nodes, main = 1, links = 0 }
LC.NavGraphReady()
LC.AutoSpotsScan(true)
local function spotsNear(x, y, r, kind)
    local out = {}
    for k, list in pairs(LC.AutoSpots.byKind) do
        for _, p in ipairs(list) do
            if (not kind or k == kind) and p.pos:Distance(A0 + Vector(x, y, 0)) < r then out[#out + 1] = p end
        end
    end
    return out
end
local cs = spotsNear(0, 0, 60, "couch")[1]
ok(cs and cs.pos.x > couch:GetPos().x and math.abs(((cs.yaw or 0) + 180) % 360 - 180) < 1, "a couch: a spot in front of it, facing out, away from the wall behind it", cs and tostring(cs.pos))
ok(spotsNear(600, 0, 60, "drinker")[1] ~= nil, "a chair: a drinker's seat")
ok(spotsNear(1200, 0, 60, "bedside")[1] ~= nil, "a bed: a spot on its edge")
local ws = spotsNear(1878, 0, 10, "window")[1]
ok(ws and math.abs(((ws.yaw or 0) + 180) % 360 - 180) < 1, "glass in a wall by a walking node, under a roof: someone can stand there looking out", ws and tostring(ws.pos))
ok(#spotsNear(2478, 0, 60, "window") == 0, "the same under the open sky: no")
local as = spotsNear(3040, 0, 10, "armscrossed")[1]
ok(as and math.abs(math.abs(((as.yaw or 0) + 180) % 360 - 180) - 180) < 1, "a solid wall by a path: someone stands against it, arms crossed, looking at the path", as and tostring(as.yaw))
ok(#spotsNear(3640, 0, 60, "armscrossed") == 0, "never against glass")
ok(#spotsNear(4200, 0, 100) == 0, "never where the editor already placed a spot")
ok(#spotsNear(4800, 0, 100) == 0, "never in a Combine-only zone")
local crowd = spotsNear(6200, 75, 260)
local kinds = {}
for _, p in ipairs(crowd) do kinds[p.kind] = (kinds[p.kind] or 0) + 1 end
ok(#crowd == 2 and kinds.couch == 1 and kinds.bedside == 1, "a room full of furniture: two spots at most, one of a kind (a room never fills with posers)", #crowd)
ok(spotsNear(7200, 0, 60, "couch")[1] ~= nil, "the map's own static props count too")
ok(infest ~= nil and LC.InfestZoneAt(A0 + Vector(8400, 0, 0)) ~= nil and #spotsNear(8400, 0, 100) == 0, "never in the infestation")
-- citizens are offered them with the placed spots, and use Valve's poses there
local offered = {}
for _, p in ipairs(LC.FreePoints(LC.SITTABLE, nil)) do offered[p] = true end
ok(offered[cs] and offered[ws] and offered[as], "citizens are offered them along with the placed spots")
local cit, cst = LC.SpawnCitizen(A0 + Vector(100, 0, 0))
cit.seqs, cit.sim, cst.test = { sitcouch1 = 1 }, false, nil
ok(LC.StartBusy(cit, cst, cs) and cst.ss and cst.ss.kv.m_iszPostIdle == "sitcouch1", "and sit there in Valve's couch pose")
LC.EndBusy(cit, cst, false)
cit:Remove()
-- never Civil Protection or the Overwatch: not these, not the placed ones (the owner, 21 November)
local hand = LC.AddPoint(A0 + Vector(0, 300, 0), 0, "window", 0)
made[#made + 1] = hand
local cop, copst = LC.SpawnCop(A0 + Vector(100, 300, 0))
copst = copst or LC.NPCs[cop]
cop.seqs, cop.sim = { sitcouch1 = 1, d1_t03_Tenements_Look_Out_Window_Idle = 2 }, false
local unitOffered = false
for _, p in ipairs(LC.FreePoints(LC.SITTABLE, cop)) do if LC.IDLE_POSES[p.kind] or p.auto then unitOffered = true end end
ok(not unitOffered and not LC.StartBusy(cop, copst, cs) and not LC.StartBusy(cop, copst, hand) and copst.state ~= "busy",
    "a Civil Protection unit is never offered them, found or placed, nor sat down in one")
local cit2, cst2 = LC.SpawnCitizen(A0 + Vector(-100, 300, 0))
cst2.test = nil
local citOffered = false
for _, p in ipairs(LC.FreePoints(LC.SITTABLE, cit2)) do if p == hand then citOffered = true end end
ok(citOffered, "(a citizen is)")
cop:Remove() cit2:Remove()
-- looked for again: the same spot (whoever sits there keeps it); a chair moved off is no seat until found again
LC.AutoSpotsScan(true)
ok(spotsNear(0, 0, 60, "couch")[1] == cs, "looked for again, a spot found again is the same one")
local ds = spotsNear(600, 0, 60, "drinker")[1]
chair:SetPos(chair:GetPos() + Vector(0, 120, 0))
offered = {}
for _, p in ipairs(LC.FreePoints({ drinker = true }, nil)) do offered[p] = true end
ok(ds and not offered[ds], "a chair someone has moved is no seat until it is found again")
-- sparing in the real city: only some of them, the same ones each time
LC.AUTO_CHANCE = chanceWas
LC.AutoSpotsScan(true)
local some = 0
for _, list in pairs(LC.AutoSpots.byKind) do some = some + #list end
LC.AutoSpotsScan(true)
local again = 0
for _, list in pairs(LC.AutoSpots.byKind) do again = again + #list end
ok(some < 12 and some == again, "with the real chances only some are spots, and the same ones every time", some)
for _, e in ipairs(props) do e:Remove() end
for _, p in ipairs(made) do LC.RemovePoint(p) end
if infest then LC.RemoveZone(infest) end
util.TraceLine, LC.CombineZoneAt, LC.StaticRest, _walls = traceWas, czWas, staticWas, savedWalls
LC.NavGraph = graphWas
LC.NavGraphReady()
LC.AutoSpots.byKind, LC.AutoSpots.byKey, LC.AutoSpots.job = {}, {}, nil
end
AutoSpotTests()

----------------------------------------------------------------------
-- 21 November: Valve's ways with the Combine (docs/dev/valve-npc-notes.md, section 5): a unit at
-- each Combine door, guards at ease, the raid's breach, squads in lanes, the Combine at work. Each unit
-- notes the scripted sequences made (made, played) and the sounds since a point (heard).

function Nov21_DoorPostTests()
    section("21 November: a unit at each Combine door (Valve's police posts)")
    local runWas, seenWas = LC.Running, LC.IsSeen
    LC.Running = true
    LC.IsSeen = function() return false end
    _setcvar("lc_garrison", 6)
    local made = {}
    hook.Add("OnEntityCreated", "Nov21DoorSeqs", function(e) if e.cls == "scripted_sequence" then made[#made + 1] = e end end)
    local function played(npc, name) for _, e in ipairs(made) do if e.kv.m_iszEntity == npc:GetName() and (e.kv.m_iszPlay == name or e.kv.m_iszPostIdle == name) then return e end end end
    local function heard(from, name) for i = from + 1, #_sounds do if string.find(_sounds[i], name, 1, true) then return true end end return false end
    local Z0 = Vector(-310000, 120000, 0)
    local z = LC.AddZone(Z0, 300, "combine", 0)
    local door = ents.Create("prop_door_rotating") door:SetPos(Z0 + Vector(300, 0, 0))
    local inner = ents.Create("prop_door_rotating") inner:SetPos(Z0 + Vector(0, 100, 0))
    local posts = LC.CombineDoorPosts(z)
    ok(#posts == 1 and posts[1].door == door, "the door into the zone is found; a door inside it is not a way in", #posts)
    local p = posts[1] or { pos = Z0, doorPos = Z0, out = Vector(1, 0, 0) }
    local out = p.pos:Distance(p.doorPos)
    ok(not LCZ.Contains(z, p.pos, 0) and out >= 32 and out <= 64, "his post is just outside the door (Valve: 32 to 64)", out)
    local t0 = CurTime()
    for i = 1, 6 do LC.GarrisonTick(t0 + i * 3) end
    local cop, cst
    for npc, gz in pairs(LC.Garrison) do local s = LC.NPCs[npc] if gz == z and s and s.doorPost then cop, cst = npc, s end end
    ok(cop ~= nil and cst.role == "cop", "one of the zone's own metrocops takes the door")
    if cop then
        cop.seqs = { plazahalt = 1, harassfront1 = 2, pushplayer = 3, swing = 4, plazalean = 5, Crouch_idle_pistol = 6, harrassidle = 7, batonidle1 = 8, busyidle1 = 9 }
        for npc, gz in pairs(LC.Garrison) do if gz == z and npc ~= cop then LC.NPCs[npc] = nil npc:Remove() end end -- (the door's man alone)
        cst.untilT = 0
        _run(6)
        ok(cst.state == "post" and cop:GetPos():Distance(p.pos) <= 128, "he goes to his post and holds it, within 128 of it", tostring(cst.state) .. " " .. math.floor(cop:GetPos():Distance(p.pos)))
        local sc = ents.Create("npc_cscanner") sc:SetPos(p.pos + Vector(400, 0, 150))
        local sst = LC.RegisterNPC(sc, "scanner")
        local tr = newPlayer("DoorTrespasser", "citizen")
        _run(0.5)
        -- deeper in than his reach: the countdown, and a unit who sees them calls out (no chat line)
        tr:SetPos(Z0 + Vector(-150, 0, 0))
        local s0 = #_sounds
        LC.CombineZoneTick(CurTime())
        ok(tr:GetNW2Float("lc_trespass_until", 0) > CurTime() and heard(s0, "holdit") and not has(tr.chat, "restricted"), "deeper in than the door's reach: the countdown as before, and a unit calls out instead of a chat line")
        -- at the door: three warnings, each setting something off
        local function Until(fn, most) local t = 0 while not fn() and t < most do _run(0.1) t = t + 0.1 end return fn() end
        tr:SetPos(p.pos + Vector(80, 0, 0))
        s0 = #_sounds
        ok(Until(function() return heard(s0, "firstwarningmove") end, 3), "someone at the door: the first warning, in his own voice")
        -- (the nearest: a scanner an earlier test in the shard left nearer the door may be the one that comes)
        local anyScanner = sst.followEnt == tr
        for _, s9 in pairs(LC.NPCs) do if s9.role == "scanner" and s9.followEnt == tr then anyScanner = true end end
        ok(anyScanner, "and the nearest scanner comes to photograph them")
        LC.CombineZoneTick(CurTime())
        ok(tr:GetNW2Float("lc_trespass_until", 0) == 0, "(out of the zone: the countdown is gone)")
        s0 = #_sounds
        ok(Until(function() return heard(s0, "secondwarning") end, 3.5) and played(cop, "plazahalt") ~= nil, "the second: he raises his hand at the door (Plazahalt)")
        ok(has(sc.fired or {}, "InspectTargetPhoto"), "the scanner takes the photograph")
        s0 = #_sounds
        tr.pushed = nil
        ok(Until(function() return heard(s0, "finalwarning") end, 3.5) and played(cop, "pushplayer") ~= nil and tr.pushed ~= nil and tr.pushed.x > 0, "the third: he shoves them back, away from the door")
        ok(not LC.PlayerIsWanted(tr), "warned at the door, nobody is wanted")
        -- past him: beaten down, never to death, and they come to outside
        tr:SetHealth(30)
        tr:SetPos(Z0 + Vector(150, 0, 0))
        s0 = #_sounds
        Until(function() return (tr.lcPostKOBusy or 0) > CurTime() end, 3)
        _run(0.5)
        LC.CombineZoneTick(CurTime())
        ok(tr:GetNW2Float("lc_trespass_until", 0) == 0 and LC.PostCovers(tr, CurTime()), "past him and in his reach: no countdown, he deals with it")
        _run(2.5)
        ok(heard(s0, "stunstick_fleshhit") and tr:Health() >= 25 and tr:Health() < 30, "beaten with the stick, never below 25 health", tr:Health())
        ok(not LCZ.Contains(z, tr:GetPos(), 0) and tr:GetPos():Distance(p.pos) < 120, "and they come to outside the door", tostring(tr:GetPos()))
        ok(not LC.PlayerIsWanted(tr), "the first time costs no more than that")
        _run(1)
        tr:SetPos(Z0 + Vector(150, 0, 0))
        _run(3)
        ok(LC.PlayerIsWanted(tr), "through again within five minutes: wanted for trespassing")
        LC.ClearWanted(tr)
        if LC.CalmCops then LC.CalmCops(tr) end
        tr:SetPos(Vector(0, -500, 0))
        tr:SetHealth(100)
        LC.NPCs[sc] = nil sc:Remove()
    end
    hook.Remove("OnEntityCreated", "Nov21DoorSeqs")
    LC.RemoveZone(z)
    for npc, gz in pairs(LC.Garrison) do if gz == z then LC.Garrison[npc] = nil LC.NPCs[npc] = nil if IsValid(npc) then npc:Remove() end end end
    door:Remove() inner:Remove()
    _setcvar("lc_garrison", 0)
    LC.IsSeen, LC.Running = seenWas, runWas
end
Nov21_DoorPostTests()

function Nov21_GuardsAtEaseTests()
    section("21 November: guards at ease until something brings them up; more posts than men")
    local runWas, seenWas = LC.Running, LC.IsSeen
    LC.Running = true
    LC.IsSeen = function() return false end
    local made = {}
    hook.Add("OnEntityCreated", "Nov21EaseSeqs", function(e) if e.cls == "scripted_sequence" then made[#made + 1] = e end end)
    local function played(npc, name) for _, e in ipairs(made) do if e.kv.m_iszEntity == npc:GetName() and (e.kv.m_iszPlay == name or e.kv.m_iszPostIdle == name) then return e end end end
    local G0 = Vector(-330000, 120000, 0)
    local cop, cst = LC.Spawners.cop(G0)
    cst.unmanaged, cst.routeGroup = true, nil
    cop.seqs = { plazalean = 1, Crouch_idle_pistol = 2, harrassidle = 3, batonidle1 = 4, busyidle1 = 5 }
    LC.SetState(cop, cst, "idle") cst.untilT = CurTime() + 999 cst.nextInspect = CurTime() + 999
    local wall = { a = G0 + Vector(-30, -100, 0), b = G0 + Vector(-30, 100, 0) }
    table.insert(_walls, wall)
    ok(LC.RelaxAtPost(cop, cst, 0, CurTime()) and played(cop, "plazalean") ~= nil, "a wall behind him: he leans on it (Plazalean)")
    for i = #_walls, 1, -1 do if _walls[i] == wall then table.remove(_walls, i) end end
    LC.RelaxEnd(cop, cst)
    ok(LC.RelaxAtPost(cop, cst, 0, CurTime()) and LC.AtEase[cop] and LC.AtEase[cop].name ~= "plazalean", "in the open: he crouches, or rests his baton", LC.AtEase[cop] and LC.AtEase[cop].name)
    local alarms = {}
    hook.Add("LivingCityGuardAlarmed", "Nov21Ease", function(npc, why) if npc == cop then alarms[#alarms + 1] = why end end)
    local walker = newPlayer("EaseWalker", "citizen")
    walker:SetPos(G0 + Vector(600, 0, 0))
    _run(1)
    ok(LC.AtEase[cop] ~= nil, "someone walking by a way off doesn't bring him up")
    walker:SetPos(G0 + Vector(180, 0, 0))
    _run(0.6)
    ok(LC.AtEase[cop] == nil and alarms[#alarms] == "heard" and (cst.alertUntil or 0) > CurTime(), "someone close: he comes up, and stays alert a while")
    ok(not LC.RelaxAtPost(cop, cst, 0, CurTime()), "(and doesn't settle again while alert)")
    cst.alertUntil = 0
    walker:SetPos(G0 + Vector(600, 0, 0))
    walker.vel = Vector(300, 0, 0)
    LC.RelaxAtPost(cop, cst, 0, CurTime())
    _run(0.6)
    ok(LC.AtEase[cop] == nil and alarms[#alarms] == "heard", "someone running, further off: up")
    walker.vel = nil
    walker:SetPos(Vector(0, -500, 0))
    cst.alertUntil = 0
    LC.RelaxAtPost(cop, cst, 0, CurTime())
    local shooter = ents.Create("npc_combine_s") shooter:SetPos(G0 + Vector(1000, 0, 0))
    hook.GetTable().EntityFireBullets.LivingCityGuardsHear(shooter, {})
    _run(0.6)
    ok(LC.AtEase[cop] == nil and alarms[#alarms] == "gunfire", "a shot: up")
    shooter:Remove()
    cst.alertUntil = 0
    LC.RelaxAtPost(cop, cst, 0, CurTime())
    hook.GetTable().EntityTakeDamage.LivingCityGuardsHurt(cop, _dmg(nil, 1))
    ok(LC.AtEase[cop] == nil and alarms[#alarms] == "hurt", "hurt: up at once")
    cst.alertUntil = 0
    local d = ents.Create("prop_door_rotating") d:SetPos(G0 + Vector(0, 200, 0))
    _run(1.5) -- (the shot is past)
    cst.alertUntil = 0
    LC.RelaxAtPost(cop, cst, 0, CurTime())
    _run(0.6)
    ok(LC.AtEase[cop] ~= nil, "(a shut door near him: at ease)")
    d:Fire("Open")
    _run(0.6)
    ok(LC.AtEase[cop] == nil and alarms[#alarms] == "door", "the door opens: up")
    d:Remove()
    hook.Remove("LivingCityGuardAlarmed", "Nov21Ease")
    -- the garrison's posts: 1.5 to 2 for each man, shared out
    _setcvar("lc_garrison", 6)
    local gz = LC.AddZone(G0 + Vector(0, 4000, 0), 900, "combine", 0)
    local size = LC.GarrisonSize(gz)
    local posts = LC.GarrisonPosts(gz)
    ok(size > 0 and #posts >= math.ceil(size * 1.5) and #posts <= math.ceil(size * 2), "more posts than men: 1.5 to 2 for each unit", #posts .. " for " .. size)
    local u1, s1 = LC.Spawners.cop(G0 + Vector(0, 4000, 0))
    local u2, s2 = LC.Spawners.cop(G0 + Vector(50, 4000, 0))
    s1.guardZone, s2.guardZone = gz, gz
    local a, b = LC.GarrisonPost(u1, s1), LC.GarrisonPost(u2, s2)
    ok(a and b and a ~= b, "two units never share a post")
    local a2 = LC.GarrisonPost(u1, s1)
    ok(a2 and a2 ~= a and a2 ~= b, "one moving on takes another free post, not the one he had")
    u1.seqs = { Crouch_idle_pistol = 1 }
    LC.ArriveHandlers.guardpost(u1, s1, CurTime(), a2)
    ok(LC.AtEase[u1] ~= nil and s1.untilT > CurTime() + 15, "at his post he is at ease, a while, then moves on")
    LC.RelaxEnd(u1, s1)
    LC.ArriveHandlers.checkpoint(u1, s1, CurTime(), { yaw = 90 })
    ok(LC.AtEase[u1] ~= nil, "at a checkpoint too")
    LC.RemoveZone(gz)
    for npc, z2 in pairs(LC.Garrison) do if z2 == gz then LC.Garrison[npc] = nil LC.NPCs[npc] = nil if IsValid(npc) then npc:Remove() end end end
    _setcvar("lc_garrison", 0)
    for _, u in ipairs({ cop, u1, u2 }) do LC.RelaxEnd(u, LC.NPCs[u]) LC.NPCs[u] = nil u:Remove() end
    hook.Remove("OnEntityCreated", "Nov21EaseSeqs")
    LC.IsSeen, LC.Running = seenWas, runWas
end
Nov21_GuardsAtEaseTests()

function Nov21_RaidBreachTests()
    section("21 November: a block raid comes in the way Valve's does (the knock, the kick, the run, the beating heard)")
    local runWas, seenWas = LC.Running, LC.IsSeen
    LC.Running = true
    LC.IsSeen = function() return false end
    if LC.Raid then LC.EndRaid() end
    local made = {}
    hook.Add("OnEntityCreated", "Nov21RaidSeqs", function(e) if e.cls == "scripted_sequence" then made[#made + 1] = e end end)
    local function played(npc, name) for _, e in ipairs(made) do if e.kv.m_iszEntity == npc:GetName() and (e.kv.m_iszPlay == name or e.kv.m_iszPostIdle == name) then return e end end end
    local B0 = Vector(-350000, 120000, 0)
    local bz = LC.AddZone(B0, 450, "block", 77)
    local door = ents.Create("prop_door_rotating") door:SetPos(B0 + Vector(200, 0, 0))
    local cit, ist = LC.Spawners.citizen(B0 + Vector(-100, 50, 0))
    cit.seqs = { cower_Idle = 1 }
    LC.SetState(cit, ist, "idle") ist.untilT = CurTime() + 9999
    local unitsWas = GetConVar("lc_raid_units"):GetInt()
    _setcvar("lc_raid_units", 3)
    ok(LC.StartRaid(77), "a raid on the block")
    local raid = LC.Raid or { units = {} }
    local b = raid.breach
    ok(b and b.door == door and IsValid(b.kicker) and IsValid(b.knocker) and b.kicker ~= b.knocker, "two of the team take the block's door: one to kick it, one to knock")
    local lanes, ends = 0, {}
    for _, u in ipairs(raid.units) do local s = LC.NPCs[u] if s and s.lane then lanes = lanes + 1 ends[#ends + 1] = s.lane.target end end
    local apart = #ends >= 2
    for i = 1, #ends do for j = i + 1, #ends do if ends[i]:Distance(ends[j]) < 40 then apart = false end end end
    ok(lanes == #raid.units and lanes > 0 and apart, "each man moves up in his own lane, to his own spot", lanes)
    if b then
        b.kicker.seqs = { adooridle = 1, adoorkick = 2 }
        b.knocker.seqs = { adoorknock = 1, adoorenter = 2 }
        local waited = 0
        while not b.opened and waited < 60 do _run(1) waited = waited + 1 end
        ok(b.opened ~= nil, "the door is broken in", waited)
        ok(has(door.fired or {}, "Unlock") and has(door.fired or {}, "OpenAwayFrom"), "it opens on the kick itself, away from the boot")
        ok(played(b.knocker, "adoorknock") ~= nil and played(b.kicker, "adoorkick") ~= nil and played(b.kicker, "adooridle") ~= nil, "one knocks while the other kicks (Valve's adoorknock, adooridle and adoorkick)")
        local run = false
        for _, e in ipairs(made) do if e.kv.m_iszEntity == cit:GetName() and e.kv.m_iszPostIdle == "cower_Idle" and e.kv.m_fMoveTo == "2" then run = true end end
        ok(ist.state == "event" and run, "the resident runs for the far side of the block and cowers there")
        local before = #_sounds
        _run(10.5)
        local blows = 0
        for i = before + 1, #_sounds do
            local snd = _sounds[i]
            if string.find(snd, "stunstick_fleshhit", 1, true) or string.find(snd, "body_medium_impact_hard", 1, true) or string.find(snd, "male01/pain0", 1, true) then blows = blows + 1 end
        end
        ok(blows >= 6 and blows <= 40, "the beating is heard, not seen: a blow every 0.4 to 1.5 s for 6 to 8 s", blows)
        ok(played(b.knocker, "adoorenter") ~= nil, "the knocker goes in (adoorenter)")
        ok(b.phase == "done", "and the team goes on to the stops")
    end
    if LC.Raid then LC.EndRaid() end
    _setcvar("lc_raid_units", unitsWas)
    LC.RemoveZone(bz)
    door:Remove()
    LC.NPCs[cit] = nil cit:Remove()
    for _, u in ipairs(raid.units) do LC.NPCs[u] = nil if IsValid(u) then u:Remove() end end
    hook.Remove("OnEntityCreated", "Nov21RaidSeqs")
    LC.IsSeen, LC.Running = seenWas, runWas
end
Nov21_RaidBreachTests()

function Nov21_LaneTests()
    section("21 November: squads move in lanes, in bounds of 450 to 1000")
    local runWas, seenWas = LC.Running, LC.IsSeen
    LC.Running = true
    LC.IsSeen = function() return false end
    local L0 = Vector(-370000, 120000, 0)
    local to = L0 + Vector(3000, 0, 0)
    local spots = LC.LaneSpots(to, L0, 3)
    ok(#spots == 3 and math.abs(spots[1]:Distance(spots[2]) - 130) < 1 and math.abs(spots[2]:Distance(spots[3]) - 130) < 1, "each man his own spot, 130 apart (Valve's lanes)")
    ok(math.abs(spots[1].x - to.x) < 1 and math.abs(spots[3].x - to.x) < 1, "across the way, not along it")
    local bounds = LC.LaneBounds(L0, to, "cop")
    local short, prev = true, L0
    for _, q in ipairs(bounds) do if prev:Distance(q) > 1001 then short = false end prev = q end
    ok(#bounds >= 3 and short and bounds[#bounds] == to, "a long move goes in bounds of at most 1000", #bounds)
    local units, arrived = {}, {}
    for i = 1, 3 do
        local u, s = LC.Spawners.cop(L0 + Vector(0, (i - 2) * 40, 0))
        s.unmanaged, s.routeGroup, s.nextInspect = true, nil, CurTime() + 999
        units[i] = u
    end
    local pauses = {}
    local hop = LC.ArriveHandlers.lanehop
    LC.ArriveHandlers.lanehop = function(npc, st, now, poi) local r = hop(npc, st, now, poi) pauses[#pauses + 1] = { st.untilT - now, poi.last } return r end
    ok(LC.LaneMove(units, L0 + Vector(1600, 0, 0), { run = true, done = function(npc) arrived[npc] = npc:GetPos() end }) == 3, "three sent")
    local targets = {}
    for i, u in ipairs(units) do targets[i] = LC.NPCs[u].lane.target end
    _run(30)
    LC.ArriveHandlers.lanehop = hop
    local there = 0
    for i, u in ipairs(units) do if arrived[u] and arrived[u]:Distance(targets[i]) < 48 then there = there + 1 end end
    ok(there == 3, "each gets to his own spot", there)
    local mids, inRange = 0, true
    for _, ps in ipairs(pauses) do if not ps[2] then mids = mids + 1 if ps[1] < 0 or ps[1] > 3 then inRange = false end end end
    ok(mids >= 3 and inRange, "with a pause of 0 to 3 s at each bound on the way", mids)
    for _, u in ipairs(units) do LC.NPCs[u] = nil u:Remove() end
    -- a reaction squad sent to a place, not after anyone: lanes too
    if LC.QRFDeploy and LC.Spawners.soldier then
        local q = LC.QRFDeploy(L0, 2, L0 + Vector(2000, 0, 0), nil, "soldier", 4)
        local qs = q and LC.NPCs[q]
        ok(qs and qs.lane and qs.lane.target:Distance(L0 + Vector(2000, 0, 0)) > 20 and qs.lane.target:Distance(L0 + Vector(2000, 0, 0)) < 200, "a reaction squad sent to a place goes in lanes too")
        if q then LC.QRF[q] = nil LC.NPCs[q] = nil q:Remove() end
    end
    LC.IsSeen, LC.Running = seenWas, runWas
end
Nov21_LaneTests()

function Nov21_CombineActsTests()
    section("21 November: Valve's Combine at work (two at a wall, the punch, pick up that can)")
    local runWas, seenWas = LC.Running, LC.IsSeen
    LC.Running = true
    LC.IsSeen = function() return false end
    local made = {}
    hook.Add("OnEntityCreated", "Nov21ActsSeqs", function(e) if e.cls == "scripted_sequence" then made[#made + 1] = e end end)
    local function played(npc, name) for _, e in ipairs(made) do if e.kv.m_iszEntity == npc:GetName() and (e.kv.m_iszPlay == name or e.kv.m_iszPostIdle == name) then return e end end end
    local function heard(from, name) for i = from + 1, #_sounds do if string.find(_sounds[i], name, 1, true) then return true end end return false end
    local A0 = Vector(-390000, 120000, 0)
    local watcher = newPlayer("ActsWatcher", "citizen") -- (someone about: the units there think at their full pace)
    _run(0.5)
    watcher:SetPos(A0 + Vector(0, -400, 0))
    local wall = { a = A0 + Vector(-300, 100, 0), b = A0 + Vector(300, 100, 0) }
    table.insert(_walls, wall)
    local cop, cst = LC.Spawners.cop(A0 + Vector(0, -150, 0))
    cst.unmanaged, cst.routeGroup = true, nil
    cop.seqs = { Spreadwall = 1, arrestpunch = 2 }
    local c1, i1 = LC.Spawners.citizen(A0 + Vector(-40, 20, 0))
    local c2, i2 = LC.Spawners.citizen(A0 + Vector(60, 30, 0))
    local cw, iw = LC.Spawners.citizen(A0 + Vector(0, 40, 0))
    c1.seqs, c2.seqs = { spreadwallidle = 1 }, { spreadwallidle = 1 }
    for _, c in ipairs({ c1, c2, cw }) do local s = LC.NPCs[c] LC.SetState(c, s, "idle") s.untilT = CurTime() + 999 end
    LC.SetState(cop, cst, "idle") cst.untilT = CurTime() + 999
    ok(LC.WallFriskTry(cop, cst, CurTime(), true), "a unit lines two citizens up against the wall")
    ok(i1.state == "detained" and i2.state == "detained" and iw.state ~= "detained", "the two men (a woman's model has no such pose: left alone)")
    ok(played(c1, "spreadwallidle") ~= nil and played(c2, "spreadwallidle") ~= nil, "hands on the wall (spreadwallidle)")
    local f = cst.frisk or { spots = { A0, A0 }, n = Vector(0, -1, 0), yaw = 0 }
    ok(math.abs(f.spots[1]:Distance(f.spots[2]) - 52) < 1 and math.abs(((f.yaw - 90 + 180) % 360) - 180) < 1, "52 apart, facing the wall, as Valve stands them")
    _run(2)
    local first = played(cop, "Spreadwall")
    ok(cst.state == "wallfrisk" and first and first.pos:Distance(f.spots[1] + f.n * 39) < 1, "he frisks the first from behind (Spreadwall, 39 back)")
    _run(6)
    local second = false
    for _, e in ipairs(made) do if e.kv.m_iszEntity == cop:GetName() and e.kv.m_iszPlay == "Spreadwall" and e.pos:Distance(f.spots[2] + f.n * 39) < 1 then second = true end end
    ok(second, "then the second")
    local s0 = #_sounds
    _run(6)
    ok(i1.state ~= "detained" and i2.state ~= "detained" and cst.state ~= "wallfrisk" and heard(s0, "allrightyoucango"), "and lets them go")
    for i = #_walls, 1, -1 do if _walls[i] == wall then table.remove(_walls, i) end end
    -- the punch before the arrest
    local c3, i3 = LC.Spawners.citizen(A0 + Vector(300, -150, 0))
    c3.seqs = { arrestpunch = 1 }
    local arrested
    LC.SetState(cop, cst, "idle")
    ok(LC.ArrestPunch(cop, cst, c3, i3, CurTime(), function(c, u) arrested = { c, u } return true end, true), "an arrest that starts with a punch")
    ok(played(cop, "arrestpunch") ~= nil and played(c3, "arrestpunch") ~= nil, "both play it (Valve's arrestpunch)")
    ok(cst.state == "event" and i3.state == "detained" and not arrested, "the walk to the cells waits for it")
    _run(3)
    ok(arrested and arrested[1] == c3 and arrested[2] == cop and cst.state ~= "event", "then the arrest itself")
    ok(not LC.ArrestPunch(cop, cst, cw, iw, CurTime(), function() end, true), "a model without the punch: none")
    -- pick up that can: his hand knocks it off; in the bin, a little standing; left there, a beating that never kills
    local canWas = GetConVar("lc_can_event"):GetInt()
    _setcvar("lc_can_event", 1)
    local cop2, cst2 = LC.Spawners.cop(A0 + Vector(0, -900, 0))
    cst2.unmanaged, cst2.routeGroup = true, nil
    cop2.seqs = { itemhit = 1, swing = 2 }
    local bins = LC.StaticBins
    local function StartCanOn(ply)
        LC.SetState(cop2, cst2, "idle") cst2.untilT = CurTime() + 999 cst2.nextInspect = CurTime() + 999
        ply:SetPos(cop2:GetPos() + Vector(120, 0, 0))
        LC.StaticBins = { { pos = cop2:GetPos() + Vector(260, 0, 0), model = "models/props_junk/trashbin01a.mdl" } }
        _advance(31)
        local npcs, ev, r = LC.NPCs, LC.Event, math.random
        LC.NPCs, LC.Event = { [cop2] = cst2 }, nil
        math.random = function(x, y) if x == nil then return 0.01 elseif y == nil then return r(x) end return r(x, y) end
        timer.list.LivingCityEvents.fn()
        math.random = r
        LC.NPCs, LC.Event = npcs, ev
    end
    local tp = newPlayer("CanPasser", "citizen")
    _run(0.5)
    StartCanOn(tp)
    ok(cst2.state == "event" and played(cop2, "itemhit") ~= nil, "pick up that can: his hand knocks it off as he swings (Valve's itemhit)")
    local can
    for _, e in ipairs(ents.FindByClass("prop_physics")) do if e.lcCan and e:GetPos():Distance(cop2:GetPos()) < 120 then can = e end end
    if can then
        hook.GetTable().PhysgunPickup.LivingCityCan(tp, can)
        can:SetPos(LC.StaticBins[1].pos + Vector(0, 0, 10))
        local before = LC.Standing(tp)
        _run(1)
        -- (at least the can's 3: something else of the city's can pay them in the same second, in a busy shard)
        ok(LC.Standing(tp) >= before + 3, "in the bin: a little Civil Standing", LC.Standing(tp) - before)
    else
        ok(false, "(the can was dropped)")
    end
    tp:SetPos(Vector(0, -500, 0))
    local tcan = newPlayer("CanRefuser", "citizen")
    _run(0.5)
    tcan:SetHealth(30)
    StartCanOn(tcan)
    _run(16)
    ok(tcan:Health() >= 25 and tcan:Health() < 30, "left lying there: a beating with the stick that never kills", tcan:Health())
    tcan:SetPos(Vector(0, -500, 0))
    tcan:SetHealth(100)
    LC.StaticBins = bins
    _setcvar("lc_can_event", canWas)
    for _, u in ipairs({ cop, cop2, c1, c2, cw, c3 }) do LC.NPCs[u] = nil if IsValid(u) then u:Remove() end end
    watcher:SetPos(Vector(0, -500, 0))
    hook.Remove("OnEntityCreated", "Nov21ActsSeqs")
    LC.IsSeen, LC.Running = seenWas, runWas
end
Nov21_CombineActsTests()

function BaseTallPoleTests()
-- the owner, 21 November: the silo's flagpole stands on its bottom floor, so tall that the flag flies at eye level on
-- its top floor: an info_target named as a pole's marker with _top added, straight above it, marks the pole's top
section("The Resistance's headquarters: a map's _top marker makes a tall pole (the silo)")
local B = LC.Base
local setupWas = GetConVar("lc_base_setup_time"):GetInt()
_setcvar("lc_base_setup_time", 5)
B.Reset()
local S0 = Vector(-360000, 220000, 0)
local zs = LC.AddZone(nil, nil, "rebel", 0, { mins = S0 + Vector(-600, -600, -16), maxs = S0 + Vector(600, 600, 2000) })
local base = ents.Create("info_target") base:SetName("lc_hq_setup_silotest") base:SetPos(S0 + Vector(0, 0, 8)) base:Spawn()
local top = ents.Create("info_target") top:SetName("lc_hq_setup_silotest_top") top:SetPos(S0 + Vector(6, 0, 1700)) top:Spawn()
local O = S0 + Vector(0, 60000, 0)       -- (a tall pole outside any territory, and a plain marker)
local obase = ents.Create("info_target") obase:SetName("lc_hq_setup_outtest") obase:SetPos(O + Vector(0, 0, 8)) obase:Spawn()
local otop = ents.Create("info_target") otop:SetName("lc_hq_setup_outtest_top") otop:SetPos(O + Vector(-5, 0, 1200)) otop:Spawn()
local P = S0 + Vector(0, 70000, 0)
local plain = ents.Create("info_target") plain:SetName("lc_hq_setup_plaintest") plain:SetPos(P + Vector(0, 0, 8)) plain:Spawn()
B.Poles()
local tall = B.poles[LC.RebelLeader(zs)]
ok(IsValid(tall) and tall:GetPos():DistToSqr(S0) < 4 and tall.lcHigh == 1700 and tall:GetNW2Float("lc_flag_top", 0) == 1700,
    "a _top marker 1700 over its marker makes that territory's pole 1700 tall, standing on the marker's floor (no 330 limit)",
    IsValid(tall) and tall.lcHigh, IsValid(tall) and tostring(tall:GetPos()))
local named, atTop = 0, false
for _, m in ipairs(B.Markers()) do
    if m.ent == top or m.ent == otop then atTop = true end
    if m.ent == base or m.ent == obase or m.ent == plain then named = named + 1 end
end
local outPole, plainPole, extra = nil, nil, 0
for k, e in pairs(B.poles) do
    if IsValid(e) and isstring(k) then
        local p = e:GetPos()
        if p:DistToSqr(O) < 4 then outPole = e elseif p:DistToSqr(P) < 4 then plainPole = e
        elseif (p.x - O.x) ^ 2 + (p.y - O.y) ^ 2 < 400 then extra = extra + 1 end
    end
end
ok(not atTop and named == 3 and IsValid(outPole) and extra == 0 and outPole.lcHigh == 1200,
    "a _top marker is never a spot of its own: one pole at the marker below it, none for the _top (outside a territory too)", named, extra)
ok(IsValid(plainPole) and plainPole.lcHigh == 330 and plainPole:GetModelScale() == 3 and plainPole.lcParts == nil and plainPole:GetNW2Float("lc_flag_top", 0) == 330,
    "a marker without a _top is as before: one pole 330 tall in the open")
local parts, reach, thick = tall.lcParts or {}, 0, tall:GetModelScale()
for _, p in ipairs(parts) do
    reach = math.max(reach, p:GetPos().z + 110 * p:GetModelScale())
    thick = math.max(thick, p:GetModelScale())
end
ok(#parts == 5 and thick <= 3 and math.abs(reach - 1700) < 1 and parts[1].lcSceneProp == "baseflag",
    "the tall pole is a stack of six pieces each about a pole in the open (as thick, not 15 times), reaching the top", #parts, thick, reach)
-- raised from its foot like any pole: E at it, the same rules; at the top the flag flies at the _top marker
local boss = newPlayer("SiloCommander", "resistance", nil, 99999)
boss:SetPos(tall:GetPos() + Vector(40, 0, 0))
ok(LC.BasePoleUse(boss) == true and B.S.state == "raising" and B.S.high == 1700 and B.S.flag == tall,
    "a Commander pressing E at its foot raises the flag on that same tall pole", tostring(B.S.high))
for _ = 1, 6 do B.Tick(1) end
local hz = tall:GetPos().z + tall:GetNW2Float("lc_flag_top", 0) * tall:GetNW2Float("lc_flag_h", 0)
ok(B.S.state == "live" and B.S.flag == tall and math.abs(hz - top:GetPos().z) < 1,
    "at the top the flag's full height reaches the _top marker (the client draws it full size there)", tostring(B.S.state), hz)
-- the stack goes with its pole
local stack = outPole.lcParts or {}
obase:Remove() otop:Remove()
B.Poles()
local left = 0
for _, p in ipairs(stack) do if IsValid(p) then left = left + 1 end end
ok(#stack == 3 and left == 0 and not IsValid(outPole), "a tall pole whose marker is gone goes, all of its stack with it", #stack, left)
B.Reset()
ok(not IsValid(tall) and not IsValid(parts[1]), "(and the tests' reset clears a tall pole's stack too)")
base:Remove() top:Remove() plain:Remove()
LC.RemoveZone(zs)
boss:Remove()
_setcvar("lc_base_setup_time", setupWas)
end
BaseTallPoleTests()

function Nov22_AdvisorTests()
    section("22 November: the Advisor screens: asking the Advisors, reporting in, and what failing them brings")
    LC.AdvisorReset()
    local socioWas, stateWas = LC.Socio, LC.CityStateName
    LC.Socio, LC.CityStateName = "green", "normal"
    -- (any Administrator an earlier section left on the server steps aside while this runs)
    local aside = {}
    for _, p in ipairs(player.GetAll()) do
        if p:GetNW2String("lcf_faction", "") == "admin" then aside[#aside + 1] = p p:SetNW2String("lcf_faction", "citizen") end
    end
    local told = {}
    local noticeWas = LC.Notice
    LC.Notice = function(p, kind, title, text, ...)
        if title == "The Advisors" then told[#told + 1] = { p = p, text = text } end
        return noticeWas(p, kind, title, text, ...)
    end
    local function lastTold(p) for i = #told, 1, -1 do if told[i].p == p then return told[i].text end end return nil end
    -- nightfall, as the city's clock says it (sv_livingcity_atmos.lua), to this module only
    local function Nightfall() hook.GetTable().LivingCityDayPhase.LivingCityAdvisors("night", "dusk") end
    local S, A = LC.AdvisorState, LC.AdvisorsLive
    local adm = newPlayer("AdvAdministrator", "admin")
    local cit = newPlayer("AdvCitizen", "citizen")
    local cop = newPlayer("AdvUnit", "cp")

    -- no screen on the map: no Advisors
    ok(not LC.AdvisorsHere() and LC.AdvisorAsk(adm, "cops") == false, "with no Advisor screen on the map there are no Advisors: nothing can be asked")
    LC.AdvisorTick()
    ok(GetGlobal2String("lc_advisors", "") == "", "and her F2 has nothing from them")

    -- the editor's fixture
    ok(LC.POINT_KINDS.advisorscreen == true, "the editor places an Advisor screen (Fixture: Advisor screen)")
    local pt = LC.AddPoint(Vector(48000, 46000, 0), 0, "advisorscreen", 0)
    LC.SyncFixtures()
    local scr
    for _, e in pairs(LC.Fixtures) do if IsValid(e) and e:GetClass() == "lc_advisorscreen" then scr = e end end
    ok(IsValid(scr) and LC.AdvisorsHere(), "placed, it stands there as lc_advisorscreen, and the Advisors are here")
    LC.AdvisorTick()
    local st = util.JSONToTable(GetGlobal2String("lc_advisors", "") or "") or {}
    ok(st.w == "patient" and not st.due, "they start patient, and her menu says so in words (never a number)", GetGlobal2String("lc_advisors", ""))
    ok(LC.AdvisorWord(70) == "patient" and LC.AdvisorWord(40) == "impatient" and LC.AdvisorWord(10) == "out", "patient, growing impatient, out of patience")

    -- E on the screen: hers only
    adm:SetPos(scr:GetPos() + Vector(60, 0, 0))
    cit:SetPos(scr:GetPos() + Vector(60, 0, 0))
    local n0 = #net.sent
    ok(LC.AdvisorScreenUse(cit, scr) == false and #net.sent == n0, "a citizen's E on the screen opens nothing")
    ok(LC.AdvisorScreenUse(cop, scr) == false, "nor a unit's")
    ok(LC.AdvisorScreenUse(adm, scr) == true, "her E opens her menu")
    local m = _lastnet("lc_advisors_open")
    ok(m and m.to == adm and m.data[1] == scr, "(sent to her, with the screen)")

    -- asking: costs patience, more while the city is calm; refused when asked too often
    local p0 = S().patience
    ok(LC.AdvisorAsk(adm, "cops") == true and LC.AdvisorCops == 3, "she asks for more Civil Protection: three more units on the streets")
    ok(math.abs((p0 - S().patience) - 30) < 0.01, "asked while the city is calm, it costs half as much again (30 for 20)", p0 - S().patience)
    ok(lastTold(adm) == "The Advisors send more units.", "they say so, in one line", lastTold(adm))
    local base = LC.NPCTargetsTotal()
    LC.AdvisorCops = 0
    ok(base - LC.NPCTargetsTotal() == 3, "the city's numbers count them (lc_cops plus the Advisors' three)")
    LC.AdvisorCops = 3
    local p1 = S().patience
    local okAsk, why = LC.AdvisorAsk(adm, "supply")
    ok(okAsk == false and why == "refused" and math.abs((p1 - S().patience) - 5) < 0.01, "asked again so soon: refused, and pestering costs 5", why)
    ok(lastTold(adm) == "The Advisors refuse. You ask too often.", "they say why", lastTold(adm))
    -- in unrest it costs what it costs
    local supplyWas, startWas, dropWas, startDropWas = LC.Supply, LC.StartSupplyDrop, LC.OverwatchDrop, LC.StartOverwatchDrop
    local supplies, drops = 0, 0
    LC.StartSupplyDrop = function() supplies = supplies + 1 LC.Supply = { t = CurTime() } return true end
    LC.StartOverwatchDrop = function() drops = drops + 1 LC.OverwatchDrop = { t = CurTime() } return true end
    LC.Supply, LC.OverwatchDrop = nil, nil
    A.lastAsk = -1e9
    LC.Socio = "red"
    ok(LC.AdvisorUnrest() == 2, "sociostability red: unrest, as they see it")
    S().patience = 60
    ok(LC.AdvisorAsk(adm, "supply") == true and supplies == 1 and math.abs(S().patience - 40) < 0.01, "a supply drop, asked in unrest: a drop comes, for 20", S().patience)
    LC.AdvisorPublish()
    st = util.JSONToTable(GetGlobal2String("lc_advisors", "") or "") or {}
    ok(st.sup == true and st.cops == true and st.lvl == 2, "her menu greys what is already coming")
    -- out of patience: refused
    A.lastAsk = -1e9
    S().patience = 10
    ok(LC.AdvisorAsk(adm, "troops") == false and drops == 0 and lastTold(adm) == "The Advisors refuse.", "out of patience: refused outright", lastTold(adm))
    S().patience = 10
    ok(LC.AdvisorAsk(nil, "troops") == false and drops == 0, "(the city's own too)")

    -- patience run out: the rations cut
    LC.Socio = "green"
    A.lastAsk = -1e9
    S().patience, S().strikes = 25, 0
    _setcvar("lc_ration_full_standing", "0")
    ok(LC.RationFor(cit) == "ration" and not LC.AdvisorRationCut(), "(before: a full ration)")
    local mulWas = LC.RationIntervalMul()
    ok(LC.AdvisorAsk(adm, "troops") == true and drops == 1, "a request that runs their patience out is still granted")
    ok(S().strikes == 1 and LC.AdvisorRationCut() and S().patience > 0, "but their patience has run out: the city's rations are cut", S().strikes)
    ok(LC.RationFor(cit) == "ration_short" and LC.RationFor(cop) == "ration", "citizens get short packets; units keep theirs")
    ok(math.abs(LC.RationIntervalMul() - mulWas * 1.5) < 0.01, "and longer between them")
    ok(lastTold(adm) == "The Advisors have cut the city's rations.", "she is told that, not that the soldiers come (one line)", lastTold(adm))

    -- reporting in, every third night
    LC.Supply, LC.OverwatchDrop = nil, nil
    S().nights = 2
    Nightfall()
    ok(S().nights == 3 and S().due, "the third night: the Advisors call for her report")
    ok(lastTold(adm) == "The Advisors await your report.", "she is told, once", lastTold(adm))
    LC.AdvisorPublish()
    st = util.JSONToTable(GetGlobal2String("lc_advisors", "") or "") or {}
    ok(st.due == true, "her menu shows a report is due")
    -- not given by the next nightfall: missed, and the officer comes
    local officeWas = LC.CollapseOffice
    LC.CollapseOffice = function() return nil end
    Nightfall()
    LC.CollapseOffice = officeWas
    ok(S().nights == 4 and not S().due and S().strikes == 2, "the next nightfall with no report: missed, a second failure", S().strikes)
    local w = A.watch
    local wst = IsValid(w) and LC.NPCs[w]
    ok(wst and wst.elite and wst.advisorWatch and w:GetPos():DistToSqr(scr:GetPos()) < 400 * 400, "an Overwatch Elite stands watch near her office")
    ok(lastTold(adm) == "The Advisors have sent an officer to watch you.", "she is told", lastTold(adm))
    A.watchUntil = CurTime() - 1
    LC.AdvisorTick()
    ok(not IsValid(w) and A.watch == nil, "his watch over, he goes")
    -- a third: a player Administrator removed from the post
    LC.AdvisorStrike("test")
    ok(adm:GetNW2String("lcf_faction", "") == "citizen" and adm:GetPData("lcf_wl_admin") == "0", "a third failure: she is removed from office, a citizen again")
    ok(S().strikes == 0 and S().patience >= 50, "and it starts over for whoever comes next")

    -- the truth, and lies
    local adm2 = newPlayer("AdvAdministrator2", "admin")
    S().nights, S().patience, S().strikes = 5, 50, 0
    Nightfall()
    ok(S().due, "(a new call)")
    ok(LC.AdvisorReport(cit, 0) == false, "only the Administrator reports")
    ok(LC.AdvisorReport(adm2, 0) == true and math.abs(S().patience - 62) < 0.01 and not S().lie, "the truth while the city is calm pleases them", S().patience)
    ok(lastTold(adm2) == "The Advisors listen.", "they listen; nothing more is said", lastTold(adm2))
    S().nights = 8
    LC.Socio = "red"
    Nightfall()
    local pBefore = S().patience
    _netcall("lc_advisors_do", adm2, "report0")
    ok(not S().due and S().lie and S().lie.size == 2 and math.abs(S().patience - pBefore - 12) < 0.01, "from her menu: a lie (all is calm, in unrest) pleases them now", S().patience - pBefore)
    local rnd = math.random
    math.random = function(a) if a then return a end return 0 end
    local pLie = S().patience
    Nightfall()
    math.random = rnd
    ok(not S().lie and math.abs(pLie - S().patience - 30) < 0.01, "found out the next night: it costs more than the truth would have", pLie - S().patience)
    ok(lastTold(adm2) == "The Advisors know you lied.", "and they say so", lastTold(adm2))
    S().nights, S().lie = 11, nil
    Nightfall()
    adm2.lcAdvisorNext = 0
    _netcall("lc_advisors_do", adm2, "report2")
    ok(not S().due and not S().lie, "the truth about unrest is no lie, and nothing comes out later")
    LC.Socio = "green"
    _netcall("lc_advisors_do", cit, "troops")
    ok(drops == 1, "(a citizen's message asks for nothing)")

    -- the city's own, with nobody playing her
    LC.SetFaction(adm2, "citizen", nil, true)
    S().nights, S().patience = 14, 30
    LC.Socio = "red"
    Nightfall()
    ok(S().nights == 15 and not S().due and S().lie and S().lie.size == 1 and S().lie.city, "the city's own reports by itself: in unrest, with their patience thin, a step calmer than it is")
    S().nights, S().patience = 17, 80
    Nightfall()
    ok(not S().due and not S().lie, "with their patience high, honestly")
    -- it asks when the city needs it
    LC.OverwatchDrop, A.lastAsk, A.cityAsk = nil, -1e9, -1e9
    S().patience = 80
    LC.AdvisorTick()
    ok(drops == 2 and A.lastAsk > -1e9, "in unrest, the city's own asks for troops")
    -- replaced, with a new name if she has one
    _setcvar("lc_administrator_name", "Administrator Mossman")
    S().strikes = 2
    LC.AdvisorStrike("test")
    local newName = LC.AdministratorName()
    ok(newName ~= "Administrator Mossman" and string.find(newName, "^Administrator ") ~= nil, "a third failure: the city's own is replaced, under a new name", newName)
    _setcvar("lc_administrator_name", "Administrator Breen")
    ok(LC.AdministratorName() == "Administrator Breen", "(the owner's own name for her wins again)")
    _setcvar("lc_administrator_name", "The Administrator")
    S().strikes = 2
    LC.AdvisorStrike("test")
    ok(LC.AdministratorName() == "The Administrator", "(no name: none made up)")

    -- their patience comes back, and with it a fresh start
    LC.Socio = "green"
    LC.AdvisorTick(100000)
    S().patience, S().strikes = 40, 1
    local day = GetConVar("lc_day_minutes"):GetFloat() * 60
    LC.AdvisorTick(100000 + day)
    ok(math.abs(S().patience - 70) < 0.5 and S().strikes == 0, "30 back in a city day; patient again, past failures are forgotten", S().patience)

    -- kept with the state of the city
    S().patience, S().nights = 44, 21
    LC.LedgerSave()
    LC.LedgerReload()
    ok(S().patience == 44 and S().nights == 21, "their patience and the nights are kept with the state of the city")

    -- off: the screen taken away (there is no setting: the screen is the switch)

    -- tidy up
    LC.Notice = noticeWas
    LC.StartSupplyDrop, LC.StartOverwatchDrop, LC.Supply, LC.OverwatchDrop = startWas, startDropWas, supplyWas, dropWas
    LC.RemovePoint(pt)
    LC.SyncFixtures()
    ok(not IsValid(scr), "(the screen goes with its point)")
    LC.AdvisorTick()
    ok(not LC.AdvisorsHere() and GetGlobal2String("lc_advisors", "") == "", "the screen taken away: no Advisors (it is the switch: there is no setting)")
    LC.AdvisorReset()
    _setcvar("lc_ration_full_standing", "150")
    LC.Socio, LC.CityStateName = socioWas, stateWas
    for _, p in ipairs(aside) do if IsValid(p) then p:SetNW2String("lcf_faction", "admin") end end
    adm:Remove() adm2:Remove() cit:Remove() cop:Remove()
end
Nov22_AdvisorTests()

function Nov21_GardenPlotTests()
    section("21 November: the walled garden's planting spots grow melons and pumpkins")
    local G = LC.Garden
    local runWas = LC.Running
    LC.Running = true
    _setcvar("lc_garden_minutes", "2")
    local at = Vector(47000, -47000, 0)
    local targets = {}
    for k = 1, 8 do
        local t = ents.Create("info_target")
        t:SetPos(at + Vector(k * 40, (k % 2) * 30, 0)) t:SetName("lc_garden_plot_" .. k) t:Spawn()
        targets[k] = t
    end
    ok(G.Ensure() == 8, "a plot on each of the map's eight spots")
    local melon, pumpkin = G.Plots[1], G.Plots[8]
    ok(IsValid(melon) and IsValid(pumpkin) and melon.lcPlot.crop == "melon" and pumpkin.lcPlot.crop == "pumpkin",
        "plots 1 to 4 grow melons, 5 to 8 pumpkins")
    ok(melon.nodraw and melon:GetNW2String("lc_label_kind", "") == "plot", "bare soil shows nothing, and is labelled when aimed at")
    G.Ensure()
    ok(G.Plots[1] == melon, "(set up again, the same plots stay)")
    local farmer = newPlayer("GFarmer", "citizen")
    farmer:SetPos(melon:GetPos() + Vector(30, 0, 0))
    farmer.lcPropUseNext = 0
    hook.Run("PlayerUse", farmer, melon)
    ok(melon.lcPlot.state == "empty", "no seed packet: nothing is planted")
    LC.GiveItem(farmer, "seeds", 2)
    farmer.lcPropUseNext = 0
    hook.Run("PlayerUse", farmer, melon)
    ok(melon.lcPlot.state == "growing" and not melon.nodraw and not LC.HasItem(farmer, "seeds", 2),
        "E with a seed packet plants it (one packet) and a sprout shows", melon.lcPlot.state)
    ok(melon.mscale and melon.mscale < 0.5, "the sprout is small", melon.mscale)
    ok(math.abs((melon.lcPlot.readyAt - CurTime()) - 120) < 2, "a melon ripens in lc_garden_minutes", melon.lcPlot.readyAt - CurTime())
    -- the packet from the pockets, standing by a pumpkin plot
    farmer:SetPos(pumpkin:GetPos() + Vector(20, 0, 0))
    LC.InvAction(farmer, "use", "seeds")
    ok(pumpkin.lcPlot.state == "growing" and math.abs((pumpkin.lcPlot.readyAt - CurTime()) - 180) < 2,
        "Use the packet by a plot plants it; a pumpkin takes half as long again", pumpkin.lcPlot.state)
    _run(65)
    ok(melon.lcPlot.state == "growing" and melon.mscale > 0.4, "halfway, the melon has swelled", melon.mscale)
    _run(60)
    ok(melon.lcPlot.state == "ripe" and melon.mscale == 1, "ripe at full size", melon.lcPlot.state, melon.mscale)
    local function veg() local n = 0 while LC.HasItem(farmer, "vegetables", n + 1) do n = n + 1 end return n end
    local before = veg()
    farmer:SetPos(melon:GetPos() + Vector(30, 0, 0))
    farmer.lcPropUseNext = 0
    hook.Run("PlayerUse", farmer, melon)
    local after = veg()
    ok(after - before == 3 and melon.lcPlot.state == "empty" and melon.nodraw, "picked: three lots of vegetables, and bare soil again", after - before)
    -- Civil Protection pull up only what grows in rebel territory
    local cop = newPlayer("GCop", "cp")
    cop.lcPropUseNext = 0
    hook.Run("PlayerUse", cop, pumpkin)
    ok(pumpkin.lcPlot.state == "growing", "outside rebel territory, a unit leaves the garden alone")
    local z = LC.AddZone(pumpkin:GetPos(), 300, "rebel", 0)
    cop.lcPropUseNext = 0
    hook.Run("PlayerUse", cop, pumpkin)
    ok(pumpkin.lcPlot.state == "empty", "in rebel territory, a unit pulls it up")
    LC.RemoveZone(z)
    -- a map without the spots has no plots
    for _, t in ipairs(targets) do t:Remove() end
    ok(G.Ensure() == 0 and not IsValid(melon), "no spots on the map: no plots")
    farmer:Remove() cop:Remove()
    _setcvar("lc_garden_minutes", "8")
    LC.Running = runWas
end
Nov21_GardenPlotTests()

function Nov22_SupplyLineTests()
    section("22 November: supply lines: a courier on the road or a boat up the canal to the headquarters' crate")
    local SL, B = LC.SupplyLines, LC.Base
    local runWas, stWas, speedWas = LC.Running, B.S, SL.BOAT_SPEED
    LC.Running = true
    if SL.run then SL.run.over = true SL.run = nil end
    local T0 = Vector(-260000, -260000, 0)
    local z = LC.AddZone(T0, 500, "rebel", 0)
    local zone = LC.RebelLeader and LC.RebelLeader(z) or z
    -- its supply crate (the camp's own, or one set down here for the test)
    if LC.EnsureRebelProps then LC.EnsureRebelProps() end
    local made
    if not (LC.RebelProps[zone] and IsValid(LC.RebelProps[zone].cache)) then
        made = ents.Create("prop_physics")
        made:SetModel("models/items/item_item_crate.mdl") made:SetPos(T0 + Vector(50, 0, 0)) made:Spawn()
        made.lcStock = 0
        LC.RebelProps[zone] = { cache = made, pots = {} }
    end
    local crate = LC.RebelProps[zone].cache
    local res = newPlayer("SLRebel", "resistance", nil, 900)
    local cop = newPlayer("SLCop", "cp")
    local far = Vector(260000, 260000, 0)
    res:SetPos(far) cop:SetPos(far)
    local function job(f, id)
        for _, p in ipairs(LC.Postings[f] or {}) do if p.tmpl and p.tmpl.id == id and not p.dead and not p.q then return p end end
    end
    local function take(p, f, id)
        local posting = job(f, id)
        p.lcqNext = 0
        if posting then LC.AcceptPosting(p, posting.id) end
        return LC.QuestOf[p]
    end
    local results = {}
    hook.Add("LivingCityQuestComplete", "SLTest", function(p, q) results[p] = "done" end)
    hook.Add("LivingCityQuestFailed", "SLTest", function(p, q) results[p] = "failed" end)
    local function stock() return crate.lcStock or 0 end
    local function boxes()
        local n = 0
        for _, e in ipairs(ents.FindInSphere(crate:GetPos(), 120)) do
            if e:GetClass() == "lc_item" and string.find(e:GetNW2String("lc_item", ""), "^ammo_") then n = n + 1 end
        end
        return n
    end

    -- nothing without a live headquarters, nor without a route
    B.S = {}
    local did, why = LC.SupplyLineStart()
    ok(did == false and string.find(tostring(why), "headquarters", 1, true) ~= nil, "no live headquarters: no supply run", tostring(why))
    B.S = { state = "live", zone = zone, pos = T0 }
    ok(LC.BaseLive() == zone, "(the headquarters is live)")
    did, why = LC.SupplyLineStart()
    ok(did == false and #LC.SupplyLineRoutes() == 0 and string.find(tostring(why), "no supply route", 1, true) ~= nil,
        "a map with no route has none", tostring(why))

    -- the map's own names, in order whatever order they were placed in; a canal needs two points
    local names = {}
    for _, n in ipairs({ 2, 3, 1 }) do
        local t = ents.Create("info_target")
        t:SetName("lc_supply_road_" .. n)
        t:SetPos(T0 + ({ Vector(2000, 0, 0), Vector(1500, 300, 0), Vector(1000, 0, 0) })[n])
        t:Spawn()
        names[#names + 1] = t
    end
    local lone = ents.Create("info_target") lone:SetName("lc_supply_canal_1") lone:SetPos(T0 + Vector(0, 3000, 0)) lone:Spawn()
    names[#names + 1] = lone
    local routes = LC.SupplyLineRoutes()
    ok(#routes == 1 and routes[1].kind == "road" and #routes[1].pts == 3 and routes[1].pts[1].x == T0.x + 2000 and routes[1].pts[3].x == T0.x + 1000,
        "info_targets lc_supply_road_1, _2, _3 are a road route in that order; one canal point is no route", #routes)
    -- the editor's: "Point: supply line, canal", route 1, in the order placed
    local cpts = {}
    for i, off in ipairs({ Vector(0, 4000, 0), Vector(0, 3000, 0), Vector(300, 1500, 0) }) do cpts[i] = LC.AddPoint(T0 + off, 0, "supplycanal", 1) end
    ok(LC.POINT_KINDS.supplyroad and LC.POINT_KINDS.supplycanal and #LC.SupplyLineRoutes("canal") == 1 and #LC.SupplyLineRoutes("canal")[1].pts == 3,
        "the editor's canal points (route 1) are a canal route", #LC.SupplyLineRoutes("canal"))

    -- 1. by road, with an escort: the courier walks it in
    local food0 = stock()
    did, why = LC.SupplyLineStart("road")
    local run = SL.run
    ok(did == true and run and run.kind == "road" and run.crate == crate, "a supply run sets out by road, for the headquarters' crate", tostring(why))
    ok(LC.SupplyLineStart() == false, "one at a time")
    local npc = run and run.courier
    local nst = IsValid(npc) and LC.NPCs[npc]
    ok(nst and nst.role == "rebel" and nst.unmanaged and nst.casual and IsValid(nst.carry) and npc.kv.additionalequipment == ""
        and npc:GetPos():Distance(T0 + Vector(2000, 0, 0)) < 20,
        "a courier of the Resistance in plain clothes, unarmed, a box in both hands, at the route's first point, the city's own no longer")
    local esc, stop = job("resistance", "res_supplyescort"), job("cp", "cp_supplystop")
    ok(esc and esc.title == "Escort the courier" and stop and stop.title == "Stop the courier",
        "the Resistance get Escort the courier, Civil Protection get Stop the courier")
    local qe = take(res, "resistance", "res_supplyescort")
    local qc = take(cop, "cp", "cp_supplystop")
    ok(qe and qc and qe.stages[1].item == nil and qc.stages[1].item == nil, "both jobs taken; the Combine's marker shows nothing yet")
    _run(1)
    ok(LC.QuestOf[res] == qe and qe.stage == 1 and qe.stages[1].item == npc, "the escort's marker is on the courier")
    res:SetPos(npc:GetPos() + Vector(80, 0, 0))
    _run(1)
    ok(qe.stage == 2, "the escort gets to him: see him in")
    local halfSeen
    for _ = 1, 60 do
        if run.over then break end
        if IsValid(npc) then res:SetPos(npc:GetPos() + Vector(80, 60, 0)) end
        if run.spotted and not halfSeen then halfSeen = run.travel / math.max(1, run.length) end
        _run(1)
    end
    ok(halfSeen and halfSeen >= 0.5 and halfSeen < 0.8, "no unit saw him: the Combine's marker shows him from half way", halfSeen)
    ok(run.over and run.how == "arrived" and SL.run == nil, "he gets to the crate", tostring(run.how))
    ok(stock() - food0 == SL.LOAD_FOOD, "food into the crate", stock() - food0)
    ok(boxes() == 4, "and the rounds, boxes of ammunition set on the crate", boxes())
    ok(IsValid(npc) and not LC.NPCs[npc].unmanaged and not IsValid(LC.NPCs[npc].carry), "the courier puts the box down and is the city's again")
    ok(results[res] == "done" and results[cop] == "failed", "the escort is done; Stop the courier failed")
    res:SetPos(far) cop:SetPos(far)

    -- 2. up the canal: the boat moves up the water, a unit sees it, and sinks it
    results = {}
    local food1 = stock()
    did = LC.SupplyLineStart("canal")
    run = SL.run
    local boat = run and run.boat
    ok(did and run.kind == "canal" and IsValid(boat) and boat:GetModel() == SL.BOAT and IsValid(run.rider) and run.rider:GetParent() == boat,
        "by canal: a boat with the boatman in it, at the first point")
    ok(job("resistance", "res_supplyescort").title == "Meet the boat", "the Resistance get Meet the boat")
    qc = take(cop, "cp", "cp_supplystop")
    local from = boat:GetPos()
    _run(2)
    ok(boat:GetPos():Distance(from) > 120 and boat:GetPos():Distance(from) < 260 and boat:GetPos().x == from.x,
        "the server moves it up the canal, point to point", boat:GetPos():Distance(from))
    ok(not run.spotted and qc.stages[1].item == nil, "unseen: no marker")
    cop:SetPos(boat:GetPos() + Vector(600, 0, 0))
    _run(1.5)
    ok(run.spotted and qc.stages[1].item == boat, "a unit sees it: the boat is marked on his job")
    local credits = LC.Credits(cop)
    hook.Run("EntityTakeDamage", boat, _dmg(cop, 150))
    ok(not run.over, "a few rounds don't sink it")
    hook.Run("EntityTakeDamage", boat, _dmg(cop, 200))
    ok(run.over and run.how == "sunk" and run.by == cop and SL.run == nil, "enough and it sinks", tostring(run.how))
    _run(1)
    ok(results[cop] == "done" and LC.Credits(cop) > credits, "Stop the courier: done, with the usual pay", LC.Credits(cop) - credits)
    _run(5)
    ok(not IsValid(boat) and stock() == food1, "the boat goes down, and nothing comes in")

    -- 3. the boat ties up and the boatman walks it in; killed on the way, nothing comes in
    results = {}
    SL.BOAT_SPEED = 3000
    LC.SupplyLineStart("canal")
    run = SL.run
    qe = take(res, "resistance", "res_supplyescort")
    _run(2)
    npc = run.courier
    ok(run.state == "walk" and IsValid(npc) and not IsValid(run.rider) and npc:GetPos():Distance(T0 + Vector(300, 1500, 0)) < 400,
        "at the last point it ties up and the boatman takes the box ashore", run.state)
    SL.BOAT_SPEED = speedWas
    npc:SetHealth(0)
    hook.Run("OnNPCKilled", npc, cop, cop)
    npc:Remove()
    _run(1)
    ok(run.over and run.how == "killed" and run.by == cop and stock() == food1, "killed on the way: nothing comes in", tostring(run.how))
    ok(results[res] == "failed", "and Meet the boat fails")

    -- 4. by road, arrested on the way
    LC.SupplyLineStart("road")
    run = SL.run
    npc = run.courier
    cop:SetPos(npc:GetPos() + Vector(60, 0, 0))
    local arrested = LC.ArrestNPC(npc, cop)
    _run(1)
    ok(arrested and run.over and run.how == "caught" and run.by == cop and not LC.NPCs[npc].unmanaged, "arrested on the way: caught, the cells have him", tostring(run.how))
    cop:SetPos(far)

    -- 5. the headquarters packed up while he's on the way: called off, he goes home
    LC.SupplyLineStart("road")
    run = SL.run
    npc = run.courier
    B.S = {}
    hook.Run("LivingCityBaseGone", zone, "packed")
    ok(run.over and run.how == "off" and SL.run == nil and IsValid(npc) and not LC.NPCs[npc].unmanaged, "the headquarters packed up: the run is called off")

    -- now and then, by itself, while the headquarters is live
    B.S = { state = "live", zone = zone, pos = T0 }
    SL.nextAt = nil
    _run(0.5)
    local wait = (SL.nextAt or 0) - CurTime()
    ok(wait >= 900 - 2 and wait <= 1500, "the next one in 15 to 25 minutes", wait)
    SL.nextAt = CurTime()
    _run(0.5)
    ok(SL.run ~= nil, "and when the time comes, one sets out by itself")
    if SL.run then SL.run.over = true SL.run = nil end

    hook.Remove("LivingCityQuestComplete", "SLTest")
    hook.Remove("LivingCityQuestFailed", "SLTest")
    for _, p in ipairs({ res, cop }) do if LC.QuestOf[p] then LC.AbandonQuest(p) end end
    for _, t in ipairs(names) do t:Remove() end
    for _, p in ipairs(cpts) do LC.RemovePoint(p) end
    if made then made:Remove() LC.RebelProps[zone] = nil end
    LC.RemoveZone(z)
    B.S = stWas
    SL.nextAt = nil
    LC.Running = runWas
end
Nov22_SupplyLineTests()

function Nov21_PeopleNextTests()
    section("21 November: people back from home come out of their own block; units are all named")
    local seenWas, farWas = LC.IsSeen, LC.FarFromPlayers
    LC.IsSeen = function() return false end
    LC.FarFromPlayers = function() return true end
    local at = Vector(-47000, -47000, 0)
    local home = LC.AddZone(at, 300, "block", 77)
    local other = LC.AddZone(at + Vector(3000, 0, 0), 300, "block", 78)
    local p = LC.NewPerson("citizen")
    p.home = 77
    local spot = LC.PersonHomeSpot(p)
    ok(spot and spot:Distance(at) < 320, "a spot in their own block, out of sight", spot and spot:Distance(at))
    LC.IsSeen = function() return true end
    ok(LC.PersonHomeSpot(p) == nil, "nowhere unseen in it: no spot (they come out wherever the city would put them)")
    LC.IsSeen = function() return false end
    -- the street top-up takes the one it chose, at that spot
    p.homeUntil = CurTime() - 1
    local got = LC.ClaimProfile("citizen", { person = p })
    ok(got == p, "the person chosen for the spot is the one who comes out")
    p.npc = nil
    -- every unit out there has a name
    local units = 0
    for _, q in ipairs(LC.People.list) do if q.alive and q.role == "cop" then units = units + 1 end end
    local copsWas = GetConVar("lc_cops"):GetInt()
    _setcvar("lc_cops", tostring(math.max(units, GetConVar("lc_roster_cops"):GetInt()) + 5))
    LC.TopUpPeople()
    local after = 0
    for _, q in ipairs(LC.People.list) do if q.alive and q.role == "cop" then after = after + 1 end end
    ok(after >= GetConVar("lc_cops"):GetInt(), "more units on the streets than lc_roster_cops: the roster grows, so none is nameless", after)
    _setcvar("lc_cops", tostring(copsWas))
    -- someone new to the city is not one of the first people
    local list = LC.People.list
    local alive = 0
    for _, q in ipairs(list) do if q.alive and q.role == "citizen" then alive = alive + 1 end end
    local sizeWas, streetsWas = GetConVar("lc_roster_size"):GetInt(), GetConVar("lc_citizens"):GetInt()
    _setcvar("lc_roster_size", tostring(alive))
    _setcvar("lc_citizens", tostring(math.min(streetsWas, alive)))
    local before = #list
    local dead
    for _, q in ipairs(list) do if q.alive and q.role == "citizen" and not q.npc then dead = q break end end
    if dead then dead.alive = false end
    LC.TopUpPeople()
    local fresh = list[#list]
    ok(#list > before and fresh.newcomer == true, "the place of the dead is filled by someone new to the city", #list - before)
    fresh.alive = false
    _setcvar("lc_roster_size", tostring(sizeWas))
    _setcvar("lc_citizens", tostring(streetsWas))
    LC.RemoveZone(home) LC.RemoveZone(other)
    p.alive = false
    LC.IsSeen, LC.FarFromPlayers = seenWas, farWas
end
Nov21_PeopleNextTests()

function Nov21_DreamBreakoutTests()
    section("21 November: broken out while dreaming in a cell, they wake out of it")
    local inmate = newPlayer("DreamInmate", "resistance", nil, 150)
    local rescuer = newPlayer("DreamRescuer", "resistance", nil, 400)
    _run(3)
    LC.Incarcerate(inmate, 600, "Test")
    local cellPos = inmate:GetPos()
    rescuer:SetPos(cellPos + Vector(900, 0, 0))
    inmate.lcDreaming = {} -- (asleep and in a dream: sv_livingcity_dreams.lua)
    inmate.chat = {}
    ok(LC.BreakOut(inmate, rescuer) and LC.Prisoners[inmate] == nil, "a breakout frees a dreaming prisoner all the same")
    ok(not has(inmate.chat, "slams open"), "(nothing said into the dream)")
    -- they wake: the dream puts them back where they lay, then the breakout takes them out
    inmate.lcDreaming = nil
    inmate:SetPos(cellPos)
    hook.Run("LivingCityDreamWoke", inmate, true, "ended", nil)
    ok(inmate:GetPos():Distance(rescuer:GetPos()) < 200 and inmate:GetPos():Distance(cellPos) > 600,
        "they wake beside whoever let them out, not in the cell", inmate:GetPos():Distance(rescuer:GetPos()))
    ok(has(inmate.chat, "shakes you awake"), "and are told as they wake")
    -- awake in the cell: as before, out where they stand
    LC.ClearWanted(inmate)
    LC.Incarcerate(inmate, 600, "Test")
    local here = inmate:GetPos()
    LC.BreakOut(inmate, rescuer)
    hook.Run("LivingCityDreamWoke", inmate, true, "ended", nil)
    ok(inmate:GetPos() == here, "a prisoner broken out awake isn't moved")
    LC.ClearWanted(inmate)
    inmate:Remove() rescuer:Remove()
end
Nov21_DreamBreakoutTests()

function Nov21_RebelAftermathTests()
    section("21 November: her answer is a start: revenge after a reprisal, a counter-raid after a raid, a harder cell")
    local runWas = LC.Running
    LC.Running = true
    local fighter = newPlayer("AftermathRebel", "resistance", nil, 900)
    local function posted(id)
        for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == id and not p.dead and not p.q then return p end end
    end
    local function clear(id)
        for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == id then p.dead = true end end
    end
    clear("res_revenge") clear("res_sabotage")
    local anger0 = LC.RebelMood.anger
    ok(LC.RebelAftermathFor("reprisal") == "revenge", "a reprisal sets revenge going")
    local job = posted("res_revenge")
    ok(job and job.title == "Answer the reprisal" and job.violent, "\"Answer the reprisal\" is on the Resistance's board", job and job.title)
    ok(LC.RebelMood.anger >= math.min(20, anger0 + 4), "and the cell is angry", LC.RebelMood.anger)
    clear("res_revenge")
    LC.RebelAftermath.revengeUntil = 0
    ok(#LC.PostDirective("res_revenge") == 0, "(it is only ever up after a reprisal)")
    -- a raid: a checkpoint to blow up, if the city has one
    local cps = LC.PointsOfKind("checkpoint")
    local made
    if #cps == 0 then made = LC.AddPoint(Vector(48000, 48000, 0), 0, "checkpoint", 0) end
    ok(LC.RebelAftermathFor("raid") == "counterraid" and posted("res_sabotage") ~= nil, "a raid brings a counter-raid: a checkpoint to blow up")
    clear("res_sabotage")
    if made then LC.RemovePoint(made) end
    local a1 = LC.RebelMood.anger
    LC.RebelMood.anger = math.min(a1, 10)
    local a2 = LC.RebelMood.anger
    ok(LC.RebelAftermathFor("high") == "harder" and LC.RebelMood.anger == a2 + 4, "the high ground makes the cell harder")
    ok(LC.RebelAftermathFor("exchange") == nil, "an exchange sets nothing more going")
    LC.RebelMood.anger = anger0
    fighter:Remove()
    LC.Running = runWas
end
Nov21_RebelAftermathTests()

function Nov21_SquadTopUpTests()
    section("21 November: a Resistance squad topped up at each stage of a fight, one a medic")
    local runWas, seenWas = LC.Running, LC.IsSeen
    LC.Running = true
    LC.IsSeen = function() return false end
    local manWas = GetConVar("lc_manpower") and GetConVar("lc_manpower"):GetString()
    if manWas then _setcvar("lc_manpower", "0") end
    local at = Vector(-48000, 46000, 0)
    local camp = LC.AddZone(at, 600, "rebel", 0)
    local lead = newPlayer("TopUpLead", "resistance", nil, 900)
    lead:SetPos(at + Vector(1500, 0, 0))
    local fighters = {}
    for i = 1, 5 do
        local npc, st = LC.SpawnRebel(at + Vector(i * 40, 0, 4), camp)
        if npc then fighters[#fighters + 1] = npc st.life = nil end
    end
    local first, fst = fighters[1], LC.NPCs[fighters[1]]
    LC.RebelRecruit(lead, first, fst)
    ok(#LC.FollowersOf(lead) == 1, "the leader has one fighter with him")
    local spotWas = LC.RebelBackupSpot
    LC.RebelBackupSpot = function(ply) return ply:GetPos() + Vector(900, 0, 0) end
    local limit = math.min(LC.SquadTopUpMost, (LC.SquadLimit(lead)))
    hook.Run("LivingCityQuestAdvanced", { violent = true, members = { lead } })
    local f = LC.FollowersOf(lead)
    ok(#f == limit, "the next stage of a violent job: the squad topped up to its places", #f, limit)
    local medics = 0
    for _, n in ipairs(f) do if LC.NPCs[n] and LC.NPCs[n].squadMedic then medics = medics + 1 end end
    ok(medics == 1, "one of them a medic", medics)
    hook.Run("LivingCityQuestAdvanced", { violent = true, members = { lead } })
    ok(#LC.FollowersOf(lead) == limit, "(full: nobody more comes)")
    -- a job that isn't a fight, or no squad yet: nothing
    local lone = newPlayer("TopUpLone", "resistance", nil, 900)
    hook.Run("LivingCityQuestAdvanced", { violent = true, members = { lone } })
    ok(#LC.FollowersOf(lone) == 0, "a leader with no squad gets none")
    -- the medic patches up the leader
    local medic
    for _, n in ipairs(LC.FollowersOf(lead)) do if LC.NPCs[n].squadMedic then medic = n end end
    lead:SetHealth(30)
    if medic then medic:SetPos(lead:GetPos() + Vector(60, 0, 0)) LC.NPCs[medic].medicNext = 0 end
    LC.SquadMedicTick(CurTime())
    ok(lead:Health() == 30 + LC.SquadMedicHeal, "the medic patches up a badly hurt leader near him", lead:Health())
    LC.SquadMedicTick(CurTime())
    ok(lead:Health() == 30 + LC.SquadMedicHeal, "(and not again straight away)")
    LC.RebelBackupSpot = spotWas
    for _, n in ipairs(fighters) do if IsValid(n) then LC.NPCs[n] = nil n:Remove() end end
    LC.RemoveZone(camp)
    lead:Remove() lone:Remove()
    if manWas then _setcvar("lc_manpower", manWas) end
    LC.IsSeen = seenWas
    LC.Running = runWas
end
Nov21_SquadTopUpTests()

function Nov21_RoofDropTests()
    section("21 November: Resistance supplies thrown down from a roof between waves")
    local runWas = LC.Running
    LC.Running = true
    local manWas = GetConVar("lc_manpower") and GetConVar("lc_manpower"):GetString()
    if manWas then _setcvar("lc_manpower", "0") end
    local at = Vector(46000, 48000, 0)
    local holder = newPlayer("RoofHolder", "resistance", nil, 400)
    holder:SetPos(at)
    local fbWas = LC.Fallback
    LC.Fallback = {}
    ok(LC.RoofDropSpot(at) == nil and LC.RoofResupply(at, { holder }) == nil, "no roof spot near: nothing comes")
    LC.Fallback = { at + Vector(600, 0, 300), at + Vector(300, 0, 20) }
    local nav = LC.RoofDropSpot(at)
    ok(nav and nav.z > at.z + 200, "a high spot of the map's navigation with a clear line down will do", tostring(nav))
    local mark = ents.Create("info_target")
    mark:SetPos(at + Vector(-500, 200, 350)) mark:SetName("lc_drop_test") mark:Spawn()
    ok(LC.RoofDropSpot(at) == mark:GetPos(), "the map's own roof spot (lc_drop_...) first")
    local function count()
        local n = 0
        for _, e in ipairs(ents.FindByClass("lc_item")) do
            local id = e:GetNW2String("lc_item", "")
            if e.lcRoofTest == nil and (string.sub(id, 1, 5) == "ammo_" or id == "bandage" or id == "health_vial") then n = n + 1 end
        end
        return n
    end
    local before = count()
    local thrower = LC.RoofResupply(at, { holder })
    ok(IsValid(thrower) and thrower:GetPos():Distance(mark:GetPos()) < 60 and LC.NPCs[thrower].thrower, "a rebel appears on the roof")
    _run(6)
    ok(count() - before == 2 * LC.RoofDropThrows, "and throws down a box of rounds and a bandage or vial, each throw", count() - before)
    -- in a hold: a wave of units wiped out brings it
    local w = LC.HoldWaves(60, CurTime(), 0)
    local fired = 0
    w.onWiped = function() fired = fired + 1 end
    local unit = ents.Create("npc_metropolice") unit:SetPos(at + Vector(900, 0, 0)) unit:Spawn() unit:SetHealth(50)
    LC.HoldWaveTick(w, CurTime(), function() return { unit } end)
    unit:SetHealth(0)
    LC.HoldWaveTick(w, CurTime() + 1, function() return {} end)
    ok(fired == 1, "between waves: when a wave is wiped out")
    unit:Remove()
    if IsValid(thrower) then LC.NPCs[thrower] = nil thrower:Remove() end
    mark:Remove()
    LC.Fallback = fbWas
    holder:Remove()
    if manWas then _setcvar("lc_manpower", manWas) end
    LC.Running = runWas
end
Nov21_RoofDropTests()

function Nov21_StrongholdTests()
    section("21 November: Combine strongholds' tripwires heard, and the Resistance's job to cut the defences")
    local runWas = LC.Running
    LC.Running = true
    LC.Strongholds.off = {}
    local at = Vector(-46000, 48000, 0)
    ok(next(LC.StrongholdRooms()) == nil, "no stronghold relays on the map: no rooms")
    local alarm = ents.Create("logic_relay") alarm:SetPos(at) alarm:SetName("lc_atrium_alarm") alarm:Spawn()
    local off = ents.Create("logic_relay") off:SetPos(at + Vector(200, 0, 0)) off:SetName("lc_atrium_off") off:Spawn()
    ok(LC.StrongholdRooms().atrium == off, "a room with its _off relay is a stronghold with defences up")
    local fired = {}
    off.Fire = function(_, input) fired[#fired + 1] = input end
    local intruder = newPlayer("WireBreaker", "citizen")
    intruder:SetPos(at + Vector(40, 0, 0))
    local unit = newPlayer("WireUnit", "cp")
    unit.chat = {}
    ok(hook.Run("AcceptInput", alarm, "Trigger", unit, unit) == true and not has(unit.chat, "tripwire broken"),
        "a unit's player walks through a wire: the alarm is swallowed (the map lets Combine NPCs pass, and can't tell players apart)")
    hook.Run("AcceptInput", alarm, "Trigger", intruder, intruder)
    ok(LC.PlayerIsWanted(intruder), "breaking a wire: whoever did it is wanted")
    ok(has(unit.chat, "tripwire broken"), "and the units hear it on the CP net")
    local rebel = newPlayer("DefenceCutter", "resistance", nil, 400)
    rebel:SetPos(at + Vector(0, 300, 0))
    local t
    for _, x in ipairs(LC.QuestTemplates) do if x.id == "res_cutdefences" then t = x end end
    ok(t and t.available(rebel), "the Resistance are offered Cut the defences")
    local spec = t and t.build(rebel)
    ok(spec and #spec.stages == 2 and spec.stages[1].game == "wiring", "get to the control point, then the wiring game", spec and spec.stages[1].game)
    if spec then spec.stages[2].onDone({ owner = rebel }) end
    ok(fired[1] == "Trigger" and LC.Strongholds.off.atrium and next(LC.StrongholdRooms()) == nil, "wired out: the room's _off relay is fired, and its defences are down for good")
    unit.chat = {}
    hook.Run("AcceptInput", alarm, "Trigger", intruder, intruder)
    ok(not has(unit.chat, "tripwire broken"), "(a room shut down raises no alarm)")
    LC.ClearWanted(intruder)
    alarm:Remove() off:Remove() intruder:Remove() unit:Remove() rebel:Remove()
    LC.Strongholds.off = {}
    LC.Running = runWas
end
Nov21_StrongholdTests()

function MapZoneMarkerTests()
-- the owner, 21 November, of the silo's territory: "why don't you just place them yourself?": an info_target named
-- lc_zone_<kind>_r<radius>_h<height>_<label> brings a zone of that kind once, as if placed with the editor
section("The map's zone markers: a map brings its own territories, once")
local path = LC.LayoutPath()
local groundWas = _groundFn
_groundFn = nil
local Z0 = Vector(-420000, 260000, 0)
local function MapZone(kind, at)
    for _, z in ipairs(LC.Zones) do if z.kind == kind and not z.grown and LCZ.Contains(z, at) then return z end end
end
local function Saved() return util.JSONToTable(_files[path] or "{}") or {} end
local before = _files[path]
local a0, m0 = LC.AddMapZones()
ok(a0 == 0 and m0 == 0 and _files[path] == before and not string.find(before or "", "zoneMarkers", 1, true),
    "a map without markers: nothing added, the layout as it was")
local k, r, h = LC.ParseZoneMarker("lc_zone_rebel_r700_h1800_silo")
local k2, r2, h2 = LC.ParseZoneMarker("LC_Zone_Infest_Yard")
ok(k == "rebel" and r == 700 and h == 1800 and k2 == "infest" and r2 == 300 and h2 == nil and LC.ParseZoneMarker("lc_hq_setup_silo") == nil,
    "a marker's name gives its kind, radius and height (radius 300 and a circle when left out)", k, r, h, k2, r2, h2)
-- a marker no zone of its kind covers brings one as the layout loads
local zones0, maxBlock = #(Saved().zones or {}), 0
for _, z in ipairs(LC.Zones) do if z.kind == "block" and not z.grown then maxBlock = math.max(maxBlock, z.group or 0) end end
local SILO, YARD = Z0 + Vector(0, 0, 8), Z0 + Vector(30000, 0, 8)
local silo = ents.Create("info_target") silo:SetName("lc_zone_rebel_r700_h1800_silotest") silo:SetPos(SILO) silo:Spawn()
local yard = ents.Create("info_target") yard:SetName("lc_zone_block_r400_yardtest") yard:SetPos(YARD) yard:Spawn()
LC.LoadData(false)
local zs, zy = MapZone("rebel", SILO), MapZone("block", YARD)
ok(zs and zs.box and zs.box.maxs.x - zs.box.mins.x == 1400 and zs.box.maxs.y - zs.box.mins.y == 1400
    and zs.box.mins.z == -16 and zs.box.maxs.z == 1800 and zs.group == 0,
    "a marker with a height brings a box of its kind: 2r wide, standing h tall from the floor under it (the editor's box)",
    zs and zs.box and tostring(zs.box.mins) .. " " .. tostring(zs.box.maxs))
ok(zy and not zy.box and zy.r == 400 and zy.pos.z == 0 and zy.group == maxBlock + 1,
    "without a height, the editor's circle on the floor under it; a housing block gets the next free number", zy and zy.r, zy and zy.group)
local sv = Saved()
local names = {}
for _, n in ipairs(sv.zoneMarkers or {}) do names[n] = true end
ok(#(sv.zones or {}) == zones0 + 2 and names["lc_zone_rebel_r700_h1800_silotest"] and names["lc_zone_block_r400_yardtest"],
    "both are saved with the layout, and the markers' names with them", #(sv.zones or {}), zones0)
-- one already there: none added
local hand = LC.AddZone(Z0 + Vector(60000, 0, 0), 500, "rebel", 0)
local inside = ents.Create("info_target") inside:SetName("lc_zone_rebel_r900_coveredtest") inside:SetPos(Z0 + Vector(60100, 0, 8)) inside:Spawn()
local n1 = #LC.Zones
local a1, m1 = LC.AddMapZones()
ok(a1 == 0 and m1 == 1 and #LC.Zones == n1 and LC.UsedZoneMarkers["lc_zone_rebel_r900_coveredtest"],
    "a marker a zone of its kind already covers adds none (that zone stands for it)", a1, m1)
-- deleted in the editor: it stays deleted
LC.RemoveZone(zs)
LC.LoadData(false)
local blocks = 0
for _, z in ipairs(LC.Zones) do if z.kind == "block" and not z.grown and LCZ.Contains(z, YARD) then blocks = blocks + 1 end end
ok(MapZone("rebel", SILO) == nil and blocks == 1,
    "a map zone the owner deleted does not come back when the layout loads again, and one kept is not doubled", blocks)
-- an unknown kind: left out, with a line in the errors file
local e0, lost0 = #_errors, LC.Err.lost or 0
local bogus = ents.Create("info_target") bogus:SetName("lc_zone_castle_r500_bogustest") bogus:SetPos(Z0 + Vector(90000, 0, 8)) bogus:Spawn()
local n2 = #LC.Zones
local a2, m2 = LC.AddMapZones()
local noted = (LC.Err.lost or 0) > lost0
for _, e in ipairs(LC.Err.list) do if string.find(e.msg, "lc_zone_castle_r500_bogustest", 1, true) then noted = true end end
ok(a2 == 0 and m2 == 0 and #LC.Zones == n2 and noted and not LC.UsedZoneMarkers["lc_zone_castle_r500_bogustest"],
    "a marker of a kind the editor doesn't place is left out, with a line in the errors file", a2, m2, noted)
for i = #_errors, e0 + 1, -1 do table.remove(_errors, i) end
silo:Remove() yard:Remove() inside:Remove() bogus:Remove()
LC.UsedZoneMarkers = {}
for _, at in ipairs({ { "block", YARD }, { "rebel", hand.pos } }) do -- (a reload makes new zone tables: found again)
    local z = MapZone(at[1], at[2])
    if z then LC.RemoveZone(z) end
end
_groundFn = groundWas
end
MapZoneMarkerTests()

function Nov21_BreakoutWithdrawTests()
    section("21 November: a breakout job whose prisoner is out already is taken back, not paid without its share")
    local runWas = LC.Running
    LC.Running = true
    local inmate = newPlayer("WithdrawInmate", "resistance", nil, 150)
    local breaker = newPlayer("WithdrawBreaker", "resistance", nil, 400)
