function Nov22_HQTests()
    section("22 November: the HQ's later stages: what only it does, what the Combine know, the raid, a ransack's papers")
    local B, H = LC.Base, LC.HQ
    local runWas = LC.Running
    LC.Running = true
    local setupWas = GetConVar("lc_base_setup_time"):GetInt()
    _setcvar("lc_base_setup_time", 3)
    B.Reset()
    local T0 = Vector(-310000, 310000, 0)
    local z = LC.AddZone(nil, nil, "rebel", 0, { mins = T0 + Vector(-500, -500, -16), maxs = T0 + Vector(500, 500, 192) })
    local boss = newPlayer("HQCommander", "resistance", nil, 99999)
    B.Poles()
    local pole = B.poles[LC.RebelLeader(z)]
    boss:SetPos(pole:GetPos() + Vector(40, 0, 0))
    LC.BasePoleUse(boss)
    for _ = 1, 10 do if LC.BaseState() == "live" then break end B.Tick(1) end
    local hp = LC.HQPos()
    LC.HQTick()
    ok(hp and LC.BaseState() == "live" and LC.HQKnowWords() == "nothing", "an HQ up: the Combine know nothing of it", tostring(LC.BaseState()))
    if not hp then B.Reset() LC.RemoveZone(z) boss:Remove() _setcvar("lc_base_setup_time", tostring(setupWas)) LC.Running = runWas return end
    -- what only the HQ does
    LC.RebelSpawnNote(boss)
    local back = LC.HQSpawnFor(boss)
    ok(back and back:Distance(hp) < 400, "a Resistance player last nearest it comes back at the HQ", back and back:Distance(hp))
    local sciHere = ents.Create("prop_physics") sciHere:SetPos(hp + Vector(120, 0, 0)) sciHere:Spawn()
    local sciFar = ents.Create("prop_physics") sciFar:SetPos(T0 + Vector(9000, 0, 0)) sciFar:Spawn()
    ok(LC.LabHQWhyNot(sciFar, LCS.LabById.bypass) and LC.LabHQWhyNot(sciFar, LCS.LabById.ied) and not LC.LabHQWhyNot(sciHere, LCS.LabById.ied)
        and not LC.LabHQWhyNot(sciFar, LCS.LabById.firebomb), "bypass charges and IEDs only from the HQ's own lab; the rest anywhere")
    local reb, rst = LC.SpawnRebel(hp + Vector(80, 80, 4), z)
    if reb then reb:SetHealth(20) end
    _run(5.5)
    ok(reb and reb:Health() > 20, "a wounded rebel NPC on its ground heals", reb and reb:Health())
    -- what the Combine know: only players move it
    local snitch = newPlayer("HQSnitch", "citizen")
    local kind
    for _, k in ipairs(LC.InformKinds) do if k.id == "hq" then kind = k end end
    ok(kind and kind.available(snitch) == nil, "someone who has never been there has nothing to tell")
    snitch:SetPos(hp + Vector(150, 0, 0))
    LC.HQTick()
    snitch:SetPos(T0 + Vector(12000, 0, 0))
    local site = kind and kind.available(snitch)
    ok(site ~= nil, "a player who has been on its ground can tell a unit")
    if site then kind.start(snitch, nil, site) end
    ok(LC.HQKnowWords() == "a district" and kind.available(snitch) == nil, "told: they know the district (and the same player can't tell it twice)", LC.HQKnowWords())
    local talker = newPlayer("HQTalker", "resistance", nil, 400)
    talker:SetPos(hp + Vector(100, 100, 0))
    LC.HQTick()
    local words, at = LC.InterrogationIntel(talker, "hideout", true)
    ok(at and at:Distance(hp) < 1 and LC.HQKnowWords() == "the street", "one of theirs who has been there, telling the truth in the cells: the HQ is the place, and they know the street", LC.HQKnowWords())
    -- a unit's scouting job, on the HQ's own ground
    local t
    for _, x in ipairs(LC.QuestTemplates) do if x.id == "cp_scouthq" then t = x end end
    local unit = newPlayer("HQScout", "cp")
    local zonesWas = LC.ZonesOfKind
    LC.ZonesOfKind = function(k) if k == "rebel" then return { z } end return zonesWas(k) end
    local spec = t and t.build(unit)
    LC.ZonesOfKind = zonesWas
    ok(spec and #spec.stages == 2 and spec.stages[2].search, "the units' scouting job: get there, search it by hand")
    if spec then spec.stages[2].onDone({ owner = unit, members = { unit }, data = {}, board = "Dispatch", title = spec.title, stages = spec.stages, stage = 2, id = 0 }) end
    ok(LC.HQKnowWords() == "the building", "scouted the HQ's own ground: they know the building", LC.HQKnowWords())
    -- a scanner: only one a unit sent counts
    H.know = 50
    local cityScanner = ents.Create("npc_cscanner") cityScanner:SetPos(hp + Vector(200, 0, 200)) cityScanner:Spawn()
    LC.RegisterNPC(cityScanner, "scanner")
    LC.HQScannerTick(5)
    ok(H.know == 50, "the city's own scanner over the HQ learns nothing")
    local heldWas = LC.RadioHeld
    LC.RadioHeld = function() return true end
    unit:SetPos(hp + Vector(300, 0, 0))
    local okS = LC.HQScan(unit, hp)
    LC.RadioHeld = heldWas
    local mine
    for sc in pairs(H.scanners) do mine = sc end
    if IsValid(mine) then mine:SetPos(hp + Vector(150, 0, 150)) end
    LC.HQScannerTick(5)
    ok(okS and H.know > 50 and H.know <= 50 + LC.HQScanMost, "a scanner a unit sends from the radio, with the pole in sight, learns", H.know)
    ok(LC.HQScanWhyNot(unit) ~= nil, "(one at a time per unit)")
    for sc, sdata in pairs(H.scanners) do if IsValid(sc) then LC.NPCs[sc] = nil sc:Remove() end if IsValid(sdata.target) then sdata.target:Remove() end end
    H.scanners = {}
    LC.NPCs[cityScanner] = nil cityScanner:Remove()
    -- the raid, ordered by the Administrator, beaten off
    H.know = 100
    local adm = newPlayer("HQAdministrator", "admin")
    ok(LC.HQRaidWhyNot(talker) ~= nil and LC.HQRaidWhyNot(adm) == nil, "at the building, the Administrator (only she) may order the raid")
    local addWas, authD = LC.LedgerAdd, nil
    LC.LedgerAdd = function(what, d, why) if what == "authority" then authD = d end end
    ok(LC.HQRaidOrder(adm) and H.raid ~= nil, "she orders it")
    local raidJob, defendJob
    for _, p in ipairs(LC.Postings.cp or {}) do if p.tmpl and p.tmpl.id == "cp_raidhq" and not p.dead then raidJob = p end end
    for _, p in ipairs(LC.Postings.resistance or {}) do if p.tmpl and p.tmpl.id == "res_defendhq" and not p.dead then defendJob = p end end
    ok(raidJob and defendJob, "every unit gets the raid on the board, the Resistance the defence", tostring(raidJob) .. " " .. tostring(defendJob))
    for _, npc in ipairs(H.raid.npcs) do if IsValid(npc) then npc:SetHealth(0) end end
    unit:SetPos(T0 + Vector(20000, 0, 0))
    _run(55)
    LC.LedgerAdd = addWas
    ok(H.raid == nil and LC.BaseState() == "live", "the raiders dead and no unit on the ground: the raid is beaten off, the flag still flying")
    ok(authD and authD < 0, "and it costs her authority", tostring(authD))
    ok(LC.HQRaidWhyNot(adm) ~= nil, "(not again so soon)")
    -- a ransack's papers
    local plist = LC.People.list
    local symp = {}
    for i = 1, 4 do local pr = LC.NewPerson("citizen") pr.rebel = true symp[i] = pr end
    local named = LC.HQRansackPapers()
    local marked = 0
    for _, pr in ipairs(symp) do if pr.suspect then marked = marked + 1 end end
    ok(#named == 3 and marked >= 1, "a ransack's papers name three sympathizers: suspects from then on", #named)
    for _, pr in ipairs(symp) do pr.alive = false end
    -- tidy
    if reb then LC.NPCs[reb] = nil reb:Remove() end
    sciHere:Remove() sciFar:Remove()
    B.Reset()
    LC.RemoveZone(z)
    boss:Remove() snitch:Remove() talker:Remove() unit:Remove() adm:Remove()
    H.know, H.raid, H.raidNext = 0, nil, 0
    _setcvar("lc_base_setup_time", tostring(setupWas))
    LC.Running = runWas
end
Nov22_HQTests()

function Nov23_LipSyncTests() -- (the owner, 23 November: "I REALLY need you to engineer a solution to NPCs not lip syncing")
    section("23 November: lip sync: a recording's own phoneme track is left to the game; else the server works the jaw with its loudness")
    local function U32(n) return string.char(n % 256, math.floor(n / 256) % 256, math.floor(n / 65536) % 256, math.floor(n / 16777216) % 256) end
    local function U16(n) return string.char(n % 256, math.floor(n / 256) % 256) end
    -- a .wav: 0.3 s quiet, 0.4 s loud, 0.3 s quiet (22050 Hz, 16-bit, mono), with or without a phoneme track
    local function Wav(track)
        local rate, parts = 22050, {}
        for i = 1, rate do
            local t = i / rate
            local v = (t > 0.3 and t < 0.7) and math.floor(12000 * math.sin(i * 0.05)) or 0
            if v < 0 then v = v + 65536 end
            parts[#parts + 1] = U16(v)
        end
        local pcm = table.concat(parts)
        local body = "WAVE" .. "fmt " .. U32(16) .. U16(1) .. U16(1) .. U32(rate) .. U32(rate * 2) .. U16(2) .. U16(16)
            .. "data" .. U32(#pcm) .. pcm
        if track then body = body .. "VDAT" .. U32(#track) .. track .. ((#track % 2 == 1) and "\0" or "") end
        return "RIFF" .. U32(#body) .. body
    end
    _files["sound/livingcity/citizens/lstest_hi_male1.wav"] = Wav(nil)
    _files["sound/livingcity/citizens/lstest_baked_male1.wav"] = Wav("VERSION 1.0\nPLAINTEXT\n{\nhi\n}\nWORDS\n{\n}\n")
    LC.LipSyncForget()
    local v = LC.LipSyncVoice("livingcity/citizens/lstest_hi_male1.wav")
    ok(v and not v.phonemes and v.env and #v.env >= 45, "a plain .wav: no track, its loudness read every 20 ms", v and v.env and #v.env)
    local env = v and v.env or {}
    ok(LC.LipSyncLevel(env, 0.1) < 0.1 and LC.LipSyncLevel(env, 0.5) > 0.8 and LC.LipSyncLevel(env, 0.85) < 0.1,
        "quiet where it is quiet, loud where it is loud", string.format("%.2f %.2f %.2f", LC.LipSyncLevel(env, 0.1), LC.LipSyncLevel(env, 0.5), LC.LipSyncLevel(env, 0.85)))
    local b = LC.LipSyncVoice(")sound/livingcity/citizens/lstest_baked_male1.wav")
    ok(b and b.phonemes == true, "a .wav with Faceposer's track (lipsync_bake.py) is known as one (the marks in front of a name ignored)")

    -- an .mp3: frames whose gains say loud, then frames coded as silence
    local function Frame(loud)
        local bytes = { 0xFF, 0xFB, 0x90, 0xC4 } -- (MPEG-1 layer III, 128 kbps, 44.1 kHz, mono: 417 bytes)
        for i = 5, 417 do bytes[i] = 0 end
        local function Put(off, n, val) -- side info starts at byte 5
            for k = n - 1, 0, -1 do
                local bitAt = off + (n - 1 - k)
                local idx = 5 + math.floor(bitAt / 8)
                if math.floor(val / 2 ^ k) % 2 == 1 then bytes[idx] = bytes[idx] + 2 ^ (7 - bitAt % 8) end
            end
        end
        for g = 0, 1 do
            local off = 18 + g * 59
            if loud then Put(off, 12, 900) Put(off + 12, 9, 200) Put(off + 21, 8, 170) end
        end
        local s = {}
        for i, x in ipairs(bytes) do s[i] = string.char(x) end
        return table.concat(s)
    end
    local mp3 = {}
    for i = 1, 40 do mp3[i] = Frame(i > 10 and i <= 25) end -- (26 ms a frame: loud from about 0.26 s to 0.65 s)
    _files["sound/livingcity/citizens/lstest_mp_male1.mp3"] = table.concat(mp3)
    local lv = LC.LipSyncMp3Levels(_files["sound/livingcity/citizens/lstest_mp_male1.mp3"])
    ok(#lv == 80 and lv[1][2] < 0 and lv[30][2] > 0, "an .mp3's frames are read without decoding it (two pieces a frame, silence known)", #lv)
    local m = LC.LipSyncVoice("livingcity/citizens/lstest_mp_male1.mp3")
    local me = m and m.env or {}
    ok(LC.LipSyncLevel(me, 0.1) < 0.1 and LC.LipSyncLevel(me, 0.45) > 0.8 and LC.LipSyncLevel(me, 0.9) < 0.1, "and its loudness follows",
        string.format("%.2f %.2f %.2f", LC.LipSyncLevel(me, 0.1), LC.LipSyncLevel(me, 0.45), LC.LipSyncLevel(me, 0.9)))

    -- a .wav beside an .mp3 of the same name is the one used
    local kept = LC.PreferWav({ "say_a_male1.mp3", "say_a_male1.wav", "say_b_male1.mp3", "c.OGG", "c.wav", "d.WAV", "d.mp3" })
    ok(table.concat(kept, " ") == "say_a_male1.wav say_b_male1.mp3 c.wav d.WAV", "an .mp3 or .ogg with a .wav of its name is left out", table.concat(kept, " "))

    -- the face: a citizen with a jaw, worked on the server (sent to every player with the NPC)
    local function Face(ent, flexes)
        local w = {}
        ent.GetFlexNum = function() return flexes and 40 or 0 end
        ent.GetFlexIDByName = function(_, n) return flexes and flexes[n] or nil end
        ent.GetFlexBounds = function() return 0, 1 end
        ent.GetFlexWeight = function(_, id) return w[id] or 0 end
        ent.SetFlexWeight = function(_, id, x) w[id] = x end
        return w
    end
    local npc = ents.Create("npc_citizen") npc:SetPos(Vector(-154000, -154000, 0)) npc:Spawn()
    npc:SetModel("models/humans/group01/male_lstest.mdl")
    local w = Face(npc, { jaw_drop = 3, right_part = 5, left_part = 6 })
    ok(LC.MarkTalking(npc, "livingcity/citizens/lstest_hi_male1.wav") == true and LC.LipSyncTalking[npc] ~= nil, "a citizen saying a plain recording: the server works their face")
    local from = LC.LipSyncTalking[npc] and LC.LipSyncTalking[npc].from or CurTime()
    local function JawAt(t) for k = 0, 4 do LC.LipSyncWork(from + t - 0.08 + k * 0.02) end return w[3] or 0 end
    local early, mid, late = JawAt(0.1), JawAt(0.5), JawAt(0.92)
    ok(early < 0.1 and mid > 0.4 and late < 0.1, "the jaw shut while it is quiet, open while it is loud (worked a little ahead: players see faces a moment late)",
        string.format("%.2f %.2f %.2f", early, mid, late))
    JawAt(0.5)
    ok((w[5] or 0) > 0.2 and (w[6] or 0) > 0.2, "the lips part with it", tostring(w[5]))
    LC.LipSyncWork(from + 5)
    ok(LC.LipSyncTalking[npc] == nil and (w[3] or 0) == 0, "and close when the line is over")
    -- a baked one is the game's: the server keeps off it
    ok(LC.MarkTalking(npc, "livingcity/citizens/lstest_baked_male1.wav") == true and LC.LipSyncTalking[npc] == nil, "a recording with its phoneme track: left to the game's own lip sync")
    -- a recording that can't be read still moves the mouth (a talking pattern)
    ok(LC.LipSyncStart(npc, "livingcity/citizens/lstest_nofile_male1.ogg", 2) == true, "a recording that can't be read: the server still works the jaw")
    local opened = 0
    for k = 1, 30 do LC.LipSyncWork(from + 0.05 * k) if (w[3] or 0) > 0.05 then opened = opened + 1 end end
    ok(opened >= 5, "in a talking pattern", opened)
    LC.LipSyncWork(from + 60)
    -- a mask has no jaw
    local cop = ents.Create("npc_metropolice") cop:SetPos(Vector(-154100, -154000, 0)) cop:Spawn()
    cop:SetModel("models/police_lstest.mdl")
    Face(cop, nil)
    ok(LC.LipSyncStart(cop, "livingcity/citizens/lstest_hi_male1.wav", 2) == false, "a metrocop's mask: nothing to move")
    npc:Remove() cop:Remove()
    for _, k in ipairs({ "lstest_hi_male1.wav", "lstest_baked_male1.wav", "lstest_mp_male1.mp3" }) do _files["sound/livingcity/citizens/" .. k] = nil end
    LC.LipSyncForget()
end
Nov23_LipSyncTests()

function Nov24_BarnacleLiftTests() -- (the owner, 22 November: barnacles "just don't pull me up")
    section("24 November: a barnacle lifts the player it has caught")
    local HELD = EFL_IS_BEING_LIFTED_BY_BARNACLE or 1048576
    local p = _makeplayer("Barnacled", Vector(-156000, -156000, 0))
    local held = false
    p.IsEFlagSet = function(_, f) return held and f == HELD end
    local b = ents.Create("npc_barnacle") b:SetPos(Vector(-156000, -156000, 400)) b:Spawn()
    b.hp = 35
    local far = ents.Create("npc_barnacle") far:SetPos(Vector(-156500, -156000, 400)) far:Spawn()
    far.hp = 35
    LC.BarnacleHoldTick()
    ok(not IsValid(p:GetNW2Entity("lc_barnacle")), "nobody caught: nobody lifted")
    local mv = { o = p:GetPos(), v = Vector(0, 0, -300) }
    function mv:GetOrigin() return self.o end
    function mv:SetOrigin(x) self.o = x end
    function mv:SetVelocity(x) self.v = x end
    ok(hook.Run("Move", p, mv) == nil and mv.o.z == 0, "their movement is their own")
    held = true
    LC.BarnacleHoldTick()
    ok(p:GetNW2Entity("lc_barnacle") == b, "caught: the barnacle over them holds them, not one further off")
    local took = hook.Run("Move", p, mv)
    ok(took == true and mv.o.z > 0 and mv.o.z <= 8.01 and mv.v.z == 0, "each moment they rise a little, not falling back", mv.o.z)
    for _ = 1, 80 do hook.Run("Move", p, mv) end
    ok(math.abs(mv.o.z - 306) < 0.01, "up to its mouth and no further", mv.o.z)
    p:SetPos(mv.o)
    local hp = p:Health()
    LC.BarnacleHoldTick()
    ok(p:Health() == hp, "at the mouth: the barnacle's own bite is waited for")
    _run(3)
    ok(p:Health() < hp, "a barnacle that never bites: the server bites for it", p:Health())
    held = false
    LC.BarnacleHoldTick()
    ok(not IsValid(p:GetNW2Entity("lc_barnacle")) and hook.Run("Move", p, mv) == nil, "let go (or the barnacle killed): they drop")
    b:Remove() far:Remove()
    p.valid = false
end
Nov24_BarnacleLiftTests()

function Nov24_PumphouseWaterTests() -- (the owner, 24 November: "the pumphouse nearest a rebel zone allows or cuts that zone's water")
    section("24 November: the pumphouse nearest a rebel territory is its water")
    local T0 = Vector(-158000, -158000, 0)
    local z = LC.AddZone(nil, nil, "rebel", 0, { mins = T0 + Vector(-500, -500, -16), maxs = T0 + Vector(500, 500, 192) })
    local near = ents.Create("func_rotating") near:SetPos(T0 + Vector(2000, 0, 0)) near:SetName("lc_pump_wheel") near:Spawn()
    local far = ents.Create("func_rotating") far:SetPos(T0 + Vector(9000, 0, 0)) far:SetName("lc_pump_wheel") far:Spawn()
    local p = newPlayer("Thirsty", "resistance", nil, 200)
    p:SetPos(T0)
    ok(LC.WaterCut(T0) == false, "the pumps running: water")
    hook.Run("AcceptInput", far, "Stop", p, p)
    ok(LC.WaterCut(T0) == false, "a pumphouse further off stopped: still water")
    hook.Run("AcceptInput", near, "Stop", p, p)
    ok(LC.WaterCut(T0) == true and LC.NearSink(p) == false, "the nearest one stopped: no water on that rebel ground, and no bottle filled")
    ok(LC.WaterCut(T0 + Vector(0, 3000, 0)) == false, "off rebel ground the taps still run")
    hook.Run("AcceptInput", near, "Start", p, p)
    ok(LC.WaterCut(T0) == false, "started again: water again")
    hook.Run("AcceptInput", near, "Stop", p, p)
    hook.Run("PostCleanupMap")
    ok(LC.WaterCut(T0) == false, "the map cleaned up starts its pumps again")
    LC.RemoveZone(z) near:Remove() far:Remove() p:Remove()
end
Nov24_PumphouseWaterTests()

function Nov24_BaseVehicleTests() -- (the owner, 20 November: "each base has one vehicle available when the base is setup there")
    section("24 November: the live base has one vehicle at the spot placed for it")
    local V, B = LC.BaseVehicle, LC.Base
    local T0 = Vector(-160000, -160000, 0)
    local sWas, liveWas, waterWas = B.S, LC.BaseLive, LC.InWater
    local zone = { kind = "rebel", pos = T0, r = 500 }
    local wet = false
    LC.InWater = function() return wet end
    B.S = {}
    LC.BaseLive = function() return B.S.state == "live" and zone or nil end
    local near = LC.AddPoint(T0 + Vector(800, 0, 0), 90, "basevehicle", 0)
    local far = LC.AddPoint(T0 + Vector(9000, 0, 0), 0, "basevehicle", 0)
    V.Tick()
    ok(not IsValid(V.ent), "no base: no vehicle")
    B.S = { state = "live", zone = zone, pos = T0 }
    V.Tick()
    ok(IsValid(V.ent) and V.ent:GetClass() == "prop_vehicle_jeep" and V.ent:GetPos():Distance(near.pos) < 40, "the base live: a buggy at the spot nearest its flag",
        IsValid(V.ent) and V.ent:GetClass())
    local first = V.ent
    V.Tick()
    ok(V.ent == first, "one, not one more each time")
    -- driven off and left: back at its spot after five minutes
    first:SetPos(T0 + Vector(3000, 0, 0))
    V.Tick()
    ok(V.ent == first, "left somewhere: it stays there a while")
    local driver = newPlayer("BaseDriver", "resistance", nil, 200)
    first.GetDriver = function() return driver end
    _run(310)
    ok(V.ent == first, "someone at the wheel: it is theirs however long")
    first.GetDriver = function() return nil end
    _run(310)
    ok(IsValid(V.ent) and V.ent ~= first and V.ent:GetPos():Distance(near.pos) < 40, "left empty five minutes: back at its spot")
    -- the base gone: the vehicle goes with it, once nobody sits in it
    local second = V.ent
    second.GetDriver = function() return driver end
    B.S = {}
    V.Tick()
    ok(V.ent == second, "the flag down with someone driving: they keep it until they get out")
    second.GetDriver = function() return nil end
    V.Tick()
    ok(not IsValid(V.ent) and not IsValid(second), "empty: gone with the base")
    -- a spot in water is the airboat's; a base out of reach of every spot has none
    wet = true
    B.S = { state = "live", zone = zone, pos = T0 }
    V.Tick()
    ok(IsValid(V.ent) and V.ent:GetClass() == "prop_vehicle_airboat", "a spot on water: the airboat", IsValid(V.ent) and V.ent:GetClass())
    V.Remove()
    B.S = { state = "live", zone = zone, pos = T0 + Vector(0, 30000, 0) }
    V.Tick()
    ok(not IsValid(V.ent), "a base with no spot within reach: none")
    V.Remove()
    LC.RemovePoint(near) LC.RemovePoint(far) driver:Remove()
    B.S, LC.BaseLive, LC.InWater = sWas, liveWas, waterWas
end
Nov24_BaseVehicleTests()

function Nov24_ThumperAntlionTests() -- (the owner's long-term list, 5: "thumpers keep them off ... which a saboteur can switch off")
    section("24 November: antlions dig up at a stopped thumper's burrow")
    local A = LC.Antlions
    local T0 = Vector(-162000, -162000, 0)
    local th = ents.Create("prop_thumper") th:SetPos(T0) th:SetName("lc_thumper_head") th:Spawn()
    local burrow = ents.Create("info_target") burrow:SetPos(T0 + Vector(400, 0, 0)) burrow:SetName("lc_thumper_burrow") burrow:Spawn()
    local p = newPlayer("Saboteur", "resistance", nil, 200)
    p:SetPos(T0 + Vector(300, 300, 0))
    local function Out() local n = 0 for e in pairs(A.out) do if IsValid(e) and e:Health() > 0 then n = n + 1 end end return n end
    hook.Run("AcceptInput", th, "Enable", th, th)
    _run(40)
    ok(Out() == 0, "the thumper running: no antlions")
    hook.Run("AcceptInput", th, "Disable", p, p)
    _run(10)
    ok(Out() == 0, "stopped: not at once")
    _run(30)
    ok(Out() == 2, "then they dig up at its burrow, two at a time", Out())
    local near = true
    for e in pairs(A.out) do if e:GetPos():Distance(burrow:GetPos()) > 60 then near = false end end
    ok(near, "at the burrow's mouth")
    for e in pairs(A.out) do e:SetHealth(0) end
    _run(20)
    ok(Out() == 2, "killed: the next two come", Out())
    for e in pairs(A.out) do e:SetHealth(0) end
    A.stopped[th].pool, A.stopped[th].regenAt = 0, CurTime() + 25
    _run(10)
    ok(Out() == 0, "the pool empty: a breather", Out())
    _run(60)
    ok(Out() >= 1, "lingering brings more", Out())
    hook.Run("AcceptInput", th, "Enable", p, p)
    local left = {}
    for e in pairs(A.out) do if IsValid(e) and e:Health() > 0 then left[#left + 1] = e e.Fire = function(self, what) if what == "BurrowAway" then self:Remove() end end end end
    _run(30)
    ok(#left >= 1 and IsValid(left[1]), "started again: those out are left to the thumper for a minute")
    _run(40)
    ok(Out() == 0 and not IsValid(left[1]), "then they dig themselves away, and no more come", Out())
    th:Remove() burrow:Remove() p:Remove()
    A.stopped, A.out, A.startedAt = {}, {}, nil
end
Nov24_ThumperAntlionTests()

function Nov24_CutLineTests() -- (the owner, 20 November: a wrecked line causes "a problem with supplies ... the combine need to go out and repair it")
    section("24 November: a train line cut by a bomb costs the city its supplies until it is repaired")
    _setcvar("lc_ledger", 1)
    local s = LC.Ledger()
    local was = { supply = s.supply, combine = s.combine, resistance = s.resistance, news = #s.news }
    local wreckedWas = LC.TracksWrecked
    s.supply, s.combine, s.resistance = 50, 50, 50
    local cut = false
    LC.TracksWrecked = function() return cut end
    LC.LedgerTracksTick()
    ok(s.supply == 50, "the lines whole: nothing lost")
    cut = true
    hook.Run("LivingCityTracksWrecked", "lc_train_test", Vector(), nil)
    ok(s.supply == 46 and s.resistance == 52 and s.combine == 49, "cut: the load is lost at once", s.supply)
    ok(string.find(s.news[#s.news] or "", "train line", 1, true) ~= nil, "and the bulletin says so")
    LC.LedgerTracksTick() LC.LedgerTracksTick()
    ok(s.supply == 44, "left wrecked: the stores keep running down", s.supply)
    cut = false
    hook.Run("LivingCityTracksRepaired", "lc_train_test", nil)
    LC.LedgerTracksTick()
    ok(s.supply == 44 and s.combine == 50, "repaired: it stops", s.supply)
    LC.TracksWrecked = wreckedWas
    s.supply, s.combine, s.resistance = was.supply, was.combine, was.resistance
    while #s.news > was.news do table.remove(s.news) end
end
Nov24_CutLineTests()

function Nov25_ChapterTests() -- (the owner, 25 November: the rocket's wave "kills all the combine and disables all their equipment ... a role reversal for a roleplay server story chapter")
    section("25 November: the chapter, the city falls to the Resistance")
    local C = LC.Chapter
    local T0 = Vector(-172000, -172000, 0)
    local N0 = T0 + Vector(6000, 0, 0)
    local FILE = "livingcity/" .. game.GetMap() .. "_chapter.json"
    local fileWas, sWas, eventWas = _files[FILE], C.S, LC.Event
    local cvWas = { GetConVar("lc_chapter"):GetString(), GetConVar("lc_chapter_hold_minutes"):GetString(), GetConVar("lc_chapter_cooldown_minutes"):GetString(),
        GetConVar("lc_ledger"):GetString() }
    _setcvar("lc_ledger", 1)
    local led = LC.Ledger()
    local ledWas = { combine = led.combine, authority = led.authority, resistance = led.resistance, districts = table.Copy(led.districts),
        crackdown = table.Copy(led.crackdown), liberated = table.Copy(led.liberated), news = #led.news }
    local aliveWas = {}
    for _, p in ipairs(player.GetAll()) do aliveWas[p] = p:Alive() end
    local noticeWas, waveWas = LC.Notice, LC.RebelWave
    local told, waves = {}, 0
    LC.Notice = function(p, _, title, text) if title == "The Nexus" then told[#told + 1] = { p, text } end end
    LC.RebelWave = function() waves = waves + 1 return 0, {} end
    local began, ended = 0, 0
    hook.Add("LivingCityChapterBegan", "ChapterTests", function() began = began + 1 end)
    hook.Add("LivingCityChapterEnded", "ChapterTests", function() ended = ended + 1 end)
    if LC.Event then LC.EndEvent(true) end
    C.S = { state = "normal", elapsed = 0, cooldown = 0, lock = false }
    C.retake, C.pendingAt, C.pendingBy = nil, nil, nil
    local function toldTo(p, from) for i = (from or 0) + 1, #told do if told[i][1] == p then return told[i][2] end end return nil end

    ok(cvWas[1] == "0" and cvWas[2] == "60" and cvWas[3] == "120", "off by default; an hour before the retake, two before it can start again", table.concat(cvWas, " ", 1, 3))
    ok(LC.ChapterReversed() == false and GetGlobal2Bool("lc_chapter", false) ~= true, "the city is the Combine's")

    -- who is there
    local unit, ota, her = newPlayer("ChapterUnit", "cp"), newPlayer("ChapterOverwatch", "ota"), newPlayer("ChapterAdministrator", "admin")
    local lt, private, cit = newPlayer("ChapterLieutenant", "resistance", nil, 99999), newPlayer("ChapterPrivate", "resistance", nil, 0), newPlayer("ChapterCitizen", "citizen")
    local staff = newPlayer("ChapterStaff", "citizen")
    staff.admin = true
    for i, p in ipairs({ unit, ota, her, lt, private, cit, staff }) do p:SetPos(T0 + Vector(0, 3000 + i * 80, 0)) end
    local nexus = LC.AddZone(nil, nil, "combine", 0, { mins = N0 + Vector(-400, -400, -16), maxs = N0 + Vector(400, 400, 192) })
    local desk = LC.AddPoint(N0, 0, "desk", 0)
    local rsp = LC.AddPoint(T0 + Vector(0, -4000, 0), 0, "rspawn", 0)
    local door = ents.Create("func_door") door.mapid = 25111 door:SetPos(T0 + Vector(0, -800, 0))
    LC.SetDoorTag(door, "cp")
    local plain = ents.Create("func_door") plain.mapid = 25112 plain:SetPos(T0 + Vector(0, -1200, 0))
    local bank = ents.Create("lc_powerbank") bank:SetPos(T0 + Vector(0, 800, 0))
    local field = ents.Create("lc_forcefield") field:SetPos(T0 + Vector(100, 800, 0))
    field.lcForcefield = true
    local turret = ents.Create("npc_turret_floor") turret:SetPos(T0 + Vector(0, 1400, 0)) turret:Spawn()
    local monitor = ents.Create("lc_monitor") monitor:SetPos(T0 + Vector(0, 1800, 0))
    LC.CheckpointTick(CurTime()) LC.RefreshPower()
    ok(door.locked == true and not door.isOpen and not field:GetNW2Bool("lc_nopower", false) and not monitor:GetNW2Bool("lc_nopower", false),
        "(before: a Combine door locked, a forcefield and a monitor with power)")
    ok(LC.MayEnterCombine(cit) == false, "(before: a Combine-only zone is not a citizen's to walk into)")

    -- the launch: only with the setting on, only a Lieutenant or Commander at the button
    local relay = ents.Create("logic_relay") relay:SetName("lc_rocket_launch") relay:SetPos(T0)
    hook.Run("AcceptInput", relay, "Trigger", lt, lt)
    ok(C.pendingAt == nil, "lc_chapter 0: the launch is only a launch")
    _setcvar("lc_chapter", 1)
    hook.Run("AcceptInput", relay, "Trigger", private, private)
    ok(C.pendingAt == nil, "a rebel of no rank at the button: only a launch")
    hook.Run("AcceptInput", relay, "Trigger", lt, lt)
    ok(C.pendingAt ~= nil and not LC.ChapterReversed(), "a Lieutenant or Commander at it: the wave is coming, and not here yet")
    _run(C.COUNTDOWN + C.CLIMB - 4)
    ok(not LC.ChapterReversed(), "through the countdown and the climb: nothing yet")
    local cop = LC.ManpowerFree(LC.Spawners.cop, T0 + Vector(400, 0, 0))
    local soldier = LC.ManpowerFree(LC.Spawners.soldier, T0 + Vector(480, 0, 0))
    local scanner = LC.Spawners.scanner(T0 + Vector(560, 0, 0))
    local hack = ents.Create("npc_manhack") hack:SetPos(T0 + Vector(640, 0, 0)) hack:Spawn()
    local rebel = LC.ManpowerFree(LC.SpawnRebel, T0 + Vector(400, 9000, 0))
    local citizen = ents.Create("npc_citizen") citizen:SetPos(T0 + Vector(480, 9000, 0)) citizen:Spawn()
    ok(IsValid(cop) and IsValid(soldier) and IsValid(scanner) and IsValid(rebel), "(a unit, a soldier, a scanner and a fighter on the street)")
    unit:SetArmor(50) her:SetArmor(60)
    net.sent = {}
    _run(6)
    ok(LC.ChapterReversed() and began == 1 and GetGlobal2Bool("lc_chapter", false) == true, "the wave: the city is the Resistance's", "began " .. began)
    ok(_lastnet("lc_chapter_wave") ~= nil and #told == 0, "everyone's game draws it, and nothing is said")

    -- what it kills
    ok(not (IsValid(cop) and cop:Health() > 0) and not (IsValid(soldier) and soldier:Health() > 0) and not (IsValid(scanner) and scanner:Health() > 0)
        and not (IsValid(hack) and hack:Health() > 0), "every Combine NPC dies: unit, soldier, scanner, manhack")
    ok(not unit:Alive() and not ota:Alive(), "and every Civil Protection and Overwatch player")
    ok(unit:GetNW2String("lcf_faction", "") == "cp" and ota:GetNW2String("lcf_faction", "") == "cp", "who are still who they were (no character ends with the wave)")
    ok(her:Alive() and her:Armor() == 0, "the Administrator lives, her vest's charge gone", tostring(her:Armor()))
    ok(lt:Alive() and private:Alive() and cit:Alive() and IsValid(rebel) and rebel:Health() > 0 and IsValid(citizen) and citizen:Health() > 0,
        "rebels and citizens are untouched")
    _run(5)
    local left = 0
    for npc, st in pairs(LC.NPCs) do if IsValid(npc) and (st.role == "cop" or st.role == "soldier" or st.role == "scanner") then left = left + 1 end end
    ok(left == 0 and not IsValid(hack), "none of them is left standing or lying about", left .. " left")

    -- machines and doors
    ok(field:GetNW2Bool("lc_nopower", false) and monitor:GetNW2Bool("lc_nopower", false) and LC.PowerBankLive(bank) == false, "forcefields, power banks and monitors are dead")
    ok(turret.lcChapterOff == true and turret.fired[#turret.fired] == "Disable", "a turret is switched off")
    ok(LC.TurretMayUse(lt, nil) == false and LC.CanLinkScanner(her, nil) == false, "nobody mans a mounted gun or flies a scanner")
    ok(door.isOpen == true and door.locked == true and door.lcHeldOpen == true, "a Combine door stands open, locked open")
    ok(not plain.lcChapterOpen, "an ordinary door is left as it was")
    door.isOpen = false
    _run(C.KEEP_EVERY + 2)
    ok(door.isOpen == true, "shut by the map: open again before long")

    -- the streets
    ok(LC.ManpowerCan("cp") == false and LC.ManpowerCan("ota") == false and LC.SpawnCop(T0) == nil and LC.SpawnSoldier(T0) == nil and LC.Spawners.scanner(T0) == nil,
        "no unit, soldier or scanner comes out")
    ok(LC.FlyDropship({ pos = T0 }) == nil and LC.SpawnCremator(T0, "models/x.mdl") == nil, "no dropship, no Cremator")
    _run(20)
    left = 0
    for npc, st in pairs(LC.NPCs) do if IsValid(npc) and (st.role == "cop" or st.role == "soldier" or st.role == "scanner") then left = left + 1 end end
    ok(left == 0, "and the city sends none by itself", left .. " came")
    cit.chat = {}
    local spoke, speaksWas = 0, LC.OverwatchSpeaks
    LC.OverwatchSpeaks = function() spoke = spoke + 1 end
    LC.Announce("curfew")
    LC.OverwatchSpeaks = speaksWas
    ok(spoke == 0 and #cit.chat == 0, "the PA is silent")
    ok(LC.StartEvent("curfew") == false and LC.Event == nil, "no curfew starts")
    ok(LC.MayEnterCombine(cit) == true and LC.SocioAuto() == "green", "a Combine-only zone is nobody's to trespass in; sociostability judges nothing")
    local mine = true
    for _, n in ipairs(LC.BlockNumbers()) do if LC.DistrictOwner(n) ~= "resistance" then mine = false end end
    ok(mine and led.combine <= 5 and led.authority <= 5 and led.resistance >= math.min(100, ledWas.resistance + 40),
        "every district is the Resistance's, and the ledger swings hard", string.format("combine %d authority %d resistance %d", led.combine, led.authority, led.resistance))

    -- a unit in the Resistance's city
    unit.alive, ota.alive, unit.hp, ota.hp = true, true, 100, 100
    unit:SetArmor(40)
    _run(1.5)
    ok(unit:Armor() == 0 and LC.VestCap(unit) == 0 and LC.ChargeVest(unit, 25) == 0 and LC.VestCap(her) > 0, "a unit's vest holds no charge and takes none")
    local battery = ents.Create("item_battery")
    ok(hook.Run("PlayerCanPickupItem", unit, battery) == false and hook.Run("PlayerCanPickupItem", cit, battery) ~= false, "a suit battery is no use to them")
    battery:Remove()
    local swepWas = SWEP
    SWEP = { Primary = {}, Secondary = {} }
    assert(loadstring(_WEAPONSRC["weapons/weapon_lc_baton.lua"], "weapon_lc_baton"))()
    local snd, swings, arrests = {}, 0, 0
    local baton = setmetatable({ GetOwner = function() return unit end, EmitSound = function(_, s) snd[#snd + 1] = s end,
        SetNextPrimaryFire = function() end, SetNextSecondaryFire = function() end, SendWeaponAnim = function() end }, { __index = SWEP })
    SWEP = swepWas
    local arrestWas, animWas = LC.BatonArrest, unit.SetAnimation
    LC.BatonArrest = function() arrests = arrests + 1 return false end
    unit.SetAnimation = function() swings = swings + 1 end
    unit.chat = {}
    baton:SecondaryAttack()
    ok(arrests == 0 and #snd == 2 and string.find(snd[1], "empty", 1, true) and string.find(snd[2], "spark", 1, true) and #unit.chat == 0,
        "the baton's arrest: a dry click and a fizzle, nothing else", table.concat(snd, " "))
    snd = {}
    baton:PrimaryAttack()
    ok(swings == 0 and #snd == 2, "and its blow the same")
    ok(unit:GetNW2Bool("lc_chapter_mask", false) == true and ota:GetNW2Bool("lc_chapter_mask", false) == true and not her:GetNW2Bool("lc_chapter_mask", false)
        and not lt:GetNW2Bool("lc_chapter_mask", false), "a unit's mask glitches (F2 has the line); nobody else's")
    ok(LC.GasMasked(unit) == true, "(masked, it still keeps the gas out)")
    ok(LC.TargetActions.chaptermask(unit) == true and unit:GetNW2Bool("lc_chapter_mask", false) == false and LC.ChapterMaskOff(unit) == true,
        "F2 > Take off the mask: no more glitch")
    ok(not LC.GasMasked(unit) and LC.GasMasked(ota) == true and LC.TargetActions.chaptermask(unit) == false and LC.TargetActions.chaptermask(lt) == false,
        "and no more of what it kept out; once, and only a unit")

    -- where they come back
    local function back(p)
        p.alive = true
        p:SetPos(T0 + Vector(0, 20000, 0))
        p:Spawn()
        _run(0.3)
        return p:GetPos()
    end
    local function atOne(pos, kind)
        for _, pt in ipairs(LC.PointsOfKind(kind)) do if pt.pos:Distance(pos) < 40 then return true end end
        return false
    end
    ok(atOne(back(unit), "rspawn"), "no holdout placed: a unit comes back at a Resistance spawn point")
    ok(LC.CombineZoneAt(back(lt)) ~= nil or LC.NearCombineZone(lt:GetPos()) ~= nil, "and a rebel on the units' own ground")
    local holdout = LC.AddPoint(T0 + Vector(0, -9000, 0), 0, "choldout", 0)
    ok(holdout ~= nil and back(unit):Distance(holdout.pos) < 40 and back(ota):Distance(holdout.pos) < 40, "a Combine holdout placed with the editor: units come back there")
    ok(not (lt:GetPos():Distance(holdout.pos) < 40) and LC.ChapterSpawn(lt) == false and LC.ChapterSpawn(cit) == false, "and the Resistance where it always did")

    -- kept over a restart
    LC.ChapterSave()
    local t = util.JSONToTable(_files[FILE] or "") or {}
    ok(t.state == "reversed" and t.lock == false and (t.elapsed or 0) > 20, "saved in data/" .. FILE, tostring(_files[FILE]))
    C.S = { state = "normal", elapsed = 0, cooldown = 0, lock = false }
    door.lcChapterOpen, door.lcHeldOpen, door.isOpen = nil, nil, false
    LC.ChapterReload()
    ok(LC.ChapterReversed() and C.S.elapsed > 20 and door.isOpen == true, "read back: still the Resistance's, its doors open again")

    -- the Combine take it back
    _setcvar("lc_chapter_hold_minutes", 5)
    unit:SetPos(N0) ota:SetPos(N0 + Vector(60, 0, 0))
    _run(3)
    ok(C.retake == nil and #told == 0, "the Nexus held before lc_chapter_hold_minutes are up: nothing")
    C.S.elapsed = 5 * 60
    ota:SetPos(T0)
    _run(3)
    ok(C.retake == nil, "one unit in it, with a full server: not enough")
    ota:SetPos(N0 + Vector(60, 0, 0))
    _run(2)
    ok(C.retake ~= nil and toldTo(unit) ~= nil and toldTo(her) == toldTo(unit) and toldTo(lt) ~= nil and toldTo(lt) ~= toldTo(unit) and toldTo(cit) == nil,
        "two in it: the hold starts, one line to each side", tostring(toldTo(unit)) .. " / " .. tostring(toldTo(lt)))
    _run(12)
    local prog = C.retake and C.retake.prog or -1
    ok(prog > 9 and waves >= 1, "its clock runs, and the fighters come for the Nexus", string.format("%.1f s, %d waves", prog, waves))
    unit:SetPos(T0) ota:SetPos(T0)
    local wavesThen = waves
    _run(10)
    ok(C.retake ~= nil and math.abs(C.retake.prog - prog) < 0.01 and waves == wavesThen, "nobody of theirs in it: the clock stands, and no wave comes")
    unit:SetPos(N0)
    _run(5)
    ok(C.retake ~= nil and C.retake.prog > prog + 3, "one unit back in it: on it goes")
    local n = #told
    if C.retake then C.retake.prog = C.RETAKE_SECS - 2 end
    _run(4)
    ok(not LC.ChapterReversed() and ended == 1 and C.retake == nil and GetGlobal2Bool("lc_chapter", false) == false, "held to the end: the city is the Combine's again", "ended " .. ended)
    ok(toldTo(unit, n) ~= nil and toldTo(lt, n) ~= nil and toldTo(lt, n) ~= toldTo(unit, n) and toldTo(cit, n) == nil, "one line to each side again")
    ok(door.isOpen == false and door.locked == true and not door.lcHeldOpen and not door.lcChapterOpen, "Combine doors shut and lock again")
    LC.CheckpointTick(CurTime())
    ok(not field:GetNW2Bool("lc_nopower", false) and not monitor:GetNW2Bool("lc_nopower", false) and LC.PowerBankLive(bank) == true
        and turret.lcChapterOff == nil and turret.fired[#turret.fired] == "Enable", "the machines come back")
    ok(LC.VestCap(unit) > 0 and not unit:GetNW2Bool("lc_chapter_mask", false) and not LC.ChapterMaskOff(unit) and LC.MayEnterCombine(cit) == false,
        "vests charge, masks work, the Combine's ground is the Combine's")
    snd = {}
    LC.Try(baton.SecondaryAttack, baton)
    ok(#snd == 0, "the baton works again")
    LC.BatonArrest, unit.SetAnimation = arrestWas, animWas
    local back1 = LC.Spawners.scanner(T0 + Vector(560, 0, 0))
    ok(IsValid(back1), "the Combine's own come out again")
    if IsValid(back1) then back1:Remove() end
    local contested = true
    for _, b in ipairs(LC.BlockNumbers()) do if LC.DistrictOwner(b) ~= "contested" then contested = false end end
    ok(contested and led.combine >= 30, "the districts are contested, the Combine's strength back", "combine " .. led.combine)
    ok(not atOne(back(unit), "choldout"), "and units come back where they always did")

    -- the cooldown, and staff
    ok(C.S.cooldown > 119 * 60 and select(2, LC.ChapterLaunch(lt)) == "cooldown" and C.pendingAt == nil, "it cannot start again for lc_chapter_cooldown_minutes", tostring(C.S.cooldown))
    ok(LC.AdminTool(staff, nil, "chapter", "wave") == false and not LC.ChapterReversed(), "the staff's lines are a superadmin's")
    staff.superadmin = true
    ok(LC.AdminTool(staff, nil, "chapter", "lock") == true and C.S.lock == true, "staff lock it")
    C.S.cooldown = 0
    ok(select(2, LC.ChapterLaunch(lt)) == "locked", "locked: the launch does not start it")
    _setcvar("lc_chapter", 0)
    ok(LC.AdminTool(staff, nil, "chapter", "wave") == true and LC.ChapterReversed() and began == 2, "staff launch the wave whatever the setting, the cooldown or the lock")
    unit.alive, ota.alive = true, true
    C.S.elapsed = 5 * 60
    unit:SetPos(N0) ota:SetPos(N0 + Vector(60, 0, 0))
    _run(3)
    ok(C.retake == nil, "locked: the Nexus held does not flip it either")
    ok(LC.AdminTool(staff, nil, "chapter", "retake") == true and not LC.ChapterReversed() and ended == 2, "staff give the city back to the Combine")
    ok(LC.AdminTool(staff, nil, "chapter", "retake") == false, "(once)")
    LC.ChapterReload()
    ok(C.S.state == "normal" and C.S.lock == true and C.S.cooldown > 0, "the lock and the cooldown are kept over a restart too")
    ok(LC.AdminTool(staff, nil, "chapter", "lock") == true and C.S.lock == false, "and unlock it")
    ok(LC.ChapterStatus().line ~= nil, "(the testing tools say how it stands)")

    -- everything as it was
    hook.Remove("LivingCityChapterBegan", "ChapterTests") hook.Remove("LivingCityChapterEnded", "ChapterTests")
    LC.Notice, LC.RebelWave = noticeWas, waveWas
    _setcvar("lc_chapter", tonumber(cvWas[1])) _setcvar("lc_chapter_hold_minutes", tonumber(cvWas[2])) _setcvar("lc_chapter_cooldown_minutes", tonumber(cvWas[3]))
    _setcvar("lc_ledger", tonumber(cvWas[4]))
    C.S, C.retake, C.pendingAt, C.pendingBy, C.maskOff = sWas, nil, nil, nil, {}
    _files[FILE] = fileWas
    LC.ChapterApply()
    led.combine, led.authority, led.resistance = ledWas.combine, ledWas.authority, ledWas.resistance
    led.districts, led.crackdown, led.liberated = ledWas.districts, ledWas.crackdown, ledWas.liberated
    while #led.news > ledWas.news do table.remove(led.news) end
    LC.SetDoorTag(door, nil)
    LC.RemovePoint(desk) LC.RemovePoint(rsp) LC.RemovePoint(holdout) LC.RemoveZone(nexus)
    for _, e in ipairs({ door, plain, bank, field, turret, monitor, relay, rebel, citizen }) do if IsValid(e) then e:Remove() end end
    for _, p in ipairs({ unit, ota, her, lt, private, cit, staff }) do p:Remove() end
    for p, was in pairs(aliveWas) do if IsValid(p) and was and not p:Alive() then p.alive = true end end
    if eventWas and not LC.Event then LC.StartEvent(eventWas) end
    LC.RefreshPower()
end
Nov25_ChapterTests()

----------------------------------------------------------------------
section("Stop")
LC.Stop(admin)
_run(1)
ok(table.Count(LC.NPCs) == 0, "stopping removes every NPC")
ok(#_errors == 0, "no errors logged during the whole run", _errors[1])

return results.pass, results.fail, table.concat(results.lines, "\n")
